\subsection{Order-Preserving Property}
Our first theoretical result establishes that the system preserves opinion ordering throughout its evolution:
\begin{thm}(Order-Preserving Property) \label{thm:Order-Preserving Property}
For the system described by (\ref{model:HKfrac}), the opinion dynamics preserve initial ordering. Specifically, for any two agents $i, j\in \mathcal{V}$ with initial opinions satisfying $x_i(0)\leq x_j(0)$, their opinions maintain this ordering for all subsequent times:
\begin{equation}
x_i(k) \leq x_j(k), \quad  k \geq 0.
\end{equation}
\end{thm}

To establish the proof of Theorem \ref{thm:Order-Preserving Property}, the following basic lemma is needed.

\begin{lem} \cite{SU2017448}\label{lem:mean}
	Suppose $z_i, i=1,2,\ldots$ is a nonnegative nondecreasing (nonincreasing) sequence. Then for any $s \geq0$, the sequence $g_s(p)=\frac{1}{p}\sum_{i=s+1}^{s+p}z_i, p \geq 1$ is monotonically nondecreasing (nonincreasing) for $p$.
\end{lem}

\noindent\textbf{Proof of Theorem \ref{thm:Order-Preserving Property}:}
We will prove the conclusion using method of mathematical induction.

If $x_i(0)\leq x_j(0)$, by Lemma \ref{lem:mean} we have
\begin{equation}
	\begin{split}
x_{i}(1)=& \frac{\sum_{l\in \bar{I}_{i}(0)}x_{l}(0)}{|I_{i}(0)|}+\frac{1}{|I_{i}(0)|}x_{i}(0)\\
=& \frac{\sum_{l\in I_{i}(0)}x_{l}(0)}{|I_{i}(0)|}\\
\leq&  \frac{\sum_{l\in I_{j}(0)}x_{l}(0)}{|I_{j}(0)|}\\
=& \frac{\sum_{l\in \bar{I}_{j}(0)}x_{l}(0)}{|I_{j}(0)|}+\frac{1}{|I_{j}(0)|}x_{j}(0)\\
=&x_{j}(1).
\end{split}	
\end{equation}
Now suppose for $k \geq 1$, $x_i(s)\leq x_j(s)$ for all $s\leq k$. Then
\begin{equation}
	\begin{split}
&	\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|x_{i}(s)+\Big(1-\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|\Big)x_{i}(k)\leq \sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|x_{j}(s)+\Big(1-\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|\Big)x_{j}(k).\\
	\end{split}
\end{equation}
Consequently, we obtain
\begin{equation}
	\begin{split}
		x_{i}(k+1)=& \frac{\sum_{l \in \bar{I}_{i}(k)}x_{l}(k)}{|I_{i}(k)|}+\frac{1}{|I_{i}(k)|}\Big[\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|x_{i}(s)+\Big(1-\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|\Big)x_{i}(k)\Big]\\
	\leq &  \frac{\sum_{l \in \bar{I}_{j}(k)}x_{l}(k)}{|I_{j}(k)|}+\frac{1}{|I_{j}(k)|}\Big[\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|x_{j}(s)+\Big(1-\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|\Big)x_{j}(k)\Big]\\
= &x_{j}(k+1).
	\end{split}
\end{equation}
Thus the method of mathematical induction yields the conclusion.\hfill $\Box$
%By the principle of, we conclude that for all $k\in N$, the inequality $x_i(k)\leq x_j(k)$ holds.

