\subsection{Asymptotic Convergence}
The order-preserving property established in Theorem \ref{thm:Order-Preserving Property} raises fundamental questions about the long-term evolution of the memory-enhanced system (\ref{model:HKfrac}). We now present the key convergence result for these dynamics:

\begin{thm}{(Asymptotic Convergence)} \label{thm:Convergence}
For the fractional opinion dynamics governed by (\ref{model:HKfrac}), the following holds for any initial configuration $x(0) \in [0,1]^n$:
\begin{itemize}
\item Each opinion trajectory admits a well-defined limit: For every agent $i \in \mathcal{V}$, there exists $x_i^* \in [0,1]$ such that $\lim_{k \to \infty} x_i(k) = x_i^*$;
\item The limiting configuration $x^* = (x_1^*,...,x_n^*)$ constitutes an equilibrium state of the system.
\end{itemize}
\end{thm}
\begin{proof}
First we consider the maximum opinion value $x_M(k)=\max_{i\in\mathcal{V}}x_i(k)$, $k\geq 0$. By the order-preserving property revealed in Theorem \ref{thm:Order-Preserving Property}, we can denote $x_1(k)=x_M(k)$ without loss of generality.
We will show that $x_1(k) \leq x_1(0)$ for all $k>0$.

For $k=0$, the definition of $x_1(k)$ implies, for all $ i \in \mathcal{V}$ and $k>0$, $x_i(0)\leq x_1(0)$,
thus,
\begin{equation} \label{equ:xioayu1}
	\frac{\sum_{j \in I_1(0)}x_j(0)}{|I_1(0)|} \leq x_1(0).
\end{equation}
When $k=0$, we have $\displaystyle\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|=0$, so the model (\ref{model:HKfrac}) degenerates to the model (\ref{model:HKorig}) (the classical HK model), which implies
\begin{equation} \label{equ:0-1}
	x_1(1)=\frac{\sum_{j \in I_1(0)}x_j(0)}{|I_1(0)|}\leq x_1(0).
\end{equation}
For $k=1$, the definition of $x_1(k)$ and (\ref{equ:0-1}) imply
\begin{equation} \label{equ:xiaoyu2}
	\frac{\sum\limits_{j \in \bar{I}_1(1)}x_j(1)}{|I_1(1)|}\leq \frac{\sum\limits_{j \in \bar{I}_1(1)}x_1(1)}{|I_1(1)|}\leq \frac{\sum\limits_{j \in \bar{I}_1(1)}x_1(0)}{|I_1(1)|}.
\end{equation}
Since $|a_m^{(\alpha)}|<1$ for each $m\geq 0$, by (\ref{equ:0-1}) and (\ref{equ:xiaoyu2}) we have
\begin{equation*}
\begin{split}
	x_1(2)=&\frac{\sum_{j \in \bar{I}_1(1)}x_1(1)}{|I_1(1)|}+\frac{1}{|I_1(1)|}\Big[|a_2^{(\alpha)}|x_1(0)+\Big(1-|a_2^{(\alpha)}|\Big)x_1(1)\Big]\\
	\leq &\frac{\sum_{j \in \bar{I}_1(1)}x_1(0)}{|I_1(1)|}+\frac{1}{|I_1(1)|}\Big[|a_2^{(\alpha)}|x_1(0)+\Big(1-|a_2^{(\alpha)}|\Big)x_1(0)\Big]\\
	=&x_1(0).
\end{split}
\end{equation*}
Applying recursive reasoning we can show that
\begin{equation}
	x_1(k)\leq x_1(0), \quad k> 0.
\end{equation}
Next we will show that there exists a sequence $0<K_{1}<K_{2}<K_{3}< \dots$ such that
\begin{equation}\label{equa:ordermax}
 	x_1(0) \geq x_1(K_{1}) \geq x_1(K_{2}) \geq \ldots.
 \end{equation}
We first demonstrate the existence of $K_1>0$ such that
\begin{equation}\label{equ:existK1}
	x_1(k) \leq x_1(K_1), \quad k>K_1.
\end{equation}
By Proposition \ref{prop:akalphadecreas} ($\lim\limits_{k \rightarrow \infty}|a_k^{(\alpha)}|=0$), we know that given any $T>0$ and $\delta>0$, we can find $k^{(T)}>T$ (one can also observe that $k^{(T)}-T$ only depends on $\delta$) such that
\begin{equation}\label{equ:alphaleqdelta}
	|a_{k^{(T)}+1-s}^{(\alpha)}| < \frac{\delta}{T+1}, \quad \forall s \leq T.
\end{equation}
Since $0\leq x_i(k)\leq1$, we have
\begin{equation} \label{equ:wuxiangxiao}
	\sum_{s=0}^{T}|a_{k^{(T)}+1-s}^{(\alpha)}|x_{i}(s) \leq \delta.
\end{equation}
For $k>k^{(T)}$, the system (\ref{model:HKfrac}) can be rewritten as
\begin{equation}\label{equ:gaixie}
	\begin{split}
		x_{i}(k+1)= & \frac{\sum_{j \in \bar{I}_{i}(k)}x_{j}(k)}{|I_{i}(k)|}\\
&+\frac{1}{|I_{i}(k)|}\Big[\sum_{s=0}^T|a_{k+1-s}^{(\alpha)}|x_{i}(s)+\sum_{s=T+1}^{k-1}|a_{k+1-s}^{(\alpha)}|x_{i}(s)+\Big(1-\sum_{s=0}^{k-1}|a_{k+1-s}^{(\alpha)}|\Big)x_{i}(k)\Big].
\end{split}
\end{equation}
Denote $t_M:=\{T+1\leq k\leq k^{(T)}|x_1(k)\geq x_1(l), T+1\leq l\leq k^{(T)}\}$, $t_m:=\{T+1\leq k\leq k^{(T)}|x_1(k)\leq x_1(l), T+1\leq l\leq k^{(T)}\}$. Given $T>0$, if for any $\delta>0$, the above selected $x_1(t_M)-x_1(t_m)<\frac{1}{|a_{k^{(T)}-T}^{(\alpha)}|} \delta$, we know
\begin{equation}\label{equ:x1MmkT}
  x_1(t_M)=x_1(t_m)=x_1(k),\quad T+1\leq k\leq k^{(T)}.
\end{equation}
If (\ref{equ:x1MmkT}) holds for all $T>0$, (\ref{equ:existK1}) and also (\ref{equa:ordermax}) hold. Otherwise, there exists $T>0$ and  $\delta>0$ such that
\begin{equation}\label{equ:x1Mmgeq}
  x_1(t_M)-x_1(t_m)> \frac{1}{|a_{k^{(T)}-T}^{(\alpha)}|} \delta.
\end{equation}
Since $\{|a_m^{(\alpha)}|, m\geq 0\}$ is decreasing by Proposition \ref{prop:akalphadecreas},
\begin{equation}\label{equ:alphaleq1}
 \frac{|a_{k^{(T)}+s-t_m}^{(\alpha)}|}{|a_{k^{(T)}-T}^{(\alpha)}|}\geq 1, \quad s\geq 1.
\end{equation}
Let $\bar{a}_M=1-\sum_{s=0}^{M-1}|a_{M+1-s}^{(\alpha)}|$, by (\ref{equ:sumalphaleq1}), (\ref{equ:wuxiangxiao}) and (\ref{equ:gaixie}),
\begin{equation} \label{equ:zhuyao0}
	\begin{split}
x_1(k^{(T)}+1)=&\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)})}x_j(k^{(T)})}{|I_1(k^{(T)})|}+\frac{1}{|I_1(k^{(T)})|}\Big[\sum_{s=0}^T|a_{k^{(T)}+1-s}^{(\alpha)}| x_1(s)\\
&+\sum_{s=T+1}^{k^{(T)}-1}|a_{k^{(T)}+1-s}^{(\alpha)}|x_1(s)+\Big(1-\sum_{s=0}^{k^{(T)}-1}|a_{k^{(T)}+1-s}^{(\alpha)}|\Big)x_1(k^{(T)})\Big]\\
\leq &\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)})}x_j(k^{(T)})}{|I_1(k^{(T)})|}+\frac{1}{|I_1(k^{(T)})|}\Big(\delta+\sum_{s=T+1}^{k^{(T)}-1}|a_{k^{(T)}+1-s}^{(\alpha)}|x_1(s)+\bar{a}_{k^{(T)}}x_1(k^{(T)})\Big).
\end{split}
\end{equation}
Further by (\ref{equ:x1Mmgeq}) and (\ref{equ:alphaleq1}), we obtain
\begin{equation} \label{equ:zhuyao}
\begin{split}
x_1(k^{(T)}+1)<&\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)})}x_1(k^{(T)})}{|I_1(k^{(T)})|}+\frac{1}{|I_1(k^{(T)})|}\Big(\delta-\frac{|a_{k^{(T)}+1-t_m}^{(\alpha)}|}{|a_{k^{(T)}-T}^{(\alpha)}|}\delta\\
&+\sum_{s=T+1}^{k^{(T)}-1}|a_{k^{(T)}+1-s}^{(\alpha)}|x_1(t_M)+\bar{a}_{k^{(T)}}x_1(t_M)\Big)\\
< &\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)})}x_1(t_M)}{|I_1(k^{(T)})|}+\frac{1}{|I_1(k^{(T)})|}x_1(t_M)\\
=&x_1(t_M).
\end{split}	
\end{equation}
By (\ref{equ:alphaleq1}) and (\ref{equ:zhuyao}),
\begin{equation}\label{equ:zhuyao21}
	\begin{split}
		x_1(k^{(T)}+2)=&\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)}+1)}x_j(k^{(T)}+1)}{|I_1(k^{(T)}+1)|}+\frac{1}{|I_1(k^{(T)}+1)|}\Big[\sum_{s=0}^T|a_{k^{(T)}+2-s}^{(\alpha)}|x_1(s)+\sum_{s=T+1}^{k^{(T)}}|a_{k^{(T)}+2-s}^{(\alpha)}|x_1(s)\\
&+\Big(1-\sum_{s=0}^{k^{(T)}}|a_{k^{(T)}+2-s}^{(\alpha)}|\Big)x_1(k^{(T)}+1)\Big]\\
< &\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)}+1)}x_1(t_M)}{|I_1(k^{(T)}+1)|}+\frac{1}{|I_1(k^{(T)}+1)|}\Big(\delta+\sum_{s=T+1}^{k^{(T)}}|a_{k^{(T)}+2-s}^{(\alpha)}|x_1(s)+\bar{a}_{k^{(T)}+1}x_1(k^{(T)}+1)\Big).
\end{split}
\end{equation}
By (\ref{equ:x1Mmgeq}), (\ref{equ:alphaleq1}) and (\ref{equ:zhuyao21}),
\begin{equation}\label{equ:zhuyao2}
	\begin{split}
		x_1(k^{(T)}+2)<&\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)}+1)}x_1(t_M)}{|I_1(k^{(T)}+1)|}+\frac{1}{|I_1(k^{(T)}+1)|}\Big(\delta-\frac{|a_{k^{(T)}+2-t_m}^{(\alpha)}|}{|a_{k^{(T)}-T}^{(\alpha)}|}\delta\\
&+\sum_{s=T+1}^{k^{(T)}}|a_{k^{(T)}+2-s}^{(\alpha)}|x_1(t_M)+\bar{a}_{k^{(T)}+1}x_1(t_M)\Big)\\
< &\frac{\sum\limits_{j \in \bar{I}_1(k^{(T)}+1)}x_1(t_M)}{|I_1(k^{(T)}+1)|}+\frac{1}{|I_1(k^{(T)}+1)|}x_1(t_M)\\
=&x_1(t_M).
\end{split}	
\end{equation}
Applying recursive method we obtain
\begin{equation*}
  x_1(t_M)\geq x_1(k),\quad k\geq t_M.
\end{equation*}
Take $K_1=t_M$, and we know that (\ref{equ:existK1}) holds. Repeating the above procedure by considering the case $T>K_1$, we can prove that there exists $K_2>K_1$ that
\begin{equation*}
  x_1(k)\leq x_1(K_2)\leq x_1(K_1),\quad k\geq K_2.
\end{equation*}
Iterating this argument, we show that there exists a sequence $K_{1}<K_{2}<K_{3}< \dots$ such that
\begin{equation}\label{equ:Ksleq}
  x_1(k)\leq x_1(K_l), \quad k\geq K_l,\quad l=1,2,\dots
\end{equation}
and
\begin{equation*}
 	x_1(0) \geq x_1(K_{1}) \geq x_1(K_{2}) \geq \dots.
 \end{equation*}
The sequence $\{x_1(K_l), l=1,2,\dots\}$ is monotonically decreasing and bounded below, so there exists $x_1^*\in [0,1]$ such that
 \begin{equation}\label{equ:limitx1}
   \lim_{l\to \infty}x_1(K_l)=x_1^*.
 \end{equation}
This also implies
\begin{equation}\label{equ:limitx1k}
  \lim\limits_{k \rightarrow \infty}x_1(k)=\lim\limits_{l \rightarrow \infty}x_1(K_l)=x_1^*.
\end{equation}
If not, we have $\varliminf \limits_{k \rightarrow \infty}x_1(k)< \lim \limits_{l \rightarrow \infty}x_{M}(K_l)=x_1^*$.
% \begin{equation}\label{equ:inflimitleq}
% \end{equation}
Hence there exists $\rho>0$ such that for any $t>0$ there exists $k_t^\rho>t$ such that
\begin{equation}\label{equ:x1ktrho}
  x_1(k_t^\rho)<x_1^*-\rho.
\end{equation}
Meanwhile, by (\ref{equ:Ksleq}) and (\ref{equ:limitx1}), we know for any $\epsilon>0$, there exists $T_\epsilon>0$ such that
\begin{equation}\label{equ:Kepsi}
  x_1(k)<x_1^*+\epsilon,\quad k>T_\epsilon.
\end{equation}
By Proposition \ref{prop:akalphadecreas} and (\ref{equ:alphaleqdelta}), given any $\delta>0$, $T>0$, there exists $k^{(T)}>0$ such that for $k>k^{(T)}$, (\ref{equ:alphaleqdelta}) holds and moreover, $k^{(T)}-T$ only depends on $\delta$. So we can denote $L(\delta)=k^{(T)}-T$.
Take $\delta=\frac{\alpha\rho}{2}$ in (\ref{equ:alphaleqdelta}), $\epsilon=\frac{\alpha\rho}{2L(\delta)}$ in (\ref{equ:Kepsi}), $T$ in (\ref{equ:alphaleqdelta}) is then taken to be $T_\epsilon$ in (\ref{equ:Kepsi}). Also by (\ref{equ:x1ktrho}), there exists $k_{T_\epsilon}^\rho\geq k^{(T_\epsilon)}$ such that
\begin{equation}\label{equ:x1ktepsrho}
  x_1(k_{T_\epsilon}^\rho)<x_1^*-\rho.
\end{equation}
By (\ref{equ:alphaleqdelta}), (\ref{equ:Kepsi}) and (\ref{equ:x1ktepsrho}),
\begin{equation}\label{equ:x1ktepsrhoplus1}
	\begin{split}
		x_1(k_{T_\epsilon}^\rho+1)=&\frac{\sum\limits_{j \in \bar{I}_1(k_{T_\epsilon}^\rho)}x_j(k_{T_\epsilon}^\rho)}{|I_1(k_{T_\epsilon}^\rho)|}+\frac{1}{|I_1(k_{T_\epsilon}^\rho)|}\Big(\sum_{s=0}^{T_\epsilon}|a_{k_{T_\epsilon}^\rho+1-s}^{(\alpha)}|x_1(s)\\ &+\sum_{s=T_\epsilon+1}^{k_{T_\epsilon}^\rho-1}|a_{k_{T_\epsilon}^\rho+1-s}^{(\alpha)}|x_1(s)+\bar{a}_{k_{T_\epsilon}^\rho}x_1(k_{T_\epsilon}^\rho)\Big)\\
< &\frac{\sum\limits_{j \in \bar{I}_1(k_{T_\epsilon}^\rho)}x_1(k_{T_\epsilon}^\rho)}{|I_1(k_{T_\epsilon}^\rho)|}+\frac{1}{|I_1(k_{T_\epsilon}^\rho)|}\Big(\delta+\sum_{s=T_\epsilon+1}^{k_{T_\epsilon}^\rho-1}|a_{k_{T_\epsilon}^\rho+1-s}^{(\alpha)}|(x_1^*+\epsilon)+\bar{a}_{k_{T_\epsilon}^\rho}(x_1^*-\rho)\Big)\\
\leq&(x_1^*-\rho)+\frac{1}{|I_1(k_{T_\epsilon}^\rho)|}\Big(\delta+\sum_{s=T_\epsilon+1}^{k_{T_\epsilon}^\rho-1}|a_{k_{T_\epsilon}^\rho+1-s}^{(\alpha)}|(\epsilon+\rho)\Big)\\
\leq &x_1^*-\Big(1-\sum_{s=T_\epsilon+1}^{k_{T_\epsilon}^\rho-1}|a_{k_{T_\epsilon}^\rho+1-s}^{(\alpha)}|\Big)\rho+\delta+L(\delta)\epsilon.
\end{split}		
\end{equation}
Since $1-\sum_{s=T_\epsilon+1}^{k_{T_\epsilon}^\rho-1}|a_{k_{T_\epsilon}^\rho+1-s}^{(\alpha)}|\geq \alpha$ by the comment (\ref{comment2}) behind the  system (\ref{model:HKfrac}), (\ref{equ:x1ktepsrhoplus1}) yields
\begin{equation}\label{equ:x1ktepsrhoplus12}
	\begin{split}
		x_1(k_{T_\epsilon}^\rho+1)< &x_1^*-\alpha\rho+\delta+L(\delta)\epsilon<x_1^*.
\end{split}		
\end{equation}
Following a similar argument of (\ref{equ:zhuyao2}), we can show that
\begin{equation}\label{equ:x1ktepsrhoall}
  x_1(k)<x_1^*,\quad k>k_{T_\epsilon}^\rho,
\end{equation}
which contradicts (\ref{equ:limitx1}), and hence (\ref{equ:limitx1k}) holds.

Let $\mathcal{V}_1:=\{i \in \mathcal{V}|\lim\limits_{k \rightarrow \infty}x_i(k)=x_1^*\}$. If $j \notin \mathcal{V}_1$, it is easy to show that $j$ cannot be the neighbor of agents in $\mathcal{V}_1$ (or their opinion values have to be less than $x_1^*$). Then for $\mathcal{V}/\mathcal{V}_1$, we can similarly define $x_1(k)$ and a same method leads to
\begin{equation}
	\lim\limits_{k \rightarrow \infty}x_1(k)=x^*_2.
\end{equation}
where $x^*_2\in[0,1]$ and $|x_1^*-x^*_2|>\epsilon$.

By repeating the above procedure, we can conclude that the opinion values of all individuals asymptotically converge. Clearly, $x^* = (x_1^*,...,x_n^*)$ constitutes an equilibrium state of the system.
\end{proof}

\begin{rem}
The convergence analysis becomes significantly more challenging in the fractional-order case compared to its integer-order counterpart. Unlike classical HK dynamics where boundary opinions evolve monotonically, the memory effects in fractional-order systems destroy this crucial monotonicity property. This technical obstacle is further compounded by the inherent complexity of bounded-confidence models, where extreme nonlinear interactions already make convergence proofs notoriously difficult - even the convergence problem for integer-order heterogeneous models remains open to date. To overcome these challenges, our proof strategy involves constructing carefully designed asymptotic subsequences and developing inductive techniques to properly account for historical state dependencies while preventing potential oscillatory behaviors.
\end{rem}
The following simple example demonstrates the loss of monotonicity in boundary opinion evolution:

%\noindent\textbf{Example}
\begin{example}\label{exam:nonmono}
For the system (\ref{model:HKfrac}), given the initial opinion values $x(0)=(1.0944, 0.2772)$ and the neighbor radius $\epsilon=1$, we obtain the following:
\begin{gather*}
	x(1)=(0.6823, 0.6834)\\
	x(2)=(0.7079, 0.6591)\\
	x(3)=(0.6941, 0.6735)\\
	x(4)=(0.6938, 0.6766)\\
	x(5)=(0.6858, 0.6788)\\
	x(6)=(0.6869, 0.6791).
\end{gather*}
\end{example}
Compared to the classical HK model where maximum opinion values evolve in a monotonically non-increasing manner, we can see the model (\ref{model:HKfrac}) in Example \ref{exam:nonmono} exhibits non-monotonic fluctuations with occasional upward perturbations. This phenomena can also be observed in Figures \ref{fig:basicevolu}-\ref{fig:consensus}. This more realistically captures phenomena such as opinion rebounds due to memory effect, local reinforcement effects, and cognitive updates--reflecting the inherent nonlinearity of real-world opinion dynamics.

\subsection{Consensus Criterion}
In opinion dynamics research, the mathematical characterization of consensus conditions remains a fundamental theoretical problem. Based on Theorem \ref{thm:Convergence}, we establish the following consensus theorem:
%\begin{defn}
%The system (\ref{model:HKfrac}) is said to achieve consensus if
%$$\lim_{k \rightarrow \infty}d(k)=0,$$ for given initial condition $x(0)=(x_{1}(0), x_{2}(0), \ldots, x_{n}(0))$.
%\end{defn}
\begin{thm} \label{thm:consensus}
Let $x_M(k)=\max_{i\in\mathcal{V}}x_i(k)$, $x_m(k)=\min_{i\in\mathcal{V}}x_i(k)$ and $d(k)=x_M(k)-x_m(k)$ for $k\geq 0$. Given $\epsilon\in(0,1]$, suppose the initial opinion value satisfies $d(0) \leq \epsilon$. Then the system (\ref{model:HKfrac}) asymptotically achieves consensus, i.e.,
	\begin{equation*}
		\lim_{k \rightarrow \infty}d(k)=0.
	\end{equation*}
\end{thm}
\begin{rem}
This theorem demonstrates that the system (\ref{model:HKfrac}) asymptotically reaches consensus under initially fully connected conditions. This conclusion verifies that the fractional-order dynamical model proposed in this work preserves the fundamental properties of classical consensus theory, while providing a theoretical foundation for subsequent studies on consensus conditions under more situations.
\end{rem}
To establish Theorem \ref{thm:consensus}, we first prove that if all individuals are initially mutual neighbors, this connectivity persists indefinitely.
\begin{lem}\label{lem:neigh}
Given $\epsilon\in(0,1]$, suppose the initial opinion value satisfies $|x_M(0)-x_m(0)| \leq \epsilon$, then $|x_M(k)-x_m(k)|\leq \epsilon$ for all $k\geq 0$.
\end{lem}
\begin{proof}
By (\ref{equa:ordermax}), we establish that for all discrete time instances $k \geq 0$, the opinion spectrum of the dynamical system (\ref{model:HKfrac}) obeys the inequality:
	\begin{equation*}
		|x_M(k)-x_m(k)| \leq |x_M(0)-x_m(0)| \leq \epsilon.
	\end{equation*}
\end{proof}

\noindent\textbf{Proof of Theorem \ref{thm:consensus}:}
The complete connectivity case represents a special instance of Theorem \ref{thm:Convergence}. When all individuals mutually interact, Lemma \ref{lem:neigh} guarantees maintained connectivity, and Theorem \ref{thm:Convergence} ensures convergence to a shared limit value, resulting in consensus.\hfill $\Box$
%\end{proof}

\section{Simulation}

In this section, we present simulation results that validate the theoretical analysis of the fractional-order opinion dynamics model.

The previous Figure \ref{fig:basicevolu} presents the opinion dynamics of a $5$-agent system with interaction radius $\epsilon=0.2$ and fractional order $\alpha=0.5$.
The simulation results confirm the order-preserving property of the system: for all time steps $k \geq 0$, the inequality $x_i(k) \geq x_j(k)$ holds whenever $x_i(0) \geq x_j(0) $.

Figure \ref{fig:convergence} displays the fragmentation pattern of a similar $5$-agent system ($\epsilon=0.2, \alpha=0.5$). The simulation shows that the system exhibits a fragmented convergence pattern, where distinct clusters emerge with intra-cluster consensus. Notably, each individual's opinion value asymptotically converges to a stable equilibrium point, demonstrating that while global consensus is not achieved, local convergence behavior is clearly observable within subsystem clusters.

