\begin{eqnarray} \label{eq_psiev_def}
\partial_t \psi &=& \{ \psi, \phi \} - \frac{\Omega_i \tau_A \rho^2_*}{n} \{ \psi, p_e \} + \frac{\eta}{n} \tilde{J_{\|}}
\end{eqnarray}
\begin{eqnarray} \label{eq_omegaev_def}
 \partial_t \mathcal{W} &=& - \{ \phi, \mathcal{W} \} - \tau_i \Omega_i \tau_A \rho^2_* \{ \nabla_{\alpha} \phi , \nabla_{\alpha} p_i \} - u_{\parallel \, i} \{ \psi , \mathcal{W} \} + \{ \psi , J_{\parallel} \} \\ \nonumber
&& + \rho^2_* (\Omega_i \tau_A)^2 \bm{\mathcal{K}_1} \! \cdot \! \nabla(\tau_i p_i + p_e) + \mu \Delta_{\perp} \tilde{\mathcal{W}}
