&& - \frac{5}{3} \Omega_i \tau_A \rho^2_* \Big( \tau_i p_i \bm{\mathcal{K}_2} \! \cdot \! \nabla T_i  - T_i\bm{\mathcal{K}_2} \! \cdot \! \nabla p_e \Big) + \chi_{\perp \, i} \Delta_{\perp} \tilde{T}_i + \chi_{\parallel \, i} \{ \psi , \{ \psi , \tilde{T}_i \} \}
\end{eqnarray}
\begin{eqnarray} \label{eq_peev_def}
\partial_t p_e &=& - \frac{5}{3} p_e \{ \psi, u_{\parallel \, e} \} - \{ \phi, p_e \} - u_{\parallel \, e} \{ \psi, p_e \} - \frac{5}{3} p_e \bm{\mathcal{K}_2} \! \cdot \! \nabla \phi \\ \nonumber
&& + \frac{5}{3} \Omega_i \tau_A \rho^2_* \bm{\mathcal{K}_2} \! \cdot \! \nabla(T_e p_e) + \chi_{\perp \, e} \Delta_{\perp} \tilde{T}_e + \chi_{\parallel \, e} \{ \psi , \{ \psi , \tilde{T}_e \} \}
\end{eqnarray}
\begin{eqnarray} \label{eq_nev_def}
\partial_t n &=& - \{ \phi, n \} - n \{ \psi, u_{\parallel \, e} \} - u_{\parallel \, e} \{ \psi, n \} -  n \bm{\mathcal{K}_3} \! \cdot \! \nabla \phi + \Omega_i \tau_A \rho^2_* \: \bm{\mathcal{K}_3} \! \cdot \! \nabla p_e + D \Delta_{\perp} \tilde{n}
\end{eqnarray}
\begin{eqnarray} \label{eq_upar_def}
\partial_t u_{\parallel \, i} &=& - \{ \phi , u_{\parallel \, i} \} - \left\{ \psi, \frac{u_{\parallel \, i}^2}{2} \right\} - \frac{(\Omega_i \tau_A)^2 \rho^2_*}{n}  \{ \psi, \tau_i p_i + p_e \} + U_d \Delta_{\perp} \tilde{u}_{\parallel \, i}
\end{eqnarray}
\end{widetext}

where $\psi$ is the poloidal magnetic flux, $\phi$ the electrostatic potential, $p_e$ and $T_e$ the electron pressure and temperature, $p_i$ and $T_i$ the ion pressure and temperature, $n$ the electron density (quasi-neutrality is assumed) and $u_{\parallel \, i/e}$ the ion and electron parallel fluid velocities, with 
\begin{equation} \label{eq_ue}
u_{\parallel \, e} = u_{\parallel \, i} - \frac{J_{\parallel}}{n \, \Omega_i \tau_A}
\end{equation}
The definition of the generalized vorticity is $\mathcal{W} = \Delta_{\perp} (\phi + \tau_i \Omega_i \tau_A \rho^2_* p_i)$, meaning that here the Boussinesq approximation is applied, and the parallel current density is $J_{\parallel} = \Delta_{\perp} \psi$. A ``$\sim$'' above the symbol of the field indicates its fluctuating component, e.g. $\tilde{\psi} = \psi - \psi_{eq}$. $\alpha$ in Eq. \ref{eq_omegaev_def} is an index for the sum over the perpendicular geometrical coordinates, since the explicit expression of  the second term on the RHS is (in slab geometry):
\begin{equation}
\{ \nabla_\alpha \phi , \nabla_\alpha p_i \} = \{ \partial_x \phi , \partial_x p_i \} + \{ \partial_y \phi , \partial_y p_i \}
\end{equation}
Using the definition of the generalized vorticity a condition can be imposed to have zero-vorticity equilibrium profiles, which is always satisfied in simulations unless clearly stated:
\begin{equation} \label{eq_vorticity_eq}
\partial_x \phi_{eq} = - \Omega_i \tau_A \rho^2_* \frac{\partial_x p_{i \, eq}}{n_{eq}}
\end{equation}
The curvature is defined as:
\begin{equation}
\bm{\mathcal{K}} = \left( \frac{1}{B} \nabla \times \bm{b} + \nabla \left( \frac{1}{B} \right) \times \bm{b} \right) \approx -\frac{\partial_x B_{y}}{B^2_{eq}} \bm{y}
\end{equation}
{where $B_{eq} = B_{z \, eq} + B_{y \, eq} (x)$ is the profile of the equilibrium magnetic field.}\\
The distinction of the parameters $\bm{\mathcal{K}_1}$, $\bm{\mathcal{K}_2}$ and $\bm{\mathcal{K}_3}$ is done to have more freedom in manipulating the linear spectrum, but this is irrelevant for the simulations in this work, as they are kept to their consistent values (see Tab. \ref{table_normalization}).\\
This model is implemented in the fluid code AMON \citep{poye2012dynamique}.\\
Note that keeping the cubic terms leads to the presence of additional terms, both quadratic and cubic, with respect to other models. These are the last two ``\textit{Non-Linear}'' rows in Eq. \ref{eq_terms_breakdown} (the subscript ``$eq$'' indicates its equilibrium part) and their effect on the dynamics will be partially the subject of this paper.
