\title{Generalized Petermann factor of non-Hermitian systems at exceptional points}
\author{Julius Kullig}
\author{Jan Wiersig}
\affiliation{Institut f{\"u}r Physik, Otto-von-Guericke-Universit{\"a}t Magdeburg, Postfach 4120, D-39016 Magdeburg, Germany}
\email{jan.wiersig@ovgu.de}
