\end{figure}

We use $(\mu_{k,j})_{(k,j) \in \mathcal{I}}$ to denote the vector in $\R^{|\mathcal{I}|}$ formed by stacking the columns of the table in \cref{fig:ind steps}. For $(k,j) \in \mathcal{I}$, let $\mathcal{U}_{k,j}$ denote the open and dense subset of $\fun$ consisting of frames $F$ such that $\mu_{k,j}(F)$ is an isolated eigenvalue of $S_k(F)$. Then $q(\mathcal{U}_{k,j})$---where $q : \fun \to \fun/(U(d) \times G)$ is the quotient map---is an open and dense subset of $\fun/(U(d)\times G)$. Finally, let 
\begin{linenomath*}
    \begin{align*}
        \mathcal{U}_\mathcal{I} := \bigcap_{(k,j) \in \mathcal{I}} \mathcal{U}_{k,j}
    \end{align*}
\end{linenomath*}
which is open and dense in $\fun$, making $q(\mathcal{U}_\mathcal{I})$ open and dense in $\fun/(U(d)\times G)$ as well, so it has full measure with respect to the Riemannian quotient measure. 

It was shown in \cite{shonk} that the circle actions $\phi_{k,j}$ preserve both the frame vector norms and the frame operator, so that $\phi_{k,j}$ restricts to a $U(1)$-action on $\mathcal{U}_{k,j} \subset \fun$. Moreover, it was shown that $\phi_{k,j}$ commutes with the left $U(d)$-action and the right $G$-action i.e., $A\phi_{k,j}(t,F)D = \phi_{k,j}(t,AFD)$ for each $A \in U(d)$ and $D \in G$. Consequently, $\phi_{k,j}$ descends to a well-defined action $\Tilde{\phi}_{k,j}$ on the open, dense, full measure subset $q(\mathcal{U}_{k,j}) \subset \fun/(U(d) \times G)$ given by $\Tilde{\phi}_{k,j}(t,[F]) = [\phi_{k,j}(t,F)]$.

When $(k,j) \in \mathcal{I}$, the momentum map $\Phi_{k,j}$ descends to a well-defined map on $q(\mathcal{U}_{k,j}) \subset \fun/(U(d) \times G)$. To see this, take an $F \in \mathcal{U}_{k,j}$ and let $AFD$ be an element in the $U(d) \times G$ orbit of $F$, where $A \in U(d)$ and $D \in G$. The $k^{th}$ partial frame operators of $F$ and $AFD$ are given by 
\begin{linenomath*}
    \begin{align*}
        S_k(F) = f_1f_1^* + \cdots + f_kf_k^*
    \end{align*}
\end{linenomath*}
and 
\begin{linenomath*}
    \begin{align*}
        S_k(AFD)  =  Af_1D(Af_1D)^* + \cdots + Af_kD(Af_kD)^* = Af_1f_1^*A^* + \cdots + Af_kf_k^*A^*.
    \end{align*}
\end{linenomath*}
Notice that $S_k(AFD)$ is simply $S_k(F)$ conjugated by the unitary matrix $A$, so $S_k(F)$ and $S_k(AFD)$ have identical spectra. This implies that $\Phi_{k,j}$ is $(U(d) \times G)$-invariant, so the map 
\begin{linenomath*}
    \begin{align*}
        \Tilde{\Phi}_{k,j} : q(\mathcal{U}_{k,j}) \to  \R \approx \u(1)^*, \hspace{15pt}
        [F] \mapsto \Phi_{k,j}(F)
    \end{align*}
\end{linenomath*}
is well-defined. Furthermore, $\Tilde{\Phi}_{k,j}$ serves as momentum map for the descended action, making $\Tilde{\phi}_{k,j}$ a Hamiltonian action.
\begin{theorem}
    For each $(k,j) \in \mathcal{I}$, the $U(1)$-action $\phi_{k,j}$ descends to a well defined circle action $\Tilde{\phi}_{k,j}$ on the open and dense full measure submanifold $q(\mathcal{U}_{k,j})$ of $\fun/(U(d) \times G)$. Moreover, the action is Hamiltonian and $\Tilde{\Phi}_{k,j}$ is the momentum map.
    \label{circleacts}
\end{theorem}
\begin{proof}
This follows from a more general fact about Hamiltonian actions. If the product Lie group $H_1 \times H_2$ acts on a symplectic manifold $(M,\omega)$ in a Hamiltonian way with momentum map $(\mu_1, \mu_2): M \to \mathfrak{h}_1^* \times \mathfrak{h}_2^*$, then $H_1$ and $H_2$ individually act on $M$ and the two actions commute. Moreover, for any coadjoint orbit $\mathcal{O} \subset \mathfrak{h}_1^*$, the $H_2$ action is $H_1$-invariant on $M\sslash_\mathcal{O} H_1$ so the $H_2$-action descends to a well defined action on the quotient $M\sslash_{\mathcal{O}} H_1$. The descended action is Hamiltonian with momentum map $\Tilde{\mu}_2$ characterized by $q^* \Tilde{\mu}_2 = \iota^* \mu_2$ where $q: \mu_1^{-1}(\mathcal{O}) \to M\sslash_\mathcal{O} H_1$ is the quotient map and $\iota: \mu_1^{-1}(\mathcal{O}) \to M$ is the inclusion map. Then setting $M = \framespace$, $H_1 = U(d)\times G$, and $H_2 = U(1)$ gives the desired result. 
\end{proof}
\begin{theorem}
 The torus $U(1)^{d_T}$ of dimension $d_T := (d-1)(N-d-1)$ acts on the open, dense, and full measure submanifold $q(\mathcal{U}_{\mathcal{I}}) \subset \fun/(U(d) \times G)$ as the product of the circle actions $\phi = \bigtimes_{(k,j) \in \mathcal{I}}{\Tilde{\phi}_{k,j}}$. The action is Hamiltonian and $\Phi: \mathcal{U}_\mathcal{I} \to \R^{d_T} \approx (\u(1)^{d_T})^*$ given by $[F] \mapsto (\mu_{k,j}(F))_{(k,j)\in \mathcal{I}}$ is the momentum map. Since
 \begin{linenomath*}
     \begin{align*}
         d_T = \frac{1}{2} \text{ dim } \fun / (U(d) \times G) = \frac{1}{2} \text{ dim } \mathcal{U}_\mathcal{I}, 
     \end{align*}
 \end{linenomath*} 
$\mathcal{U}_{\mathcal{I}}$ is a toric symplectic manifold.
\end{theorem}
\begin{proof}
    As shown in \cite{shonk}, for each $(k,j), (l,m) \in \mathcal{I}$ the circle actions $\Tilde{\phi}_{kj}$ and $\Tilde{\phi}_{kj}$ commute; i.e., 
    \begin{linenomath*}
    \begin{align*}
        \Tilde{\phi}_{kj}(t, \Tilde{\phi}_{lm}(s,[F])) = \Tilde{\phi}_{lm}(s, \Tilde{\phi}_{kj}(t,[F])).
    \end{align*}
    \end{linenomath*}
    Additionally, it is easy to see that the cardinality of $\mathcal{I}$ is $d_T$. 
\end{proof}
Let $\mathcal{P}_{d,N} := \Phi(\mathcal{U}_\mathcal{I})$ be the moment polytope of the Hamiltonian toric action on $\mathcal{U}_\mathcal{I}$. Then $\overline{\mathcal{P}}_{d,N} := \text{cl }\mathcal{P}_{d,N}$ is the convex polytope in $\R^{d_T}$ consisting of all vectors of independent eigensteps of FUNTFs; i.e., 
\begin{linenomath*}
    \begin{align*}
        \overline{\mathcal{P}}_{d,N} = \{ (\mu_{k,j}(F))_{(k,j) \in \mathcal{I}} : F \in \fun \}.
    \end{align*}
\end{linenomath*}
This polytope is defined by Weyl's inequalities and the row sum constraints, as discussed in \cref{fig:eigensteps,fig:ind steps}. For general $d$ and $N$, there is no straightforward way to explicitly list all the defining inequalities for $\overline{\mathcal{P}}_{d,N}$; however, they can be generated algorithmically with relative ease. Our proof-of-concept implementation, available on GitHub~\cite{sampler}, demonstrates this process. The defining inequalities of $\mathcal{P}_{3,5}$ were explicitly worked out in \cref{35example}.

Notice, given an $[F] \in \mathcal{U}_\mathcal{I}$ we can reconstruct the complete eigenstep table of $F$ from $\Phi([F])$ using the fact that $\sum_{j = 1}^{\text{min}\{k,d\}} \mu_{k,j}(F) = k$ and  $\mu_{k,j}(F) = N/d$ whenever $k = N-d + 1, \dots, N$ and $j = 1, \dots, k-(N -d)$. For example, if $F \in \mathcal{F}^{3,5}_{5/3}(1)$ and $\Phi([F]) = (x_1,x_2) \in \overline{\mathcal{P}}_{3,5}$ then the complete eigenstep table of $F$ can be constructed by plugging $x_1$ and $x_2$ into the table of Example $\ref{35example}$. 

We have established that \( \fun/(U(d) \times G) \) is a toric Kähler manifold that admits the Hamiltonian action \( \phi \) with moment map \( \Phi \) and moment polytope \( \mathcal{P}_{d,N} \). Furthermore, following the procedure described in Cahill et al.~\cite[Theorem~7]{fickus}—choosing the identity matrix whenever a choice arises in their algorithm—we define the function \verb|lift_to_fiber|. This function maps a point \( \mu \in \mathcal{P}_{d,N} \) to a representative \( F \) of the unitary equivalence class \( [F] \in \fun/(U(d) \times G) \) such that \( \Tilde{\Phi}([F]) = \mu \). In other words, \verb|lift_to_fiber| serves as a rough section of the \( U(1)^n \) bundle \( \fun/(U(d) \times G) \). Using these components in \cref{alg:samp} yields our \eigenlift algorithm, stated below as \cref{alg:sampling FUNTF}. 

    \begin{algorithm}
        \caption{Eigenlift}\label{alg:sampling FUNTF}
    \begin{algorithmic}[1]
        \Require $d + 1 < N$
        \State $ \mu \sim \text{Uniform}(\overline{\mathcal{P}}_{d,N}, \lambda)$
        \State $F \gets \verb|lift_to_fiber|(\mu)$ defined using Theorem 7 in \cite{fickus}
        \State $\theta \sim \text{Uniform}(U(1)^n, \nu)$
        \State $F_{new} \gets \phi(\theta,F)$
        \State \Return $[F_{new}]$
    \end{algorithmic}
    \end{algorithm}


\begin{corollary}
    For any $d, N \in \N$ with $d + 1  < N$, \cref{alg:sampling FUNTF} produces a uniformly random $[F] \in \fun/(U(d) \times G)$ with respect to the Riemannian quotient volume measure. Moreover, the representative $F$ is full-spark with probability 1. 
\end{corollary}

\begin{proof}
    The first sentence follows from applying \cref{sampling uniform}, and the second sentence is a consequence of \cref{full-spark}. 
\end{proof}

\section{Implementation}\label{sec:implementation}
As a proof of concept, we implemented this algorithm in Python. The implementation supports any values of $d$ and $N$, provided that $N > d + 1$. However, for large $d$ and $N$, our simple implementation becomes intractable due to computational complexity. It is well known in the literature that uniformly sampling a convex polytope is a challenging problem, and our implementation reflects this difficulty.  

The computational complexity of \cref{alg:sampling FUNTF} is primarily dictated by the first step: sampling $\mu$ from $\overline{\mathcal{P}}_{d,N}$. We attempted to use the standard hit-and-run algorithm~\cite{hnr,bonehConstraintsRedundancyFeasible1979,andersenHitRunUnifying2007,smithEfficientMonteCarlo1984}, which is a Markov chain that converges to Lebesgue measure on any convex polytope. However, it performed poorly, exhibiting extremely slow convergence on our polytope $\overline{\mathcal{P}}_{d,N}$. % This difficulty arises because $\overline{\mathcal{P}}_{d,N}$ is defined by $\mathcal{O}(d^2N^2)$ inequalities, making its structure highly complex.

For the purpose of this paper, our goal is to demonstrate a proof of concept in low dimensions. Given this, a reasonable approach is to use rejection sampling within the bounding box of $\overline{\mathcal{P}}_{d,N}$. However, for the algorithm to be practical with larger values of $d$ and $N$, a new sampling paradigm must be developed for generating random independent eigensteps. Note that the Top Kill algorithm~\cite{fickusConstructingAllSelfadjoint2013} samples eigensteps from a measure on $\overline{\mathcal{P}}_{d,N}$ which is absolutely continuous with respect to Lebesgue measure, but not from Lebesgues masure itself.


In our proof-of-concept experiment, we sampled \(10^6\) uniformly random unitary classes of FUNTFs from \(\mathcal{F}_N / (U(d) \times G)\) using Algorithm~\ref{alg:sampling FUNTF}. We then recorded the coherence, defined for a unit norm frame  $F$ as \( \text{Coh}(F) := \max_{i \neq j} |\langle f_i, f_j \rangle|\), of the representative in a histogram. The results are shown in \cref{fig:coherences}.

