%
%
%
%
%
\section{Emergence of the relativistic Lagrangian and Hamiltonian from the multiplicative formulation}\label{sec3}
In this section, we demonstrate how the relativistic Lagrangian and Hamiltonian for a free particle emerge naturally from the multiplicative formulation through an elegant integration over a parameterized family of Lagrangians\footnote{The alternative method is provided in the appendix A. However, these two approaches are equivalent.}.
%
%
%
\subsection{Lagrangian}
In this section, we shall start with the multiplicative Lagrangian for a free particle 
\begin{equation}\label{Lf}
L_\lambda(x, \dot{x}) = -m\lambda^2 \left( e^{\frac{\dot{x}^2}{2\lambda^2}} - \frac{\dot{x}}{\lambda^2} \int_0^{\dot{x}} e^{\frac{v^2}{2\lambda^2}} dv \right) \;.
\end{equation}
We note that the parameter $\lambda^2$ is replaced by $-\lambda^2$ since we need a bound energy function $H_\lambda(p, x) = m\lambda^2 e^{ \frac{H_N}{m\lambda^2}}$. Of course, this mathematical trick does not affect the EOM. Then, we rescale the parameter such that $\lambda\rightarrow \beta\lambda$. The Lagrangian \eqref{Lf} becomes
\begin{equation}\label{Lf2}
L_{\beta\lambda}(x, \dot{x}) = -m\beta^2\lambda^2 \left( e^{\frac{\dot{x}^2}{2\beta^2\lambda^2}} - \frac{\dot{x}}{\beta^2\lambda^2} \int_0^{\dot{x}} e^{\frac{v^2}{2\beta^2\lambda^2}} dv \right) \;.
\end{equation}
Next, we introduce the distribution function, see figure \ref{dis},
\begin{equation}
    \rho(\beta)=\frac{2}{\sqrt{\pi}}\frac{e^{-\frac{1}{\beta^2}}}{\beta^4}=\frac{2}{\sqrt{\pi}}\left(\frac{H_\lambda(\dot x=0)}{H_{\beta\lambda}(\dot x=\lambda)}\right)^2
\end{equation}
which satisfies $\int_{-\infty}^{+\infty}d\beta \rho(\beta)=1$. 
\begin{figure}[h]
\centering
\includegraphics[width=1\linewidth]{dis}
\caption{\label{dis} The distribution function $\rho(\beta).$}
\end{figure}
We find that a statistical average of \eqref{Lf2} 
\begin{equation}
    \langle L_{\beta\lambda}\rangle_{\rho(\beta)}=\int_{-\infty}^{+\infty}d\beta \rho(\beta)L_{\beta\lambda}
\end{equation}
results
\begin{equation}
    \langle L_{\beta\lambda}\rangle_{\rho(\beta)}=-2m^2\lambda^2\sqrt{1-\frac{\dot x^2}{2\lambda^2}}\;.
\end{equation}
If we pick $\lambda^2=c^2/2$, we obtain
\begin{equation}
    L_c=\langle L_{\beta \lambda/\sqrt 2}\rangle_{\rho(\beta)}=-m^2c^2/\gamma\;,\;\; \gamma=1/\sqrt{1-\frac{\dot x^2}{c^2}}\;,
\end{equation}
which is nothing but the relativistic Lagrangian.
%
%
%%
%%
%
%
%
%
%
\subsection{Emergence of the relativistic equation of motion}
We again consider EOM with replacing $\lambda\rightarrow \beta\lambda$
\begin{equation}
e^{\dot{x}^2 / \beta^2\lambda^2} m\ddot{x} = 0\;.
\end{equation}
Then we calculate 
\begin{equation}
  \frac{1}{2}\langle e^{\dot{x}^2 / \beta^2\lambda^2} \rangle_{\rho(\beta)}m\ddot{x}= \frac{1}{2} \int_{-\infty}^{+\infty}d\beta \rho(\beta) \left(e^{\dot{x}^2 / \beta^2\lambda^2} \right)m\ddot{x}=m\ddot x{\left(1-\frac{\dot x^2}{2\lambda^2}\right)^{3/2}}=0\;.
\end{equation}
If we pick $\lambda^2=c^2/2$, we obtain the relativistic EOM: $m\ddot x\gamma^3=0$. If we introduce $d\tau=dt/\gamma$, the relativistic EOM can be compactly written as $d^2x/d\tau^2=0$. This equation means that the particle moves with constant velocity in its own proper time $\tau$, which is consistent with the fact that, in the absence of external forces, the particle moves along a geodesic in spacetime (straight-line motion).
%
%
%
%
%
%
%%
%
%
%%
%
%
%
\subsection{Hamiltonian}
We now consider the multiplicative Hamiltonian for free particle
$
    H_\lambda=m\lambda^2e^{\frac{p_N^2}{2m\lambda^2}}\;.
$
We do again replace $\lambda\rightarrow\beta\lambda$ resulting in
\begin{equation}
    H_{\beta\lambda}=m\beta^2\lambda^2e^{\frac{p_N^2}{2m\beta^2\lambda^2}}\;.
\end{equation}
If we pick $\lambda^2=c^2/2$ and consider the statistical average
\begin{equation}
    \langle H_{\beta \lambda/\sqrt 2} \rangle_{\rho(\beta)} =\int_{-\infty}^{+\infty}d\beta \rho(\beta) H_{\beta \lambda/\sqrt 2}=mc^2\gamma\;,
\end{equation}\
which is of course the relativistic Hamiltonian.
%
\subsection{Interpretation}
Recalling the relativistic Lagrangian
\begin{eqnarray}
    L_c&=&\int_{-\infty}^{+\infty}d\beta \rho(\beta)L_{\beta \lambda/\sqrt 2}=\langle L_{\beta \lambda/\sqrt 2 \rangle}\rangle_{\rho(\beta)}\nonumber\\
    &=&-mc^2/2\left[\langle \beta^2 \rangle_{\rho(\beta)}-\frac{T}{mc^2/2}\langle  1\rangle_{\rho(\beta)}-\frac{1}{2!3}\frac{T^2}{(mc^2/2)^2}\left\langle   \frac{1}{\beta^2}\right\rangle_{\rho(\beta)}+...\right]\;,
\end{eqnarray}
where $T=m\dot x^2/2$. We find that the relativistic Lagrangian is a statistical average under distribution $\rho(\beta)$ of all possible structures of the non-relativistic Lagrangian generated from the multiplicative Lagrangian.
\\
\\
Next, we consider the EOM which is
\begin{eqnarray}
    &&m\ddot x\left\langle e^{\frac{\dot x^2}{\beta^2 c^2}}\right\rangle_{\rho(\beta)}=0 \nonumber\\
    &&m\ddot x\left(\underbrace{1}_{standard \;one}+ \underbrace{\left\langle \frac{\dot x^2}{\beta^2 c^2}\right\rangle_{\rho(\beta)}+\frac{1}{2!}\left\langle \left(\frac{\dot x^2}{\beta^2 c^2}\right)^2\right\rangle_{\rho(\beta)}+...}_{non-standard\;one}\right)=0\;.
\end{eqnarray}
This equation indicates that a relativistic particle is a non-relativistic particle which explores (sum over possible) all possible relativistic fractions (weight function) $\langle (\dot x^2/\beta^2 c^2)^j\rangle_{\rho(\beta)}$, where $j=0,1,2,...$.
\\
\\
The relativistic free Hamiltonian can be expressed in terms of the $q$-deformed exponential function \cite{Tsallis2023ch3} as
\begin{equation}\label{EE1}
    H_c/mc^2 \,= e_{q}^{\frac{1}{mc^2}\frac{p_c^2}{2m}}\;,
\end{equation}
where $q=-1$. We rewrite the non-relativistic multiplicative Hamiltonian for the free particle as
\begin{equation}\label{HkA2}
    H_{\lambda}/m\lambda^2=e_q^{\frac{1}{m\lambda^2}\frac{p_N^2}{2m}}\;,
\end{equation}
where $q=+1$.  This structure was explored in \cite{krisut2024} to highlight the non-additive nature of the relativistic free Hamiltonian. However, the connection between the non-relativistic Hamiltonian $(q=+1)$ and the relativistic Hamiltonian $(q=-1)$ is not straightforward, as the procedure for upgrading the former to the latter remains nontrivial. Fortunately, through the process described in section \ref{sec2}, we gain a clear perspective on how these two Hamiltonians are interconnected from top-down and bottom-up approaches, see Figure \ref{Ham}. In other words, this work demonstrates how high-energy physics naturally emerges from low-energy physics through the proposed framework.
%
%
\begin{figure}[h]
\centering
\includegraphics[width=1\linewidth]{Ham}
\caption{\label{Ham} The interconnected diagram for Hamiltonians.}
\end{figure}
