\subsection{Multiplicative relativistic Hamiltonian}
In \cite{MultiL}, the one-parameter version of the standard relativistic Hamiltonian was established given by
\begin{equation}
    H_{c,\lambda}=-m\lambda^2e^{-\frac{\gamma c^2}{\lambda^2}}\;
\end{equation}
Then, replacing $\lambda\rightarrow \beta\lambda$, we obtain
\begin{equation}
    H_{c,\beta\lambda}=-m\beta^2\lambda^2e^{-\frac{\gamma c^2}{\beta^2\lambda^2}}\;
\end{equation}
Next, we introduce the distribution function
\begin{equation}
    \rho(\beta)=N\frac{e^{-\frac{2c^2}{\lambda^2}\left(1-\frac{1}{\beta^2\delta}\right)}}{\beta^4}\;,\;\; 1/N=\frac{1}{4}e^{-\frac{2c^2}{\lambda^2}}\sqrt{\frac{\pi}{2}}\left(-\frac{\lambda^2\delta}{c^2}\right)^{3/2}\;,\;\;\delta=\sqrt{1-\frac{\lambda^2}{c^2}}\;.
\end{equation}
Of course, it is not difficult to see that $\int_{-\infty}^{+\infty}\rho(\beta)=1$. We proceed the same mathematical steps resulting in
\begin{equation}
    H'=\left\langle H_{c,\beta\lambda} \right\rangle =\int_{-\infty}^{+\infty}d\beta \rho(\beta) H_{c,\beta\lambda} =m\left(\frac{4c^2}{\delta}\right)\sqrt{\frac{1}{1-\dot x^2/\left(\frac{4c^2}{\delta}\right)}}\;.
\end{equation}
If we replace $4c^2/\delta\rightarrow c^2$, we obtain $ H'= mc^2\gamma$, which is a relativistic Hamiltonian. This whole calculation suggests that, with the same mathematical trick, we could not go beyond the relativistic realm.
%
%%
%
\section{Including potential}\label{sec4}
In this section, the full form of the multiplicative Lagrangian \eqref{ML} will be considered. We first construct the distribution function from the Hamiltonian function as follows:
\begin{equation}
    \left(\frac{H_{c,\lambda}(\dot x=0,V)}{H_{c,\beta\lambda}(\dot x=\lambda,V=0)}\right)^2=\frac{e^{-\frac{1}{\beta^2}-\frac{2V}{m\lambda^2}}}{\beta^4}\;.
\end{equation}
After normalising, we obtain
\begin{equation}
    \rho(\beta)=\frac{2}{\sqrt \pi}\frac{e^{-\frac{1}{\beta^2}}}{\beta^4}\;,
\end{equation}
which is in the same form as the previous section. Next, we compute the statistical average 
\begin{equation}\label{LN}
    \left\langle L_{\beta\lambda}\right\rangle_{\rho(\beta)}=\frac{-2m\lambda^2\sqrt{1-\frac{\dot x^2}{2\lambda^2}-\frac{V}{m\lambda^2}}}{1-\frac{V}{m\lambda^2}}\equiv \tilde L_\lambda\;,\;\;\text{where}\;, V\neq m\lambda^2\;.
\end{equation}
Applying the Legendre transformation, we obtain
\begin{equation}\label{HN}
    \tilde H_{\lambda}=\frac{2m\lambda^2}{\sqrt{1-\frac{\dot x^2}{2\lambda^2}-\frac{V}{m\lambda^2}}}\;.
\end{equation}
Using the Euler-Lagrange equation, one obtains the EOM
\begin{equation}
    \left(\frac{-2m\lambda^2}{2m\lambda^2-2V-m\dot x^2}\right)^{3/2}\left(\frac{dV}{dx}+m\ddot x\right)=0\;.
\end{equation}
Since the first bracket is not zero, we obtain the EOM: $m\ddot x=-V'$. This means that, by employing the same mathematical trick with the full multiplicative Lagrangian, we obtain a new form of Lagrangian producing the same EOM. Therefore, there exists an alternative form of the Lagrangian apart from the multiplicative Lagrangian, see figure \ref{fig3}.
\\
\\
Let us now consider the expansion of the Lagrangian \eqref{LN} with respect to the potential $V$
\begin{eqnarray}\label{LNN}
\tilde L_{\lambda}=-2m\lambda^2\sqrt{1-\frac{\dot x^2}{2\lambda^2}}\left(1+\frac{V}{m\lambda^2}\left[1-\frac{1}{2B(\dot x)}\right]+\left(\frac{V}{m\lambda^2}\right)^2\left[1-\frac{1}{2B(\dot x)}-\frac{1}{8B^2(\dot x)}\right]+... \right)\;,
\end{eqnarray}
where $B(\dot x)=1-\dot x^2/2\lambda^2$. The structure of this particular Lagrangian is very interesting. Intriguingly, if we set $V=0$ and $\lambda^2=c^2/2$, the Lagrangian \eqref{LNN} becomes $\tilde L_{\lambda}\rightarrow L_c=-mc^2/\gamma$, which is nothing but the relativistic Lagrangian. Moreover, if we consider the limit $\lambda\rightarrow \infty$, the Lagrangian \eqref{LNN} will be the non-relativistic Lagrangian $\lim_{\lambda\rightarrow\infty}(\tilde L_\lambda+2m\lambda^2)=m\dot x^2/2-V=L_N$.
%
\begin{figure}[h]
\centering
\includegraphics[width=.8\linewidth]{fig3}
\caption{\label{fig3} The interconnected diagram for all Lagrangians.}
\end{figure}
%
\\
\\
Now, if we expand the Lagrangian with respect to $m\lambda^2$, we obtain
\begin{equation}
    \begin{aligned}\label{LH1}
\tilde{L}_\lambda+2m\lambda^2 =\   L_1 
- \frac{1}{m\lambda^2} L_2 
+ \left(\frac{1}{m\lambda^2}\right)^2 L_3 + \cdots
\end{aligned}
\end{equation}
where the first three Lagrangians in the hierarchy are given by
\begin{eqnarray}\label{lll}
    &&L_1=L_N=T-V\;,\nonumber\\
    &&L_2=\frac{1}{8} \left( T + V \right)^2 + \frac{1}{2}V \left(T + V \right) - V^2\nonumber\;,\\
    &&L_3=\frac{1}{16} \left(T + V \right)^3 + \frac{1}{8} \left( T + V \right)^2 V + \frac{1}{2} \left( T + V \right) V^2 - V^3\;.\nonumber
\end{eqnarray}
It is not difficult to see that these Lagrangians in the hierarchy \eqref{LH1} give exactly the EOM: $m\ddot x=-V'$. What we see is that this new Lagrangian \eqref{LN} gives us a way in generating a set of non-trivial Lagrangian\footnote{This new set is not the same with those obtained from the multiplicative Lagrangian \cite{MultiL}.} producing the same EOM. Therefore, this reflects again the non-uniqueness property of Lagrangian.
\\
\\
For the Hamiltonian \eqref{HN}, we find that it can be rewritten in the form
\begin{equation}
    \tilde H_\lambda=\frac{ 2m\lambda^2}{\sqrt{1-\frac{1}{m\lambda^2}(T+V)}}\;.
\end{equation}
Then, expansion with respect to $m\lambda^2$, we obtain
\begin{equation}
    \tilde H_{\lambda}+2m\lambda^2=H_1+\frac{3}{4}\frac{1}{m\lambda^2}H_2+\frac{5}{8}\left(\frac{1}{m\lambda^2}\right)^2H_3+\cdots\;,
\end{equation}
where the first three Hamiltonian in hierarchy are given by
\begin{eqnarray}
    &&H_1=T+V=H_N\;,\nonumber\\
    &&H_2= \left( T + V \right)^2=H_N^2 \nonumber\;,\\
    &&H_3= \left(T + V \right)^3=H_N^3 \;.\nonumber
\end{eqnarray}
Again, these Hamiltonians give the same EOM: $m\ddot x=-V'$. Unlike the Lagrangian structure given in \eqref{lll}, the hierarchy of the Hamiltonian $\tilde H_\lambda$ is the same as that obtained from the multiplicative Hamiltonian \cite{MultiL}, since $H_\lambda(H_N)$ and $\tilde H_\lambda(H_N)$ are functions of the standard Hamiltonian.
