  \subsection{Configurations with metrical control} \



  The following definition is strongly motivated by the pair $(B_\emptyset, \tilde \B_1)$  mentioned  in  Paragraph \ref{sec-struc-spec}. See Figure \ref{fig-standard-config} for an illustration of the definition.

\begin{defi}\label{config-standard}
Given a $[r,s]$-configuration $(I,\mathcal J)$.  Write
 $\mathscr I:=\{i\in\Z:-r\le i\le s\}$ and
$$
I:=[\eta,\xi];\ \  J_i:=[\eta_i,\xi_i],\  (i\in \mathscr I).
$$
  Given the following parameters:
\begin{equation}\label{parameter}
 \varsigma\in (0,4), \ \epsilon\in (0,\varsigma/100),\  M> C>1,\ 0<h<(1/C)\wedge(\epsilon/ M)\wedge e^{-1/C}.
\end{equation}
$(I,\mathcal J)$ is called a standard $(\varsigma,\epsilon, M, C,h)$-configuration if the following hold:

(i)   $I$ satisfies
$$[-\varsigma,\varsigma]\subset I=[\eta,\xi]\subset [-4,4].$$

(ii)  The numbers $r,s$ satisfy
 $$C^{-1}h^{-1}\le r,s\le Ch^{-1}.$$

 (iii) The ``central", the most left and the most right subintervals satisfy
$$0\in J_0,\ \  C^{-1}h\le |J_0|\le Ch;\ \ \eta_{-r}=\eta;\ \ \xi_s=\xi.$$

(iv) Write $r_1:=-\min \mathscr I_{in}, s_1=\max \mathscr I_{in}$, where
$$
\mathscr I_{in}:=\{i: J_i\cap [-Mh,Mh]\ne\emptyset\}.
$$
we have
$$-C^{-1}\log h\le r_1,s_1\le -C\log h.$$
Moreover, for any $i\in \mathscr I_{in}\setminus \{0\}$, we have
$$
\frac{h}{-C\log h}\le|J_i|  \le \frac{Ch}{-\log h}\ \ \text{ and }\ \
\frac{h}{-C\log h}\le  |G_i| \le C h.
$$

(v)  Write  $\mathscr I_{out}:=\mathscr I_{out}^-\bigsqcup \mathscr I_{out}^+$, where
$$
\mathscr I_{out}^-:=\{i: J_i\cap [\eta,-\epsilon]\ne\emptyset\};\ \ \ \mathscr I_{out}^+:=\{i: J_i\cap [\epsilon,\xi]\ne\emptyset\}.
$$
Then for any $i\in \mathscr I_{out}$, we have
$$
e^{-\frac{C}{h}}\le |J_i|\le e^{-\frac{1}{Ch}};\ \ C^{-1}h\le |G_i|\le Ch.
$$

(vi) For any $i\in \mathscr I_{mid}:=\mathscr I\setminus(\mathscr I_{in}\cup
 \mathscr I_{out})$, we have
$$
 e^{-\frac{|c_i|C}{h}}\frac{h}{-C\log|c_i|}\le |J_i|\le  e^{-\frac{|c_i|}{Ch}}\frac{Ch}{-\log|c_i|};\ \  \frac{h}{-C\log |g_i|}\le |G_i|\le \frac{Ch}{-\log |g_i|},
$$
where $c_i$ and $g_i$ are the centers of $J_i$ and $G_i$, respectively.

\end{defi}
See Figures \ref{fig-inside}, \ref{fig-outside}, \ref{fig-middle} for geometric illustrations of  $(iv), (v), (vi),$ respectively.

