Let us first make some simple observations that will be useful later.

\begin{lem}\label{lenth-of-band}
 Assume $\varsigma,\epsilon, M,C$ satisfy \eqref{parameter}. Then there exists $\hat h=\hat h(C)>0$ such that if $h\in (0,\hat h]$ and  $(I,\mathcal J) $ is a standard $(\varsigma,\epsilon, M,C,h)$-configuration, then
   \begin{equation}\label{upper-lower-length}
    e^{-C/h}\le \mathcal J_{\min}\le \mathcal J_{\max}\le Ch.
   \end{equation}

\end{lem}

\begin{proof}
  Choose $\hat h=\hat h(C)>0$ such that for any $h\in (0,\hat h]$, we have
\begin{equation}\label{h_0}
 e^{-\frac{1}{Ch}}\le Ch \ \ \text{ and }\ \  e^{-\frac{C}{h}}\le e^{-\frac{C}{10h}}\frac{h}{-C\log h} .
\end{equation}
Notice that if $i\in \mathscr I_{mid}$, then
$$h\le Mh\le|c_i|\le \epsilon\le \varsigma/100<1/10.$$
So if $h\in (0,\hat h]$, by Definition \ref{config-standard} and \eqref{h_0},
\begin{eqnarray*}
% \nonumber % Remove numbering (before each equation)
\mathcal J_{\max}&\le& \max\left\{Ch, \frac{Ch}{-\log h}, e^{-\frac{1}{Ch}}, \frac{Ch}{\log 10}\right\}\le Ch,\\
\mathcal J_{\min}&\ge& \min\left\{\frac{h}{C}, \frac{h}{-C\log h}, e^{-\frac{C}{h}}, e^{-\frac{C}{10h}}\frac{h}{-C\log h}\right\}\ge e^{-\frac{C}{h}}.
\end{eqnarray*}
So \eqref{upper-lower-length} holds.
\end{proof}

To model the more general pair $(B,\tilde \B_B)$  which  is mentioned  in Paragraph \ref{sec-struc-spec},  we introduce two more configurations as follows:

\begin{defi}
  Assume $(I,\mathcal J)$ is a $[r,s]$-configuration and  $\varsigma,\epsilon, M,C, h$ satisfy \eqref{parameter}. We call $(I,\mathcal J)$ an $(\varsigma,\epsilon, M,C,h)$-configuration if there exists an affine map $T$ such that $(T(I),T(\mathcal J))$ is a standard $(\varsigma,\epsilon, M, C,h)$-configuration, where
  $
  T(\mathcal J):=\{T(J): J\in \mathcal J\}.
  $
\end{defi}

%Assume $I$ is a compact interval and $\{I_1,\cdots, I_\kappa\}$ is a family of subintervals of $I$.
%$\{I_1,\cdots,I_\kappa\}$ is called a closed partition of $I$ if all $I_i$ are closed and
% $$
% \bigcup_{i=1}^\kappa I_i=I;\ \  \overset{\circ}{I_i}\cap \overset{\circ}{I_j}=\emptyset,\ \  i\ne j.
% $$


\begin{defi}\label{config-kappa-rho}
    Assume $(I,\mathcal J)$ is a  configuration and  $\varsigma,\epsilon, M,C, h$ satisfy \eqref{parameter}.  Assume $k\in \N$ and $\rho\in (0,1)$. We call $(I,\mathcal J)$ a  $(k,\rho;\varsigma,\epsilon, M, C,h)$-configuration if the following hold:

(i)
 There exists a  disjoint family  $\{I_1,\cdots, I_k\}$ of subintervals of $I$   such that
     $$
    \frac{\rho}{k}\le  \frac{|I_i|}{|I|}\le \frac{1}{\rho k}, \  \forall i=1,\cdots,k
     $$
     and for any $J\in \mathcal J$, there exists some $i$ (hence unique) such that $J\subset I_i$.

  (ii)    For any $i$, define
    $
    \mathcal J_i:=\{J\in \mathcal J: J\subset I_i\}.
    $ Then
     $(I_i,\mathcal J_i)$ is a $(\varsigma,\epsilon, M,C,h)$-configuration.

\end{defi}
