We have the following observation, which is crucial later for estimating the dimensions of the spectrum.

\begin{lem}\label{pre-dim-delta}
Given $k\in \N$, $\rho\in (0,1)$. Assume $\varsigma,\epsilon, M, C, h$ satisfy \eqref{parameter}. Assume  $(I,\mathcal J)$ is a $(k,\rho; \varsigma,\epsilon,M,C,h)$-configuration. Let $\hat h$ be the constant in Lemma \ref{lenth-of-band}.  Then

(1)  There exists $\tilde h=\tilde h(C,\varsigma,\rho)\in (0,\hat h]$ such that if $h\in (0,\tilde h] $, then for any $J\in \mathcal J$,
\begin{equation*}
  \frac{\rho}{8ke^{C/h}}\le \frac{|J|}{|I|}\le \frac{Ch}{2k\rho \varsigma}\le \frac{1}{10}.
\end{equation*}

(2) Assume $h\in (0,\tilde h]$. Assume $r>0$ satisfies
$\mathcal J_{\min}\le r<|I|$. Then
$$N_r(I)\le \frac{16k e^{C/h}}{\rho}.$$
%where $N_r(I)$ is the minimal number of intervals of length $r$ which can cover $I$.


(3) Fix $\kappa\in \N.$ Then for any $\delta\in(0,1)$  there exists $h(\delta)\in (0,\tilde h]$ such that if $h\in (0,h(\delta)]$ and $1\le k\le \kappa$,   then
\begin{equation}\label{delta}
\sum_{J\in \mathcal J}\left(\frac{|J|}{|I|}\right)^\delta\le 1.
\end{equation}

\end{lem}

\begin{proof}
(1) Define $\tilde h$ as
\begin{equation}\label{def-tilde-h}
  \tilde h:=\min\left\{\hat h, \frac{2\rho\varsigma}{10C}\right\}.
\end{equation}

Fix any $h\in(0,\tilde h]$. Assume $J_\ast\in \mathcal J_i$ is such that $|J_\ast|=\mathcal J_{\min}.$
By Definition \ref{config-kappa-rho}, $(I_i,\mathcal J_i)$ is a $( \varsigma,\epsilon,M,C,h)$-configuration and $|I_i|/|I|\ge \rho/k$.  So by Lemma \ref{lenth-of-band},
\begin{align*}
  \frac{\mathcal J_{\min}}{|I|} & =\frac{|J_\ast|}{|I_i|}\frac{|I_i|}{|I|}\ge\frac{e^{-C/h}}{8}\frac{\rho}{k}=\frac{\rho}{8ke^{C/h}}.
\end{align*}
Similarly, assume $J^\ast\in \mathcal J_j$  is such that $|J^\ast|=\mathcal J_{\max}.$
By Definition \ref{config-kappa-rho}, $(I_j,\mathcal J_j)$ is a $( \varsigma,\epsilon,M,C,h)$-configuration and $|I_j|/|I|\le 1/k\rho$.  So by Lemma \ref{lenth-of-band},
\begin{align*}
  \frac{\mathcal J_{\max}}{|I|} & =\frac{|J^\ast|}{|I_j|}\frac{|I_j|}{|I|}\le\frac{Ch}{2\varsigma}\frac{1}{k\rho}=\frac{Ch}{2k\rho \varsigma}\le \frac{1}{10}.
\end{align*}
So the result follows.

(2) By (1), we have
\begin{align*}
N_r(I) \le \frac{|I|}{r} +1& \le \frac{|I|}{\mathcal J_{\min}}+1\le \frac{8k e^{C/h}}{\rho}+1\le\frac{16k e^{C/h}}{\rho}.
\end{align*}


(3)
Assume $\{I_1,\cdots,I_k\}$ are the  subintervals in Definition \ref{config-kappa-rho}(i). Since $k\le \kappa$, we have
$$
\sum_{J\in \mathcal J}\left(\frac{|J|}{|I|}\right)^\delta=\sum_{i=1}^k\sum_{J\in \mathcal J_i}\left(\frac{|J|}{|I_i|}\right)^\delta\left(\frac{|I_i|}{|I|}\right)^\delta\le \frac{\kappa}{\rho^{\delta}}\max_{1\le i\le k}\sum_{J\in \mathcal J_i}\left(\frac{|J|}{|I_i|}\right)^\delta.
$$
By Definition \ref{config-kappa-rho}(ii), each $(I_i, \mathcal J_i)$ is a $(\varsigma,\epsilon,M,C,h)$-configuration.
Thus to get \eqref{delta}, we only need to show that for a standard $(\varsigma,\epsilon, M, C,h)$-configuration  $(I,\mathcal J)$, we have
\begin{equation}\label{delta-1}
  \sum_{J\in \mathcal J}\left(\frac{|J|}{|I|}\right)^\delta\le\frac{\rho^\delta}{\kappa}.
\end{equation}

Now assume  $(I,\mathcal J)$ is a standard $(\varsigma,\epsilon, M, C,h)$-configuration. By Definition \ref{config-standard}(i), we have $|I|\ge 2\varsigma$. To show \eqref{delta-1}, we only need to show that
\begin{equation}\label{delta-2}
  S(\delta):=\sum_{J\in \mathcal J}|J|^\delta\le\frac{(2\varsigma\rho)^\delta}{\kappa}.
\end{equation}

We  split the sum in \eqref{delta-2} into three parts and estimate them separately.
Write
\begin{equation*}
  S(\delta)=\sum_{J\in \mathcal J}|J|^\delta=\sum_{i\in \mathscr I_{in}}|J_i|^\delta+\sum_{i\in \mathscr I_{out}}|J_i|^\delta+\sum_{i\in \mathscr I_{mid}}|J_i|^\delta=: S_{in}(\delta)+ S_{out}(\delta)+ S_{mid}(\delta).
\end{equation*}
By Definition \ref{config-standard}(iii) and (iv), we have
\begin{align}\label{S-in}
  S_{in}(\delta) & =\sum_{-r_1\le i\le s_1}|J_i|^\delta\le (Ch)^\delta+(-2C\log h)\left(\frac{Ch}{-\log h}\right)^\delta.
\end{align}
By Definition \ref{config-standard}(ii) and (v), we have
\begin{align}\label{S-out}
  S_{out}(\delta) & =\sum_{i\in \mathscr I_{out}}|J_i|^\delta\le 2\frac{C}{h}\exp\left(\frac{-\delta}{Ch}\right).
\end{align}
By \eqref{S-in} and \eqref{S-out} it is seen that there exists $h_1\in (0,\tilde h]$ such that for any $h\in (0,h_1]$ we have
\begin{equation}\label{est-S-in-out}
  S_{in}(\delta),\ \ \  S_{out}(\delta)\le \frac{(2\varsigma\rho)^\delta}{3\kappa}.
\end{equation}

The estimate of $S_{mid}(\delta)$ is more complex. We need to split the sum further according to different scales. We proceed as follows. Assume $L=L(h)\in \N$ is such that
\begin{equation*}
  e^{-L-1}< h\le e^{-L}.
\end{equation*}
Recall that $c_i$ is the center of $J_i.$
For any $1\le l\le L$, define
$$
\mathscr I_{mid}^l:=\{i\in \mathscr I_{mid}: e^{-l-1}<|c_i|\le e^{-l}\}.
$$
Since $e^{-L-1}<h< Mh\le|c_i|\le \epsilon<e^{-1}$, we have
$$
\mathscr I_{mid}=\bigsqcup_{l=1}^L \mathscr I_{mid}^l.
$$
By Definition \ref{config-standard}(vi), if $i\in \mathscr I_{mid}^l$, we have
\begin{align*}
  |J_i| & \le C \exp(-e^{L-l}/eC)\frac{h}{l}.
\end{align*}
Now we estimate the cardinality of $\mathscr I_{mid}^l$. If $i-1,i\in \mathscr I_{mid}^l$, then
$$
e^{-l-1}<|c_{i-1}|<|g_i|<|c_i|\le e^{-l}.
$$
By Definition \ref{config-standard}(vi), we have
$$
|G_i|\ge \frac{h}{-C\log |g_i|}\ge \frac{h}{C(l+1)}.
$$
From this we conclude that
\begin{equation*}
  \#\mathscr I_{mid}^l\le \frac{C(l+1)(e^{-l}-e^{-l-1})}{h}+2\le \frac{6Cle^{-l}}{h}.
\end{equation*}
Consequently, we have
\begin{align*}\label{S-in}
  S_{mid}^{(l)}(\delta) :&=\sum_{i\in \mathscr I_{mid}^l}|J_i|^\delta\le \frac{6Cle^{-l}}{h}
  C^\delta \exp(-e^{L-l}\delta/eC)\frac{h^\delta}{l^\delta}\\
  &=6C^{1+\delta}l^{1-\delta}e^{-l}h^{\delta-1}\exp(-e^{L-l}\delta/eC)\\
  &\le 6C^{2}le^{-l}\exp((L+1)(1-\delta)-e^{L-l}\delta/eC)\\
  &\le 6eC^{2}le^{-l}\exp(L(1-\delta)-e^{L-l}\delta/eC).
\end{align*}
If $1\le l\le L(1-\delta/2)$, then
\begin{equation*}
  S_{mid}^{(l)}(\delta)\le 6eC^{2}L\exp(L-e^{\delta L/2}\delta/eC).
\end{equation*}
If $ l> L(1-\delta/2)$, then
\begin{equation*}
  S_{mid}^{(l)}(\delta)\le 6eC^{2}Le^{-L(1-\delta/2)}\exp(L(1-\delta))=6eC^{2}Le^{-L\delta/2}.
\end{equation*}
From these, it is seen that there exists $h(\delta)\in (0,h_1)$ such that for any $h\in (0,h(\delta)]$ and any $1\le l\le L$ we have
\begin{equation}\label{est-S-mid-k}
  S_{mid}^{(l)}(\delta)\le \frac{(2\varsigma\rho)^\delta}{3L\kappa}.
\end{equation}
Consequently, we have
\begin{equation}\label{est-S-mid}
 S_{mid}(\delta)=\sum_{l=1}^{L} S_{mid}^{(l)}(\delta)\le \frac{(2\varsigma\rho)^\delta}{3\kappa}.
\end{equation}
Combine with  \eqref{est-S-in-out} and \eqref{est-S-mid}, we get \eqref{delta-2}.
\end{proof}


