 Assume $\Omega_n$ has been defined, we define $\Omega_{n+1}$ as follows.
Fix any $w\in \Omega_n$,
choose $k_w\in \N$, and for  any $1\le k\le k_w$, choose  $r_w^{[k]}, s_w^{[k]}\in \N$. We write
$$
I_w^{[k]}:=\{i\in \Z:-r_w^{[k]}\le i\le s_w^{[k]},i\ne0\}
$$
and define the alphabets
$$
\mathscr A_w^{[k]}:=\{i_\1^{[k]}: i\in I_w^{[k]}\}\cup \{0_\2^{[k]}\}\ \ \text{ and }\ \
\mathscr A_w:=\bigcup_{1\le k\le k_w}\mathscr A_w^{[k]}.
$$
We define $\Omega_{n+1}$ as
$$
\Omega_{n+1}:=\{w e: w\in \Omega_n; e\in \mathscr A_w\}.
$$
By induction, we have defined a set $\Omega_n$ for any $n\in\Z_+$. Finally we write
$$
\Omega_\ast:=\bigcup_{n\in \Z_+}\Omega_n.
$$
We call $\Omega_\ast$ a {\it language} and call any $w\in \Omega_\ast$ a {\it word}.



For any $w\in \Omega_\ast$ and any $e=i^{[k]}_{\mathbf t}\in \mathscr A_w$, we call $\mathbf t, k, i$ the {\it type}, the {\it global index}, the {\it local index} of $e$, respectively and  will use the notations
\begin{equation*}
  T_e:=\mathbf t;\ \ \ G_e:=k;\ \ \ L_e:=i.
\end{equation*}

For any $w\in \Omega_\ast$, we also introduce an order on $\mathscr A_w$ as follows: for $e,\hat e\in \mathscr A_w$ and $e\ne \hat e$,
$$
e\prec \hat e\Leftrightarrow G_e<G_{\hat e} \text{ or } \ G_e=G_{\hat e}, L_e<L_{\hat e}.
$$

For any $w=w_0\cdots w_n\in \Omega_n$, we define $T_w:=T_{w_n}$ and  say that $w$ has type $T_{w_n}.$  We also write $|w|=n$ and say that $w$ is a word of length $n.$  For any $0\le i\le n$, we  write $w|_i:=w_0\cdots w_i$ and call it the $i$-th prefix of $w.$

\subsection{ A nested covering structure coded by $\Omega_\ast$}\

Assuming  $\Omega_\ast$ is a language defined  in the previous subsection, we now describe a nested covering structure indexed by $\Omega_\ast$.

\begin{defi}
 Given a language $\Omega_\ast$.  Assume $\mathcal I(\Omega_\ast):=\{I_w: w\in \Omega_\ast\}$ is a class of compact intervals in $\R$. We say that  $\mathcal I(\Omega_\ast)$  is  a nested covering structure if
the following hold:

(i) For any $w\in \Omega_*$,  the pair $(I_w,\mathcal J_w)$ is a configuration, where $\mathcal J_w:=\{I_{we}: e\in \mathscr A_w\}.$ Moreover, for different $e,\hat e\in \mathscr A_w,$
\begin{equation*}
  I_{we}<I_{w\hat e} \Leftrightarrow e\prec \hat e.
\end{equation*}



(ii) $\max\{|I_w|: w\in \Omega_n\}\to 0$ as $n\to\infty$.

\end{defi}

Finally, if $\mathcal I(\Omega_\ast)$ is a nested covering structure, we define the limit set of  $\mathcal I(\Omega_\ast)$ as
\begin{equation}\label{def-lim-set}
  X(\Omega_\ast):=\bigcap_{n\ge0} \bigcup_{w\in \Omega_n} I_w.
\end{equation}


Assume $\mathcal I(\Omega_\ast)$ is a nested covering structure. For each $w\in \Omega_*$ and $1\le k\le k_w$, we write
$$
\mathcal J_w^{[k]}:=\{I_{we}: e\in \mathscr A_w^{[k]}\} \ \ \text{ and }\ \ I_w^{[k]}:={\rm Co}(\bigcup_{J\in \mathcal J_w^{[k]}}J),
$$
where ${\rm Co}(A)$ denotes the convex hull of $A$. Then  $(I_w^{[k]}, \mathcal J_w^{[k]}), \ 1\le k\le k_w$ are all configurations and
$$\mathcal J_w=\bigsqcup_{1\le k\le k_w}\mathcal J_w^{[k]}.$$


\subsection{Upper bounds of the dimensions for limit sets}\


Now we can state the main result of this section:

\begin{thm}\label{abstract-dim-bd}
  Assume $\kappa\in \N$ and $\rho\in (0,1)$. Assume $\varsigma, \epsilon, M,C$ satisfy \eqref{parameter}. Fix any $\delta\in (0,1)$, let $h(\delta)$ be the constant given by Lemma \ref{pre-dim-delta}(3). Assume $\Omega_\ast$ is a language  and $\mathcal I(\Omega_\ast)$ is a nested covering structure such that for any $w\in \Omega_\ast$,   there exists $h_w>0$ such that $(I_w, \mathcal J_w)$ is a $(k_w,\rho; \varsigma,\epsilon,M,C,h_w)$-configuration with
  $(I_w^{[k]}, \mathcal J_w^{[k]}), \ 1\le k\le k_w$  the related sub $(\varsigma,\epsilon,M,C,h_w)$-configurations.

  (1) If $k_w\le \kappa$ and $h_w\in (0,h(\delta)]$ for any $w\in \Omega_\ast$, then
  $$\dim_H X(\Omega_\ast)\le \delta.$$

  (2) Fix any $h'(\delta)\in (0,h(\delta)]$.  If $k_w\le \kappa$ and $h_w\in [h'(\delta),h(\delta)]$ for any $w\in \Omega_\ast$, then
  $$\overline{\dim}_B X(\Omega_\ast)\le \delta.$$
\end{thm}

\begin{proof}
  (1)   For any $n$, $\{I_w: w\in \Omega_n\}$ forms a covering of $X(\Omega_\ast)$. Moreover, by Lemma \ref{pre-dim-delta}(1) we have
\begin{equation}\label{upper-est-n-band}
|I_w|=|I_{\emptyset_{\mathbf t}}|\prod_{i=1}^n \frac{|I_{w|_i}|}{|I_{w|_{i-1}}|}\le\frac{|I_{\emptyset_{\mathbf t}}|}{10^n}\to 0.
\end{equation}

We claim that for any $n\in \N,$
\begin{equation}\label{sim-dim}
  \sum_{w\in \Omega_n}|I_w|^\delta\le |I_{\emptyset_{\mathbf t}}|^\delta.
\end{equation}

We show it by induction. When $n=0,$ it is trivially true.

Now assume the statement is true for $n-1$. We have
\begin{align*}
  \sum_{u\in \Omega_n} |I_u|^\delta & =\sum_{w\in\Omega_{n-1}}\sum_{e\in \mathscr A_w}|I_{we}|^\delta =\sum_{w\in\Omega_{n-1}}|I_w|^\delta\sum_{e\in \mathscr A_w}\frac{|I_{we}|^\delta}{|I_w|^\delta}.
\end{align*}
By the assumption,  the pair $(I_w,\{I_{we}:e\in \mathscr A_w\})$ is a $(k_w,\rho;\varsigma,\epsilon,M,C,h_w)$-configuration with $k_w\le \kappa$ and  $h_w\le h(\delta)$. By Lemma \ref{pre-dim-delta}(3), we have
$$
\sum_{e\in \mathscr A_w}\frac{|I_{we}|^\delta}{|I_w|^\delta}\le 1.
$$
So by induction hypothesis, we have
\begin{align*}
  \sum_{u\in \Omega_n} |I_u|^\delta =\sum_{w\in\Omega_{n-1}}|I_w|^\delta\sum_{e\in \mathscr A_w}\frac{|I_{we}|^\delta}{|I_w|^\delta}\le \sum_{w\in\Omega_{n-1}}|I_w|^\delta\le |I_{\emptyset_{\mathbf t}}|^\delta.
\end{align*}
By induction, the claim holds.

Then by the definition of Hausdorff measure, we have
$$
\mathscr H^\delta(X(\Omega_\ast))\le |I_{\emptyset_{\mathbf t}}|^\delta,
$$
where $\mathscr H^\delta$ denotes $\delta$-dimensional Hausdorff measure. Consequently, $\dim_H X(\Omega_\ast)\le \delta.$

(2)  Assume $0<r<|I_{\emptyset_{\mathbf t}}|$, let us estimate $N_r(X(\Omega_\ast))$. Our strategy is the following: we construct an interval  covering of $X(\Omega_\ast)$ such that each interval in this covering has approximately the size $r$, then we estimate the number of intervals.

At first, we define a subset of  $\Omega_\ast$  as follows. By \eqref{upper-est-n-band},  for any $w\in\Omega_n$ we have
$$
|I_w|\le |I_{\emptyset_{\mathbf t}}|/{10^n}.
$$

Take $N\in \N$ such that $|I_{\emptyset_{\mathbf t}}|/10^N<r.$ For each $w\in \Omega_N$, let $0\le m_w\le N$ be the integer such that
\begin{equation}\label{m-w}
  |I_{w|_{m_w}}|>r, (\mathcal J_{w|_{m_w}})_{\min}\le r.
\end{equation}
Since $|I_{\emptyset_{\mathbf t}}|>r$ and $|I_w|<r$, the number $m_w$ is well-defined and unique. Now define
$$
\mathcal U:=\{w|_{m_w}: w\in \Omega_N\}.
$$

We claim that:  $\{I_u: u\in \mathcal U\}$ is a covering of $X(\Omega_\ast)$ and
$\sum_{u\in \mathcal U}|I_u|^\delta\le |I_{\emptyset_{\mathbf t}}|^\delta.$

Indeed,
by \eqref{def-lim-set}, $\{I_w: w\in \Omega_N\}$ is a covering of $X(\Omega_\ast)$. Since for each $w\in \Omega_N$, we have $u=w|_{m_w}\in \mathcal U$ and $I_w\subset I_u$, so the first statement holds.

Notice that if $u,\hat u\in \mathcal U$ and $u\ne \hat u$, then $u$ and $\hat u$ are non-compatible, that is, neither $u\lhd \hat u$, nor $\hat u\lhd u$ (where $u\lhd v$ means that $u$ is a prefix of $v$). This is due to the uniqueness of $m_w$ in \eqref{m-w}. Now write
$$m_\ast=\min\{|u|: u\in \mathcal U\}\ \ \text{ and }\ \  m^\ast=\max\{|u|: u\in \mathcal U\}.$$ Then $0\le m_\ast\le m^\ast\le N.$ For any $m_\ast\le k\le m^\ast$, write
$$
\mathcal U_k:=\{u\in \mathcal U: |u|=k\}.
$$
Then $\mathcal U=\bigsqcup_{k=m_\ast}^{m^\ast} \mathcal U_k.$
By \eqref{sim-dim} and Lemma \ref{pre-dim-delta}(3), we have
\begin{eqnarray*}
  |I_{\emptyset_{\mathbf t}}|^\delta&\ge& \sum_{u\in \Omega_{m_\ast}}|I_u|^\delta=\sum_{u\in \mathcal U_{m_\ast}}|I_u|^\delta+\sum_{u\in \Omega_{m_\ast}\setminus\mathcal U_{m_\ast}}|I_u|^\delta\\
  &\ge&\sum_{u\in \mathcal U_{m_\ast}}|I_u|^\delta+\sum_{u\in \Omega_{m_\ast}\setminus\mathcal U_{m_\ast}}\sum_{e\in\mathscr A_u}|I_{ue}|^\delta=\sum_{u\in \mathcal U_{m_\ast}}|I_u|^\delta+\sum_{v\in \mathcal V_{m_\ast+1}}|I_v|^\delta,
\end{eqnarray*}
where $\mathcal V_{m_\ast+1}:=\{ue: u\in \Omega_{m_\ast}\setminus\mathcal U_{m_\ast},e\in\mathscr A_u\}$. Since words in $\mathcal U_{m_\ast+1}$ and $\mathcal U_{m_\ast}$ are non compatible, we must have $\mathcal U_{m_\ast+1}\subset \mathcal V_{m_\ast+1}.$ Consequently,
\begin{eqnarray*}
  |I_{\emptyset_{\mathbf t}}|^\delta&\ge& \sum_{u\in \mathcal U_{m_\ast}}|I_u|^\delta+\sum_{v\in \mathcal V_{m_\ast+1}}|I_v|^\delta\\
  &=&\sum_{u\in \mathcal U_{m_\ast}}|I_u|^\delta+\sum_{u\in \mathcal U_{m_\ast+1}}|I_u|^\delta+\sum_{v\in \mathcal V_{m_\ast+1}\setminus\mathcal U_{m_\ast+1}}|I_{v}|^\delta.
\end{eqnarray*}
We can iterate this process. Finally we get
$$
|I_{\emptyset_{\mathbf t}}|^\delta\ge\sum_{k=m_\ast}^{m^\ast} \sum_{u\in \mathcal U_{k}}|I_u|^\delta=\sum_{u\in \mathcal U}|I_u|^\delta.
$$
Hence the second statement of the claim holds.

By \eqref{m-w} and the claim, we have
$$
|I_{\emptyset_{\mathbf t}}|^\delta\ge \sum_{u\in \mathcal U}|I_u|^\delta\ge r^\delta \#\mathcal U.
$$
For each $u\in \mathcal U$, since $(I_u, \mathcal J_u)$ is a $(k_u,\rho; \varsigma,\epsilon,M,C,h_u)$-configuration with $k_u\le \kappa$ and $h'(\delta)\le h_u\le h(\delta)$, by Lemma \ref{pre-dim-delta}(2),we have
$$
N_r(I_u)\le \frac{16k_u e^{C/h_u}}{\rho}\le \frac{16\kappa e^{C/h'(\delta)}}{\rho}.
$$
Since $\{I_u: u\in \mathcal U\}$ is a covering of $X(\Omega_\ast)$, we have
$$
N_r(X(\Omega_\ast))\le \sum_{u\in \mathcal U}N_r(I_u)\le \frac{16\kappa e^{C/h'(\delta)}}{\rho}\#\mathcal U\le \frac{16\kappa e^{C/h'(\delta)}|I_{\emptyset_{\mathbf t}}|^\delta}{\rho}r^{-\delta}.
$$
Then we have
$$
\overline{\dim}_B X(\Omega_\ast)=\limsup_{r\to0}\frac{\log N_r(X(\Omega_\ast))}{-\log r}\le \delta.
$$
So the result follows.
\end{proof}

 \section{The fractal  dimensions  of the spectrum of  critical AMO}\label{sec-dim}

In this section, we apply  Theorem \ref{abstract-dim-bd} to  critical AMO and finish the proof of Theorems~\ref{main-3} and ~\ref{main-2}.


\subsection{ The nested covering  structure  of the spectrum}\


In this part, the nested covering  structure  of the spectrum established in  \cite{HS1,HS2,HS3} is essential. We summarize the  related results in Theorem \ref{key-HS-new} . The statements are extracted from all the three works and are  unified in a way  suitable for our use.   We will  make some remarks on  the connection  of the result and the works \cite{HS1,HS2,HS3}.

 \begin{rem}\label{Z-inv}
     Note that for $\alpha,\beta\in \R\setminus\Q$ with  $\alpha-\beta\in \Z$,  we have  $\Sigma_\alpha=\Sigma_\beta$.  Consequently,  both $\mathscr F_B(\delta)$ and $\mathscr F_H(\delta)$ are $\Z$-invariant.  Hence  in the rest of  this section we will  restrict $\alpha\in [0,1]\setminus \Q.$
 \end{rem}



 Assume that $\alpha\in [0,1]\setminus \mathbb{Q}$ and  has a continued fraction expansion
$$
\alpha=[a_1,a_2,a_3,\cdots].
$$
Let $G:[0,1]\setminus \mathbb{Q}\to [0,1] \setminus \mathbb{Q}$ be the Gauss map defined by
\begin{equation*}
  G(\alpha):=\{1/\alpha\}.
\end{equation*}
For any $n\in \N$,  define
\begin{equation*}
  h_n(\alpha):=2\pi[a_n,a_{n+1},a_{n+2},\cdots]=2\pi G^{n-1}(\alpha).
\end{equation*}

