\subsection{Arbitrarily small  Hausdorff and upper box dimensions of the spectrum}

As an application of Theorem \ref{abstract-dim-bd} and  Lemma \ref{pre-dim-delta}, we have the following estimates.


\begin{prop}\label{basic-H-B}

Let $\hat m \in \Z_+$  and $\hat M \geq 2$. Then for any $\delta>0$, there exists a constant
$L:=L(\delta,\hat m, \hat M)>0$ such that   the following hold:

(1) If
$\alpha=[a_1,a_2,\cdots,a_{\hat m},a_{\hat m+1},\cdots]$ is  such that $q_{\hat m}(\alpha)$ is odd and
   \begin{equation}\label{alpha-condi-1}
  1\le a_n\le \hat M,\ (1\le n\le \hat m); \ \ L\le a_n, \ (n\ge \hat m+1),
  \end{equation}
   then $\dim_H\Sigma_\alpha\le \delta$.

   (2) Fix any $\gamma>1$. If
$\alpha=[a_1,a_2,\cdots,a_{\hat m},a_{\hat m+1},\cdots]$ is such that $q_{\hat m}(\alpha)$ is odd and
   $$
  1\le a_n\le \hat M,\ (1\le n\le \hat m); \ \ L\le a_n\le \gamma L, \ (n\ge \hat m+1),  $$
   then $\overline{\dim}_B\Sigma_\alpha\le \delta$.
\end{prop}


\begin{proof}
(1)
  Let $\epsilon_0,\varsigma,\kappa$ be the constants in Theorem \ref{key-HS-new}.
Fix
$$\epsilon\in (0, \frac{\varsigma}{100}\wedge \epsilon_0].$$ Let $h_0>0,M> C>1,\rho\in (0,1)$ be the constants determined by Theorem \ref{key-HS-new}.

Now fix any $\delta>0$. Choose $h(\delta,\hat m,\hat M)\in (0,h_0)$ such that  Lemma \ref{pre-dim-delta} holds. Choose
$$L(\delta,\hat m,\hat M):=2\pi/h(\delta,\hat m,\hat M).$$
Now fix any $\alpha=[a_1,a_2,\cdots]$ such that \eqref{alpha-condi-1} holds.
Then for any $n\ge \hat m+1$, we have
$$
h_n(\alpha)= \frac{2\pi}{a_n+G_{n}(\alpha)}\le \frac{2\pi}{a_n}\le h(\delta,\hat m,\hat M)\le h_0.
$$
By Theorem \ref{key-HS-new}, there exists $\{I_i: 1\le i\le q_{\hat m}(\alpha)\}$ and  for any $1\le i\le q_{\hat m}(\alpha),$ there exist $\Omega_\ast^{(i)}$ and $\mathcal I(\Omega_\ast^{(i)})$ such that Theorem \ref{key-HS-new}  (2-1) and (2-2) hold. Then by Theorem \ref{abstract-dim-bd}(1), we have
$$
\dim_H \Sigma_\alpha=\dim_H \bigcup_{1\le i\le q_{\hat m}(\alpha)}\Sigma_\alpha^{(i)}=\max_{1\le i\le q_{\hat m}(\alpha)}\dim_H\Sigma_\alpha^{(i)}=\max_{1\le i\le q_{\hat m}(\alpha)}\dim_H X(\Omega_\ast^{(i)})\le \delta.
$$


(2) By the assumption, for any $n\ge \hat m+1$ we also have
$$
h_n(\alpha)= \frac{2\pi}{a_n+G_{n}(\alpha)}\ge \frac{2\pi}{a_n+1}\ge \frac{\pi}{a_n}\ge \frac{\pi}{\gamma L(\delta,\hat m,\hat M)}= \frac{h(\delta,\hat m,\hat M)}{2\gamma}.
$$
Then by Theorem \ref{abstract-dim-bd}(2), we have
$$
\overline{\dim}_B \Sigma_\alpha=\overline{\dim}_B \bigcup_{1\le i\le q_{\hat m}(\alpha)}\Sigma_\alpha^{(i)}=\max_{1\le i\le q_{\hat m}(\alpha)}\overline{\dim}_B\Sigma_\alpha^{(i)}=\max_{1\le i\le q_{\hat m}(\alpha)}\overline{\dim}_B X(\Omega_\ast^{(i)})\le \delta.
$$
\end{proof}
\subsection{Proofs of Theorem \ref{main-3} and Theorem \ref{main-2}}\

  Given Proposition \ref{basic-H-B}, the proofs are essentially the same as that of \cite{HLQZ} Theorem 1.1. The only extra issue is  the parity of $q_{\hat m}(\alpha)$.
To deal with this, we need  the following well-known fact.  We also include a very short proof.

\begin{lem}\label{odd}
  Given $\alpha\in [0,1]\setminus \Q$, assume $p_n(\alpha)/q_n(\alpha)$ is the $n$-th convergent of $\alpha$. Then for any $n\in \N$, at least one of $q_n(\alpha), q_{n+1}(\alpha)$ is odd.
\end{lem}

\begin{proof}
  Note that $q_n(\alpha)$ can be defined recursively by
  $$
  q_{-1}(\alpha)=0, \ q_0(\alpha)=1, \ q_{n+1}(\alpha)=a_{n+1}q_{n}(\alpha)+q_{n-1}(\alpha),\  (n\ge0).
  $$
  If both $q_n(\alpha)$ and $q_{n+1}(\alpha)$ are even for some $n\ge1$, then
  $$
  q_{n-1}(\alpha)=q_{n+1}(\alpha)-a_{n+1}q_{n}(\alpha)
  $$
  is also even. By induction, we get $q_0(\alpha)$ is even, a contradiction.
\end{proof}

\noindent {\bf Proof of Theorem \ref{main-3}.}
By Remark \ref{Z-inv}, we only need to show that $\mathscr F_B(\delta)\cap [0,1]$  is dense in $[0,1]$ and has positive Hausdorff dimension.

At first we show that $\mathscr F_B(\delta)\cap [0,1]$ has positive Hausdorff dimension.  Take $L=L(\delta, 2,2)$ as in  Proposition \ref{basic-H-B}. Define
$$
\mathscr F:=\{[1,2,a_3,a_4,\cdots]: L\le a_n\le 10 L, n\ge3\}.
$$
Then for any $\alpha\in \mathscr F$, we have $q_2(\alpha)=3.$ By Proposition \ref{basic-H-B},
we have $\overline \dim_B \Sigma_\alpha\le \delta.$  So $\mathscr  F\subset \mathscr F_B(\delta)\cap [0,1]$. By \cite{Go} Theorem 11, $\dim_H G^2(\mathscr  F)>0.$ By a simple computation, we know that $G^2: \mathscr F\to G^2(\mathscr F)$ is a bi-Lipschitz map. So $\dim_H \mathscr  F=\dim_H G^2(\mathscr  F)>0$.
Hence $\dim_H\mathscr F_B(\delta)\cap [0,1]>0.$

Next we show that $\mathscr F_B(\delta)\cap [0,1]$ is dense in $[0,1]$. Fix any $N\ge 2$ and take
$$
\hat L:=L(\delta, N,N)\vee L(\delta, N+1,N).
$$
Define $\mathscr F_N:=\mathscr F_N^o\cup \mathscr F_N^e$, where
\begin{align*}
  \mathscr F_N^o&:=\{\alpha\in \R\setminus \Q: a_n\le N,\ ( n\le N);  q_N(\alpha) \text{ is odd}; a_n=\hat L, \ (n\ge N+1)\}\\
  \mathscr F_N^e&:=\{\alpha\in \R\setminus \Q: a_n\le N,\ ( n\le N);  q_N(\alpha) \text{ is even}; a_{N+1}=1, a_n=\hat L, \ (n\ge N+2)\}.
\end{align*}
By Proposition \ref{basic-H-B}, $\mathscr F_N^o\subset \mathscr F_B(\delta)\cap [0,1]$. If $\alpha\in \mathscr F_N^e$, then by Lemma \ref{odd}, $q_{N+1}(\alpha)$ is odd. Then By Proposition \ref{basic-H-B} again, $\mathscr F_N^e\subset \mathscr F_B(\delta)\cap [0,1]$. So $\mathscr F_N\subset \mathscr F_B(\delta)\cap [0,1]$. Now define
$$
\widehat{\mathscr F}:=\bigcup_{N\ge2}\mathscr F_N
$$
Then $\widehat{\mathscr F}\subset \mathscr F_B(\delta)\cap [0,1]$ and by the same argument as \cite{HLQZ} Sec. 4.4, $\widehat{\mathscr F}$ is dense in $[0,1]$. So $\mathscr F_B(\delta)\cap [0,1]$ is also dense in $[0,1]$.
\hfill $\Box$

\noindent {\bf Proof of Theorem \ref{main-2}.}\ Let $\mathcal F$ and $\widehat{\mathcal F}$  be  defined as above.  Then $\widetilde F:={\mathcal F}\cup \widehat{\mathcal F}$ is dense in $[0,1]$ and of positive Hausdorff dimension.  For any $\alpha\in \widetilde{\mathcal F}$,  we have shown that $\overline{\dim}_B\Sigma_\alpha\le \delta<1$. Consequently,   $\beta(\alpha)=0$ by \cite{JZ}. By \cite{HLQZ} Theorem 1.3, we have $\dim_H \Sigma_\alpha>0.$
\hfill $\Box$

