 \section{A short reminder on the results  in \cite{HS2}}\label{sec-ap-a}
 The following theorem was proved in \cite{HS2} and sufficient for the results given in \cite{HLQZ}.



\begin{thm}
 Let $\hat m \in \Z_+$  and $M \geq 2$. There exists $\eta_0  >0$ and, for $\eta_1 \in (0,\eta_0  )$,   constants $C=C(\hat m, M,\eta_1) >0$  and $C'=C'(\hat m, M,\eta_1) >0$ such that if
 $$\alpha=[a_1,a_2,\dots] $$
  is irrational and satisfies  for some $m\leq \hat m$
 \begin{equation}\label{0.7}
 \begin{array}{ll}
 1 \leq  a_j \leq M& \mbox{ for } 0 < j \leq m\\
 a_j \geq C & \mbox{ for } j\geq m+1\,,
 \end{array}
 \end{equation}
 then $\Sigma_{\alpha}$ is contained in the union of $q_m(\alpha)$ intervals $I_\ell (h)$ ($\ell=1,\cdots, q_m(\alpha))$ in the form
 $[\gamma_\ell (h), \delta_\ell (h)]$ with
 \begin{equation}\label{0.8}
 \begin{array}{l}
   \gamma_\ell(h)\,,\, \delta_\ell (h) \in \Sigma_{\alpha}\,,\\
 \gamma_\ell < \delta_\ell \leq \gamma_{\ell +1} < \delta_{\ell +1}\,,\\
 \gamma_\ell(h) \geq \gamma_\ell  - C' h\, \mbox{ and }   \delta_\ell (h) < \delta_\ell + C'  h\,, \\
\gamma_{\ell}(h) \geq \gamma_{\ell} + \frac{1}{C'} \sqrt{h} \mbox{ if } \delta_{\ell-1} =\gamma_{\ell}\,,
 \end{array}
 \end{equation}
 where
 \begin{equation}
  \alpha^{(m)} =[a_1,\dots,a_m]= \frac{p_m(\alpha)}{q_m(\alpha)}\,,
  \end{equation}
 \begin{equation}
 h = 2\pi |\alpha - \alpha^{(m)}| \,,
 \end{equation}
 \begin{equation}\label{0.11}
 \cup_\ell [\gamma_\ell,\delta_\ell]  =\Sigma_{\alpha^{(m)}} \,,
 \end{equation}
 \begin{equation}\label{0.12}
 d(I_\ell (h), I_{\ell+1}(h))\geq \frac 1{C' }\mbox{ if } \delta_\ell \neq \gamma_{\ell +1}
 \mbox{ and } \geq \frac 1 {C'} \sqrt{h} \mbox{ if } \delta_\ell =\gamma_{\ell +1}\,.
 \end{equation}
 For each interval $I_\ell(h)$, $\Sigma_{\alpha}\cap I_\ell (h)$ can be described as living in a union of closed intervals $J_j^{(\ell)}$ of length $\neq 0$ with
 $\partial J_{j}^{(\ell)} \subset \Sigma_{\alpha}\,$, $J_{j+1}^{(\ell)}$ on the right of $J_j^{(\ell)}$ and
 \begin{equation}\label{0.13}
\frac{1}{C'}  \frac{1}{a_{m+1}} \leq d(J_j^{(\ell)}, J_{j+1}^{(\ell)} )  \leq C'  \frac{1}{\sqrt{a_{m+1}}}\,,
 \end{equation}
 \begin{equation}
| |J_0^{(\ell)}| - 2 \eta_1|  \leq  \frac{C'}{|a_{m+1}|}\,.
 \end{equation}
 The other bands have size
 \begin{equation}\label{0.16}
 \exp \left( - C(j) |a_{m+1}| \right) \mbox{ with } \frac 1 {C'} \leq C(j) \leq C'\,.
 \end{equation}
 For $j\neq 0$, if $\kappa_j^{(\ell)} $ is the affine function sending $J_j^{(\ell)}$ into  $[-2,+2]$, then
 $$
 \kappa_j^{(\ell)}(J_{j}^{(\ell)}) \cap \Sigma_{\alpha} \subset \cup_k J_{j,k}^{(\ell)}\,,
 $$
 where the $J_{j,k}^{(\ell)}$ have analogous properties to the $J_j^{(\ell)} $ with $a_{m+1}$ replaced by $a_{m+2}$ and \eqref{0.13} can be improved in the form
 \begin{equation}
\frac{1}{C'}   \frac{1}{a_{m+2}} \leq d(J_{j,k}^{(\ell)}, J_{j,k+1}^{(\ell)}) \leq C' \frac{1}{a_{m+2}}\,.
 \end{equation}
 One can then iterate indefinitely.
   \end{thm}


