\subsection{Special Case with LoS Channels}    
In this subsection, we consider another special case with LoS channels from the BS to both users. Let $\theta_{k}$/$\phi_{k}$ be the elevation/azimuth AoD from the BS to user $k, k=1,2$. Then, the array response from the BS to user $k$ can be written as
\begin{equation}\label{eqn_ArrayResp}
    \mathbf{a}\left( \mathbf{T}, \theta_{k},\phi_{k} \right) = [e^{j\rho _{k}\left( \mathbf{t}_1 \right)},e^{j\rho _{k}\left( \mathbf{t}_2 \right)},
    \cdots ,e^{j\rho _{k}\left( \mathbf{t}_N \right)}],
\end{equation}
where $\lambda$ denotes the wavelength, and $\rho_{k}\left( \boldsymbol{\mathrm{t}}_n \right) =\frac{2\pi}{\lambda}(x_n\sin \theta _{k}\cos \phi _{k}+y_n\cos \theta _{k})$. As such, the channel vector from the BS to user $k$ can be expressed as $\mbf{h}_k(\mbf{T})=\beta_k\mbf{a}(\mbf{T},\theta_k,\phi_k),\,\,k=1,2$,
where $\beta_{k}$ denotes the path gain from the BS to user $k$.

Then, the achievable secrecy rate and multicast rate can be expressed as
\begingroup\makeatletter\def\f@size{9}\check@mathfonts
\def\maketag@@@#1{\hbox{\m@th\normalsize\normalfont#1}}%
\begin{align}	&R_c(\mbf{T})=\log_2\frac{\sigma^2+P_c\left|\beta_1\right|^2\left|\mbf{w}_c^H\mbf{a}(\mbf{T},\theta_1,\phi_1)\right|^2}{\sigma^2+P_c\left|\beta_2\right|^2\left|\mbf{w}_c^H\mbf{a}(\mbf{T},\theta_2,\phi_2)\right|^2},\label{eqn_LoS_Rc}\\
&R_0(\mbf{T})=\underset{k=1,2}{\min}R_{0,k}(\mbf{T})\label{eqn_LoS_R0},
\end{align}\endgroup
where $R_{0,k}(\mbf{T})=\log_2\left(1+\frac{P_0\left|\beta_k\right|^2\left|\mbf{w}_0^H\mbf{a}(\mbf{T},\theta_k,\phi_k)\right|^2}{\sigma^2+P_c\left|\beta_k\right|^2\left|\mbf{w}_c^H\mbf{a}(\mbf{T},\theta_k,\phi_k)\right|^2}\right)$.  We further assume an arbitrarily large movement region as in \cite{L. Zhu2023}, \cite{X. Wei}, \cite{L. Zhu2024Modeling} (i.e., constraint \eqref{p1c} is relaxed).\footnote{It is worth noting that the actual movement region of the antennas is always finite. The purpose of the asymptotic analysis here is to reveal the unique characteristics of MAs compared to FPAs in PHY-SI, similarly to that for massive multiple-input multiple-output (MIMO) systems \cite{MIMO}.} Then, the optimal secrecy and multicast beamforming solutions to (P1) can always be obtained as array response vectors, as presented in the following lemma and theorem. 	
\begin{lemma}
Let $\tilde{\mbf{w}}_c(\mbf{T})=\frac{1}{\sqrt{N}}\mbf{a}(\mbf{T},\theta_c,\phi_c)$ and $\tilde{\mbf{w}}_0(\mbf{T})=\frac{1}{\sqrt{N}}\mbf{a}(\mbf{T},\theta_0,\phi_0)$ denote the BS's transmit beamforming vector for the confidential and multicast messages, respectively, where $\theta_{c}$/$\phi_{c}$ and $\theta_{0}$/$\phi_{0}$ denote their elevation/azimuth AoDs, which can be arbitrarily selected as long as $\theta_0\ne\theta_c\ne\theta_k, k=1, 2$. Define 
\begin{equation}\label{eqn_Lem1_func}
g_{i,k}(\mbf{T})\triangleq\left|\tilde{\mbf{w}}_i^H(\mbf{T})\mbf{a}(\mbf{T},\theta_k,\phi_k)\right|^2\!,i\in\left\{c,0\right\}\!,\!k=1,2,
\end{equation}
as the secrecy/multicast beamforming gain at the direction of user $k$.
Then, there exists an APV $\mbf{T}^{\star}$ such that
\begin{equation}\label{null}
g_{c,1}(\mbf{T}^{\star})=g_{0,1}(\mbf{T}^{\star})=g_{0,2}(\mbf{T}^{\star})=N,\; g_{c,2}(\mbf{T}^{\star})=0.
\end{equation}
\end{lemma}
\begin{IEEEproof}
To construct $\mbf{T}^{\star}$, we consider that all MAs are placed with an equal spacing (denoted as $d$) along the horizontal dimension. Then, the position of the $n$-th MA is given by $\mbf{t}_n=\left[(n-1)d,0\right]^T$, $n\ic{N}$, and $g_{i,k}(\mbf{T})$ in \eqref{eqn_Lem1_func} can be simplified as
%\begingroup\makeatletter\def\f@size{9}\check@mathfonts\def\maketag@@@#1{\hbox{\m@th\normalsize\normalfont#1}}%
\begin{equation}\label{eqn_Lem1_eqn1}
g_{i,k}(\mbf{T})=\frac{1}{N}\left|\sum_{n=1}^{N}e^{j2\pi(n-1)dr_{i,k}}\right|^2=\frac{1}{N}\frac{1-\cos \left(2\pi Nr_{i,k}d\right)}{1-\cos \left(2\pi r_{i,k}d\right)},
\end{equation}
%\endgroup
where $r_{i,k}\triangleq\frac{1}{\lambda}\left(\sin\theta_k\cos\phi_k-\sin\theta_i\cos\phi_i\!+\!\cos\theta_k\!-\!\cos\theta_i\right)$.

Note that due to the randomly distributed scatterers in the environment, all $r_{i,k}$'s can be considered as irrational values and independent over the set of rational numbers with the probability of one. As such, according to \cite{A. Leshem}, for any given $\epsilon\in(0,2\pi)$, there must exist a positive integer $d$ such that
\begin{align}
    &0 < 2\pi Nr_{i,1}d < \epsilon, \;0 < 2\pi r_{i,1}d < \epsilon\;(\mathrm{mod}\,\,2\pi),\; i\in\left\{c,0\right\},\nonumber\\
    &0 < 2\pi Nr_{0,2}d < \epsilon,\;0 < 2\pi r_{0,2}d < \epsilon\;(\mathrm{mod}\,\,2\pi),\nonumber\\
    &0 < 2\pi Nr_{c,2}d < \epsilon\;(\mathrm{mod}\,\,2\pi)\nonumber\\
    &\pi - \frac{\epsilon}{2} < 2\pi r_{c,2}d < \pi + \frac{\epsilon}{2}\;(\mathrm{mod}\,\,2\pi).\label{eqn_Lem1_eqn2}
\end{align}
% \begin{equation}\label{eqn_Lem1_eqn2}
% \begin{cases}
%     \cos \left(2\pi Nr_{c,1}d\right) >  1-\delta,\quad\cos \left(2\pi r_{c,1}d\right) >  1-\delta,\\
%     \cos \left(2\pi Nr_{c,2}d\right) >  1-\delta,\quad\cos \left(2\pi r_{c,2}d\right) <  \delta,\\
%     \cos \left(2\pi Nr_{0,1}d\right) >  1-\delta,\quad\cos \left(2\pi r_{0,1}d\right) >  1-\delta,\\
%     \cos \left(2\pi Nr_{0,2}d\right) >  1-\delta,\quad\cos \left(2\pi r_{0,2}d\right) >  1-\delta.\\
% \end{cases}
% \end{equation}
By substituting \eqref{eqn_Lem1_eqn2} into \eqref{eqn_Lem1_eqn1} and letting $\epsilon\rightarrow0$, we can obtain \eqref{null}.
%\begin{equation}
    %\begin{cases}
        %\underset{r_{i,1}d\rightarrow0}{\lim}g_{i,1}(\mbf{T})=\underset{r_{i,1}d\rightarrow0}{\lim}g_{0,2}(\mbf{T})= N\\
        %\underset{2\pi Nr_{c,2}d\rightarrow0,\,\,2\pi r_{c,2}d\rightarrow\pi}{\lim}g_{c,2}(\mbf{T})=0
    %\end{cases}
%\end{equation}
%\begin{equation}
%g_{c,1}(\mbf{T})\rightarrow N,\,\,g_{0,1}(\mbf{T})\rightarrow N,\,\, g_{0,2}(\mbf{T})\rightarrow N,\,\, g_{c,2}(\mbf{T})\rightarrow 0.\nonumber
%\end{equation}
Moreover, as $d$ is a positive integer that is much greater than the wavelength-level antenna spacing in practice, the minimum antenna spacing constraints in \eqref{eqn_SRM} can be satisfied. This completes the proof.
\end{IEEEproof}

The equalities in \eqref{null} reveal that via MA position optimization, the confidential beam gain can be maximized at user 1 while being nulled at user 2. Moreover, the multicast beam gain can be maximized at both users 1 and 2. With Lemma 1, we proceed to show the optimality of $\mathbf{T}^{\star}$.
\begin{theorem}
The APV $\mathbf{T}^{\star}$ can result in a larger secrecy rate region achievable by any other APVs $\mbf{T}$, i.e., $R_0(\mbf{T}^{\star}) \ge R_0(\mathbf{T})$ and $R_c(\mbf{T}^{\star})\ge R_c(\mathbf{T})$.
\end{theorem}
\begin{IEEEproof}
For the APV $\mathbf{T}^{\star}$ and its associated beamforming designs $\tilde{\mbf{w}}_c(\mbf{T})$ and $\tilde{\mbf{w}}_0(\mbf{T})$ presented in Lemma 1, the achievable secrecy rate and multicast rate are given by
\begin{align}
&R_c(\mbf{T}^{\star})=\log_2\left(1+\frac{\tilde{P}_cN\left|\beta_1\right|^2}{\sigma^2}\right),\label{eqn_Th1_Rc}\\
&R_0(\mbf{T}^{\star})=\underset{k=1,2}{\min}R_{0,k}(\mbf{T}^{\star})\label{eqn_Th1_R0},
\end{align}
where $R_{0,1}(\mbf{T})=\log_2\left(1+\frac{\tilde{P}_0N\left|\beta_1\right|^2}{\sigma^2+\tilde{P}_cN\left|\beta_1\right|^2}\right),\label{eqn_Th1_R01}$
    and $R_{0,2}(\mbf{T})=\log_2\left(1+\frac{\tilde{P}_0N\left|\beta_2\right|^2}{\sigma^2}\right)\label{eqn_Th1_R02}$, and $\tilde{P}_c$ and $\tilde{P}_0$ denote the power allocation to the confidential and multicast messages, respectively. Then, by comparing \eqref{eqn_LoS_Rc}-\eqref{eqn_LoS_R0} with \eqref{eqn_Th1_Rc}-\eqref{eqn_Th1_R0}, if we set       
\begin{equation}\label{eqn_Th1_TxPw}
    \tilde{P}_c=P_c\frac{\left|\mbf{w}_c^H\mbf{a}(\mbf{T},\theta_1,\phi_1)\right|^2}{N},\quad \tilde{P}_0=P-\tilde{P}_c,
\end{equation}
and substitute \eqref{eqn_Th1_TxPw} into \eqref{eqn_Th1_Rc}-\eqref{eqn_Th1_R0}, we can always obtain $R_0(\mbf{T}^{\star}) \ge R_0(\mathbf{T}) $ and  $R_c(\mbf{T}^{\star})\ge R_c(\mathbf{T})$. 
\end{IEEEproof}

Notably, since the APV solution presented in Lemma 1 can yield a larger secrecy rate region compared to any other APVs, it should also outperform the time-sharing strategy. Theorem 1 also manifests the exceptional capability of MAs to configure signal transmission of different types, beyond the single-type signal transmission as studied in \cite{Y. Gao, G. Hu, Z. Cheng}.\vspace{-6pt}

\section{Proposed Solution to (P1)}
In this section, we aim to solve (P1) in the general case. To this end, we propose a two-layer optimization algorithm to decompose (P1) into two subproblems. The inner problem optimizes $\mathbf{w}_0$ and $\mathbf{w}_c$ for a given APV $\mathbf{T}$, while the outer problem optimizes the APV based on the optimal value of the inner problem. The outer and inner optimization problems are respectively given by
\begin{equation}
   \text{(P2-Outer)}\; \max_\mathbf{T}\; g^*(\mathbf{T}),\quad
    \text{s.t.}  \;{\text{\eqref{p1c},\eqref{p1d}}},\label{eqn_outer problem}
\end{equation}
and
\begingroup\makeatletter\def\f@size{9.2}\check@mathfonts
\def\maketag@@@#1{\hbox{\m@th\normalsize\normalfont#1}}%
\begin{align}
    \text{(P2-Inner)} &\; g^*(\mathbf{T}) =\max_{\mathbf{w}_0, \mathbf{w}_c}\log_2\left(\frac{\sigma^2 + |\mathbf{h}_1^H (\mathbf{T})\mathbf{w}_c |^2}{\sigma^2 + |\mathbf{h}_2^H (\mathbf{T})\mathbf{w}_c |^2}\right) \nonumber\\
    \text{s.t.} &\quad \min_{k=1, 2} \log_2\left(1 + \frac{|\mathbf{h}_k^H\left( \mathbf{T} \right) \mathbf{w}_0|^2 }{\sigma^2 + |\mathbf{h}_k^H\left( \mathbf{T} \right) \mathbf{w}_c |^2}\right) \geq r_{ms}, \nonumber\\
    & \quad |\mathbf{w}_0|^2 + |\mathbf{w}_c|^2 \leq P.\label{eqn_inner problem}
\end{align}\endgroup
Next, we employ the SDR to solve the inner problem, as it can yield a globally optimal solution to (P2-Inner).\vspace{-9pt}

\subsection{Inner-layer: Beamforming Optimization with Given $\mathbf{T}$}\label{innerProb}
Specifically, we let $\mathbf{Q}_0=\mathbf{w}_0\mathbf{w}_0^H\succeq {\bf{0}}$ and $\mathbf{Q}_c=\mathbf{w}_c\mathbf{w}_c^H\succeq {\bf{0}}$, with rank$(\mathbf{Q}_0)=\text{rank}(\mathbf{Q}_c)=1$. By further leveraging the monotonic property of the logarithm function, we can recast (P2-Inner) as
\begingroup\makeatletter\def\f@size{9.2}\check@mathfonts
\def\maketag@@@#1{\hbox{\m@th\normalsize\normalfont#1}}%
\begin{align}
    \text{(P3)} &\quad g^*(\mathbf{T}) =\max_{\mathbf{Q}_0\succeq {\bf{0}}, \mathbf{Q}_c\succeq {\bf{0}}}\frac{\sigma^2 + \mathbf{h}_1^H (\mathbf{T})\mathbf{Q}_c\mathbf{h}_1(\mathbf{T}) }{\sigma^2 + \mathbf{h}_2^H(\mathbf{T})\mathbf{Q}_c \mathbf{h}_2(\mathbf{T}) } \nonumber\\
    \text{s.t.} &\quad  \mathbf{h}_k^H(\mathbf{T})
    \mathbf{Q}_0 \mathbf{h}_k (\mathbf{T})- \tau_{ms}(\sigma^2 + \mathbf{h}_k^H(\mathbf{T}) \mathbf{Q}_c\mathbf{h}_k (\mathbf{T}) ) \geq 0, \nonumber\\
    &\quad k=1,2,\nonumber\\
    & \quad \text{Tr}(\mathbf{Q}_0 + \mathbf{Q}_c) \leq P,\; \text{rank}(\mathbf{Q}_0)=\text{rank}(\mathbf{Q}_c)=1.
\end{align}\endgroup

Although (P3) is still a non-convex optimization problem w.r.t. $\mathbf{Q}_0$ and $\mathbf{Q}_c$, we can relax the rank-one constraints in (P3) and introduce the Charnes-Cooper transformation, i.e.,
\begin{equation}\label{eqn_Charnes-Cooper}
\mathbf{Q}_c=\mathbf{Z}/\xi, \mathbf{Q}_0=\mathbf{\Gamma}/\xi, \xi \geq 0.
\end{equation}
Then, we can rewrite (P3) as
\begingroup\makeatletter\def\f@size{9.2}\check@mathfonts
\def\maketag@@@#1{\hbox{\m@th\normalsize\normalfont#1}}%
\begin{align}
     \max_{\mathbf{Z}\succeq {\bf{0}}, \mathbf{\Gamma}\succeq {\bf{0}}, \xi }&\;\xi + {\mathbf{h}_1^H( \mathbf{{T}}) \mathbf{Z} \mathbf{h}_1 (\mathbf{{T}})}/{\sigma^2} \nonumber\\
    \text{s.t.} \;&\xi + {\mathbf{h}_2^H( \mathbf{{T}}) \mathbf{Z} \mathbf{h}_2 (\mathbf{{T}})}/{\sigma^2} = 1, \nonumber\\
     &\mathbf{h}_k^H( \mathbf{{T}} ) \mathbf{\Gamma} \mathbf{h}_k (\mathbf{{T}}) \!-\! \tau_{ms}( \xi \sigma^2 + \mathbf{h}_k^H\left( \mathbf{{T}} \right) \mathbf{Z} \mathbf{h}_k (\mathbf{{T}})) \geq 0, \nonumber\\
     &k=1,2, \label{eqn_SDP}\\
     &\text{Tr}(\mathbf{Z}+\mathbf{\Gamma}) \leq P\xi.\nonumber
\end{align}\endgroup
Note that problem \eqref{eqn_SDP} is convex, which thus can be optimally solved through the interior-point algorithm.

Let $\mathbf{Z}^*$, $\mathbf{\Gamma}^*$ and $\xi^*$ denote the optimal solution to problem \eqref{eqn_SDP}. Then, it must hold that $\text{rank}^2(\mathbf{Z}^*)+\text{rank}^2(\mathbf{\Gamma}^*) \le 3$ for problem \eqref{eqn_SDP}\cite{W. Mei}, where the constant “3” denotes the total number of linear equalities and inequalities in problem \eqref{eqn_SDP}. As such, the optimal solutions to \eqref{eqn_SDP} satisfy $\text{rank}(\mathbf{Z}^*)=\text{rank}(\mbf{\Gamma}^*)=1$. Then, we can retrieve the optimal $\mathbf{Q}_0$ and $\mathbf{Q}_c$ based on \eqref{eqn_Charnes-Cooper} and then the optimal $\mathbf{w}_0$ and $\mathbf{w}_c$ via the singular value decomposition (SVD).\vspace{-6pt}
