\begin{example}[White noise on $\T^2$]\label{ex:SWN}
Consider space white noise on $\T^2$, which we realize as the random Fourier series 
%
\begin{equation}
\xi = \sum_{k\in(2\pi\Z)^2} e_k \hat\xi_k \, ,
\end{equation}
%
where $e_k(x)=e^{i k\cdot x}$ and $\hat\xi_k$ are independent (up to the usual restriction that the complex conjugate of $\hat\xi_k$ coincides with $\hat\xi_{-k}$)
complex-valued centered Gaussians with variance $1$. 
In this example $k$ is always assumed to be an element of $(2\pi\Z)^2$. 
Of course, $\xi$ is not smooth and thus does not satisfy the qualitative Assumption~\ref{ass:noise}~(i). 
This can be fixed by replacing $\xi$ by the smooth $\xi_\epsilon=\sum_{|k|\leq\epsilon^{-1}}e_k\hat\xi_k$. 
It is then easy to check that \eqref{eq:modelbound} holds for $\tau\in\{\noise,\xnoise\}$ for any $\alpha<1$ uniformly in $\epsilon>0$. 
The corresponding $\Pi[\lolly]$ is given by 
%
\begin{equation}
\Pi_{(t,x)}[\lolly;a](s,y)
= (s-t) \hat\xi_0
+ \sum_{0<|k|\leq\epsilon^{-1}} 
\Big( e_k(y) \frac{1-e^{-a|k|^2s}}{a|k|^2} 
- e_k(x) \frac{1-e^{-a|k|^2t}}{a|k|^2} \Big) \hat\xi_k \, .
\end{equation}
%
One can verify \eqref{eq:lollybound}, e.g.~for spatial increments and $\bar\epsilon>0$
%
\begin{align}
\E|\Pi_{(t,x)}[\lolly;a](t,y)|^2 
&= \sum_{0<|k|\leq\epsilon^{-1}} |e_k(x)-e_k(y)|^2 \Big(\frac{1-e^{-a|k|^2t}}{a|k|^2}\Big)^2 \\
&\lesssim \sum_{0<|k|\leq\epsilon^{-1}} \frac{|k|^{2-\bar\epsilon}|x-y|^{2-\bar\epsilon}}{a^2|k|^4} \, ,
\end{align}
%
where in the inequality we interpolated between $|e_k(x)-e_k(y)|\lesssim1$ and $|e_k(x)-e_k(y)|\lesssim|k||x-y|$. 
One can argue similarly for time increments and derivatives with respect to $a$, 
so that equivalence of moments together with Kolmogorov's continuity theorem yield for compact $\mathfrak{K}\subseteq\R\times\R^d$ and $\bar\epsilon>0$
%
\begin{equation}
\E\Big| \sup_{\x\neq\y\in\mathfrak{K}} \sup_{\bar a\in a(\mathrm{supp}\,\sigma)} \bar a^{1+\bar\epsilon} \frac{\Pi_{\x}[\lolly;\bar a](\y)}{\|\x-\y\|_\s^{1-\bar\epsilon}}
\Big|^p <\infty \, ,
\end{equation}
%
and thus almost surely \eqref{eq:lollybound}.

The counterterm $\cdumbeps^{a}(t)$ can be chosen as $t+\sum_{0<|k|\leq\epsilon^{-1}}(1-e^{-a|k|^2t})/(a|k|^2)$
such that $\Pi[\dumb]$ without recentering has vanishing expectation, 
where the time dependence of the counterterm follows from the zero initial condition of $\Pi[\dumb]$. 
With this choice one can show that $\Pi[\dumb]$ satisfies \eqref{eq:modelbound}; 
we refer the reader to \cite[Section~3.3.1]{dLF24} for further details. 
Furthermore, choosing $C_\epsilon^a=\sum_{0<|k|\leq\epsilon^{-1}}(a|k|^2)^{-1}$, 
we have for $v\in\R$ 
%
\begin{align}
|\sigma'(v)\sigma(v) (C_\epsilon^{a(v)} - \cdumbeps^{a(v)}(t)) |
&\leq |\sigma'(v)\sigma(v)| \Big( t + \sum_{0<|k|\leq\epsilon^{-1}}\frac{e^{-a(v)|k|^2t}}{a(v)|k|^2} \Big) \\
&\leq |\sigma'(v)\sigma(v)| \Big(t+\sum_{0<|k|\leq\epsilon^{-1}}\frac{1}{a(v)^{3/2}|k|^3\sqrt{t}} \Big) \, ,
\end{align}
%
where in the second inequality we used $e^{-x}\leq x^{-1/2}$.
Using Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} the above is estimated by $t + \sum_{0<|k|\leq\epsilon^{-1}}(|k|^3\sqrt{t})^{-1}$, 
which is integrable in $t$ from $0$ to $T$ and hence \eqref{eq:counterterm_time_independent} is satisfied. 

Similarly $\ccherryeps^a(t)$ can be chosen as $\sum_{0<|k|\leq\epsilon^{-1}} (1-e^{-a|k|^2t})^2/(a^2|k|^2)$ such that $\Pi[\derivativecherry]$ has vanishing expectation.
Then $\Pi[\derivativecherry]$ satisfies \eqref{eq:modelbound}, and
%
\begin{align}
\cdumbeps^{a(v)}(t)-a(v)\ccherryeps^{a(v)}(t) 
&= t + \sum_{0<|k|\leq\epsilon^{-1}} \Big(
\frac{1-e^{-a(v)|k|^2t}}{a(v)|k|^2}
- a(u) \frac{(1-e^{-a(v)|k|^2t})^2}{a(v)^2|k|^2} \Big) \\
&= t + \sum_{0<|k|\leq\epsilon^{-1}} 
\frac{e^{-a(v)|k|^2t}(1-e^{-a(v)|k|^2t})}{a(v)|k|^2} \\
&\leq t + \sum_{0<|k|\leq\epsilon^{-1}} 
\frac{e^{-a(v)|k|^2t}}{a(v)|k|^2} \, ,
\end{align}
%
and we conclude as for $C_\epsilon^a - \cdumbeps^a(t)$ that \eqref{eq:counterterm_dumb_cherry} holds. 

Altogether Assumption~\ref{ass:noise} is satisfied for $\xi_\epsilon$, and the main result can be applied to obtain a priori estimates which are uniform in $\epsilon>0$. 
\hfill /\!\!/
\end{example}

Actually, the assumed estimates \eqref{eq:modelbound} and \eqref{eq:lollybound} are a worst case scenario in terms of blowup in $\bar a$. 
This is easiest seen by considering noise which is rough in time and constant in space, e.g.~temporal white noise. In this case, $\Pi_{(t,x)}[\lolly;\bar a](s,y)=\int_t^s dr \, \xi(r)$, 
which is even independent of $\bar a$, i.e.~$\mathfrak{e}(\tau)$ could be replaced by $0$ in \eqref{eq:lollybound}. 
The following example considers a situation somewhat in between temporal noise and spatial noise as considered in the previous example, 
where $\mathfrak{e}(\tau)$ can be replaced by $\mathfrak{e}(\tau)/2$. 
Unfortunately, this improved estimate does not allow to weaken the assumption $N\geq M+1$, 
which is in particular made for equation \eqref{eq:IV} to hold, 
which in turn is independent of $\mathfrak{e(\tau)}$. 
As already mentioned in Remark~\ref{rem:restriction_N}, 
a more careful analysis might allow to take advantage of an improved \eqref{eq:modelbound} to relax the assumption on $N$. 

\begin{example}[Spatially coloured noise]\label{ex:CN}
Consider $\xi$ on $\R\times\T^d$ which is white in time and sufficiently coloured in space realized via
%
\begin{equation}
\xi = \sum_{k\in(2\pi\Z)^d} \sqrt{c_k} e_k dB_k \, ,
\end{equation}
%
where in analogy to the previous example $k$ will always be assumed to belong to $(2\pi\Z)^d$ and $e_k(x)=e^{ik\cdot x}$, and where 
%
\begin{equation}
c_k = \frac{1}{(1+|k|)^{d-2+2\alpha'}}
\end{equation}
%
for $\alpha'\in(2/3,1)$, and $B_k(t)$ are independent (again up to $\bar{B}_k=B_{-k}$)
complex-valued Brownian motions. 
Here a Fourier cutoff is not enough to obtain a smooth approximation of $\xi$ due to the roughness of $dB_k$ in time. 
Hence we also fix a compactly supported $\rho\colon\R\to[0,1]$ with $\int\rho=1$ which is even. Denoting $\rho_\epsilon=\epsilon^{-1}\rho(\cdot/\epsilon)$ and $B^{(\epsilon)} = \rho_\epsilon*B$ we approximate $\xi$ by the smooth $\xi_\epsilon=\sum_{|k|\leq\epsilon^{-1}} \sqrt{c_k} e_k dB^{(\epsilon)}_k$. 
Then \eqref{eq:modelbound} holds for $\tau\in\{\noise,\xnoise\}$ for any $\alpha<\alpha'$ uniformly in $\epsilon>0$. 
The corresponding $\Pi[\lolly]$ is given by 
%
\begin{equation}
\begin{split}
&\Pi_{(t,x)}[\lolly;a](s,y) \\
&= \sum_{|k|\leq\epsilon^{-1}}\sqrt{c_k} \Big( 
e_k(y) \int_0^s e^{-a|k|^2(s-r)} dB^{(\epsilon)}_k(r)
- e_k(x) \int_0^t e^{-a|k|^2(t-r)} dB^{(\epsilon)}_k(r) \Big) \, .
\end{split}
\end{equation}
%
For spatial increments 
%
\begin{align}
&\E|\Pi_{(t,x)}[\lolly;a](t,y)|^2 \\
&= \sum_{|k|\leq\epsilon^{-1}} c_k |e_k(y)-e_k(x)|^2 
\int_0^t dr \int_0^t dr'\, e^{-a|k|^2(t-r)} e^{-a|k|^2(t-r')} \rho_\epsilon*\rho_\epsilon(r-r') \\
&\leq \sum_{|k|\leq\epsilon^{-1}} c_k |e_k(y)-e_k(x)|^2 
\int_0^t dr \, e^{-2a|k|^2(t-r)}
\int_\R dr \, |\rho_\epsilon*\rho_\epsilon(r)| \\
&= \sum_{0<|k|\leq\epsilon^{-1}} c_k |e_k(y)-e_k(x)|^2 \, 
\frac{1-e^{-2a|k|^2t}}{2a|k|^2} \, ,
\end{align}
%
where in the inequality we have used Young's inequality for convolutions in the form of $|\int\int f(r)g(r')h(r-r')| \leq \|f\|_{L^2} \|g\|_{L^2} \|h\|_{L^1}$. 
Interpolating between $|e_k(x)-e_k(y)|\lesssim1$ and $|e_k(x)-e_k(y)|\lesssim|k||x-y|$ the above right hand side is bounded by 
%
\begin{equation}
\sum_{0<|k|\leq\epsilon^{-1}} |x-y|^{2\alpha} a^{-1} |k|^{-d-2\alpha'+2\alpha} \, ,
\end{equation}
%
which is estimated uniformly in $\epsilon>0$ by $|x-y|^{2\alpha} a^{-1}$ provided $\alpha<\alpha'$. 
One can proceed similarly with time increments and derivatives with respect to $a$, which together with equivalence of moments and Kolmogorov's continuity theorem proves \eqref{eq:lollybound} as in Example~\ref{ex:SWN}, but with $\mathfrak{e}(\lolly)$ replaced by $\mathfrak{e}(\lolly)/2$.

The counterterm $\cdumbeps^a(t)$ can be chosen as $\sum_{|k|\leq\epsilon^{-1}} c_k \int_0^t dr\,e^{-a|k|^2r}\rho_\epsilon*\rho_\epsilon(r)$ 
such that $\Pi[\dumb]$ without recentering has vanishing expectation.
If we ignored the qualitative smoothness assumption on $\xi$ and worked with $dB_k$ without mollification, 
we could construct $\Pi[\dumb]$ as It\^o integral, and the corresponding counterterm would be zero. 
Our choice of counterterm can therefore be seen to be the It\^o-Stratonovich correction.
In any case, $\Pi[\dumb]$ satisfies \eqref{eq:modelbound} for any $\alpha<\alpha'$; 
we refer again to \cite[Section~3.2.2]{dLF24} for details. 
Choosing $C_\epsilon^a= \sum_{|k|\leq\epsilon^{-1}} c_k \int_0^\infty dr\, e^{-a|k|^2r}\rho_\epsilon*\rho_\epsilon(r)$ we have for $v\in\R$
%
\begin{align}
|\sigma'(v)\sigma(v) (C_\epsilon^{a(v)}-\cdumbeps^{a(v)}(t))|
&= |\sigma'(v)\sigma(v)| \sum_{|k|\leq\epsilon^{-1}} c_k \int_t^\infty dr\, e^{-a(v)|k|^2r}\rho_\epsilon*\rho_\epsilon(r) \\
&\leq |\sigma'(v)\sigma(v)| \sum_{|k|\leq\epsilon^{-1}} c_k e^{-a(v)|k|^2t} \, .
\end{align}
%
Using $e^{-x}\leq x^{-1/2}$ and the definition of $c_k$ this is bounded by 
$|\sigma'(v)\sigma(v)|(1+\sum_{0<|k|\leq\epsilon^{-1}} |k|^{-d+1-2\alpha'} a(v)^{-1/2} t^{-1/2})$, 
which by Assumption~\ref{ass:nonlinearities}~(ii), \eqref{eq:restrictionM}, and $\alpha'>1/2$ is bounded uniformly in $\epsilon>0$ by $1+t^{-1/2}$. Since the latter is integrable in $t$ from $0$ to $T$ this verifies \eqref{eq:counterterm_time_independent}.

Similarly we choose $\ccherryeps^{a}(t)=\sum_{|k|\leq\epsilon^{-1}} c_k |k|^2 \int_0^tdr\int_0^tdr'\,e^{-a|k|^2r}e^{-a|k|^2r'}\rho_\epsilon*\rho_\epsilon(r-r')$ 
so that $\Pi[\derivativecherry]$ satisfies \eqref{eq:modelbound} for any $\alpha<\alpha'$, and 
%
\begin{align}
&\cdumbeps^{a(v)}(t) - a(v)\ccherryeps^{a(v)}(t) \\
&= \sum_{|k|\leq\epsilon^{-1}} \! c_k\! \int_0^t \! dr\, e^{-a(v)|k|^2r}\Big(
\rho_\epsilon\!*\!\rho_\epsilon(r)
- a(v)|k|^2\! \int_0^t \! dr'\, e^{-a(v)|k|^2r'}\rho_\epsilon\!*\!\rho_\epsilon(r-r')\Big) \, .
\end{align}
%
By integration by parts we observe that this equals
%
\begin{equation}
\sum_{|k|\leq\epsilon^{-1}} \! c_k \! \int_0^t\! dr\, e^{-a(v)|k|^2r}\Big(
e^{-a(v)|k|^2t}\rho_\epsilon*\rho_\epsilon(r-t) - \int_0^t \! dr' e^{-a(v)|k|^2r'}\tfrac{d}{dr'}\rho_\epsilon*\rho_\epsilon(r-r') \Big) .
\end{equation}
%
The last summand vanishes by symmetry (recall that $\rho$ and hence $\rho_\epsilon*\rho_\epsilon$ is even and its derivative thus odd), so that
%
\begin{equation}
|\cdumbeps^{a(v)}(t) - a(v)\ccherryeps^{a(v)}(t) |
\leq \sum_{|k|\leq\epsilon^{-1}} c_k e^{-a(v)|k|^2t} \, ,
\end{equation}
%
and we conclude as for $C_\epsilon^a-\cdumbeps^a(t)$ that \eqref{eq:counterterm_dumb_cherry} holds. 

Altogether Assumption~\ref{ass:noise} is satisfied for $\xi_\epsilon$ and with $\mathfrak{e}(\tau)$ replaced by $\mathfrak{e}(\tau)/2$, 
and the main result can be applied to obtain a priori estimates which are uniform in $\epsilon>0$. 
\hfill /\!\!/
\end{example}

