\subsection{Notation}\label{sec:notation}

$\mathbb{N}$ denotes the natural numbers including zero,
$d$ is the space dimension. 
For $k\in\N^d$ and $x\in\R^d$ we write $x^k=x_1^{k_1}\cdots x_d^{k_d}$ and $k!=k_1!\cdots k_d!$. 
For $k\in\N^d$ we write $|k|_1$ for the $\ell^1$ norm $k_1+\cdots+k_d$. 
The Euclidean norm in any dimension is denoted by $|\cdot|$. 
Space-time points are always denoted by $\x=(t,x),\,\y=(s,y),\,\z=(r,z)\in\R\times\R^d$.
Distance of space-time points is measured with respect to the parabolic Carnot-Carath\'eodory metric $\|(t,x)\|_\s\coloneqq\sqrt{|t|+x_1^2+\cdots+x_d^2}$, 
and the effective dimension of space-time equipped with this metric is $D\coloneqq d+2$. 
For $\lambda>0$ we write $\S^\lambda$ for the parabolic rescaling 
$\S^\lambda(t,x)\coloneqq(\lambda^2t, \lambda x)$, 
and note that $\|\S^\lambda(t,x)\|_\s = \lambda \|(t,x)\|_\s$. 
For $\bar{a}>0$ we write $\D^{\bar a}$ for the anisotropic dilation $\D^{\bar{a}}(t,x)\coloneqq(\bar{a}t,x)$. 
Recentered and rescaled space-time functions $\varphi$ are denoted by 
$\varphi_\x^\lambda(\y)=\lambda^{-D}\varphi(\S^\lambda(\y-\x))$.
$\mathcal{B}$ is the set of smooth functions supported in the (parabolic) unit ball with 
all its derivatives up to order $2$ bounded by $1$. 
Unless stated otherwise, $\|\cdot\|_{L^p}$ is considered on $[0,T]\times\T^d$, 
and we simply write $\|\cdot\|_\infty$ to denote $\|\cdot\|_{L^\infty(\R)}$. 
For $\alpha\in(0,1)$ 
%
\begin{equation}
[u]_{B_{1,\infty}^\alpha} 
= \sup_{\|\y\|_\s\leq R} \|\y\|_\s^{-\alpha} \int_{D_\y} d\x\,|u(\x+\y)-u(\x)|\, ,
\end{equation}
%
where $D_\y=\{\x\in [0,T]\times\T^d\,|\,\x+\y\in [0,T]\times\T^d\}$, 
and $[f(\mathcal{U})]_{B_{1,\infty}^\beta}$ is for $\beta\in(1,2)$ given by the supremum over $\|\y\|_\s\leq R$ of
%
\begin{equation}
%\sup_{\|\y\|_\s\leq R} 
\|\y\|_\s^{-\beta}\! \int_{D_{\y}} d\x \, 
\big| f(u(\x+\y)) - f(u(\x)) - f'(u(\x))\big(\sigma(u(\x))\Pi_{\x}[\lolly;\x](\x+\y) + \nu(\x)\cdot y\big) \big| \, ,
\end{equation}
%
where $\Pi_\x[\lolly;\bar \x]$ is short for $\Pi_\x[\lolly;a(u(\bar \x))]$ defined in \eqref{eq:lolly} and $\nu$ is defined in \eqref{eq:gubinelliderivative}. 
The $L^2$ inner product on $\R\times\R^d$ is denoted by $\langle\cdot,\cdot\rangle$, 
and for testing on $[0,\infty)\times\R^d$ we also write $F(\varphi)=\int_{[0,\infty)\times\R^d} d\x \,F(\x)\varphi(\x)$.
By $\lesssim$ we understand $\leq C$ for a generic constant $C$ unless stated otherwise, 
and the implicit constant in $\lesssimdata$ depends on 
$d$, 
$\alpha$, 
$\beta$, 
$M$, 
$p$, 
$\{[\tau]_{|\tau|}\}_{\tau\in\mathcal{T}}$, 
and $C$ from Assumptions~\ref{ass:nonlinearities}, \ref{ass:noise}, and \ref{ass:initial}.

