\section{Splitting into small and large velocities}\label{sec:splitting}

To prove Theorem~\ref{thm:modelledness} we treat the contributions to $u=\int dv\, \chi$ 
from small and large velocities separately. 
In the proof it will be convenient to avoid sharp cutoffs. 
We thus fix a smooth 
$\varphi^>\colon[0,\infty)\to[0,1]$ which vanishes on $[0,1]$ and equals $1$ on $[2,\infty)$, 
and we denote $\varphi^<\coloneqq 1-\varphi^>$.
Then for $\delta>0$ we decompose
%
\begin{equation}\label{eq:splitu}
u(t,x)=u^<(t,x)+u^>(t,x) 
\coloneqq 
\int_\R dv\, \varphi^<(\tfrac{a(v)}{\delta}) \chi(t,x,v) 
+ \int_\R dv\, \varphi^>(\tfrac{a(v)}{\delta}) \chi(t,x,v) \, ,
\end{equation}
%
and estimate $u^<$ and $u^>$ separately. 
We start with the former, which is estimated only in $L^1$ but with good decay as $\delta\to0$. 

\begin{proposition}[Small velocities]\label{prop:u<}
Under the assumption of Theorem~\ref{thm:main} and for $T,\delta>0$ it holds
%
\begin{equation}
\int_{[0,T]\times\T^d} d\x \, |u^<(\x)| \lesssim T \, \delta^{1/(M-1)} \, ,
\end{equation}
%
where $\lesssim$ depends on the constant $C$ of Assumption~\ref{ass:nonlinearities}.
\end{proposition}

\begin{proof}
By definition $0\leq\varphi^< \leq\1_{[0,2]}$ and $|\chi|\leq1$, hence
%
\begin{equation}
\int_{[0,T]\times\T^d} d\x \, | u^<(\x) | 
= \int_{[0,T]\times\T^d} d\x \Big| \int_\R dv \, \varphi^<(\tfrac{a(v)}{\delta}) \chi(\x,v) \Big| 
\leq T \int_\R dv\, \1_{[0,2]}(\tfrac{a(v)}{\delta}) \, .
\end{equation}
%
We conclude by noting that \eqref{eq:alower} implies $|v|\lesssim a(v)^{1/(M-1)}$.
\end{proof}

To prove Theorem~\ref{thm:modelledness} we shall also make use of the following simple lemma. 

\begin{lemma}\label{lem:Pi<}
Let $\Pi_\x^<[\lolly;\bar a](\y) \coloneqq \varphi^<(\bar a/\delta) \Pi_\x[\lolly;\bar a](\y)$ for $\delta>0$, and let $R,T>0$. 
Then under the assumption of Theorem~\ref{thm:main} it holds for $\|\y\|_\s\leq R$
%
\begin{equation}
\int_{D_\y} d\x \, |\sigma(u(\x)) \Pi_\x^<[\lolly;\x](\x+\y)|
\lesssim [\lolly]_\alpha \|\y\|_\s^\alpha T\, \delta^{1/(M-1)} \, ,
\end{equation}
%
where $\lesssim$ depends on the constant $C$ of Assumption~\ref{ass:nonlinearities}.
\end{lemma}

\begin{proof}
The model estimate \eqref{eq:lollybound} yields 
%
\begin{align}
\int_{D_\y} d\x \, |\sigma(u(\x)) \Pi_\x^<[\lolly;\x](\x+\y)|
&\leq [\lolly]_\alpha \|\y\|_\s^\alpha \int_{D_\y} d\x \, \big|\tfrac{\sigma(u(\x))}{a(u(\x))^{\mathfrak{e}(\lollysmall)}}\big| \, \varphi^<(\tfrac{a(u(\x))}{\delta}) \\
&\lesssim [\lolly]_\alpha \|\y\|_\s^\alpha \int_{D_\y} d\x \, |u(\x)| \, \varphi^<(\tfrac{a(u(\x))}{\delta}) \, ,
\end{align}
%
where in the second inequality we used that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
% ($N-(M-1)\geq1$)
%
\begin{equation}
\Big|\frac{\sigma(v)}{a(v)^{\mathfrak{e}(\lollysmall)}}\Big|\lesssim |v| \, .
\tag{I}\label{eq:I}
\end{equation}
%
Using $0\leq\varphi^< \leq\1_{[0,2]}$ and noting that \eqref{eq:alower} implies $|u(\x)|\lesssim a(u(\x))^{1/(M-1)}$, we conclude together with $|D_\y|\leq T$.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We turn to the estimate of $u^>$.
The main result of this section is modelledness of $u^>$ to order $2\alpha$ which is deteriorating as $\delta\to0$. 
To formulate this modelledness we introduce
%
\begin{equation}
\Pi_\x^>[\lolly;\bar{a}](\y) 
\coloneqq \varphi^>(\tfrac{\bar{a}}{\delta}) \Pi_\x[\lolly;\bar{a}](\y) \, ,
\end{equation}
%
and 
%
\begin{equation}
\nu^>(\x)\coloneqq \nabla_z\big(u^>(\z)-u^>(\x)-\sigma(u(\x))\Pi_\x^>[\lolly;\x](\z)\big)_{|\z=\x} \, .
\end{equation}
%
With this notation we have the following proposition. 

\begin{proposition}[Large velocities]\label{prop:u>}
Under the assumption of Theorem~\ref{thm:main} and for $\beta\in(2-\alpha,2\alpha)$, 
$\epsilon>0$, 
dyadic\footnote{i.e.~of the form $2^{-n}$ for $n\in\Z$} $\delta\in(0,1)$, and $0<R,T\leq1$ it holds for $\|\y\|_\s\leq R$
%
\begin{align}\label{eq:modelledness_u>}
&\int_{D_\y} d\x\,
\big|u^>(\x+\y)-u^>(\x)-\sigma(u(\x))\Pi_\x^>[\lolly;a(u(\x))](\x+\y)-\nu^>(\x)\cdot y \big| \\
&\lesssimdata \|\y\|_\s^{2\alpha} \delta^{-\alpha-\epsilon} 
\big(1+(R+T)^{1-\alpha} [\mathcal{U}]_{B_{1,\infty}^\beta} \big) \, .
\end{align}
%
The implicit constant in $\lesssimdata$ depends on $\beta$, $\epsilon$, and the data as in Theorem~\ref{thm:main}.
The best constant (implicit in $\lesssimdata$) is denoted by $[\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}}$.
\end{proposition}
\noindent
The remainder of this section is dedicated to the proof of Proposition~\ref{prop:u>}, 
which is finally given in Section~\ref{sec:proof_prop:u>}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Mild formulation for large velocities}
\label{sec:mild}

To prove Proposition~\ref{prop:u>} we appeal to the mild formulation of \eqref{eq:kinetic}
to rewrite 
%
\begin{align}
u^>(t,x) 
&= \int_\R dv\, \varphi^>(\tfrac{a(v)}{\delta}) \chi(t,x,v) \\
&= \int_\R dv\, \varphi^>(\tfrac{a(v)}{\delta}) e^{t a(v)\Delta} \chi(0,x,v) \\
&\,+ \int_0^t ds\, \Big(e^{(t-s)a(v)\Delta} \varphi^>(\tfrac{a(v)}{\delta})
\big(\sigma(v)\xi(s,x) - \sigma'(v)\sigma(v)C^{a(v)}\big) \Big)_{|v=u(s,x)}\\
&\,+ \int_\R dv\int_0^t ds \, e^{(t-s)a(v)\Delta} \varphi^>(\tfrac{a(v)}{\delta}) \, \partial_v \big(\delta_{u(s,x)}(v) a(u(s,x))|\nabla u(s,x)|^2 \big) \, ,
\end{align}
%
where 
%
\begin{equation}
\chi(0,x,v) 
= \1_{(-\infty,u_0(x))}(v) - \1_{(-\infty,0)}(v) \, .
\end{equation}
%
We rewrite this mild formulation in terms of the dilated heat kernel $\Psi$ defined in \eqref{eq:dilatedheatkernel} 
%
\begin{align}
&u^>(\x) \\
&=\int_{\R} dv \, \varphi^>(\tfrac{a(v)}{\delta}) 
\int_{\R^d} dz\, \Psi\big(a(v),t,x-z\big) \chi(0,z,v) \\
&\,+\int_{(0,\infty)\times\R^d}\! d\z \, \varphi^>(\tfrac{a(u(\z))}{\delta}) \Psi\big(a(u(\z)),\x-\z\big) 
\Big(\sigma(u(\z))\xi(\z) - (\sigma'\sigma)(u(\z))C^{a(u(\z))} \Big) \\
&\,- \int_{(0,\infty)\times\R^d}\! d\z\, 
\partial_{v} \big( \varphi^>(\tfrac{a(v)}{\delta}) \Psi(a(v),\x-\z) \big)_{|v=u(\z)} 
a(u(\z)) |\nabla u(\z)|^2 \, . 
\end{align}
%
As discussed in Section~\ref{sec:strategy}, this right hand side contains additional singular products. 
Crucially, both singular terms need the same (up to an integrable blowup) counterterm 
with opposite signs which we include now: 
%
\begin{align}
&u^>(\x) \\
&=\int_\R dv\, \varphi^>(\tfrac{a(v)}{\delta}) 
\int_{\R^d} dz \, \Psi(a(v),t,x-z\big) \chi(0,z,v) \\
&\,+\int_{(0,\infty)\times\R^d} d\z 
\Big[\varphi^>(\tfrac{a(u(\z))}{\delta}) \Psi\big(a(u(\z)),\x-\z\big) \sigma(u(\z)) \xi(\z) \\
&\hphantom{\coloneqq\int_{(0,\infty)\times\R^d}d\z}- \partial_v\Big( \varphi^>(\tfrac{a(v)}{\delta}) \Psi(a(v),\x-\z) \sigma(v) \Big)_{|v=u(\z)}
\sigma(u(\z)) \cdumb^{a(u(\z))}(r) \Big] \\
&\,-\! \int_{(0,\infty)\times\R^d} \! d\z 
\Big[ \partial_v \big( \varphi^>(\tfrac{a(v)}{\delta}) \Psi(a(v),\x\!-\!\z) \big)
a(v) \big( |\nabla u(\z)|^2 \!-\! \sigma^2(v) \ccherry^{a(v)}(r) \big) \Big]_{|v=u(\z)}  \\
&\,+\! \int_{(0,\infty)\times\R^d}\! d\z \Big[\partial_v \big( \varphi^>(\tfrac{a(v)}{\delta}) \Psi(a(v),\x\!-\!\z) \big) \sigma^2(v) \big( \cdumb^{a(v)}(r) \!-\! a(v) \ccherry^{a(v)}(r)\big) \Big]_{|v=u(\z)}\\
&\,+\! \int_{(0,\infty)\times\R^d} \! d\z \, \varphi^>(\tfrac{a(u(\z))}{\delta}) \Psi(a(u(\z)),\x\!-\!\z) (\sigma'\sigma)(u(\z)) \Big( \cdumb^{a(u(\z))}(r)-C^{a(u(\z))}\Big) \, .
\end{align}
%

In the proof it will be convenient to decompose $\varphi^>$ further into dyadic blocks.
We thus fix a smooth $\varphi:\R\to[0,1]$ with $\mathrm{supp}\,\varphi\subseteq[\tfrac{1}{2},2]$ such that $\sum_{q\in\Z} \varphi(2^q t)=1$ for all $t>0$. 
Choosing $\varphi^>\coloneqq \sum_{q<0} \varphi(2^q \cdot)$ we obtain for dyadic $\delta\in(0,1)$ the decomposition 
%
\begin{equation}\label{eq:decompose_phi>}
\varphi^>(\tfrac{a(v)}{\delta}) = \sum_{q\colon \delta<2^{-q}} \varphi(2^q a(v)) \, .
\end{equation}
%
Denoting 
%
\begin{equation}\label{eq:Psi_q}
\Psi_q(\bar{a},\x)\coloneqq \varphi(2^q\bar{a})\Psi(\bar{a},\x) \, ,
\end{equation}
%
and 
%
\begin{align}
u_0^q(\x) &\coloneqq 
\int_\R dv \int_{\R^d} dz \, \Psi_q\big(a(v),t,x-z\big) \chi(0,z,v) \, , \\
%
u_1^q(\x) &\coloneqq
\int_{(0,\infty)\times\R^d} d\z \Big[ \Psi_q\big(a(u(\z)),\x-\z\big) \sigma(u(\z)) \xi(\z) \\ 
&\hphantom{\coloneqq\int_{(0,\infty)\times\R^d}d\z}- 
\partial_v\Big( \Psi_q\big(a(v),\x-\z\big) \sigma(v) \Big)_{|v=u(\z)} 
\sigma(u(\z)) \cdumb^{a(u(\z))}(r) \Big] \, , \\
%
u_2^q(\x) &\coloneqq
\int_{(0,\infty)\times\R^d} d\z 
\Big[ \partial_v \Psi_q\big(a(v),\x-\z\big)
a(v)\big( |\nabla u(\z)|^2 - \sigma^2(v) \ccherry^{a(v)}(r) \big) \Big]_{|v=u(\z)} \, , \\
%
u_3^q(\x) &\coloneqq
\int_{(0,\infty)\times\R^d} d\z \, 
\Big[ \partial_v \Psi_q\big(a(v),\x-\z\big)
\sigma^2(v) \big( \cdumb^{a(v)}(r) - a(v) \ccherry^{a(v)}(r) \big) \Big]_{|v=u(\z)} \\
&\,+\int_{(0,\infty)\times\R^d} d\z \, 
\Psi_q\big(a(u(\z)),\x-\z\big)
(\sigma'\sigma)(u(\z)) \big( \cdumb^{a(u(\z))}(r) - C^{a(u(\z))} \big) \, , 
\end{align}
%
we obtain for $u^>$ the decomposition 
%
\begin{equation}
u^> = \sum_{q\colon\delta<2^{-q}} \big(u^q_0 + u^q_1 - u^q_2 + u^q_3\big)\, .
\end{equation}
%
Analogously we can decompose 
%
\begin{align}
\Pi^>_\x[\lolly;\bar{a}](\y)
&\,= \sum_{q\colon \delta<2^{-q}} \Pi_\x^q[\lolly;\bar{a}](\y) \\
&\coloneqq \sum_{q\colon \delta<2^{-q}} 
\int_{(0,\infty)\times\R^d} d\z\,\Big(\Psi_q\big(\bar{a},\y-\z\big)-\Psi_q\big(\bar{a},\x-\z\big)\Big)\xi(\z) \, .
\end{align}
%
To prove Proposition~\ref{prop:u>} we thus have to estimate the $L^1_\x(D_{\y})$-norm of 
%
\begin{align}
&u_0^q(\x+\y) - u_0^q(\x) - \nabla u_0^q(\x)\cdot y \\
&+u_1^q(\x\!+\!\y) \!-\! u_1^q(\x) \!-\! \sigma(u(\x)) \Pi_\x^q[\lolly;\x](\x\!+\!\y) \!-\! \big(\nabla u_1^q(\x) \!-\! \sigma(u(\x)) \nabla\Pi_\x^q[\lolly;\x](\x) \big) \!\cdot\! y \\
&- \big( u_2^q(\x+\y) - u_2^q(\x) - \nabla u_2^q(\x) \cdot y \big) 
+ u_3^q(\x+\y) - u_3^q(\x) - \nabla u_3^q(\x) \cdot y  \, . 
\end{align}
%
We break up the contributions from $u_0,\dots,u_3$ by the triangle inequality and estimate them separately 
in the four following propositions.

%
\begin{proposition}\label{prop:u0}
Let $u_0\in L^1(\T^d)$, $T>0$, $\y\in\R\times\R^d$, and $\delta\in(0,1)$. 
Then 
%
\begin{equation}
\sum_{q\colon \delta<2^{-q}} \int_{D_{\y}} d\x\,
\Big|u_0^q(\x+\y)-u_0^q(\x)-\nabla u_0^q(\x) \cdot y \Big|
\lesssim \|\y\|_\s^{2\alpha} \, \delta^{-\alpha} T^{1-\alpha} \|u_0\|_{L_1(\T^d)} \, .
\end{equation}
%
\end{proposition}
%
\noindent
The proof of Proposition~\ref{prop:u0} is given in Section~\ref{sec:initial}.

In the following two propositions it is convenient to consider a smooth $\Theta\colon\R\to\R$ which is monotone increasing, coincides with the identity on the support of $\sigma$, and is constant outside a neighbourhood of the support of $\sigma$, so that in particular 
%
\begin{equation}\label{eq:Theta}
f(u)\sigma(u)=f(\Theta(u))\sigma(\Theta(u)) \quad\textnormal{and}\quad 
\sigma(u)=\Theta'(u)\sigma(u) \, .
\end{equation}
%
This will ensure in the following that $\nu$ is only evaluated where $|u|\lesssim1$, so that its $L^2$ norm can be estimated by $[\mathcal{U}]_{B_{1,\infty}^\beta}$, see Lemma~\ref{lem:absorb}~\ref{it:nu^2_0}.
%
\begin{proposition}\label{prop:u1}
Let the assumption of Theorem~\ref{thm:main} hold.
Furthermore let $0<R,T\leq1$, $\beta\in(2-\alpha,2\alpha]$, and $\delta\in(0,1)$. 
Then for $\|\y\|_\s\leq R$
%
\begin{align}
\sum_{q\colon\delta<2^{-q}} \int_{D_{\y}} d\x\,
\Big|u_1^q(\x+\y)&-u_1^q(\x)-\sigma(u(\x))\Pi_\x^q[\lolly;\x](\x+\y) \\
&\!\!\!\!- \big(\nabla u_1^q(\x) - \sigma(u(\x)) \nabla\Pi_\x^q[\lolly;\x](\x) \big) \cdot y \Big|
\lesssim \|\y\|_\s^{2\alpha} \delta^{-\alpha} \, C_1 \, ,
\end{align}
%
where $\lesssim$ depends on $\beta$ and $C$ of Assumption~\ref{ass:nonlinearities}, and where $C_1$ is given by 
%
\begin{align}
C_1&=
[\dumb]_{2\alpha-2} T \\
&\,+ R^{1-\alpha} [\xnoise]_{\alpha-1} \|\Theta'(u)\nu\|_{L^1} \\
%
&\,+ R^{1-\alpha} 
[\xi]_{\alpha-2} 
\Big( [\Theta(\mathcal{U})]_{B^{\beta}_{1,\infty}} 
+ [\lolly]_\alpha^2 T
+ [\lolly]_\alpha \|\Theta'(u)\nu\|_{L^1} 
+ \|\Theta'(u)\nu\|_{L^2}^2 \Big) \\
%
&\,+ R^{1-\alpha}  
[\dumb]_{2\alpha-2} [\Theta(u)]_{B^\alpha_{1,\infty}} \\
%
&\,+ R^{1-\alpha} 
[\xnoise]_{\alpha-1} 
\Big( 
[\Theta(u)]_{B^\alpha_{1,\infty}}^{1/2} \|\Theta'(u)\nu\|_{L^2} 
+ [\Theta'(u)\nu]_{B^{\beta-1}_{1,\infty}} \Big)
%
\, ,
\end{align}
%
with $[\Theta(\mathcal{U})]_{B_{1,\infty}^\beta}$ defined as the supremum over $\|\y\|_\s\leq R$ of
%
\begin{equation}
%\sup_{\|\y\|_\s\leq R} 
\|\y\|_\s^{-\beta}\! \int_{D_{\y}} d\x \, 
\big| \Theta(u(\x+\y)) - \Theta(u(\x)) - \Theta'(u(\x))\big(\sigma(u(\x))\Pi_{\x}[\lolly;\x](\x+\y) + \nu(\x)\cdot y\big) \big| \, .
\end{equation}
%
\end{proposition}
%

\noindent
The proof of Proposition~\ref{prop:u1} is given in Section~\ref{sec:singularforcing}.

\begin{proposition}\label{prop:u2}
Let the assumption of Theorem~\ref{thm:main} hold. 
Furthermore let $0<R,T\leq1$, $\beta\in(2-\alpha,2\alpha]$, $\epsilon>0$, and $\delta\in(0,1)$. 
Then for $\|\y\|_\s\leq R$
%
\begin{equation}
\sum_{q\colon \delta<2^{-q}} \int_{D_{\y}} d\x\,
\Big|u_2^q(\x+\y)-u_2^q(\x)-\nabla u_2^q(\x) \cdot y \Big|
\lesssim \|\y\|_\s^{2\alpha} \, \delta^{-\alpha-\epsilon} C_2 \, ,
\end{equation}
%
where $\lesssim$ depends on $\beta$, $\epsilon$ and the constants $C$ of Assumptions~\ref{ass:nonlinearities} and~\ref{ass:noise}, and where $C_2$ is with $g(v)=\int_0^vdw\,|w|^{-1+\epsilon(M-1)}$ given by 
%
\begin{align}
C_2 
&= [\derivativecherry]_{2\alpha-2} 
\Big( [\Theta(u)]_{B^\alpha_{1,\infty}} 
+ T \Big) \\
%
&\,+ R^{1-\alpha} [\lolly]_\alpha 
\Big( [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}}
+ 
[\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2}
+ \|\Theta'(u)\nu\|_{L^1} \Big) \\
%
&\,+ T^{1-\alpha} \Big( \|u_0\|_{L^{1+\epsilon(M-1)}(\T^d)}^{1+\epsilon(M-1)} + 1\Big) \\
%
&\,+ T^{1-\alpha} [\xi]_{\alpha-2} 
\Big( [(g\sigma)(\mathcal{U})]_{B^{\beta}_{1,\infty}} 
+ 1 \Big) \\
%
&\,+ T^{1-\alpha} ([\dumb]_{2\alpha-2} +[\derivativecherry]_{2\alpha-2} )
\Big( [\Theta(u)]_{B^\alpha_{1,\infty}} 
+ 1 \Big) \\
%
&\,+ T^{1-\alpha} ([\xnoise]_{\alpha-1} +  [\lolly]_\alpha ) \\
&\quad\times\Big( [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}}
+ 
[\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2}
+  \|\Theta'(u)\nu\|_{L^1} (\sqrt{T})^{\alpha-1}\Big) \, .
\end{align}
%
\end{proposition}
%
\noindent
The proof of Proposition~\ref{prop:u2} is given in Section~\ref{sec:energy}.

\begin{proposition}\label{prop:u3}
Under the assumption of Theorem~\ref{thm:main}, 
and for $T>0$, $\y\in\R\times\R^d$, and $\delta\in(0,1)$, it holds
%
\begin{equation}
\sum_{q\colon \delta<2^{-q}} \int_{D_{\y}} d\x\,
\Big|u_3^q(\x+\y)-u_3^q(\x)-\nabla u_3^q(\x) \cdot y \Big|
\lesssim \|\y\|_\s^{2\alpha} \, \delta^{-\alpha} T^{1-\alpha} \, ,
\end{equation}
%
where $\lesssim$ depends on the constants $C$ of Assumptions~\ref{ass:nonlinearities} and \ref{ass:noise}. 
\end{proposition}
%
\noindent
The proof of Proposition~\ref{prop:u3} is given in Section~\ref{sec:initial}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Proof of Proposition \texorpdfstring{\ref{prop:u>} (Large velocities)}{large velocities}}\label{sec:proof_prop:u>}

Combining Propositions~\ref{prop:u0},~\ref{prop:u1},~\ref{prop:u2}, and \ref{prop:u3}, 
yields an estimate of $[\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}}$
in terms of $C_1$ and $C_2$. 
The following lemma allows to estimate the constants $C_1$ and $C_2$ in terms of $[\mathcal{U}]_{B_{1,\infty}^\beta}$.

\begin{lemma}[Back to $\mathcal{U}$]\label{lem:absorb}
Let the assumption of Theorem~\ref{thm:main} hold.
Furthermore let $\beta\in(2-\alpha,2\alpha)$ and $0<R,T\leq1$.
Then for $f\in C^2(\R)$ with $f(v)=const$ for $|v|\geq C$ for some $C$
%
~\begin{enumerate}[label=(\roman*)]
%
\item \label{it:u_alpha}
$[f(u)]_{B_{1,\infty}^\alpha}
\lesssimdata (R^{\beta-\alpha}+R^{1-\alpha}\sqrt{T}) [\mathcal{U}]_{B_{1,\infty}^{\beta}} + 1$,
%
\item \label{it:f(U)_2alpha}
$[f(\mathcal{U})]_{B_{1,\infty}^{\beta}} 
\lesssimdata [\mathcal{U}]_{B_{1,\infty}^{\beta}} + 1$,
%
%\item \label{it:nu_0}
%$\|\nu\|_{L^1} 
%\lesssimdata R^{\beta-1} [\mathcal{U}]_{B_{1,\infty}^{\beta}} + 1$,
%
\item \label{it:nu^2_0}
$\|f'(u)\nu\|_{L^2}^2 
\lesssimdata [\mathcal{U}]_{B_{1,\infty}^{\beta}} + 1$,
%
\item\label{it:nu_2alpha-1}
$[f'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
\lesssimdata [\mathcal{U}]_{B_{1,\infty}^{\beta}} + 1$.
\end{enumerate}
%
The implicit constant in $\lesssimdata$ depends on $\beta,C$, and the data as in Theorem~\ref{thm:main}.
\end{lemma}

\noindent
The proof of Lemma~\ref{lem:absorb} is standard but tedious due to the degeneracy  and is given in Appendix~\ref{app:absorb}.
%
We have now all ingredients to prove Proposition~\ref{prop:u>}.

\begin{proof}[Proof of Proposition~\ref{prop:u>}]
We begin with plugging Lemma~\ref{lem:absorb} into $C_1$ defined in Proposition~\ref{prop:u1}. 
Absorbing $\{[\tau]_{|\tau|}\}_{\tau\in\mathcal{T}}$ in the implicit constant and using $R,T\leq1$ and $\|\cdot\|_{L^1}\leq\sqrt{T}\|\cdot\|_{L^2}$ yields 
%
\begin{align}
C_1
\lesssimdata 
1 
&+ R^{1-\alpha} \big( \|\Theta'(u)\nu\|_{L^2} 
+ [\Theta(\mathcal{U})]_{B_{1,\infty}^{\beta}} 
+ [\Theta(u)]_{B_{1,\infty}^\alpha}
+ [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} \big) \, .
\end{align}
%
Using Lemma~\ref{lem:absorb} together with $R,T\leq1$ and $\beta\geq1$ implies 
%
\begin{equation}
C_1 
\lesssimdata 1 + R^{1-\alpha} [\mathcal{U}]_{B_{1,\infty}^{\beta}} \, .
\end{equation}
%
Appealing to the same argumentation for $C_2$ defined in Proposition~\ref{prop:u2}, 
and using that $\|u_0\|_{L^{1+\epsilon(M-1)}(\T^d)}\leq\|u_0\|_{L^p(\T^d)}$ for $\epsilon>0$ small enough yields
%
\begin{align}
C_2 
&\lesssimdata 
1
+ [\Theta(u)]_{B_{1,\infty}^{\alpha}} 
	+ R^{1-\alpha} \big([\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
	+ \|\Theta'(u)\nu\|_{L^2}^2 \big) \\
&+ T^{1-\alpha} [(g\sigma)(\mathcal{U})]_{B_{1,\infty}^{\beta}} 
	+ T^{1-\alpha} \big([\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
	+ \|\Theta'(u)\nu\|_{L^2}^2 \big)\, .
\end{align}
%
Recall that here $g(v)=\int_0^vdw\, |w|^{-1+\epsilon(M-1)}$ and consequently 
$g\sigma\in C^2(\R)$ and compactly supported (by Assumption~\ref{ass:nonlinearities}~(ii)).
Using Lemma~\ref{lem:absorb} together with $R,T\leq1$ and $\beta\geq1$ implies 
%
\begin{equation}
C_2
\lesssimdata 1 
+ R^{1-\alpha} [\mathcal{U}]_{B_{1,\infty}^{\beta}} 
+ T^{1-\alpha} [\mathcal{U}]_{B_{1,\infty}^{\beta}}  \, .
\end{equation}
%
Combining this with Propositions~\ref{prop:u0}~--~\ref{prop:u3} we thus have 
%
\begin{equation}
[\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} 
\lesssimdata \delta^{-\alpha-\epsilon} \big( 1 + C_1+C_2 \big)
\lesssimdata \delta^{-\alpha-\epsilon} \big( 1 + (R+T)^{1-\alpha} [\mathcal{U}]_{B_{1,\infty}^{\beta}} \big) \, .
\end{equation}
%
\end{proof}

