\section{Reconstruction and integration with rough singular kernels}\label{sec:roughkernels}

In this section we collect a number of integration and reconstruction arguments used in Section~\ref{sec:averaging} to prove Propositions~\ref{prop:u0} -- \ref{prop:u3}.
Some of these results are well known, however we provide all proofs as we need the dependence on the diffusion coefficient. 

When estimating $u_0,\dots,u_3$ in Propositions~\ref{prop:u0} -- \ref{prop:u3}, increments of the form 
%
\begin{equation}
\Psi_q\big(a,\x+\y-\z\big)
- \Psi_q\big(a,\x-\z\big) 
- \nabla\Psi_q\big(a,\x-\z\big)\cdot y
\end{equation}
%
integrated in $\x$ over $D_\y$ and in $\z$ over $(0,\infty)\times\R^d$ will come up. 
It will be convenient to replace $\Psi_q$ defined in \eqref{eq:Psi_q} by a compactly supported $K$; 
we suppress the $q$-dependence of $K$ in the notation as $q$ is fixed in what follows. 
Since the time components of the arguments $\x+\y-\z$ and $\x-\z$ are elements of $[0,T]$ by the definitions of $\Psi_q$ and $D_\y$, 
we only worry about spatial components. 
Furthermore, since we only ever consider convolutions of $\Psi_q$ with $1$-periodic (in space) functions, 
we can replace $\Psi_q$ by any function having the same (spatial) periodization. 
We thus fix a smooth $\zeta\colon\R^d\to[0,1]$ 
with $\mathrm{supp}\,\zeta\subseteq \{x\in\R^d\,|\,|x|<1\}$
such that $\sum_{k\in\Z^d} \zeta(x+k) = 1$ for all $x\in\R^d$. 
%
An example of such a $\zeta$ is given by $\zeta = \1_{[-1/2,1/2]^d}*\tilde\zeta$
for a smooth approximation $\tilde\zeta\colon\R^d\to\R$ of the Dirac, 
say with compact support in the ball of radius $2^{-10}$ centered at the origin and $\int\tilde\zeta=1$; 
then 
%
\begin{equation}
\sum_{k\in\Z^d} \zeta(x+k)
= \sum_{k\in\Z^d} \int_{\R^d} dy \, \1_{[-\frac12,\frac12]^d}(x+k-y) \tilde\zeta(y) 
= \int_{\R^d} dy \, \tilde\zeta(y) 
= 1 \, .
\end{equation}
%
With this $\zeta$ define (remember that we suppress the $q$-dependence in the notation) 
%
\begin{equation}\label{eq:defK}
K(\bar{a},\x) \coloneqq 
\sum_{k\in\Z^d}
\Psi_q(\bar{a}, (t, x+k)) \zeta(x)
\quad \textnormal{for }\bar{a}\in\R, \, \x=(t,x)\in\R\times\R^d \, .
\end{equation}
%
The (spatial) periodization of $K$ is given by 
%
\begin{equation}
\sum_{\ell\in\Z^d} K(\bar a, t, x+\ell) 
= \sum_{k\in\Z^d} \Psi_q(\bar a, (t, x+k)) 
\sum_{\ell\in\Z^d} \zeta(x+\ell) \, , 
\end{equation}
%
which coincides with the (spatial) periodization of $\Psi_q$. 

To establish estimates for convolutions of $K$ it is convenient to decompose $K$ as follows.
Fix a smooth $\eta$ compactly supported in 
$\{\x\in\R\times\R^d \,\big|\, 2^{-1} <\|\x\|_\s<2 \}$
such that $\{\eta(\S^{2^n}\cdot)\}_{n\in\N}$ is a partition of unity on\footnote{strictly speaking this requires $\sqrt{2T+1}<2$, which will always be satisfied as we are interested in small $T$} $[0,2T]\times\{x\in\R^d\,|\,|x|<1\}$.
Then for $q\in\N$ 
%
\begin{equation}\label{eq:splittingk}
K(\bar{a},\x) = \sum_{n\in\N} \Kn(\bar{a},\x) 
\quad\textnormal{for }\bar{a}\in\R\textnormal{ and }\x\in[0,T]\times\R^d \, ,
\end{equation}
%
where $\Kn(\bar{a},\x)\coloneqq\eta(\S^{2^n}\Da\x) K(\bar{a},\x)$ with the dilation $\Da\x\coloneqq(\bar at,x)$, 
and where we used that $K(\bar a,\cdot)$ vanishes unless $\bar a\leq2\cdot2^{-q}$, see \eqref{eq:defK} and \eqref{eq:Psi_q}.

Using this decomposition 
we shall often distinguish the cases $2^{-n}\leq\|\y\|_\s$ and $2^{-n}>\|\y\|_\s$; 
the former is referred to as the near-field regime 
and the latter is referred to as the far-field regime. 
In the near field we shall not make use of cancellations due to the Taylor remainder of $K$ 
and estimate the contributions from $K(\bar{a},\x+\y-\z)$, $K(\bar{a},\x-\z)$, and 
$\nabla K(\bar{a},\x-\z)\cdot y$ separately. 
%
In the far field we use the following representation of the anisotropic Taylor remainder: 
%
\begin{align}
&\bar{K}\big(\bar{a},\x,\y,\z\big) \\
&\coloneqq K\big(\bar{a},\x+\y-\z\big) - K\big(\bar{a},\x-\z\big) - \nabla K\big(\bar{a},\x-\z\big) \cdot y \\
&\,=\sum_{\substack{\hphantom{2}l+|k|_1\leq2,\\2l+|k|_1\geq2\hphantom{,}}} 
C_{l,k} 
\int_0^1 d\vartheta \, (1-\vartheta) \vartheta^{2l+|k|_1-2} \partial_t^l\partial_x^k K\big(\bar{a},\x+\S^\vartheta \y-\z\big) s^l y^k \label{eq:anisotropicTaylor}
\end{align}
%
for some generic constants $C_{l,k}$, 
which can be checked easily by plugging $f(\vartheta)\coloneqq K\big(\bar{a},\x+\S^\vartheta \y-\z\big)$ 
into $f(1)-f(0)-f'(0) = \int_0^1 d\vartheta\, (1-\vartheta) f''(\vartheta)$. 

With this decomposition at hand we give a couple of lemmas which are frequently used. 
The reader may directly jump to Section~\ref{sec:averaging} on first reading, 
and come back to these rather technical results when they are used.
We start with the following $L^1$-based regularity estimate for convolutions with the heat kernel, where we do not yet make use of the decomposition introduced above. 

\begin{lemma}\label{lem:integration1}
Recall $\Psi_q$ defined in \eqref{eq:Psi_q} for $q\in\Z$, and let $m\in\N$, $\y\in\R\times\R^d$, and $f,g\colon(0,T)\times\T^d\to\R$. 
Then 
%
\begin{align}
&\int_{D_\y}\!\! d\x \Big|\! \int_{(0,\infty)\times\R^d} \!\! d\z\, 
\partial_{\bar a}^m \! \big(\Psi_{\!q}(\bar a,\x\!+\!\y\!-\!\z) \!-\! \Psi_{\!q}(\bar a, \x\!-\!\z) \!-\! \nabla\Psi_{\!q}(\bar a, \x\!-\!\z) \!\cdot\! y \big)_{|\bar a = f(\z)}
g(\z) \Big| \\
&\lesssim T^{1-\alpha} \|\y\|_\s^{2\alpha} 
\int_{(0,T)\times\T^d} d\z \, |g(\z)| |f(\z)|^{-m} (1+|f(\z)|^{-\alpha}) |\tilde\varphi(2^q f(\z))| 
\end{align}
%
for some smooth $\tilde\varphi:\R\to\R$ supported in $(1/2,2)$. 
The same statement holds if $\int_{(0,\infty)\times\R^d}d\z$ and $\int_{(0,T)\times\T^d}d\z$ are replaced by $\int_{\R^d}dz$ and $\int_{\T^d}dz$, respectively. 
\end{lemma}

\begin{proof}
\textbf{Step 1.} We first prove for $\bar a>0$ and $s,t\in\R$
%
\begin{align}
&\int_{\R^d} dx \big| \partial_{\bar a}^m \Psi(\bar a, t+s,x+y) - \partial_{\bar a}^m \Psi(\bar a, t,x) - \partial_{\bar a}^m \nabla\Psi(\bar a,t,x)\cdot y \big| \\
&\lesssim \bar a^{-m} (1+\bar a^{-\alpha}) \|(s,y)\|_\s^{2\alpha} \cdot \left\{
\begin{array}{ll}
\min\{t,t+s\}^{-\alpha} & \textnormal{if }t>0,\,t+s>0 \, , \\
t^{-\alpha} & \textnormal{if }t>0,\,t+s<0 \, , \\
(t+s)^{-\alpha} & \textnormal{if }t<0,\,t+s>0 \, , \\
0 & \textnormal{if }t<0,\,t+s<0 \, .
\end{array}\right. 
\end{align}
%
To see this, recall that the heat kernel $\Phi$ defined in \eqref{eq:heatkernel} satisfies for $l\in\N$ and $k\in\N^d$ (we will only need it for $2l+|k|_1\leq2$) 
%
\begin{equation}
\int_{\R^d}dx \big| \partial_t^l \partial_x^k \Phi(t,x)\big| 
\lesssim t^{-(2l+|k|_1)/2} \1_{t>0} \, ,
\end{equation}
%
which by $\partial_{\bar a}^m \partial_t^l\partial_x^k\Psi(\bar a,t,x)=\partial_t^{m+l}\partial_x^k\Phi(\bar at,x) a^l t^m$ implies 
%
\begin{equation}
\int_{\R^d}dx \big| \partial_{\bar a}^m \partial_t^l \partial_x^k \Psi(\bar a,t,x)\big| 
\lesssim a^{-(2m+|k|_1)/2} t^{-(2l+|k|_1)/2} \1_{t>0} \, .
\end{equation}
%
Thus for time increments where $t,t+s>0$ we obtain by the fundamental theorem of calculus 
%
\begin{align}
&\int_{\R^d} dx \big| \Psi(\bar a,t+s,x+y) - \Psi(\bar a,t,x+y) \big| \\
&=\int_{\R^d} dx \Big| \int_0^1 d\vartheta \, \partial_t \Psi(\bar a,t+\vartheta s,x+y) s \Big| 
\lesssim \int_0^1d\vartheta\, (t+\vartheta s)^{-1} |s|
\lesssim \frac{|s|}{\min\{t,t+s\}} \, ,
\end{align}
%
and by the triangle inequality also 
%
\begin{equation}\label{eq:mt01}
\int_{\R^d} dx \big| \Psi(\bar a,t+s,x+y) - \Psi(\bar a,t,x+y) \big| 
\lesssim 1 \, ,
\end{equation}
%
and hence by interpolation 
%
\begin{equation}
\int_{\R^d} dx \big| \Psi(\bar a,t+s,x+y) - \Psi(\bar a,t,x+y) \big| 
\lesssim \frac{|s|^\alpha}{\min\{t,t+s\}^\alpha} 
\leq \frac{\|(s,y)\|_\s^{2\alpha}}{\min\{t,t+s\}^\alpha} \, .
\end{equation}
%
For time increments with $t+s<0<t$ we use \eqref{eq:mt01} (which holds for all $s,t\in\R$) and that in this case $1\leq |s|/t$ to deduce
%
\begin{equation}
\int_{\R^d} dx \big| \Psi(\bar a,t+s,x+y) - \Psi(\bar a,t,x+y) \big| 
\lesssim \frac{|s|^\alpha}{t^\alpha} 
\leq \frac{\|(s,y)\|_\s^{2\alpha}}{t^\alpha} \, ,
\end{equation}
%
and if $t<0<t+s$ we use \eqref{eq:mt01} and that in this case $1\leq s/(t+s)$ to obtain 
%
\begin{equation}
\int_{\R^d} dx \big| \Psi(\bar a,t+s,x+y) - \Psi(\bar a,t,x+y) \big| 
\lesssim \frac{|s|^\alpha}{(t+s)^\alpha} 
\leq \frac{\|(s,y)\|_\s^{2\alpha}}{(t+s)^\alpha} \, .
\end{equation}
% 
For spatial increments and $t\in\R$ we obtain by the fundamental theorem of calculus and the triangle inequality 
%
\begin{align}
&\int_{\R^d} dx \big| \Psi(\bar a,t,x+y) - \Psi(\bar a,t,x) - \nabla\Psi(\bar a,t,x)\cdot y \big| \\
&=\int_{\R^d} dx \Big| \int_0^1d\vartheta \, \nabla \Psi(\bar a,t,x+\vartheta y)\cdot y - \nabla\Psi(\bar a,t,x)\cdot y \Big| 
\lesssim (\bar a t)^{-1/2} |y| \1_{t>0} \, .
\end{align}
%
Instead of applying the triangle inequality, we can also apply the fundamental theorem of calculus a second time to obtain 
%
\begin{align}
&\int_{\R^d} dx \big| \Psi(\bar a,t,x+y) - \Psi(\bar a,t,x) - \nabla\Psi(\bar a,t,x)\cdot y \big| \\
&=\int_{\R^d} dx \Big| \int_0^1d\vartheta \int_0^1d\bar\vartheta \sum_{|k|_1=2} \partial_x^k \Psi(\bar a,t,x+\vartheta\bar\vartheta y) y^k \Big| 
\lesssim (\bar a t)^{-1} |y|^2 \1_{t>0} \, ,
\end{align}
%
so that by interpolation we obtain
%
\begin{equation}
\int_{\R^d} dx \big| \Psi(\bar a,t,x+y) - \Psi(\bar a,t,x) - \nabla\Psi(\bar a,t,x)\cdot y \big| 
\lesssim \frac{|y|^{2\alpha}}{(\bar a t)^\alpha} \1_{t>0}
\leq \frac{\|(s,y)\|_\s^{2\alpha}}{(\bar a t)^\alpha} \1_{t>0} \, .
\end{equation}
%
The argument for $m>0$ is analogous, which concludes Step~1.

\textbf{Step 2.}
We turn to the proper estimate.
Since $\Psi_q(\bar{a},\x+\vartheta\y-\z)$ for $\vartheta\in\{0,1\}$ vanishes unless the time component $t+\vartheta s-r$ of $\x+\vartheta\y-\z$ is positive, 
and since $\x\in D_\y$ implies $t+s\leq T$, 
we have effectively $r<t+\vartheta s\leq T$. 
Hence the integral $\int_{(0,\infty)\times\R^d}d\z$ effectively reduces to $\int_{(0,T)\times\R^d}d\z$. 
By periodicity of $f,g$, we further rewrite the left hand side of the assertion as
%
\begin{align}
\int_{D_\y} d\x \Big| \int_{(0,T)\times\T^d} d\z \sum_{j\in\Z^d}
\partial_{\bar a}^m 
\big(\Psi_{\!q}(\bar a,\x\!+\!\y\!-\!\z+(0,j)) 
- \Psi_{\!q}(\bar a, \x\!-\!\z+(0,j)) & \\
- \nabla\Psi_{\!q}(\bar a, \x\!-\!\z+(0,j)) \cdot y \big)_{|\bar a = f(\z)}
&g(\z) \Big| \, .
\end{align}
%
By the triangle inequality and Fubini this expression is bounded by (w.l.o.g.~let $s>0$, and recall $\x=(t,x),\y=(s,y),\z=(r,z)$)
%
\begin{align}
\int_{(0,T)\times\T^d} \!\! d\z \, |g(\z)| \int_{(0,T-s)\times\R^d} \!\! d\x 
\big| \partial_{\bar a}^m \big( \Psi_{\! q}(\bar a, t+s&-r,x+y) 
- \Psi_{\! q}(\bar a,t-r,x) \\
&- \nabla\Psi_{\! q}(\bar a,t-r,x)\cdot y \big)_{|\bar a=f(\z)} \big| \, .
\end{align}
%
The claim follows from $\Psi_q(\bar a,\cdot)=\varphi(2^q\bar a)\Psi(\bar a,\cdot)$ (see \eqref{eq:Psi_q}) and the product rule, together with Step~1 and $\int_0^Tdt \,t^{-\alpha}\lesssim T^{1-\alpha}$. 
\end{proof}

The next lemma is similar in flavour to the previous one, 
but is $L^\infty$-based and considers basepoint dependent integrands.

\begin{lemma}\label{lem:integration2}
Let $\bar K$ be the anisotropic second order Taylor remainder of $K$ from \eqref{eq:defK} as in \eqref{eq:anisotropicTaylor}, $m,q\in\N$, $\y\in\R\times\R^d$, $\x\in D_\y$, $T\leq1$, $\bar{a}\in\R$, 
and $f_\x\colon(0,\infty)\times\R^d\to\R$. 
Furthermore, let $\theta_1,\theta_2\in\R$, $\theta_1>-2$, $\theta_2\geq0$, $-1<\theta_1+\theta_2<0$, and
%
\begin{equation}
[f_\x]_{\theta_1,\theta_2}
\coloneqq
\sup_{\substack{\varphi\in\mathcal{B},\, \lambda\leq1 \\ \|\bar\x\|_\s<\|\y\|_\s+1}}
\lambda^{-\theta_1}(\lambda+\|\bar\x\|_\s)^{-\theta_2}
\Big|\int_{(0,\infty)\times\R^d}d\z f_\x(\z)\varphi^\lambda_{\x+\bar\x}(\z)\Big| \, .
\end{equation}
%
Then 
%
\begin{equation}
\Big|\int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m \bar K\big(\bar{a},\x,\y,\z\big) f_\x(\z) \Big| 
\lesssim \|\y\|_\s^{\theta_1+\theta_2+2} [f_\x]_{\theta_1,\theta_2} \, 
\frac{|\tilde\varphi(2^q\bar{a})|}{\bar{a}^{m+1+\theta_2/2}} 
\end{equation}
%
for some smooth $\tilde\varphi\colon\R\to\R$ supported in $(1/2,2)$, 
with the understanding that the right hand side vanishes for $\bar a=0$.
\end{lemma}
%
\begin{proof}
If $\bar{a}\leq0$ or $\bar{a}>2$ the left hand side vanishes by the definition of $K$ in \eqref{eq:defK} via $\Psi_q$ (defined in \eqref{eq:Psi_q}) for $q\in\N$, 
and so does the right hand side by the support of $\tilde\varphi$. 
It remains to consider $0<\bar{a}\leq2$.

\textbf{Step 1.}
We first prove for $\vartheta\in[0,1]$ and $l,n\in\N$, $k\in\N^d$ that 
%
\begin{align}
&\Big|\int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m \partial_t^l\partial_x^k K^{(n)} \big(\bar{a},\x+\S^\vartheta\y-\z\big) f_\x(\z) \Big| \\
&\lesssim 2^{-n(\theta_1+2-2l-|k|_1)} (2^{-n} + \vartheta\|\y\|_\s)^{\theta_2} [f_\x]_{\theta_1,\theta_2} \, 
\frac{|\tilde\varphi(2^q\bar{a})|}{\bar{a}^{m+1+\theta_2/2}} \, .
\end{align}
%
According to Lemma~\ref{lem:multtest}~\textit{(ii)} we have that 
%
\begin{equation}
\partial_{\bar a}^m \partial_t^l\partial_x^k K^{(n)} (\bar{a},\yy-\z) 
= 2^{-n(2-2l-|k|_1)} \bar{a}^{l-m} \rho_{\Da\yy}^{2^{-n}}(\Da\z) \tilde\varphi(2^q\bar{a})
\end{equation}
%
for some $\rho\in C\mathcal{B}$ supported on non-positive time components
and a smooth $\tilde\varphi\colon\R\to\R$ supported in $(1/2,2)$. 
Since $\rho(\Da\z)=\rho(\bar{a}r,z)$ is not a test function uniform in $\bar{a}$ we decompose it. 
We fix $r_i\in(0,\bar{a}^{-1})$ for $i=1,\dots,\bar{a}^{-1}$ and a\footnote{$\tilde\rho$ could depend on $i$, however such that its $C^n$-norms are uniformly bounded, which is why we drop the dependence in the notation for brevity} test function $\tilde\rho\in C\mathcal{B}$ supported on non-positive time components such that 
$\rho(\bar{a}r,z) = \sum_{i=1}^{\bar{a}^{-1}} \tilde\rho(r+r_i,z)$.
Then $\rho_{\Da\yy}^{2^{-n}}(\Da\z)
= \sum_{i=1}^{\bar{a}^{-1}} \tilde\rho^{2^{-n}}_{\yy-(2^{-2n}r_i,0)}(\z)$ 
and thus 
%
\begin{align}
&\Big|\int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m \partial_t^l\partial_x^k K^{(n)} \big(\bar{a},\x+\S^\vartheta\y-\z\big) f_\x(\z) \Big|\\
&\leq 2^{-n(2-2l-|k|_1)} \bar{a}^{l-m} |\tilde\varphi(2^q\bar{a})| \sum_{i=1}^{\bar{a}^{-1}}
\Big|\int_{(0,\infty)\times\R^d}d\z\, \tilde\rho^{2^{-n}}_{\x+\S^\vartheta\y-(2^{-2n}r_i,0)}(\z) f_\x(\z) \Big| \, .
\end{align}
%
Since $\tilde\rho$ is supported in the past, 
the time component $r-t-\vartheta^2s+2^{-2n}r_i$ of $\z-\x-\S^\vartheta\y+(2^{-2n}r_i,0)$ is effectively non-positive; 
hence $2^{-2n}r_i\leq t+\vartheta^2s-r$, which by assumption and $r\geq0$ implies $2^{-2n}r_i\leq T\leq1$.
Thus the above right hand side is bounded by 
%
\begin{align}
2^{-n(2-2l-|k|_1)} \bar{a}^{l-m} |\tilde\varphi(2^q\bar{a})| \sum_{i=1}^{\bar{a}^{-1}} 
2^{-n\theta_1} (2^{-n}+2^{-n}\sqrt{r_i}+\vartheta\|\y\|_\s)^{\theta_2} 
[f_\x]_{\theta_1,\theta_2} \, ,
\end{align}
%
which is bounded as desired since $1,r_i\lesssim\bar{a}^{-1}$. 
%\mt{it seems that this is not optimal}

\textbf{Step 2.}
Decomposing $K$ as in \eqref{eq:splittingk}, 
splitting into near-field and far-field, 
and using in the far-field the anisotropic Taylor remainder \eqref{eq:anisotropicTaylor} yields
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m \bar K\big(\bar a,\x,\y,\z\big) f_\x(\z) \Big| \\
&\lesssim \sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m K^{(n)}\big(\bar a,\x+\y-\z\big) f_\x(\z) \Big| \\
&\,+ \sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m K^{(n)}\big(\bar a,\x-\z\big) f_\x(\z) \Big| \\
&\,+ \sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\partial_{\bar a}^m \nabla K^{(n)}\big(\bar a,\x-\z\big)\cdot y f_\x(\z) \Big| \\
&\,+ \sum_{n\colon 2^{-n}> \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \\
&\hphantom{\,+ \sum_{n\colon 2^{-n}> \|\y\|_\s} \int_{D_\y} d\x}\times\!
\sum_{\substack{\hphantom{2}l+|k|_1\leq2,\\2l+|k|_1\geq2\hphantom{,}}}
\int_0^1 d\vartheta\, \partial_{\bar a}^m \partial_t^l\partial_x^k K^{(n)}\big(\bar a,\x+\S^\vartheta\y-\z\big) s^l y^kf_\x(\z) \Big| \, .
\end{align}
%
Using Step 1 it remains to argue that 
%
\begin{align}
&\sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
% l=k=0, v=1
\big( 2^{-n(\theta_1+2)} (2^{-n} + \|\y\|_\s)^{\theta_2} 
%l=k=0, v=0
+2^{-n(\theta_1+\theta_2+2)} 
% l=0, k=1, v=0
+ 2^{-n(\theta_1+\theta_2+1)} \|\y\|_\s \big) \\
%
&+ \sum_{n\colon 2^{-n}> \|\y\|_\s} 
\sum_{\substack{\hphantom{2}l+|k|_1\leq2,\\2l+|k|_1\geq2\hphantom{,}}} 
2^{-n(\theta_1+2-2l-|k|_1)} (2^{-n} + \|\y\|_\s)^{\theta_2}
 \|\y\|_\s^{2l+|k|_1}
\lesssim \|\y\|_\s^{\theta_1+\theta_2+2} \, .
\end{align}
%
Indeed, the geometric series are bounded by their largest summands as the exponents on $2^{-n}$ are positive, 
where in the first near-field term we use additionally $2^{-n}+\|\y\|_\s\leq2\|\y\|_\s$.
For the geometric sum we use $2^{-n}+\|\y\|_\s\leq2\cdot2^{-n}$ and $\theta_1+\theta_2+2-2l-|k|_1<0$, 
hence it is also estimated by its largest summand. 
\end{proof}

The following lemma is a small upgrade of the modelbound \eqref{eq:modelbound} when 
the model is tested with the product of a smooth kernel and $K^{(n)}$. 

\begin{lemma}\label{lem:integration3}
Let $l,\bar m,n,q\in\N$, $k\in\N^d$, $\tilde m=0,1$, $\x,\y\in\R\times\R^d$, $\varphi\in\mathcal{B}$, 
$0<\lambda\leq2^{-n}$, $\bar{a}\in\R$, $\tilde{a}\in a(\mathrm{supp}\,\sigma)\setminus\{0\}$, 
$\tau\in\mathcal{T}$, and $\Pi_\x[\tau;\tilde a]$ such that \eqref{eq:modelbound} holds.
Then 
%
\begin{align}
&\Big|\int_{(0,\infty)\times\R^d} d\z\,\varphi_\x^\lambda(\z) \partial_{\bar a}^{\bar m} \partial_t^l\partial_x^k K^{(n)} \big(\bar{a},\y-\z\big) 
\partial_{\tilde a}^{\tilde m} \Pi_\x[\tau;\tilde a](\z) \Big| \\
&\lesssim 2^{n(D-2+2l+|k|_1)} \lambda^{|\tau|} [\tau]_{|\tau|} \, 
\frac{\tilde\varphi(2^q\bar{a})}{\tilde{a}^{\mathfrak{e}(\tau)+\tilde m} \, \bar{a}^{\bar m}} 
\end{align}
%
for some smooth $\tilde\varphi\colon\R\to\R$ supported in $(1/2,2)$, 
with the understanding that the right hand side vanishes for $\bar a=0$. 
\end{lemma}
%
\begin{proof}
If $\bar{a}\leq0$ or $\bar{a}>2$ the left hand side vanishes by the definition of $K$ in \eqref{eq:defK} via $\Psi_q$ (defined in \eqref{eq:Psi_q}) for $q\in\N$, 
and so does the right hand side by the support of $\tilde\varphi$. 
It remains to consider $0<\bar{a}\leq2$.
In this case, 
according to Lemma~\ref{lem:multtest} and the assumption $\lambda\leq2^{-n}$ we have that 
$\varphi_\x^\lambda(\z) \partial_{\bar a}^{\bar m}\partial_t^l\partial_x^k K^{(n)} (\bar{a},\y-\z) 
= 2^{n(D-2+2l+|k|_1)} \bar{a}^{l-\bar m} \psi_\x^\lambda(\z) \tilde\varphi(2^q\bar{a})$ 
for some $\psi\in C\mathcal{B}$ and some a $\tilde\varphi\colon\R\to\R$ supported in $(1/2,2)$; 
we emphasize that Lemma~\ref{lem:multtest}~\textit{(i)} still holds if the test function on the larger scale is dilated with $\bar{a}\leq2$. 
The assumed model bound \eqref{eq:modelbound} then yields the claim. 
\end{proof}

Since the composition of the kernel $K$ with the solution $u$,
which appears e.g.~when estimating $u_1$ in Proposition~\ref{prop:u1}, 
has only limited regularity, its convolution with distributions may be in need of renormalization. 
The next lemma is a combination of reconstruction and integration to account for this. 

\begin{lemma}\label{lem:reconstruction0}
Let $f\colon[0,T]\times\T^d\to\R$ and $g,h\colon([0,T]\times\R^d)^2\to\R$ be jointly $1$-periodic in its spatial arguments, i.e.~$g_\x(\y)=g_{\x+(0,k)}(\y+(0,k))$ for all $k\in\Z^d$. 
For $\x,\y,\z\in[0,T]\times\R^d$ and $q\in\N$ (recall that $K$ in \eqref{eq:defK} depends on $q$) define 
%
\begin{equation}
F_\x(\z;\y)\coloneqq K(f(\x),\y-\z)g_\x(\z) + \partial_{\bar a} K(\bar a,\y-\z)_{|\bar a=f(\x)} h_\x(\z) \, ,
\end{equation}
%
and denote by $F^{(n),l,k}$ the analogous expression where $K$ is replaced by $\partial_t^l \partial_x^k K^{(n)}$.

Assume that there exist a smooth $\varphi$ compactly supported in the past with $\int\varphi\neq0$ and 
$\theta_1,\theta_2\in\R$ with $\theta_1+\theta_2>0$, $\theta_1>-2$, $\theta_2\geq0$
such that 
%
\begin{align}
&\int_{D_{\y'}\cap D_{\y''}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big(F^{(n),l,k}_{\x+\y'}(\z;\x+\y'') - F^{(n),l,k}_{\x}(\z;\x+\y'') \big) \varphi_\x^\lambda (\z) \Big| \\
&\leq C 2^{n(D-2+2l+|k|_1)} \lambda^{\theta_1} (\lambda+\|\y'\|_\s)^{\theta_2} \, ,
\end{align}
%
for $n,l\in\N$, $k\in\N^d$, $\y'\in\R\times\R^d$, $\y''\in[0,\infty)\times\R^d$,
and dyadic $\lambda\leq4\cdot2^{-n}$. 

Then $\bar F_{\x'}(\z;\x,\y)\coloneqq F_{\x'}(\z;\x+\y) - F_{\x'}(\z;\x) - \nabla_x F_{\x'}(\z;\x)\cdot y$ satisfies 
%
\begin{align}
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( \bar F_{\z}(\z;\x,\y) - \bar F_{\x}(\z;\x,\y) \big) \Big| 
\lesssim C 2^{q(\theta_2+2)/2} \|\y\|_\s^{2-} \, ,
\end{align}
%
for $\|\y\|_\s\leq1$.
By $2-$ we understand $2-\epsilon$ for arbitrary $\epsilon>0$, and the implicit constant in $\lesssim$ depends on this $\epsilon$.
The assumption is only used for $l+|k|_1\leq2$ and $\|\y'\|_\s,\|\y''\|_\s\lesssim1$. 
\end{lemma}

\begin{proof}
\textbf{Step 1 \textnormal{(splitting near-field and far field)}.}
Decomposing $K$ as in \eqref{eq:splittingk}, splitting into near-field and far-field, 
and using in the far-field the anisotropic Taylor remainder \eqref{eq:anisotropicTaylor} yields
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( \bar F_{\z}(\z;\x,\y) - \bar F_{\x}(\z;\x,\y) \big) \Big| \\
&\lesssim\sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F^{(n),0,0}_{\z}(\z;\x+\y) - F^{(n),0,0}_{\x}(\z;\x+\y) \big) \Big| \\
&\,+\sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F^{(n),0,0}_{\z}(\z;\x) - F^{(n),0,0}_{\x}(\z;\x) \big) \Big| \\
&\,+\sum_{n\colon 2^{-n}\leq \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \sum_{|k|_1=1}
\big( F^{(n),0,k}_{\z}(\z;\x) - F^{(n),0,k}_{\x}(\z;\x) \big) y^k \Big| \\
&\,+\sum_{n\colon 2^{-n}> \|\y\|_\s} 
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z 
\sum_{\substack{\hphantom{2}l+|k|_1\leq2,\\2l+|k|_1\geq2\hphantom{,}}} \\
&\hphantom{\,+\sum_{n\colon 2^{-n}> \|\y\|_\s} \int_{D_\y} d\x}\times\!
\int_0^1 d\vartheta\, 
\big( F^{(n),l,k}_{\z}(\z;\x+\S^\vartheta\y) - F^{(n),l,k}_{\x}(\z;\x+\S^\vartheta\y) \big) s^l y^k \Big| \, .
\end{align}
%

\textbf{Step 2 \textnormal{(smuggling in test functions)}.}
To estimate these expressions by reconstruction it is convenient to smuggle in a suitable test function. 
It is furthermore convenient to remember in the test function that 
$F_\x^{(n),l,k}(\z;\bar\y)$ vanishes unless the time component 
of $\bar\y-\z$ is positive. 
Unfortunately $\1_{(0,\infty)}$ is not smooth, 
which we fix by decomposing the indicator as in \cite[Section~6.1]{Hai14} as follows.
Recall
$\varphi\colon\R\to[0,1]$ with $\textrm{supp}\,\varphi\subseteq[\frac12,2]$ 
such that $\sum_{m\in\Z} \varphi(2^m s) = 1$ for all $s>0$ from \eqref{eq:decompose_phi>},
and 
$\zeta\colon\R^d\to[0,1]$ with $\textrm{supp}\,\zeta\subseteq \{x\in\R^d\,|\,|x|<1\}$ 
such that $\sum_{k\in\Z^d} \zeta(x+k) = 1$ for all $x\in\R^d$ from \eqref{eq:defK}. 
Finally, for $m\in\Z$ define the set 
%
\begin{equation}
S^m \coloneqq \{ \bar\x=(\bar{t},\bar{x})\in\R\times\R^d \, |\, 
\bar{t}=2^{-2(m+1)} \textnormal{ and } \bar{x}\in2^{-m}\Z^d \} \, .
\end{equation}
%
One can then check that $\varphi_{\bar\x,m}$ defined by 
%
\begin{equation}
\varphi_{\bar\x,m}(s,y) \coloneqq \varphi(2^m \sqrt{s}) \zeta(2^m(y-\bar{x})) 
\end{equation}
%
for $s>0$ and extended by $0$ for $s\leq0$, 
is a smooth partition of $(0,\infty)\times\R^d$, i.e.
%
\begin{equation}
\sum_{m\in\Z} \sum_{\bar\x\in S^m} \varphi_{\bar\x,m}(s,y) = \1_{(0,\infty)}(s) \, .
\end{equation}
%
Replacing $(s,y)$ by $\Dd(\yy-\z)$ we thus obtain
%
\begin{equation}
F^{(n),l,k}_\x(\z;\bar\y) 
= \sum_{m\in\Z} \sum_{\bar\x\in S^m} \varphi_{\bar\x,m}(\Dd(\bar\y-\z)) F^{(n),l,k}_\x(\z;\bar\y) \, .
\end{equation}
%
Since $F_\x^{(n),l,k}(\z;\yy)$ is for $\yy=(\bar{s},\bar{y})$ and $\z=(r,z)$ supported on 
$$2^{-n-1}<\|(f(\x)(\bar{s}-r),\bar{y}-z)\|_\s<2^{-n+1} \textnormal{ and }
2^{-q-1}<f(\x)<2^{-q+1} \, ,$$ 
and since $\varphi_{\bar\x,m}(\Dd(\yy-\z))$ is supported on $2^{-m-1}<\sqrt{2^{-q}(\bar{s}-r)}<2^{-m+1}$ 
we deduce that their product $\varphi_{\bar\x,m} F_\x^{(n),l,k}$ is only non-vanishing if 
$2^{-m-1}<2^{-n+3/2}$, i.e.~$m\geq n-2$. 
Similarly, $\varphi_{\bar\x,m}(\Dd(\yy-\z))$ is supported on $|\bar{y}-z-\bar{x}|<2^{-m}$, 
hence effectively 
$|\bar{x}|\leq|\bar{y}-z-\bar{x}|+|\bar{y}-z|<2^{-m}+2^{-n+1}<10\cdot2^{-n}$.
Furthermore there is a $\psi\in C \mathcal{B}$ (for some $C>0$) such that 
$\varphi_{\bar\x,m}(\Dd(\yy-\z)) = 2^{-mD} \psi_{\Dd(\yy-\bar\x)}^{2^{-m}}(\Dd\z)$.
Altogether this yields
%
\begin{equation}\label{eq:smuggleTestfunction}
F^{(n),l,k}_\x(\z;\bar\y) 
= \sum_{m\geq n-2} 2^{-mD} \sum_{\substack{\bar\x\in S^m \\ |\bar{x}|<10\cdot2^{-n}}} 
\psi_{\Dd(\yy-\bar\x)}^{2^{-m}}(\Dd\z) F^{(n),l,k}_\x(\z;\bar\y) \, .
\end{equation}
%
Let us point out that the kernel $\psi$ is supported on negative times: 
by definition 
%
\begin{align}
\psi(s,y) 
&= \varphi_{\bar{\x},m}\big((2^{-q}\bar{t},\bar{x})-\S^{2^{-m}}(s,y)\big) \\
&= \varphi\big(2^m \sqrt{2^{-q}\bar{t}-2^{-2m}s}\,\big) \,
\zeta\big(2^m (\bar{x}-2^{-m}y-\bar{x})\big) \\
&= \varphi\big(\sqrt{2^{-q}2^{-2}-s}\,\big) \, \zeta(-y) \, ,
\end{align}
%
where in the last equality we used that\footnote{Note that it is here where the choice of $\bar{t}$ in the definition of $S^m$ matters, 
whereas $\varphi_{\bar\x,m}$ is independent of this choice of $\bar{t}$.} 
$\bar\x=(\bar{t},\bar{x})\in S^m$, 
hence the claim follows from $\varphi$ being supported in $(1/2,2)$ and $q\in\N$.

\textbf{Step 3 \textnormal{(reconstruction)}.}
We prove for $n,l\in\N$, $k\in\N^d$, $\|\y\|_\s\lesssim1$, and $\vartheta\in[0,1]$ that 
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F_{\z}^{(n),l,k}(\z;\x+\S^\vartheta\y) - F_{\x}^{(n),l,k}(\z;\x+\S^\vartheta\y) \big) \Big| \\
&\lesssim C 2^{q(\theta_2+2)/2} 2^{-n(\theta_1+2-2l-|k|_1)} (2^{-n}+\vartheta\|\y\|_\s)^{\theta_2} \, .
\end{align}
%
By \eqref{eq:smuggleTestfunction} and the triangle inequality we have
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F_{\z}^{(n),l,k}(\z;\x+\S^\vartheta\y) - F_{\x}^{(n),l,k}(\z;\x+\S^\vartheta\y) \big) \Big| \\
&\leq 
\sum_{m\geq n-2} 2^{-mD} 
\sum_{\bar\x\in S^m\colon\, |\bar{x}|<10\cdot2^{-n}} 
\int_{D_\y} d\x\\
&\times\! \Big|\! \int_{(0,\infty)\times\R^d}\! d\z 
\big( F_{\z}^{(n),l,k}(\z;\!\x\!+\!\S^\vartheta\y) \!-\! F_{\x}^{(n),l,k}(\z;\!\x\!+\!\S^\vartheta\y) \big) 
\psi_{\Dd(\x+\S^\vartheta\y-\bar\x)}^{2^{-m}}(\Dd\!\z) \Big|
\end{align}
%
for some test function $\psi$ supported in the past. 
%
Decomposing $\psi$ as in the proof of Lemma~\ref{lem:integration2} 
to eliminate its $q$-dependence this is bounded by 
%
\begin{align}
&\sum_{m\geq n-2} 2^{-mD} 
\sum_{\bar\x\in S^m\colon\, |\bar{x}|<10\cdot2^{-n}} 
\sum_{i=1}^{2^q} 
\int_{D_\y} d\x \\
&\times\! \Big|\! \int_{(0,\infty)\times\R^d} \!d\z  
\big( F_{\z}^{(n),l,k}(\z;\!\x\!+\!\S^\vartheta\y) \!-\! F_{\x}^{(n),l,k}(\z;\!\x\!+\!\S^\vartheta\y) \big) 
\tilde\psi_{\x+\S^\vartheta\y-\bar\x-(2^{-2m}r_i,0)}^{2^{-m}}(\z) \Big|
\end{align}
%
for some $r_i\in(0,2^q)$ and $\tilde\psi\in C\mathcal{B}$ supported in the past.
%
As a consequence of the assumption and 
general reconstruction Theorem~\ref{thm:reconstruction}, 
this is estimated by 
%
\begin{align}
\sum_{m\geq n-2} 2^{-mD} 
\hspace{-3ex}
\sum_{\substack{\bar\x\in S^m \\ |\bar{x}|<10\cdot2^{-n}}} 
\hspace{-3ex}
\sum_{i=1}^{2^q} 
C 2^{n(D-2+2l+|k|_1)} 
2^{-m\theta_1} (2^{-m}+\|\S^\vartheta\y-\bar\x-(2^{-2m}r_i,0)\|_\s)^{\theta_2} \, .
\end{align}
%
For $\bar\x\in S^m$ with $|\bar x|\lesssim2^{-n}$ we have $\|\bar\x\|_\s\lesssim 2^{-m}+2^{-n}$, 
and since $m\geq n-2$ and $1,r_i\leq2^q$ we have by the triangle inequality
$2^{-m}+\|\S^\vartheta\y-\bar\x-(2^{-2m}r_i,0)\|_\s\lesssim 2^{q/2}(2^{-n}+\vartheta\|\y\|_\s)$. 
Furthermore, $\sum_{\bar\x\in S^m, \, |\bar{x}|\lesssim 2^{-n}}1$ is of the order $(2^{-n}/2^{-m})^d$, 
hence the above expression is further estimated by 
%
\begin{align}
\sum_{m\geq n-2} 
C 2^{q(\theta_2+2)/2} 2^{n(2l+|k|_1)} 2^{-m(\theta_1+2)} (2^{-n}+\vartheta\|\y\|_\s)^{\theta_2} \, .
\end{align}
%
Since the exponent on $2^{-m}$ is positive this geometric series is summable 
and bounded by its largest summand, yielding the desired estimate.

\textbf{Step 4 \textnormal{(conclusion)}.}
Combining Steps~1 and 3 it remains to argue that 
%
\begin{align}
&\sum_{n\colon 2^{-n}\leq \|\y\|_\s} \big(
% l=k=0, v=1
2^{-n(\theta_1+2)} (2^{-n}+\|\y\|_\s)^{\theta_2}
% l=k=0, v=0
+2^{-n(\theta_1+\theta_2+2)} 
% l=0, k=1, v=0
+2^{-n(\theta_1+\theta_2+1)} \|\y\|_\s \big) \\
%
&+ \sum_{n\colon 2^{-n}> \|\y\|_\s} 
\sum_{\substack{\hphantom{2}l+|k|_1\leq2,\\2l+|k|_1\geq2\hphantom{,}}}
2^{-n(\theta_1+2-2l-|k|_1)} (2^{-n}+\|\y\|_\s)^{\theta_2} \|\y\|_\s^{2l+|k|_1} 
\lesssim \|\y\|_\s^{2-} \, .
\end{align}
%
The three geometric series are each bounded by their largest summand as the exponents on $2^{-n}$ are all positive, where for the first term we use additionally $2^{-n}+\|\y\|_\s\leq 2\|\y\|_\s$. 
In the geometric sum we first use $2^{-n}+\|\y\|_\s\leq 2\cdot2^{-n}$. 
We only know that $2l+|k|_1\geq2$, hence the exponent $\theta_1+\theta_2+2-2l-|k|_1$ on $2^{-n}$ does not have a sign. 
We remedy this by giving up $2^{-n(\theta_1+\theta_2+\epsilon)}\leq1$, 
so that the remaining $2^{-n(2-2l-|k|_1-\epsilon)}$ has an overall positive exponent and the  corresponding geometric sum is bounded by its largest summand. 
\end{proof}

Finally we provide a version of reconstruction which allows to ``test with indicators''.

\begin{lemma}\label{lem:reconstruction4}
Let $F_\x(\z)$ for 
$\x\in[0,T]\times\R^d$ and $\z\in[0,\infty)\times\R^d$
be jointly $1$-periodic in its spatial arguments, 
i.e.~$F_{\x}(\z) = F_{\x+(0,k)}(\z+(0,k))$ for all $k\in\Z^d$. 

Assume that there exist 
a smooth $\varphi$ compactly supported in the past with $\int\varphi\neq0$ and 
$\theta_1,\theta_2\in\R$ with $\theta_1+\theta_2>0$, $\theta_1>-2$, $\theta_2\geq0$ 
such that 
%
\begin{align}
\int_{D_{\y}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big(F_{\x+\y}(\z) - F_{\x}(\z) \big) \varphi_\x^\lambda (\z) \Big|
\leq C_1 \lambda^{\theta_1} (\lambda+\|\y\|_\s)^{\theta_2} \, ,
\end{align}
%
for $\y$ in compacts and $0<\lambda\leq\sqrt{T}$.

Assume furthermore that there exist $\theta_3,\theta_4\in\R$ with $\theta_3>-2$, $\theta_4\geq0$ such that
%
\begin{align}
\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_{\x}(\z) \psi_{\x-(\bar t,0)}^\lambda(\z) \Big|
\leq C_2 \lambda^{\theta_3} (\lambda+\sqrt{\bar t\,}\,)^{\theta_4} \, ,
\end{align}
%
for smooth $\psi$ compactly supported in the past, 
$0<\lambda\leq\sqrt{T}$, and $0\leq\bar t\leq T$.

Then 
%
\begin{equation}
\Big| \int_{(0,T)\times\T^d} d\z \, F_{\z}(\z) \Big|
\lesssim C_1 (\sqrt{T})^{\theta_1+\theta_2} + C_2 (\sqrt{T})^{\theta_3+\theta_4} \, .
\end{equation}
%
\end{lemma}

\begin{proof}
\textbf{Step 1 \textnormal{(smuggling in test functions)}.}
In this first step we smuggle in another integral $\int_{(0,T)\times\T^d} d\x$ and a suitable test function $\psi_\x(\z)$. 
To do so recall from the definition \eqref{eq:defK} of $K$ the smooth $\zeta\colon\R^d\to[0,1]$ 
with $\mathrm{supp}\,\zeta\subseteq \{x\in\R^d\,|\,|x|<1\}$
such that $\sum_{k\in\Z^d} \zeta(x+k) = 1$ for all $x\in\R^d$. 
Then for $1$-periodic $f$ we have 
%
\begin{align}
\int_{(0,T)\times\T^d} d\z \, f(\z)
&= \frac{1}{T} \int_{(0,T)\times\T^d} d\x \int_{(0,T)\times\T^d} d\z \, f(\z) \\
&= \frac{1}{T} \int_{(0,T)\times\T^d} d\x \sum_{k\in\Z^d} \int_{(0,T)\times\T^d} d\z\, f(\z) \, 
\zeta(x-z+k) \\
&= \frac{1}{T} \int_{(0,T)\times\T^d} d\x \int_{(0,T)\times\R^d} d\z\, f(\z) \, 
\zeta(x-z) \, .
\end{align}
%
Noting that $t\in(0,T)$ and $t-r\in(0,T)$ imply $r<t<T$, 
yields
%
\begin{equation}
\int_{(0,T)\times\T^d} d\z \, f(\z) 
= \frac{1}{T} \int_{(0,T)\times\T^d} d\x 
\int_{(0,\infty)\times\R^d} d\z\, f(\z) \zeta(x-z)\1_{(0,T)}(t-r) \, .
\end{equation}
%
Unfortunately the indicator $\1_{(0,T)}$ is not a suitable test function, which we remedy by a decomposition similar to the one in Step~2 of the proof of Lemma~\ref{lem:reconstruction0}. 
Similar to before, we fix a smooth $\varphi\colon\R\to[0,1]$ with 
$\textrm{supp}\,\varphi\subseteq[\frac14,1]$ 
such that $\sum_{m\in\Z} \varphi(2^m s) = 1$ for all $s>0$. 
Then define $\varphi_m(t)\coloneqq\varphi(2^{|m|} t)$ for $m\geq1$, 
$\varphi_m(t)\coloneqq\varphi_{-m}(1-t)$ for $m\leq-1$ 
(made such that $\varphi_m$ is the around $1/2$ mirrored version of $\varphi_{-m}$), 
and $\varphi_0\coloneqq \1_{(0,1)}-\sum_{m\in\Z\setminus\{0\}}\varphi_m$.
This yields a smooth decomposition $\sum_{m\in\Z} \varphi_m=\1_{(0,1)}$. 
Finally, for $m\in\Z$ define the set 
%
\begin{align}
S^m \coloneqq \{ \bar\x=(\bar{t},\bar{x})\in\R\times\R^d \, |\, 
&\bar{t}=2^{-2(|m|+2)} \textnormal{ if } m\geq1, \, 
\bar{t}=(1\!-\!2^{-|m|})^2 \textnormal{ if } m\leq-1, \\
&\bar{t}=(\tfrac14)^2 \textnormal{ if } m=0,
\textnormal{ and } \bar{x}\in2^{-|m|}\Z^d \} \, ,
\end{align}
%
and note that $\bar t$ is the square of the left end point of the support of $\varphi_m$, see Figure~\ref{fig:dyadic}. 
%
