One can then check that $\varphi_{\bar\x,m}$ defined by 
%
\begin{equation}
\varphi_{\bar\x,m}(s,y) \coloneqq \varphi_m(\sqrt{s}) \zeta(2^{|m|}(y-\bar{x})) 
\end{equation}
%
for $s>0$ and extended by $0$ for $s\leq0$, 
is a smooth partition of $(0,1)\times\R^d$, i.e.
%
\begin{equation}
\sum_{m\in\Z} \sum_{\bar\x\in S^m} \varphi_{\bar\x,m}(s,y) = \1_{(0,1)}(s) \, .
\end{equation}
%
In particular 
%
\begin{equation}
\1_{(0,T)}(s) 
= \1_{(0,1)}(\tfrac{s}{T}) 
= \sum_{m\in\Z} \sum_{\bar\x\in S^m} \varphi_{\bar\x,m}(\tfrac{s}{T},y) 
= \sum_{m\in\Z} \sum_{\bar\x\in S^m} \varphi_m(\sqrt{\tfrac{s}{T}}) \zeta(2^{|m|}(y-\bar{x})) \, , 
\end{equation}
%
and plugging this into the above expression for $\int d\z f(\z)$ yields
%
\begin{align}
&\int_{(0,T)\times\T^d} d\z \, f(\z) \\
&= \frac{1}{T}\! \int_{(0,T)\times\T^d} \! d\x 
\int_{(0,\infty)\times\R^d} \! d\z\, f(\z) \zeta(x\!-\!z) 
\sum_{m\in\Z} \sum_{\bar\x\in S^m} 
\varphi_m(\sqrt{\tfrac{t-r}{T}}) \zeta(2^{|m|}(x\!-\!z\!-\!\bar{x})) \, .
\end{align}
%
Note that since $\zeta$ 
is supported in a ball of radius $1$, the sum over $\bar\x\in S^m$ effectively restricts to $|\bar{x}|\leq2$.
Since $2^{-|m|}\leq1$ Lemma~\ref{lem:multtest}~\textit{(i)} yields 
$\zeta(x-z) \zeta(2^{|m|}(x-z-\bar{x}))
= \hat\psi(2^{|m|}(x-z-\bar{x}))$
for some test function $\hat\psi$. 
Furthermore, the set $S^m$ (in particular the values of $\bar{t}$) is chosen such that 
$\varphi_m(\sqrt{\tfrac{t-r}{T}}) = \check\psi(\tfrac{t-r-T\bar{t}}{T 2^{-2|m|}})$ 
for $(\bar{t},\bar{x})\in S^m$ and for some\footnote{$\check\psi$ could depend on the sign of $m$, however such that its $C^n$-norms are uniformly bounded, which is why we drop the dependence in the notation for brevity} test function $\check\psi$ supported on positive times. 
Since $\check\psi(2^{2|m|}(t-r-T\bar{t})/T)$ and $\hat\psi(2^{|m|}(x-z-\bar{x}))$ 
live on different scales (w.l.o.g.~$T\leq1$ hence $\hat\psi$ lives on larger scales)
we decompose $\hat\psi$ further. 
We fix $x_k\in\R^d$ with $|x_k|<2^{-|m|}$ and a\footnote{also here $\tilde\psi$ could depend on $k$, however such that its $C^n$-norms are uniformly bounded, which is why we drop the dependence in the notation for brevity} test function $\tilde\psi$ such that 
$\hat\psi(2^{|m|}(x-z-\bar{x}))
= \sum_{k=1}^{T^{-d/2}} \tilde\psi(2^{|m|} (x-z-\bar{x}-x_k)/\sqrt{T})$.
We thus have
%
\begin{equation}
\check\psi(2^{2|m|}(t-r-T\bar{t})/T)
\hat\psi(2^{|m|}(x-z-\bar{x})) 
= \sum_{k=1}^{T^{-d/2}} \psi_{\x-(T\bar t,\bar x+x_k)}^{\sqrt{T}2^{-|m|}} (\z) 
2^{-|m|D} T^{D/2}
\end{equation}
%
for some $\psi\in C\mathcal{B}$ supported in the past. 
Altogether we obtain (for $f(\z)=F_\z(\z)$)
%
\begin{align}
&\int_{(0,T)\times\T^d} d\z \, F_\z(\z) \\
&= \sum_{m\in\Z} \sum_{\substack{\bar\x\in S^m\\ |\bar{x}|\leq2}} \sum_{k=1}^{T^{-d/2}} 
2^{-|m|D} T^{d/2} 
\int_{(0,T)\times\T^d} d\x 
\int_{(0,\infty)\times\R^d} d\z\, 
F_\z(\z) \psi_{\x-(T\bar t,\bar x+x_k)}^{\sqrt{T}2^{-|m|}}(\z) \, .
\end{align}
%

\textbf{Step 2 \textnormal{(reconstruction)}.}
Using a change of variables together with periodicity, 
and using the triangle inequality, yield
%
\begin{align}
&\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_\z(\z) \psi_{\x-(T\bar t,\bar x+x_k)}^{\sqrt{T}2^{-|m|}}(\z) \Big| \\
&=\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_\z(\z) \psi_{\x-(T\bar{t},0)}^{\sqrt{T}2^{-|m|}}(\z) \Big| \\
&\leq
\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F_\z(\z) - F_\x(\z) \big) \psi_{\x-(T\bar{t},0)}^{\sqrt{T}2^{-|m|}}(\z) \Big| \\
&\,+
\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_\x(\z) \psi_{\x-(T\bar{t},0)}^{\sqrt{T}2^{-|m|}}(\z) \Big| \, .
\end{align}
%
The first right hand side term can be estimated by general reconstruction (Theorem~\ref{thm:reconstruction}) as a consequence of the assumption; 
the second right hand side term can be estimated directly using the assumption,
so that 
%
\begin{align}
&\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_\z(\z) \psi_{\x-(T\bar t,\bar x+x_k)}^{\sqrt{T}2^{-|m|}}(\z) \Big| \\
&\lesssim C_1 (\sqrt{T}2^{-|m|})^{\theta_1} (\sqrt{T}2^{-|m|} + \sqrt{T\bar t}\,)^{\theta_2} 
+ C_2 (\sqrt{T}2^{-|m|})^{\theta_3} (\sqrt{T}2^{-|m|} + \sqrt{T\bar t}\,)^{\theta_4} \, .
\end{align}
%
Since $2^{-|m|}+\sqrt{\bar t\,}\lesssim1$ this right hand side is bounded by 
%
\begin{equation}
C_1(\sqrt{T})^{\theta_1+\theta_2} 2^{-|m|\theta_1} 
+ C_2 (\sqrt{T})^{\theta_3+\theta_4} 2^{-|m|\theta_3} \, .
\end{equation}
%

\textbf{Step 3 \textnormal{(conclusion)}.}
Plugging the estimate of Step~2 into the expression for $\int d\z\, F_\z(\z)$ from Step~1 yields
%
\begin{align}
&\Big| \int_{(0,T)\times\T^d} d\z \, F_\z(\z) \Big| \\
&\lesssim 
\sum_{m\in\Z} \sum_{\substack{\bar\x\in S^m\\ |\bar{x}|\leq2}} \sum_{k=1}^{T^{-d/2}} 
2^{-|m|D} T^{d/2} 
\big(C_1(\sqrt{T})^{\theta_1+\theta_2} 2^{-|m|\theta_1} 
+ C_2 (\sqrt{T})^{\theta_3+\theta_4} 2^{-|m|\theta_3} \big) \\
&=\sum_{m\in\Z} \sum_{\substack{\bar\x\in S^m\\ |\bar{x}|\leq2}} 2^{-|m|D} 
\big(C_1(\sqrt{T})^{\theta_1+\theta_2} 2^{-|m|\theta_1} 
+ C_2 (\sqrt{T})^{\theta_3+\theta_4} 2^{-|m|\theta_3} \big) \, .
\end{align}
%
The number of $\bar\x\in S^m$ with $|\bar{x}|\leq2$ is of the order $2^{|m|d}$, 
hence this right hand side is further estimated by 
%
\begin{equation}
\sum_{m\in\Z} 
2^{-2|m|} 
\big(C_1(\sqrt{T})^{\theta_1+\theta_2} 2^{-|m|\theta_1} 
+ C_2 (\sqrt{T})^{\theta_3+\theta_4} 2^{-|m|\theta_3} \big) \, .
\end{equation}
%
We conclude the proof by noting that the exponent on $2^{-|m|}$ is positive by assumption and the geometric series thus bounded by its largest summand. 
\end{proof}

