\section{Large velocity contributions}\label{sec:averaging}

In the following we frequently use that 
as a consequence of its definition, $\Pi_\x$ is transforming according to 
%
\begin{align}
\Pi_\x[\noise] &= \Pi_\y[\noise] \, , \\
\Pi_\x[\lolly;\bar{a}] &= \Pi_\y[\lolly;\bar{a}] + \Pi_\x[\lolly;\bar{a}](\y) \, , \label{eq:trafololly}\\
\Pi_\x[\dumb;\bar{a}] &= \Pi_\y[\dumb;\bar{a}] + \Pi_\x[\lolly;\bar{a}](\y) \xi \, , \label{eq:trafodumb} \\
\Pi_\x[\derivativecherry;\bar{a}] &= \Pi_\y[\derivativecherry;\bar{a}] \, , \label{eq:trafoderivativecherry} \\
\Pi_\x[\xnoise] &= \Pi_\y[\xnoise] + (y-x) \xi \label{eq:trafoxnoise}  \, , 
\end{align}
%
which combined with \eqref{eq:modelbound} yields for $\tau\in\mathcal{T}$
%
\begin{equation}\label{eq:offdiagonal}
|\big\langle \partial_{\bar{a}}^m \Pi_\x[\tau;\bar{a}] , \varphi_\y^\lambda \big\rangle |
\lesssim [\tau]_{|\tau|} \lambda^{\alpha-2} (\lambda+\|\x-\y\|_\s)^{|\tau|+2-\alpha} \, \bar{a}^{-\mathfrak{e}(\tau)-m} 
\end{equation}
%
uniformly for $\x,\y$ in compacts, $\lambda\in(0,1)$, $\bar a\in a(\mathrm{supp}\,\sigma)\setminus\{0\}$, $m=0,1$, and $\varphi\in\mathcal{B}$. 
Here we made a small abuse of notation: the constant $[\dumb]_{2\alpha-2}$ in \eqref{eq:offdiagonal} in case of $\tau=\dumb$ should actually be $[\dumb]_{2\alpha-2}+[\lolly]_{\alpha}[\noise]_{\alpha-2}$ in order to be consistent with \eqref{eq:trafodumb} and \eqref{eq:modelbound}, 
which however we ignore for notational simplicity.\footnote{The reason why we keep $[\tau]_{|\tau|}$ at all throughout most estimates and do not hide it in $\lesssim$ is that we hope it helps the reader to match in long estimates, e.g.~right before equation \eqref{eq:XIII}, which terms arise from which contributions.}

\subsection{Contributions of the initial condition and counterterms}\label{sec:initial} 

Both Propositions~\ref{prop:u0} and \ref{prop:u3} are a simple consequence of Lemma~\ref{lem:integration1}.

\begin{proof}[Proof of Proposition~\ref{prop:u0}]
By the definition of $u_0^q$ in Section~\ref{sec:mild} we have
%
\begin{align}
&u_0^q(\x+\y)-u_0^q(\x)-\nabla u_0^q(\x)\cdot y \\
&= \int_\R dv \int_{\R^d} dz
\Big( \Psi_q\big(a(v),t+s,x+y-z\big) 
- \Psi_q\big(a(v),t,x-z\big) \\
&\hphantom{= \int_\R dv \int_{\R^d} dz\Big( \Psi_q\big(a(v),t+s,x+y-z\big)\ }
- \nabla \Psi_q\big(a(v),t,x-z\big) \cdot y \Big)
\chi(0,z,v) \, .
\end{align}
%
Applying Lemma~\ref{lem:integration1} 
(with $m=0$, $f(z)=a(v)$, i.e.~$f$ is constant in $z$, and $g(z)=\chi(0,z,v)$) yields 
%
\begin{align}
&\int_{D_\y}d\x \big| u_0^q(\x+\y)-u_0^q(\x)-\nabla u_0^q(\x)\cdot y \big| \\
&\lesssim T^{1-\alpha} \|\y\|_\s^{2\alpha} \int_\R dv \int_{\T^d} dz \, \big|
\chi(0,z,v)\,(1+a(v)^{-\alpha}) \tilde\varphi(2^q a(v)) \big| \, .
\end{align}
%
Here $\tilde\varphi$ is smooth and supported in $(1/2,2)$, 
hence $(1+ a^{-\alpha})|\tilde\varphi(2^q a)| \lesssim (1+2^{q\alpha})|\tilde\varphi(2^q a)|$. 
Summing over $q\in\Z$ with $\delta<2^{-q}$ we observe that for such $q$ we have $(1+2^{q\alpha})\lesssim\delta^{-\alpha}$, and furthermore $\sum_{q} |\tilde\varphi(2^q a)|\lesssim 1$. 
Thus the claim follows from noting that 
$\int_\R dv\,|\chi(0,z,v)|\leq |u_0(z)|$. 
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{proof}[Proof of Proposition~\ref{prop:u3}]
By the definition of $u_3^q$ in Section~\ref{sec:mild} we have
%
\begin{align}
&u_3^q(\x+\y) - u_3^q(\x) - \nabla u_3^q(\x) \cdot y \\
&=\!\int_{(0,\infty)\times\R^d} \hspace{-3ex}d\z \, 
\partial_v \Big(\!\Psi_q\big(a(v),\x\!+\!\y\!-\!\z\big)
\!-\! \Psi_q\big(a(v),\x\!-\!\z\big) 
\!-\! \nabla\Psi_q\big(a(v),\x\!-\!\z\big)\!\cdot\! y \Big)_{|v=u(\z)} \\
&\qquad\times 
\sigma^2(u(\z)) \big( \cdumb^{a(u(\z))}(r) - a(u(\z)) \ccherry^{a(u(\z))}(r) \big) \\
%
&\,+\!\int_{(0,\infty)\times\R^d}\hspace{-3ex} d\z \, 
\Big(\!\Psi_q\big(a(u(\z)),\x\!+\!\y\!-\!\z\big)
\!-\! \Psi_q\big(a(u(\z)),\x\!-\!\z\big)
\!-\! \nabla\Psi_q\big(a(u(\z)),\x\!-\!\z\big)\!\cdot\! y\Big) \\
&\qquad\times
\sigma'(u(\z))\sigma(u(\z)) \big( \cdumb^{a(u(\z))}(r) - C^{a(u(\z))} \big) \, .
\end{align}
%
Applying Lemma~\ref{lem:integration1} 
(once with $m=1$ and $g=a'(u)\sigma^2(u)(\cdumb^{a(u)}-a(u)\ccherry^{a(u)})$,
once with $m=0$ and $g=\sigma'\sigma(\cdumb^{a(u)}-C^{a(u)})$,
and both times with $f=a(u)$)
yields 
%
\begin{align}
&\int_{D_{\y}} d\x\,
\Big|u_3^q(\x+\y)-u_3^q(\x)-\nabla u_3^q(\x) \cdot y \Big| 
\lesssim T^{1-\alpha} \|\y\|_\s^{2\alpha} \\
&\times\!\Big( 
\int_{(0,T)\times\T^d}\! d\z \big| \big(a'\!\sigma^2\!/a (1\!+\!a^{-\alpha}) \tilde\varphi(2^qa)\big)(u(\z)) \big(\cdumb^{a(u(\z))}(r)-a(u(\z))\ccherry^{a(u(\z))}(r)\big) \big| \\
&\ \ + \int_{(0,T)\times\T^d}\! d\z \big| \big(\sigma'\!\sigma(1+a^{-\alpha}) \tilde\varphi(2^qa)\big)(u(\z)) \big(\cdumb^{a(u(\z))}(r)-C^{a(u(\z))}\big) \big| \Big) \, .
\end{align}
%
Summing over $q\in\Z$ with $\delta<2^{-q}$ we argue as in the proof of Proposition~\ref{prop:u0} to estimate $\sum_{\delta<2^{-q}} (1+a^{-\alpha})|\tilde\varphi(2^qa)|\lesssim \delta^{-\alpha}$. 
Since Assumption~\ref{ass:nonlinearities} implies $|a'(v)/a(v)|\lesssim|v|^{-1}$ the claim follows from Assumption~\ref{ass:noise}. 
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Contributions of the singular forcing}\label{sec:singularforcing}

\begin{proof}[Proof of Proposition~\ref{prop:u1}]
Appealing to the definitions of $u_1^q$ and $\Pi_\x^q$ in Section~\ref{sec:mild}, we observe
%
\begin{align}
&u_1^q(\x\!+\!\y)\!-\!u_1^q(\x)\!-\!\sigma(u(\x))\Pi_\x^q[\lolly;\x](\x\!+\!\y) 
\!-\! \big(\nabla u_1^q(\x) \!-\! \sigma(u(\x)) \nabla\Pi_\x^q[\lolly;\x](\x) \big) \!\cdot\! y \\
&=\int_{(0,\infty)\times\R^d} d\z \, 
\bar\Psi_q\big(a(u(\z)),\x,\y,\z\big) \sigma(u(\z))\xi(\z) \\ 
&\,-\int_{(0,\infty)\times\R^d} d\z \, 
\partial_v\Big( \bar\Psi_q\big(a(v),\x,\y,\z\big) \sigma(v) \Big)_{|v=u(\z)} 
\sigma(u(\z)) \cdumb^{a(u(\z))}(r) \\
&\,-\int_{(0,\infty)\times\R^d} d\z \, 
\bar\Psi_q \big(a(u(\x)),\x,\y,\z\big) \sigma(u(\x)) \xi(\z) \, , 
\end{align}
%
where $\bar\Psi_q\big(\bar a,\x,\y,\z\big)$ denotes the anisotropic second order Taylor remainder 
%
\begin{equation}
\Psi_q \big(\bar a,\x+\y-\z\big) 
- \Psi_q \big(\bar a,\x-\z\big)
- \nabla \Psi_q \big(\bar a,\x-\z\big) \cdot y \, .
\end{equation}
%
Since all terms contain an instance of $\sigma(u)$, we effectively have to deal with bounded $u$, hence we may assume w.l.o.g.~that $a\leq1$ so that we only need to consider $q\in\N$. 
As in Section~\ref{sec:roughkernels} we replace $\Psi_q$ by $K$ defined in \eqref{eq:defK}. 
In the following we smuggle in suitable terms. 
To shorten the expressions a bit we 
write $\K(\bar{a},\x,\y,\z)$ as in \eqref{eq:anisotropicTaylor} to denote the anisotropic Taylor remainder. 
Furthermore we use the shorthand notation 
$\fnoise=f(u)$ and $\flolly=f'(u)$.

We start by rewriting 
%
\begin{align}
&\K\big(\anoise(\z),\x,\y,\z\big) \snoise(\z) \xi(\z)
- \partial_v \big( \K\big(a(v),\x,\y,\z\big) \sigma(v) \big)_{|v=u(\z)} \snoise(\z) \cdumb^{\anoise(\z)}(r) \\
&\,- \K\big(\anoise(\x),\x,\y,\z\big) \snoise(\x) \xi(\z) \\
&= \partial_v \big( \K \big(a(v),\x,\y,\z\big) \sigma(v) \big)_{|v=u(\x)}
\snoise(\x) \Pi_\x[\dumb;\x](\z) \label{eq:nf1} \\
&\,+ \partial_v \big( \K\big(a(v),\x,\y,\z\big) \sigma(v) \big)_{|v=u(\x)}
\nu(\x) \cdot \Pi_\x[\xnoise](\z) \label{eq:nf2} \\
&\,+ \K\big(\anoise(\z),\x,\y,\z\big) \snoise(\z) \xi(\z)
- \partial_v\big( \K\big(a(v),\x,\y,\z\big) \sigma(v) \big)_{|v=u(\z)} 
\snoise(\z) \cdumb^{\anoise(\z)}(r) \\ 
&\quad- \K\big(\anoise(\x),\x,\y,\z\big) \snoise(\x) \xi(\z) \\
&\quad- \partial_v \big( \K\big(a(v),\x,\y,\z\big) \sigma(v) \big)_{|v=u(\x)} 
\big( \snoise(\x) \Pi_\x[\dumb;\x](\z) 
+ \nu(\x)\cdot\Pi_\x[\xnoise](\z) \big) \, . \label{eq:nf3}
\end{align}
%
We estimate \eqref{eq:nf1} and \eqref{eq:nf2} in Step~1, and \eqref{eq:nf3} in Step~2 below. 

\textbf{Step 1 \textnormal{(estimate of \eqref{eq:nf1} and \eqref{eq:nf2})}.}
Note that 
%
\begin{equation}
\partial_v\big(\K\big(a(v),\cdot\big)\sigma(v)\big)_{|v=u(\x)}
= \partial_{\bar a}\K\big(\bar a,\cdot\big)_{|\bar a=\anoise(\x)} \alolly(\x) \snoise(\x) 
+ \K\big(\anoise(\x),\cdot\big) \slolly(\x) \, ,
\end{equation}
% 
so that Lemma~\ref{lem:integration2} can be applied: 
once with 
$m=1$, $f_\x=\alolly(\x)\ssnoise(\x)\Pi_\x[\dumb;\x]$, $\theta_1=\alpha-2$, $\theta_2=\alpha$,
once with 
$m=0$, $f_\x=\slolly(\x)\snoise(\x)\Pi_\x[\dumb;\x]$, $\theta_1=\alpha-2$, $\theta_2=\alpha$,
once with
$m=1$, $f_\x=\alolly(\x)\snoise(\x)\nu(\x)\cdot\Pi_\x[\xnoise]$, $\theta_1=\alpha-2$, $\theta_2=1$,
and once with
$m=0$, $f_\x=\slolly(\x)\nu(\x)\cdot\Pi_\x[\xnoise]$, $\theta_1=\alpha-2$, $\theta_2=1$,
to deduce 
%
\begin{align}
&\int_{D_{\y}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( \eqref{eq:nf1} + \eqref{eq:nf2} \big) \Big| \\
&\lesssim \|\y\|_\s^{2\alpha} [\dumb]_{2\alpha-2} 
\int_{D_\y} d\x \, \Big( \frac{|\alolly(\x)\ssnoise(\x)\tilde\varphi(2^q\anoise(\x))|}{\anoise(\x)^{1+1+\alpha/2+\mathfrak{e}(\dumbsmall)}}
+ \frac{|\slolly(\x)\snoise(\x)\tilde\varphi(2^q\anoise(\x))|}{\anoise(\x)^{1+\alpha/2+\mathfrak{e}(\dumbsmall)}}\Big) \\
&\,+ \|\y\|_\s^{\alpha+1} [\xnoise]_{\alpha-1} \!
\int_{D_\y} \! d\x \, \Big( \frac{|\alolly(\x)\snoise(\x)\nu(\x)\tilde\varphi(2^q\anoise(\x))|}{\anoise(\x)^{1+1+1/2}}
+ \frac{|\slolly(\x)\nu(\x)\tilde\varphi(2^q\anoise(\x))|}{\anoise(\x)^{1+1/2}}\Big) \, ,
\end{align}
%
where we directly used \eqref{eq:offdiagonal} 
(and $\mathfrak{e}(\xnoise)=0$, see Table~\ref{tab:hom}).
Using \eqref{eq:Theta} and 
that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($2N-1-(\alpha/2+2)(M-1)\geq-\alpha(M-1)$, 
%$2N-1-(\alpha/2+2)(M-1)\geq-\alpha(M-1)$, 
%$N+M-2-5/2(M-1)\geq-\alpha(M-1)$, 
%$N-1-3/2(M-1)\geq-\alpha(M-1)$) 
%
\begin{equation}
\max\Big\{
\Big|\frac{a'\sigma^2}{a^{\alpha/2+2+\mathfrak{e}(\dumbsmall)}}\Big| \, , \ 
\Big|\frac{\sigma'\sigma}{a^{\alpha/2+1+\mathfrak{e}(\dumbsmall)}}\Big|\, , \ 
\Big|\frac{a'\sigma}{a^{5/2}}\Big| \, , \ 
\Big|\frac{\sigma'}{a^{3/2}}\Big| \Big\} \lesssim \frac{1}{a^{\alpha}} 
\tag{II}
\end{equation}
%
we obtain 
%
\begin{align}
&\int_{D_{\y}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( \eqref{eq:nf1} + \eqref{eq:nf2} \big) \Big| \\
&\lesssim \|\y\|_\s^{2\alpha} 2^{q\alpha} [\dumb]_{2\alpha-2} T
+ \|\y\|_\s^{\alpha+1} 2^{q\alpha} [\xnoise]_{\alpha-1} \|\Theta'(u)\nu\|_{L^1} \, . \label{eq:nf5}
\end{align}
%
Summing over $q\in\N$ with $\delta<2^{-q}$ this is estimated as desired since $\sum_{\delta<2^{-q}} 2^{q\alpha}\lesssim\delta^{-\alpha}$. 

\textbf{Step 2 \textnormal{(estimate of \eqref{eq:nf3})}.}
We aim to apply Lemma~\ref{lem:reconstruction0} to 
%
\begin{align}
F_\x(\z;\yy) 
&\coloneqq K\big(\anoise(\x),\yy-\z\big) \snoise(\x) \xi(\z) \label{eq:F0}\\
&\ + \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{|v=u(\x)}
\big( \snoise(\x) \Pi_\x[\dumb;\x](\z) 
+ \nu(\x) \cdot\Pi_\x[\xnoise](\z) \big) \, .
\end{align}
%
Note that 
%
\begin{align}
F_\z(\z;\yy) 
&= K\big(\anoise(\z),\yy-\z\big) \snoise(\z) \xi(\z) \\
&\,- \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{v=u(\z)}  
\snoise(\z) \cdumb^{\anoise(\z)}(r) \, ,
\end{align}
% 
so that (recall from Lemma~\ref{lem:reconstruction0} that $\bar F$ denotes the Taylor remainder of $F$) 
%
\begin{equation}
\eqref{eq:nf3} 
= \bar F_\z(\z;\x,\y) - \bar F_\x(\z;\x,\y) \, .
\end{equation}
%
The following lemma verifies the assumption of Lemma~\ref{lem:reconstruction0}
(recall that $F^{(n),l,k}$ is defined analogously to $F$ with $K$ replaced by $\partial_t^l\partial_x^k \Kn$).

%
\begin{lemma}\label{lem:reconstruction1}
Let $n,l,q\in\N$, $k\in\N^d$, $\y,\y'\in\mathfrak{K}\subseteq\R\times\R^d$ for compact $\mathfrak{K}$, $0<\lambda\leq2^{-n}$, $\varphi\in\mathcal{B}$, $\beta\in(1,2)$, and $\bar\alpha\coloneqq\min\{1+\alpha/2,\beta\}$. 
Then $F$ defined in \eqref{eq:F0} satisfies 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big(F^{(n),l,k}_{\x+\y}(\z;\x+\y') - F^{(n),l,k}_{\x}(\z;\x+\y') \big) \varphi_\x^\lambda (\z) \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} 
\lambda^{\alpha-2} (\lambda+ \|\y\|_\s)^{\bar\alpha} C_{\eqref{eq:nf3}} 2^{-q} \, ,
\end{align}
%
where $\lesssim$ depends on $\mathfrak{K}$ and the constant $C$ of Assumption~\ref{ass:nonlinearities}, and where 
%
\begin{align}
C_{\eqref{eq:nf3}} 
&= [\xi]_{\alpha-2} 
\Big( [\Theta(\mathcal{U})]_{B^{\beta}_{1,\infty}} 
+ [\lolly]_\alpha^2 T 
+ [\lolly]_\alpha \|\Theta'(u)\nu\|_{L^1} 
+ \|\Theta'(u)\nu\|_{L^2}^2 \Big) \\
%
&\,+ [\dumb]_{2\alpha-2} 
[\Theta(u)]_{B_{1,\infty}^\alpha} \\
%
&\,+ [\xnoise]_{\alpha-1} 
\Big( [\Theta(u)]_{B^\alpha_{1,\infty}}^{1/2} \|\Theta'(u)\nu\|_{L^2}  
+ [\Theta'(u)\nu]_{B^{\beta-1}_{1,\infty}} \Big) \, ,
\end{align}
%
with $\Theta$ from \eqref{eq:Theta}.
\end{lemma}
%

Before giving the proof of Lemma~\ref{lem:reconstruction1} we continue Step~2 in the proof of Proposition~\ref{prop:u1}. 
Lemma~\ref{lem:reconstruction1} verifies the assumption of Lemma~\ref{lem:reconstruction0} with $\theta_1=\alpha-2$ and $\theta_2=\min\{1+\alpha/2,\beta\}$. 
Since by assumption $\alpha-2+\beta>0$ and $3\alpha-2>0$, Lemma~\ref{lem:reconstruction0} yields
%
\begin{align}
\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, \eqref{eq:nf3} \Big| 
\lesssim C_{\eqref{eq:nf3}} 2^{-q} 2^{q(2\alpha+2)/2} \|\y\|_\s^{2-} \, ,
\end{align}
%
where we have directly used that $\min\{1+\alpha/2,\beta\}\leq 2\alpha$. 
From $\|\y\|_\s\leq R\leq1$ follows $\|\y\|_\s^{2-}\leq\|\y\|_\s^{2\alpha}R^{1-\alpha}$ and hence the desired bound from summing over $q\in\N$ with $\delta<2^{-q}$. 
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:reconstruction1}]
We start with having a closer look on $F_{\x+\y} - F_{\x}$,
%
\begin{align}
&F_{\x+\y}(\z;\yy) - F_{\x}(\z;\yy) \\
&= K\big(\anoise(\x+\y),\yy-\z\big) \snoise(\x+\y) \xi(\z) \\
&\,+ \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{|v=u(\x+\y)} \\[-1ex]
&\quad\times
\big( \snoise(\x+\y) \Pi_{\x+\y}[\dumb;\x+\y](\z) 
+ \nu(\x+\y) \cdot\Pi_{\x+\y}[\xnoise](\z) \big) \\
&\,- K\big(\anoise(\x),\yy-\z\big) \snoise(\x) \xi(\z) \\
&\,- \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{|v=u(\x)} 
\big( \snoise(\x) \Pi_\x[\dumb;\x](\z) 
+ \nu(\x) \cdot\Pi_\x[\xnoise](\z) \big) \, .
\end{align}
%
Using \eqref{eq:trafodumb} in form of 
$\Pi_{\x}[\dumb;\x] = \Pi_{\x+\y}[\dumb;\x] + \Pi_{\x}[\lolly;\x](\x+\y) \xi$
and \eqref{eq:trafoxnoise} in form of 
$\Pi_{\x}[\xnoise] = \Pi_{\x+\y}[\xnoise] + y \xi$,
we obtain 
%
\begin{align}
&F_{\x+\y}(\z;\yy) - F_{\x}(\z;\yy) \\
&= K\big(\anoise(\x+\y),\yy-\z\big) \snoise(\x+\y) \xi(\z) \\
&\,- K\big(\anoise(\x),\yy-\z\big) \snoise(\x) \xi(\z) \\
&\,- \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{v=u(\x)} 
\big( \snoise(\x) \Pi_{\x}[\lolly;\x](\x+\y) 
+ \nu(\x) \cdot y \big) \xi(\z) \\
%
&\,+ \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{v=u(\x+\y)} \\[-1ex]
&\quad\times
\big( \snoise(\x+\y) \Pi_{\x+\y}[\dumb;\x+\y](\z) 
+ \nu(\x+\y) \cdot\Pi_{\x+\y}[\xnoise](\z) \big) \\
&\,- \partial_v \big( K\big(a(v),\yy-\z\big) \sigma(v) \big)_{|v=u(\x)}
\big( \snoise(\x) \Pi_{\x+\y}[\dumb;\x](\z) 
+ \nu(\x) \cdot\Pi_{\x+\y}[\xnoise](\z) \big) \, .
\end{align}
%
Note that because of the presence of $\sigma$, all instances of $u$ 
(also those implicit in $\anoise=a(u)$ and $\snoise=\sigma(u)$) 
can be replaced by $\bar u\coloneqq \Theta(u)$ with $\Theta$ from \eqref{eq:Theta}, 
and all instances of $\nu$ can be replaced by $\bar\nu\coloneqq\Theta'(u)\nu$. 
Denoting $G(v)\coloneqq K(a(v),\yy-\z)\sigma(v)$ 
and $G'(v)=\partial_v G(v)$, we rewrite the first three lines of the right hand side as 
%
\begin{align}
&G\big( \bar u(\x+\y)\big)\xi(\z) 
- G\big( \bar u(\x) + \snoise(\x)\Pi_\x[\lolly;\x](\x+\y) + \bar\nu(\x) \cdot y \big) \xi(\z) \label{eq:mt05} \qquad \\
&+ G\big( \bar u(\x) + \snoise(\x)\Pi_\x[\lolly;\x](\x+\y) + \bar\nu(\x) \cdot y) \xi(\z) \\
&\quad- G\big( \bar u(\x) + \bar\nu(\x)\cdot y\big) \xi(\z)
- G'\big(\bar u(\x)\big) \snoise(\x) \Pi_\x[\lolly;\x](\x+\y) \xi(\z) \label{eq:mt06} \\
&+ G\big(\bar u(\x) + \bar\nu(\x) \cdot y \big) \xi(\z) 
- G\big(\bar u(\x)\big) \xi(\z) 
- G'\big(\bar u(\x)\big) \bar\nu(\x) \cdot y \xi(\z) \, , \label{eq:mt07}
\end{align}
%
and the last two lines as 
%
\begin{align}
&G'\big(\bar u(\x+\y)\big) \snoise(\x+\y) \Pi_{\x+\y}[\dumb;\x+\y](\z)
- G'\big(\bar u(\x)\big) \snoise(\x) \Pi_{\x+\y}[\dumb;\x](\z) \qquad \label{eq:mt08} \\
&+ \big( G'\big(\bar u(\x+\y)\big) - G'\big(\bar u(\x)\big) \big) \bar\nu(\x+\y) \cdot \Pi_{\x+\y}[\xnoise](\z) \label{eq:mt09} \\
&+ G'\big(\bar u(\x)\big) \big( \bar\nu(\x+\y) - \bar\nu(\x) \big) \cdot \Pi_{\x+\y}[\xnoise](\z) \label{eq:mt10} \, .
\end{align}
%
Using the fundamental theorem of calculus we have 
%
\begin{align}
\eqref{eq:mt05}
= \int_0^1 d\vartheta \, &G'\big( \vartheta \bar u(\x+\y) +(1-\vartheta) \big(\bar u(\x)+\snoise(\x)\Pi_\x[\lolly;\x](\x+\y)+\bar\nu(\x)\cdot y\big)\big) \\
&\times \big( \bar u(\x+\y) - \bar u(\x) - \snoise(\x)\Pi_\x[\lolly;\x](\x+\y) - \bar\nu(\x)\cdot y\big) \xi(\z) \, ,
\end{align}
%
which by $\snoise=\sigma(u)=\Theta'(u)\sigma(u)$, 
%
\begin{equation}
G'(v) 
= \partial_{\bar a}K(\bar a,\yy-\z)_{|\bar a=a(v)} a'(v)\sigma(v)
+ K(a(v),\yy-\z)\sigma'(v) \, ,
\end{equation}
%
and Lemma~\ref{lem:integration3} with $\yy=\x+\y'$ yields for $\lambda\leq2^{-n}$ 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\varphi_\x^\lambda(\z) \eqref{eq:mt05}^{(n),l,k} \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-2} [\xi]_{\alpha-2} 
\big( \|a'\!\sigma/a\tilde\varphi(2^qa)\|_\infty + \|\sigma'\tilde\varphi(2^qa)\|_\infty \big)
[\Theta(\mathcal{U})]_{B_{1,\infty}^{\beta}} \|\y\|_\s^{\beta} \, .
\end{align}
%
For \eqref{eq:mt06} we use the fundamental theorem of calculus twice to see
%
\begin{align}
\eqref{eq:mt06}
&=\! \int_0^1\! d\vartheta\, G'\big( \bar u(\x) \!+\! \vartheta \snoise(\x) \Pi_\x[\lolly;\x](\x\!+\!\y) \!+\! \bar\nu(\x) \!\cdot\! y \big) 
\snoise(\x) \Pi_\x[\lolly;\x](\x\!+\!\y) \xi(\z) \\
&\,- G'\big( \bar u(\x)\big) \snoise(\x) \Pi_\x[\lolly;\x](\x+\y) \xi(\z) \\ 
&= \int_0^1 d\vartheta \int_0^1 d\bar{\vartheta} \, G''\big( \bar u(\x) + \vartheta\bar{\vartheta} \snoise(\x) \Pi_\x[\lolly;\x](\x+\y) + \bar{\vartheta} \bar \nu(\x) \cdot y \big) \\
&\quad\times \snoise(\x) \Pi_\x[\lolly;\x](\x+\y) 
\big( \vartheta \snoise(\x) \Pi_\x[\lolly;\x](\x+\y) + \bar \nu(\x)\cdot y\big) \xi(\z) \, .
\end{align}
%
Using 
%
\begin{align}
G''(v) 
&= 
\partial_{\bar a}^2K(\bar a,\yy-\z)_{|\bar a=a(v)} (a'(v))^2 \sigma(v) 
+ \partial_{\bar a}K(\bar a,\yy-\z)_{|\bar a=a(v)} a''(v)\sigma(v) \\
&\,+ 2 \partial_{\bar a}K(\bar a,\yy-\z)_{|\bar a=a(v)} a'(v)\sigma'(v)
+ K(a(v),\yy-\z)\sigma''(v)
\end{align}
%
and Lemma~\ref{lem:integration3} with $\yy=\x+\y'$ yields for $\lambda\leq2^{-n}$ 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\varphi_\x^\lambda(\z) \eqref{eq:mt06}^{(n),l,k} \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-2} [\xi]_{\alpha-2} \\
&\,\times \!
\big( \|a^{-2}(a')^2\sigma\tilde\varphi(2^qa)\|_\infty 
\!+\! \|a^{-1}\!a''\!\sigma\tilde\varphi(2^qa)\|_\infty
\!+\! \|a^{-1}\!a'\!\sigma'\tilde\varphi(2^qa)\|_\infty
\!+\! \|\sigma''\tilde\varphi(2^qa)\|_\infty \big) \\
&\,\times \!
\big( \|a^{-\mathfrak{e}(\lollysmall)}\sigma \|^2_\infty [\lolly]_\alpha^2 \|\y\|_\s^{2\alpha} T 
+ \|a^{-\mathfrak{e}(\lollysmall)}\sigma\|_\infty [\lolly]_\alpha \|\y\|_\s^\alpha \|\Theta'(u)\nu\|_{L^1} \|\y\|_\s \big) \, .
\end{align}
%
Also for \eqref{eq:mt07} we use the fundamental theorem of calculus twice to obtain
%
\begin{align}
\eqref{eq:mt07}
&= \int_0^1 d\vartheta \, G'\big( \bar u(\x) + \vartheta\bar\nu(\x)\cdot y\big) \bar\nu(\x)\cdot y \xi(\z)
- G'\big( \bar u(\x)\big) \bar\nu(\x)\cdot y \xi(\z) \\ 
&= \int_0^1 d\vartheta \int_0^1 d\bar{\vartheta} \, G''\big( \bar u(\x) + \vartheta\bar{\vartheta}\bar\nu(\x)\cdot y\big) (\bar\nu(\x)\cdot y)^2 \xi(\z) \, .
\end{align}
%
As before we deduce from Lemma~\ref{lem:integration3} with $\yy=\x+\y'$ that for $\lambda\leq2^{-n}$ 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\varphi_\x^\lambda(\z) \eqref{eq:mt07}^{(n),l,k} \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-2} [\xi]_{\alpha-2} \|\Theta'(u)\nu\|_{L^2}^2 \|\y\|_\s^2 \\
&\times \!
\big( \|a^{-2}(a')^2\sigma\tilde\varphi(2^qa)\|_\infty 
\!+\! \|a^{-1}\!a''\!\sigma\tilde\varphi(2^qa)\|_\infty
\!+\! \|a^{-1}\!a'\!\sigma'\tilde\varphi(2^qa)\|_\infty
\!+\! \|\sigma''\tilde\varphi(2^qa)\|_\infty \big) .
\end{align}
%
For \eqref{eq:mt08} we use the fundamental theorem of calculus to see
%
\begin{align}
&\eqref{eq:mt08} \\
&= \int_0^1 d\vartheta \, \partial_v \big( G'(v) \sigma(v) \Pi_{\x+\y}[\dumb;a(v)](\z) \big)_{|v=\vartheta \bar u(\x+\y)+(1-\vartheta)\bar u(\x)} \big( \bar u(\x+\y) - \bar u(\x)\big) \, ,
\end{align}
%
and deduce from Lemma~\ref{lem:integration3} with $\yy=\x+\y'$ that for $\lambda\leq2^{-n}$ 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\varphi_\x^\lambda(\z) \eqref{eq:mt08}^{(n),l,k} \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} \lambda^{2\alpha-2} [\dumb]_{2\alpha-2} \\
&\,\times \!
\big( \|a^{-2-\mathfrak{e}(\dumbsmall)}(a')^2\sigma^2\tilde\varphi(2^qa)\|_\infty 
\!+\! \|a^{-1-\mathfrak{e}(\dumbsmall)}a''\sigma^2\tilde\varphi(2^qa)\|_\infty
\!+\! \|a^{-1-\mathfrak{e}(\dumbsmall)}a'\sigma'\sigma\tilde\varphi(2^qa)\|_\infty \\
&\quad+ \|a^{-\mathfrak{e}(\dumbsmall)}\sigma''\sigma\tilde\varphi(2^qa)\|_\infty 
+ \|a^{-1-\mathfrak{e}(\dumbsmall)}a'\sigma\sigma'\tilde\varphi(2^qa)\|_\infty 
+ \|a^{-\mathfrak{e}(\dumbsmall)}(\sigma')^2\tilde\varphi(2^qa)\|_\infty \\
&\quad+ \|a^{-2-\mathfrak{e}(\dumbsmall)}a'\sigma^2\tilde\varphi(2^qa)\|_\infty 
+ \|a^{-1-\mathfrak{e}(\dumbsmall)}\sigma\sigma'\tilde\varphi(2^qa)\|_\infty \big) 
[\Theta(u)]_{B_{1,\infty}^\alpha} \|\y\|_\s^\alpha \, .
\end{align}
%
Similarly, we have by the fundamental theorem of calculus
%
\begin{align}
&\eqref{eq:mt09} \\
&= \!\int_0^1\! d\vartheta \, G''\big(\vartheta \bar u(\x\!+\!\y))+(1-\vartheta)\bar u(\x)\big) \big(\bar u(\x\!+\!\y)-\bar u(\x)\big) \bar\nu(\x\!+\!\y) \cdot \Pi_{\x+\y}[\xnoise](\z) \, ,
\end{align}
%
so that again by Lemma~\ref{lem:integration3} with $\yy=\x+\y'$ we obtain for $\lambda\leq2^{-n}$ 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\varphi_\x^\lambda(\z) \eqref{eq:mt09}^{(n),l,k} \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-1} [\xnoise]_{\alpha-1} 
[\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\y\|_\s^{\alpha/2} \|\Theta'(u)\nu\|_{L^2} \\
&\times \!
\big( \|a^{-2}(a')^2\sigma\tilde\varphi(2^qa)\|_\infty 
\!+\! \|a^{-1}\!a''\!\sigma\tilde\varphi(2^qa)\|_\infty
\!+\! \|a^{-1}\!a'\!\sigma'\tilde\varphi(2^qa)\|_\infty
\!+\! \|\sigma''\tilde\varphi(2^qa)\|_\infty \big) ,
\end{align}
%
where we used Cauchy-Schwarz in form of $\int d\x |\bar u(\x+\y)-\bar u(\x)| |\bar\nu(\x+\y)| \lesssim \|\bar u\|_{L^\infty}^{1/2} [\bar u]_{B_{1,\infty}^\alpha}^{1/2} \|\y\|_\s^{\alpha/2} \|\bar\nu\|_{L^2}$ 
and that $\|\bar u\|_{L^\infty}\lesssim1$ by construction.
For \eqref{eq:mt10} we have by Lemma~\ref{lem:integration3} with $\yy=\x+\y'$ that for $\lambda\leq2^{-n}$ 
%
\begin{align}
&\int_{D_{\y}\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\varphi_\x^\lambda(\z) \eqref{eq:mt10}^{(n),l,k} \Big| \\
&\lesssim 
2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-1} [\xnoise]_{\alpha-1} \\
&\,\times 
\big( \|a^{-1}a'\sigma\tilde\varphi(2^qa)\|_\infty 
+ \|\sigma'\tilde\varphi(2^qa)\|_\infty \big) [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
\|\y\|_\s^{\beta-1} \, .
\end{align}
%

We conclude the proof by balancing $a$ and $\sigma$.
For \eqref{eq:mt05} and \eqref{eq:mt10} we use
that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($N+M-2-(M-1)\geq M-1$, $N-1\geq M-1$)
%
\begin{equation}
\max\Big\{
\Big|\frac{a'\sigma}{a}\Big| \, , \
\big|\sigma'\big| \Big\} \lesssim a \, ,
\tag{III}\label{eq:III}
\end{equation}
%
so that $\|a^{-1}a'\sigma\tilde\varphi(2^qa)\|_\infty\lesssim 2^{-q}$ 
and $\|\sigma'\tilde\varphi(2^qa)\|_\infty\lesssim 2^{-q}$. 
Analogously, for \eqref{eq:mt06}, \eqref{eq:mt07}, and \eqref{eq:mt09} we use 
%\mt{this is most restricting}
%($2(M-2)+N-2(M-1)\geq M-1$, $M-3+N-(M-1)\geq M-1$, $N-2\geq M-1$)
%
\begin{equation}
\max\Big\{
\Big|\frac{(a')^2\sigma}{a^2}\Big| \, , \
\Big|\frac{a''\sigma}{a}\Big| \, , \
\Big|\frac{a'\sigma'}{a}\Big| \, , \
\big|\sigma''\big| \Big\} \lesssim a \, ,
\tag{IV}\label{eq:IV}
\end{equation}
%
and for \eqref{eq:mt06} additionally 
%($N-(M-1)\geq M-1$)
%
\begin{equation}
\Big|\frac{\sigma}{a^{\mathfrak{e}(\lollysmall)}}\Big| \lesssim a \, .
\tag{V}\label{eq:V}
\end{equation}
%
For \eqref{eq:mt08} we use  
%($2N-2\geq 2(M-1)$, $2N-1-(M-1)\geq2(M-1)$)
%
\begin{align}
\max\Big\{
\Big|\frac{(a')^2\sigma^2}{a^{2+\mathfrak{e}(\dumbsmall)}}\Big| , 
\Big|\frac{a''\sigma^2}{a^{1+\mathfrak{e}(\dumbsmall)}}\Big| , 
\Big|\frac{a'\sigma\sigma'}{a^{1+\mathfrak{e}(\dumbsmall)}}\Big| , 
\Big|\frac{\sigma\sigma''}{a^{\mathfrak{e}(\dumbsmall)}}\Big| , 
\Big|\frac{(\sigma')^2}{a^{\mathfrak{e}(\dumbsmall)}}\Big| , 
\Big|\frac{a'\sigma^2}{a^{2+\mathfrak{e}(\dumbsmall)}}\Big| , 
\Big|\frac{\sigma\sigma'}{a^{1+\mathfrak{e}(\dumbsmall)}}\Big| \Big\} \lesssim a \, ,
\tag{VI}
\end{align}
%
yielding the desired estimate. 
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Contributions of the renormalized kinetic measure}\label{sec:energy}

\begin{proof}[Proof of Proposition~\ref{prop:u2}]
The definition of $u_2^q$ in Section~\ref{sec:mild} yields
%
\begin{align}
&u_2^q(\x+\y)-u_2^q(\x)-\nabla u_2^q(\x)\cdot y\\
&=\!\int_{(0,\infty)\times\R^d}\! d\z \, \partial_v \bar\Psi_q\big(a(v),\x,\y,\z\big)_{|v=u(\z)} 
a(u(\z)) \big( |\nabla u(\z)|^2 \!-\! \sigma^2(u(\z)) \ccherry^{a(u(\z))}(r)\big) \, ,
\end{align}
%
where $\bar\Psi_q(a(v),\x,\y,\z)=\Psi_q(a(v),\x+\y-\z) - \Psi_q(a(v),\x-\z)
- \nabla \Psi_q(a(v),\x-\z)\cdot y$.
As in Section~\ref{sec:roughkernels} we replace $\Psi_q$ by $K$ defined in \eqref{eq:defK}, and we write $\bar K$ as in \eqref{eq:anisotropicTaylor} to denote the anisotropic Taylor remainder. 
Furthermore we momentarily write $K_1(\bar a,\x)\coloneqq\partial_{\bar a} K(\bar a,\x)$, and correspondingly $\bar K_1$ to denote its Taylor remainder. 
With this notation
%
\begin{align}
&u_2^q(\x+\y)-u_2^q(\x)-\nabla u_2^q(\x)\cdot y\\
&=\int_{(0,\infty)\times\R^{d}} \! d\z\, \K_1\big(a(u(\z)),\x,\y,\z\big) 
(a'\!a)(u(\z)) \Big( |\nabla u(\z)|^2 - \sigma^2(u(\z)) \ccherry^{a(u(\z))}(r) \Big) \, .
\end{align}
%
By the definition \eqref{eq:gubinelliderivative} of $\nu$, 
and using the same shorthand notation $\fnoise=f(u)$ and $\flolly=f'(u)$ as in the proof of Proposition~\ref{prop:u1}, 
we have 
%
\begin{align}
&\K_1(a(u(\z)),\x,\y,\z) a'(u(\z)) a(u(\z)) \Big( |\nabla u(\z)|^2 - \sigma^2(u(\z)) \ccherry^{a(u(\z))}(r) \Big) \\
&= \K_1(\anoise(\z),\x,\y,\z) \alolly(\z) \anoise(\z) \Big( 
\ssnoise(\z) |\nabla \Pi_\z[\lolly;\z](\z) |^2 - \ssnoise(\z) \ccherry^{\anoise(\z)}(r) \\
&\hphantom{=\K_1(\anoise(\z),\x,\y,\z) \alolly(\z) \anoise(\z)}
\,+ 2 \snoise(\z) \nabla \Pi_\z[\lolly;\z](\z) \cdot \nu(\z) 
+ |\nu(\z)|^2 \Big) \, ,
\end{align}
%
which by the definition \eqref{eq:derivativecherry} of $\Pi[\derivativecherry]$ equals
%
\begin{align}
&\K_1(\anoise(\z),\x,\y,\z) \alolly(\z)
\anoise(\z)\ssnoise(\z) \Pi_\z[\derivativecherry,\z](\z) \label{eq:u2part1} \\
&+ 2 \K_1(\anoise(\z),\x,\y,\z) \alolly(\z) \anoise(\z) \snoise(\z) \nabla \Pi_\z[\lolly;\z](\z) \cdot \nu(\z) \label{eq:u2part2} \\
&+ \K_1(\anoise(\z),\x,\y,\z) \alolly(\z) \anoise(\z) |\nu(\z)|^2 \label{eq:u2part3} \, .
\end{align}
%
We estimate these three contributions separately in the following three steps. 

\textbf{Step 1 \textnormal{(estimate of \eqref{eq:u2part1})}.}
To estimate \eqref{eq:u2part1} we define 
%
\begin{equation}\label{eq:F1}
F_\x(\z;\yy) \coloneqq 
K_1\big(\anoise(\x),\yy-\z\big) \alolly(\x) \anoise(\x) \ssnoise(\x) \Pi_\x[\derivativecherry;\x](\z) \, ,
\end{equation}
%
and note that 
%
\begin{equation}
F_\z(\z;\yy) 
= K_1\big(\anoise(\z),\yy-\z\big) \alolly(\z) \anoise(\z) \ssnoise(\z) \Pi_\z[\derivativecherry;\z](\z) \, .
\end{equation}
%
Hence (recall from Lemma~\ref{lem:reconstruction0} that $\bar F$ denotes the Taylor remainder of $F$)
%
\begin{align}
\eqref{eq:u2part1} 
&= \bar F_\z(\z;\x,\y) \\
&= \bar F_\z(\z;\x,\y) - \bar F_\x(\z;\x,\y) + \bar K_1(\anoise(\x),\x,\y,\z) \alolly(\x)\anoise(\x)\ssnoise(\x)\Pi_\x[\derivativecherry;\x](\z) \, .
\end{align}
%
The following lemma verifies the assumption of Lemma~\ref{lem:reconstruction0} 
(recall that $F^{(n),l,k}$ is defined analogously to $F$ with $K$ replaced by $\partial_t^l\partial_x^k K^{(n)}$). 
Note that as in the proof of Proposition~\ref{prop:u1}, 
due to the presence of $\sigma$ and its compact support we may assume w.l.o.g.~that $a\leq1$ and consider only $q\in\N$. 

\begin{lemma}\label{lem:reconstruction2}
Let $n,l,q\in\N$, $k\in\N^d$, $\y,\y'\in\mathfrak{K}\subseteq\R\times\R^d$ for compact $\mathfrak{K}$, $0<\lambda\leq2^{-n}$,
and $\varphi\in\mathcal{B}$.
Then $F$ defined in \eqref{eq:F1} satisfies
%
\begin{align}
&\int_{D_\y\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\big( F_{\x+\y}^{(n),l,k}(\z;\x+\y') - F_\x^{(n),l,k}(\z;\x+\y') \big) 
\varphi_\x^\lambda(\z) \Big| \\
&\lesssim 2^{n(D-2+2l+|k|_1)} \lambda^{2\alpha-2} \|\y\|_\s^\alpha [\derivativecherry]_{2\alpha-2} [\Theta(u)]_{B_{1,\infty}^\alpha} 2^{-q(1-\alpha/2)} \, ,
\end{align}
%
where $\Theta$ is as in \eqref{eq:Theta}, and $\lesssim$ depends on $\mathfrak{K}$ and the constant $C$ of Assumption~\ref{ass:nonlinearities}. 
\end{lemma}

Before giving the proof of Lemma~\ref{lem:reconstruction2} at the end of the section 
we continue Step 1 in the proof of Proposition~\ref{prop:u2}.
We have by the triangle inequality 
%
\begin{align}
&\int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \eqref{eq:u2part1} \Big| \\
&\leq \int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \big(
\bar F_\z(\z;\x,\y) - \bar F_\x(\z;\x,\y)\big) \Big| \\
&\,+ \int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\bar K_1(\anoise(\x),\x,\y,\z) \alolly(\x)\anoise(\x)\ssnoise(\x)\Pi_\x[\derivativecherry;\x](\z) \Big|  \, .
\end{align}
%
Lemma \ref{lem:reconstruction2} verifies the assumption of Lemma~\ref{lem:reconstruction0} with 
$(\theta_1,\theta_2)=(2\alpha-2,\alpha)$, 
where we note that by assumption $3\alpha-2>0$. 
Thus by Lemma~\ref{lem:reconstruction0} the first right hand side term is bounded by
%
\begin{equation}
[\derivativecherry]_{2\alpha-2} [\Theta(u)]_{B_{1,\infty}^\alpha} 2^{-q(1-\alpha/2)} 2^{q(\alpha+2)/2} \|\y\|_\s^{2-} \, .
\end{equation}
%
To estimate the second right hand side term we apply Lemma~\ref{lem:integration2} 
with $m=1$, $f_\x=\alolly(\x)\anoise(\x)\ssnoise(\x)\Pi_\x[\derivativecherry;\x]$, $\theta_1=2\alpha-2$, and $\theta_2=0$, hence it is estimated by 
%
\begin{equation}
\|\y\|_\s^{2\alpha} [\derivativecherry]_{2\alpha-2} \int_{D_\y} d\x \, 
\Big| \frac{\alolly(\x)\anoise(\x)\ssnoise(\x)\tilde\varphi(2^q\anoise(\x))}{\anoise(\x)^{1+1+\mathfrak{e}(\cherrysmall)}}\Big| \, ,
\end{equation}
%
where we have directly used \eqref{eq:modelbound} along with $\Pi_\x[\derivativecherry]=\Pi_\y[\derivativecherry]$ (see \eqref{eq:trafoderivativecherry}). 
Using that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($-1+2N-2(M-1)\geq-\alpha(M-1)$)
%
\begin{equation}
\Big|\frac{a'\sigma^2}{a^{1+\mathfrak{e}(\cherrysmall)}}\Big| \lesssim \frac{1}{a^\alpha} \, ,
\tag{VII}
\end{equation}
%
we deduce by $\|\y\|_\s\leq R\leq1$
%
\begin{equation}
\int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \eqref{eq:u2part1} \Big| 
\lesssim 2^{q\alpha} \|\y\|_\s^{2\alpha} [\derivativecherry]_{2\alpha-2} \big([\Theta(u)]_{B_{1,\infty}^\alpha} + T\big) \, .
\end{equation}
%
Summation over $q\in\N$ with $\delta<2^{-q}$ yields the desired bound.

\textbf{Step 2 \textnormal{(estimate of \eqref{eq:u2part2})}.}
To estimate \eqref{eq:u2part2} we proceed analogously to Step~1 and define 
%
\begin{equation}\label{eq:F2}
F_\x(\z;\yy) 
\coloneqq K_1(\anoise(\x),\yy-\z) \alolly(\x) \anoise(\x) \snoise(\x) \nabla \Pi_\x[\lolly;\x](\z) \cdot \nu(\x) \, .
\end{equation}
%
We then have the following analogue of Lemma~\ref{lem:reconstruction2}, again only for $q\in\N$. 
%
\begin{lemma}\label{lem:reconstruction3}
Let $n,l,q\in\N$, $k\in\N^d$, $\y,\y'\in\mathfrak{K}\subseteq\R\times\R^d$ for compact $\mathfrak{K}$, $0<\lambda\leq2^{-n}$, $\varphi\in\mathcal{B}$, $\beta\in(1,2)$, and $\bar\alpha\coloneqq\min\{\alpha/2,\beta-1\}$.
Then $F$ defined in \eqref{eq:F2} satisfies
%
\begin{align}
&\int_{D_\y\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F_{\x+\y}^{(n),l,k}(\z;\x+\y') - F_\x^{(n),l,k}(\z;\x+\y') \big) 
\varphi_\x^\lambda(\z) \Big| \\
&\lesssim 2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-1} \|\y\|_\s^{\bar\alpha} 
[\lolly]_{\alpha} 
\Big( [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
+ [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2} \Big) 2^{-q/2} \, ,
\end{align}
%
where $\Theta$ is as in \eqref{eq:Theta}, and $\lesssim$ depends on $\mathfrak{K}$ and the constant $C$ of Assumption~\ref{ass:nonlinearities}.
\end{lemma}
%

Before giving the proof of Lemma~\ref{lem:reconstruction3} at the end of the section 
we continue Step~2 in the proof of Proposition~\ref{prop:u2}. 
By the triangle inequality 
%
\begin{align}
&\int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \eqref{eq:u2part2} \Big| \\
&\leq \int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \big(
\bar F_\z(\z;\x,\y) - \bar F_\x(\z;\x,\y)\big) \Big| \\
&\,+ \int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\bar K_1(\anoise(\x),\x,\y,\z) \alolly(\x)\anoise(\x)\snoise(\x)\nabla\Pi_\x[\lolly;\x](\z) \cdot\nu(\x)\Big| \, .
\end{align}
%
Lemma~\ref{lem:reconstruction3} verifies the assumption of Lemma~\ref{lem:reconstruction0} with $\theta_1=\alpha-1$ and $\theta_2=\min\{\alpha/2,\beta-1\}$. 
Since by assumption $\alpha-2+\beta>0$ and $3\alpha-2>0$, 
the first right hand side term is estimated by 
%
\begin{equation}
[\lolly]_\alpha \Big( [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
+ [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2} \Big) 
2^{-q/2}2^{q(2\alpha+1)/2} \|\y\|_\s^{2-} \, ,
\end{equation}
%
where we have directly used that $\min\{\alpha/2,\beta-1\}\leq 2\alpha-1$.
To estimate the second right hand side term we apply Lemma~\ref{lem:integration2} 
with $m=1$, $f_\x=\alolly(\x)\anoise(\x)\snoise(\x)\nu(\x)\cdot\nabla\Pi_\x[\lolly;\x]$, $\theta_1=\alpha-1$, and $\theta_2=0$, 
hence it is estimated by 
%
\begin{equation}
\|\y\|_\s^{\alpha+1} [\lolly]_{\alpha} \int_{D_\y} d\x \, 
\Big| \frac{\alolly(\x)\anoise(\x)\snoise(\x)\nu(\x)\tilde\varphi(2^q\anoise(\x))}{\anoise(\x)^{1+1+\mathfrak{e}(\lollysmall)}}\Big| \, ,
\end{equation}
%
where we have directly used \eqref{eq:modelbound} along with $\nabla\Pi_\x[\lolly]=\nabla\Pi_\y[\lolly]$ (see \eqref{eq:trafololly}). 
Using \eqref{eq:Theta} and that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($-1+N-(M-1)\geq-\alpha(M-1)$)
%
\begin{equation}
\Big|\frac{a'\sigma}{a^{1+\mathfrak{e}(\lollysmall)}}\Big| \lesssim \frac{1}{a^\alpha} 
\tag{VIII}
\end{equation}
%
we deduce by $\|\y\|_\s\leq R\leq1$
%
\begin{align}
&\int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \eqref{eq:u2part2} \Big| \\
&\lesssim 2^{q\alpha} \|\y\|_\s^{\alpha+1} [\lolly]_\alpha 
\Big( [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
+ [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2}
+ \|\Theta'(u)\nu\|_{L^1} \Big) \, .
\end{align}
%
Summation over $q\in\N$ with $\delta<2^{-q}$ yields the desired bound.

\textbf{Step 3 \textnormal{(estimate of \eqref{eq:u2part3})}.}
Applying Lemma~\ref{lem:integration1} (with $m=1$, $f=a(u)$, $g=a'(u)a(u)|\nu|^2$) yields\footnote{It is here where the blowup of $[\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}}$ in Proposition~\ref{prop:u>} in terms of $2^q$ and ultimately $\delta$ comes from, as there is no $\sigma$ to compensate.}
%
\begin{align}
&\int_{D_\y}d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, \eqref{eq:u2part3} \Big| \\
&\lesssim T^{1-\alpha} \|\y\|_\s^{2\alpha} 
\int_{(0,T)\times\T^d} d\z \, |a'(u(\z))| (1+a(u(\z))^{-\alpha}) |\tilde\varphi(2^qa(u(\z)))| |\nu(\z)|^2 \, .
\end{align}
%
Summing over $q\in\Z$ with $\delta<2^{-q}$ we argue as in the proof of Proposition~\ref{prop:u0} to estimate $\sum_{\delta<2^{-q}} a^{-\epsilon}(1+a^{-\alpha})|\tilde\varphi(2^qa)|\lesssim \delta^{-\alpha-\epsilon}$ for any $\epsilon>0$, 
so it is left to estimate 
%
\begin{equation}
\int_{(0,T)\times\T^d} d\z \, |a'(u(\z))| a(u(\z))^\epsilon |\nu(\z)|^2 \, .
\end{equation}
%
This is achieved in the following proposition.  

\begin{proposition}\label{prop:energy}
Let the assumption of Theorem~\ref{thm:main} hold,
in particular let u be the solution of \eqref{eq:spm} and $\nu$ be given in \eqref{eq:gubinelliderivative}. 
Furthermore let $g(v)=\int_0^vdw\,|w|^{p-2}$ for $p>1$.
Then for $T\leq1$ and $\beta\in(2-\alpha,2\alpha]$
%
\begin{equation}
\int_{(0,T)\times\T^d} d\z \, |g'(u(\z))|\,a(u(\z)) |\nu(\z)|^2 
\lesssim \|u_0\|_{L^p(\T^d)}^p + C_{\eqref{eq:u2part3}} + 1 \, , 
% +1 comes from the counterterm bounds 
\end{equation}
%
where $\lesssim$ depends on $\beta$ and the constants $C$ of Assumptions~\ref{ass:nonlinearities} and~\ref{ass:noise}, 
and 
%
\begin{align}
&C_{\eqref{eq:u2part3}} \\
&=
%
[\xi]_{\alpha-2} 
\Big( [(g\sigma)(\mathcal{U})]_{B^{\beta}_{1,\infty}} 
+ (\sqrt{T})^{\alpha} \Big) \\
%
&+\! \big( [\dumb]_{2\alpha-2} + [\derivativecherry]_{2\alpha-2} \big)
\Big( [\Theta(u)]_{B^\alpha_{1,\infty}} 
+ (\sqrt{T})^{2\alpha} \Big) \\
%
&+\! \big( [\xnoise]_{\alpha-1} \!+\! [\lolly]_\alpha \big) \!
\Big( [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}}
\!+\! [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2} 
\!+\! \|\Theta'(u)\nu\|_{L^1} (\sqrt{T})^{\alpha-1} \Big) ,
\end{align}
%
with $\Theta$ from \eqref{eq:Theta}.
\end{proposition}
%
The proof of Proposition~\ref{prop:energy} is given at the end of this section. 
%
To continue with Step~3 in the proof of Proposition~\ref{prop:u2} we use Proposition~\ref{prop:energy} with $p=1+\epsilon(M-1)$, 
so that by Assumption~\ref{ass:nonlinearities} we have 
$|a'(u)|a(u)^{\epsilon-1}\lesssim |u|^{-1+\epsilon(M-1)}=|u|^{p-2}$.
It follows 
%
\begin{equation}
\int_{(0,T)\times\T^d}d\z \, |a'(u(\z))|a(u(\z))^\epsilon|\nu(\z)|^2
\lesssim \|u_0\|_{L^{1+\epsilon(M-1)}(\T^d)}^{1+\epsilon(M-1)} + C_{\eqref{eq:u2part3}} + 1 \, .
\end{equation}
%
Combining Steps~1 -- 3 finishes the proof of Proposition~\ref{prop:u2}.
\end{proof}

