\begin{proof}[Proof of Lemma~\ref{lem:reconstruction2}]
We have by the definition of $F$ in \eqref{eq:F1}
%
\begin{align}
&F_{\x+\y}(\z;\yy) - F_\x(\z;\yy) \\
&= K_1\big(\anoise(\x+\y),\yy-\z\big) \alolly(\x+\y) \anoise(\x+\y) \ssnoise(\x+\y) \Pi_{\x+\y}[\derivativecherry;\x+\y](\z) \\
&\, - K_1\big(\anoise(\x),\yy-\z\big) \alolly(\x) \anoise(\x) \ssnoise(\x) \Pi_\x[\derivativecherry;\x](\z) \\
&= K_1\big(\anoise(\x+\y),\yy-\z\big) \alolly(\x+\y) \anoise(\x+\y) \ssnoise(\x+\y) \Pi_{\x}[\derivativecherry;\x+\y](\z) \\
&\, - K_1\big(\anoise(\x),\yy-\z\big) \alolly(\x) \anoise(\x) \ssnoise(\x) \Pi_{\x}[\derivativecherry;\x](\z) \, ,
\end{align}
%
where in the second equality we have used \eqref{eq:trafoderivativecherry} 
in form of $\Pi_\x[\derivativecherry;\x] = \Pi_{\x+\y}[\derivativecherry;\x]$. 
Denoting $G(v)\coloneqq K_1(a(v),\yy-\z)a'(v)a(v)\sigma^2(v)\Pi_{\x}[\derivativecherry;a(v)](\z)$ and observing that $G(u)=G(\bar u)$ for $\bar u\coloneqq\Theta(u)$ with $\Theta$ from \eqref{eq:Theta}, 
we obtain from the fundamental theorem of calculus 
%
\begin{align}
&F_{\x+\y}(\z;\yy) - F_\x(\z;\yy) = \int_0^1 d\vartheta \, G'\big(\vartheta \bar u(\x+\y)+(1-\vartheta) \bar u(\x)\big) \big(\bar u(\x+\y)-\bar u(\x)\big) \, .
\end{align}
%
Denoting $K_{11}(\bar a,\x)\coloneqq\partial_{\bar a}^2 K(\bar a,\x)$ note that 
%
\begin{align}
G'(v)
&= K_{11}(a(v),\yy-\z)(a'(v))^2a(v)\sigma^2(v)\Pi_{\x}[\derivativecherry;a(v)](\z) \\
&\,+ K_1(a(v),\yy-\z)\big(a'a\sigma^2)'(v)\Pi_{\x}[\derivativecherry;a(v)](\z) \\
&\,+ K_1(a(v),\yy-\z)a'(v)a(v)\sigma^2(v)\partial_{a}\Pi_{\x}[\derivativecherry;a(v)](\z)a'(v) \, ,
\end{align}
%
so that we can apply Lemma~\ref{lem:integration3} to obtain for $\lambda\leq2^{-n}$
%
\begin{align}
&\int_{D_\y\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\big( F_{\x+\y}^{(n),l,k}(\z;\x+\y') - F_\x^{(n),l,k}(\z;\x+\y') \big) \varphi_\x^\lambda(\z) \Big| \\
&\lesssim 	2^{n(D-2+2l+|k|_1)} \lambda^{2\alpha-2} [\derivativecherry]_{2\alpha-2} 
[\Theta(u)]_{B_{1,\infty}^\alpha} \|\y\|_\s^\alpha \\
&\,\times \big(
\|a^{-2-\mathfrak{e}(\cherrysmall)} (a')^2 a \sigma^2 \tilde\varphi(2^q a)\|_\infty 
+ \|a^{-1-\mathfrak{e}(\cherrysmall)} (a' a \sigma^2)' \tilde\varphi(2^q a)\|_\infty \big) \, .
\end{align}
%
The claim follows by using that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($2(M-2)+2N-3(M-1)\geq(1-\alpha/2)(M-1)$)
%
\begin{equation}
\max\Big\{
\Big|\frac{(a')^2\sigma^2}{a^{1+\mathfrak{e}(\cherrysmall)}}\Big| \, , \ 
\Big|\frac{(a'a\sigma^2)'}{a^{1+\mathfrak{e}(\cherrysmall)}}\Big| \Big\} \lesssim a^{1-\alpha/2} \, , 
\tag{IX}
\end{equation}
%
so that $\|a^{-1-\mathfrak{e}(\cherrysmall)} (a')^2 \sigma^2 \tilde\varphi(2^q a)\|_\infty\lesssim 2^{-q(1-\alpha/2)}$, 
and similarly for the remaining $\|\cdot\|_\infty$ term. 
\end{proof}

