\begin{proof}[Proof of Lemma~\ref{lem:reconstruction3}]
We have by the definition of $F$ in \eqref{eq:F2}
%
\begin{align}
&F_{\x+\y}(\z;\yy) - F_\x(\z;\yy) \\
&= K_1\big(\anoise(\x+\y),\yy-\z\big) \alolly(\x\!+\!\y) \anoise(\x\!+\!\y) \snoise(\x\!+\!\y) \nabla\Pi_{\x+\y}[\lolly;\x+\y](\z) \cdot \nu(\x\!+\!\y) \\
&\, - K_1\big(\anoise(\x),\yy-\z\big) \alolly(\x) \anoise(\x) \snoise(\x) \nabla\Pi_\x[\lolly;\x](\z) \cdot \nu(\x) \\
&= K_1\big(\anoise(\x+\y),\yy-\z\big) \alolly(\x+\y) \anoise(\x+\y) \snoise(\x+\y) \nabla\Pi_{\x}[\lolly;\x+\y](\z) \cdot \nu(\x\!+\!\y) \\
&\,- K_1\big(\anoise(\x+\y),\yy-\z\big) \alolly(\x+\y) \anoise(\x+\y) \snoise(\x+\y) \nabla\Pi_{\x}[\lolly;\x+\y](\z) \cdot \nu(\x) \\
&\,+ K_1\big(\anoise(\x+\y),\yy-\z\big) \alolly(\x+\y) \anoise(\x+\y) \snoise(\x+\y) \nabla\Pi_{\x}[\lolly;\x+\y](\z) \cdot \nu(\x) \\
&\, - K_1\big(\anoise(\x),\yy-\z\big) \alolly(\x) \anoise(\x) \snoise(\x) \nabla\Pi_{\x}[\lolly;\x](\z) \cdot \nu(\x) \, ,
\end{align}
%
where in the second equality we have used \eqref{eq:trafololly} 
in form of $\nabla\Pi_\x[\lolly;\x] = \nabla\Pi_{\x+\y}[\lolly;\x]$. 
Again we replace all instances of $u$ by $\bar u\coloneqq\Theta(u)$ with $\Theta$ from \eqref{eq:Theta}, 
and we replace $\nu$ by $\bar\nu\coloneqq\Theta'(u)\nu$ (for the first and last term this is justified by the presence of $\sigma$, while the two middle terms cancel anyway).
Denoting $G(v)\coloneqq K_1(a(v),\yy-\z) a'(v) a(v)\sigma(v) \nabla\Pi_\x[\lolly;a(v)](\z)$, 
we obtain from the fundamental theorem of calculus
%
\begin{align}
&F_{\x+\y}(\z;\yy) - F_\x(\z;\yy) \\
&=G\big(\bar u(\x+\y)\big) \cdot \big(\bar\nu(\x+\y)-\bar\nu(\x)\big) \\
&\,+ \int_0^1 d\vartheta \, G'\big(\vartheta \bar u(\x+\y)+(1-\vartheta)\bar u(\x)\big) \big(\bar u(\x+\y)-\bar u(\x)\big) \cdot \bar\nu(\x) \, .
\end{align}
%
Note that (using $K_{11}(\bar a,\x)=\partial_{\bar a}^2K(\bar a,\x)$ as in the proof of Lemma~\ref{lem:reconstruction2})
%
\begin{align}
G'(v)
&= K_{11}(a(v),\yy-\z) (a'(v))^2 a(v) \sigma(v) \nabla\Pi_\x[\lolly;a(v)](\z) \\
&\,+ K_1(a(v),\yy-\z) (a' a \sigma)'(v) \nabla\Pi_\x[\lolly;a(v)](\z) \\
&\,+ K_1(a(v),\yy-\z) a'(v) a(v)\sigma(v) \partial_a\nabla\Pi_\x[\lolly;a(v)](\z) a'(v) \, ,
\end{align}
%
so that we can apply Lemma~\ref{lem:integration3} to obtain for $\lambda\leq2^{-n}$
%
\begin{align}
&\int_{D_\y\cap D_{\y'}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\big( F_{\x+\y}^{(n),l,k}(\z;\x+\y') - F_\x^{(n),l,k}(\z;\x+\y') \big) \varphi_\x^\lambda(\z) \Big| \\
&\lesssim 	2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-1} [\lolly]_{\alpha} [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} \|\y\|_\s^{\beta-1} \|a^{-1-\mathfrak{e}(\lollysmall)}a'a\sigma\tilde\varphi(2^q a)\|_\infty \\
&\,+ 	2^{n(D-2+2l+|k|_1)} \lambda^{\alpha-1} [\lolly]_{\alpha} 
[\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\y\|_\s^{\alpha/2} \|\Theta'(u)\nu\|_{L^2} \\
&\,\times \big(
\|a^{-2-\mathfrak{e}(\lollysmall)} (a')^2 a \sigma \tilde\varphi(2^q a)\|_\infty
+ \|a^{-1-\mathfrak{e}(\lollysmall)} (a' a \sigma)' \tilde\varphi(2^q a)\|_\infty \big) \, .
\end{align}
% 
As in the estimate of \eqref{eq:mt09} in the proof of Lemma~\ref{lem:reconstruction1} we have used Cauchy-Schwarz and $\|\bar u\|_{L^\infty}\lesssim1$.
The claim follows by using that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply
%($M-2+N-(M-1)\geq(M-1)/2$, $2(M-2)+N-2(M-1)\geq(M-1)/2$, $M-2+M-1+N-1-2(M-1)\geq(M-1)/2$)
%
\begin{equation}
\max\Big\{
\Big|\frac{a'\sigma}{a^{\mathfrak{e}(\lollysmall)}}\Big| \, , \ 
\Big|\frac{(a')^2\sigma}{a^{1+\mathfrak{e}(\lollysmall)}}\Big| \, , \ 
\Big|\frac{(a'a\sigma)'}{a^{1+\mathfrak{e}(\lollysmall)}}\Big| \Big\} \lesssim a^{1/2} \, , 
\tag{X}
\end{equation}
%
so that $\|a^{-1-\mathfrak{e}(\lollysmall)}a'a\sigma\tilde\varphi(2^q a)\|_\infty\lesssim 2^{-q/2}$, 
and similarly for the remaining $\|\cdot\|_\infty$ terms. 
\end{proof}

