\begin{proof}[Proof of Proposition~\ref{prop:energy}]
Let 
%
\begin{equation}
g'(v)\coloneqq |v|^{p-2} \, ,\quad 
g(v)\coloneqq \int_0^v dw \, g'(w) \, ,\quad\textnormal{and}\quad
G(v)\coloneqq \int_0^v dw \, g(w) \, .
\end{equation}
%
Then $G\in C^1(\R)\cap C^2(\R\setminus\{0\})$ (with derivative $g$, the derivative of which is $g'$), 
$G\geq0$,
and by Assumption~\ref{ass:nonlinearities} $g'\sigma\in C^1(\R)$. 

By the chain rule and \eqref{eq:spm} 
%
\begin{equation}
\partial_t G(u)
= g(u)\partial_t u 
= g(u) \Big( \nabla\cdot \big(a(u)\nabla u\big) 
+ \sigma(u)\xi 
- \sigma'(u)\sigma(u) C^{a(u)} \Big) \, .
\end{equation}
%
Integration over $(0,T)\times\T^d$ and integrating by parts\footnote{which can be made rigorous by an approximation argument, e.g.~replace $g'(v)$ by $(|v|+\epsilon)^{p-2}$ and appeal to the monotone convergence theorem} yields
%
\begin{align}
&\int_{\T^d} dz\, \big(G(u(T,z))-G(u(0,z))\big)
+ \int_{(0,T)\times\T^d} d\z\, g'(u(\z)) a(u(\z)) |\nabla u(\z)|^2 \\
&= \int_{(0,T)\times\T^d} d\z\, g(u(\z)) \Big( \sigma(u(\z)) \xi(\z) 
- \sigma'(u(\z))\sigma(u(\z)) C^{a(u(\z))} \Big) \, .
\end{align}
%
Again, the left as well as the right hand side of this equality are problematic as 
$|\nabla u|^2$ is a singular product and similarly $g(u)$ multiplied with the renormalized product of $\sigma(u)$ and $\xi$ is singular. 
Luckily it turns out that both need the same counterterm 
(up to an integrable blowup), 
which we now subtract from the equality to arrive at 
%
\begin{align}
&\int_{\T^d} dz\, \big(G(u(T,z))-G(u(0,z))\big) \\
&\,+ \int_{(0,T)\times\T^d} d\z\, g'(u(\z)) a(u(\z)) \Big( |\nabla u(\z)|^2 - \sigma^2(u(\z)) \ccherry^{a(u(\z))}(r) \Big) \\
&= \int_{(0,T)\times\T^d} d\z\, \Big( g(u(\z)) \sigma(u(\z)) \xi(\z) 
- (g\sigma)'(u(\z))\sigma(u(\z)) \cdumb^{a(u(\z))}(r) \Big) \\
&\,+ \int_{(0,T)\times\T^d} d\z\, g'(u(\z)) \sigma^2(u(\z)) 
\Big( \cdumb^{a(u(\z))}(r) - a(u(\z)) \ccherry^{a(u(\z))}(r) \Big) \\
&\,+ \int_{(0,T)\times\T^d} d\z\, g(u(\z)) \sigma'(u(\z)) \sigma(u(\z)) 
\Big( \cdumb^{a(u(\z))}(r) - C^{a(u(\z))} \Big) \, .
\end{align}
%
Along the lines that led to \eqref{eq:u2part1} -- \eqref{eq:u2part3} 
we use the definitions \eqref{eq:gubinelliderivative} of $\nu$ and \eqref{eq:derivativecherry} of  $\Pi[\derivativecherry]$ to rewrite 
%
\begin{align}
&|\nabla u(\z)|^2 - \sigma^2(u(\z)) \ccherry^{a(u(\z))}(r) \\
&=\sigma^2(u(\z)) \Pi_\z[\derivativecherry,\z](\z) 
+ 2 \sigma(u(\z)) \nabla \Pi_\z[\lolly;\z](\z) \cdot \nu(\z) 
+ |\nu(\z)|^2
\end{align}
%
We thus obtain 
%
\begin{align}
&\int_{\T^d} dz\, G(u(T,z))
+ \int_{(0,T)\times\T^d} d\z \, g'(u(\z)) a(u(\z)) |\nu(\z)|^2 \\
&= \int_{\T^d} dz\, G(u(0,z)) \\
&\,+ \int_{(0,T)\times\T^d} d\z\, \Big( g(u(\z)) \sigma(u(\z)) \xi(\z) 
- (g\sigma)'(u(\z))\sigma(u(\z)) \cdumb^{a(u(\z))}(r) \Big) 
 \label{eq:energy1} \\
&\, - \int_{(0,T)\times\T^d} d\z\, (g'a\sigma)(u(\z)) 
\Big(\sigma(u(\z)) \Pi_\z[\derivativecherry;\z](\z)
+ 2 \nabla \Pi_\z[\lolly;\z](\z) \cdot \nu(\z) \Big) \label{eq:energy2} \qquad \\
&\,+ \int_{(0,T)\times\T^d} d\z\, g'(u(\z)) \sigma^2(u(\z)) 
\Big( \cdumb^{a(u(\z))}(r) - a(u(\z)) \ccherry^{a(u(\z))}(r) \Big) \\
&\,+ \int_{(0,T)\times\T^d} d\z\, g(u(\z)) \sigma'(u(\z)) \sigma(u(\z)) 
\Big( \cdumb^{a(u(\z))}(r) - C^{a(u(\z))} \Big) \, .
\end{align}
%
Since $G\geq0$ and $g'(u)a(u)|\nu|^2\geq0$, 
the claim thus follows from estimating the right hand side. 

Note that $G(v)=|v|^p/(p(p-1))$, hence the first right hand side term is estimated by 
$\|u_0\|_{L^p(\T^d)}^p$. 
%
For the last two terms of the right hand side, 
note that $|g'(u)\sigma^2(u)|\lesssim|\sigma^2(u)/u|$ 
and $|g(u)\sigma'(u)\sigma(u)|\lesssim|\sigma'(u)\sigma(u)|$ 
by $p>1$ and the compact support of $\sigma$ from Assumption~\ref{ass:nonlinearities}, 
hence both terms are estimated by a constant as a consequence of Assumption~\ref{ass:noise}. 

To estimate \eqref{eq:energy1} and \eqref{eq:energy2}
we aim to apply Lemma~\ref{lem:reconstruction4}. 
For \eqref{eq:energy2} define 
%
\begin{equation}
F_\x(\z)\coloneqq 
(g'a\sigma^2)(u(\x)) \Pi_\x[\derivativecherry;\x](\z)
+ 2(g'a\sigma)(u(\x)) \nabla\Pi_\x[\lolly;\x](\z) \cdot \nu(\x) \, ,
\end{equation}
%
such that 
%
\begin{equation}
\eqref{eq:energy2} = \int_{(0,T)\times\T^d} d\z \, F_\z(\z) \, .
\end{equation}
%
Analogous to the proof of Lemma~\ref{lem:reconstruction2} and Lemma~\ref{lem:reconstruction3} (setting $K_1=1$ and $\alolly=g'(u)$) 
we have for $\y\in\mathfrak{K}\subseteq\R\times\R^d$ for compact $\mathfrak{K}$, $0<\lambda\leq\sqrt{T}$, and $\varphi\in\mathcal{B}$ 
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z\, 
\big( F_{\x+\y}(\z) - F_\x(\z) \big) \varphi_\x^\lambda(\z) \Big| \\
&\lesssim 
\lambda^{2\alpha-2} \|\y\|_\s^\alpha 
[\derivativecherry]_{2\alpha-2} [\Theta(u)]_{B_{1,\infty}^\alpha} 
\big( \|a^{-\mathfrak{e}(\cherrysmall)}(g'a\sigma^2)'\|_\infty + \|a^{-1-\mathfrak{e}(\cherrysmall)}g'a'a\sigma^2\|_\infty\big) \\
&\,+ \lambda^{\alpha-1} \|\y\|_\s^{\beta-1} 
[\lolly]_\alpha [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} \|a^{-\mathfrak{e}(\lollysmall)}g'a\sigma\|_\infty \\
&\,+ \lambda^{\alpha-1} \|\y\|_\s^{\alpha/2}
[\lolly]_\alpha [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2} 
\big( \|a^{-\mathfrak{e}(\lollysmall)} (g'\!a\sigma)'\|_\infty + \|a^{-1-\mathfrak{e}(\lollysmall)}g'\!a'a\sigma\|_\infty\big) \, .
\end{align}
%
Using that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($-1+M-1+2N-1-2(M-1)\geq0$, $-1+N\geq0$, $-1+M-1+N-1-(M-1)\geq0$)
%
\begin{equation}
\max\Big\{
\Big|\frac{(g'a\sigma^2)'}{a^{\mathfrak{e}(\cherrysmall)}}\Big| \, , \ 
\Big|\frac{g'a'\sigma^2}{a^{\mathfrak{e}(\cherrysmall)}}\Big| \, , \ 
\big|\frac{g'\sigma}{a^{\mathfrak{e}(\lollysmall)-1}}\big| \, , \ 
\Big|\frac{(g'a\sigma)'}{a^{\mathfrak{e}(\lollysmall)}}\Big| \, , \ 
\Big|\frac{g'a'\sigma}{a^{\mathfrak{e}(\lollysmall)}}\Big| \Big\} \lesssim 1 \, , 
\tag{XI}
\end{equation}
%
this right hand side is estimated by 
%
\begin{align}
\lambda^{2\alpha-2} (\lambda+\|\y\|_\s)^{\bar\alpha}
\big( [\derivativecherry]_{2\alpha-2} [\Theta(u)]_{B_{1,\infty}^\alpha}
&+ [\lolly]_\alpha [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} \\
&+ [\lolly]_\alpha [\Theta(u)]_{B_{1,\infty}^\alpha} \|\Theta'(u)\nu\|_{L^2} \big) \, ,
\end{align}
%
where $\bar\alpha=\min\{\alpha,\beta-\alpha,1-\alpha/2\}$.
Furthermore, using \eqref{eq:Theta} and the modelbound \eqref{eq:modelbound} combined with 
$\Pi_\x[\derivativecherry]=\Pi_\y[\derivativecherry]$ and $\nabla\Pi_\x[\lolly]=\nabla\Pi_\y[\lolly]$ (see \eqref{eq:trafoderivativecherry} and \eqref{eq:trafololly}), 
yields for $\lambda\leq\sqrt{T}$ and $0\leq\bar t\leq T$
%
\begin{align}
&\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_\x(\z) \psi_{\x-(\bar{t},0)}^{\lambda}(\z) \Big| \\
&\lesssim \lambda^{2\alpha-2} 
[\derivativecherry]_{2\alpha-2} T \|a^{-\mathfrak{e}(\cherrysmall)}g'a\sigma^2\|_\infty 
+ \lambda^{\alpha-1} 
[\lolly]_\alpha \|\Theta'(u)\nu\|_{L^1} \|a^{-\mathfrak{e}(\lollysmall)}g'a\sigma\|_\infty \\
&\lesssim 
\lambda^{2\alpha-2} [\derivativecherry]_{2\alpha-2} T 
+ \lambda^{\alpha-1} [\lolly]_\alpha \|\Theta'(u)\nu\|_{L^1} \\
&\lesssim
\lambda^{2\alpha-2} \big([\derivativecherry]_{2\alpha-2} T 
+ (\sqrt{T})^{1-\alpha} [\lolly]_\alpha \|\Theta'(u)\nu\|_{L^1} \big) \, ,
\end{align}
%
where in the second inequality we used that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($-1+2N-(M-1)\geq0$, $-1+N\geq0$)
%
\begin{equation}
\max\Big\{
\Big|\frac{g'\sigma^2}{a^{\mathfrak{e}(\cherrysmall)-1}}\Big| \, , \
\Big|\frac{g'\sigma}{a^{\mathfrak{e}(\lollysmall)-1}}\big| \Big\} \lesssim 1 \, .
\tag{XII}
\end{equation}
%
Thus Lemma~\ref{lem:reconstruction4} can be applied with 
$\theta_1=2\alpha-2$, $\theta_2=\min\{\alpha,\beta-\alpha,1-\alpha/2\}$, 
$\theta_3=2\alpha-2$, and $\theta_4=0$, to obtain 
%
\begin{align}
|\eqref{eq:energy2}|
&\lesssim [\derivativecherry]_{2\alpha-2} [\Theta(u)]_{B_{1,\infty}^\alpha}
+ [\lolly]_\alpha [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}}
+ [\lolly]_\alpha [\Theta(u)]_{B_{1,\infty}^\alpha} \|\Theta'(u)\nu\|_{L^2} \\
&\,+ [\derivativecherry]_{2\alpha-2} T (\sqrt{T})^{2\alpha-2}
+ [\lolly]_{\alpha} \|\Theta'(u)\nu\|_{L^1} (\sqrt{T})^{\alpha-1} \, .
\end{align}
%
Here we have directly used that $\theta_1+\theta_2>0$ and $T\leq1$.

We turn to \eqref{eq:energy1} where we define (recall that we write $\fnoise=f(u)$) 
%
\begin{equation}
F_\x(\z) 
\coloneqq \gnoise(\x)\snoise(\x) \xi(\z)
+ (g\sigma)'(u(\x)) \big( \snoise(\x) \Pi_\x[\dumb;\x](\z) + \nu(\x) \cdot \Pi_\x[\xnoise](\z) \big)
\end{equation}
%
such that 
%
\begin{equation}
\eqref{eq:energy1} 
= \int_{(0,T)\times\T^d} d\z \, F_\z(\z) \, .
\end{equation}
%
By definition 
%
\begin{align}
&F_{\x+\y} - F_\x \\
&= \gnoise(\x+\y)\snoise(\x+\y) \xi
+ (g\sigma)'(u(\x+\y)) \snoise(\x+\y) \Pi_{\x+\y}[\dumb;\x+\y] \\
&\hphantom{= \gnoise(\x+\y)\snoise(\x+\y) \xi \ }
+ (g\sigma)'(u(\x+\y)) \nu(\x+\y) \cdot \Pi_{\x+\y}[\xnoise] \\
&\,- \gnoise(\x)\snoise(\x) \xi
- (g\sigma)'(u(\x)) \snoise(\x) \Pi_\x[\dumb;\x]
- (g\sigma)'(u(\x)) \nu(\x) \cdot \Pi_\x[\xnoise] \, .
\end{align}
%
Using \eqref{eq:trafodumb} in form of 
$\Pi_{\x}[\dumb;\x] = \Pi_{\x+\y}[\dumb;\x] + \Pi_{\x}[\lolly;\x](\x+\y) \xi$
and \eqref{eq:trafoxnoise} in form of 
$\Pi_{\x}[\xnoise] = \Pi_{\x+\y}[\xnoise] + y \xi$,
we obtain 
%
\begin{align}
&F_{\x+\y} - F_\x \\
&= \Big( \gnoise(\x\!+\!\y)\snoise(\x\!+\!\y) 
\!-\! \gnoise(\x)\snoise(\x) 
\!-\! (g\sigma)'(u(\x)) \big(\snoise(\x) \Pi_{\x}[\lolly;\x](\x\!+\!\y) \!+\! \nu(\x) \!\cdot\! y \big) \Big) \xi \\
%
&\,+ (g\sigma)'(u(\x+\y)) \snoise(\x+\y) \Pi_{\x+\y}[\dumb;\x+\y] 
- (g\sigma)'(u(\x)) \snoise(\x) \Pi_{\x+\y}[\dumb;\x] \\
%
&\,+ \Big( (g\sigma)'(u(\x+\y)) - (g\sigma)'(u(\x)) \Big) \nu(\x+\y) 
\cdot \Pi_{\x+\y}[\xnoise] \\
&\,+ (g\sigma)'(u(\x)) \Big(\nu(\x+\y)-\nu(\x) \Big) \cdot \Pi_{\x+\y}[\xnoise] \, .
\end{align}
%
In the second, third, and fourth right hand side term we can replace every instance of $u$ by $\Theta(u)$ and every instance of $\nu$ by $\Theta'(u)\nu$.
Thus for $\y\in\mathfrak{K}\subseteq\R\times\R^d$ for compact $\mathfrak{K}$, $0<\lambda\leq\sqrt{T}$, and $\varphi\in\mathcal{B}$
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F_{\x+\y}(\z) - F_\x(\z) \big) \varphi_\x^\lambda(\z) \Big| \\
&\lesssim [(g\sigma)(\mathcal{U})]_{B^{\beta}_{1,\infty}} \|\y\|_\s^{\beta} [\xi]_{\alpha-2} \lambda^{\alpha-2} \\
&\,+ [\Theta(u)]_{B^\alpha_{1,\infty}} \|\y\|_\s^\alpha [\dumb]_{2\alpha-2} \lambda^{\alpha-2}(\lambda+\|\y\|_\s)^\alpha \\
&\quad\times \big( \|a^{-\mathfrak{e}(\dumbsmall)}(g\sigma)''\sigma\|_\infty
+ \|a^{-\mathfrak{e}(\dumbsmall)} (g\sigma)' \sigma'\|_\infty 
+ \|a^{-1-\mathfrak{e}(\dumbsmall)} (g\sigma)' \sigma a'\|_\infty \big) \\
&\,+ \|(g\sigma)''\|_\infty [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\y\|_\s^{\alpha/2} \|\Theta'(u)\nu\|_{L^2} 
[\xnoise]_{\alpha-1} \lambda^{\alpha-2}(\lambda+\|\y\|_\s) \\
&\,+ \|(g\sigma)'\|_\infty 
[\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} \|\y\|_\s^{\beta-1}
[\xnoise]_{\alpha-1} \lambda^{\alpha-2}(\lambda+\|\y\|_\s) \, ,
\end{align}
%
where we used the modelbound \eqref{eq:offdiagonal}, 
for the second and third term also the fundamental theorem of calculus, 
and for the third term additionally Cauchy-Schwarz and $\|\Theta(u)\|_{L^\infty}\lesssim1$ 
as in the estimate of \eqref{eq:mt09} in the proof of Lemma~\ref{lem:reconstruction1}.
Using that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($N-2+N-(M-1)\geq0$, $N-2\geq0$, $N-1\geq0$)
%
\begin{equation}
\max\Big\{
\Big|\frac{(g\sigma)''\sigma}{a^{\mathfrak{e}(\dumbsmall)}}\Big| \, , \ 
\Big|\frac{(g\sigma)'\sigma'}{a^{\mathfrak{e}(\dumbsmall)}}\Big| \, , \
\Big|\frac{(g\sigma)'a'\sigma}{a^{1+\mathfrak{e}(\dumbsmall)}}\Big| \, , \
\big|(g\sigma)''\big| \, , \
\big|(g\sigma)'\big| \Big\} \lesssim 1 \, , 
\tag{XIII}
\label{eq:XIII}
\end{equation}
%
this right hand side is estimated by
%
\begin{align}
&\lambda^{\alpha-2} (\lambda+\|\y\|_\s)^{\beta} 
\big(  [(g\sigma)(\mathcal{U})]_{B_{1,\infty}^{\beta}} [\xi]_{\alpha-2} 
+ [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} [\xnoise]_{\alpha-1} \big) \\
&+ \lambda^{\alpha-2} (\lambda+\|\y\|_\s)^{2\alpha} 
[\Theta(u)]_{B_{1,\infty}^\alpha} [\dumb]_{2\alpha-2} \\
&+ \lambda^{\alpha-2} (\lambda+\|\y\|_\s)^{1+\alpha/2} 
[\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2} [\xnoise]_{\alpha-1} \, .
\end{align}
%
Furthermore, using \eqref{eq:Theta} and the modelbound \eqref{eq:offdiagonal} yields for $0<\lambda\leq\sqrt{T}$ and $0\leq\bar t\leq T$
%
\begin{align}
&\int_{(0,T)\times\T^d} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
F_\x(\z) \psi_{\x-(\bar{t},0)}^{\lambda}(\z) \Big| \\
&\lesssim \lambda^{\alpha-2} [\xi]_{\alpha-2} T \|g\sigma\|_\infty \\
&\,+ \lambda^{\alpha-2} (\lambda + \sqrt{\bar t\,}\,)^{\alpha} 
[\dumb]_{2\alpha-2} T \|a^{-\mathfrak{e}(\dumbsmall)} (g\sigma)' \sigma\|_\infty \\
&\,+ \lambda^{\alpha-2} (\lambda + \sqrt{\bar t\,}\,)
[\xnoise]_{\alpha-1} \|\Theta'(u)\nu\|_{L^1} \|(g\sigma)'\|_\infty \\
&\lesssim \lambda^{\alpha-2} [\xi]_{\alpha-2} T 
+ \lambda^{\alpha-2} (\lambda + \sqrt{\bar t\,}\,)^{\alpha} [\dumb]_{2\alpha-2} T 
+ \lambda^{\alpha-2} (\lambda + \sqrt{\bar t\,}\,)
[\xnoise]_{\alpha-1} \|\Theta'(u)\nu\|_{L^1} \\
&\lesssim
 \lambda^{\alpha-2} \big( [\xi]_{\alpha-2} T 
+(\sqrt{T})^{\alpha} [\dumb]_{2\alpha-2} T 
+\sqrt{T} \, [\xnoise]_{\alpha-1} \|\Theta'(u)\nu\|_{L^1} \big) \, ,
\end{align}
%
where in the second inequality we have used that Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} imply 
%($N\geq0$, $N-1+N-(M-1)\geq0$, $N-1\geq0$)
%
\begin{equation}
\max\Big\{\big|g\sigma\big| \, , \
\Big|\frac{(g\sigma)'\sigma}{a^{\mathfrak{e}(\dumbsmall)}}\Big| \, \
\big|(g\sigma)'\big| \Big\} \lesssim 1\, . 
\tag{XIV}
\end{equation}
%
Thus Lemma~\ref{lem:reconstruction4} can be applied with $\theta_1=\alpha-2$, 
$\theta_2=\min\{\beta,2\alpha,1+\alpha/2\}$, 
$\theta_3 = \alpha-2$, and
$\theta_4=0$, to obtain 
%
\begin{align}
|\eqref{eq:energy1}|
&\lesssim [(g\sigma)(\mathcal{U})]_{B_{1,\infty}^{\beta}} [\xi]_{\alpha-2} 
+ [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} [\xnoise]_{\alpha-1} \\
&\,+ [\Theta(u)]_{B_{1,\infty}^\alpha} [\dumb]_{2\alpha-2} 
+ [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2} [\xnoise]_{\alpha-1} \\
&\,+ [\xi]_{\alpha-2} T (\sqrt{T})^{\alpha-2}
+ [\dumb]_{2\alpha-2} T (\sqrt{T})^{2\alpha-2}
+ [\xnoise]_{\alpha-1} \|\Theta'(u)\nu\|_{L^1} (\sqrt{T})^{\alpha-1} \, .
\end{align}
%
Here we have directly used that $\theta_1+\theta_2>0$ and $T\leq1$.
\end{proof}

