\section{Real interpolation and proof of the main result}\label{sec:interpolation}

The main result of this section is to prove Theorem~\ref{thm:modelledness}. 
This is achieved by real interpolation based on Propositions~\ref{prop:u<} and \ref{prop:u>}, more precisely by what is called the $K$-method, 
see \cite{BL76} (or \cite{Lun18} for a more pedagogical introduction). 
Before giving the actual proof, we heuristically outline the strategy in the following.

If we had not estimated $[\mathcal{U^>}]_{B_{1,\infty}^{2\alpha}}$  
but the actual Besov norms
$\|u^<\|_{B_{1,\infty}^0}\lesssim \delta^{1/(M-1)}$ and 
$\|u^>\|_{B_{1,\infty}^{2\alpha}}\lesssim \delta^{-\alpha}$, 
we could define 
%
\begin{equation}
K(\lambda, u, B_{1,\infty}^0,B_{1,\infty}^{2\alpha})
= \inf_{u_1\in B_{1,\infty}^0,\,u_2\in B_{1,\infty}^{2\alpha},\,u_1+u_2=u} \big( \|u_1\|_{B_{1,\infty}^0} + \lambda \|u_2\|_{B_{1,\infty}^{2\alpha}} \big) \, , 
\end{equation}
%
which would be estimated by $\delta^{1/(M-1)}+\lambda\delta^{-\alpha}$ for all $\delta\in(0,1)$ since $u=u^<+u^>$. 
Choosing $\delta=\lambda^{(M-1)/(1+M\alpha-\alpha)}$, 
this would be further estimated by $\lambda^{1/(1+M\alpha-\alpha)}$, and thus
%
\begin{equation}
\sup_{\lambda>0} \lambda^{-\frac{1}{1+M\alpha-\alpha}} K(\lambda,u,B_{1,\infty}^0,B_{1,\infty}^{2\alpha}) < \infty \, .
\end{equation}
%
This in turn is the norm of the interpolation space $(B_{1,\infty}^0,B_{1,\infty}^{2\alpha})_{\theta,\infty}$ for $\theta=1/(1+M\alpha-\alpha)$, 
which by \cite[Theorem~6.4.5 (1)]{BL76} coincides with $B_{1,\infty}^{\theta2\alpha}$ (with equivalent norms). 

We need an extension of such real interpolation spaces to basepoint dependent seminorms, 
which is conveniently achieved via the following equivalence. 

\begin{lemma}\label{lem:equivalence}
Let $\mathcal{B}_1$ denote the set of smooth functions $\zeta$ on $\R^d$ supported in the unit ball with all its derivatives up to order $2$ bounded by $1$, 
and such that $\int_{\R^d} dy\, \zeta(y)y^k=0$ for $|k|_1\leq1$.
Furthermore let $u_\x(\y)$ be real valued and continuous in $\x,\y\in [0,T]\times\R^d$ with $\nabla_y u_\x(\y)$ continuous, and jointly $1$-periodic in its spatial arguments, i.e.~$u_\x(\y)=u_{\x+(0,k)}(\y+(0,k))$ for all $k\in\Z^d$. 
Then\footnote{here we write $\langle\cdot,\cdot\rangle$ to denote the $L^2$ inner product on $R^d$} 
for $\gamma\in(1,2\alpha)$
(recall that $\x=(t,x)$ and $\y=(s,y)$)
%
\begin{align}
&\sup_{0<\|\y\|_\s\leq R} \|\y\|_\s^{-\gamma} \int_{D_\y} d\x \, 
\big| u_\x(\x+\y) - u_\x(\x+(0,y)) \big| \\
&+\sup_{0<\lambda\leq R} \lambda^{-\gamma} 
\sup_{\zeta\in\mathcal{B}_1} 
\int_{[0,T]\times\T^d} d\x \, \big| \langle u_\x(t,\cdot),\zeta_x^\lambda\rangle \big| \\
%
&\lesssim \sup_{0<\|\y\|_\s\leq R} \|\y\|_\s^{-\gamma} \int_{D_\y} d\x \, 
|u_\x(\x+\y)-u_\x(\x)-\nabla u_\x(\x)\cdot y| \\
%
&\lesssim \sup_{0<\|\y\|_\s\leq R} \|\y\|_\s^{-\gamma} \int_{D_\y} d\x \, 
\big| u_\x(\x+\y) - u_\x(\x+(0,y)) \big| \\
&+\sup_{0<\lambda\leq R} \lambda^{-\gamma} 
\sup_{\zeta\in\mathcal{B}_1} 
\int_{[0,T]\times\T^d} d\x \, |\langle u_\x(t,\cdot), \zeta_x^\lambda \rangle| \\
&\,+ R^{2\alpha-\gamma} \!\!
\sup_{0<\lambda\leq R}\sup_{0<| y|\leq R} \lambda^{-\alpha}| y|^{-\alpha} 
\sup_{\zeta\in\mathcal{B}_1}
\int_{[0,T]\times\T^d}\!\! d\x 
\big| \big\langle u_\x(t,\cdot)-u_{\x+(0, y)}(t,\cdot), \zeta_{x+ y}^{\lambda} \big\rangle\big| \, .
\end{align}
%
Furthermore let $u_\x\coloneqq u - \sigma(u(\x)) \Pi_\x[\lolly;\x]$ under the assumption of Theorem~\ref{thm:main}. 
Then
%
\begin{align}
&\sup_{0<\lambda\leq R}\sup_{0<| y|\leq R} \lambda^{-\alpha}| y|^{-\alpha} 
\sup_{\zeta\in\mathcal{B}_1}
\int_{[0,T]\times\T^d} d\x 
\big| \big\langle u_\x(t,\cdot)-u_{\x+(0, y)}(t,\cdot), \zeta_{x+ y}^{\lambda} \big\rangle\big| \\
&\lesssimdata 1 \\
&\,+ (R^{\gamma-\alpha} + R^{1-\alpha}\sqrt{T}) 
\sup_{0<\|\y\|_\s\leq R} \|\y\|_\s^{-\gamma} \int_{D_\y} d\x \, 
\big|u_\x(\x+\y)-u_\x(\x)-\nabla u_\x(\x)\cdot y\big| \, .
\end{align}
%
The dependence of the implicit constant in $\lesssimdata$ on the data is as in Theorem~\ref{thm:main}. 
\end{lemma}

\begin{proof}
The three inequalities are proved in the following three steps, respectively. 

\textbf{Step 1.} We start with the first inequality. 
The first left hand side term is estimated as desired as an immediate consequence of 
%
\begin{align}
u_\x(\x+\y)-u_\x(\x+(0,y))
&= u_\x(\x+\y) - u_\x(\x) - \nabla u_\x(\x)\cdot y \\
&\,-\big(u_\x(\x+(0,y)) - u_\x(\x) - \nabla u_\x(\x)\cdot y\big) \, ,
\end{align}
%
the triangle inequality, and $D_\y\subseteq[0,T]\times\T^d$. 

We turn to the second left hand side term.
Let $\zeta\in\mathcal{B}_1$ and $0<\lambda\leq R$. Then
%
\begin{align}
&\int_{[0,T]\times\T^d} d\x |\langle u_\x(t,\cdot) , \zeta_x^\lambda\rangle| \\
&= \int_{[0,T]\times\T^d} d\x \Big| \int_{\R^d} dy \, u_\x(\x+(0,y)) \zeta^\lambda(y) \Big| \\
&= \int_{[0,T]\times\T^d} d\x \Big| \int_{\R^d} dy \, \big(u_\x(\x+(0,y))-u_\x(\x)-\nabla u_\x(\x)\cdot y\big) \zeta^\lambda(y) \Big| \\
&\leq \int_{\R^d} dy \, |\zeta^\lambda(y)| 
\int_{[0,T]\times\T^d} d\x \big| u_\x(\x+(0,y))-u_\x(\x)-\nabla u_\x(\x)\cdot y\big| \, ,
\end{align}
%
where in the second equality we used that $\int dy \zeta(y)y^k = 0$ for $|k|_1\leq1$ 
and in the inequality we used the triangle inequality and Fubini. 
Note that by the support of $\zeta$ we have effectively $|y|<\lambda\leq R$, 
hence the claim follows from 
$\int_{\R^d} dy \, |\zeta^\lambda(y)| |y|^\gamma \lesssim \lambda^{\gamma}$. 


\textbf{Step 2.}
We turn to the second inequality, where by the triangle inequality
%
\begin{align}
\big| u_\x(\x+\y)-u_\x(\x)-\nabla u_\x(\x)\cdot y \big|
&\leq \big| u_\x(\x+\y)-u_\x(\x+(0,y))\big| \\
&\,+ \big|u_\x(\x+(0,y)-\nabla u_\x(\x)\cdot y \big| \, .
\end{align}
%
It remains to estimate the second right hand side term. 
Let $\zeta$ be smooth, compactly supported in the unit ball, 
and satisfy $\int_{\R^d} dy\,\zeta(y)=1$ and $\int_{\R^d} dy\,\zeta(y)y^k=0$ for $|k|_1=1$. 
Then for $n_0\in\N$ to be chosen we have 
%
\begin{align}
u_\x(\x+(0,y)) - u_\x(\x) - \nabla u_\x(\x)\cdot y
&=
\big\langle u_\x(t,\cdot), 
\zeta_{x+y}^{2^{-n_0}} - \zeta_x^{2^{-n_0}} + \nabla \zeta_x^{2^{-n_0}} \cdot y\big\rangle \\
&\,+ \sum_{n=0}^\infty \big\langle u_\x(t,\cdot), \zeta_{x+y}^{2^{-n_0-n-1}} - \zeta_{x+y}^{2^{-n_0-n}} \big\rangle \\
&\,- \sum_{n=0}^\infty \big\langle u_\x(t,\cdot), \zeta_{x}^{2^{-n_0-n-1}} - \zeta_{x}^{2^{-n_0-n}} \big\rangle \\
&\,- \sum_{n=0}^\infty \big\langle \nabla u_\x(t,\cdot)\cdot y, \zeta_{x}^{2^{-n_0-n-1}} - \zeta_{x}^{2^{-n_0-n}} \big\rangle \, .
\end{align}
%
The first right hand side term equals 
%
\begin{equation}
\int_{\R^d} dz\, u_\x(t,z) 2^{n_0 d} \Big(
\zeta\big(2^{n_0}(z-x-y)\big) - \zeta\big(2^{n_0}(z-x)\big) - \nabla\zeta\big(2^{n_0}(z-x)\big) \cdot(-y)2^{n_0} \Big) \, ,
\end{equation}
%
which using $f(1)-f(0)-f'(0) = \int_0^1 d\vartheta\, (1-\vartheta) f''(\vartheta)$ applied to $f(\vartheta) = \zeta(2^{n_0}(z-x-\vartheta y))$ we rewrite as 
%
\begin{align}
&\int_{\R^d} \!dz\, u_\x(t,z) 2^{n_0 d}
\!\int_0^1\! d\vartheta\,(1\!-\!\vartheta) \sum_{|k_1+k_2|_1=2} \!\partial^{k_1+k_2}\zeta\big(2^{n_0}(z\!-\!x\!-\!\vartheta y)\big) (-y)^{k_1+k_2} 2^{2n_0} \\
&= \int_0^1 d\vartheta\,(1-\vartheta) \sum_{|k_1+k_2|_1=2} \big\langle u_\x(t,\cdot), \partial^{k_1+k_2} \zeta_{x+\vartheta y}^{2^{-n_0}} \big\rangle (-y)^{k_1+k_2} \, .
\end{align}
%
Rewriting
%
\begin{align}
\big\langle u_\x(t,\cdot),\partial^{k_1+k_2}\zeta_{x+vy}^{2^{-n_0}}\big\rangle
&= \big\langle u_{\x+(0,\vartheta y)}(t,\cdot),\partial^{k_1+k_2}\zeta_{x+\vartheta y}^{2^{-n_0}}\big\rangle \\
&\,+ \big\langle u_\x(t,\cdot) - u_{\x+(0,vy)}(t,\cdot),\partial^{k_1+k_2}\zeta_{x+\vartheta y}^{2^{-n_0}}\big\rangle
\end{align}
%
and noting that $\partial^{k_1+k_2}\zeta\in C\mathcal{B}_1$ for some $C>0$ 
(since $|k_1+k_2|_1=2$), 
we thus obtain 
%
\begin{align}
&\int_{D_\y} d\x \big| 
\big\langle u_\x(t,\cdot), 
\zeta_{x+y}^{2^{-n_0}} - \zeta_x^{2^{-n_0}} + \nabla \zeta_x^{2^{-n_0}} \cdot y\big\rangle \big| \\
&\lesssim 2^{-n_0(\gamma-2)} |y|^2 \sup_{0<\lambda\leq R} \lambda^{-\gamma} \sup_{\tilde\zeta\in\mathcal{B}_1} \int_{D_\y} d\x \, |\langle u_\x(t,\cdot),\tilde\zeta_x^\lambda\rangle| \\
&+\! 2^{-n_0(\alpha-2)} |y|^{\alpha+2} \!\!\!
\sup_{0<\lambda\leq R}\sup_{0<|\tilde y|\leq R} \! (\lambda|\tilde y|)^{-\alpha} \!
\sup_{\tilde\zeta\in\mathcal{B}_1} \!
\int_{D_\y}\!\!d\x 
\big| \big\langle u_\x(t,\cdot)-u_{\x+(0,\tilde y)}(t,\cdot), \tilde\zeta_{x+\tilde y}^{\lambda} \big\rangle\big| ,
\end{align}
%
provided $2^{-n_0}\leq R$ and $|y|\leq R$. 

We turn to estimating $\langle \partial^k u_\x(t,\cdot) y^k , \zeta_{x+\vartheta y}^{2^{-n_0-n-1}} - \zeta_{x+\vartheta y}^{2^{-n_0-n}} \rangle$ for $|k|_1\leq1$ and $\vartheta\in\{0,1\}$. 
Denoting $\hat\zeta\coloneqq\zeta^{1/2}-\zeta$ we have 
$\zeta_{x+\vartheta y}^{2^{-n_0-n-1}}-\zeta_{x+\vartheta y}^{2^{-n_0-n}} = \hat\zeta_{x+\vartheta y}^{2^{-n_0-n}}$ 
and $\partial^k\hat\zeta\in\mathcal{B}_1$ for $|k|_1\leq1$ 
(here we use $\int dy \, \zeta(y)y^k=0$ for $|k|_1=1$). 
Hence 
%
\begin{align}
&\int_{D_\y} d\x \big| \big\langle \partial^k u_\x(t,\cdot)y^k , 
\zeta_{x+\vartheta y}^{2^{-n_0-n-1}}-\zeta_{x+\vartheta y}^{2^{-n_0-n}} \big\rangle\big| \\
&\leq \int_{D_\y} d\x \big| \big\langle u_{\x+(0,\vartheta y)}(t,\cdot) , 
\partial^k\hat\zeta_{x+\vartheta y}^{2^{-n_0-n}}\big\rangle y^k \big| \\
&\,+ \int_{D_\y} d\x \big| \big\langle u_\x(t,\cdot) - u_{\x+(0,\vartheta y)}(t,\cdot) , 
\partial^k \hat\zeta_{x+\vartheta y}^{2^{-n_0-n}}\big\rangle y^k \big| \\
&\lesssim 2^{-(n_0+n)(\gamma-|k|_1)} |y|^{|k|_1} \sup_{0<\lambda\leq R} \lambda^{-\gamma} 
\sup_{\tilde\zeta\in\mathcal{B}_1} 
\int_{D_\y} d\x |\langle u_\x(t,\cdot), \tilde\zeta_{x}^\lambda \rangle| \\
&\,+ 2^{-(n_0+n)(\alpha-|k|_1)} |\vartheta y|^\alpha |y|^{|k|_1} \\
&\quad\times
\sup_{0<\lambda\leq R} \sup_{0<|\tilde y|\leq R} \lambda^{-\alpha} |\tilde y|^{-\alpha}
\sup_{\tilde\zeta\in\mathcal{B}_1} \int_{D_\y} d\x \big|\big\langle u_\x(t,\cdot) - u_{\x+(0,\tilde y)}(t,\cdot), \tilde\zeta_{x+\tilde y}^\lambda \big\rangle\big| \, ,
\end{align}
%
again provided $2^{-n_0}\leq R$ and $|y|\leq R$. 
For such $n_0$ and $y$ we thus have
%
\begin{align}
&\int_{D_\y} d\x \Big| \sum_{n=0}^\infty \big\langle u_\x(t,\cdot), \zeta_{x+y}^{2^{-n_0-n-1}} - \zeta_{x+y}^{2^{-n_0-n}} \big\rangle 
- \sum_{n=0}^\infty \big\langle u_\x(t,\cdot), \zeta_{x}^{2^{-n_0-n-1}} - \zeta_{x}^{2^{-n_0-n}} \big\rangle \\
&\qquad- \sum_{n=0}^\infty \big\langle \nabla u_\x(t,\cdot)\cdot y, \zeta_{x}^{2^{-n_0-n-1}} - \zeta_{x}^{2^{-n_0-n}} \big\rangle \Big| \\
&\lesssim (2^{-n_0\gamma} + 2^{-n_0(\gamma-1)}|y|) 
\sup_{0<\lambda\leq R}\lambda^{-\gamma}
\sup_{\tilde\zeta\in\mathcal{B}_1} 
\int_{D_\y} d\x |\langle u_\x(t,\cdot), \tilde\zeta_{x}^\lambda \rangle| \\
&\,+ 2^{-n_0\alpha}|y|^\alpha 
\sup_{0<\lambda\leq R} \sup_{0<|\tilde y|\leq R} \lambda^{-\alpha} |\tilde y|^{-\alpha}
\sup_{\tilde\zeta\in\mathcal{B}_1} \int_{D_\y} d\x \big|\big\langle u_\x(t,\cdot) - u_{\x+(0,\tilde y)}(t,\cdot), \tilde\zeta_{x+\tilde y}^\lambda \big\rangle\big| \, ,
\end{align}
%
where we used $\alpha>0$ and $\gamma>1$ such that 
$\sum_{n=0}^\infty (2^{-n\gamma} + 2^{-n(\gamma-1)} + 2^{-n\alpha}) \lesssim 1$. 

For $|y|\leq R$ we thus choose $n_0$ such that $2^{-n_0}\leq R$ and $2^{-n_0}\sim|y|$ and the claim follows. 

\textbf{Step 3.}
We turn to the last inequality. 
First observe that by the definition of $u_\x$ and by \eqref{eq:trafololly} in form of 
$\Pi_{\x}[\lolly;\x] = \Pi_{\x+(0,y)}[\lolly;\x] + \Pi_{\x}[\lolly;\x](\x+(0,y))$ 
%
\begin{align}
u_\x - u_{\x+(0,y)} 
&= \sigma(u(\x+(0,y))) \Pi_{\x+(0,y)}[\lolly;\x+(0,y)] - \sigma(u(\x))\Pi_\x[\lolly;\x] \\
&= \sigma(u(\x+(0,y))) \Pi_{\x+(0,y)}[\lolly;\x+(0,y)] - \sigma(u(\x))\Pi_{\x+(0,y)}[\lolly;\x] \\
&\,- \sigma(u(\x)) \Pi_{\x}[\lolly;\x](\x+(0,y)) \, .
\end{align}
%
For $\zeta\in\mathcal{B}_1$ we thus have 
%
\begin{align}
&\big\langle u_\x(t,\cdot) - u_{\x+(0,y)}(t,\cdot) , \zeta_{x+y}^\lambda \big\rangle \\
&= \big\langle \sigma(u(\x+(0,y))) \Pi_{\x+(0,y)}[\lolly;\x+(0,y)](t,\cdot) - \sigma(u(\x))\Pi_{\x+(0,y)}[\lolly;\x](t,\cdot) , \zeta_{x+y}^\lambda \big\rangle \, .
\end{align}
%
Denoting $G(v)\coloneqq \sigma(v) \Pi_{\x+(0,y)}[\lolly;a(v)](t,\cdot)$ and observing that $G(v)=G(\Theta(v))$ for $\Theta$ from \eqref{eq:Theta}, 
we have by the fundamental theorem of calculus 
%
\begin{align}
&\big\langle u_\x(t,\cdot) - u_{\x+(0,y)}(t,\cdot) , \zeta_{x+y}^\lambda \big\rangle \\
&= \int_0^1 d\vartheta\, \big\langle G'\big(\vartheta \Theta(u(\x+(0,y)))+(1-\vartheta)\Theta(u(\x))\big) , \zeta_{x+y}^\lambda\big\rangle \\
&\quad\times \big(\Theta(u(\x+(0,y)))-\Theta(u(\x))\big) \, .
\end{align}
%
Using 
%
\begin{equation}
G'(v) 
= \sigma'(v) \Pi_{\x+(0,y)}[\lolly;a(v)](t,\cdot) + \sigma(v)a'(v)\partial_a\Pi_{\x+(0,y)}[\lolly;a(v)](t,\cdot) 
\end{equation}
%
we obtain from the model estimate \eqref{eq:lollybound} 
%
\begin{align}
&\int_{[0,T]\times\T^d} d\x \big| \big\langle u_\x(t,\cdot) - u_{\x+(0,y)}(t,\cdot) , \zeta_{x+y}^\lambda \big\rangle \big| \\
&\lesssim \lambda^\alpha [\lolly]_\alpha \big(\|\sigma'\!/\!a^{\mathfrak{e}(\lollysmall)}\|_\infty \!+\! \|\sigma a'\!/\!a^{1+\mathfrak{e}(\lollysmall)}\|_\infty\big)
\!\int_{[0,T]\times\T^d} \! d\x \big| \Theta(u(\x\!+\!(0,y)))\!-\!\Theta(u(\x)) \big| \, .
\end{align}
%
Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} yield 
%($N-1-(M-1)\geq0$)
%
\begin{equation}
\max\Big\{
\Big|\frac{\sigma'}{a^{\mathfrak{e}(\lollysmall)}}\Big| \, , \ 
\Big|\frac{\sigma a'}{a^{1+\mathfrak{e}(\lollysmall)}}\Big| \Big\} \lesssim 1\, ,
\tag{XV}\label{eq:XV}
\end{equation}
%
and together with the definition of $[\Theta(u)]_{B_{1,\infty}^\alpha}$ we deduce 
%
\begin{equation}
\int_{[0,T]\times\T^d} d\x \big| \big\langle u_\x(t,\cdot) - u_{\x+(0,y)}(t,\cdot) , \zeta_{x+y}^\lambda \big\rangle \big|
\lesssim \lambda^\alpha |y|^\alpha [\lolly]_\alpha [\Theta(u)]_{B_{1,\infty}^\alpha} \, .
\end{equation}
%
The claim follows from 
$[\Theta(u)]_{B_{1,\infty}^\alpha}
\lesssim (R^{\gamma-\alpha}+R^{1-\alpha}\sqrt{T}) [\mathcal{U}]_{B_{1,\infty}^{\gamma}} +1$, 
see Lemma~\ref{lem:absorb}, and noting that $u_\x$ is defined such that 
%
\begin{equation}
u_\x(\x+\y)-u_\x(\x)-\nabla u_\x(\x)\cdot y
= u(\x+\y)-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)-\nu(\x)\cdot y \, .
\end{equation}
%
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We can finally give the proof of Theorem~\ref{thm:modelledness}.

\begin{proof}[Proof of Theorem~\ref{thm:modelledness}]
Let $0<R,T\leq1$.
Recall $u_\x=u - \sigma(u(\x)) \Pi_\x[\lolly;\x]$ from Lemma~\ref{lem:equivalence} defined such that
%
\begin{equation}
u(\x+\y)-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)-\nu(\x)\cdot y
= u_\x(\x+\y)-u_\x(\x)-\nabla u_\x(\x)\cdot y \, .
\end{equation}
%
Hence by Lemma~\ref{lem:equivalence} we have for $\gamma\in(1,2\alpha)$ and $R$ small enough 
%
\begin{align}
&[\mathcal{U}]_{B_{1,\infty}^\gamma} \\
&=\sup_{0<\|\y\|_\s\leq R}
\|\y\|_\s^{-\gamma} \int_{D_\y} d\x \big| u(\x+\y)-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)-\nu(\x)\cdot y \big| \\
&\lesssimdata 1 
+ \sup_{0<\|\y\|_\s\leq R} \|\y\|_\s^{-\gamma} \int_{D_\y} d\x \, 
\big| u_\x(\x+\y) - u_\x(\x+(0,y)) \big| \\
&\hphantom{\lesssimdata 1\ }
+\sup_{0<\lambda\leq R} \lambda^{-\gamma} 
\sup_{\zeta\in\mathcal{B}_1} \int_{[0,T]\times\T^d} d\x \big| \langle u_\x(t,\cdot), \zeta_x^\lambda \rangle \big| \, .
\end{align}
%
In Step~1 we estimate the time increments and in Step~2 we estimate the last right hand side term; 
in Step~3 we combine both estimates and conclude. 
In all steps we use for $\delta\in(0,1)$ the splitting $u=u^<+u^>$ and $\Pi[\lolly]=\Pi^<[\lolly]+\Pi^>[\lolly]$ into small and large velocities as in 
the beginning of Section~\ref{sec:splitting}.

\textbf{Step 1.} 
Let $u_\x^<\coloneqq u^< - \sigma(u(\x)) \Pi^<_\x[\lolly;\x]$ and 
$u_\x^>\coloneqq u^> - \sigma(u(\x)) \Pi^>_\x[\lolly;\x]$. 
Then $u_\x=u_\x^<+u_\x^>$, and by the triangle inequality 
%
\begin{align}
&\int_{D_\y} d\x \big| u_\x(\x+\y) - u_\x(\x+(0,y)) \big| \\
&\leq \int_{D_\y} d\x \big( |u^<_\x(\x+\y)| + |u^<_\x(\x+(0,y))| + |u^>_\x(\x+\y)-u^>_\x(\x+(0,y))| \big) \, .
\end{align}
%
Again by the triangle inequality, 
%
\begin{align}
&\int_{D_\y} d\x \big| u^>_\x(\x+\y)-u^>_\x(\x+(0,y)) \big| \\
&\leq \int_{D_\y} d\x \big| u^>(\x+\y)-u^>(\x)-\sigma(u(\x))\Pi^>_\x[\lolly;\x](\x+\y) - \nu^>(\x) \cdot y \big| \\
&\,+ \int_{D_\y} d\x \big| u^>(\x+(0,y))-u^>(\x)-\sigma(u(\x))\Pi^>_\x[\lolly;\x](\x+(0,y)) - \nu^>(\x)\cdot y \big| \, .
\end{align}
%
Denoting 
$[\![u^<]\!]\coloneqq \sup_{\|\y\|_\s\leq R} \int_{D_\y} d\x |u^<_\x(\x+\y)|$ 
this yields for $\|\y\|_\s\leq R$
%
\begin{equation}
\int_{D_\y} d\x \big| u_\x(\x+\y)-u_\x(\x+(0,y)) \big| 
\leq 2 [\![u^<]\!]
+ 2 [\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} \|\y\|^{2\alpha} \, .
\end{equation}
%
Since $\delta\in(0,1)$ was arbitrary (but for convenience dyadic, see \eqref{eq:decompose_phi>}) in the decomposition $u=u^<+u^>$ from Section~\ref{sec:splitting}, we deduce for $\gamma\in(1,2\alpha]$ and $\|\y\|_\s\leq R$
%
\begin{align}
&\|\y\|_\s^{-\gamma} \int_{D_\y} d\x \big| u_\x(\x+\y)-u_\x(\x+(0,y)) \big| \\
&\lesssim \sup_{0<\lambda\leq R} \lambda^{-\gamma} \inf_{\substack{0<\delta<1\\ \delta\textnormal{ dyadic}}}
\big( [\![u^<]\!] + \lambda^{2\alpha} [\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} \big) \, .
\end{align}
%

\textbf{Step 2.}
Let $\lambda\leq R$ and $\zeta\in\mathcal{B}_1$. 
Splitting once more $u_\x=u^<_\x+u^>_\x$ the triangle inequality yields
%
\begin{align}
\int d\x \big| \langle u_\x(t,\cdot),\zeta^\lambda_x\rangle \big| 
\leq \int d\x \int_{\R^d} dz \big| u_\x^<(\x+(0,z))\zeta^\lambda(z) \big|
+ \int d\x \big| \langle u^>_\x(t,\cdot), \zeta^\lambda_x \rangle \big| \, .
\end{align}
%
For the first right hand side term note that $|z|\leq\lambda\leq R$ by the support of $\zeta$, 
hence it is bounded by $[\![u^<]\!]$. 
The second right hand side term is by Lemma~\ref{lem:equivalence} estimated by 
%
\begin{equation}
\lambda^{2\alpha} \sup_{0<\|\y\|_\s\leq R} \|\y\|_\s^{-2\alpha} \int_{D_\y} d\x \big|
u^>_\x(\x+\y)-u^>_\x(\x)-\nabla u^>_\x(\x)\cdot y \big| 
\leq \lambda^{2\alpha} [\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} \, .
\end{equation}
%
Hence we obtain altogether (again since $\delta$ was arbitrary)
%
\begin{equation}
\lambda^{-\gamma} 
\sup_{\zeta\in\mathcal{B}_1} \int_{[0,T]\times\T^d} d\x \big| \langle u_\x(t,\cdot), \zeta_x^\lambda \rangle \big| \lesssim \sup_{0<\lambda\leq R} \lambda^{-\gamma} \inf_{\substack{0<\delta<1\\ \delta \textnormal{ dyadic}}}
\big( [\![u^<]\!] + \lambda^{2\alpha} [\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} \big) \, .
\end{equation}
%

\textbf{Step 3.}
Combining Steps~1 and 2 we deduce for $\gamma\in(1,2\alpha)$
%
\begin{align}
[\mathcal{U}]_{B_{1,\infty}^\gamma} 
\lesssimdata 1+ \sup_{0<\lambda\leq R} \lambda^{-\gamma} \inf_{\substack{0<\delta<1\\ \delta\textnormal{ dyadic}}}
\big( [\![u^<]\!] + \lambda^{2\alpha} [\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} \big) \, .
\end{align}
%
By Proposition~\ref{prop:u<} and Lemma~\ref{lem:Pi<} we estimate 
%
\begin{align}
[\![u^<]\!]
&= \sup_{0<\|\y\|_\s\leq R} \int_{D_\y} d\x \, \big|u^<(\x+\y)-\sigma(u(\x))\Pi^<_\x[\lolly;\x](\x+\y) \big| 
\lesssimdata \delta^{1/(M-1)} \, .
\end{align}
%
Furthermore, by Proposition~\ref{prop:u>} we have for $\beta\in(2-\alpha,2\alpha)$ and $\epsilon>0$ small enough
%
\begin{equation}
[\mathcal{U}^>]_{B_{1,\infty}^{2\alpha}} 
\lesssimdata \delta^{-\alpha-\epsilon} \big( 1+ (R+T)^{1-\alpha} [\mathcal{U}]_{B_{1,\infty}^\beta} \big) \, ,
\end{equation}
%
and thus 
%
\begin{equation}
[\mathcal{U}]_{B_{1,\infty}^\gamma} 
\lesssimdata 1 + \sup_{0<\lambda\leq R} \lambda^{-\gamma} \inf_{\substack{0<\delta<1\\ \delta\textnormal{ dyadic}}}
\big( \delta^{1/(M-1)} + \lambda^{2\alpha} \delta^{-\alpha-\epsilon} (1+ (R+T)^{1-\alpha}[\mathcal{U}]_{B_{1,\infty}^\beta}) \big) \, .
\end{equation}
%
Choosing $\delta$ such that $\delta^{1/(M-1)}=\lambda^{2\alpha} \delta^{-\alpha-\epsilon}$, 
i.e.~$\delta=\lambda^{2\alpha(M-1)/(1+(M-1)(\alpha+\epsilon))}\in(0,1)$ and hence 
$\delta^{1/(M-1)} = \lambda^{2\alpha/(1+(M-1)(\alpha+\epsilon))}$ 
(since this choice need not be dyadic, actually choose $\delta$ to be the closest dyadic), yields
%
\begin{equation}
[\mathcal{U}]_{B_{1,\infty}^\gamma} 
\lesssimdata 1 + \sup_{0<\lambda\leq R} \lambda^{\frac{2\alpha}{1+(M-1)(\alpha+\epsilon)}-\gamma}
\big(1+(R+T)^{1-\alpha}[\mathcal{U}]_{B_{1,\infty}^\beta} \big) \, .
\end{equation}
%
Using that \eqref{eq:restrictionM} is equivalent to 
%
\begin{equation}
\frac{2\alpha}{1+(M-1)\alpha}> 2-\alpha 
\end{equation}
%
we can choose $\beta=\gamma\in(2-\alpha,2\alpha/(1+(M-1)(\alpha+\epsilon)]$ to deduce for $R,T$ small enough the desired 
%
\begin{equation}
[\mathcal{U}]_{B_{1,\infty}^\beta} 
\lesssimdata 1 \, .
\end{equation}
%
\end{proof}

Theorem~\ref{thm:main} is now a simple consequence of Theorem~\ref{thm:modelledness}. 

\begin{proof}[Proof of Theorem~\ref{thm:main}]
By the triangle inequality and the definitions of $[\mathcal{U}]_{B_{1,\infty}^\beta}$ for $\beta\in(1,2)$ and $[\lolly]_\alpha$ we have
%
\begin{align}
&\int_{D_\y} d\x\, \big|u(\x+\y)-u(\x)\big| \\
&\leq \int_{D_\y} d\x\, \big|u(\x+\y)-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)-\nu(\x)\cdot y\big| \\
&\,+ \int_{D_\y} d\x\, \big|\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)-\nu(\x)\cdot y\big| \\
&\leq \|\y\|_\s^\beta [\mathcal{U}]_{B_{1,\infty}^\beta} 
+ \|\y\|_\s^\alpha \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_\alpha
+ \|\nu\|_{L^1}\|\y\|_\s \, .
\end{align}
%
Choosing $\beta$ as in Theorem~\ref{thm:modelledness} and appealing to 
%($N-(M-1)\geq0$)
%
\begin{equation}
\Big|\frac{\sigma}{a^{\mathfrak{e}(\lollysmall)}}\Big| \lesssim 1\, ,
\tag{XVI}\label{eq:XVI}
\end{equation}
%
it remains to estimate $\|\nu\|_{L^1}$. 
For this we rewrite 
%
\begin{align}
\nu(\x)\cdot y
&=u(\x+(0,y))-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+(0,y)) \\
&\,-\big(u(\x+(0,y))-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+(0,y))-\nu(\x)\cdot y\big) \, ,
\end{align}
%
which by the triangle inequality and the definitions of $[\lolly]_\alpha$ and $[\mathcal{U}]_{B_{1,\infty}^{\beta}}$ yields
%
\begin{equation}
\int_{(0,T)\times\T^d} \! d\x \, | \nu(\x)\cdot y| 
\leq 2 T \! \sup_{0<t\leq T}\int_{\T^d}dx\,|u(t,x)| 
+ \|\sigma\!/\!a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_\alpha |y|^\alpha 
+ [\mathcal{U}]_{B_{1,\infty}^{\beta}} |y|^{\beta} \, .
\end{equation}
%
Choosing $y=T e_i$ for $e_i\in\R^d$ the $i$-th unit vector with $|y|=T\leq R$ yields 
%
\begin{equation}
\int_{(0,T)\times\T^d}d\x\,|\nu(\x)|
\lesssimdata \sup_{0<t\leq T}\int_{\T^d}dx\,|u(t,x)| + [\mathcal{U}]_{B_{1,\infty}^\beta} +1 \, .
\end{equation}
%
Actually, $\|u(t,\cdot)\|_{L^1(\T^d)}$ is estimated in the proof of Proposition~\ref{prop:energy}
by $C_2$ from Proposition~\ref{prop:u2}, which in turn is estimated in the proof of Proposition~\ref{prop:u>} by $1+[\mathcal{U}]_{B_{1,\infty}^\beta}$ for $\beta\in(2-\alpha,2\alpha)$. 
Thus for such $\beta$ it holds $\|\nu\|_{L^1}\lesssim 1+[\mathcal{U}]_{B_{1,\infty}^\beta}$, and we conclude by appealing once more to Theorem~\ref{thm:modelledness}. 
\end{proof}

