\subsection{Test functions}

\begin{lemma}\label{lem:estK}
The kernel 
$G(t,x)\coloneqq \sum_{n\in\Z^d}\Phi(t,x+n) \zeta(x)$ 
with $\Phi$ the heat kernel defined in \eqref{eq:heatkernel} and $\zeta$ from \eqref{eq:defK} 
satisfies for $0\neq\x=(t,x)\in\R\times\R^d$ and $l\in\N$, $k\in\N^d$
%
\begin{align}
\big| \partial_t^l\partial_x^k G(\x) \big| 
\lesssim 1+ \|\x\|_\s^{-d-2l-|k|_1} \, .
\end{align}
%
The implicit constant depends only on the dimension $d$ 
and the derivatives (up to order $k$) 
of $\zeta$.
\end{lemma}
%
\begin{proof}
As a first step we claim that the heat kernel $\Phi$ defined in \eqref{eq:heatkernel} satisfies 
%
\begin{equation}
\big| \partial_t^l\partial_x^k \Phi(\x) \big| \lesssim \|\x\|_\s^{-d-2l-|k|_1} \textnormal{ for } 0\neq\x\in\R\times\R^d \, .
\end{equation}
%
Indeed, note that $\Phi$ satisfies the scaling invariance
$\Phi(\S^{1/\lambda}\x) = \lambda^d \Phi(\x)$. 
By choosing $\lambda\coloneqq\|\x\|_\s$ and since $\Phi(\S^{1/\|\x\|_\s}\x)$ is 
a smooth function on a compact set we obtain the desired estimate for $\Phi$ 
and all $\x\in\R\times\R^d$, $\x\neq0$.

We turn to $G$, where by the binomial formula 
%
\begin{equation}
\partial_t^l\partial_x^k G(\x)
= \sum_{k_1+k_2=k}\sum_{n\in\Z^d} \tbinom{k_1+k_2}{k_1} 
\partial_t^{l}\partial_x^{k_1} \Phi(t,x+n) 
\partial_x^{k_2} \zeta(x) \, .
\end{equation}
%
By the triangle inequality this can be split into\footnote{$k_1\leq k$ for $k_1,k\in\N^d$ has to be understood component wise}
%
\begin{align}
|\partial_t^l\partial_x^k G(\x)|
&\lesssim 
\sum_{k_1\leq k} \sum_{n\in\{-1,0,1\}^d}
| \partial_t^{l}\partial_x^{k_1} \Phi(t,x+n) | \\
&\,+ 
\sum_{k_1\leq k} \sum_{n\in\Z^d\setminus\{-1,0,1\}^d} 
| \partial_t^{l}\partial_x^{k_1} \Phi(t,x+n) | \, .
\end{align}
%
The first right hand side term is by the just established estimate of $\Phi$ estimated by 
%
\begin{equation}
\sum_{k_1\leq k} \sum_{n\in\{-1,0,1\}^d} 
\|(t,x+n)\|_\s^{-d-2l-|k_1|_1} 
\lesssim 
\sum_{k_1\leq k} 
\|(t,x)\|_\s^{-d-2l-|k_1|_1} \, ,
\end{equation}
%
where we used that we only need to consider $x$ in a set slightly larger than $[-1/2,1/2]^d$ by the support of $\zeta$.
To estimate the second right hand side term we distinguish the case $2l+|k_1|_1=0$ from $2l+|k_1|_1\geq1$. 
The contribution of the former case to the second right hand side term equals 
$\sum_{n\in\Z^d\setminus\{-1,0,1\}^d} \Phi(t,x+n)$ which is estimated by 
$\int_{\R^d} dx \, \Phi(t,x) = 1$,
where we used again that $x$ is close to $[-1/2,1/2]^d$; 
the contributions of the latter case can be estimated by using the already established estimate of $\Phi$ by 
%
\begin{equation}
\sum_{n\in\Z^d\setminus\{-1,0,1\}^d} 
\|(t,x+n)\|_\s^{-d-2l-|k_1|_1} 
\lesssim 
\sum_{n\in\Z^d\setminus\{-1,0,1\}^d} 
|x+n|^{-d-2l-|k_1|_1} 
\lesssim 1 \, ,
\end{equation}
%
where in the last inequality we used once more that $x$ is close to 
$[-1/2,1/2]^d$.

Summarizing, we obtained that 
$|\partial_t^l\partial_x^k G(\x)|\lesssim 1+
\sum_{k_1\leq k} \|\x\|_\s^{-d-2l-|k_1|_1}$.
We conclude by noting that 
if $\|\x\|_\s<1$ then $\sum_{k_1\leq k} \|\x\|_\s^{-d-2l-|k_1|_1}\lesssim \|\x\|_\s^{-d-2l-|k|_1}$, 
whereas if $\|\x\|_\s\geq1$ then $\sum_{k_1\leq k} \|\x\|_\s^{-d-2l-|k_1|_1}\lesssim1$.
\end{proof}

\begin{lemma}\label{lem:multtest}
There exists a constant $C>0$ such that the following holds. 
\begin{itemize}
\item[(i)] For $\varphi,\psi\in\mathcal{B}$, $\x,\y\in\R\times\R^d$, and $0<\lambda\leq r$ it holds
%
\begin{equation}
\varphi_\x^\lambda \, \psi_\y^r = r^{-D} \rho_\x^\lambda
\quad\textnormal{for some } \rho\in C\mathcal{B} \, . 
\end{equation}
%
\item[(ii)] For $\x,\z\in\R\times\R^d$, $l,m,n\in\N$, $k\in\N^d$, $q\in\Z$, and $\bar{a}>0$, 
the kernel $K^{(n)}=K_q^{(n)}$ defined in \eqref{eq:defK} and \eqref{eq:splittingk} satisfies 
%
\begin{equation}
\partial_{\bar{a}}^m\partial_t^l\partial_x^k \Kn(\bar{a},\x-\z) 
= 2^{-n(2-2l-|k|_1)} \bar{a}^{l-m} \, \rho_{(\bar{a}t,x)}^{2^{-n}}(\bar{a}r,z)
\, \tilde\varphi(2^q\bar{a})
\end{equation}
%
for some $\rho\in C\mathcal{B}$ supported on non-positive times and 
for some smooth $\tilde\varphi\colon\R\to\R$ supported in $(1/2,2)$.\footnote{Actually, for $m>0$ it is a linear combination of such $\rho$ and $\tilde\varphi$, which we suppress for notational convenience.} 
\end{itemize}
\end{lemma}
%
\begin{proof}
For \textit{(i)} define $\rho(\z) \coloneqq \varphi(\z) \, \psi(\S^{1/r}(\S^\lambda\z+\x-\y))$.
Then 
%
\begin{align}
\rho_\x^\lambda(\z) &= \lambda^{-D} \rho(\S^{1/\lambda}(\z-\x)) \\
&= \lambda^{-D} \varphi(\S^{1/\lambda}(\z-\x)) \, \psi(\S^{1/r}(\z-\x+\x-\y)) \\
&= \varphi_\x^\lambda(\z) \, r^D \psi_\y^r(\z) \, .
\end{align}
%
Furthermore, $\rho$ is smooth and its support is contained in that of $\varphi$, and
%
\begin{align}
\big|\partial_t^l\partial_x^k \rho(\z)\big| 
&= \Big|\sum_{\substack{l_1+l_2=l \\k_1+k_2=k}} \tbinom{l}{l_1} \tbinom{k}{k_1} 
\partial_t^{l_1}\partial_x^{k_1}\varphi(\z) \, \partial_t^{l_2}\partial_x^{k_2} \psi(\S^{1/r}(\S^\lambda\z+\x-\y)) (\tfrac{\lambda}{r})^{2l_2+|k_2|_1} \Big| \\
&\leq \sum_{\substack{l_1+l_2=l \\k_1+k_2=k}} \tbinom{l}{l_1} \tbinom{k}{k_1} 
=2^{l+|k|_1} \, ,
\end{align}
%
hence $\rho\in C\mathcal{B}$ for a sufficiently large $C$. 

For \textit{(ii)} recall the kernel $G$ from Lemma~\ref{lem:estK} and $\eta$ from \eqref{eq:splittingk}, 
and define 
$\rho(\z)\coloneqq 2^{-nd} \, \eta(-\z)G(-\S^{2^{-n}}\z)$. 
Then for $\varphi$ from \eqref{eq:decompose_phi>} it holds
%
\begin{align}
\rho_{(\bar{a}t,x)}^{2^{-n}}(\bar{a}r,z) \varphi(2^q\bar{a})
&= 2^{nD} \rho(\S^{2^n}\Da (\z-\x)) \varphi(2^q\bar{a}) \\
&= 2^{2n} \eta(\S^{2^n}\Da (\x-\z)) G(\Da(\x-\z)) \varphi(2^q\bar{a}) \\
&= 2^{2n} \Kn(\bar{a},\x-\z) \, ,
\end{align}
%
which proves the claim for $m=l=0$ and $k=0$ with $\tilde\varphi=\varphi$, 
provided $\rho\in C\mathcal{B}$ which we establish next. 
The support of $\rho$ is contained in 
$(-\,\mathrm{supp}\,\eta) \cap ((-\infty,0)\times\R^d)$, it is smooth, and 
%
\begin{align}
\big|\partial_t^l\partial_x^k \rho(-\z)\big| 
&= 2^{-nd}\Big| \sum_{\substack{l_1+l_2=l \\k_1+k_2=k}} \tbinom{l}{l_1}\tbinom{k}{k_1} 
\partial_t^{l_1}\partial_x^{k_1} \eta(\z) \, \partial_t^{l_2}\partial_x^{k_2} G(\S^{2^{-n}}\z) 2^{-n(2l_2+|k_2|_1)} \Big| \\
&\lesssim 2^{-nd} \!\!\! \sum_{\substack{l_1+l_2=l \\k_1+k_2=k}} \! \tbinom{l}{l_1}\tbinom{k}{k_1} 
\1_{\mathrm{supp}\,\eta}(\z)
(1\!+\!\|\S^{2^{-n}}\!\z\|_\s^{-d-2l_2-|k_2|_1}) 2^{-n(2l_2+|k_2|_1)} \\
&\leq \sum_{\substack{l_1+l_2=l \\k_1+k_2=k}} \tbinom{l}{l_1}\tbinom{k}{k_1} 
\1_{\mathrm{supp}\,\eta}(\z)
(1+\|\z\|_\s^{-d-2l_2-|k_2|_1}) \, , 
\end{align}
%
where in the first inequality we have used Lemma~\ref{lem:estK} 
and in the second inequality we used $n\in\N$.
Since $\|\z\|_\s \sim1$ on $\mathrm{supp}\,\eta$
we obtain $|\partial_t^l\partial_x^k\rho(\z)|\lesssim 1$ and thus 
$\rho\in C\mathcal{B}$ for a sufficiently large $C$. 
The claim for general $m,l,k$ is a consequence of the already established: 
applying the product and chain rule to the claim without derivatives yields
%
\begin{align}
&\partial_{\bar{a}}^m\partial_t^l\partial_x^k \Kn(\bar{a},\x-\z) 
= 2^{-2n} \sum_{m_1+m_2+m_3=m} \tfrac{m!}{m_1!m_2!m_3!} \\
&\, \times \tfrac{l!}{(l-m_1)!} \bar{a}^{l-m_1} 
(\partial_t^{l+m_2} \partial_x^k \rho)_{(\bar{a}t,x)}^{2^{-n}}(\bar{a}r,z) 2^{n(2l+2m_2+|k|_1)} (r-t)^{m_2} 
(\partial_{\bar{a}}^{m_3}\tilde\varphi)(2^q\bar{a}) 2^{qm_3} \, .
\end{align}
%
We conclude by noting that 
$(2^{2n}(r-t))^{m_2}\sim\bar{a}^{-m_2}$ which is a consequence 
of the support of $\rho$ being contained in the support of $\eta$, 
and by noting that $2^{qm_3}\sim\bar{a}^{-m_3}$ which is a consequence 
of the support of $\tilde\varphi$.
\end{proof}

