\subsection{Reconstruction in an \texorpdfstring{$L^1$}{L1} setting}

We recall here a version of the reconstruction theorem in an $L^1$-setting which we used frequently. 
%
\begin{theorem}[Reconstruction]\label{thm:reconstruction}
Let $F_\x(\z;\y)$ for 
$\x\in[0,T]\times\R^d$, $\y\in[0,T]\times\R^d$, and $\z\in[0,\infty)\times\R^d$
be jointly $1$-periodic in its spatial arguments, 
i.e.~$F_{\x}(\z;\y) = F_{\x+(0,k)}(\z+(0,k);\y+(0,k))$ for all $k\in\Z^d$. 
Assume that there exist 
a smooth $\varphi$ compactly supported in the past with $\int\varphi\neq0$ and 
$\theta_1,\theta_2\in\R$ with $\theta_1+\theta_2>0$, $\theta_2\geq0$
such that 
%
\begin{align}
&\int_{D_{\y'}\cap D_{\y''}} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big(F_{\x+\y'}(\z;\x+\y'') - F_{\x}(\z;\x+\y'') \big) \varphi_\x^\lambda (\z) \Big| \\
&\leq C \lambda^{\theta_1} (\lambda+\|\y'\|_\s)^{\theta_2} \, ,
\end{align}
%
for $\y'\in\R\times\R^d$, $\y''\in[0,\infty)\times\R^d$, 
and dyadic\footnote{i.e.~of the form $2^{-n}$ for $n\in\Z$} $\lambda\leq\Lambda$ 
for some dyadic $\Lambda$. 

Then 
%
\begin{align}
&\int_{D_\y} d\x \Big| \int_{(0,\infty)\times\R^d} d\z \, 
\big( F_{\z}(\z;\x+\S^\vartheta\y) - F_{\x}(\z;\x+\S^\vartheta\y) \big) 
\psi^\Lambda_{\x+\S^\vartheta\y-\bar\x}(\z) \Big| \\
&\lesssim C \Lambda^{\theta_1} (\Lambda+\|\S^\vartheta\y-\bar\x\|_\s)^{\theta_2} 
\end{align}
%
for $\y\in\R\times\R^d$, $\bar\x\in[0,\infty)\times\R^d$, $\vartheta\in[0,1]$, 
and smooth $\psi$ compactly supported in the past, 
where the implicit constant depends only on $d$ 
and $\|\psi\|_{C^r}$ for the smallest $r\in\N$ with $\theta_1+r>0$. 
The assumption is only used for $\|\y'\|_\s<\vartheta\|\y\|_\s+\|\bar\x\|_\s+3\Lambda$ 
and $\|\y''\|_\s<\|\bar\x\|_\s+3\Lambda$. 
\end{theorem}

\begin{proof}
Let us first mention that the definition of $D_\y$ (see Theorem~\ref{thm:main}) ensures that all arguments of 
$F$ in the assumption are contained in the domain of $F$. 
To check that all arguments of $F$ in the conclusion are contained in the domain of $F$ we argue as follows: 
first, $\x\in D_\y$ implies that the time component of $\x+\S^\vartheta\y$ is contained in $[0,T]$ for all $\vartheta\in[0,1]$; 
furthermore, $F_\cdot(\z;\x+\S^\vartheta\y)$ vanishes by assumption 
unless $\z$ has a non-negative time component, 
and $\Psi_{\x+\S^\vartheta\y-\bar\x}(\z)$ vanishes by assumption unless $\z-\x-\S^\vartheta\y+\bar\x$ has a negative time component which by $\x\in D_\y$ and $\bar\x$ having a non-negative time component implies that 
also the time component of $\z$ is contained in $[0,T]$. 

We now turn to the reconstruction proof proper. 
A concise proof of the reconstruction theorem in a Besov setting can be found in \cite{BL23}. 
We are not precisely in their setup 
since we deal with time components in $[0,T]$, 
have the additional dependence on $\x+\S^\vartheta\y$ 
(which is not merely an additional parameter as we integrate over $\x$), 
and work with kernels only looking into the past. 
We thus briefly mention how to adapt the proof of \cite[Proposition~4.10]{BL23}, 
which is the main step in the proof of the reconstruction bound we want to obtain. 

In a first step\footnote{recall that we write $F(\varphi)$ short for 
$\int_{(0,\infty)\times\R^d}d\z\,F(\z)\varphi(\z)$} 
$(F_\cdot(\,\cdot\,;\x+\S^\vartheta\y)-F_\x(\,\cdot\,;\x+\S^\vartheta\y))(\psi_{\x+\S^\vartheta\y-\bar\x}^\Lambda)$ is rewritten
as a sum of four terms $a,b,c,d$, 
the first one of which is given by 
%
\begin{equation}
a(\x) \coloneqq
\int \!d\z' \int \!d\x' \big( F_{\z'}(\,\cdot\,;\x+\S^\vartheta\y)-F_{\x'}(\,\cdot\,;\x+\S^\vartheta\y) \big) 
(\hat{\varphi}_{\x'}^\Lambda) 
\hat{\varphi}_{\z'}^{2\Lambda}(\x') \psi_{\x+\S^\vartheta\y-\bar\x}^\Lambda(\z') \, .
\end{equation}
%
We neglect the remaining three terms for now and get back to them below. 
Here, $\hat\varphi\in\mathcal{B}$ is defined in \cite[Proposition~5.4]{BL23} as a linear combination of rescaled versions of $\varphi$ and is thus supported in the past. 
The integral over $\z'$ restricts effectively to the support 
$B_\s^-(\x+\S^\vartheta\y-\bar\x, \Lambda)$ of $\psi_{\x+\S^\vartheta\y-\bar\x}^\Lambda$, 
and the integral over $\x'$ restricts effectively to the support 
$B_\s^-(\z', 2\Lambda)$ of $\varphi_{\z'}^{2\Lambda}$, 
where $B_\s^-(\x,R)$ denotes the parabolic ball with radius $R$ centered at $\x$ looking only into the past. 
Using the triangle inequality and bounding the suprema of $\hat\varphi$ and $\psi$ by $1$ we obtain 
%
\begin{equation}
\begin{split}
|a(\x)| \lesssim 
\Lambda^{-2D} \int_{B_\s^-(\x+\S^\vartheta\y-\bar\x,\Lambda)} d\z' 
&\int_{B_\s^-(\z',2\Lambda)} d\x' \, \\
&\big| \big( F_{\z'}(\,\cdot\,;\x+\S^\vartheta\y) 
- F_{\x'}(\,\cdot\,;\x+\S^\vartheta\y)\big) (\hat\varphi_{\x'}^\Lambda) \big| \, .
\end{split}
\end{equation}
%
Changing variables according to $\tilde\x=-\x'+\z'$ and $\tilde\z=\z'-(\x+\S^\vartheta\y-\bar\x)$ yields
%
\begin{equation}
\begin{split}
|a(\x)| &\lesssim 
\Lambda^{-2D} \int_{B_\s^-(0,\Lambda)} d\tilde\z \int_{-B_\s^-(0,2\Lambda)} d\tilde\x \\
&\ \big| \big( F_{\tilde\z+\x+\S^\vartheta\y-\bar\x}(\cdot;\x\!+\!\S^\vartheta\y) - F_{\tilde\z+\x+\S^\vartheta\y-\bar\x-\tilde\x}(\cdot;\x\!+\!\S^\vartheta\y)\big) (\hat\varphi_{\tilde\z+\x+\S^\vartheta\y-\bar\x-\tilde\x}^\Lambda) \big| .
\end{split}
\end{equation}
%
By Minkowski's inequality 
%
\begin{align}
\int_{D_\y} d\x \, |a(\x)| 
&\lesssim \Lambda^{-2D} 
\int_{B_\s^-(0,\Lambda)} d\tilde\z 
\int_{-B_\s^-(0,2\Lambda)} d\tilde\x 
\int_{D_\y+\tilde\z+\S^\vartheta\y-\bar\x-\tilde\x} d\tilde{\mathbf{w}} \\
&\quad\big| \big( F_{\tilde{\mathbf{w}}+\tilde\x}(\,\cdot\,;\tilde{\mathbf{w}}-\tilde\z+\bar\x+\tilde\x) 
- F_{\tilde{\mathbf{w}}}(\,\cdot\,;\tilde{\mathbf{w}}-\tilde\z+\bar\x+\tilde\x) \big) 
(\hat\varphi_{\tilde{\mathbf{w}}}^\Lambda) \big| \, ,
\end{align}
%
where we changed variables according to $\tilde{\mathbf{w}}=\tilde\z+\x+\S^\vartheta\y-\bar\x-\tilde\x$.

To apply the assumption 
(with $\y'=\tilde\x$ and $\y''=-\tilde\z+\bar\x+\tilde\x$) 
we verify that all arguments of $F$ belong to its domain. 
First, note that the time component of 
$\tilde{\mathbf{w}}-\tilde\z+\bar\x+\tilde\x\in D_\y+\S^\vartheta\y$ 
is contained in $[0,T]$ by definition of $D_\y$. 
We now argue that in the above integral effectively $\tilde{\mathbf{w}}\in D_{\tilde\x}$ 
and first focus on the time variable. 
The implicit $(\cdot)$-variable of $F$ has effectively a non-negative time component by assumption, 
and since $\hat\varphi$ is supported in the past 
this transfers to $\tilde{\mathbf{w}}$ having effectively a non-negative time component. 
Furthermore, $\tilde\z\in B_\s^-(0,\Lambda)$ has a negative time component, 
$-\bar\x$ has by assumption a non-positive time component, 
and $-\tilde\x\in B_\s^-(0,2\Lambda)$ has a negative time component as well; 
hence $\tilde{\mathbf{w}}\in D_\y+\tilde\z+\S^\vartheta\y-\bar\x-\tilde\x$ has a time component $\leq T$. 
Once more since $\tilde\x$ has a positive time component 
also $\tilde{\mathbf{w}}+\tilde\x$ has a positive time component, 
and by $\tilde{\mathbf{w}}+\tilde\x\in D_\y+\tilde\z+\S^\vartheta\y-\bar\x$ 
and $\tilde\z-\bar\x$ having a negative time component 
we deduce that $\tilde{\mathbf{w}}+\tilde\x$ has a time component $\leq T$.
Altogether the time components of $\tilde{\mathbf{w}}$ and $\tilde{\mathbf{w}}+\tilde\x$ 
are contained in $[0,T]$. 
We turn to the spatial variables, 
where we remark that the function 
$\tilde{\mathbf{w}}
\mapsto 
F_{\tilde{\mathbf{w}}+\tilde\x}(\,\cdot\,;\tilde{\mathbf{w}}+\tilde\y) 
(\varphi_{\tilde{\mathbf{w}}})$ 
is periodic in space by assumption (for all $\tilde\x$, $\tilde\y$, and $\varphi$). 
Thus shifting the torus $\T^d$ by the spatial components of $\tilde\z+\S^\vartheta\y-\bar\x-\tilde\x$ 
has no effect. 
Altogether this yields the desired $\tilde{\mathbf{w}}\in D_{\tilde\x}$. 

The assumption thus applies and yields the estimate
%
\begin{equation}
\int_{D_\y} d\x \, |a(\x)| 
\lesssim \Lambda^{-2D} 
\int_{B_\s^-(0,\Lambda)} d\tilde\z 
\int_{-B_\s^-(0,2\Lambda)} d\tilde\x \, 
C \Lambda^{\theta_1} (\Lambda+\|\tilde\x\|_\s)^{\theta_2}
\lesssim C \Lambda^{\theta_1+\theta_2} \, .
\end{equation}
%

\medskip

We turn to the remaining three terms $b,c,d$. 
The first of them is given by 
%
\begin{equation}
b(\x)\coloneqq
\int \! d\z' \int\! d\x' \, \big(F_{\x'}(\,\cdot\,;\x+\S^\vartheta\y) - F_{\x}(\,\cdot\,;\x+\S^\vartheta\y)\big) 
(\hat\varphi_{\x'}^\Lambda) \hat\varphi_{\z'}^{2\Lambda}(\x') \psi_{\x+\S^\vartheta\y-\bar\x}^\Lambda(\z') \, .
\end{equation}
%
The two integrals effectively restrict to the same sets as for $a$. 
As for $a$ we bound the suprema of $\hat\varphi$ and $\psi$ by $1$ and note that 
$B_\s^-(\z',2\Lambda)\subseteq B_\s^-(\x+\S^\vartheta\y-\bar\x,3\Lambda)$ 
for $\z'\in B_\s^-(\x+\S^\vartheta\y-\bar\x,\Lambda)$, so that we obtain 
%
\begin{equation}
|b(\x)| \lesssim
\Lambda^{-D} \int_{B_\s^-(\x+\S^\vartheta\y-\bar\x,3\Lambda)} d\x' \, 
\big| \big( F_{\x'}(\,\cdot\,;\x+\S^\vartheta\y) - F_{\x}(\,\cdot\,;\x+\S^\vartheta\y) \big) (\hat\varphi_{\x'}^\Lambda) \big| \, .
\end{equation}
%
Changing variables according to $\tilde\x=-\x'+\x+\S^\vartheta\y-\bar\x$ yields
%
\begin{equation}
\begin{split}
|b(\x)| &\lesssim
\Lambda^{-D} \int_{-B_\s^-(0,3\Lambda)} d\tilde\x \\
&\quad
\big| \big( F_{\x+\S^\vartheta\y-\bar\x-\tilde\x}(\,\cdot\,;\x+\S^\vartheta\y) - F_{\x}(\,\cdot\,;\x+\S^\vartheta\y) \big) (\hat\varphi_{\x+\S^\vartheta\y-\bar\x-\tilde\x}^\Lambda) \big| \, .
\end{split}
\end{equation}
%
By Minkowski's inequality 
%
\begin{align}
\int_{D_\y} d\x \, |b(\x)| 
&\lesssim \Lambda^{-D} \int_{-B_\s^-(0,3\Lambda)} d\tilde\x
\int_{D_\y+\S^\vartheta\y-\bar\x-\tilde\x} d\tilde{\mathbf{w}} \\
&\quad\big| \big( F_{\tilde{\mathbf{w}}}(\,\cdot\,;\tilde{\mathbf{w}}+\bar\x+\tilde\x) - F_{\tilde{\mathbf{w}}-\S^\vartheta\y+\bar\x+\tilde\x}(\,\cdot\,;\tilde{\mathbf{w}}+\bar\x+\tilde\x) \big) (\hat\varphi_{\tilde{\mathbf{w}}}^\Lambda) \big| \, ,
\end{align}
%
where we changed variables according to $\tilde{\mathbf{w}}=\x+\S^\vartheta\y-\bar\x-\tilde\x$. 
The analogous arguments as for $a$ show that the assumption 
(with $\y'=-\S^\vartheta\y+\bar\x+\tilde\x$ and $\y''=\bar\x+\tilde\x$)
can be applied which yields
%
\begin{align}
\int_{D_\y} d\x \, |b(\x)| 
&\lesssim
\Lambda^{-D} \int_{-B_\s^-(0,3\Lambda)} d\tilde\x \, 
C\Lambda^{\theta_1} (\Lambda+\|\S^\vartheta\y-\bar\x-\tilde\x\|_\s)^{\theta_2} \\
&\lesssim C \Lambda^{\theta_1} (\Lambda+\|\S^\vartheta\y-\bar\x\|_\s)^{\theta_2} \, .
\end{align}
%

We turn to $c$ which is given by 
%
\begin{equation}
c(\x)\coloneqq 
\!\sum_{\lambda\leq\Lambda}\! \int\! d\z'\!\! \int \!d\x' \big( F_{\z'}(\cdot;\x+\S^\vartheta\y) - F_{\x'}(\cdot;\x+\S^\vartheta\y)\big)
(\hat\varphi_{\x'}^{\lambda}) \check\varphi_{\z'}^\lambda(\x') \psi_{\x+\S^\vartheta\y-\bar\x}^\Lambda(\z') ,
\end{equation}
%
where the sum is taken over dyadic $\lambda$, and 
$\check\varphi\in\mathcal{B}$ is defined in \cite[Section~4.3]{BL23} as a linear combination of rescaled versions of $\hat\varphi$ and is thus also supported in the past. 
The first integral restricts as for $a,b$ to $\z'\in B_\s^-(\x+\S^\vartheta\y-\bar\x,\Lambda)$, 
whereas the second integral restricts to $\x'\in B_\s^-(\z',\lambda)$. 
Bounding the suprema of $\check\varphi$ and $\psi$ by $1$ yields
%
\begin{equation}
\begin{split}
|c(\x)| \lesssim 
\Lambda^{-D} &\sum_{\lambda\leq\Lambda} \lambda^{-D} 
\int_{B_\s^-(\x+\S^\vartheta\y-\bar\x,\Lambda)}d\z' \int_{B_\s^-(\z',\lambda)} d\x' \\
&\quad
\big| \big( F_{\z'}(\,\cdot\,;\x+\S^\vartheta\y) - F_{\x'}(\,\cdot\,;\x+\S^\vartheta\y) \big)
(\hat\varphi_{\x'}^\lambda) \big| \, .
\end{split}
\end{equation}
%
Changing variables as for $a$ yields
%
\begin{align}
\int_{D_\y} d\x \, |c(\x)| 
&\lesssim \Lambda^{-D} \sum_{\lambda\leq\Lambda} \lambda^{-D} 
\int_{B_\s^-(0,\Lambda)} d\tilde\z \int_{-B_\s^-(0,\lambda)} d\tilde\x
\int_{D_\y+\tilde\z+\S^\vartheta\y-\bar\x-\tilde\x} d\tilde{\mathbf{w}} \\
&\quad\big| \big( F_{\tilde{\mathbf{w}}+\tilde\x}(\,\cdot\,;\tilde{\mathbf{w}}-\tilde\z+\bar\x+\tilde\x) - 
F_{\tilde{\mathbf{w}}}(\,\cdot\,;\tilde{\mathbf{w}}-\tilde\z+\bar\x+\tilde\x) \big)
(\hat\varphi_{\tilde{\mathbf{w}}}^\lambda) \big| \, .
\end{align}
%
Again the assumption 
(with $\y'=\tilde\x$ and $\y''=-\tilde\z+\bar\x+\tilde\x$)
can be applied to the effect of 
%
\begin{align}
\int_{D_\y} d\x \, |c(\x)| 
&\lesssim \Lambda^{-D} \sum_{\lambda\leq\Lambda} \lambda^{-D} 
\int_{B_\s^-(0,\Lambda)} d\tilde\z \int_{-B_\s^-(0,\lambda)} d\tilde\x \,
C \lambda^{\theta_1} (\lambda+\|\tilde\x\|_\s)^{\theta_2} \\
&\lesssim C \sum_{\lambda\leq\Lambda} \lambda^{\theta_1+\theta_2} 
\lesssim C \Lambda^{\theta_1+\theta_2} \, 
\end{align}
%
where in the last inequality we have used that by assumption $\theta_1+\theta_2>0$. 

Finally we turn to $d$, which is given by 
%
\begin{equation}
d(\x) \coloneqq
\!\sum_{\lambda\leq\Lambda}\! \int\! d\z'\!\! \int\! d\x' 
\big( F_{\x'}(\cdot;\x+\S^\vartheta\y) - F_\x(\cdot;\x+\S^\vartheta\y) \big)(\hat\varphi_{\x'}^\lambda)
\check\varphi_{\z'}^\lambda(\x') \psi_{\x+\S^\vartheta\y-\bar\x}^\Lambda(\z') \, .
\end{equation}
%
The two integrals effectively restrict to the same sets as for $c$. 
Changing variables according to 
$\tilde\z=\z'-\x-\S^\vartheta\y+\bar\x$ and then $\tilde\x=-\x'+\x+\S^\vartheta\y-\bar\x$, yields 
%
\begin{align}
d(\x) &= 
\sum_{\lambda\leq\Lambda} \int_{B_\s^-(0,\Lambda)} d\tilde\z 
\int_{-B_\s^-(\tilde\z,\lambda)} d\tilde\x \\
&\quad\big(F_{\x\!+\!\S^\vartheta\y-\bar\x-\tilde\x}(\,\cdot\,;\x\!+\!\S^\vartheta\y) - F_{\x}(\,\cdot\,;\x+\S^\vartheta\y) \big)(\hat\varphi_{\x+\S^\vartheta\y-\bar\x-\tilde\x}^\lambda) 
\check\varphi_{\tilde\z}^\lambda(-\tilde\x) \psi^\Lambda(\tilde\z) \, .
\end{align}
%
By the support of $\check\varphi$ we can replace the integration domain from 
$\tilde\x\in-B_\s^-(\tilde\z,\lambda)$ to $\tilde\x\in -B_\s^-(0,2\Lambda)$, so that
\begin{align}
d(\x) &= 
\sum_{\lambda\leq\Lambda} 
\int_{-B_\s^-(0,2\Lambda)} d\tilde\x \\
&\quad
\big(F_{\x+\S^\vartheta\y-\bar\x-\tilde\x}(\,\cdot\,;\x\!+\!\S^\vartheta\y) - F_{\x}(\,\cdot\,;\x\!+\!\S^\vartheta\y) \big)(\hat\varphi_{\x+\S^\vartheta\y-\bar\x-\tilde\x}^\lambda) 
(\check\varphi^\lambda * \psi^\Lambda)(-\tilde\x) .
\end{align}
%
Using Minkowski's inequality, 
$|\check\varphi^\lambda*\psi^\Lambda|\lesssim \Lambda^{-r-D} \lambda^r$ 
(see \cite[Lemma~4.8]{BL23}), 
and changing variables according to $\tilde{\mathbf{w}}=\x+\S^\vartheta\y-\bar\x-\tilde\x$ yields
%
\begin{align}
\int_{D_\y}d\tilde\x \, |d(\x)| 
&\lesssim \Lambda^{-r-D} \sum_{\lambda\leq\Lambda} \lambda^r 
\int_{-B_\s^-(0,2\Lambda)} d\tilde\x \int_{D_\y+\S^\vartheta\y-\bar\x-\tilde\x} d\tilde{\mathbf{w}} \\ 
&\quad\big| \big( F_{\tilde{\mathbf{w}}}(\,\cdot\,;\tilde{\mathbf{w}}+\bar\x+\tilde\x) 
- F_{\tilde{\mathbf{w}}-\S^\vartheta\y+\bar\x+\tilde\x}(\,\cdot\,;\tilde{\mathbf{w}}+\bar\x+\tilde\x) 
(\hat\varphi_{\tilde{\mathbf{w}}}^\lambda) \big| \, .
\end{align}
%
As for $b$ we argue that we can apply the assumption 
(with $\y'=-\S^\vartheta\y+\bar\x+\tilde\x$ and $\y''=\bar\x+\tilde\x$) 
and obtain 
%
\begin{align}
\int_{D_\y}d\tilde\x \, |d(\x)| 
&\lesssim \Lambda^{-r-D} \sum_{\lambda\leq\Lambda} \lambda^r 
\int_{-B_\s^-(0,2\Lambda)} d\tilde\x \, 
C \lambda^{\theta_1} (\lambda+\|\S^\vartheta\y-\bar\x-\tilde\x\|_\s)^{\theta_2} \\
&\lesssim C \Lambda^{-r} (\Lambda+\|v\y-\bar\x\|_\s)^{\theta_2} 
\sum_{\lambda\leq\Lambda} \lambda^{\theta_1+r} 
\lesssim C \Lambda^{\theta_1} (\Lambda+\|\S^\vartheta\y-\bar\x\|_\s)^{\theta_2} \, ,
\end{align}
%
where in the last inequality we used that by assumption $\theta_1+r>0$. 
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Proof of Lemma \texorpdfstring{\ref{lem:absorb}}{back to mathcal(U)}}\label{app:absorb}

Before we give the proof of Lemma~\ref{lem:absorb} 
we prove the following auxiliary lemma.

%
\begin{lemma}\label{lem:absorb_aux}
Let $\alpha\in(2/3,1)$, $\beta\in(2-\alpha,2\alpha]$, $0<R,T\leq1$, 
and recall $\nu$ defined in \eqref{eq:gubinelliderivative} for some sufficiently smooth $u$.
Then 
%
\begin{enumerate}[label=(\roman*)]
%
\item \label{ita:u_alpha}
for $f\in C^1(\R)$
%
\begin{equation}
[f(u)]_{B_{1,\infty}^\alpha}
\leq [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} R^{\beta-\alpha} 
+ \|f'\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_\alpha 
+ \|f'(u)\nu\|_{L^1} R^{1-\alpha} \, ,
\end{equation}
%
\item \label{ita:f(U)_2alpha}
for $f\in C^2(\R)$ with $f(v)=const$ for $|v|\geq C$
%
\begin{align}
&[f(\mathcal{U})]_{B_{1,\infty}^{\beta}} \\
&\leq \|f'\|_\infty [\mathcal{U}]_{B_{1,\infty}^{\beta}} \\
&\,+ \|f''\|_\infty \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty [\lolly]_\alpha 
\big(R^{2\alpha-\beta} \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_\alpha 
+ \|\1_{|u|\leq2C}\nu\|_{L^1} R^{1+\alpha-\beta} \big) \\
&\,+ R^{2\alpha-\beta} 2^{2-2\alpha} \|f'\|_\infty^{2-2\alpha} \|f''\|_\infty^{2\alpha-1} \|\1_{|u|\leq2C}\nu\|_{L^1}^{2-2\alpha} \|\1_{|u|\leq2C}\nu\|_{L^2}^{2(2\alpha-1)} \\
&\,+ 4/C \|f\|_\infty [\mathcal{U}]_{B_{1,\infty}^\beta} \\
&\,+\frac{2^{1+3\beta/(2\alpha)}}{C^{\beta/\alpha}} \|f\|_\infty 
\big(T [\lolly]_\alpha^{\beta/\alpha} \|\sigma\!/\!a^{\mathfrak{e}(\lollysmall)}\|_\infty^{\beta/\alpha} 
+ T^{1-\beta/(2\alpha)} \|\1_{|u|\leq C}\nu\|_{L^2}^{\beta/\alpha} R^{\beta/\alpha-\beta} \big)\, ,
\end{align}
%
%\item \label{ita:nu_0}
%$\|\nu\|_{L^1} 
%\leq \tfrac{\sqrt{d}}{\epsilon} \big( 2\|u\|_\infty T + \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_{\alpha} \epsilon^\alpha + [\mathcal{U}]_{B_{1,\infty}^{\beta}}\epsilon^{\beta} \big)$
%for all $0<\epsilon\leq R$, 
%
\item \label{ita:nu_2alpha-1}
for $f\in C^2(\R)$ and $\Theta$ from \eqref{eq:Theta}
%
\begin{align}
[f'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
&\leq \sqrt{d} \big(6 [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} \\
&\,+ R^{2\alpha-\beta} (\|(f'\!\sigma)'/a^{\mathfrak{e}(\lollysmall)}\|_\infty + \|f'\!\sigma/a^{1+\mathfrak{e}(\lollysmall)}\|_\infty) [\Theta(u)]_{B_{1,\infty}^\alpha} [\lolly]_\alpha\big) \, .
\end{align}
%
\end{enumerate}
%
\end{lemma}
%
\begin{proof}
%
\ref{ita:u_alpha}.
By the triangle inequality and the definitions of 
$[f(\mathcal{U})]_{B_{1,\infty}^{\beta}}$ and
$[\lolly]_\alpha$ we have
%
\begin{align}
&\int_{D_\y} d\x \big| f(u(\x+\y))-f(u(\x)) \big| \\
&\leq \int_{D_\y} d\x \big| f(u(\x+\y))-f(u(\x))-f'(u(\x))\big(\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\nu(\x)\cdot y \big) \big| \\
&\,+ \int_{D_\y} d\x\,|f'(u(\x))|\, \big| \sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\nu(\x)\cdot y \big| \\
&\leq
\|\y\|_\s^{\beta} [f(\mathcal{U})]_{B_{1,\infty}^{\beta}}
+ \|\y\|_\s^\alpha \|f'\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_\alpha 
+ \|f'(u)\nu\|_{L^1} \|\y\|_\s \, ,
\end{align}
%
hence the claim follows from the definition of $[\cdot]_{B_{1,\infty}^\alpha}$.

\ref{ita:f(U)_2alpha}.
For 
%
\begin{equation}\label{eq:f(U)}
f(u(\x+\y)) - f(u(\x)) - f'(u(\x))\big(\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\nu(\x)\cdot y\big)
\end{equation}
%
we split 
%
\begin{equation}
\int_{D_\y}d\x\,|\eqref{eq:f(U)}|
=\int_{D_\y}d\x\,|\eqref{eq:f(U)}|\1_{|u(\x)|\leq2C}
+\int_{D_\y}d\x\,|\eqref{eq:f(U)}|\1_{|u(\x)|>2C} \, .
\end{equation}
%
For the former integral we rewrite
%
\begin{align}
\eqref{eq:f(U)} 
&=f(u(\x+\y)) - f\big(u(\x)+\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\nu(\x)\cdot y\big) \label{eq:mt11}\\
&\,+ f\big(u(\x)+\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\nu(\x)\cdot y\big) \\
&\,- f\big(u(\x)+\nu(\x)\cdot y\big) - f'(u(\x))\sigma(u(\x)) \Pi_\x[\lolly;\x](\x+\y) \label{eq:mt12}\\
&\,+f\big(u(\x)+\nu(\x)\cdot y\big) - f(u(\x)) - f'(u(\x))\nu(\x)\cdot y \, . \label{eq:mt13}
\end{align}
%
For the first right hand side term we have by the fundamental theorem of calculus
%
\begin{align}
\eqref{eq:mt11} 
=\! \int_0^1\! d\vartheta \, f'\big(\vartheta u(\x\!+\!\y)+(1-\vartheta)(u(\x)+\sigma(u(\x))\Pi_\x[\lolly;\x](\x\!+\!\y)+\nu(\x)\cdot y)\big)& \\
\quad\times\big(u(\x+\y)-u(\x)-\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)-\nu(\x)\cdot y \big)& \, ,
\end{align}
%
and hence by 
the triangle inequality
and the definition of $[\mathcal{U}]_{B_{1,\infty}^{\beta}}$ that 
%
\begin{equation}
\int_{D_\y} d\x\, | \eqref{eq:mt11} | \1_{|u(\x)|\leq2C}
\leq \|f'\|_\infty [\mathcal{U}]_{B_{1,\infty}^{\beta}} \|\y\|_\s^{\beta} \, .
\end{equation}
%
For the second right hand side term we appeal twice to the fundamental theorem of calculus to obtain 
%
\begin{align}
\eqref{eq:mt12}
&=\!\int_0^1\! d\vartheta \,
f'\big( u(\x)\!+\!\vartheta \sigma(u(\x))\Pi_\x[\lolly;\x](\x\!+\!\y)\!+\!\nu(\x) \!\cdot\! y\big) 
\sigma(u(\x))\Pi_\x[\lolly;\x](\x\!+\!\y) \\
&\,- f'(u(\x))\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y) \\
&= \int_0^1 d\vartheta \int_0^1 d\bar{\vartheta} \,
f''\big( u(\x)+\vartheta\bar{\vartheta} \sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\bar{\vartheta}\nu(\x)\cdot y\big) \\
&\quad\times \sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y) 
\big( \vartheta\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y) + \nu(\x)\cdot y\big) \, ,
\end{align}
%
so that by the triangle inequality and the definition of $[\lolly]_\alpha$ 
%
\begin{align}
&\int_{D_\y} d\x |\eqref{eq:mt12}| \1_{|u(\x)|\leq2C} \\
&\leq \|f''\|_\infty \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty [\lolly]_\alpha \|\y\|_\s^\alpha
\big( \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty T [\lolly]_\alpha \|\y\|_\s^\alpha + \|\1_{|u|\leq2C}\nu\|_{L^1} \|\y\|_\s \big) \, .
\end{align}
%
The third right hand side term is analogously estimated by 
%
\begin{equation}
\int_{D_\y}d\x |\eqref{eq:mt13}| \1_{|u(\x)|\leq2C}
\leq \|f''\|_\infty \|\1_{|u|\leq2C}\nu\|_{L^2}^2 \|\y\|_\s^2 \, .
\end{equation}
%
Alternatively, we can appeal just once to the fundamental theorem of calculus and break the resulting terms up by the triangle inequality to obtain 
%
\begin{equation}
\int_{D_\y}d\x |\eqref{eq:mt13}| \1_{|u(\x)|\leq2C}
\leq 2\|f'\|_\infty \|\1_{|u|\leq2C}\nu\|_{L^1} \|\y\|_\s \, .
\end{equation}
%
Interpolating between these two estimates yields 
%
\begin{align}
&\int_{D_\y}d\x |\eqref{eq:mt13}| \1_{|u(\x)|\leq2C} \\
&\leq 2^{2-2\alpha} \|f'\|_\infty^{2-2\alpha} \|\1_{|u|\leq2C}\nu\|_{L^1}^{2-2\alpha}
\|f''\|_\infty^{2\alpha-1} \|\1_{|u|\leq2C}\nu\|_{L^2}^{2(2\alpha-1)} \|\y\|_\s^{2\alpha} \, .
\end{align}
%
We turn to the contributions from $\1_{|u(\x)|>2C}$. Note that $|u(\x)|>2C$ implies by the assumption on $f$ that $f'(u(\x))=0$, and thus 
%
\begin{align}
|\eqref{eq:f(U)}| \1_{|u(\x)|>2C}
&= |f(u(\x+\y))-f(u(\x))| \1_{|u(\x)|>2C} \\
&= |f(u(\x+\y))-f(u(\x))| \1_{|u(\x)|>2C} \1_{|u(\x+\y)|\leq C} \, ,
\end{align}
%
where in the last equality we used once more the assumption on $f$. 
Thus 
%
\begin{align}
&\int_{D_\y}d\x\,|\eqref{eq:f(U)}| \1_{|u(\x)|>2C} \\
%&=\int_{D_\y}d\x\, 
%|f(u(\x+\y))-f(u(\x))| \1_{|u(\x)|>2C} \1_{|u(\x+\y)|\leq C} \\
%&\quad\times\1_{|u(\x+\y)+\sigma(u(\x+\y))\Pi_{\x+\y}[\lollysmall;\x+\y](\x)-\nu(\x+\y)\cdot y|\leq3C/2}\\
%&\,+\int_{D_\y}d\x\, 
%|f(u(\x+\y))-f(u(\x))| \1_{|u(\x)|>2C} \1_{|u(\x+\y)|\leq C} \\
%&\quad\times\1_{|u(\x+\y)+\sigma(u(\x+\y))\Pi_{\x+\y}[\lollysmall;\x+\y](\x)-\nu(\x+\y)\cdot y|>3C/2} \\
&\leq 2\|f\|_\infty \int_{D_\y}d\x\, 
\1_{|u(\x)|>2C} 
\1_{|u(\x+\y)+\sigma(u(\x+\y))\Pi_{\x+\y}[\lollysmall;\x+\y](\x)-\nu(\x+\y)\cdot y|\leq3C/2} \quad\qquad \label{eq:mt14} \\
&\,+ 2\|f\|_\infty \int_{D_\y}d\x\, 
\1_{|u(\x+\y)|\leq C} 
\1_{|u(\x+\y)+\sigma(u(\x+\y))\Pi_{\x+\y}[\lollysmall;\x+\y](\x)-\nu(\x+\y)\cdot y|>3C/2} \label{eq:mt15} \, .
\end{align}
%
By a change of variables, using $D_\y+\y\subseteq D_{-\y}$, and by the inverse triangle inequality, we deduce
%
\begin{align}
\eqref{eq:mt14} 
&\leq 2\|f\|_\infty \! \int_{D_{-\y}}\!d\x\, 
\1_{|u(\x-\y)-u(\x)-\sigma(u(\x))\Pi_{\x}[\lollysmall;\x](\x-\y)-\nu(\x)\cdot (-y)|>C/2} \\
&\leq 2\|f\|_\infty \! \int_{D_{-\y}}\!d\x\, 
\tfrac{2}{C} |u(\x\!-\!\y)\!-\!u(\x)-\sigma(u(\x))\Pi_{\x}[\lolly;\x](\x\!-\!\y)\!-\!\nu(\x)\cdot (-y)| \\
&\leq 4/C \|f\|_\infty [\mathcal{U}]_{B_{1,\infty}^\beta} \|\y\|_\s^\beta \, .
\end{align}
%
The same argumentation reveals 
%
\begin{align}
\eqref{eq:mt15} 
&\leq 2\|f\|_\infty \! \int_{D_{-\y}}\!d\x\, 
\1_{|u(\x)|\leq C} \1_{|\sigma(u(\x))\Pi_{\x}[\lollysmall;\x](\x-\y)-\nu(\x)\cdot y|>C/2} \, .
\end{align}
%
On the one hand, this is bounded by $2\|f\|_\infty T$, while on the other hand it is bounded by 
%
\begin{align}
&2\|f\|_\infty \! \int_{D_{-\y}}\!d\x\, 
\1_{|u(\x)|\leq C} \tfrac{4}{C^2} |\sigma(u(\x))\Pi_{\x}[\lolly;\x](\x-\y)-\nu(\x)\cdot y|^2 \\
&\leq16/C^2 \|f\|_\infty \big( T [\lolly]_\alpha^2 \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty^2 \|\y\|_\s^{2\alpha}
+ \|\1_{|u|\leq C}\nu\|_{L^2}^2 \|\y\|_\s^2 \big) \, .
\end{align}
%
Interpolating between both estimates shows that $\eqref{eq:mt15}$ is bounded by 
%
\begin{align}
\frac{2^{1+3\beta/(2\alpha)}}{C^{\beta/\alpha}} \|f\|_\infty 
\big(T [\lolly]_\alpha^{\beta/\alpha} \|\sigma/a^{\mathfrak{e}(\lollysmall)}\|_\infty^{\beta/\alpha} \|\y\|_\s^{\beta}
+ T^{1-\beta/(2\alpha)} \|\1_{|u|\leq C}\nu\|_{L^2}^{\beta/\alpha} \|\y\|_\s^{\beta/\alpha} \big) \, .
\end{align}
%
Combining the estimates of \eqref{eq:mt11} -- \eqref{eq:mt15} with the definition of $[f(\mathcal{U})]_{B_{1,\infty}^{\beta}}$ yields the claim. 

\ref{ita:nu_2alpha-1}.
We introduce the shorthand notation
%
\begin{equation}
f(\mathcal{U})_\x(\x+\y) \coloneqq
f(u(\x+\y))-f(u(\x))-f'(u(\x))\big(\sigma(u(\x))\Pi_\x[\lolly;\x](\x+\y)+\nu(\x)\cdot y \big) \, .
\end{equation}
% 
Then 
%
\begin{align}
&\big(f'(u(\x+\y))\nu(\x+\y)-f'(u(\x))\nu(\x)\big)\cdot z \\
&= f(\mathcal{U})_\x(\x+\y+\z) - f(\mathcal{U})_\x(\x+\y) - f(\mathcal{U})_{\x+\y}(\x+\y+\z) \\
&\,+f'(u(\x))\sigma(u(\x)) \big( \Pi_\x[\lolly;\x](\x+\y+\z) - \Pi_\x[\lolly;\x](\x+\y) \big) \\
&\,- f'(u(\x+\y))\sigma(u(\x+\y))\Pi_{\x+\y}[\lolly;\x+\y](\x+\y+\z) \\
&= f(\mathcal{U})_\x(\x+\y+\z) - f(\mathcal{U})_\x(\x+\y) - f(\mathcal{U})_{\x+\y}(\x+\y+\z) \\
&\,+f'(u(\x))\sigma(u(\x)) \Pi_{\x+\y}[\lolly;\x](\x+\y+\z) \\
&\,- f'(u(\x+\y))\sigma(u(\x+\y)) \Pi_{\x+\y}[\lolly;\x+\y](\x+\y+\z) \, ,
\end{align}
%
where in the second equality we have used $\Pi_\x[\lolly;\x](\x+\y+\z)-\Pi_\x[\lolly;\x](\x+\y)=\Pi_{\x+\y}[\lolly;\x](\x+\y+\z)$ as a consequence of \eqref{eq:trafololly}.
We choose $\z\coloneqq e_i \|\y\|_\s$ for the $d$ unit vectors $e_1,\dots,e_d$ of $\R^d$, 
and note that $D_\y=D_{\y+\z}$ as $\z$ has no time component. 
Thus 
%
\begin{align}
\int_{D_\y}\! d\x\, |f(\mathcal{U})_\x(\x+\y+\z)| 
&=\!\int_{D_{\y+\z}} \! d\x\, |f(\mathcal{U})_\x(\x+\y+\z)| \\
&\leq [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} \! \|\y+\z\|_\s^{\beta} 
\leq 4 [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} \! \|\y\|_\s^{\beta} \, .
\end{align}
%
Similarly, since $D_\y+\y\subseteq [0,T]\times\T^d$ by the definition of $D_\y$ (see Theorem~\ref{thm:main}), 
and again since $[0,T]\times\T^d=D_\z$ as $\z$ has no time component, we deduce
%
\begin{align}
\int_{D_\y} d\x \, |f(\mathcal{U})_{\x+\y}(\x+\y+\z)| 
&=\int_{D_\y+\y} d\x \, |f(\mathcal{U})_\x(\x+\z)| \\
&\leq\int_{D_\z} d\x \, |f(\mathcal{U})_\x(\x+\z)| 
\leq [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} \|\y\|_\s^{\beta} \, .
\end{align}
%
Of course, also 
%
\begin{equation}
\int_{D_\y} |f(\mathcal{U})_\x(\x+\y)| \leq [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} \|\y\|_\s^{\beta} \, .
\end{equation}
%
Furthermore, 
by \eqref{eq:Theta} and the fundamental theorem of calculus we have
%
\begin{align}
&(f'\!\sigma)(u(\x))\Pi_{\x+\y}[\lolly;\x](\x+\y+\z)
- (f'\!\sigma)(u(\x+\y))\Pi_{\x+\y}[\lolly;\x+\y](\x+\y+\z) \\
&= \int_0^1 d\vartheta \, \partial_v \big( f'(v) \sigma(v) \Pi_{\x+\y}[\lolly;a(v)](\x+\y+\z) \big)_{|v=\vartheta \Theta(u(\x))+(1-\vartheta)\Theta(u(\x+\y))} \\
&\quad\times \big(\Theta(u(\x))-\Theta(u(\x+\y))\big) \, ,
\end{align}
%
and thus
%
\begin{align}
&\int_{D_\y}\! d\x\, \Big| 
(f'\!\sigma)(u(\x))\Pi_{\x+\y}[\lolly;\x](\x\!+\!\y\!+\!\z)
\!-\! (f'\!\sigma)(u(\x\!+\!\y))\Pi_{\x+\y}[\lolly;\x\!+\!\y](\x\!+\!\y\!+\!\z) \Big| \\
&\leq \big(\|(f'\!\sigma)'/a^{\mathfrak{e}(\lollysmall)}\|_\infty + \|f'\!\sigma/a^{1+\mathfrak{e}(\lollysmall)}\|_\infty \big) 
[\lolly]_\alpha \|\y\|_\s^\alpha [\Theta(u)]_{B_{1,\infty}^\alpha} \|\y\|_\s^\alpha \, ,
\end{align}
%
where we have used the definitions of $[\lolly]_\alpha$ and $[\cdot]_{B_{1,\infty}^\alpha}$.
Altogether we proved 
%
\begin{align}
&\int_{D_\y}d\x \, \big|f'(u(\x+\y))\nu_i(\x+\y)-f'(u(\x))\nu_i(\x)\big| \|\y\|_\s \\
&\leq \|\y\|_\s^{\beta} 
\big( 6 [f(\mathcal{U})]_{B_{1,\infty}^{\beta}} 
\!+\! \|\y\|_\s^{2\alpha-\beta} (\|(f'\!\sigma)'/a^{\mathfrak{e}(\lollysmall)}\|_\infty \!+\! \|f'\!\sigma/a^{1+\mathfrak{e}(\lollysmall)}\|_\infty) [\Theta(u)]_{B_{1,\infty}^\alpha} [\lolly]_\alpha \big) 
\end{align}
%
for $i=1,\dots,d$ which implies the desired estimate. 
\end{proof}

Equipped with Lemma~\ref{lem:absorb_aux} we are now in position to prove Lemma~\ref{lem:absorb}.

\begin{proof}[Proof of Lemma~\ref{lem:absorb}]
Combining Lemma~\ref{lem:absorb_aux}~\ref{ita:f(U)_2alpha} with 
%($N-(M-1)\geq0$)
$|\sigma/a^{\mathfrak{e}(\lollysmall)}|\lesssim 1$
from equation \eqref{eq:XVI}, 
using $\|f\|_\infty,\|f'\|_\infty,\|f''\|_\infty\lesssim1$, $R,T\leq1$, and $\|\cdot\|_{L^1}\leq\sqrt{T}\|\cdot\|_{L^2}$
we obtain 
%
\begin{align}
[f(\mathcal{U})]_{B_{1,\infty}^{\beta}} 
&\lesssimdata [\mathcal{U}]_{B_{1,\infty}^{\beta}} 
+ \|\1_{|u|\leq2C}\nu\|_{L^2}^{2\alpha} + \|\1_{|u|\leq2C}\nu\|_{L^2}^{\beta/\alpha} + 1 \, .\label{eq:f(U)_2alpha}
\end{align}
%
Plugging this into Lemma~\ref{lem:absorb_aux}~\ref{ita:u_alpha} and using once more 
%($N-(M-1)\geq0$)
$|\sigma/a^{\mathfrak{e}(\lollysmall)}|\lesssim 1$
from equation \eqref{eq:XVI}, 
$\|f'\|_\infty\lesssim1$, and the assumption of $f$, yields
%
\begin{align}
[f(u)]_{B_{1,\infty}^\alpha} 
&\lesssimdata R^{\beta-\alpha} \big([\mathcal{U}]_{B_{1,\infty}^{\beta}} + \|\1_{|u|\leq2C}\nu\|_{L^2}^{2\alpha} + \|\1_{|u|\leq2C}\nu\|_{L^2}^{\beta/\alpha}\big) \\
&\,+ R^{1-\alpha} \sqrt{T} \|\1_{|u|\leq2C}\nu\|_{L^2} 
+ 1 \, . \label{eq:u_alpha}
\end{align}
%
Similarly, using additionally 
%($N-1-(M-1)\geq0$)
$|\sigma'/a^{\mathfrak{e}(\lollysmall)}|\lesssim1$
from equation \eqref{eq:III}
and 
%($N-2(M-1)\geq0$)
$|\sigma/a^{1+\mathfrak{e}(\lollysmall)}|\lesssim1$
from equation \eqref{eq:V}, 
Lemma~\ref{lem:absorb_aux}~\ref{ita:nu_2alpha-1} implies for $C$ large enough ($\Theta$ is by construction constant outside a sufficiently large ball)
%
\begin{equation}\label{eq:nu_2alpha-1}
[f'(u)\nu]_{B_{1,\infty}^{\beta-1}} 
\lesssimdata [\mathcal{U}]_{B_{1,\infty}^{\beta}} 
+ \|\1_{|u|\leq2C}\nu\|_{L^2}^{2\alpha} + \|\1_{|u|\leq2C}\nu\|_{L^2}^{\beta/\alpha} + 1 \, .
\end{equation}
%

We're finally in position to tackle Item~\ref{it:nu^2_0}.
Note that for $1<p'\leq3-M$
%
\begin{equation}
\|\1_{|u|\leq2C}\nu\|_{L^2}^2
\lesssim \int_{[0,T]\times\T^d} d\z \, |u(\z)|^{p'-2} \,a(u(\z)) |\nu(\z)|^2
\lesssim 
\|u_0\|_{L^{p'}(\T^d)}^{p'} + C_{\eqref{eq:u2part3}} + 1 \, .
\end{equation}
%
The first inequality is an immediate consequence of Assumption~\ref{ass:nonlinearities}~(ii),
while the second inequality is exactly the content of Proposition~\ref{prop:energy}.
Choosing $p'\leq p$ with $p$ from Assumption~\ref{ass:initial} and plugging in $C_{\eqref{eq:u2part3}}$ from Proposition~\ref{prop:energy} we obtain 
%
\begin{align}
\|\1_{|u|\leq2C}\nu\|_{L^2}^2
\lesssimdata 
	1
	&+ [(g\sigma)(\mathcal{U})]_{B_{1,\infty}^{\beta}} 
	+ [\Theta(u)]_{B_{1,\infty}^\alpha}
	+ [\Theta'(u)\nu]_{B_{1,\infty}^{\beta-1}} \\
	&+ [\Theta(u)]_{B_{1,\infty}^\alpha}^{1/2} \|\Theta'(u)\nu\|_{L^2}
	+ \|\Theta'(u)\nu\|_{L^1} (\sqrt{T})^{\alpha-1} \, ,
\end{align}
%
where we recall that $g(v)=\int_0^vdw\,|w|^{p'-2}$. 
Using Cauchy-Schwarz in form of $\|\cdot\|_{L^1}\leq\sqrt{T}\|\cdot\|_{L^2}$, 
plugging in \eqref{eq:f(U)_2alpha} for $f=g\sigma$ 
(which by Assumption~\ref{ass:nonlinearities}~(ii) and \eqref{eq:restrictionM} is in $C^2(\R)$ and compactly supported), 
\eqref{eq:u_alpha} and \eqref{eq:nu_2alpha-1} for $f=\Theta$ 
(which by construction is constant outside a sufficiently large ball), 
and using $R,T\leq1$ yields for $C$ sufficiently large
%
\begin{align}
\|\1_{|u|\leq2C}\nu\|_{L^2}^2
&\lesssimdata 
	1
	+[\mathcal{U}]_{B_{1,\infty}^{\beta}} 
	+\|\1_{|u|\leq2C}\nu\|_{L^2}^{\max\{2\alpha,\beta/\alpha\}} \\
	&\quad+ \big([\mathcal{U}]_{B_{1,\infty}^{\beta}} 
		+\|\1_{|u|\leq2C}\nu\|_{L^2}^{\max\{2\alpha,\beta/\alpha\}}\big)^{1/2} 
	\|\1_{|u|\leq2C}\nu\|_{L^2} \\
&\lesssim 
	1
	+[\mathcal{U}]_{B_{1,\infty}^{\beta}} 
	+[\mathcal{U}]_{B_{1,\infty}^{\beta}}^{1/2} \|\1_{|u|\leq2C}\nu\|_{L^2}
	+ \|\1_{|u|\leq2C}\nu\|_{L^2}^{\max\{2\alpha,\beta/\alpha\}/2+1} \, .
\end{align}
%
Observe that $\max\{2\alpha,\beta/\alpha\}/2+1<2$ by assumption. 
%\mt{this is where the restriction $\beta<2\alpha$ comes from. It could be avoided by keeping track of $R,T$, since $\|\1_{|u|\leq2C}\|^{L^2}^{\beta/\alpha}$ comes with a prefactor, which could be chosen to be small to absorb. The current version does not need $R,T$ to be small.}
We conclude the proof of Item~\ref{it:nu^2_0} by absorbing $\|\1_{|u|\leq2C}\nu\|_{L^2}$ as follows. 
We claim that 
$x\leq C_1 x^{\epsilon_1} + C_2 x^{\epsilon_2} +C_3$ for $0<\epsilon_1,\epsilon_2<1$ and some constants $C_1,C_2,C_3>0$ implies 
$x\lesssim C_1^{1/(1-\epsilon_1)} + C_2^{1/(1-\epsilon_2)} + C_3$. 
To prove this claim we distinguish two cases. 
In the case $x\geq(3C_1)^{1/(1-\epsilon_1)}$ and $x\geq(3C_2)^{1/(1-\epsilon_2)}$ 
we have $x^{\epsilon_1}\leq x/(3C_1)$ and $x^{\epsilon_2}\leq x/(3C_2)$ 
and thus 
%
\begin{equation}
x\leq C_1 x^{\epsilon_1} + C_2 x^{\epsilon_2} +C_3
\leq x/3 + x/3 +C_3 \, .
\end{equation}
%
In particular $x\leq3 C_3 \lesssim C_1^{1/(1-\epsilon_1)} + C_2^{1/(1-\epsilon_2)}+C_3$.
We conclude with noting that the remaining case is 
$x<(3C_1)^{1/(1-\epsilon_1)}$ or $x<(3C_2)^{1/(1-\epsilon_2)}$.

This establishes $\|\1_{|u|\leq2C}\nu\|_{L^2}^2\lesssim [\mathcal{U}]_{B_{1,\infty}^\beta} +1$, 
and Item~\ref{it:nu^2_0} follows from $|f'(u)|\lesssim\1_{|u|\leq2C}$. 
The remaining Items~\ref{it:u_alpha}, \ref{it:f(U)_2alpha}, and \ref{it:nu_2alpha-1}
follow by plugging the already established bound on $\|\1_{|u|\leq2C}\nu\|_{L^2}^2$ into \eqref{eq:f(U)_2alpha} -- \eqref{eq:nu_2alpha-1} and using $R,T\leq1$.
\end{proof}

