\title{On the non-convexity issue in the radial Calder\'on problem}
\author{Giovanni S. Alberti\thanks{Machine Learning Genoa Center (MaLGa), Department of Mathematics, Department of Excellence 2023–2027, University of Genoa (\url{giovanni.alberti@unige.it}).} \and Romain Petit\thanks{CNRS and DMA, ENS, PSL Universit\'e (\url{romain.petit@ens.fr}).} \and Clarice Poon\thanks{Mathematics Institute, University of Warwick (\url{clarice.poon@warwick.ac.uk}).}}

