\paragraph{Plan of the paper.} In \Cref{sec_pc_radial}, we introduce the setting of piecewise constant radial conductivities. In \Cref{sec_convex}, we introduce the resolution method introduced in \cite{harrachCalderonProblemFinitely2023} and propose a method for estimating all the parameters of the related convex program. In \Cref{sec_num_comparison}, we perform an extensive numerical comparison of this method with the least squares approach. Finally, in \Cref{sec_theory}, we analyze the case of conductivities that are defined by two scalar unknowns, and discuss the extension of our results to the higher dimensional setting.

\section{Piecewise constant radial conductivities}
\label{sec_pc_radial}
In this section, we introduce the setting of radial piecewise constant conductivities, which has all the important features of the full Calder\'on problem. Its main interest is to allow the evaluation of the forward map without having to rely on finite element methods to solve the underlying PDE. This allows us to decouple the study of the inverse problem and its ill-posedness from the effect of numerical errors in the evaluation of the forward map.

\subsection{Setting}\label{sub:setting}
We work on the two-dimensional open unit ball $\Omega=B(0,1)$ and assume that the unknown conductivity is piecewise constant on a known partition of $\Omega$ made of concentric annuli. More precisely, we use the polar coordinates $(r,\theta)$ and assume that $\gamma(r,\theta)$ is equal to a positive constant $\sigma_i>0$ for every $r_{i}<r<r_{i-1}$ with $0=r_n<r_{n-1}<...<r_0=1$ (see \Cref{fig_radial} for a schematic description). For every vector $\sigma\in(\RR_{>0})^n$, we denote by $\gamma_{\sigma}$ the associated function, where $\RR_{>0}$ denotes the set of positive real numbers.

\begin{figure}
    \centering
    \input{plots/fig_radial}
    \caption{schematic description of the piecewise constant radial setting. The conductivity $\gamma:B(0,1)\to \RR$ is such that, using the polar coordinates $(r,\theta)$, it holds $\gamma(r,\theta)=\sigma_i$ for every $r_{i}<r<r_{i-1}$ for some $\sigma=(\sigma_i)_{1\leq i\leq n}\in (\RR_{>0})^n$.}
    \label{fig_radial}
\end{figure}

As noticed in \citet[Lemma 4.1]{siltanenImplementationReconstructionAlgorithm2000}, taking the Neumann data to be cosine functions allows us to obtain a diagonal Neumann-to-Dirichlet map. To be more precise, we fix a number of scalar measurements $m$, and,  given $j\in\{1,...,m\}$, we define $g_j:\partial \Omega\to\RR$ by $g_j(\theta)=\cos(j\theta)$. We notice as in \citet[Lemma 4.1]{siltanenImplementationReconstructionAlgorithm2000} that if $u_j(r,\theta)=(\alpha_{i,j}r^j+\beta_{i,j}r^{-j})\mathrm{cos}(j\theta)$ for every $r_{i}<r<r_{i-1}$ then $u_j$ is a solution to the Neumann problem for the conductivity equation
\begin{equation*}
    \begin{cases}
        \mathrm{div}(\gamma_\sigma\nabla u_j)=0 &\mathrm{in}~\Omega,\\
        \gamma_\sigma \partial_{\nu}u_j=g_j &\mathrm{on}~\partial\Omega,
    \end{cases}
\end{equation*}
provided $\beta_{n,j}=0$, $\sigma_1j(\alpha_{1,j}-\beta_{1,j})=1$ and
\begin{equation}
    \left\{
    \begin{aligned}
        \alpha_{i,j}r_i^j+\beta_{i,j}r_i^{-j}&=\alpha_{i+1,j}r_i^j+\beta_{i+1,j}r_i^{-j},\\
        \sigma_i(\alpha_{i,j}r_i^j-\beta_{i,j}r_i^{-j})&=\sigma_{i+1}(\alpha_{i+1,j}r_i^j-\beta_{i+1,j}r_i^{-j}),
    \end{aligned}
    \right.
    \label{linear_system_pde_coeff}
\end{equation}
for every $1\leq i\leq n-1$ and $1\leq j\leq m$. It is shown in \citet[Lemma 4.1]{siltanenImplementationReconstructionAlgorithm2000} that the solution of \eqref{linear_system_pde_coeff} satisfies $\beta_{i,j}=C_{i,j}\alpha_{i,j}$ with
\begin{equation}
    \begin{aligned}
        C_{n,j}=0~~\mathrm{and}~~C_{i,j}=\frac{\rho_i r_i^{2j}+C_{i+1,j}}{1+\rho_i C_{i+1}r_i^{-2j}},
    \end{aligned}
    \label{rec_rel_C}
\end{equation}
where $\rho_i\eqdef(\sigma_{i}-\sigma_{i+1})/(\sigma_{i}+\sigma_{i+1})$.

Since $\restriction{u_j}{\partial\Omega}=(\alpha_{1,j}+\beta_{1,j})\cos(j\theta)$, we obtain that the Neumann-to-Dirichlet map introduced in \Cref{subsec_eit_calderon} satisfies $\Lambda(\gamma_{\sigma})g_j=\lambda_j(\sigma)g_j$ with 
\begin{equation}
    \lambda_j(\sigma)\eqdef \frac{1+C_{1,j}}{j\sigma_1(1-C_{1,j})}.
\end{equation}
\paragraph{Finite-dimensional forward map.} Abusing notation, we also denote by $\Lambda$ the mapping 
\begin{equation*}
    \begin{aligned}
        \Lambda \colon (\RR_{>0})^n &\to \RR^m\\
        \sigma &\mapsto [\lambda_j(\sigma)]_{j=1}^m.
    \end{aligned}
\end{equation*}
In the following, we focus on the recovery of $\sigma$ from the knowledge of $\Lambda(\sigma)$, which is an inverse problem with a finite-dimensional unknown and finitely many measurements.

In practice, the forward map $\Lambda$ can be evaluated by computing $C_{1,j}$ using \eqref{rec_rel_C} and plugging the result in the expression of $\lambda_j(\sigma)$. The Jacobian and the Hessian of $\Lambda$ can also be computed efficiently via automatic differentiation. To compute them, we use the package \texttt{ForwarDiff.jl} \citep{revelsForwardModeAutomaticDifferentiation2016} via \texttt{DifferentiationInterface.jl} \citep{dalleDifferentiationInterface2025,hill2025sparserbetterfasterstronger,schäfer2022abstractdifferentiationjlbackendagnosticdifferentiableprogramming}.

The following proposition gives some properties of the forward map $\Lambda$, on which we crucially rely.
\begin{proposition}
    The mapping $\Lambda$ is convex. In addition, it is strictly decreasing, meaning that for every $\sigma,\sigma'\in (\RR_{>0})^n$ with $\sigma\leq \sigma'$ (pointwise) and $\sigma\neq \sigma'$, it holds $\lambda_j(\sigma)>\lambda_j(\sigma')$ for every $1\leq j\leq m$.
    \label{prop_forward_map}
\end{proposition}
\begin{proof}
    The convexity of $\Lambda$ is proved in \cite[Lemma 4.1]{harrachCalderonProblemFinitely2023}. From the same reference, we have that
    \begin{equation}\label{eq:derivative_explicit}
        \partial_i\lambda_j(\sigma)=-\frac{1}{\pi}\int_{A_i}|\nabla u_j|^2,
    \end{equation}
    where $A_i$ denotes the annulus $r_i<r<r_{i-1}$. We claim that this quantity is positive for every $1\leq i\leq n$ and $1\leq j \leq m$. To see this, we notice that, since $\gamma_{\sigma}$ is lower bounded by the positive constant $\mathrm{min}_{1\leq i\leq n}\,\sigma_i$, the differential operator $\mathrm{div}(\gamma_{\sigma}\nabla\cdot)$ is uniformly elliptic. As a result, the strong unique continuation principle (see for instance \cite{alessandriniStrongUniqueContinuation2012}) ensures that, if $u_j$ vanishes on a non empty open set, it is identically zero. Since the boundary data $g_j$ is not identically zero, we obtain that $u_j$ is not identically zero. If $u_j$ was equal to a constant on a non empty open set, the same argument could be applied to $u_j$ minus this constant, which still solves $\mathrm{div}(\gamma_{\sigma}\nabla u_j)=0$. As a result, we obtain that $\nabla u_j$ cannot vanish on a non empty open set, which yields the result.
\end{proof}

\subsection{Numerical study of the inverse problem}
\label{subsec_numerical_study_ip}
In this section, we present several experiments suggesting that this simple piecewise constant radial model exhibits all the important features of the classical Calder\'on problem. In particular, the estimation problem becomes increasingly ill-posed away from the boundary. In the following, we take $r_i=(n-i)/n$ ($i=0,...,n$).

Our first experiment shows that the estimation of the conductivity is much harder on annuli that are distant from the boundary. We take $n=m=10$ and draw $100$ random true conductivities uniformly in $[a,b]^n$ with $a=0.5$ and $b=1.5$. Then, we use a Newton trust region algorithm to solve the nonlinear equation $\Lambda(\sigma)=\Lambda(\sigma^\dagger)$ for each true conductivity $\sigma^\dagger$. For each instance, the algorithm is randomly initialized and re-run until the estimated conductivity $\hat{\sigma}$ satisfies $\|\Lambda(\hat{\sigma})-\Lambda(\sigma^\dagger)\|_{\infty}\leq 10^{-15}$.\footnote{Re-initializing was required in $20$ out of $100$ instances, with up to $7$ re-initialization for some instances.} Then, we compute the mean of $|\hat{\sigma}_i-\sigma^\dagger_i|$ for each $i\in\{1,...,n\}$. The result is given in \Cref{fig_error_outer_inner}. We notice that the average error increases by several orders of magnitude as $i$ grows. This is consistent with the well-known fact that the reconstruction quality deteriorates as one moves away from the boundary, see e.g.\ \cite{winkler-rieder-2014,garde-knudsen-2017,alessandrini-scapin-2017,garde-nyvonen-2020}. Taking $m$ much larger than $n$ yields similar results. 

Our second experiment shows that the inverse problem becomes more and more ill-posed as $n$ grows, as expected given the severe ill-posedness of the infinite-dimensional inverse problem, see \cite{rondi-2006}. Indeed, given $\epsilon>0$, we notice that the quantity
\begin{equation*}
    \underset{\sigma,\sigma'\in[a,b]^n}{\mathrm{sup}}~\|\sigma-\sigma'\|_{\infty}~~\mathrm{s.t.}~~\|\Lambda(\sigma)-\Lambda(\sigma')\|_{\infty}\leq\epsilon
\end{equation*}
significantly increases as $n$ increases. To show this, we run the same experiment as above with $n=m$ ranging from $2$ to $10$. The results are displayed in \Cref{fig_mean_error_npixels}. Again, taking $m$ much larger than $n$ yields similar results.
