\section{Identifiability and absence of bad critical points}
\label{sec_theory}
Motivated by the good performance of the least squares approach observed in \Cref{sec_num_comparison}, we prove in this section that, when $n=2$ and $m\geq 2$, the forward map $\Lambda$ is injective. We also show that, when $n=m=2$, for every $\sigma^\dagger\in(\RR_{>0})^n$, the least squares objective $\sigma\mapsto\|\Lambda(\sigma)-\Lambda(\sigma^\dagger)\|_2^2$ has a unique critical point, which is $\sigma^\dagger$. Finally, we provide a discussion concerning the case where $n>2$. Our results suggest that, in this piecewise constant radial setting, the main difficulty for solving the inverse problem is not the nonconvexity of the least squares objective, but rather the ill-posedness of the problem.

Throughout, given $\Lambda: \sigma\in (\RR_{>0})^n \to (\lambda_i(\sigma))_{i=1}^m$, its Jacobian is denoted by $\Lambda'(\sigma)\in\RR^{m\times n}$ with its $(j,i)$-th entry in row $j$ and column $i$ being $\partial_i \lambda_j(\sigma)$.

\subsection{The two-dimensional case}
We first state the following useful lemma.
\begin{lemma}\label{lem:2d}
    Let $n=m=2$ and consider $\Lambda:\sigma\mapsto(\lambda_1(\sigma),\lambda_2(\sigma))$. Then, the determinant of the Jacobian is negative, that is to say $\det(\Lambda'(\sigma))<0$ for all $\sigma\in(\RR_{>0})^2$.
\end{lemma}
\begin{proof}
As shown in the proof of Proposition~\ref{prop_forward_map}, we have $\partial_i\lambda_j(\sigma)>0$. Let 
$$
h_j(\sigma) \eqdef \frac{\partial_1 \lambda_j (\sigma)}{\partial_2 \lambda_j(\sigma)}.
$$
Then, one can check (we obtained this expression by relying on a symbolic computation tool):  
\begin{align}
    h_j(\sigma) = \frac{1}{4\sigma_1^2} \left(\frac{1}{r_1^{2j}} (\sigma_1+\sigma_2)^2 - \frac{1}{r_1^{2j}}(\sigma_1-\sigma_2)^2 - 4\sigma_1\sigma_2\right),\qquad \sigma=(\sigma_1,\sigma_2)\in(\RR_{>0})^2,
\end{align}
which is clearly increasing in $j$, since $r_1\in (0,1)$ implies that each of the terms is increasing in $j$.
It follows that $$\det(\Lambda'(\sigma)) = \partial_1\lambda_1(\sigma) \partial_2\lambda_2(\sigma) - \partial_1\lambda_2(\sigma) \partial_2\lambda_1(\sigma) =\partial_2\lambda_2(\sigma)\partial_2\lambda_1(\sigma)[h_1(\sigma)-h_2(\sigma)]<0,$$
where we have used also that $\partial_i\lambda_1(\sigma)>0$ ($i=1,2$).
\end{proof}

Now, we prove that the unknown conductivity can be recovered from two scalar measurements. To our knowledge, the best identifiability results that are currently available require a number of measurements which is exponential in the number of unknowns \citep{albertiInfiniteDimensionalInverseProblems2022}.
\begin{proposition}\label{prop:2d_inj}
    If $n=2$ and $m\geq 2$, the forward map $\Lambda$ is injective.
\end{proposition}
\begin{proof}
   It is enough to prove the result in the case $m=2$. Let $\sigma^\dagger,\hat \sigma\in(\RR_{>0})^2$ be such that 
     $\sigma^\dagger \neq  \hat \sigma$ and $\Lambda(\sigma^\dagger) = \Lambda(\hat \sigma)$. By strict monotonicity {(Proposition~\ref{prop_forward_map})}, we can assume without loss of generality that $\sigma^\dagger_1<\hat \sigma_1$ and $\sigma^\dagger_2> \hat \sigma_2$.

     We first show that there exists a function $g:[\sigma^\dagger_1,\hat \sigma_1] \to [ \hat \sigma_2,\sigma^\dagger_2]$ such that $\lambda_1(\sigma_1,g(\sigma_1)) = \lambda_1(\sigma^\dagger)$ for every $\sigma_1\in[\sigma_1^\dagger,\hat{\sigma}_1]$. For visualization purposes, the graph of this function, as well as the graph of the function $h$ that we compute below, is given in \Cref{fig_g_h} in the case where $\sigma^\dagger=\mathbf{1}$. Define $f(\sigma) = \lambda_1(\sigma) - \lambda_1(\sigma^\dagger)$. Then, by monotonicity,
     \begin{itemize}
         \item $f$ is negative on $(\sigma^\dagger_1,\hat \sigma_1)\times \{\sigma_2^\dagger\}$,
         \item $f$ is positive on $(\sigma^\dagger_1,\hat \sigma_1)\times \{\hat \sigma_2\}$.
     \end{itemize}
     It follows by the intermediate value theorem that for all $\sigma_1 \in (\sigma^\dagger_1,\hat \sigma_1)$, there exists $\sigma_2 \in (\hat \sigma_2,\sigma^\dagger_2)$ such that $f(\sigma_1,\sigma_2) = 0$. This shows that $g$ is well defined. Moreover, since $\partial_2 \lambda_1 <0$, it follows by the implicit function theorem that $g$ is of class $C^1$ and $g'(\sigma_1) = - \partial_1 \lambda_1(\sigma, g(\sigma_1))/\partial_2 \lambda_1(\sigma_1, g(\sigma_1)).$

 \begin{figure}
    \centering
    \subfloat[]{\includegraphics[width=3in]{plots/plot_g}}~
    \subfloat[]{\includegraphics[width=3in]{plots/plot_h}}
\caption{graph of the functions $g$ and $h$ constructed in the proof of \Cref{prop:2d_inj}, with $\sigma^\dagger=\mathbf{1}$. The function $h$ is strictly monotone, showing that the forward map is injective.}
    \label{fig_g_h}
\end{figure}

     Now consider $h(\sigma_1) = \lambda_2(\sigma_1,g(\sigma_1))$. Since $g(\sigma_1^\dagger) = \sigma_2^\dagger$ and $g(\hat \sigma_1) =\hat  \sigma_2$, by  assumption, $h(\sigma_1^\dagger) = h(\hat \sigma_1)$. Observe also that
     $$
     h'(\sigma_1) = \partial_1\lambda_2(\sigma_1,g(\sigma_1)) + \partial_2 \lambda_2(\sigma_1,g(\sigma_1)) g'(\sigma_1) = \frac{(\partial_1\lambda_2 \partial_2 \lambda_1 - \partial_1\lambda_1 \partial_2\lambda_2) }{\partial_2\lambda_1},
     $$
     where each term on the right-hand side is evaluated at $(\sigma_1,g(\sigma_1))$. We have $h'(\sigma_1)>0$ for every $\sigma_1 \in (\sigma^\dagger_1,\hat \sigma_1)$ by Lemma~\ref{lem:2d}, which contradicts the assumption that $h$ takes the same value on two distinct points.    
\end{proof}

Finally, we prove that, when $m=n=2$, the least squares objective does not have any spurious critical point.
\begin{proposition}
    If $n=m=2$, for every $\sigma^\dagger\in(\RR_{>0})^n$, the least squares objective $$f:\sigma\mapsto \frac{1}{2}\|\Lambda(\sigma)-\Lambda(\sigma^\dagger)\|_2^2$$ has a unique critical point on $(\RR_{>0})^n$, which is $\sigma^\dagger$.
    \label{prop_critical_point}
\end{proposition}
\begin{proof}
    Let $\sigma$ be a critical point. We have $\nabla f(\sigma)=\Lambda'(\sigma)(\Lambda(\sigma) - \Lambda(\sigma^\dagger)) = 0$. Since $\Lambda'(\sigma)\in\RR^{2\times 2}$ is injective (by \Cref{lem:2d}), this implies $\Lambda(\sigma) - \Lambda(\sigma^\dagger)= 0$. By injectivity of $\Lambda$ (Proposition~\ref{prop:2d_inj}), we obtain $\sigma= \sigma^\dagger$.
\end{proof}

\begin{remark}
    Surprisingly, the argument we use to prove \Cref{prop_critical_point} does not allow us to conclude that the result holds when $m>n$. One could think that having more measurements should make the estimation easier, and numerical experiments indeed suggest that increasing the number of measurements does not introduce new spurious critical points. However, we were not able to prove the result with $m>n$. 
\end{remark}

\subsection{The higher dimensional case}
In this section, we discuss the extension of the above results to the case $n>2$. We restrict ourselves to the case $m=n$. Given $\sigma\in(\RR_{>0})^n$, we denote by $\Lambda_{[n-1]}'(\sigma) \in \RR^{(n-1)\times (n-1)}$ the submatrix of $\Lambda'(\sigma)\in\RR^{n\times n}$ obtained by removing its last row (corresponding to the last measurement) and its first column (corresponding to the outermost annulus).

\subsubsection{Main result}
Our main result shows that, provided the following two conditions hold, the least squares objective has a unique critical point, which is the unknown conductivity. We discuss these conditions in greater details at the end of this section.
\begin{itemize}
    \item[(i)] Jacobian invertibility: for every $n\geq 2$ and every $\sigma\in (\RR_{>0})^n$, $\Lambda'(\sigma)$ and $\Lambda'_{[n-1]}(\sigma)$ are invertible.

    \item[(ii)] Alternating signs: for every $n\geq 2$, if $\sigma^\dagger, \hat \sigma \in (\RR_{>0})^n$ are such that $\sigma^\dagger_1 < \hat \sigma_1$ and $\lambda_j(\sigma^\dagger) = \lambda_j(\hat \sigma)$ for every $j=1,\ldots, n-1$, then $\mathrm{sign}( \sigma^\dagger_i -  \hat \sigma_i) = (-1)^i$ for every $2\leq i\leq n$, that is to say $\sigma_2^\dagger>\hat \sigma_2^\dagger$, $\sigma_3^\dagger<\hat \sigma_3^\dagger$, and so on.
\end{itemize}

\begin{proposition}
    Assume that conditions (i) and (ii) hold. Then, for every $n\geq 2$ and $m=n$, the least squares objective $f:\sigma\mapsto(1/2)\norm{\Lambda(\sigma)-\Lambda(\sigma^\dagger)}^2$ has $\sigma^\dagger$ as its  unique critical point in $(\RR_{>0})^n$.
    \label{prop_absence_critical_point_d}
\end{proposition}
\begin{proof}
    Just as in the $n=2$ setting, since condition (i) guarantees that $\Lambda'(\sigma)$ is invertible, it is sufficient to show that $\Lambda$ is injective. We prove the injectivity by induction on $n$. For $n=2$, this follows by Proposition~\ref{prop:2d_inj}. Assume now that the result is true for $n-1$. Suppose by contradiction that there exist distinct $\sigma^\dagger$ and $\hat \sigma$ such that $\Lambda(\sigma^\dagger) = \Lambda(\hat \sigma)$. Note that $\sigma^\dagger_i\neq \hat \sigma_i$ for all $i$, otherwise, this contradicts our induction assumption on the injectivity of $\Lambda$. Without loss of generality, we assume that $\hat \sigma_1>\sigma_1^\dagger$. By the alternating signs condition (ii), we have $\sigma_2^\dagger>\hat \sigma_2^\dagger$, $\sigma_3^\dagger<\hat \sigma_3^\dagger$, and so on.

    Let $I\eqdef [\sigma_1^\dagger,\hat \sigma_1]$. We first claim that for all $\sigma_1\in I$, there exists a differentiable function $g\colon I \to (\RR_{>0})^{n-1}$ such that 
    $$
    \forall j=1,\ldots,n-1, \quad \lambda_j(\sigma_1, g(\sigma_1))  = \lambda_j(\sigma^\dagger).
    $$
    Certainly, any such $g$ satisfies $g(\sigma^\dagger_1) = (\sigma^\dagger_i)_{i=2}^{n-1}$ and $g(\hat \sigma_1) = (\hat \sigma_i)_{i=2}^{n-1}$.  Note also that  by the implicit function theorem, any such  $g$  has differential
    \begin{equation}\label{eq:derivative_g}
    g'(\sigma_1) = -(\Lambda_{[n-1]}')^{-1} \left(\partial_1 \lambda_j\right)_{j=1}^{n-1},
    \end{equation}
    where, as a slight abuse of notation, we write $\Lambda_{[n-1]}' \eqdef\Lambda_{[n-1]}'(\sigma_1,g(\sigma_1)) $. Note that, by assumption (i), $\Lambda_{[n-1]}'$ is invertible.

    We now claim that $g$ is well defined on $I$  and maps into the cuboid
    $$
    B = [\hat \sigma_2,  \sigma_2^\dagger] \times [\sigma_3^\dagger, \hat \sigma_3] \times [\hat \sigma_4,  \sigma_4^\dagger] \times \cdots .
    $$
    Indeed, since $C = \{\sigma\in(\RR_{>0})^n:\;\forall j=1,\ldots, n-1,\; \lambda_j(\sigma) = \lambda_j(\sigma^\dagger)\}$ is a closed set, the only reason why $g$ might not exist on $I$ is that $g(\sigma_1)_i$ diverges to infinity or converges to $0$. This cannot happen because we can  apply the implicit function theorem at $\hat \sigma$ (and $\sigma^\dagger$) to conclude that $g$ exists on a neighborhood around $\hat \sigma$ (respectively $\sigma^\dagger$). So, there exists $\epsilon>0$ such that $g(\sigma_1^\dagger + \epsilon)$ and $g(\hat \sigma_1-\epsilon)$ are well defined and are strictly inside the set $B$ by the alternating signs assumption.
    Note also that since the set $C$ is closed, if it is made of disjoint closed intervals inside $B$, then we can apply the implicit function theorem to the end points of these intervals to extend $g$. So, there exists a continuously differentiable function $g\colon I\to B$.


    Now consider $h\colon I\to (\RR_{>0})^{n-1}$ defined by $h(\sigma_1) = \lambda_n(\sigma_1, g(\sigma_1))$. We aim to show that $h'(\sigma_1)\neq 0$ for all $\sigma_1 \in I$ which would lead to a contradiction by Rolle's theorem since we know that $h(\sigma_1^\dagger) = h(\hat \sigma_1) = \lambda_n(\sigma^\dagger)$. Indeed, 
    $$
    h'(\sigma_1) = \partial_1 \lambda_n + \langle{(\partial_i \lambda_n)_{i=2}^{n}},{g'(\sigma_1)}\rangle = \partial_1 \lambda_n - \langle{(\partial_i \lambda_n)_{i=2}^{n}},{(\Lambda'_{[n-1]})^{-1} (\partial_1\lambda_j)_{j=1}^{n-1}}\rangle =\frac{ \mathrm{det}(\Lambda'(\sigma))}{\mathrm{det}(\Lambda_{[n-1]}'(\sigma))},
    $$
    where the final inequality is due to the  determinant formula for block matrices. Since $\Lambda'(\sigma)$ is invertible, we must have $h'(\sigma_1)\neq 0$ for all $\sigma_1 \in I$.
\end{proof}

\begin{remark}
     We mention here that if condition (i) was relaxed to $\Lambda'(\sigma)$ is invertible for every $n\geq 2$ and every $\sigma \in B\eqdef [a,b]^n$ for some $0<a<b$ and $\sigma^\dagger$ is in the interior of $B$, then our proof implies that the least squares objective $f$ has only one critical point in the interior of $B$.  As we discuss in the following section, in practice, we observe numerically that the Jacobian $\Lambda'(\sigma)$  has non-zero determinant for every $\sigma\in(\RR_{>0})^n$.
\end{remark}

\subsubsection{Discussion on the assumptions} Now, we go back to the two conditions under which the result of \Cref{prop_absence_critical_point_d} holds. 
\paragraph{Condition (i).} 
We first rigorously prove that this condition is satisfied in the case where $\sigma= \mathbf{1}$. The proof makes use of the fact that, in this case, we only need to deal with harmonic functions, whose explicit expression is simple.
\begin{lemma}
    If $\sigma= \mathbf{1}$ and $m=n$ then 
    \begin{equation}\label{eq:sign_det}
    (-1)^{\frac{n(n+1)}{2}}\det \Lambda'(\sigma) >0 \quad \text{and}\quad  (-1)^{\frac{n(n-1)}{2}}\det \Lambda_{[n-1]}'(\sigma) >0.
\end{equation}
\end{lemma}
\begin{proof}
    Since $\sigma= \mathbf{1}$, we have that $u_j(r,\theta) = j^{-1}r^j \cos(j\theta)$ (see Section~\ref{sub:setting}), so that $|\nabla u_j(r,\theta)|^2=r^{2(j-1)}$, for $j=1,\dots,n$. Thus, by \eqref{eq:derivative_explicit}, we have 
    \[
    \partial_i\lambda_j(\sigma)=-\frac{1}{\pi}\int_{r_i}^{r_{i-1}} \int_0^{2\pi}|\nabla u_j(r,\theta)|^2 r\,d\theta dr = - j^{-1} (r_{i-1}^{2j}-r_{i}^{2j}) .
    \]
    Let $A_i\in \RR^n$ be the column vector given by $(A_i)_j = R_i^{j}$, where $R_i = r_i^2$. Note that $A_n=0$. Then, using that the determinant is a multilinear function, we obtain
    \[
   \det \Lambda'(\sigma) = \frac{(-1)^n}{n!} \det [A_0-A_1,A_1-A_2,\dots,A_{n-2}-A_{n-1},A_{n-1}]
   = \frac{(-1)^n}{n!} \det [A_0,A_1,\dots,A_{n-2},A_{n-1}].
    \]
    Therefore
\[
\det \Lambda'(\sigma) = \frac{(-1)^n}{n!} \det
\begin{bmatrix}
    R_0 & R_1& \cdots & R_{n-1} \\
    R_0^2 & R_1^2& \cdots & R_{n-1}^2 \\
    \vdots & \vdots & \dots & \vdots \\
    R_0^n & R_1^n& \cdots & R_{n-1}^n 
\end{bmatrix}
= \frac{(-1)^n}{n!} \left(\prod_{i=1}^{n-1} R_i\right)\det
\begin{bmatrix}
    1 & 1& \cdots & 1 \\
    R_0 & R_1& \cdots & R_{n-1} \\
    \vdots & \vdots & \dots & \vdots \\
    R_0^{n-1} & R_1^{n-1}& \cdots & R_{n-1}^{n-1} 
\end{bmatrix}.
\]
The latter is a Vandermonde matrix, for which the determinant can be explicitly computed. More precisely, we have
\[
\det \Lambda'(\sigma) = \frac{(-1)^n}{n!} \left(\prod_{i=1}^{n-1} R_i\right) \prod_{0\le i<j\le n-1} (R_j-R_i)=(-1)^{n+\frac{n(n-1)}{2}} \frac{1}{n!} \left(\prod_{i=1}^{n-1} R_i\right) \prod_{0\le i<j\le n-1} (R_i-R_j).
\]
This concludes the proof of the result concerning the sign of $\det \Lambda'(\sigma)$, since $R_i>R_j$ for $i<j$. 

Concerning the sign of $\det \Lambda'_{[n-1]}(\sigma)$, we stress that removing the row corresponding to the outermost annulus corresponds to removing the column $A_0-A_1$ in the computation above. As a result, the same argument applies.
\end{proof}


Unfortunately, we have been unable to prove this rigorously  in the general case. This may require studying  the dependence of the integrals of $|\nabla u_j|^2$ on $j$ and on the radii of the subdomains quantitatively, see \cite{garofalo-lin-1986,dicristo-rondi-2021}. As stated in \Cref{subsec_numerical_study_ip}, we always observe numerically that \eqref{eq:sign_det} holds, regardless of the value of $n$ and of $\sigma$. In \Cref{table_jac_det}, we show the minimum value of $(-1)^{n(n+1)/2}\det \Lambda'(\sigma)$, $(-1)^{n(n-1)/2}\det \Lambda_{[n-1]}'(\sigma)$, $\sigma_{\mathrm{min}}(\Lambda'(\sigma))$ (the smallest singular value of $\Lambda'(\sigma)$) and $\sigma_{\mathrm{min}}(\Lambda_{[n-1]}'(\sigma))$ over $I_{k}^n$, where $I_k=\{a+(i/(k-1))(b-a):0\leq i\leq k-1\}$ with $k=5$ and $(a,b)=(0.5, 1.5)$. The minimum of $(-1)^{n(n+1)/2}\det \Lambda'(\sigma)$ seems to be reached at $b\mathbf{1}$, so that increasing $b$ would result in an even smaller value for the minimum.
