To validate the switching from $\gamma_2$ to $\gamma_1$, it suffices to consider the portion of the geodesic from time $s$ to time $t''$, where $t''>t'$, since portions of finite geodesics are also finite geodesics. Let $y''=g_{(x,s)}(t''-s)$. Also, let $\gamma_0$ be the portion of $g_{(x,s)}(\cdot)$ that connects $(x,s)$ and $(y,t)$ and let $\gamma_3$ be the portion of $g_{(x,s)}(\cdot)$ that connects $(y',t')$ and $(y'',t'')$. Because $\gamma_1$ and $\gamma_2$ are restrictions of infinite upward geodesics, we have $||\gamma_1||_\mathcal{L}=||\gamma_2||_\mathcal{L} = \L(y,t;y',t')$. Then, by Proposition \ref{Proposition: concatenation}, 
\begin{align*}
||\gamma_0\oplus \gamma_1\oplus\gamma_3||_\mathcal{L} = ||\gamma_0||_\mathcal{L}+||\gamma_1||_\mathcal{L}+||\gamma_3||_\mathcal{L} = ||\gamma_0||_\mathcal{L}+||\gamma_2||_\mathcal{L}+||\gamma_3||_\mathcal{L} = ||\gamma_0\oplus\gamma_2\oplus\gamma_3||_\mathcal{L}.
\end{align*}
Because $\gamma_0\oplus\gamma_2\oplus\gamma_3$ is the restriction of an infinite upward geodesic, the quantity above is equal to $\L(x,s;y'',t'')$, which shows that $\gamma_0\oplus \gamma_1\oplus\gamma_3$ is a finite geodesic.
\end{proof}

Recall that $\widetilde{\V}_a$ defined in \eqref{Introduction: def T_a, fixed time} consists of the individuals whose set of descendants at time zero has Lebesgue measure greater than $a$.  The following result is an immediate consequence of Lemma \ref{Lemma: semigroup}.

\begin{corollary}\label{Corollary: Vtildenew}
If $(y',t')$ is an ancestor of $(y,t)$, i.e. $g_{(y,t)}(t'-t)=y'$, then $\widetilde{D}_{(y',t')}\supseteq \widetilde{D}_{(y,t)}$. In particular, if $(y,t)\in \widetilde{\V}_{a}$, then $(y',t')\in \widetilde{\V}_{a}$.
\end{corollary}

We now establish a scaling property for $\widetilde{\V}_a$.  Define the scaling map $S_{\rho}: \R^2 \rightarrow \R^2$ by 
\begin{equation}\label{scaling map}
S_\rho(x,s)=(\rho^{-2}x,\rho^{-3}s)\qquad\text{ for all } (x,s)\in\R^2.
\end{equation}
For any $A\subseteq\R^2$, we write $S_{\rho}(A)$ for the image of $A$ under $S_{\rho}$.

\begin{proposition}\label{Proposition: properties of T_a, fixed time}
We have $S_\rho(\widetilde{\V}_{a})\stackrel{d}{=}\widetilde{\V}_{\rho^{-2}a}$.  Also, $\P(\widetilde{\V}_{a}=\emptyset)=0$ for all $a>0$.
\end{proposition}

\begin{proof}
Define $\L_{\rho}$ on $\R^4_{\uparrow}$ by
$$
\L_{\rho}(x,s;y,t)=\rho \L(\rho^{-2}x, \rho^{-3}s; \rho^{-2}y, \rho^{-3}t)=\rho\L(S_{\rho}(x,s);S_{\rho}(y,t)).
$$
Note that $\L$ and $\L_\rho$ are equal in distribution by the scaling property of the directed landscape (part 3 of Proposition \ref{Proposition: properties of the landscape}). Quantities defined with respect to $\L_{\rho}$ will be subscripted by $\rho$. For example, $g_{(x,s),\rho}$ denotes the geodesic starting from $(x,s)$ in $\L_{\rho}$, and $\widetilde{D}_{(y,t),\rho}$ denotes the descendants of $(y,t)$ in $\L_{\rho}$. Note that we have the following equality by definition:
$$
S_{\rho}(g_{(x,s)})=g_{S_{\rho}(x,s),\rho}.
$$
That is, if $g_{(x,s)}$ is an infinite upward geodesic in $\L$, then its image under $S_{\rho}$ is the infinite upward geodesic $g_{S_{\rho}(x,s),\rho}$ in $\L_{\rho}$. It follows that 
$$
S_{\rho}(\widetilde{D}_{(y,t)}) = \widetilde{D}_{S_{\rho}(y,t),\rho}.
$$
Note that $\widetilde{m}(\widetilde{D}_{(y,t)})\ge a$ if and only if $\widetilde{m}(\widetilde{D}_{S_{\rho}(y,t),\rho})=\widetilde{m}(S_{\rho}(\widetilde{D}_{(y,t)}))\ge \rho^{-2} a$. Therefore,
\begin{align*}
\widetilde{\V}_{a} = \{(y,t)\in\R^2: \widetilde{m}(\widetilde{D}_{(y,t)})\ge a\}=\{(y,t)\in\R^2 :\widetilde{m}(\widetilde{D}_{S_{\rho}(y,t),\rho})\ge \rho^{-2}a\}.
\end{align*}
Therefore, 
\begin{align*}
S_{\rho}(\widetilde{\V}_a)=\{S_{\rho}(y,t): \widetilde{m}(\widetilde{D}_{S_{\rho}(y,t),\rho})\ge \rho^{-2} a\}=\{(y,t): \widetilde{m}(\widetilde{D}_{(y,t),\rho})\ge \rho^{-2} a\}=\widetilde{\V}_{\rho^{-2}a,\rho}.
\end{align*}
Because $\L$ and $\L_\rho$ are equal in distribution, it follows that $S_{\rho}(\V_{a})\stackrel{d}{=}\V_{\rho^{-2}a}$.

To prove the second claim, consider the geodesics $g_{(0,0)}$ and $g_{(1,0)}$. By Proposition \ref{Proposition: geodesic coalesecent}, with probability 1, these geodesics coalesce at some $(y,t)\in\R^2$ and there exists a random $\eps>0$ such that $(y,t)\in\widetilde{\V}_{\eps}$. Therefore $\P(\cup_{a>0} \widetilde{\V}_{a} =\emptyset)=\lim_{a\rightarrow0}\P(\widetilde{\V}_{a}=\emptyset)=0$. By the first claim, the probability $\P(\widetilde{\V}_{a}=\emptyset)$ does not depend on $a$, and we have $\P(\widetilde{\V}_{a}=\emptyset)=0$ for all $a>0$. 
\end{proof}

The next lemma bounds the expected number of points in $(0,1]\times\{t\}$ whose set of descendants at time zero has Lebesgue measure greater than 2 but less than 4. Because the integral of this bound over $t$ converges, we will be able to use this bound to show that the constant $C_1'$ in Proposition \ref{Proposition: expectation, fixed time} is finite. The primary tool that we need to prove this bound is the three-arm estimate in Theorem \ref{Theorem: 3-disjoint}.
\begin{lemma}\label{Lemma: C is finite, fixed time}
For all $p\in(1,\infty)$, there exists a constant $C_p$ such that 
$$
\E\big[\#\big((\widetilde{\V}_{2}^t\setminus \widetilde{\V}_{4}^t) \cap (0,1] \big) \big]\le C_pt^{-5/(3p)}\log^{52/p}(t\vee 2).
$$
\end{lemma}

\begin{proof}
Fix $t>0$. For each integer $i$, let $E_i$ be the event that the geodesics $g_{(i-4,0)}$, $g_{(i,0)}$, and $g_{(i+4,0)}$ are disjoint for all $s\in [0, t]$.
For each $y\in\R$, let $I_y$ be the collection of integers $i$ such that the event $E_i$ occurs and $g_{(i,0)}(t)=y$. We claim that $I_y\neq\emptyset$ if $y\in\widetilde{\V}_{2}^t\setminus \widetilde{\V}_{4}^t$. Indeed, since $\widetilde{m}(\widetilde{D}_{(y,t)})\ge 2$ and $\widetilde{D}_{(y,t)}$ is an interval, there exists an integer $i$ such that $g_{(i,0)}(t)=y$. Also, the geodesics $g_{(i-4,0)}$, $g_{(i,0)}$, and $g_{(i+4,0)}$ are disjoint for all $s\in [0, t]$, because otherwise we would have $y\in\widetilde{\V}_{4}^t$.
Let $K\ge 1$ be an integer to be determined later, and let $\widetilde{A}_K=(\widetilde{\V}_{2}^t\setminus \widetilde{\V}_{4}^t)\cap (-K,K]$. It then follows from the argument above that
\begin{align*}
\#\widetilde{A}_K&\le \sum_{y\in\widetilde{A}_K}\#I_y=\sum_{y\in\widetilde{A}_K} \sum_{i\in\Z}\mathbbm{1}_{E_i}\mathbbm{1}_{\{g_{(i,0)}(t)=y\}}\\
&=\sum_{i\in\Z}\sum_{y\in\widetilde{A}_K}\mathbbm{1}_{E_i}\mathbbm{1}_{\{g_{(i,0)}(t)=y\}}=\sum_{i\in\Z}\mathbbm{1}_{E_i}\mathbbm{1}_{\{g_{(i,0)}(t)\in \widetilde{A}_K\}}\le\sum_{i\in\Z}\mathbbm{1}_{E_i}\mathbbm{1}_{\{-K<g_{(i,0)}(t)\le K\}}.
\end{align*} 
Taking expectations, we have
$$
\E[\#\widetilde{A}_K]\le \sum_{i\in \Z} \E[\mathbbm{1}_{E_i} \mathbbm{1}_{\{-K< g_{(i,0)}(t)\le K\}}].
$$
By H\"older's inequality, for any $p,q\in(1,\infty)$ with $1/p+1/q=1$, we have
$$
\E[\#\widetilde{A}_K]\le \sum_{i\in \Z} \P(E_i)^{1/p}\P(-K< g_{(i,0)}(t)\le K)^{1/q}.
$$
By Theorem \ref{Theorem: 3-disjoint}, there exists a constant $C\in(0,\infty)$ such that 
$$
\P(E_i)\le Ct^{-5/3}\log ^{52}(t\vee 2).
$$
Therefore,
\begin{equation}\label{Sampling from a fixed time: C is finite}
\E[\#\widetilde{A}_K]\le C_pt^{-5/(3p)}\log^{52/p}(t\vee 2)\sum_{i\in \Z}\P(-K<g_{(i,0)}(t)\le K)^{1/q}.
\end{equation}  
We bound $\P(-K< g_{(i,0)}(t)\le K)$ by 1 if $|i|< 2K$, and use Theorem \ref{Theorem: transversal fluctuation} if $|i|\ge 2K$ to get
\begin{align*}
&\sum_{i\in\Z}\P(-K< g_{(i,0)}(t)\le K)^{1/q}\\
&\qquad=\sum_{|i|< 2K}\P(-K< g_{(i,0)}(t)\le K)^{1/q}+\sum_{|i|\ge 2K}\P(-K< g_{(i,0)}(t)\le K)^{1/q}\\
&\qquad\le (4K-1)+2\sum_{i\ge2K}\P(|g_{(i,0)}(0)-g_{(i,0)}(t)|\ge i-K)^{1/q}\\
&\qquad=(4K-1)+2\sum_{i\ge K}\P(|g_{(i+K,0)}(0)-g_{(i+K,0)}(t)|\ge i)^{1/q}\\
&\qquad\le (4K-1)+2C_3 \sum_{i\ge K} e^{-C_4 i^3 /(t^2 q)}.
\end{align*}
We now take $K=\lceil t^{2/3}\rceil $. For $i\ge K$, we have $e^{-C_4 i^3 /(t^2 q)}\le e^{-C_4 i /(t^{2/3}q)}$ and hence
\begin{align*}
\sum_{i\in\Z}\P(-K< g_{(i,0)}(t)\le K)^{1/q}\le (4K-1)+2C_3 \sum_{i\ge K} e^{-C_4 i /(t^{2/3}q)}\le(4K-1)+\frac{2C_3}{1-e^{-C_4 /(t^{2/3}q)}}.
\end{align*}
The last expression is bounded above by $C_p t^{2/3}$ for some constant $C_p$ as $t\rightarrow\infty$, and is bounded by a constant $C$ as $t\rightarrow0$. Therefore, there exists a constant $C_p$ such that
$$
\sum_{i\in\Z}\P(-K< g_{(i,0)}(t)\le K)^{1/q}\le C_p\max\{1,t^{2/3}\}.
$$
Plugging this in \eqref{Sampling from a fixed time: C is finite}, we get
$$
\E[\#\widetilde{A}_K]\le C_pt^{-5/(3p)}\log^{52/p}(t\vee 2)\max\{1,t^{2/3}\}.
$$
Recall that $\widetilde{A}_K=(\widetilde{\V}_{2}^t\setminus \widetilde{\V}_{4}^t)\cap (-K,K]$ and that $K=\lceil t^{2/3} \rceil\ge \max\{1,t^{2/3}\}$. It follows, using the translation invariance property of the directed landscape, that
$$
\E\big[\#\big((\widetilde{\V}_{2}^t\setminus \widetilde{\V}_{4}^t) \cap (0,1] \big) \big]=\frac{1}{2K}\E[\#\widetilde{A}_K]\le C_pt^{-5/(3p)}\log^{52/p}(t\vee 2),
$$
which completes the proof.
\end{proof}

We now complete the proof of Proposition \ref{Proposition: expectation, fixed time}. As in the proof of Proposition \ref{Proposition: expectation}, we will use the scaling invariance property of the directed landscape. 
\begin{proof}[Proof of Proposition \ref{Proposition: expectation, fixed time}]
Let $A=\widetilde{A}\times\R_+$  be defined as in the statement of the proposition. For any $a>0$, we define a measure $\widetilde{\nu}_a$ on $\R$ by 
$$
\widetilde{\nu}_a(\widetilde{A})=\E\Big[l\big((\widetilde{\V}_0\setminus\widetilde{\V}_a)\cap A\big)\Big].
$$
The countable additivity follows from the linearity of expectation and the monotone convergence theorem. The measure $\widetilde{\nu}_a$ is translation invariant by part 2 of Proposition \ref{Proposition: properties of the landscape}. Therefore, there exists some constant $\eta(a)\in[0,\infty]$ such that $\widetilde{\nu}_a(A)=\eta(a)\widetilde{m}(\widetilde{A})$.

Recalling the definition of $\widetilde{S}_\rho$ from \eqref{scaling map, fixed time} and applying Proposition~\ref{Proposition: properties of T_a, fixed time} with $\rho = \sqrt{a}$, we have
\begin{align*}
\#(\widetilde{\V}^t_{a}\cap \widetilde{A})
=\#\Big(\widetilde{S}_{\sqrt{a}}(\widetilde{\V}_{a}^t\cap \widetilde{A})\Big) =\#\Big(\widetilde{S}_{\sqrt{a}}(\widetilde{\V}^t_{a})\cap \widetilde{S}_{\sqrt{a}}(\widetilde{A})\Big)
\stackrel{d}{=}\#\Big(\widetilde{\V}_{1}^{a^{-3/2}t}\cap \widetilde{S}_{\sqrt{a}}(\widetilde{A})\Big).
\end{align*}
Taking expectations, integrating over $t\ge 0$, and using the change of variable $s=a^{-3/2}t$, we have
\begin{align}\label{eta}
\E\left[l\big((\widetilde{\V}_{0} \setminus \widetilde{\V}_{a})\cap A\big)\right]&=
\int_0^\infty
\E\Big[\#\big((\widetilde{\V}_{0}^t\setminus \widetilde{\V}_{a}^t) \cap \widetilde{A}\big)\Big]\ dt\nonumber\\
&=\int_0^\infty \E\Big[\#\big((\widetilde{\V}_{0}^{a^{-3/2}t}\setminus \widetilde{\V}_{1}^{a^{-3/2}t}) \cap \widetilde{S}_{\sqrt{a}}(\widetilde{A})\big) \Big] \: dt\nonumber\\
&=\int_0^\infty \E\big[\#\Big((\widetilde{\V}_{0}^{s}\setminus \widetilde{\V}_{1}^{s})\cap \widetilde{S}_{\sqrt{a}}(\widetilde{A})\big)\Big]\ a^{3/2} \: ds\nonumber\\
&=\eta(1)\widetilde{m}(\widetilde{S}_{\sqrt{a}}(\widetilde{A}))a^{3/2}\nonumber\\
&=\eta(1) \widetilde{m}(\widetilde{A})a^{1/2}. 
\end{align}
Therefore, we have $\eta(a)=\eta(1)a^{1/2}$ and we can take $C_1'=\eta(1)$. To prove \eqref{cdf2}, it remains to show that $C_1'=\eta(1)\in(0,\infty)$.

We first rule out the possibility that $\eta(1)=0$. Proceeding by contradiction, suppose that $\eta(1)=0$. Then $\eta(a)=\eta(1)a^{1/2}=0$ for all $a>0$. Taking $A=\R^2$ and taking the limit as $a\rightarrow\infty$, we get $\E[l(\widetilde{\V}_0)]=0$. By Corollary \ref{Corollary: Vtildenew}, $\widetilde{\V}_a^s\neq\emptyset$ implies that $\widetilde{\V}_a^t\neq\emptyset$ for all $t\ge s$. Therefore, the fact that $\E[l(\widetilde{\V}_a)]=0$ implies that $\P(\widetilde{\V}_{a}=\emptyset)=1$, which contradicts the second claim in Proposition \ref{Proposition: properties of T_a, fixed time}.

We next rule out the possibility that $\eta(1)=\infty$. Let $A=(0,1]\times\R_+$. By Lemma \ref{Lemma: C is finite, fixed time}, we have
$$
\E\left[l\big((\widetilde{\V}_{2} \setminus \widetilde{\V}_{4})\cap A\big)\right]=
\int_0^\infty
\E\Big[\#\big((\widetilde{\V}_{2}^t\setminus \widetilde{\V}_{4}^t) \cap \widetilde{A}\big)\Big]\ dt=C_5<\infty.
$$
For any $a>0$, the same scaling argument given in \eqref{eta} gives 
$$
\E\left[l\big((\widetilde{\V}_{2a} \setminus \widetilde{\V}_{4a})\cap A\big)\right]=\E\left[l\big((\widetilde{\V}_{2} \setminus \widetilde{\V}_{4})\cap A\big)\right]a^{1/2}=C_5 a^{1/2}.
$$
Therefore,
$$
\eta(1)=\E\left[l\big((\widetilde{\V}_{0} \setminus \widetilde{\V}_{1})\cap A\big)\right]=\sum_{i=-\infty}^0\E\left[l\big((\widetilde{\V}_{2^{i-1}} \setminus \widetilde{\V}_{2^{i}})\cap A\big)\right]=\sum_{i=-\infty}^0 C_5 2^{(i-2)/2}<\infty.
$$

It remains to prove \eqref{sfs2}. It suffices to consider the case when $\widetilde{m}(\widetilde{A})<\infty$. Note that if $\widetilde{m}(\widetilde{D}_{(y,t)})=a$, then $(y,t)\in Anc_k(\widetilde{\Pi}_\lambda)$ with probability $e^{-\lambda a}(\lambda a)^k/k!$. Using \eqref{cdf2}, if we let 
\begin{equation}\label{Sampling from a fixed time, density}
\phi(a)=\frac{d}{da}\E\Big[l\big((\widetilde{\V}_0\setminus\widetilde{\V}_a)\cap ([0,1]\times\R)\big)\Big] = \frac{C_1' a^{-1/2}}{2} 
\end{equation}
be the ``density" for the length of the branches whose descendants at time zero have Lebesgue measure $a$, then one would expect to integrate over $a$ to get 
\begin{equation}\label{Sampling from a fixed time: integration over a}
\E\Big[l\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\Big]=\int_0^\infty \frac{e^{-\lambda a}(\lambda a)^k}{k!}\cdot \frac{C_1'a^{-1/2}}{2}\cdot\widetilde{m}(\widetilde{A}) \ da.
\end{equation}
We establish \eqref{Sampling from a fixed time: integration over a} using a discrete approximation. We have
$$
\E\big[l\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\Big] = \E\left[\int_0^\infty \#\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)^t\ dt\right]=\int_0^\infty \E\Big[\#\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)^t\Big]\ dt.
$$
For each $n\ge 1$, we have
\begin{align*}
\E\Big[\#\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)^t\Big] &=\sum_{i=-\infty}^\infty \E\big[\#\big(Anc_k(\widetilde{\Pi}_\lambda)\cap (\widetilde{\V}_{2^{i/n}}\setminus\widetilde{\V}_{2^{(i+1)/n}})\cap A\big)^t \Big]\\
&\le \sum_{i=-\infty}^\infty \left(\sup_{x\in (2^{i/n}, 2^{(i+1)/n}]} \frac{e^{-\lambda x}(\lambda x)^k}{k!}\cdot\E\Big[\#\big( (\widetilde{\V}_{2^{i/n}}\setminus\widetilde{\V}_{2^{(i+1)/n}})\cap A\big)^t \Big]\right).
\end{align*}
For $a\in(2^{i/n}, 2^{(i+1)/n}]$, we define
$$
f_{n,t}(a) = \sup_{x\in (2^{i/n}, 2^{(i+1)/n}]} \frac{e^{-\lambda x}(\lambda x)^k}{k!} \cdot\frac{\E[\#( (\widetilde{\V}_{2^{i/n}}\setminus\widetilde{\V}_{2^{(i+1)/n}})\cap A)^t ]}{2^{(i+1)/n}-2^{i/n}},
$$
and 
\begin{align*}
f_{n}(a) = \int_0^{\infty} f_{n,t}(a)\ dt= \sup_{x\in (2^{i/n}, 2^{(i+1)/n}]} \frac{e^{-\lambda x}(\lambda x)^k}{k!} \cdot\frac{\E[l( (\widetilde{\V}_{2^{i/n}}\setminus\widetilde{\V}_{2^{(i+1)/n}})\cap A) ]}{2^{(i+1)/n}-2^{i/n}}.
\end{align*}
Then
$$
\E\Big[\#\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)^t\Big] \le\int_0^\infty f_{n,t}(a)\ da,\qquad\E\Big[l\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\big] \le\int_0^\infty f_{n}(a)\ da.
$$
We now claim that we can apply the dominated convergence theorem to conclude that
\begin{equation}\label{Sampling from a fixed time, discretization}
\E\Big[\#\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\Big] \le\lim_{n\rightarrow\infty}\int_0^\infty f_n(a)\ da=\int_0^\infty \lim_{n\rightarrow\infty}f_n(a)\ da.
\end{equation}
For the pointwise limit, using \eqref{cdf2} again, we get
\begin{equation}\label{Sampling from a fixed time, pointwise limit}
\lim_{n\rightarrow\infty} f_n(a) = \frac{e^{-\lambda a}(\lambda a)^k}{k!}\widetilde{m}(\widetilde{A})\phi(a).
\end{equation}
To see that $\{f_n\}_{n\ge 2}$ is dominated, note that $\phi(\cdot)$ is decreasing. Suppose $a\in(2^{i/n}, 2^{(i+1)/n}]$. Then
\begin{align*}
f_n(a)&=\sup_{x\in (2^{i/n}, 2^{(i+1)/n}]} \frac{e^{-\lambda x}(\lambda x)^k}{k!} \cdot\frac{\E[l( (\widetilde{\V}_{2^{i/n}}\setminus\widetilde{\V}_{2^{(i+1)/n}})\cap A) ]}{2^{(i+1)/n}-2^{i/n}}\\
&\le\frac{e^{-\lambda 2^{i/n}} (\lambda 2^{(i+1)/n})^k}{k!} \cdot \widetilde{m}(\widetilde{{A}})\phi(2^{i/n})\\
&\le \frac{e^{-\lambda 2^{i/n}} (2^{(i+1)/n})^k \phi(2^{i/n})}{e^{-\lambda 2^{(i+1)/n}} (2^{i/n})^k \phi(2^{(i+1)/n})} \frac{e^{-\lambda a} (\lambda a)^k}{k!}\cdot \widetilde{m}(\widetilde{A}) \phi(a)\\
&\le e^{(\sqrt{2}-1)\lambda a} 2^{k+1/2} \frac{e^{-\lambda a} (\lambda a)^k}{k!}\cdot \frac{C_1'a^{-1/2}}{2}\cdot\widetilde{m}(\widetilde{A}),
\end{align*}
which is integrable. This concludes the proof of \eqref{Sampling from a fixed time, discretization}. Then by \eqref{Sampling from a fixed time, density} and \eqref{Sampling from a fixed time, pointwise limit}, we have
$$
\E\Big[l\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\Big]\le \int_0^\infty \frac{e^{-\lambda a}(\lambda a)^k}{k!}\cdot \frac{C_1'a^{-1/2}}{2}\cdot\widetilde{m}(\widetilde{A})\ da.
$$
If we replace the supremum by the infimum in the definitions of  $f_{n,t}$ and $f_n$, then a similar argument yields
$$
\E\Big[l\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\Big]\ge \int_0^\infty \frac{e^{-\lambda a}(\lambda a)^k}{k!}\cdot \frac{C_1'a^{-1/2}}{2}\cdot\widetilde{m}(\widetilde{A}) \ da.
$$
Therefore,
\begin{align*}
\E\Big[l\big(Anc_k(\widetilde{\Pi}_\lambda)\cap A\big)\Big]&=\int_0^\infty \frac{e^{-\lambda a}(\lambda a)^k}{k!}\cdot \frac{C_1'a^{-1/2}}{2}\cdot\widetilde{m}(\widetilde{A}) \ da\\
&= \frac{C_1'\lambda^k\widetilde{m}(\widetilde{A})}{2k!}\int_0^\infty e^{-\lambda a} a^{k-1/2}\ da\\
&=\frac{C_1' \lambda^{-1/2}}{2}\cdot\widetilde{m}(\widetilde{A}) \cdot\frac{\Gamma(k + 1/2)}{k!},
\end{align*}
which completes the proof of \eqref{sfs2}.
\end{proof}

\subsection{Proof of Proposition \ref{Proposition: lln, fixed time, points anywhere}}\label{sub3.2}

We now establish a strong law of large numbers as stated in Proposition \ref{Proposition: lln, fixed time, points anywhere}. The spatial stationarity of $\L$ and $\widetilde{\Pi}_{\lambda}$ implies the convergence to a possibly random limit. We use a coupling argument based on Proposition \ref{Proposition: coupling} and a variance computation to deduce that the limit is deterministic.

We start with a general fact about identically distributed non-negative random variables.

\begin{lemma}\label{Lemma: probability fact}
Let $\{X_i\}_{i\in I}$ be a collection of identically distributed nonnegative random variables with finite mean. Let $\{I_n\}_{n=1}^\infty$ be a sequence of finite subsets of $I$ and $S_n=\sum_{i\in I_n} X_i$. Suppose that 
$S_n/\#I_n$ converges a.s. and in $L^1$ and that $\liminf_{n\rightarrow\infty} S_n/\#I_n\ge \E[X_1]$ a.s. Then, as $n\rightarrow\infty$, we have $S_n/\#I_n\rightarrow \E[X_1]$ a.s. and in $L^1$.
\end{lemma}

\begin{proof}
By Fatou's lemma, we have 
$$
\E\left[\liminf_{n\rightarrow\infty} S_n/\# I_n\right]\le \liminf_{n\rightarrow\infty}\E[S_n/\# I_n]=\E[X_1].
$$
Combining this with the assumption that $\liminf_{n\rightarrow\infty} S_n/\#I_n\ge \E[X_1]$ a.s., we have 
$$
\liminf_{n\rightarrow\infty} S_n/\#I_n=\E[X_1]\qquad\text{a.s.}.
$$ 
The claim then follows from the assumption that $S_n/\#I_n$ converges a.s. and in $L^1$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{Proposition: lln, fixed time, points anywhere}]
Fix $T>0$. By part 2 of Proposition \ref{Proposition: properties of the landscape}, the random variables 
$$
\Big(l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times[0,T])\big)\Big)_{i\in \Z}
$$ 
are stationary in $i$. Also, equation \eqref{sfs2} implies that
$$
\E\Big[l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times[0,T])\big)\Big]<\infty.
$$ 
It then follows from Birkhoff's ergodic theorem that 
\begin{equation}\label{Sampling from a fixed time, law of large numbers, ergodic}
\lim_{N\rightarrow\infty}\frac{1}{N}\sum_{i=1}^N l\left(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times[0,T])\right)\text{ exists a.s. and in } L^1. 
\end{equation}
We claim that there is there exists a subsequence $(N_m)_{m\ge 1}$ and some constant $c$ such that
\begin{equation}\label{Sampling from a fixed time, law of large numbers, subsequence converges to constant}
\frac{1}{N_m}\sum_{i=1}^{N_m} l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times[0,T])\big)\rightarrow c,\qquad\text{in probability}.
\end{equation}
Suppose for now that \eqref{Sampling from a fixed time, law of large numbers, subsequence converges to constant} holds. Then the limit in \eqref{Sampling from a fixed time, law of large numbers, ergodic} is deterministic, and using the $L^1$ convergence of \eqref{Sampling from a fixed time, law of large numbers, ergodic}, we can conclude that
\begin{equation}\label{Sampling from a fixed time, slln}
\lim_{N\rightarrow\infty}\frac{1}{N}\sum_{i=1}^N l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times[0,T])\big)= \E\big[l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([0, 1)\times[0,T])\big)\big],\ \text{ a.s. and in } L^1.  
\end{equation}
We then apply Lemma \ref{Lemma: probability fact} with $X_i=l(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times\R_+))$ and $I_n=\{1,2,\dots, n\}$. Note that $\E[X_1]<\infty$ by \eqref{sfs2}. For each $T>0$, let $X_{i,T}=l(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap([i-1, i)\times[0,T]))$ and $S_{n,T}=\sum_{i=1}^n X_{i,T}$. Using \eqref{Sampling from a fixed time, slln}, we have
$$
\liminf_{n\rightarrow\infty}\frac{S_n}{n}\ge \sup_{T>0}\left(\lim_{n\rightarrow\infty} \frac{S_{n,T}}{n}\right)=\sup_{T>0}\E[X_{1,T}]=\E[X_1].
$$
Also, by Birkhoff's ergodic theorem, $S_{n}/n$ converges a.s. and in $L^1$. It then follows from Lemma ~\ref{Lemma: probability fact} that $S_{n}/n$ converges to $\E[X_1]$ a.s and in $L^1$. Proposition \ref{Proposition: lln, fixed time, points anywhere} then follows from \eqref{sfs2}.

It remains to show \eqref{Sampling from a fixed time, law of large numbers, subsequence converges to constant}. To prove \eqref{Sampling from a fixed time, law of large numbers, subsequence converges to constant}, we will make use of the approximate independence of the directed landscape restricted to disjoint boxes. For any $\eps>0$, let $K_{i,\eps} =[i-1/4,i+1/4]\times[0,\eps]$ be defined as in Proposition \ref{Proposition: coupling}. Also, for any $n\in \N$, let $\L_0,\L_1,\dots,\L_n$ be coupled as described in Proposition \ref{Proposition: coupling}. We can choose $\eps_n>0$ which goes to 0 as $n\rightarrow\infty$ such that
$$
\lim_{n\rightarrow\infty}\P(\L_0|_{K_{i,\eps_n}} =\L_i|_{K_{i,\eps_n}}\text{ for all }i=1,\dots, n)=1.
$$
Recall the scaling map $S_{\rho}$ from \eqref{scaling map}. Let $\rho_n=(\eps_n/T)^{1/3}$, $a_{n,i}=\rho_n^{-2}(i-1/4)$ and $b_{n,i}=\rho_n^{-2}(i+1/4)$ so that the box $B_{n,i}:=S_{\rho_n}(K_{i,\eps_n})=[a_{n,i}, b_{n,i}]\times [0,T]$ has height $T$. By choosing a smaller $\eps_n$ if necessary, we may assume that $\rho_n^{-1}$ is an integer. By the KPZ scaling property in Proposition \ref{Proposition: properties of the landscape}, we may choose $\L_{n,1},\dots, \L_{n,n}$ to be independent, and coupled with $\L$ such that
$$
\lim_{n\rightarrow\infty}\P(\L|_{B_{n,i}} =\L_{n,i}|_{B_{n,i}}\text{ for all }i=1,\dots, n)=1.
$$
Let $W$ be the two sided Brownian motion given by Theorem \ref{Theorem: Brownian motion}. For each box $B_{n,i}$ and each $x\in[a_{n,i},b_{n,i}]$, we define
$$
g^{B_{n,i}}_{(x,0)}(T)=\argmax_{y\in[a_{n,i},b_{n,i}]} \{\L_{n,i}(x,0; y,T)+W(y)-W(x)\},
$$
and for $0< t< T$, we define
$$
g^{B_{n,i}}_{(x,0)}(t)=\argmax_{y\in[a_{n,i},b_{n,i}]} \{\L_{n,i}(x,0; y,t)+\L_{n,i}(y,t; g^{B_{n,i}}_{(x,0)}(T),T)\},
$$
where the argmax is chosen to be the left-most one if it is not unique. We think of $g_{(x,0)}^{B_{n,i}}(\cdot)$ as geodesic starting from $(x,0)$ associated with the box $B_{n,i}$.

Since $W$ is independent of $\{\L_{n,i}\}_{i=1}^{n}$ and has independent increments, the geodesics associated with $B_{n,i}$ and $B_{n,j}$ are independent if $i$ and $j$ are distinct. For each $(y,t)\in B_{n,i}$, each integer $k\ge 1$, and each $a>0$, we also define the analogs of $\widetilde{D}_{(y,t)}$, $Anc_{k}(\widetilde{\Pi}_{\lambda})$, and $\widetilde{\V}_{a}$ as
\begin{align*}
\widetilde{D}_{(y,t)}^{B_{n,i}} &:= \{x\in[a_{n,i},b_{n,i}]: g_{(x,0)}^{B_{n,i}}(t)=y\},\\
Anc_{k}(\widetilde{\Pi}_{\lambda})^{B_{n,i}}&:= \{(y,t)\in {B_{n,i}}: \#(\widetilde{D}_{(y,t)}^{B_{n,i}}\cap \widetilde{\Pi}_\lambda)= k\},\\
\widetilde{\V}_{a}^{B_{n,i}} &:= \{(y,t)\in B_{n,i}: \widetilde{m}(\widetilde{D}_{(y,t)}^{B_{n,i}})> a\}.
\end{align*}

Let $B'_{n,i}:=[(2a_{n,i}+b_{n,i})/3,(a_{n,i}+2b_{n,i})/3)\times[0,T]$ be a box contained in $B_{n,i}$. Let $E_{n,i}$ be the event that the following holds; see Figure \ref{Figure} for an illustration. 
\begin{enumerate}
\item $\L|_{B_{n,i}} =\L_{n,i}|_{B_{n,i}},$
\item $\sup_{t\in[0,T]} |g_{((5a_{n,i}+b_{n,i})/6,0)}(t)-(5a_{n,i}+b_{n,i})/6|< (b_{n,i}-a_{n,i})/6,$
\item $\sup_{t\in[0,T]}|g_{((a_{n,i}+5b_{n,i})/6,0)}(t)-(a_{n,i}+5b_{n,i})/6|< (b_{n,i}-a_{n,i})/6.$
\end{enumerate}
Finally, we write $E_n:=\cap_{i=1}^n E_{n,i}$. Recall that $\P(\L|_{B_{n,i}} =\L_{n,i}|_{B_{n,i}}\text{ for all }i=1,\dots, n)\rightarrow1$ as $n\rightarrow\infty$. Also, by Theorem \ref{Theorem: transversal fluctuation}, we have
\begin{align*}
&\P\left(\sup_{t\in[0,T]}\left|g_{((a_{n,i}+5b_{n,i})/6,0)}(t)-\frac{a_{n,i}+5b_{n,i}}{6}\right|< \frac{b_{n,i}-a_{n,i}}{6}\right)\ge 1-C_3e^{-C_4/(12^3\eps_n^2)},
\end{align*}
and the same bound holds for $g_{((5a_{n,i}+b_{n,i})/6,0)}$. Therefore, $\P(E_n)\rightarrow1$ because $\eps_n\rightarrow0$.

