The ordering of the geodesics in Proposition \ref{Proposition: ordering of geodesics} implies that, on the  event $E_{n,i}$, for any $(y,t)\in B'_{n,i}$, we have $\widetilde{D}_{(y,t)}\subseteq[(5a_{n,i}+b_{n,i})/6, (a_{n,i}+5b_{n,i})/6]$. Also, for any $x\in[(5a_{n,i}+b_{n,i})/6,(a_{n,i}+5b_{n,i})/6]$, the geodesic $g_{(x,0)}$ lies in the box $B_{n,i}$ for $t\in[0,T]$. Therefore, using Theorem \ref{Theorem: Brownian motion}, on $E_{n,i}$, for all $x\in[(5a_{n,i}+b_{n,i})/6,(a_{n,i}+5b_{n,i})/6]$, we have
\begin{align*}
g_{(x,0)}(T)&=\argmax_{y\in\R} \{\L(x,0; y,T)+W(y)-W(x)\}\\
 &=\argmax_{y\in[a_{n,i}, b_{n,i}]} \{\L(x,0; y,T)+W(y)-W(x)\}\\
 &=\argmax_{y\in[a_{n,i}, b_{n,i}]} \{\L_{n,i}(x,0; y,T)+W(y)-W(x)\}=g_{(x,0)}^{B_{n,i}}(T),
\end{align*}
and $g_{(x,0)}(t)=g_{(x,0)}^{B_{n,i}}(t)$ for all $0\le t\le T$. It follows that
\begin{equation}\label{Sampling from a fixed time, law of large numbers, coupling difference}
\lim_{n\rightarrow\infty}\P\left(\sum_{i=1}^n l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})\cap B'_{n,i}\big)\neq\sum_{i=1}^n l\big(Anc_{k}(\widetilde{\Pi}_{\lambda})^{B_{n,i}}\cap B'_{n,i}\big)\right)=0.  
\end{equation}

For $n\ge 1$ and $1\le i\le n$, let $X_{n,i}=l(Anc_{k}(\widetilde{\Pi}_{\lambda})^{B_{n,i}}\cap{B'_{n,i}})/(b_{n,i}-a_{n,i})$. Then for each fixed $n$, the random variables $\{X_{n,i}\}_{i=1}^n$ are independent. We now show that
\begin{equation}\label{Sampling from a fixed time, law of large numbers, SLLN for triangular array}
\lim_{n\rightarrow\infty}\frac{1}{n}\sum_{i=1}^n (X_{n,i}-\E[X_{n,i}])= 0\qquad\text{ in } L^2.
\end{equation}
Note that one can upper bound $l(Anc_{k}(\widetilde{\Pi}_{\lambda})^{B_{n,i}}\cap{B'_{n,i}})$ by considering the worst case where the geodesics starting from points in $\widetilde{\Pi}_{\lambda}\cap[a_{n,i}, b_{n,i}]$ immediately coalesce into groups of size $k$. We get
$$
\#\{x\in[a_{n,i}, b_{n,i}]: (x,t)\in Anc_{k}(\widetilde{\Pi}_{\lambda})^{B_{n,i}}\}\le \frac{\#(\widetilde{\Pi}_{\lambda}\cap[a_{n,i}, b_{n,i}])}{k},
$$ 
and hence
$$
X_{n,i}=\frac{l(Anc_k(\widetilde{\Pi}_{\lambda})^{B_{n,i}}\cap{B'_{n,i}})}{b_{n,i}-a_{n,i}}\le\frac{T\#(\widetilde{\Pi}_{\lambda}\cap[a_{n,i}, b_{n,i}])}{k(b_{n,i}-a_{n,i})}.
$$
Note also that $b_{n,i}-a_{n,i}=1/(2\rho_n^2)\rightarrow\infty$ as $n\rightarrow\infty$. It follows that 
$$
\E[X_{n,i}^2]\le \E\left[\left(\frac{T\#(\widetilde{\Pi}_{\lambda}\cap[a_{n,i}, b_{n,i}])}{k(b_{n,i}-a_{n,i})}\right)^2\right]=\frac{T^2}{k^2}\cdot\frac{\lambda^2(b_{n,i}-a_{n,i})^2+\lambda(b_{n,i}-a_{n,i})}{(b_{n,i}-a_{n,i})^2},
$$
which is uniformly bounded in $n$. Therefore, as $n\rightarrow\infty$
$$
\E\left[\left(\frac{1}{n}\sum_{i=1}^n (X_{n,i}-\E[X_{n,i}])\right)^2\right]\le \frac{\E[X_{n,1}^2]}{n} \rightarrow0,
$$
which completes the proof of \eqref{Sampling from a fixed time, law of large numbers, SLLN for triangular array}.
Also $\E[X_{n,i}]\le \lambda T/k$ is uniformly bounded in $n$. Therefore we may choose a subsequence $(n_m)_{m\ge 0}$ such that 
$$
\frac{1}{n_m}\sum_{i=1}^{n_m} X_{n_m,i}=\frac{1}{n_m(b_{n_m,i}-a_{n_m,i})}\sum_{i=1}^{n_m} l(Anc_k(\widetilde{\Pi}_{\lambda})^{B_{n_m,i}}\cap{B'_{n_m,i}})
$$
converges to a constant in probability. Combining this with \eqref{Sampling from a fixed time, law of large numbers, coupling difference}, we conclude that there is a subsequence $(n_m)_{m\ge 1}$ such that
$$
\frac{1}{n_m(b_{n_m,i}-a_{n_m,i})}\sum_{i=1}^{n_m} l(Anc_{k}(\widetilde{\Pi}_\lambda)\cap{B'_{n_m,i}})
$$
converges to some constant in probability. Recall that 
$$B'_{n,i}=[(2a_{n,i}+b_{n,i})/3,(a_{n,i}+2b_{n,i})/3)\times[0,T]=[\rho_n^{-2}(i-1/12),\rho_n^{-2}(i+1/12))\times[0,T].$$ 
Applying the same argument where we replace $[i-1/12, i+1/12)$ by $[i-1,i-5/6),\dots,[i-1/6,i)$ and choosing another subsequence which we still write as $(n_m)_{m\ge 1}$, we conclude that 
$$
\frac{1}{n_m\rho_{n_m}^{-2}}l(Anc_{k}(\widetilde{\Pi}_\lambda)\cap[0,n_m\rho_{n_m}^{-2}])
$$
converges to a constant in probability. Since $\rho_n^{-1}$ was chosen to be an integer, this concludes the proof of \eqref{Sampling from a fixed time, law of large numbers, subsequence converges to constant}.
\end{proof}

\subsection{Proof of Proposition \ref{Proposition: lln, fixed time, points in [0,n]}}\label{sub3.3}

In this section, we prove Proposition \ref{Proposition: lln, fixed time, points in [0,n]}, which establishes that the convergence proved in Proposition \ref{Proposition: lln, fixed time, points anywhere} still holds in probability when the sampling parameter is chosen so that exactly $n$ points are sampled from $[0,n]$.  As noted in the introduction, convergence in probability is more natural in this setting and is sufficient for the proof of Theorem \ref{Theorem: main2}.  We first prove a lemma which states that $Anc_k(\widetilde{\Pi}_{\lambda})$ does not change much if we change the sampling intensity $\lambda$ by a small amount. 

\begin{lemma}\label{Lemma: perturb the sampling intensity2}
Fix $\lambda>\eps>0$. Let $A=\widetilde{A}\times \R_+$ where $\widetilde{A}$ is a measurable subset of $\R$. Let
$$
B=\bigcup_{1\le i\le k\le j, i\neq j} \left(Anc_{i}(\widetilde{\Pi}_{\lambda-\eps})\cap Anc_{j}(\widetilde{\Pi}_{\lambda+\eps})\right)
$$
be the pairs $(y,t)\in\R^2$ that are ancestral to at most $k$ points in $\widetilde{\Pi}_{\lambda-\eps}$, at least $k$ points in $\widetilde{\Pi}_{\lambda+\eps}$, and at least one point in $\widetilde{\Pi}_{\lambda+\eps}\setminus\widetilde{\Pi}_{\lambda-\eps}$. Then there exists a constant $C_{k,\lambda}$ depending on $k$ and $\lambda$ such that if $\eps<\lambda/2$, then
$$
\E[l(A\cap B)]\le C_{k,\lambda}\widetilde{m}(\widetilde{A})\eps.
$$  
\end{lemma}

\begin{proof}
For each $i\ge 1$, let
$$
B_i = Anc_{i}(\widetilde{\Pi}_{\lambda-\eps}) \cap\{(y,t)\in\R^2: \widetilde{D}_{(y,t)}\cap (\widetilde{\Pi}_{\lambda+\eps}\setminus\widetilde{\Pi}_{\lambda-\eps})\neq\emptyset\}
$$
be the pairs $(y,t)\in\R^2$ that are ancestral to $i$ points in $\widetilde{\Pi}_{\lambda-\eps}$ and at least one point in $\widetilde{\Pi}_{\lambda+\eps}\setminus\widetilde{\Pi}_{\lambda-\eps}$.
Then, $B\subseteq \cup_{1\le i\le k} B_i$ by definition. Therefore
$$
\E[l(A\cap B)]\le \sum_{1\le i\le k}\E[l(A\cap B_i)].
$$
Let $\phi(\cdot)$ be defined as in \eqref{Sampling from a fixed time, density}. If $\widetilde{m}(\widetilde{D}_{(y,t)})=a$, then the probability that $(y,t)$ is ancestral to $i$ points in $\widetilde{\Pi}_{\lambda-\eps}$ and at least one point in $\widetilde{\Pi}_{\lambda+\eps}\setminus\widetilde{\Pi}_{\lambda-\eps}$ is
$$
\frac{e^{-(\lambda-\eps)a}(\lambda-\eps)^i a^i }{i!}(1-e^{-2\eps a}).
$$
Therefore, using that $1 - e^{-2 \eps a} \leq 2 \eps a$, 
\begin{align}\label{ElAB}
\E[l(A\cap B)]&\le\sum_{1\le i\le k}
\int_0^\infty \widetilde{m}(\widetilde{A})\phi(a) \cdot \frac{e^{-(\lambda-\eps)a}(\lambda-\eps)^i a^i }{i!}(1-e^{-2\eps a})\ da \nonumber \\
&\leq  \sum_{1 \leq i \leq k} \int_0^\infty \widetilde{m}(\widetilde{A}) \cdot \frac{C_1' a^{-1/2}}{2} \cdot \frac{e^{-(\lambda-\eps)a}(\lambda-\eps)^i a^i }{i!} \cdot 2 \eps a \ da \nonumber \\
&\le C_{k,\lambda}\widetilde{m}(\widetilde{A})\eps
\end{align}
because the integral is finite, which completes the proof.
\end{proof}

\begin{proof}[Proof of Proposition \ref{Proposition: lln, fixed time, points in [0,n]}]

For $n$ sufficiently large, we apply Lemma \ref{Lemma: perturb the sampling intensity2} with $\lambda=1$, $\eps_n = (\log n)/\sqrt{n}$ and $A_n=[0,n]\times\R_+$ to get
$$
\E[l(A_n\cap B)]\le C_{k,\lambda}\sqrt{n}\log n.
$$
In particular, as $n\rightarrow\infty$, we have
$$
\frac{l(A_n\cap B)}{n}\rightarrow 0,\qquad\text{in probability}.
$$
Recall the definition of $\widetilde{\lambda}_n^*$ from \eqref{lambda2}. Then, as $n\rightarrow\infty$,
\begin{equation}\label{lambda star}
\P(\widetilde{\lambda}_n^*\in [1-\eps_n,1+\eps_n])\ge \P(\#(\widetilde{\Pi}_{1-\eps_n}\cap A_n)< n<\#(\widetilde{\Pi}_{1+\eps_n}\cap A_n))\rightarrow1.    
\end{equation}
On the event $\widetilde{\lambda}_n^*\in [1-\eps_n,1+\eps_n]$, we have
$$
Anc_k(\widetilde{\Pi}_{1})\ \triangle\  Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\subseteq B.
$$
It follows that as $n\rightarrow\infty$, 
\begin{equation}\label{Sampling from a fixed time, comparison}
\frac{l\Big(\big(Anc_k(\widetilde{\Pi}_{1})\ \triangle\  Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\big)\cap A_n\Big)}{n}\rightarrow 0,\qquad\text{in probability}.   
\end{equation}
The claim of the proposition then follows from \eqref{Sampling from a fixed time, comparison} and Proposition \ref{Proposition: lln, fixed time, points anywhere}.
\end{proof}

\begin{remark}\label{Remark}
The same reasoning applies if we take $A_n=[0,n]\times[0,T]$ for a fixed $T>0$. Using \eqref{Sampling from a fixed time, slln}, we conclude that as $n\rightarrow\infty$,
$$
\frac{l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap([0,n]\times[0,T])\big)}{n}\rightarrow\E\Big[l\big(Anc_{k}(\widetilde{\Pi}_1)\cap([0, 1)\times[0,T])\big)\Big]\qquad\text{in probability}.
$$
\end{remark}

\subsection{Proof of Proposition \ref{Proposition: diff2}}\label{sub3.4}

To obtain Proposition \ref{Proposition: diff2} from Proposition \ref{Proposition: lln, fixed time, points in [0,n]}, we will derive lower and upper bounds for $l(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n))$ in terms of $l(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap A_n)$. 
The following lemma bounds the length of the set of points that are ancestors of $k$ points in $[0,n]$ and additional sampled points outside of the interval.

\begin{lemma}\label{Lemma: Height of the Anc_k1}
Let $\eps_n=(\log n)/\sqrt{n}$. Let $A_n$ and $\widetilde{\lambda}_n^*$ be defined as in Proposition \ref{Proposition: lln, fixed time, points in [0,n]}. Then, as $n\rightarrow\infty$, we have
$$
\frac{l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\setminus Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\big)}{n}\rightarrow 0\qquad \text{ in probability}.
$$
\end{lemma}

\begin{proof}
For any $\lambda>0$, let $\{(x_{i,\lambda},0)\}_{i\in\Z}$ be the sampled points in $\widetilde{\Pi}_{\lambda}$, ordered so that $$
\dots<x_{0,\lambda}<0\le x_{1,\lambda}<x_{2,\lambda}<\dots<x_{N_{\lambda}, \lambda}\le n<x_{N_{\lambda}+1,\lambda}<\dots.
$$ 
Then there are $N_{\lambda}$ points sampled from $[0,n]$. Note that the choice of $\widetilde{\lambda}_n^*$ guarantees that $N_{\widetilde{\lambda}_n^*}=n$. For ease of notation, we write $x_i=x_{i,\widetilde{\lambda}_n^*}$. 

Because $\P(\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n])\rightarrow1$ as $n\rightarrow\infty$ by \eqref{lambda star}, we may assume that $\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]$ holds in the rest of the argument. If $(y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*} \cap A_n)\setminus Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})$, then there exist $i\in\{1,\dots, n\}$ and $j\notin\{1,\dots, n\}$ such that both $(x_i,0)$ and $(x_j,0)$ are descendants of $(y,t)$. By the ordering of geodesics in Proposition \ref{Proposition: ordering of geodesics}, we deduce that $(x_0,0)\in \widetilde{D}_{(y,t)}$ or $(x_{n+1},0)\in\widetilde{D}_{(y,t)}$. Therefore, for any $t>0$, we have
$$
\#\Big\{y\in\R: (y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*} \cap A_n)\setminus Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\Big\}\le 2.
$$
Moreover, if $(x_0,0)\in \widetilde{D}_{(y,t)}$ with $(y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)$, then using the ordering of geodesics again, we have $\widetilde{D}_{(y,t)}\cap\widetilde{\Pi}_{\widetilde{\lambda}_n^*} \cap A_n=\{(x_i,0)\}_{i=1}^k$. In this case, the time $t$ is bounded above by the coalescence time of the geodesics $g_{(x_1,0)}$ and $g_{(x_{k+1},0)}$ because otherwise we would have $\{(x_i,0)\}_{i=1}^{k+1}\subseteq \widetilde{D}_{(y,t)}$, contradicting that $(y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)$. Also, if $n$ is sufficiently large and $\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]$, then
$$
x_{0,1/2}\le x_{0,1-\eps_n}< x_1<x_{k+1}\le x_{k+1,1-\eps_n}\le x_{k+1,1/2}.
$$
Therefore, by the ordering of geodesics, the time $t$ is bounded from above by the coalescence time of $g_{(x_{0,1/2},0)}$ and $g_{(x_{k+1,1/2}, 0)}$ which we call $\xi_1$.
Similarly, if $(x_n,0)\in\widetilde{D}_{(y,t)}$, $n$ is sufficiently large, and $\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]$, then the time $t$ is bounded from above by the coalescence time of $g_{(x_{N_{1/2}-k,1/2},0)}$ and $g_{(x_{N_{1/2}+1,1/2},0)}$ which we call $\xi_2$. Therefore, 
$$
l\left(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\setminus Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\right)
$$
is bounded above by $\xi_1+\xi_2$. Because this is a tight random variable, the lemma follows.
\end{proof}

The next lemma bounds the probability that there are points at height greater than $t$ that are ancestral to exactly $k$ sampled points, all of which are in $[0,n]$. In the proof of Lemma \ref{Lemma: Height of the Anc_k2}, we will again use the three-arm estimate given in Theorem \ref{Theorem: 3-disjoint}. Note that by combining Theorem \ref{Theorem: 3-disjoint} with the scaling property in part 3 of Proposition \ref{Proposition: properties of the landscape}, we can see that for $M\ge 1$, the probability that the geodesics $g_{(-M,0)}$, $g_{(0,0)}$ and $g_{(-M,0)}$ remain disjoint until time $t$ is bounded above by $CM^{5/2}t^{-5/2}\log^{52}(t\vee 2)$.

\begin{lemma}\label{Lemma: Height of the Anc_k2}
Let $\eps_n=(\log n)/\sqrt{n}$. Let $A_n$ and $\widetilde{\lambda}_n^*$ be defined as in Proposition \ref{Proposition: lln, fixed time, points in [0,n]}. Then there exists a constant $C_{k}$ depending only on $k$ such that for all $t\ge 2$, we have
\begin{align*}
&\P\Big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\cap Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap (\R\times[t,\infty))\neq \emptyset\Big)\\
&\qquad\qquad\le C_{k}nt^{-5/3}\log^{52}t + \P\Big(\widetilde{\lambda}_n^{*}\notin[1-\eps_n,1+\eps_n]\Big).    
\end{align*}
\end{lemma}

\begin{proof}
If $(y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\cap Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})$, then there exists $i\in\{1,\dots, n-k+1\}$ such that
\begin{equation*}
D_{(y,t)}\cap\widetilde{\Pi}_{\widetilde{\lambda}_n^*}=D_{(y,t)}\cap\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n=\{(x_i,0),\dots, (x_{i+k-1},0)\}. 
\end{equation*}
Then, before time $t$, the geodesics  $g_{(x_{i},0)}$ and $g_{(x_{i+k-1},0)}$ coalesce, and neither $g_{(x_{i-1},0)}$ and $g_{(x_{i},0)}$ nor $g_{(x_{i+k-1},0)}$ and $g_{(x_{i+k},0)}$ coalesce. In particular, the geodesics $g_{(x_{i-1},0)}$, $g_{(x_{i},0)}$, and $g_{(x_{i+k},0)}$ are disjoint until time $t$. Note also that the probability that these geodesics are disjoint is monotone in the gaps $x_{i}-x_{i-1}$ and $x_{i+k}-x_{i}$. Conditioning on $(\widetilde{\Pi}_{\lambda})_{\lambda>0}$ and applying Theorem \ref{Theorem: 3-disjoint} with $M=\max\{x_i-x_{i-1}, x_{i+k}-x_i,1\}$ for $i=1,2,\dots, n-k+1$, we have
\begin{align*}
&\P\Big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\cap Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap (\R\times[t,\infty))\neq \emptyset\Big|\widetilde{\Pi}\Big)\\
&\qquad\le Ct^{-5/3}\log^{52} (t\vee 2) \sum_{i=1}^{n-k+1}\max\{x_i-x_{i-1}, x_{i+k}-x_i,1\}^{5/2}.
\end{align*}
Taking expectations, we have
\begin{align}\label{height Anc_k}
&\P\Big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\cap Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap (\R\times[t,\infty))\neq \emptyset\Big)\nonumber\\
&\qquad\le Ct^{-5/3}\log^{52} (t\vee 2) \sum_{i=1}^{n-k+1}\E\Big[\max\{x_i-x_{i-1}, x_{i+k}-x_i,1\}^{5/2}\mathbbm{1}_{\{\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]\}}\Big]\nonumber\\
&\qquad\qquad+\P\Big(\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]\Big).
\end{align}
For $1\le i<i'\le n$, the random variable $(x_{i'}-x_{i})/n$ has a $Beta(i'-i, n+1-(i'-i))$ distribution (see Section 4.1 of \cite{p65}). Therefore, for $2\le i\le n-k$, we have
$$
\E\Big[\max\{x_i-x_{i-1}, x_{i+k}-x_i,1\}^{5/2}\mathbbm{1}_{\{\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]\}}\Big]\le \E\big[(x_{i+k}-x_{i-1}+1)^{5/2}\big]\le C_k.
$$
Also, if $n$ is sufficiently large and $\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]$, then $x_{0,1/2}\le x_0< 0$ and $n<x_{n+1}\le x_{N_{1/2}+1,1/2}$. Then for $i=1$, we have
\begin{align*}
\E\Big[\max\{x_1-x_{0}, x_{k+1}-x_1,1\}^{5/2}\mathbbm{1}_{\{\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]\}}\Big]
&\le \E\Big[(x_{k+1}-x_0+1)^{5/2}\mathbbm{1}_{\{\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]\}}\Big]\\
&\le \E[(x_{k+1}-x_{0,1/2}+1)^{5/2}]\\
&\le 3^{5/2}\big(\E[x_{k+1}^{5/2}]+\E[|x_{0,1/2}|^{5/2}]+1\big)\\
&\le C_{k},
\end{align*}
and a similar estimate holds for $i=n-k+1$. Combining this bound with the estimate for $2\le i\le n-k$, we have
\begin{equation}\label{beta expectation}
\sum_{i=1}^{n-k+1}\E\Big[\max\{x_i-x_{i-1}, x_{i+k}-x_i\}^{5/2}\mathbbm{1}_{\{\widetilde{\lambda}_n^*\in[1-\eps_n,1+\eps_n]\}}\Big]\le C_{k}n.
\end{equation}
The lemma now follows from \eqref{height Anc_k} and \eqref{beta expectation}.
\end{proof}

We now prove Proposition \ref{Proposition: diff2}. We will show that with high probability, one can lower and upper bound $l(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n))$ using $l(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap A_n)$ and some error terms.
\begin{proof}[Proof Proposition \ref{Proposition: diff2}]
We will prove that for any subsequence $(n_m)_{m\ge 1}$, there is a further subsequence $(n_{m_l})_{l\ge 1}$ such that
\begin{equation}\label{Sampling from a fixed time, lower bound}
\liminf_{l\rightarrow\infty}\frac{l\Big(Anc_k\Big(\widetilde{\Pi}_{\widetilde{\lambda}_{n_{m_l}}^*}\cap A_{n_{m_l}}\Big)\Big)}{n}\ge  \frac{C_1'}{2}\cdot\frac{\Gamma(k + 1/2)}{k!}\qquad\text{a.s.},
\end{equation}
and another further subsequence $(n_{m_{l'}})_{l'\ge 1}$ such that
\begin{equation}\label{Sampling from a fixed time, upper bound}
\limsup_{l\rightarrow\infty}\frac{l\Big(Anc_k\Big(\widetilde{\Pi}_{\widetilde{\lambda}_{n_{m_{l'}}}^*}\cap A_{n_{m_{l'}}}\Big)\Big)}{n_{m_{l'}}}\le  \frac{C_1'}{2}\cdot \frac{\Gamma(k+1/2)}{k!}\qquad\text{a.s.}.
\end{equation}
The statement of the proposition then follows from \eqref{Sampling from a fixed time, lower bound} and \eqref{Sampling from a fixed time, upper bound}.

We start with the proof of \eqref{Sampling from a fixed time, lower bound}, which does not require Lemmas \ref{Lemma: Height of the Anc_k1} and \ref{Lemma: Height of the Anc_k2}. Fix $\eps>0$ and $T>0$. Let $E_n$ be the event that the following hold:
\begin{enumerate}
\item $\sup_{t\in[0,T]} |g_{(\eps n,0)}(t)-\eps n|\le \eps n,$
\item $\sup_{t\in[0,T]}|g_{((1-\eps) n, 0)}(t)-(1-\eps)n|\le \eps n.$
\end{enumerate}
By Theorem \ref{Theorem: transversal fluctuation}, we have $\P(E_n^c)\le 2C_3 e^{-C_4 \eps^3 n^3/T^2}$, which is summable in $n$. Also, on the event $E_n$, we have
$$
Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\supseteq   Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap ([2\eps n,(1-2\eps)n]\times[0,T]),
$$
and hence
$$
\liminf_{n\rightarrow\infty}\frac{l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\big)}{n}\ge  \liminf_{n\rightarrow\infty} \frac{l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap ([2\eps n,(1-2\eps)n]\times[0,T])\big)}{n}.
$$
Therefore, by Remark \ref{Remark}, we can choose a subsequence $(n_{m_l})$ such that
$$
\liminf_{l\rightarrow\infty}\frac{l\Big(Anc_k\Big(\widetilde{\Pi}_{\widetilde{\lambda}_{n_{m_l}}^*}\Big)\cap A_{n_{m_l}}\Big)}{n}\ge (1-4\eps)\E[l\big(Anc_{k}(\widetilde{\Pi}_1)\cap([0, 1)\times[0,T])\big)].
$$
Recall from \eqref{sfs2} that 
$$
\E[l\big(Anc_{k}(\widetilde{\Pi}_1)\cap([0, 1)\times\R_+)\big)]=\frac{C_1'}{2}\cdot\frac{\Gamma(k+1/2)}{k!}.
$$
Equation \eqref{Sampling from a fixed time, lower bound} then follows from a diagonalization argument as we let $\eps\rightarrow0$ and $T\rightarrow\infty$.

We now prove \eqref{Sampling from a fixed time, upper bound}.
Fix $\eps>0$. Let $F_n$ be the event that
\begin{enumerate}
\item $Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\cap Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap (\R\times[n,\infty))=\emptyset$,
\item $\sup_{t\in[0,n]} |g_{(-\eps n,0)}(t)+\eps n|\le \eps n,$
\item $\sup_{t\in[0,n]}|g_{((1+\eps) n, 0)}(t)-(1+\eps)n|\le \eps n.$
\end{enumerate}
By Theorem \ref{Theorem: transversal fluctuation} and Lemma \ref{Lemma: Height of the Anc_k2}, we have
$$
\P(F_n^c)\le Cn^{-2/3}\log^{52} n+\P\big(\widetilde{\lambda}_n^*\notin \big[1-(\log n)/\sqrt{n},1+(\log n)/\sqrt{n}\big]\Big)+2C_3 e^{-C_4 \eps^3 n}.
$$
One may choose $(n_{m_l})_{l\ge 1}$ so that $\sum_l \P(F_{n_{m_l}}^c)<\infty$. If the event $F_n$ occurs, then for each $(y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)$, either $(y,t)\notin Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})$ or $(y,t)\in Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})$. For the latter case, we have $t\le n$ by the first condition of $F_n$ and then $-2\eps n\le y\le (1+2\eps )n$ by the second and third conditions of $F_n$. Then 
\begin{align*}
&l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\big)\\
&\le l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\setminus Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\big)+ l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap ([-2\eps n,(1+2\eps)n]\times[0,n])\big)\\
&\le l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*}\cap A_n)\setminus Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\big)+ l\big(Anc_k(\widetilde{\Pi}_{\widetilde{\lambda}_n^*})\cap ([-2\eps n,(1+2\eps)n]\times\R_+)\big).
\end{align*}
Then, by Remark \ref{Remark} and Lemma \ref{Lemma: Height of the Anc_k1}, choosing a further subsequence if necessary, we have
\begin{align*}
\limsup_{l\rightarrow\infty}\frac{l\big(Anc_k(\widetilde{\Pi}_{\lambda_{n_{m_{l'}}}^*}\cap A_{n_{m_{l'}}})\big)}{n_{m_{l'}}}\le (1+4\eps)\frac{C_1'}{2}\cdot\frac{\Gamma(k+1/2)}{k!}.
\end{align*}
Equation \eqref{Sampling from a fixed time, upper bound} then follows from a diagonalization argument as we let $\eps\rightarrow0$.
\end{proof}

\section{Sampling from the entire population}\label{Section: 2-dimension}

We will proceed by proving Propositions~\ref{Proposition: expectation}-\ref{Proposition: diff1}. In Section~\ref{Subsection: expectation1}, we derive \eqref{cdf1} and \eqref{sfs1} using the scaling invariance property of the directed landscape. In Section~\ref{Subsection: lln, points anywhere}, we prove a strong law of large numbers as stated in Proposition~\ref{Proposition: lln, points anywhere}. It is worth noting that, while the directed landscape is independent over disjoint time intervals, the quantity $l(Anc_k(\Pi_\lambda)\cap A_n)$ does not enjoy this property because the geodesic $g_{(x,s)}$ depends on $\L|_{\R\times(s,\infty)}$. A coupling argument is carried out in Lemma~\ref{Lemma: localization for sampling from the population} so that this dependence is localized in the temporal direction.  In Section~\ref{Subsection: robust1}, we establish a stability result in terms of the sampling rate, allowing us to change from a deterministic sampling rate in Proposition~\ref{Proposition: lln, points anywhere} to a random sampling rate in Proposition~\ref{Proposition: lln, points in the box}. Section~\ref{Subsection: diff1} concludes the proof of Theorem~\ref{Theorem: main1} by proving Proposition~\ref{Proposition: diff1}.

\subsection{Proof of Proposition \ref{Proposition: expectation}}\label{Subsection: expectation1}

To prove Proposition \ref{Proposition: expectation}, we need to establish a scaling result that is similar to Proposition~\ref{Proposition: properties of T_a}.
For any $A\subseteq \R^2$, let 
\begin{equation*}
H(A)= \sup\{|t'-t|:(y,t), (y',t')\in A\} 
\end{equation*}
be the height of $A$ and 
\begin{equation*}
W(A)= \sup\{|x'-x|: (x,s),(x',s')\in A\}
\end{equation*}
be the width of $A$. We take $H(\emptyset)=W(\emptyset)=0$ by convention. For any $a\ge 0$, let
\begin{equation}\label{Definition: height and width of descendants}
\H_{ a}:=\{(y,t)\in\R^2:H(D_{(y,t)})> a\},\qquad\W_{a}:=\{(y,t)\in\R^2:W(D_{(y,t)})> a\}   
\end{equation}
be the collection of space-time pairs whose descendants have height (resp. width) more than $a$. Also, recall $\V_a$ from \eqref{Introduction: def T_a}. The following result, which is similar to Corollary \ref{Corollary: Vtildenew} is an immediate consequence of Lemma \ref{Lemma: semigroup}.

\begin{corollary}\label{Corollary: semigroup}
If $(y',t')$ is an ancestor of $(y,t)$, i.e., $g_{(y,t)}(t'-t)=y'$, then $D_{(y',t')}\supseteq D_{(y,t)}$. In particular, if $(y,t)\in\V_{a}$ (resp. $\H_a$ or $\W_a$), then $(y',t')\in\V_{a}$ (resp. $\H_a$ or $\W_a$).
\end{corollary}

We now collect some results about $\H_a,\W_a,$ and $\V_a$ which are consequences of the scaling property of $\L$.  This result is proved in exactly the same way as Proposition \ref{Proposition: properties of T_a, fixed time}, so we do not repeat the argument.

\begin{proposition}\label{Proposition: properties of T_a}
Recall the scaling map $S_{\rho}: \R^2 \rightarrow \R^2$ defined by 
$S_\rho(x,s)=(\rho^{-2}x,\rho^{-3}s)$.
The following hold for $\V_{a}$, $\H_{a}$, and $\W_{a}$:
\begin{enumerate}
\item We have $S_\rho(\V_{a})\stackrel{d}{=}\V_{\rho^{-5}a}$, $S_\rho(\H_{a})\stackrel{d}{=}\H_{\rho^{-3}a}$, and $S_\rho(\W_{a})\stackrel{d}{=}\W_{\rho^{-2}a}$.

\item We have $\P(\V_{a}=\emptyset)=\P(\H_{a}=\emptyset)=\P(\W_{a}=\emptyset)=0$ for all $a>0$.
\end{enumerate}
\end{proposition}

We are now ready to prove Proposition \ref{Proposition: expectation}. 
\begin{proof}[Proof of Proposition \ref{Proposition: expectation}]
Firstly, we show that \eqref{cdf1} holds when $a=1$, with $C_2'\in[0,\infty]$. Fix $t\in\R$. We define a measure $\widetilde{\mu}$ on $\R$ by
\begin{equation}\label{mu1}
\widetilde{\mu}(\widetilde{A}) :=\E[\#(\V_{1}^t\cap \widetilde{A})]\qquad\text{ for all measurable } \widetilde{A}\subseteq\R.
\end{equation}
The countable additivity of $\widetilde{\mu}$ follows from the linearity of expectation and the monotone convergence theorem. The measure $\widetilde{\mu}$ is translation invariant by part 2 of Proposition \ref{Proposition: properties of the landscape}. It follows that there exists a constant $C_2'\in[0,\infty]$ such that $\widetilde{\mu}(\widetilde{A})=C_2'\widetilde{m}(\widetilde{A})$. Part 1 of Proposition \ref{Proposition: properties of the landscape} implies that the constant $C_2'$ does not depend on $t$.

We now show that \eqref{cdf1} holds for all $a>0$, with $C_2'\in[0,\infty]$.  Recall the scaling map $S_\rho$ from \eqref{scaling map}. We define its action on the spatial axis by 
\begin{equation}\label{scaling map, fixed time}
\widetilde{S}_{\rho}(x)=\rho^{-2} x,\qquad\text{for all }x\in\R. 
\end{equation}
For any $\widetilde{A}\subseteq\R$, we write $\widetilde{S}_{\rho}(\widetilde{A})$ for the image of $\widetilde{A}$ under $\widetilde{S}_{\rho}$.
Applying part 1 of Proposition \ref{Proposition: properties of T_a} with $\rho = a^{1/5}$, we have $S_{a^{1/5}}(\V_a)\stackrel{d}{=}\V_1$. Taking the time-$(a^{-3/5}t)$ slice, we get
$$
(\widetilde{S}_{a^{1/5}}(\V_a^t))=(S_{a^{1/5}}(\V_a))^{a^{-3/5}t}\stackrel{d}{=}\V_1^{a^{-3/5}t}.
$$
Therefore,
\begin{align*}
\#(\V^t_{a}\cap \widetilde{A})=\#\left(\widetilde{S}_{a^{1/5}}(\V_{a}^t\cap \widetilde{A})\right)=\#\left(\widetilde{S}_{a^{1/5}}(\V^t_{a})\cap \widetilde{S}_{a^{1/5}}(\widetilde{A})\right)\stackrel{d}{=}\#\left(\V_1^{a^{-3/5}t}\cap \widetilde{S}_{a^{1/5}}(\widetilde{A})\right).
\end{align*}
Taking expectations, and then using \eqref{mu1}, we have
$$
\E[\#(\V^t_{a}\cap \widetilde{A})] = \E\Big[\#\big(\V_{1}^{a^{-3/5}t}\cap \widetilde{S}_{a^{1/5}}(\widetilde{A})\big)\Big]=C_2'\widetilde{m}\big(\widetilde{S}_{a^{1/5}}(\widetilde{A})\big)=C_2'\widetilde{m}(\widetilde{A})a^{-2/5}.
$$
To prove \eqref{cdf1}, it remains to show that $C_2'\in(0,\infty)$.

We first rule out the possibility that $C_2'=0$. Fix $a>0$. Seeking a contradiction, we suppose that $C_2'=0$. Then $\E[\#\V^t_{a}]=0$ for all $t\in\R$. This implies that $\P(\V^t_{a}=\emptyset \text{ for all }t\in\Q)=1$. It then follows from Corollary \ref{Corollary: semigroup} that $\P(\V_{a}=\emptyset)=1$, which contradicts part 2 of Proposition \ref{Proposition: properties of T_a}.

