We next rule out the possibility that  $C_2'=\infty$. Note that if $m(D_{(y,t)})$ is large, then $D_{(y,t)}$ has to be either ``tall" or ``wide" (see Figure \ref{Figure: tall wide}). We take $t=1$, $a=1$, and $\widetilde{A}=[-1,1]$. Recall the definition of $\H_a$ from \eqref{Definition: height and width of descendants}. We decompose $\V^1_{1}\cap \widetilde{A}$ according to whether the height is greater than $1$ or not:
$$
\V^1_{1}\cap \widetilde{A}= (\V^1_{1}\cap \widetilde{A}\cap \H_{1}^1) \cup (\V^1_{1}\cap \widetilde{A}\cap(\H_{1}^c)^1).
$$
If $(y,1)\in\V^1_{1}\cap \widetilde{A}\cap \H_{1}^1$, then by the definition of $\H_{1}$, we have $H(D_{(y,1)})>1$ and there exists a geodesic $g_{(x,0)}$ that passes through $(y,1)$. Recall the definition of $N_1$ from Proposition \ref{Proposition: number of intersection points}. Then
$$
\#(\V^1_{1}\cap \widetilde{A}\cap \H_{1}^1)\le N_{1}.
$$
In particular, 
$$
\E\big[\#(\V^1_{1}\cap \widetilde{A}\cap \H_{1}^1)\big]\le \E[N_{1}]<\infty.
$$
Let $\widetilde{B}=\V^1_{1}\cap \widetilde{A}\cap (\H_{1}^1)^c$. It remains to show that $\E[\# \widetilde{B}]<\infty$. 
Note that the sets $D_{(y,1)}$ are disjoint for distinct $y\in \widetilde{A}$, and that $m(D_{(y,1)})> 1$ and $H(D_{(y,1)})\le 1$ for all $y\in\widetilde{B}$. Therefore, if we let
\begin{equation*}
D_A:=\bigcup_{(x,s)\in A}D_{(x,s)}
\end{equation*}
be the descendants of $A\subseteq\R^2$, then 
$$
\#\widetilde{B}\le \sum_{y\in \widetilde{B}}m(D_{(y,1)}) =m (D_{\widetilde{B}\times \{1\}})\le m \left(D_{\widetilde{A}\times \{1\}}\cap(\R\times[0,1])\right).
$$
Taking expected values, we have
$$
\E[\#\widetilde{B}]\le \E\left[m \left(D_{\widetilde{A}\times \{1\}}\cap(\R\times[0,1])\right)\right].
$$
To bound the right-hand side, for any $K>0$, let $E_K$ be the event 
that 
$$
m\left(D_{\widetilde{A}\times \{1\}}\cap(\R\times[0,1])\right)\ge 2(K+1).
$$
We claim that the event $E_K$ occurs only if one of the following events occurs:
\begin{enumerate}
\item $\sup_{u\in[0,1]}|g_{(K/2+1,0)}(u)-(K/2+1)|\ge K/2$,
\item $\sup_{u\in[0,1]}|g_{(-K/2-1,0)}(u)+(K/2+1)|\ge K/2$.
\end{enumerate}
Indeed, unless one of these two events occurs, if $(x,s)\in D_{(y,1)}$, where $-1\le y\le 1$,  $|x|>K+1$ and $0\le s\le 1$, then the geodesic $g_{(x,s)}$ must cross either the geodesic $g_{(K/2+1,0)}$ or $g_{(-K/2-1,0)}$, which contradicts the ordering of geodesics in Proposition \ref{Proposition: ordering of geodesics}. Therefore, by Theorem \ref{Theorem: transversal fluctuation}, we have
$$
\P(E_K)\le 2\P\left(\sup_{u\in[0,1]} |g_{(K/2+1,0)}(u)-(K/2+1)|\ge K/2\right)\le 2C_3 e^{-C_4 K^3/8}.
$$
It follows that $\E[\#\widetilde{B}]<\infty$, which concludes the proof of \eqref{cdf1}.

It remains to prove \eqref{sfs1}. It suffices to consider the case where $\widetilde{m}(A^t)<\infty$ for all $t\in \R$, as one can replace $A$ by $A\cap([-n,n]\times\R)$ and take the limit as $n\rightarrow\infty$. Recalling the definition of the branch length from \eqref{def length}, we have
\begin{equation*}
\E\Big[l\big(Anc_k(\Pi_\lambda)\cap A\big)\Big]
= \E\left[\int_{-\infty}^\infty \#(Anc_k(\Pi_\lambda)\cap A)^t\ dt\right]=\int_{-\infty}^\infty \E\Big[\#\big(Anc_k(\Pi_\lambda)\cap A\big)^t\Big]\ dt.
\end{equation*}
To evaluate the expectation, note that if $m(D_{(y,t)})=a$, then $(y,t)\in Anc_k(\Pi_\lambda)$ with probability $e^{-\lambda a}(\lambda a)^k/k!$. 
Using \eqref{cdf1}, let 
\begin{equation}\label{Sampling from the population, density}
\phi(a)=-\frac{d}{da}\E[\#([0,1]\cap\V_a^t)] = \frac{2C_2' a^{-7/5}}{5}  
\end{equation}
be the ``density" for the number of points whose descendants have Lebesgue measure ``exactly" $a$.  Just as in the proof of \eqref{Sampling from a fixed time: integration over a}, we can use a discrete approximation to justify integrating over $a$ to obtain
\begin{align}\label{Sampling from the entire population, expectation}
\E\Big[\#\big(Anc_k(\Pi_\lambda)\cap A\big)^t\Big]&=\int_0^\infty \frac{e^{-\lambda a}(\lambda a)^k}{k!}\cdot \frac{2C_2' a^{-7/5}}{5}\cdot\widetilde{m}(A^t)\ da\nonumber\\
&= \frac{2C_2'\lambda^k}{5k!}\cdot\widetilde{m}(A^t)\int_0^\infty e^{-\lambda a} a^{k-7/5}\ da\nonumber\\
&=\frac{2C_2' \lambda^{2/5}}{5}\cdot\widetilde{m}(A^t) \cdot\frac{\Gamma(k-2/5)}{k!}.
\end{align}
Equation \eqref{sfs1} then follows from integrating over $t$.
\end{proof}

\begin{remark}\label{Remark: scaling of H_a}
Similar to the proof of \eqref{cdf1}, one can show that there exists a constant $C_2''\in(0,\infty)$ such that 
$$
\E\Big[\#\big(\mathcal{H}_a^t \cap \widetilde{A}\big)\Big] = C_2''\widetilde{m}(\widetilde{A})a^{-2/3},
$$
for all $t\in\R$ and all measurable subsets $\widetilde{A}\subseteq\R$. We will use this remark in Lemma~\ref{Lemma: tall bubbles} later.
\end{remark}

\subsection{Proof of Proposition \ref{Proposition: lln, points anywhere}}\label{Subsection: lln, points anywhere}

We now turn to the law of large numbers result.  As mentioned at the beginning of Section \ref{Section: 2-dimension}, we now introduce a coupling so that the dependence of $l(Anc_k(\Pi_\lambda)\cap A_n)$ on $\L$ is localized. In the next lemma, we consider the set $R_M$ of points in a unit box $B$ that are ancestral to $k$ sampled points and whose set of descendants has height at most $M$. We show that with high probability, $l(R_M)$ agrees with a random variable $X$ which is obtained by replacing infinite upward geodesics by finite geodesics in the definition of $Anc_{k}(\Pi_\lambda)$.  The random variable $X$ therefore depends on $\L$ only within a horizontal strip of height $T$. The dominant term in the bound on $\P(X\neq l(R_M))$ is an estimate for the probability that two finite geodesics do not intersect and comes from Proposition \ref{Proposition: disjoint finite geodesics} with $x_2-x_1=O(\log T)$ and $y_2-y_1=O(T^{2/3}\log T)$.

\begin{lemma}\label{Lemma: localization for sampling from the population}
Recall the definition of $\H_a$ from \eqref{Definition: height and width of descendants}. Let $B=[-1/2, 1/2]\times[0,1]$. For any $M>1$ and any $T>2M+1$, let
$$
R_M=(Anc_{k}(\Pi_\lambda)\setminus\H_M)\cap B,
$$
as shown in Figure \ref{Figure: R_M} below. Then there exists a random variable $X$ measurable with respect to the $\sigma$-field generated by $\Pi_{\lambda}\cap (\R\times [-2M,1])$ and $\L|_{\R\times[-2M,T-2M]}$ and a constant $C_M$ depending on $M$ such that
$$
\P(X\neq l(R_M))\le C_M  T^{-1/3}(\log ^{3/2}T)\exp(\log ^{5/6}T).
$$
\end{lemma}

