\caption{A realization of the event $E_{K}$. The geodesics $g_1$ and $g_2$ coalesce at $(y^*,t^*)$. The region $B_1$ is the dotted region enclosed by $g_1$, $g_2$, and $t=-2M$. For $(x,s)\in B_1$, the infinite upward geodesic $g_{(x,s)}$ and the finite geodesic $g_{(x,s; 0,T-2M)}$ pass through $(y^*,t^*)$ and agree up to time $t^*$.  If the event $E_K$ occurs, then the box $B_2 :=[-3K/4-1/2,3K/4+1/2]\times[-2M,1]$ is a subset of $B_1$.}
\label{Figure: coupling}
\end{figure}
\begin{enumerate}
\item $E_{K,1}: \sup_{u\in[0,2M+1]}|g_{(K/2+1/2,-2M)}(u)-(K/2+1/2)|< K/4$,
\item $E_{K,2}: \sup_{u\in[0,2M+1]}|g_{(-K/2-1/2,-2M)}(u)+(K/2+1/2)|< K/4$,
\item $E_{K,3}: \sup_{u\in[0,2M+1]}|g_{(K+1/2,-2M)}(u)-(K+1/2)|< K/4$,
\item $E_{K,4}: \sup_{u\in[0,2M+1]}|g_{(-K-1/2,-2M)}(u)+(K+1/2)|< K/4$,
\item $E_{K,5}: \sup_{u\in[0,T]}|g_{(K+1/2,-2M)}(u)-(K+1/2)|< T^{2/3}\log T$,
\item $E_{K,6}: \sup_{u\in[0,T]}|g_{(-K-1/2,-2M)}(u)+(K+1/2)|< T^{2/3}\log T$.
\item $E_{K,7}$ is the event that the finite geodesics $g_1=g_{(-K-1/2,-2M;-K-1/2-T^{2/3}\log T,T-2M)}$ and \newline $g_2=g_{(K+1/2,-2M;K+1/2+T^{2/3}\log T,T-2M)}
$ are nondisjoint.
\end{enumerate}
By Theorem \ref{Theorem: transversal fluctuation}, we have
$$
\P(E_{K,1}^c)=\P(E_{K,2}^c)=\P(E_{K,3}^c)=\P(E_{K,4}^c)\le C_3 e^{-C_4 K^3/(64(2M+1)^2)},
$$
and
$$
\P(E_{K,5}^c)=\P(E_{K,6}^c)\le C_3 e^{-C_4 \log ^3 T}.
$$
By Proposition \ref{Proposition: disjoint finite geodesics}, we have
$$
\P(E_{K,7}^c)\le C(2K+1)^{1/2}(2K+1+2T^{2/3}\log T)\cdot\frac{1}{T}\cdot\exp\left(\log^{5/6}\left(\frac{T}{(2K+1)^{3/2}}\vee 1\right)\right).
$$
Take $K=\log T$, and we have $\P(E_K)\ge 1-C_M T^{-1/3}(\log ^{3/2}T)\exp(\log ^{5/6}T)$.

It remains to show that $X=l(R_M)$ on $E_K$, which will imply the statement of the lemma. We make the following observations:
\begin{enumerate}
\item If the event $E_{K,7}$ occurs, then the geodesics $g_1$ and $g_2$ coalesce at some point $(y^*,t^*)$ where $t^*\le T-2M$. If the events $E_{K,5}$ and $E_{K,6}$ also occur, then applying Proposition \ref{Proposition: ordering of geodesics} to the finite geodesics $g_1$ and $g_2$ and the restrictions of $g_{(-K-1/2,-2M)}$ and $g_{(-K-1/2,-2M)}$ up to time $T-2M$, we conclude that the infinite upward geodesics $g_{(-K-1/2,-2M)}$ and $g_{(K+1/2,-2M)}$ must pass through $(y^*,t^*)$. Also, let
$$
B_1=\{(y,t)\in \R^2: -2M\le t\le t^*, g_1(t+2M)\le y\le g_2(t+2M)\}
$$
be the region between the geodesics $g_1$ and $g_2$ up to time $t^*$ (see Figure \ref{Figure: coupling}). Using Proposition~\ref{Proposition: ordering of geodesics} again, we see that for any $(x,s)\in B_1$, the geodesics $g_{(x,s)}$ and $g_{(x,s;0,T-2M)}$ agree up to time $t^*$, i.e., 
\begin{equation}\label{Sampling from the entire population: local1}
g_{(x,s)}(u)=g_{(x,s; 0,T-2M)}(u)\qquad\text{for all } (x,s)\in B_1 \text{ and }0\le u\le t^*-s.
\end{equation}
\item If the events $E_{K,3}$ and $E_{K,4}$ occur and we define $B_2 :=[-3K/4-1/2,3K/4+1/2]\times[-2M,1]$, then 
\begin{equation}\label{B2 B1}
B_2\subseteq B_1 .  
\end{equation}
\item If the events $E_{K,1}$ and $E_{K,2}$ occur, then descendants of individuals in $B$ stay within the box $B_2$. That is,
\begin{equation}\label{Sampling from the entire population: local2}
D_{(y,t)}\cap(\R\times[-2M,1])\subseteq B_2,\qquad\text{ for all }(y,t)\in B.
\end{equation}
\item If the event $E_K$ occurs, then we claim that
\begin{equation}\label{coupling height}
H(D_{(y,t)})\le M \qquad\text{ for all }(y,t)\in R_M'.
\end{equation}
Indeed, if $H(D_{(y,t)})>M$, then there exists $x\in\R$ and $s\in[-2M,t-M)$ such that the infinite upward geodesic $g_{(x,s)}$ passes through $(y,t)$. By \eqref{B2 B1} and \eqref{Sampling from the entire population: local2}, we have $(x,s)\in B_2\subseteq B_1$. Then \eqref{Sampling from the entire population: local1} implies that the finite geodesic $g_{(x,s;0,T-2M)}$ also passes through $(y,t)$. Therefore, we have $H(D'_{(y,t)})>M$, contradicting that $(y,t)\in R_M'\subseteq(\H'_M)^c$.
\end{enumerate}

We now prove that on the event $E_K$, the equality $R_M=R_M'$ holds, which implies that $X=l(R_M')=l(R_M)$. 

If $(y,t)\in R_M$, then we have $H(D_{(y,t)})\le M$ by definition and hence $D_{(y,t)}\subseteq \R\times[-M,1]$. Combining this with \eqref{B2 B1} and \eqref{Sampling from the entire population: local2} gives $D_{(y,t)}\subseteq B_2\subseteq B_1$. It then follows from \eqref{Sampling from the entire population: local1} that $D_{(y,t)}=D'_{(y,t)}$ and hence $(y,t)\in R_M'$. 

If $(y,t)\in R_M'$, then we have $H(D_{(y,t)})\le M$ from \eqref{coupling height}. Repeating the argument as in the case where $y\in R_M$ gives  us $D_{(y,t)}=D'_{(y,t)}$, which implies that $(y,t)\in R_M$. 
\end{proof}

We are now ready to prove Proposition \ref{Proposition: lln, points anywhere}. We use an ergodic theorem and the space-time stationarity of $\L$ to deduce the a.s. and $L^1$ convergence to a possibly random limit, and then use a variance computation to conclude that a strong law of large numbers holds, as stated in Proposition \ref{Proposition: lln, points anywhere}.
\begin{proof}[Proof of Proposition \ref{Proposition: lln, points anywhere}]
Recall the definition of $A_n$ from the statement of Proposition \ref{Proposition: lln, points anywhere}. For $m\in[n^5,(n+1)^5)$, where $n$ is a positive integer, we have
\begin{align*}
\frac{l(Anc_k(\Pi_\lambda)\cap A_{n^5})}{(n+1)^5}\le \frac{l(Anc_k(\Pi_\lambda)\cap A_m)}{m}\le\frac{l(Anc_k(\Pi_\lambda)\cap A_{(n+1)^5})}{n^5}.
\end{align*}
Therefore, it suffices to show that
\begin{equation}\label{Sampling from the entire population, integer side length}
\lim_{n\rightarrow\infty}\frac{l(Anc_k(\Pi_\lambda)\cap A_{n^5})}{n^5}= \frac{2C_2'\lambda^{2/5}}{5}\cdot \frac{\Gamma(k - 2/5)}{k!},\qquad \text{a.s. and in } L^1,  
\end{equation}
holds when we only consider positive integers $n$.

We will divide $A_{n^5}$ into $n^5$ unit boxes and consider the restrictions of $Anc_k(\Pi_\lambda)$ to those boxes. We will also apply a truncation so that the variance can be bounded. Let $M,N>1$ be fixed integers. For $i,j\in\Z$, let $B_{i,j}=[i-1,i]\times[j-1,j]$, and let 
$$
X_{i,j}=l\Big((Anc(\Pi_{\lambda})\setminus\H_M)\cap B_{i,j}\Big).
$$ 
By parts 1 and 2 of Proposition \ref{Proposition: properties of the landscape}, $\{X_{i,j}\}_{i,j\in\Z}$ is stationary under shifts in the time or space direction. Therefore, we can apply an ergodic theorem which holds for random variables indexed by $\Z^2$, as stated in Theorems~1 and 3 of \cite{b71}. Using the notation of \cite{b71}, let $G=\Z^2$, let the set $A_n=\{1,\dots ,n^2\}\times\{1,\dots, n^3\}$, and let $\gamma$ be the counting measure. We can then conclude from \cite{b71} that as $n\rightarrow\infty$,
\begin{equation}\label{Sampling from the entire population, ergodic}
\frac{1}{n^5}\sum_{i=1}^{n^2}\sum_{j=1}^{n^3} (X_{i,j}\wedge N)\text{ converges a.s. and in } L^1.
\end{equation}

We next show that the limit in \eqref{Sampling from the entire population, ergodic} is $\E[X_{1,1}\wedge N]$. Consider two boxes $B_{i,j}$ and $B_{i',j'}$ where $j'>j+2M+1$. Applying Lemma \ref{Lemma: localization for sampling from the population} to the box $B_{i,j}$ with $T=j'-j$, there exists a constant $C_M$ which could vary from line to line, and a random variable $X$, measurable with respect to the $\sigma$-field generated by $\Pi_{\lambda}\cap (\R\times[j-2M-1,j])$ and $\L|_{\R\times[j-2M-1,j'-2M-1]}$, such that
$$
\P(X\neq X_{i,j})\le C_M  (j'-j)^{-1/3}\log^{3/2} (j'-j)\exp(\log^{5/6}(j'-j)).
$$
Then for any $N>0$, we have
$$
|\E[X\wedge N]-\E[X_{i,j}\wedge N]|\le C_M N (j'-j)^{-1/3}\log^{3/2} (j'-j)\exp(\log^{5/6}(j'-j)),
$$
and 
\begin{align*}
&|\E[(X\wedge N)(X_{i',j'}\wedge N)]-\E[(X_{i,j}\wedge N)(X_{i',j'}\wedge N)]|\\
&\qquad\le C_M N^2 (j'-j)^{-1/3}\log^{3/2}(j'-j)\exp(\log^{5/6}(j'-j)).
\end{align*}
Since $X_{i',j'}$ is measurable with respect to the $\sigma$-field generated by $\Pi_\lambda\cap (\R\times(j'-2M-1,j'])$ and $\L|_{\R\times(j'-2M-1,\infty)}$, by the independent increments property in Proposition \ref{Proposition: independent increment}, the random variables $X$ and $X_{i',j'}$ are independent. Therefore, $\Cov(X\wedge N,X_{i',j'}\wedge N)=0$, and it follows that
\begin{align*}
&|\Cov(X_{i,j}\wedge N,X_{i',j'}\wedge N)|\\
&\qquad=|\Cov((X_{i,j}\wedge N)-(X\wedge N),X_{i',j'}\wedge N)+\Cov(X\wedge N,X_{i',j'}\wedge N)|\\
&\qquad=|\Cov((X_{i,j}\wedge N)-(X\wedge N),X_{i',j'}\wedge N)|\\
&\qquad=\big|\E\big[((X_{i,j}\wedge N)-(X\wedge N))(X_{i',j'}\wedge N)\big]-\E\big[(X_{i,j}\wedge N)-(X\wedge N)\big]\E\big[X_{i',j'}\wedge N\big]\big|\\
&\qquad\le C_M N^2 (j'-j)^{-1/3}\log^{3/2} (j'-j)\exp(\log^{5/6}(j'-j)).
\end{align*}
For two boxes $B_{i,j}$ and $B_{i',j'}$ where $|j-j'|\le 2M+1$, we use the trivial bound
$$
|\Cov(X_{i,j}\wedge N,X_{i',j'}\wedge N)|\le N^2.
$$
Therefore,
\begin{align*}
\Var\left(\sum_{i=1}^{n^2}\sum_{j=1}^{n^3} \left(X_{i,j}\wedge N\right)\right)&= \sum_{1\le i,i'\le n^2}\sum_{1\le j,j'\le n^3} \Cov(X_{i,j}\wedge N,X_{i',j'}\wedge N)\\
&=\sum_{1\le i,i'\le n^2}\Bigg(\sum_{|j-j'|\le 2M+1} \Cov(X_{i,j}\wedge N,X_{i',j'}\wedge N)\\
&\qquad\qquad\qquad+\sum_{|j-j'|> 2M+1} \Cov(X_{i,j}\wedge N,X_{i',j'}\wedge N)\Bigg)\\
&\le Cn^4\left(Mn^3\cdot N^2+n^3\sum_{T=2M+2}^{n^3}C_M N^2 T^{-1/3}(\log^2 T) \exp(\log^{5/6}T)\right)\\
&\le C_M N^2 n^9 (\log^2 n)\exp(\log^{5/6}n^3).
\end{align*}
It follows that 
\begin{equation}\label{Sampling from the entire population, wlln}
\frac{1}{n^5}\sum_{i=1}^{n^2}\sum_{j=1}^{n^3} (X_{i,j}\wedge N)\rightarrow \E[X_{1,1}\wedge N]\qquad\text{in probability}.   
\end{equation}
Note that the definition of $X_{i,j}$ depends on $M$, so the right hand side depends on both $M$ and $N$. Combining \eqref{Sampling from the entire population, ergodic} with \eqref{Sampling from the entire population, wlln}, we get
$$
\frac{1}{n^5}\sum_{i=1}^{n^2}\sum_{j=1}^{n^3} (X_{i,j}\wedge N)\rightarrow \E[X_{1,1}\wedge N]\qquad\text{a.s. and in } L^1.
$$
Taking the supremum over $M$ and $N$, we have
\begin{align*}
\liminf_{n\rightarrow\infty}\frac{1}{n^5} l\big(Anc_k(\Pi_\lambda)\cap A_{n^5}\big)&\ge \sup_{M,N}\liminf_{n\rightarrow\infty}\frac{1}{n^5}\sum_{i=1}^{n^2}\sum_{j=1}^{n^3} (X_{i,j}\wedge N)\\
&=\sup_{M,N} \E[X_{1,1}\wedge N]\\
&=\E\big[l(Anc_k(\Pi_\lambda)\cap A_1)\big].
\end{align*}
Recall from Proposition \ref{Proposition: expectation} that $\E[l(Anc_k(\Pi_\lambda)\cap A_{n^5})]<\infty$. We apply Theorems 1 and 3 of \cite{b71} again to conclude that $l(Anc_k(\Pi_\lambda)\cap A_{n^5})/n^5$ converges a.s. and in $L^1$. It then follows from Lemma \ref{Lemma: probability fact} that
$$
\frac{l(Anc_k(\Pi_\lambda)\cap A_{n^5})}{n^5}\rightarrow \E[l(Anc_k(\Pi_{\lambda})\cap A_1)]\qquad\text{a.s. and in } L^1,
$$
which, together with equation \eqref{sfs1}, concludes the proof of \eqref{Sampling from the entire population, integer side length}.
\end{proof}

\subsection{Proof of Proposition \ref{Proposition: lln, points in the box}}\label{Subsection: robust1}

Now that we have proved Proposition \ref{Proposition: lln, points anywhere}, which gives a strong law of large numbers for $l(Anc_k(\Pi_{\lambda})\cap A_n)$, the next step is to show that we get a similar result, but with convergence in probability instead of almost sure convergence, when we sample in such a way that there are exactly $n$ points sampled from $A_n$.  
To prove this convergence, we first establish a result similar to Lemma \ref{Lemma: perturb the sampling intensity2}
which shows that $Anc_k(\Pi_\lambda)$ does not change much if we change the sampling intensity $\lambda$ by a small amount.

\begin{lemma}\label{Lemma: perturb the sampling intensity1}

Fix $\lambda> \eps>0$, and fix a positive integer $k$. Let $A$ be a measurable subset of $\R^2$. Let
$$
B=\bigcup_{1\le i\le k\le j, i\neq j} \left(Anc_{i}(\Pi_{\lambda-\eps})\cap Anc_{j}(\Pi_{\lambda+\eps})\right)
$$
be the pairs $(y,t)\in\R^2$ that are ancestral to at most $k$ points in $\Pi_{\lambda-\eps}$, at least $k$ points in $\Pi_{\lambda+\eps}$, and at least one point in $\Pi_{\lambda+\eps}\setminus\Pi_{\lambda-\eps}$. Then there exists a constant $C_{k,\lambda}$ depending on $k$ and $\lambda$ such that for all $\eps<\lambda/2$ and all measurable $A\subseteq\R^2$,
$$
\E[l(A\cap B)]\le C_{k,\lambda}m(A)\eps.
$$  
\end{lemma}
\begin{proof}
For each $i>0$, let
$$
B_i = Anc_{i}(\Pi_{\lambda-\eps}) \cap\{(y,t)\in\R^2: D_{(y,t)}\cap (\Pi_{\lambda+\eps}\setminus\Pi_{\lambda-\eps})\neq\emptyset\}
$$
be the pairs $(y,t)\in\R^2$ that are ancestral to $i$ points in $\Pi_{\lambda-\eps}$ and at least one point in $\Pi_{\lambda+\eps}\setminus\Pi_{\lambda-\eps}$.
Then, $B\subseteq \cup_{1\le i\le k} B_i$ by definition. Therefore,
\begin{align*}
\E[l(A\cap B)]\le \sum_{1\le i\le k} \E[l(A\cap B_i)]=\sum_{1\le i\le k} \int_{-\infty}^\infty \E\left[\#(A\cap B_i)^t\right]\ dt.
\end{align*}
Similar to the proof of Proposition \ref{Proposition: expectation}, we let $\phi(\cdot)$ be defined as in \eqref{Sampling from the population, density}. If $m(D_{(y,t)})=a$, then the probability that $(y,t)$ is ancestral to $i$ points in $\Pi_{\lambda-\eps}$ and at least one point in $\Pi_{\lambda+\eps}\setminus\Pi_{\lambda-\eps}$ is
$$
\frac{e^{-(\lambda-\eps)a}(\lambda-\eps)^i a^i }{i!}(1-e^{-2\eps a}).
$$
Therefore, using an argument similar to the ones used to prove \eqref{Sampling from the entire population, expectation} and \eqref{ElAB},
\begin{align}\label{perturb bound}
\E[l(A\cap B)]&\le\sum_{1\le i\le k} \int_{-\infty}^\infty 
\int_0^\infty \widetilde{m}(A^t)\phi(a) \cdot \frac{e^{-(\lambda-\eps)a}(\lambda-\eps)^i a^i }{i!}(1-e^{-2\eps a})\ da\ dt\nonumber\\
&\leq \sum_{1\le i\le k} \int_0^\infty 
\left(\int_{-\infty}^\infty   \widetilde{m}(A^t)\ dt\right) \cdot \frac{2C_2' a^{-7/5}}{5}\cdot \frac{e^{-(\lambda-\eps)a}(\lambda-\eps)^i a^i }{i!} \cdot 2 \eps a \ da\nonumber\\
&\le C_{k,\lambda}m(A)\eps
\end{align}
because the integral is finite for all $i$, which completes the proof.
\end{proof}

\begin{proof}[Proof of Proposition \ref{Proposition: lln, points in the box}]
Define $B$ as in the statement of Lemma \ref{Lemma: perturb the sampling intensity1}. For $n$ sufficiently large, we apply Lemma \ref{Lemma: perturb the sampling intensity1} with $\lambda=1$, $\eps_n=(\log n)/\sqrt{n}$ and $A_n=[0,n^{2/5}]\times[0,n^{3/5}]$ to get
$$
\E[l(A_n\cap B)]\le C_{k,\lambda}\sqrt{n}\log n.
$$
In particular, as $n\rightarrow\infty$, by Markov's inequality we have
$$
\frac{l(A_n\cap B)}{n}\rightarrow 0,\qquad\text{in probability}.
$$
Recall the definition of $\lambda_n^*$ from \eqref{lambda1}. Then, as $n\rightarrow\infty$,
\begin{equation}\label{Sampling from the population: Poisson deviation}
\P(\lambda_n^*\in [1-\eps_n,1+\eps_n])\ge \P(\#(\Pi_{1-\eps_n}\cap A_n)< n<\#(\Pi_{1+\eps_n}\cap A_n))\rightarrow1.    
\end{equation}
On the event $\lambda_n^*\in [1-\eps_n,1+\eps_n]$, we have
$$
Anc_k(\Pi_{1})\ \triangle\  Anc_k(\Pi_{\lambda_n^*})\subseteq B.
$$
It follows that as $n\rightarrow\infty$, 
\begin{equation}\label{pertubation1}
\frac{l\Big(\big(Anc_k(\Pi_{1})\ \triangle\ Anc_k(\Pi_{\lambda_n^*})\big)\cap A_n\Big)}{n}\rightarrow 0,\qquad\text{in probability}.
\end{equation}
The claim of the proposition then follows from \eqref{pertubation1} and Proposition \ref{Proposition: lln, points anywhere}.
\end{proof}

\subsection{Proof of Proposition \ref{Proposition: diff1}}\label{Subsection: diff1}

To complete the proof of Theorem \ref{Theorem: main1}, it remains only to prove Proposition \ref{Proposition: diff1}. Recall that $A_n=[0,n^{2/5}]\times[0,n^{3/5}]$. To prove Proposition \ref{Proposition: diff1}, we need to compare the sets $Anc_k(\Pi_{\lambda_n^*})\cap A_n$ and $Anc_k(\Pi_{\lambda_n^*}\cap A_n)$. Recall from Figure \ref{Figure: diff1} in the introduction that $Anc_k(\Pi_{\lambda_n^*})\cap A_n$ consists of points in $A_n$ that are ancestral to $k$ sampled points in $\R^2$, while $Anc_k(\Pi_{\lambda_n^*}\cap A_n)$ consists of points in $\R^2$ that are ancestral to $k$ sampled points in $A_n$. Typically, points that are ancestral to $k$ sampled points in $A_n$ will themselves be in $A_n$, and points in $A_n$ that are ancestral to $k$ sampled points will have their descendants contained in $A_n$. Therefore, these sets will be close with high probability. Nevertheless, some discrepancies will occur near the boundary of $A_n$. These discrepancies need to be bounded, which requires some rather technical arguments.

Suppose $(y,t)\in\R^2$ is in one of these sets but not the other. Then there are two possibilities. 
\begin{enumerate}
\item $(y,t)\notin A_n$, and $(y,t)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)$. That is $(y,t)$ is not in the box $A_n$ but ancestral to $k$ points in the box.
\item $(y,t)\in Anc_{j}(\Pi_{\lambda_n^*})\cap A_n$ for some $j\ge k$, and $D_{(y,t)}\cap A_n^c\neq\emptyset$. That is, $(y,t)$ is in the box $A_n$ and is ancestral to at least $k$ of the sample points, and some of its descendants go outside the box $A_n$.
\end{enumerate}
We refer the reader back to Figure \ref{Figure: diff1} for an illustration, where the thick portion of $T_1$ in the right plot corresponds to the first possibility above, and the thick portion of $T_1$ in the left plot corresponds to the second possibility above.
If we write, for $A\subseteq\R^2$,
$$
Anc_{\ge k}(A):=\bigcup_{j\ge k}Anc_j(A),\qquad \text{ for all } A\subseteq\R^2
$$
for the set of points $(y,t)$ that are ancestral to at least $k$ points in $A$, then the discussion above implies that
$$
(Anc_k(\Pi_{\lambda_n^*}) \cap A_n)\ \triangle\  Anc_k(\Pi_{\lambda_n^*}\cap A_n)\subseteq F_{k,n}\cup G_{k,n},
$$
where
$$
F_{k,n}:=Anc_k(\Pi_{\lambda_n^*}\cap A_n)\setminus A_n
$$
is the set described in case 1 above and 
$$
G_{k,n} := \{(y,t)\in Anc_{\ge k}(\Pi_{\lambda_n^*})\cap A_n: D_{(y,t)}\cap A_n^c\neq \emptyset\}
$$
is the set described in case 2 above. We claim that for all positive integers $k$, as $n\rightarrow\infty$, 
\begin{equation}\label{Sampling from the entire population: comparison1}
\frac{l(F_{k,n})}{n}\rightarrow 0,\qquad\text{in probability},   
\end{equation}
and
\begin{equation}\label{Sampling from the entire population: comparison2}
\frac{l(G_{k,n})}{n}\rightarrow0,\qquad\text{in probability}.
\end{equation}
Proposition \ref{Proposition: diff1} is an immediate consequence of \eqref{Sampling from the entire population: comparison1} and \eqref{Sampling from the entire population: comparison2}. We prove \eqref{Sampling from the entire population: comparison1} in Section \ref{Subsubsection: comparison1}, and \eqref{Sampling from the entire population: comparison2} in Section \ref{Subsubsection: comparison2}.

\subsubsection{Proof of \eqref{Sampling from the entire population: comparison1}}\label{Subsubsection: comparison1}

In this section, we prove \eqref{Sampling from the entire population: comparison1} using a first moment computation with truncation. Recall that $F_{k,n}$ is the set of points that are not in $A_n$ but are ancestral to $k$ points in $A_n$.

\begin{proof}[Proof of \eqref{Sampling from the entire population: comparison1}]
To bound $l(F_{k,n})$, we split the branches at time $T_n = n^{3/5}\log\log n$. We have
\begin{equation}\label{Sampling from the entire population, diff1, case1}
l(F_{k,n})=l\big(F_{k,n}\cap(\R\times[0,T_n])\big)+l\big(F_{k,n}\cap(\R\times(T_n,\infty))\big).
\end{equation}
The choice of $T_n$ is somewhat flexible here.  However, we need to choose $T_n \gg n^{3/5}$ to ensure that with high probability, all geodesics starting from the box $A_n$ have coalesced by time $T_n$, and we need $T_n$ to be sufficiently small that \eqref{Sampling from the entire population, branches outside the box} below holds.

For the first term on the right hand side of \eqref{Sampling from the entire population, diff1, case1}, we will show in Lemma \ref{Lemma:  branches outside the box} that
\begin{equation}\label{Sampling from the entire population, branches outside the box}
\E\Big[l\big(F_{k,n}\cap(\R\times[0,T_n])\big)\Big] = o(n).
\end{equation}
It will then follow from Markov's inequality that
$$
\frac{l\big(F_{k,n}\cap(\R\times[0,T_n])\big)}{n}\rightarrow0,\qquad\text{in probability.}
$$
For the second term on the right hand side of \eqref{Sampling from the entire population, diff1, case1}, note that for $n>k$, the set $F_{k,n}\cap(\R\times(T_n,\infty))$ is nonempty only if the geodesics starting from the box $A_n$ have not coalesced into one geodesic at time $T_n=n^{3/5}\log\log  n$. We claim that this event occurs with probability going to 0 and hence
$$
\lim_{n\rightarrow\infty}\P\big(F_{k,n}\cap(\R\times(T_n,\infty))\neq\emptyset\big)=0,
$$
which completes the proof of \eqref{Sampling from the entire population: comparison1}.

It remains to justify our claim that, with probability going to 1, all the geodesics starting from the box $A_n$ have coalesced into one geodesic at time $T_n$. Denote this event by $E_n$. Let $z_n=n^{2/5}\log\log\log n$. Let $E_{n,1}$ be the event that the geodesics $g_{(-z_n,0)}$ and $g_{(n^{2/5}+z_n,0)}$ coalesce by time $T_n$. Let $E_{n,2}$ be the event that 
$$
\sup_{u\in[0,n^{3/5}]}|g_{(-z_n,0)}(u)-(-z_n)|< z_n,\qquad \sup_{u\in[0,n^{3/5}]}|g_{(n^{2/5}+z,0)}(u)-(n^{2/5}+z_n)|< z_n.
$$
Note that if both events $E_{n,1}$ and $E_{n,2}$ occur, then the event $E_n$ occurs. See Figure \ref{Figure: box coalescence} for an illustration. Also, Theorem \ref{Theorem: transversal fluctuation} and Proposition \ref{Proposition: 2-disjoint} guarantee that both events $E_{n,1}$ and $E_{n,2}$ occur with probability going to 1, which completes the proof.
