It remains to prove \eqref{Sampling from the entire population, branches outside the box} in the following Lemma. The dominant contribution comes from the geodesics starting from sampled points in the box $A_n$ that are close to the top boundary of $A_n$.
\begin{lemma}\label{Lemma:  branches outside the box}
For any $T\ge n^{3/5}$, we have
\begin{align*}
&\E\Big[l\big(F_{k,n}\cap (\R\times[0,T])\big)\Big]\le \frac{CTn^{2/5}}{\log n}.
\end{align*}
In particular, for $T_n=n^{3/5}\log\log n$,
$$
\E\Big[l\big(F_{k,n}\cap(\R\times[0,T_n])\big)\Big]\le C(n\log\log n )/\log n = o(n).
$$
\end{lemma}
\begin{proof}
Any point in $F_{k,n}$ must lie on the infinite upward geodesics starting from $k$ of the points in $\Pi_{\lambda_n^*}\cap A_n$. Therefore, if we write $G_{(y,t)}=\{(g_{(y,t)}(u), t+u): u\ge0\}\subseteq\R^2$ for the graph of $g_{(y,t)}$, then we have
$$
F_{k,n}\cap (\R\times[0,T])=\bigcup_{(y,t)\in \Pi_{\lambda_n^*}\cap A_n}F_{k,n}\cap (\R\times[0,T])\cap G_{(y,t)}.
$$
Measuring the length and taking the conditional expectation given $\Pi=(\Pi_{\lambda})_{\lambda>0}$, we have
\begin{align*}
\E\Big[l\big(F_{k,n}\cap (\R\times[0,T])\big)\Big|\Pi\Big]\le \sum_{(y,t)\in \Pi_{\lambda_n^*}\cap A_n}\E\Big[l\big(F_{k,n}\cap (\R\times[0,T])\cap G_{(y,t)}\big)\Big|\Pi\Big].
\end{align*}
We split $A_n$ into three regions, as shown in Figure \ref{Figure: A_n split}. Sampled points in $A_{n,1}$ are likely to contribute to $F_{k,n}$ by having ancestral lines that go above the top of the box.  Similarly, ancestral lines of sampled points in $A_{n,2}$ are likely to contribute to $F_{k,n}$ by going beyond the side of the box.  Ancestral lines of sampled points in $A_{n,3}$ are unlikely to contribute to $F_{k,n}$.  As mentioned before the lemma, the dominant contribution comes from points sampled in $A_{n,1}$.
\begin{enumerate}
\item $A_{n,1}=\{(y,t)\in A_n: t>n^{3/5}-1/\log n\}$,
\item $A_{n,2}=\{(y,t)\in A_n\setminus A_{n,1}: y<3\log^3 n\text{ or } y> n^{2/5}-3\log^3 n\}$,
\item $A_{n,3} = A_n\setminus(A_{n,1}\cup A_{n,2})$.
\end{enumerate}
