By Proposition \ref{Proposition: 2-disjoint}, we have
$$
\P(E_1^c)\le C u^{-2/3}\log^3 n.
$$ 
By Theorem \ref{Theorem: transversal fluctuation}, we have
$$
\P(E_2^c)=\P(E_3^c)\le C_3  e^{-C_4\log^{11} n}.
$$
Using \eqref{An2 An3}, it follows that for $(y,t)\in A_{n,2}$,
\begin{align*}
&\E\Big[l\big(F_{k,n}\cap (\R\times[0,T])\cap G_{(y,t)}\big)\Big|\Pi\Big]\\
&\qquad\le\int_0^{T} \P\Big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\Big|\Pi\Big)\ du\\
&\qquad\le\frac{1}{\log n}+\int_{1/\log n}^T C u^{-2/3}\log^3 n+2C_3  e^{-C_4\log^{11} n}+\mathbbm{1}_{E_4^c}\ du\\
&\qquad\le CT^{1/3}\log^3 n+2C_3  Te^{-C_4\log ^{11}n}+T\mathbbm{1}_{E_4^c}.
\end{align*}
Let $p= (\log^2 n)/n$. Since
\begin{equation}\label{bin}
\P(E_4^c) = \sum_{i=0}^{k} {n\choose i} p^i (1-p)^{n-i}\le \sum_{i=0}^{k}  (np)^i (1-p)^{n-i}\le C e^{-\log^2 n} \log^{2k} n,
\end{equation}
summing over $(y,t)\in \Pi_{\lambda_n^*}\cap A_{n,2}$ and taking the unconditioned expectation gives
\begin{align}\label{Sampling from the entire population: B2}
&\E\left[\sum_{(y,t)\in \Pi_{\lambda_n^*}\cap A_{n,2}}l\big(F_{k,n}\cap (\R\times[0,T])\cap G_{(y,t)}\big)\right]\nonumber\\
&\qquad\qquad\le 6n^{3/5}\log^3 n\left(CT^{1/3}\log^3 n+CTe^{-\log^2 n} \log^{2k} n\right).
\end{align}

For $(y,t)\in A_{n,3}$, we write $r_1 = n^{3/5}-t$ for the distance from $(y,t)$ to the top boundary and $r_2=\min\{y, n^{2/5}-y\}$ for the distance to the left or right boundary. To bound $
\P(g_{(y,t)}(u)\in A_n^c|\Pi )$ for $t+u<n^{3/5}$, or, equivalently, for $u<r_1$, note that for such choice of $u$, the geodesic $g_{(y,t)}(\cdot)$ could only exit the box $A_n$ by hitting the left or right boundary of $A_n$. By Theorem \ref{Theorem: transversal fluctuation}, we have
\begin{equation}\label{An3 1}
\P(g_{(y,t)}(u)\in A_n^c|\Pi )\le C_3e^{-C_4 r_2^3/u^2},\qquad\text{ if } u<r_1.    
\end{equation}
To bound $\P(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)|\Pi)$, we use an argument similar to that for $(y,t)\in A_{n,2}$, except that this time, we consider three geodesics, including one on each side of $g_{(y,t)}$.  We will argue that as long as at least two of these three geodesics intersect by time $t + u$, the point $g_{(y,t)}(u)$ will be the ancestor of more than $k$ sampled points in $A_n$, and we will use Theorem~\ref{Theorem: 3-disjoint} to bound this probability.  To make this argument precise, let $E$ be the intersection of the following events and see Figure \ref{Figure: A_{n,3}} for an illustration.
\begin{enumerate}
\item $E_1$: The geodesic $g_{(y,t)}(\cdot)$ coalesces with either $g_{(y-3\log^3 n,t)}(\cdot)$ or $g_{(y+3\log^3 n, t)}(\cdot)$ by time $t+u$.
\item $E_2$: $\sup_{0\le v\le 1/\log n} |g_{(y,t)}(v)-y|< \log^3 n$.
\item $E_3$: $\sup_{0\le v\le 1/\log n} |g_{(y+3\log^3 n,t)}(v)-(y+3\log^3 n)|< \log^3 n$.
\item $E_4$: $\sup_{0\le v\le 1/\log n} |g_{(y-3\log^3 n,t)}(v)-(y-3\log^3 n)|< \log^3 n$.
\item $E_5$: $\#(\Pi_{\lambda_n^*}\cap([y+\log^3 n, y+2\log^3 n]\times[t,t+1/\log n]))\ge k+1$.
\item $E_6$: $\#(\Pi_{\lambda_n^*}\cap([y-2\log^3 n, y-\log^3 n]\times[t,t+1/\log n]))\ge  k+1$.
\end{enumerate}
