If the event $E$ occurs, then $g_{(y,t)}(u)$ is an ancestor of at least $k+1$ points in $\Pi_{\lambda_n^*}\cap A_n$, as illustrated in Figure \ref{Figure: A_{n,3}}. Therefore,
$$
\P\Big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\Big|\Pi\Big)\le \P(E^c|\Pi)
$$
Also, the events $E_1$, $E_2$, $E_3$ and $E_4$ are independent of $\Pi$ and the events $E_5$ and $E_6$ are determined by $\Pi$, and we have
\begin{equation}\label{An3 E}
\P\Big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\Big|\Pi\Big)\le \P(E_1^c)+\P(E_2^c)+\P(E_3^c)+\P(E_4^c)+\mathbbm{1}_{E_5^c}+\mathbbm{1}_{E_6^c}.  
\end{equation}
By a scaling argument using part 3 of Proposition \ref{Proposition: properties of the landscape}, we can apply Theorem \ref{Theorem: 3-disjoint} with $u/(\log ^{9/2} n)$ in place of $t$ to get
\begin{equation}\label{An3 E1}
\P(E_1^c)\le Cu^{-5/3}(\log^{15/2} n )(\log^{52} (u\vee 2)). 
\end{equation}
By Theorem \ref{Theorem: transversal fluctuation}, we have
\begin{equation}\label{An3 E234}
\P(E_2^c)=\P(E_3^c)=\P(E_4^c)\le C_3  e^{-C_4\log^{11} n}.
\end{equation}
The argument in \eqref{bin} gives 
\begin{equation}\label{An3 E56}
\P(E_5^c)=\P(E_6^c)\le C e^{-\log^2n}\log ^{2k}n.
\end{equation}
Combining \eqref{An3 E}, \eqref{An3 E1}, \eqref{An3 E234}, and \eqref{An3 E56}, we get
\begin{equation}\label{An3 2}
\P\Big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\Big)\le Cu^{-5/3}(\log^{15/2} n )(\log^{52} (u\vee 2))+C e^{-\log^2n}\log ^{2k}n.
\end{equation}
Using \eqref{An2 An3}, we have for $(y,t)\in A_{n,3}$,
\begin{align*}
&\E\Big[l\big(F_{k,n}\cap (\R\times[0,T])\cap G_{(y,t)}\big)\Big|\Pi\Big]\\
&\qquad\le \int_0^T\min\Big\{\P\big(g_{(y,t)}(u)\in A_n^c\big|\Pi\big),\ \P\big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\big|\Pi\big)\Big\}\ du\\
&\qquad\le\int_0^T \P\big(g_{(y,t)}(u)\in A_n^c\big|\Pi\big)\mathbbm{1}_{\{u\le r_1\wedge r_2^{3/2}/(\log n)\}}\ du\\
&\qquad\qquad+\int_0^T\P\big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\big|\Pi\big)\mathbbm{1}_{\{u> r_1\wedge r_2^{3/2}/(\log n)\}}\ du.
\end{align*}
Recall that $\Pi_{\lambda_n^*}\cap A_n$ has the same distribution as $U_n$. Therefore, if $(y,t)$ is picked uniformly at random from $\Pi_{\lambda_n^*}\cap A_n$ and conditioned to be in $A_{n,3}$, then the random variable $r_1$ is uniformly distributed over $[1/\log n, n^{3/5}]$ and $r_2$ is uniformly distributed over $[3\log^3 n,n^{2/5}/2]$. Taking the unconditioned expectation, we have
\begin{align}\label{An3 integral}
&\E\left[\sum_{(y,t)\in \Pi_{\lambda_n}^*\cap A_{n,3}}l\big(F_{k,n}\cap (\R\times[0,T])\cap  G_{(y,t)}\big)\right]\nonumber\\
&\qquad\le\int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2} \int_0^{r_1\wedge r_2^{3/2}/(\log n)} \P\big(g_{(y,t)}(u)\in A_n^c\big)\ du\ dr_2\ dr_1\nonumber\\
&\qquad\qquad+\int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2} \int_{r_1\wedge r_2^{3/2}/(\log n)}^T \P\big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\big)\ du\ dr_2\ dr_1.
\end{align}
We bound the first integral in \eqref{An3 integral} using \eqref{An3 1} and the second integral using \eqref{An3 2}. We have
\begin{align}\label{An3 integral1}
&\int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2} \int_0^{r_1\wedge r_2^{3/2}/(\log n)} \P\big(g_{(y,t)}(u)\in A_n^c\big)\ du\ dr_2\ dr_1\nonumber\\
&\qquad\le\int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2} \int_0^{r_1\wedge r_2^{3/2}/(\log n)}C_3e^{-C_4 r_2^3/u^2}\ du\ dr_2\ dr_1\nonumber\\
&\qquad\le \int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2}r_1 C_3e^{-C_4 \log ^2 n}\ dr_2\ dr_1\nonumber\\
&\qquad\le Cn^{8/5} e^{-C_4\log^2 n}.
\end{align}
Also,
\begin{align}\label{An3 integral2}
&\int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2} \int_{r_1\wedge r_2^{3/2}/(\log n)}^T \P\big(g_{(y,t)}(u)\in Anc_k(\Pi_{\lambda_n^*}\cap A_n)\big)\ du\ dr_2\ dr_1\nonumber\\
&\qquad\le \int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2} \int_{r_1\wedge r_2^{3/2}/(\log n)}^T \Big(Cu^{-5/3}(\log ^{15/2} n)(\log^{52}(u\vee 2))\nonumber\\
&\qquad\qquad +Ce^{-\log^2 n}\log^{2k} n\Big)\ du\ dr_2\ dr_1\nonumber\\
&\qquad\le C(\log ^{15/2} n)(\log^{52}T)\int_{1/\log n}^{n^{3/5}} \int_{3\log ^3 n}^{n^{2/5}/2}\Big( r_1^{-2/3}+r_2^{-1}(\log^{2/3}n)\Big)\ dr_2 \ dr_1\nonumber\\
&\qquad\qquad+CnTe^{-\log^2 n} \log^{2k}n\nonumber\\
&\qquad\le Cn^{3/5}(\log^{55/6}n)(\log^{52}T)+CnT e^{-\log^2 n}\log^{2k}n.
\end{align}
Combining \eqref{An3 integral}, \eqref{An3 integral1}, and \eqref{An3 integral2}, we get
\begin{align}\label{Sampling from the entire population: B3}
&\E\left[\sum_{(y,t)\in \Pi_{\lambda_n^*}\cap A_{n,3}}l\big(F_{k,n}\cap (\R\times[0,T])\cap G_{(y,t)}\big)\right]\nonumber\\
&\qquad\le C n^{3/5}(\log^{55/6} n)(\log ^{52}T)+CnT e^{-\log^2 n}\log^{2k} n.   
\end{align}
Note that if $n$ is sufficiently large and $T\ge n^{3/5}$, then the bound in \eqref{Sampling from the entire population: B1} dominates those in \eqref{Sampling from the entire population: B2}, and \eqref{Sampling from the entire population: B3}. Therefore, combining \eqref{Sampling from the entire population: B1}, \eqref{Sampling from the entire population: B2}, and \eqref{Sampling from the entire population: B3} gives the result.
\end{proof}

\subsubsection{Proof of (\ref{Sampling from the entire population: comparison2})}\label{Subsubsection: comparison2}

In this section, we prove \eqref{Sampling from the entire population: comparison2}. The idea is that if $(y,t)\in A_n$ is ancestral to points both in and outside of $A_n$, then $(y,t)$ should be close to the boundary of $A_n$. Therefore, the total length of the branches indicated on the left-hand side of \eqref{Sampling from the entire population: comparison2} will be small.

\begin{proof}[Proof of \eqref{Sampling from the entire population: comparison2}]
Let $\eps_n = (\log n)/\sqrt{n}$. Since $\P(\lambda_n^*\in[1-\eps_n,1+\eps_n])\rightarrow1$ by \eqref{Sampling from the population: Poisson deviation} as $n\rightarrow\infty$ and $Anc_{\ge k}(\Pi_{\lambda})\subseteq Anc_{\ge k}(\Pi_{\lambda'})$ whenever $\lambda<\lambda'$, it follows that as $n\rightarrow\infty$, 
$$
\P(Anc_{\ge k}(\Pi_{\lambda_n^*})\subseteq Anc_{\ge k}(\Pi_{1+\eps_n}))\rightarrow1.
$$
Therefore, we will consider the case where the sampling rate is deterministic. If $(y,t)\in A_n$  is ancestral to at least $k$ points in $\Pi_{1+\eps_n}$ and at least one point in $A_n^c$, then there are three possibilities: either $(y,t)$ is close to the boundary of $A_n$, $H(D_{(y,t)})$ is large, or $W(D_{(y,t)})$ is large. See Figure \ref{Figure An0} for an illustration. More precisely, recall the definitions of $\H_a$ and $\W_a$ from \eqref{Definition: height and width of descendants}. Let $A_{n,0}=[3n^{1/5},n^{2/5}-3n^{1/5}]\times[n^{1/5},n^{3/5}]$ be a subset of $A_n$. We have the following decomposition:
\begin{align}\label{Sampling from the entire population: decompose bubbles outside of the box}
&G_{k,n}\subseteq\Big(Anc_{\ge k}(\Pi_{\lambda})\cap (A_n\setminus A_{n,0})\Big)\cup \Big(Anc_{\ge k}(\Pi_{\lambda})\cap A_{n,0}\cap\H_{n^{1/5}}\Big)\nonumber\\
&\qquad\qquad\cup\Big(Anc_{\ge k}(\Pi_{\lambda})\cap A_{n,0}\cap\H_{n^{1/5}}^c\cap\W_{3n^{1/5}}\Big). 
\end{align}

