\end{figure}

For the first term on the right-hand side of \eqref{Sampling from the entire population: decompose bubbles outside of the box}, by \eqref{sfs1}, we have
\begin{equation}\label{Sampling from the entire population: bubbles near the boundary}
\E\Big[l\big(Anc_{\ge k}(\Pi_\lambda)\cap (A_n\setminus A_{n,0})\big)\Big]=\sum_{i=k}^{\infty} \left(\frac{2C_2'\lambda^{2/5}}{5}\cdot m(A_n\setminus A_{n,0}) \cdot\frac{\Gamma(i-2/5)}{i!}\right)\le C\lambda^{2/5}n^{4/5}.
\end{equation}
For the the second term on the right-hand side of \eqref{Sampling from the entire population: decompose bubbles outside of the box}, we will show in Lemma \ref{Lemma: tall bubbles}
that
\begin{equation}\label{Sampling from the entire population, tall bubbles}
\E\Big[l\big(Anc_{\ge k}(\Pi_\lambda)\cap A_{n,0}\cap\H_{n^{1/5}}\big)\Big]\le Cn^{13/15}.    
\end{equation}
For the the third term on the right-hand side of \eqref{Sampling from the entire population: decompose bubbles outside of the box}, we will show in Lemma \ref{Lemma: wide bubbles}
that if $E$ denotes the event that $Anc_{\ge k}(\Pi_\lambda)\cap A_{n,0}\cap\H_{n^{1/5}}^c\cap\W_{3n^{1/5}}$ is not empty, then
\begin{equation}\label{Sampling from the entire population, wide bubbles}
\P(E)\le C e^{-C' n^{1/5}}.
\end{equation}
Then \eqref{Sampling from the entire population: comparison2} follows from \eqref{Sampling from the entire population: decompose bubbles outside of the box}, \eqref{Sampling from the entire population: bubbles near the boundary}, \eqref{Sampling from the entire population, tall bubbles}, and \eqref{Sampling from the entire population, wide bubbles}.
\end{proof}

We now bound the second term on the right-hand side of \eqref{Sampling from the entire population: decompose bubbles outside of the box}.

\begin{lemma}\label{Lemma: tall bubbles}
Let $C_2''\in(0,\infty)$ be the constant in Remark \ref{Remark: scaling of H_a}. Then
$$
\E\Big[l\big(Anc_{\ge k}(\Pi_\lambda)\cap A_{n,0}\cap\H_{n^{1/5}}\big)\Big]\le C_2'' n^{13/15}.
$$
\end{lemma}
\begin{proof}
By Remark \ref{Remark: scaling of H_a}, for all $t\in\R$ and all measurable $\widetilde{A}\subseteq\R$, we have
$$
\E[\#(\H_{a}^t\cap \widetilde{A})] = C_2''\widetilde{m}(\widetilde{A})a^{-2/3}.
$$
Then, for any measurable $A\subseteq\R^2$, we have
$$
\E[l(\H_a \cap A)]=\int_{-\infty}^\infty \E[\#(\H_a \cap A)^t]\ dt =\int_{-\infty}^\infty C_2''\widetilde{m}(A^t)a^{-2/3}\ dt= C_2''m(A)a^{-2/3},
$$
and hence
$$
\E\Big[l\big(Anc_{\ge k}(\Pi_\lambda)\cap A_{n,0}\cap\H_{n^{1/5}}\big)\Big]\le \E\Big[l(\mathcal{H}_{n^{1/5}}\cap A_{n,0})\Big]\le n\cdot C_2''n^{-2/15}=C_2''n^{13/15},
$$
which completes the proof.
\end{proof}

We now bound the third term on the right-hand side of \eqref{Sampling from the entire population: decompose bubbles outside of the box}.

\begin{lemma}\label{Lemma: wide bubbles}
Let $E$ be the event that $Anc_{\ge k}(\Pi_\lambda)\cap A_{n,0}\cap\H_{n^{1/5}}^c\cap\W_{3n^{1/5}}$ is not empty. Then
$$
\P(E)\le C e^{-C' n^{1/5}}.
$$
\end{lemma}
\begin{proof}
Here we need to show that it is unlikely that there are any points with $k$ or more descendants whose set of descendants is both short and wide. We will argue that the existence of such a point would require geodesics to have unusually large transversal fluctuations. Consider the grid point $(i,j)$ for $i\in \mathcal{I}=\{0,n^{1/5},2n^{1/5},\dots, \lceil n^{1/5}\rceil n^{1/5}\}$ and $j\in\mathcal{J}=\{0,n^{1/5},2n^{1/5},\dots,\lceil n^{2/5}\rceil n^{1/5}\}$. For each $(i,j)$, let $E_{i,j}$ be the event that 
$$
\sup_{0\le u\le 2n^{1/5}} |g_{(i,j)}(u)-i|\ge \frac{1}{3}n^{1/5}.
$$
We claim that 
\begin{equation}\label{Sampling from the entire population, grid}
E\subseteq\bigcup_{i\in\mathcal{I},j\in\mathcal{J}} E_{i,j}.   
\end{equation}
If \eqref{Sampling from the entire population, grid} holds, then the result follows from Theorem \ref{Theorem: transversal fluctuation}.

We now prove \eqref{Sampling from the entire population, grid}. Suppose the event $E$ occurs. Let $(y_0,t_0)\in A_{n,0}$ be a point such that $H(D_{(y_0,t_0)})\le  n^{1/5}$ and $W(D_{(y_0,t_0)})> 3n^{1/5}$. Let $i_0:=\sup\{i\in\mathcal{I}: i+n^{1/5}/3\le y_0\}$, $i_1:=\inf\{i\in\mathcal{I}: i-n^{1/5}/3\ge y_0\}$
and $j_0:=\sup\{j\in\mathcal{J}: j+n^{1/5}\le t_0\}$. Note that since $(y_0,t_0)\in A_{n,0}$ is away from the boundary, the quantities $i_0$, $i_1$, and $j_0$ are well-defined and we have $i_1-i_0\le 2n^{1/5}$. Suppose that neither $E_{i_0,j_0}$ nor $E_{i_1,j_0}$ holds, that is
\begin{equation}\label{Sampling from the entire population, transversal fluctuation on the grid}
\sup_{0\le u\le 2n^{1/5}} |g_{(i_0,j_0)}(u)-i_0|< \frac{1}{3}n^{1/5},\qquad\sup_{0\le u\le 2n^{1/5}} |g_{(i_1,j_0)}(u)-i_1|<\frac{1}{3}n^{1/5}.
\end{equation}
The assumption $H(D_{(y_0,t_0)})\le n^{1/5}$ implies that $D_{(y_0,t_0)}\subseteq\R\times[j_0,t_0]$. Then, \eqref{Sampling from the entire population, transversal fluctuation on the grid} implies that
$$
W(D_{(y,t)})\le i_1-i_0+\frac{2}{3}n^{1/5}\le 3n^{1/5},
$$
which contradicts $W(D_{(y,t)})>3n^{1/5}$.
\end{proof}

\section{The three-arm event}\label{Section: 3-arm}

We finally arrive at the proof of the three-arm probability bound. 
For convenience let us restate an equivalent version of the statement of the theorem as also recorded in \eqref{scaled123}.
\newcommand{\e}{\varepsilon}

\begin{theorem}\label{threearm}
Consider the infinite upward geodesics $g_{(-\e,0)}$, $g_{(0,0)}$, and $g_{(\e,0)}$. Then there exists a constant $C\in(0,\infty)$ such that, for all $\e \le 1/2,$
\begin{equation}\label{threearm1}
\P(g_{(-\e,0)}, g_{(0,0)}, \text{ and } g_{(\e,0)} \text{ are disjoint for all } s\in[0,1])\le C\e^{5/2}\log^{52} (1/\eps).
\end{equation}
\end{theorem}

Continuing the discussion following \eqref{scaled123}, one can indeed predict that the exponent $5/2$ is the right one by reducing to events about the parabolic Airy line ensemble which is indeed how our proof will proceed. We now include a short review of the basics of the parabolic Airy LE that will be needed for our purpose and which will allow us to explain the source of the $5/2$ exponent. 

\newcommand{\cA}{\mathcal{P}}
\newcommand{\ocA}{\overline{\mathcal P}}

\subsection{The parabolic Airy line ensemble and its properties}  \label{ss:ale}

The parabolic Airy line ensemble (LE) $\cA=\{\cA_n\}_{n=1}^\infty$ is a family of random processes on $\R$ which are ordered, and was constructed in \cite{ch14}.
Some crucial properties are presented next. Define $\ocA_n(x):=\cA_n(x)+x^2$ for any $x\in \R$, $n\in \N$.
\begin{enumerate}
    \item Stationarity: $\ocA=\{\ocA_n\}_{n=1}^\infty$ is stationary with respect to horizontal shift.
   \item Ergodicity: $\ocA=\{\ocA_n\}_{n=1}^\infty$ is ergodic with respect to horizontal shift.
   \item Brownian Gibbs property: for any $m\le n\in \N$ and $x\le y$, let $S = \llbracket m,n\rrbracket \times [x, y]$.
 $\cA$, as a (random) function on $\N\times \R$, admits the following local Gibbs specification: the conditional distribution of the process $\cA|_S$ given $\cA|_{S^c}$ is just $n-m + 1$ Brownian bridges with variance parameter 2 connecting up the points $\cA_i(x)$ and $\cA_i(y)$, for $m\le i \le n$, conditioned on a global non-intersection, i.e., $\cA_i(z)>\cA_{i+1}(z)$ for any $1\vee (m-1) \le i \le n$ and $z\in [x,y]$.
\end{enumerate}


\newcommand{\boo}{\mathbf 0}
\newcommand{\cL}{\mathcal{L}}
\newcommand{\cB}{\mathcal{B}}

The first property is from its construction, and the second property is proved in \cite{cs14}. The third property is proved in \cite{ch14}.

The first line $\cA_1$ (of $\cA$) is the parabolic Airy$_2$ process on $\R$, and equals in law to the function $x\mapsto \cL(\boo;x,1)$, where we write $\boo = (0,0)$.
A particularly important property of the parabolic Airy LE is a strong form of local Brownianity that it admits which helps reduce estimating probabilities of several events to tractable Brownian computations. This has formed the basis of several recent advances. While a result of this form first appeared in \cite{chh19}, several strengthenings have followed. For our application we will use the following version recently obtained in \cite[Theorem 3.8]{d24w}. 

\begin{theorem}\label{duncan12} Fix $t\ge 1$ and $k, \ell \in \N$.  Fix $\mathbf{a} \in \R^{\ell}$ such that if $\ell \ge 2$, then $a_j+t < a_{j+1}$ for all $j \in \llbracket 1, \ell-1 \rrbracket.$ Define $U(\mathbf{a})=\bigcup_{j=1}^\ell(\llbracket 1,k \rrbracket \times (a_{j}, a_{j}+t))$. Then there exists a random sequence of continuous functions $\mathfrak{L}^{\mathbf{a}}=\mathfrak{L}^{t,k,\mathbf{a}}=\{\mathfrak{L}_{i}^{\mathbf{a}}: \mathbb{R} \to \mathbb{R}, i \in \N\}$ such that the following hold:
\begin{enumerate}
\item Almost surely, $\mathfrak{L}^{\mathbf{a}}_i(r)> \mathfrak{L}^{\mathbf{a}}_{i+1}(r)$ for all pairs $(i,r) \notin U(\mathbf{a}).$

\item The ensemble has the following Gibbs property: For any $m\in \N$ and $a<b$, consider the set $S=\llbracket 1,m \rrbracket \times [a,b].$ Then, conditional on the values of $\mathfrak{L}^{\mathbf{a}}_i(r)$ for $(i,r) \notin S$, the distribution of $\mathfrak{L}^{\mathbf{a}}_i(r)$ for $(i,r) \in S$ is given by $m$ independent Brownian bridges $B_1, B_2, \ldots, B_m$ with variance parameter 2 from $(a, \mathfrak{L}_i^{\mathbf{a}}(a))$ to $(b, \mathfrak{L}_i^{\mathbf{a}}(b))$ for $i \in \llbracket 1,m \rrbracket,$ conditioned on the event $B_i(r)> B_{i+1}(r)$ whenever $(i,r) \notin U(\mathbf{a}).$

\item We have $$\P(\mathfrak{L}_1^{\mathbf{a}}> \mathfrak{L}_2^{\mathbf{a}}> \ldots) \ge e^{-c_{k,\ell}^* t^3}$$ where $c_{k,\ell} > 0$ depends only on $k$ and $\ell$.  Also, conditional on the event $\{\mathfrak{L}_1^{\mathbf{a}}> \mathfrak{L}_2^{\mathbf{a}}> \ldots\},$ the ensemble $\mathfrak{L}^{\mathbf{a}}$ is equal in law to the parabolic Airy LE.
\end{enumerate}
\end{theorem}

In words, the above says that given a domain $U$, there is a line ensemble $\mathfrak{L}^{\mathbf{a}}$ for which the Gibbs property on $U$ simply involves Brownian bridges without the non-intersection constraints, hence making computations about events on $U$ simpler.  On the other hand, conditional on non-intersection everywhere (which happens with reasonably large probability) the line ensemble has the distribution of the parabolic Airy LE thus allowing one to transfer estimates to the latter.

\subsection{Geodesic watermelons}
A key object in our analysis will be geodesic watermelons. 
Informally, geodesic watermelons are disjoint optimizers, i.e., a $k$-geodesic watermelon is a collection of $k$ distinct paths whose cumulative energy is the maximum. Note that the $1$-watermelon is simply a geodesic. See \cite{dz24d} for formal definitions, and arguments showing their existence and uniqueness in the directed landscape. 

We will use the following key fact from \cite{dz24d} which is a consequence of the RSK correspondence.  To state it we introduce the notion of a Gelfand-Tsetlin pattern. 
For $k\in \N$ let $T_k = \{(i, j) \in \N^2: i + j \le k + 1\}$.
We say that $w \in \R^{T_k}$ is a $k$-level Gelfand-Tsetlin pattern if it satisfies the interlacing
inequalities $w_{i,j} \le w_{i+1,j} \le w_{i,j+1}$
for all $i+j \le k$, and let $GT_k$ be the space of $k$-level Gelfand-Tsetlin patterns. For $x \in \R^{k+1}_{\le},$
we let $GT_k(x)$ be the set of all $w\in GT_k$ such that $(w,x) \in GT_{k+1}$ where $(w,x)_{i,j} = w_{i-1,j}$
for $i \ge 2$ and $(w,x)_{1,j} = x_j$.

While the top line in the parabolic Airy LE traces out $\cL({\bf 0};x,1)$ (recall that $\bf0$ is used to denote $(0,0)$), the lower lines allow access to disjointness of geodesics via the following relation. 

\newcommand{\cS}{\mathcal{S}}

\begin{proposition}[\cite{dz24d}, Proposition 5.9]\label{GTprop}
The directed landscape $\cL$ and the parabolic Airy line ensemble $\cA$ can be coupled so that $\cA_1(x) = \cL(\boo;x,1)$ for all $x \in \R$ and the following holds.
For a vector $\mathbf{x}= (x_1, x_2, x_3)$ with $x_1 < x_2 < x_3$, denote by $$\gamma(\mathbf{x})=(\gamma_1(x_1),\ldots,\gamma_3 (x_3))$$ the geodesic watermelon from $\boo$ to $(\mathbf{x},1)$, whose existence is the one of the main results in \cite{dz24d}.  For brevity, write $\cL(\gamma(\mathbf{x})) = \| \gamma_1 \|_{\mathcal{L}} + \| \gamma_2 \|_{\mathcal{L}} + \| \gamma_3 \|_{\mathcal{L}}.$  Then 
\begin{equation}\label{GTpattern}
\cL(\gamma(\mathbf{x})) = \sum_{i=1}^3 \cL(\boo; x_i,0)-\inf_{ w\in GT_{2}(x) }\sum_{i=1}^2 \sum_{j=1}^{3-i} \big( \cA_i(w_{i,j}) - \cA_{i+1}(w_{i,j}) \big).
\end{equation}
\end{proposition}

Note that indeed the LHS is bounded above by the first term of the RHS (since the geodesic watermelons have energies bounded by that of the corresponding geodesics) and the second term quantifies the deficit. Further, each of the summands in the second term is strictly positive on account of the non-intersection property of $\cA.$  Note also that the infimum on the RHS can be expressed as
$$\inf_{\substack{x_1 < w_{11} < x_2 < w_{12} < x_3 \\ w_{11} < w_{21} < w_{12}}} \Big[\big(\mathcal{P}_1(w_{11}) - \mathcal{P}_2(w_{11})\big) + \big(\mathcal{P}_2(w_{21}) - \mathcal{P}_3(w_{21})\big) + \big(\mathcal{P}_1(w_{12}) - \mathcal{P}_2(w_{12})\big)\Big].$$


Now on the event that that there are disjoint geodesics from $\boo$ to $(\mathbf{x},1),$ the error term must be zero. This corresponds to exact touches between $\cA_i$ and $\cA_{i+1}$ at the locations $w_{i,j}.$ This is a zero probability event since $\cA$ is non-intersecting, but we will work with an approximate version of this event where instead of exactly touching, the curves will come close to each other. Further, note that while the above only considers finite geodesics going from $\boo$ to $(\mathbf{x},1)$, we are interested in the further constraint that $\gamma_1,\gamma_2, \gamma_3$ are initial segments of semi-infinite geodesics. We next see how to incorporate this constraint.  Recall the Busemann function $\cB(x,s)$ from \eqref{busemann1}, which should be thought of as a properly centered version of the distance to infinity, in the vertical direction.  For convenience, we will use a modified definition of the Busemann function in this section, with $\mathcal{L}(0,0;0,n)$ on the right-hand side of \eqref{busemann1} replaced by $\mathcal{L}(0,1;0,n)$; note that this change only adds a constant shift to the Busemann function.  When $s=1$, we will denote $\cB(x,1)$ by $\cB(x).$  We also denote $\cL(0,0;x,1)$ by $\mathcal{L}(x)$.
By Theorem \ref{Theorem: Brownian motion}, the condition that the components of $\gamma$
are initial segments of semi-infinite geodesics is equivalent to the condition that for all $i=1,2,3,$
\begin{equation}\label{argmax}
\cB(x_i)+\cL(x_i)=\max_{x\in \R} \big(\cB(x)+\cL(x) \big)
\end{equation}
and hence in particular,
\begin{equation}\label{argmax1}
\cB(x_1)+\cL(x_1)=\cB(x_2)+\cL(x_2)=\cB(x_3)+\cL(x_3).
\end{equation}
Importantly, $\cB$ is independent of $\cL(\cdot,0;\cdot,1)$ which allows one to decouple the events in \eqref{GTpattern} and \eqref{argmax}.
We are now in a position to explain the source of the exponent $5/2$ appearing in the statement of Theorem \ref{threearm}.

Note that for the error term in \eqref{GTpattern} to be zero each of the three non-negative terms must be zero. Further \eqref{argmax1} stipulates that $\cB(x_1)+\cL(x_1)-\cB(x_2)-\cL(x_2)$ and $\cB(x_2)+\cL(x_2)-\cB(x_3)-\cL(x_3)$ are zero. 
In our argument all of the zeros will be replaced by $\sqrt{\e}$ (for reasons that will be apparent shortly). Thus, our event $\ncg$ consists of five events which, ignoring a certain degree of correlation between them, all require two independent Brownian motions to come within $\sqrt \e$ of each other on a unit order interval along with certain non-intersection constraints. It will turn out that the probability of each of these events will be of the order $\sqrt{\e}$.  The points will also typically be well separated, implying that the correlation between them will be weak enough to yield the $\e^{5/2}$ bound. 

However, a formal argument must address situations where the points are close to each other, increasing the correlation between the events. Nonetheless, the contributions of such situations will turn out to be negligible, albeit proving which turns out to be somewhat complicated.  We now proceed to making the above reasoning precise.  

The first point we need to address is that in Theorem \ref{threearm}, the geodesics do not emanate from the same point but rather are spaced $\eps$ apart.  For convenience of writing, instead of starting from height $0$, we will instead consider the three infinite upward geodesics emanating from the points $(-\eps, \eps^{3/2})$, $(0, \eps^{3/2})$, and $(\eps, \eps^{3/2})$, i.e., their starting points are shifted upward by $\eps^{3/2}$.  Let us call them $\gamma_1,\gamma_2,\gamma_3.$  A simple scaling argument shows that it suffices to prove the upper bound in \eqref{threearm1} for the geodesics $\gamma_1,\gamma_2,\gamma_3$. Towards this, we will perform a, by now, standard surgery argument to tie them all to the point $(0,0)$ at the cost of losing the geodesic status but being a near geodesic. Such an argument had first appeared in \cite{h20}.   We define three relevant events below, the first of which will be pertinent for this surgery argument.

\begin{itemize}
\item There is a constant $C_6 > 0$ such that with probability greater than $1/2$ one can find three disjoint curves $\eta_1,\eta_2,\eta_3$  joining $(0,0)$ and $(-\e,\eps^{-3/2}), (0,\eps^{-3/2})$, and $(\e,\eps^{-3/2})$ respectively, all of whose lengths are between $[-C_6 \sqrt{\e}, C_6 \sqrt{\e}]$. This can be seen, for instance, by scaling space by $\eps^{-1}$ and time by $\eps^{-3/2}$ and appealing to \eqref{GTpattern} (see also \cite{h20} where a different argument ensuring this was employed). Let us call this event $\mathcal{S}_1.$  On $\mathcal{S}_1$, let the paths obtained by concatenating $\gamma_i$ and $\eta_i$ be denoted by $\pi_i.$
Thus the lengths of $\pi_i$ and $\gamma_i$ differ by no more than $C_6 \sqrt \e.$

\item Let $\mathcal{S}_2$ be the event that the intersections of the semi-infinite geodesics emanating from $(0,0)$, $(-\e,\eps^{3/2}), (0,\eps^{3/2})$, and $(\e,\eps^{3/2})$ with the line $y=1$ all lie in the interval\\ $[-\log^{1/2}(1/\eps), \log^{1/2}(1/\eps)].$  By Theorem \ref{Theorem: transversal fluctuation}, for sufficiently small $\eps$, we have $\P(\mathcal{S}_2)\ge 1-\e^{10}.$

\item Let $\cS_3$ be the event that for each $x \in [-\log^{1/2}(1/\eps), \log^{1/2}(1/\eps)]$ and $i\in \{-1,0,1\},$  we have
$$|\cL(0,0; x,1)-\cL(\e i, \eps^{3/2}; x,1)| \leq \sqrt{\e}\log^{3/2}(1/\eps).$$
It is possible to reduce the power of the logarithm, but this definition will be sufficient for our purposes.
\end{itemize}

\begin{lemma}
For sufficiently small $\eps$, we have $\P(\cS_3)\ge 1-\e^{10}.$
\end{lemma}

\begin{proof} 
By an application of Theorem \ref{Theorem: transversal fluctuation} for finite geodesics, all the geodesics $g_{(0,0; x,1)}$ with $|x|\le {\log^{1/2}(1/\eps)}$ intersect the line $y = \eps^{3/2}$ at points $z$ with absolute value no more than $\eps \log^{1/2}(1/\eps)$, with probability at least $1 - \frac{1}{3} \eps^{10}$.  By the triangle inequality,
$$|\cL(0,0; x,1)-\cL(\eps i, \eps^{3/2}; x,1)|\le |\cL(0,0; z,\eps^{3/2})|+|\cL(\eps i, \eps^{3/2}; x,1)-\cL(z,\eps^{3/2}; x,1)|.$$
To bound the first term on the RHS, note that by scaling, $\cL(0,0; z,\eps^{3/2})$ has the same law as $\sqrt{\eps} \cL(0,0; \eps^{-1} z, 1)$.  Theorem \ref{hold432} then establishes that when $\eps$ is sufficiently small, we have $\mathcal{L}(0, 0; \eps^{-1} z, 1) \leq 2 \log(1/\eps)$ with probability at least $\frac{1}{3} \eps^{10}$; indeed the random variable $R$ in Theorem \ref{hold432} has the property that $\P(R > \log^a(1/\eps))$ decays faster than any power of $\eps$ as $\eps \rightarrow 0$ as long as $a > 2/3$. 
The second term can be bounded by applying Theorem \ref{modcont} with $\tau = 0$ and $\xi = |\eps i - z|$.
\end{proof}

Armed with the above, we state the following proposition. 

\begin{proposition}\label{Airyprop}
Let $\mathcal{P}_1$, $\mathcal{P}_2$, and $\mathcal{P}_3$ denote the top three lines of the parabolic Airy line ensemble.  Let $(W(t), t \in \R)$ be two-sided Brownian motion with variance parameter 2, independent of the parabolic Airy line ensemble.  Let $T = \lfloor \log^{1/2}(1/\eps) + 2 \rfloor$.  Let $A$ be the event that there exist times $a$, $b$, and $c$ with $-\log^{1/2}(1/\eps) \leq a < b < c \leq \log^{1/2}(1/\eps)$ such that the following hold:
\begin{itemize}
\item We have $\mathcal{P}_1(a) - \mathcal{P}_2(a) < \eps$, $\mathcal{P}_1(c) - \mathcal{P}_2(c) < \eps$, and $\mathcal{P}_2(b) - \mathcal{P}_3(b) < \eps$.

\item Let $$m_1 = \max_{-T \leq t \leq a} (W(t) + \mathcal{P}_1(t)), \quad m_2 = \max_{a \leq t \leq c} (W(t) + \mathcal{P}_1(t)), \quad m_3 = \max_{c \leq t \leq T} (W(t) + \mathcal{P}_1(t)).$$  We have $|m_1 - m_2| < \eps$, $|m_1 - m_3| < \eps$, and $|m_2 - m_3| < \eps$.
\end{itemize}
Then there exists a constant $C > 0$ such that $\P(A) \leq C \eps^{5} \log^{44}(1/\eps)$ for sufficiently small $\eps$.
\end{proposition}

Theorem \ref{threearm} is therefore an immediate consequence of the following lemma and an elementary scaling argument.  Proposition \ref{Airyprop} and Lemma \ref{reduction} give a power of the logarithm of $44 + 5(3/2) = 51.5$, which we round up to 52 in Theorem \ref{threearm}, as we do not aim to optimize the exponent.

\begin{lemma}\label{reduction}
Let $A$ be the event defined in Proposition \ref{Airyprop}, when we put $4 \sqrt{\eps} \log^{3/2} (1/\eps)$ in place of $\eps$.
Let $\ncg$ be the event defined following the statement of Theorem \ref{threearm}, but with the geodesics starting from height $\eps^{3/2}$ instead of $0$.
Then for sufficiently small $\eps$, we have
$\P(\ncg) \leq 2 \P(A)+ 4\e^{10}$.
\end{lemma}

\begin{proof}
Recall the events $\cS_1$, $\cS_2$, and $\cS_3$, and note that $\ncg$ is independent of $\cS_1$ and that $x \mapsto \cL({\bf 0};x,1)$ has the same law as $\cA_1$.  Also, by Theorem \ref{Theorem: Brownian motion}, the process $x \mapsto \cB(x)$ is a two-sided Brownian motion with variance parameter 2, which is independent of the process $x \mapsto \cL({\bf 0};x)$.  Therefore, we can set $\cA_1(x) = \cL(\boo;x,1)$ and $W(x) = \cB(x)$.
We now claim that $\ncg\cap \cS_1\cap \cS_2\cap \cS_3 \subseteq A.$ That this immediately implies the lemma follows by observing that $\P(\ncg\cap \cS_1\cap \cS_2\cap \cS_3)\ge \frac{1}{2}\P(\ncg)-2\e^{10}$.

It remains to prove the above claim. 
Note that on $\cS_1\cap \cS_2\cap \cS_3\cap \ncg$, the portions of the paths $\pi_1,\pi_2,\pi_3$ up to height $1$ are disjoint paths originating from $(0,0)$ and ending at $(x_1, 1)$, $(x_2, 1)$, and $(x_3, 1)$.  The lengths of these disjoint paths differ from $\cL(0,0; x_i, 1)$ by at most $\sqrt{\e}\log^{3/2}(1/\eps)  + C_6 \sqrt{\eps}$.
By Proposition \ref{GTprop}, it follows that for sufficiently small $\eps$, there exist $x_1< w_{11}< x_2 < w_{12} < x_3$ and $w_{11}<w_{21}< w_{12}$ such that 
\begin{align}\label{neartouch1}
|\cA_1(w_{11})-\cA_2(w_{11})| \leq 4 \sqrt{\e}\log^{3/2}(1/\eps), \quad & |\cA_1(w_{12})-\cA_2(w_{12})|\leq 4 \sqrt{\e}\log^{3/2}(1/\eps), \\
\nonumber
|\cA_2(w_{21})-\cA_3(w_{21})| \leq &\,\,\, 4\sqrt{\e}\log^{3/2}(1/\eps).
\end{align}
Because on $\cS_{2}$, all of the $x_{i}$ have absolute value at most $\log^{1/2}(1/\e)$, we can therefore take $w_{11}=a, w_{12}=c$, and $w_{21}=b$ to see that the first condition in the definition of $A$ is satisfied.

It remains to check the second condition in the definition of $A$ by showing that approximate versions of \eqref{argmax} and \eqref{argmax1} hold.  For $x \in \R$, we write $\cL({\bf 0};x)$ in place of $\cL({\bf 0}; x,1)$.  Let $s=\argmax_{x} (\cB(x)+\cL({\bf 0}; x))$.  On $\cS_{2}$, $s$ has absolute value at most $\log^{1/2}(1/\e).$ Then for $i=1,2,3,$ we observe, using twice the definition of $\cS_3$, that
\begin{align*}
\cB(x_i) + \cL({\bf 0}; x_i) + \sqrt{\eps} \log^{3/2}(1/\eps) &\geq \cB(x_i) + \cL(\eps i, \eps^{3/2}; x_i, 1) \\
&\geq \cB(s) + \cL(\eps i, \eps^{3/2}; s, 1) \\
&\geq \cB(s) + \cL({\bf 0}; s) - \sqrt{\eps} \log^{3/2}(1/\eps).
\end{align*}
Therefore,
\begin{equation}\label{argmax2}
|\cB(x_i)+\cL({\bf 0}; x_i)-\cB(s)-\cL({\bf 0}; s)| \leq 2 \sqrt{\e}\log^{3/2}(1/\eps).
\end{equation}
That is, the maximum value of $\cB(x)+\cL({\bf 0}; x)$ is nearly attained at the points $x_1$, $x_2$, and $x_3$.  Recalling that $\mathcal{P}_1(x) = \cL({\bf 0}; x)$ and $W(x) = \cB(x)$,
it follows that the second condition in the definition of $A$ is satisfied, as the values of $m_1$, $m_2$, and $m_3$ in Proposition \ref{Airyprop} are all within $2 \sqrt{\e}\log^{3/2}(1/\eps)$ of the global maximum.
\end{proof}

\newcommand{\PP}{\mathbb{P}}
Thus it remains to prove Proposition \ref{Airyprop}.The argument has many pieces and the entirety of the remainder of the paper is devoted to this. 

\subsection{Proof of Proposition \ref{Airyprop}}

We begin by collecting several lemmas which will be useful in the proof.  The first lemma is a standard formula for the maximum of a Brownian bridge, which can be found, for example, on page 63 of \cite{borsal}.

\begin{lemma}\label{maxbridge}
Let $(B_s)_{0 \leq s \leq t}$ be a standard Brownian bridge going from $0$ to $z$ in time $t$.  For $y\geq \max\{0,z\}$, we have
$$\P \bigg( \sup_{0 \leq s \leq t} B_s \leq y \bigg) = 1 - \exp \bigg(- \frac{2y(y-z)}{t} \bigg) \leq \frac{2y(y-z)}{t}.$$
\end{lemma}

The second is an entropic repulsion estimate of a Brownian excursion. 
\begin{lemma}\label{onebridge}
Let $(X_t)_{0 \leq t \leq  1}$ be a standard Brownian bridge from $x_1$ to $x_2$, where $x_1 > 0$ and $x_2 > 0$.  Let $\delta \in (0, 1/2)$.  Then there exists a positive constant $C_7$, depending on $\delta$ but not on $x_1$ or $x_2$, such that for all $\eps > 0$ and all $t \in [\delta, 1 - \delta]$, we have $$\P(X_t < \eps, X_s > 0 \textup{ for all } s \in [0,1]) \leq C_7 \eps^3.$$
\end{lemma}

\begin{proof}
We have
\begin{equation}\label{condbridge}
\P(X_t < \eps, X_s > 0 \textup{ for all } s \in [0,1]) \leq \P(X_t < \eps \,|\, X_s > 0 \textup{ for all } s \in [0,1]).
\end{equation}
The Brownian bridge from $x_1$ to $x_2$ conditioned to stay positive is a three-dimensional Bessel bridge from $x_1$ to $x_2$.  The three-dimensional Bessel bridge from $0$ to $0$ is the same as a standard Brownian excursion $(B^{ex}_t)_{0 \leq t \leq 1}$.  Therefore using the monotonicity coming, for example, from the construction of the Bessel bridge in (0.22) of \cite{pitcsp}, we get that the probability on the right-hand side of \eqref{condbridge} is bounded above by $\P(B^{ex}_t < \eps)$.  It is well-known (see, for example, page 76 of \cite{itomckean}) that $B^{ex}_t$ has probability density function $$f_t(x) = \frac{2x^2}{\sqrt{2 \pi t^3(1-t^3)}} e^{-x^2/(2t(1-t))}, \qquad x > 0.$$
Integrating this formula over $x$ from $0$ to $\eps$, we get that $\P(B^{ex}_t > \eps) = O(\eps^3)$, which completes the proof.
\end{proof}

We now consider independent Brownian bridges conditioned not to intersect, which we call nonintersecting Brownian bridges.
The next lemma records various near touch events for nonintersecting Brownian bridge ensembles.

\begin{lemma}
Let $(X_t)_{0 \leq t \leq 1}$, $(Y_t)_{0 \leq t \leq 1}$, and $(Z_t)_{0 \leq t \leq 1}$ be nonintersecting standard Brownian bridges going from $x_1$ to $x_2$, from $y_1$ to $y_2$, and from $z_1$ to $z_2$ respectively. Suppose $x_1 > y_1 > z_1$ and $x_2 > y_2 > z_2$.  Let $\delta \in (0, 1/2)$.  Then there exist positive constants $C_8$ and $C_9$, depending only on $\delta$, such that for all $\eps > 0$ and all $t \in [\delta, 1 - \delta]$, we have
\begin{equation}\label{twoclose}
\P(X_t - Y_t < \eps) \leq C_8 \eps^{3}
\end{equation}
and
\begin{equation}\label{threeclose}
\P(X_t - Y_t < \eps, Y_t - Z_t < \eps) \leq C_9 \eps^8.
\end{equation}
\end{lemma}
While we will not require and hence not pursue lower bounds, the above bounds are in fact sharp.  

\begin{proof}
It was proved in Proposition 5.1 of \cite{ah23} that the gap processes in an ensemble of nonintersecting Brownian bridges are monotone in the endpoint gaps.  As a consequence, the probabilities in \eqref{twoclose} and \eqref{threeclose} are largest when $x_1 = y_1 = z_1 = x_2 = y_2 = z_2 = 0$, so it suffices to prove the bound in this case.  Then the process $(X_t, Y_t, Z_t)_{0 \leq t \leq 1}$ is known as the Brownian 3-watermelon, and the joint density of $(X_t, Y_t, Z_t)$ can be found using the formula of Karlin and McGregor \cite{km59}.  As noted, for example, in Remark 1.3 of \cite{LDA24}, the joint density is given by
$$f_t(x,y,z) = c_t (x-y)^2 (x-z)^2 (y-z)^2 \exp \bigg(- \frac{x^2 + y^2 + z^2}{2t(1-t)} \bigg) {\bf 1}_{\{x > y > z\}},$$
where $c_t$ is a constant depending on $t$.  Using that $x^2 + y^2 + z^2 \geq x^2$ and that, when $0 < x-y < \eps$ and $0 < y-z < \eps$, we have $(x-y)^2 (x-z)^2 (y-z)^2 \leq 4 \eps^6$, we get
\begin{align*}
\P(Y_t - X_t < \eps, Z_t - Y_t < \eps)
&= \int_{y - \eps}^y \int_{x - \eps}^x \int_{-\infty}^{\infty} f_t(x,y,z) \: dx \: dy \: dz \\
&\leq 4c_t \eps^6 \int_{y - \eps}^y \int_{x - \eps}^x \int_{-\infty}^{\infty} \exp \bigg(- \frac{x^2}{2t(1-t)} \bigg) \: dx \: dy \: dz \\
&= 4 c_t \eps^8 \int_{-\infty}^{\infty} \exp \bigg(- \frac{x^2}{2t(1-t)} \bigg) \: dx.
\end{align*}
Because the integral is finite, this expression is bounded above by $C_9 \eps^8$, proving \eqref{threeclose}.
Likewise,
\begin{align*}
\P(Y_t - X_t < \eps) &= \int_{-\infty}^y \int_{x - \eps}^x \int_{-\infty}^{\infty} c_t (x-y)^2 (x-z)^2 (y-z)^2 \exp \bigg(- \frac{x^2 + y^2 + z^2}{2t(1-t)} \bigg) \: dx \: dy \: dz.
\end{align*}
This is easily seen to be $O(\eps^3)$ because $(x - y)^2 \leq \eps^2$ and the middle integral is over an interval whose length is $\eps$.  The result \eqref{twoclose} follows.
\end{proof}

The next lemma is a H\"older regularity estimate for the top three lines of the parabolic Airy line ensemble, which follows from Theorem 1.5 of \cite{dv21a}. Note that the regularity of the top line was already quoted in Theorem \ref{modcont}.

\begin{lemma}\label{AiryHolder}
Let $(W(t), t \in \R)$ be a two-sided Brownian motion with variance parameter 2, and let $\mathcal{P}_1$, $\mathcal{P}_2$, and $\mathcal{P}_3$ denote the top three lines of the parabolic Airy line ensemble.  Let $T = \lfloor \log^{1/2}(1/\eps) + 2 \rfloor$.  There exists a constant $C_{10} > 0$ such that with probability at least $1 - \eps^{100}$, for all $s, t \in [-T, T]$ with $\eps^{100} \leq |t - s| \leq 1$, we have
$$\max\{|W(t) - W(s)|, |\mathcal{P}_1(t) - \mathcal{P}_1(s)|, |\mathcal{P}_2(t) - \mathcal{P}_2(s)|, |\mathcal{P}_3(t) - \mathcal{P}_3(s)|\} \leq C_{10} \log(1/\eps) \sqrt{|t - s|}.$$
\end{lemma}

\begin{proof}
Theorem 1.5 of \cite{dv21a} states that there are positive constants $c$ and $d$ such that for all positive integers $k$ and all $s, t \in [0,1]$, we have
$$|\mathcal{P}_k(s) - \mathcal{P}_k(t)| \leq R_k |t - s|^{1/2} \log^{1/2}\bigg( \frac{2}{|t-s|} \bigg),$$
where $R_k$ is a random constant satisfying $\P(R_k > m) \leq e^{ck - dm^2}$ for all $m > 0$.  
Therefore, by choosing $m = C' \log^{1/2}(1/\eps)$ for a sufficiently large constant $C'$, we see that there is a positive constant $C$ such that, with probability at least $1 - \eps^{101}$, for $k \in \{1, 2, 3\}$ and all $s,t \in [0,1]$ with $\eps^{100} \leq |t - s| \leq 1$,
we have
\begin{equation}\label{Pkdiff}
|\mathcal{P}_k(s) - \mathcal{P}_k(t)| \leq C |t - s|^{1/2} \log(1/\eps).
\end{equation}
Standard modulus of continuity estimates imply that this result also holds with Brownian motion $W$ in place of $\mathcal{P}_k$ (this is already noted in \cite{dv21a}).

As observed in \cite{dv21a}, we can extend this result beyond the interval $[0,1]$ by using the stationarity of $(\mathcal{P}_k(t) + t^2, t \in \R)$.  For $s, t \in [0,1]$, we have $|s^2 - t^2| \leq 2|t - s| \leq 2|t - s|^{1/2}$.  Therefore, the bound \eqref{Pkdiff} can be rewritten as
\begin{equation}\label{diff2}
|(\mathcal{P}_k(s) - s^2) - (\mathcal{P}_k(t) - t^2)| \leq C |t - s|^{1/2} \log(1/\eps).
\end{equation}
By considering overlapping time intervals of length 1 started at the half integers, we get that \eqref{diff2} holds with probability at least $1 - \eps^{100}$ for $k \in \{1, 2, 3\}$ and all $s, t \in [-T, T]$ with $\eps^{100} \leq |t - s| \leq 1$.  Now for $s, t \in [-T, T]$ with $\eps^{100} \leq |t - s| \leq 1$,
\begin{align*}
|\mathcal{P}_k(s) - \mathcal{P}_k(t)| &= |(\mathcal{P}_k(s) + s^2) - (\mathcal{P}_k(t) + t^2) + (t^2 - s^2)| \\
&\leq |(\mathcal{P}_k(s) + s^2) - (\mathcal{P}_k(t) + t^2)| + 2T |t - s| \\
&\leq C \log(1/\eps) \sqrt{|t - s|}.
\end{align*}
This inequality implies the result.
\end{proof}

Given the above inputs, we are now in a position to dive into the proof of Proposition \ref{Airyprop}.

\begin{proof}[Proof of Proposition \ref{Airyprop}]
We first observe that Lemma \ref{AiryHolder} allows us to restrict our attention to a finite mesh for the points $a$, $b$, and $c$.
Let $m = 2^h$, where $$h = \min\{k \in \Z: 2^{-k} \leq \eps^2 \log^{-3}(1/\eps)\}.$$  Note that $\frac{1}{2} \eps^2 \log^{-3}(1/\eps) < 1/m \leq \eps^2 \log^{-3}(1/\eps)$.
Let $L = \{i/m: -m(T-1) \leq i \leq m(T - 1)\}$ be the set consisting of the integer multiples of $1/m$ that are in the interval $[-(T-1), T-1]$.

Given $u, v, w \in L$ with $u < v < w$, we define the event
$$A_{u,v,w} = \{\mathcal{P}_1(u) - \mathcal{P}_2(u) < 2 \eps, \: \mathcal{P}_1(w) - \mathcal{P}_2(w) < 2 \eps, \: \mathcal{P}_2(v) - \mathcal{P}_3(v) < 2 \eps\}.$$
Also, let $$m_1^* = \max_{-T \leq t \leq u} (W(t) + \mathcal{P}_1(t)), \quad m_2^* = \max_{u \leq t \leq w} (W(t) + \mathcal{P}_1(t)), \quad m_3^* = \max_{w \leq t \leq T} (W(t) + \mathcal{P}_1(t)).$$  Then define the event $$B_{u,v,w} = \{|m^*_1 - m^*_2| < 2 \eps, |m^*_2 - m^*_3| < 2 \eps\}.$$
Recall the event $A$ defined in the statement of the proposition, and let $G$ be the event in Lemma~\ref{AiryHolder}.  It follows from Lemma \ref{AiryHolder} that if $A \cap G$ occurs, then we can find points $u$, $v$, and $w$ in $L$ that are sufficiently close to $a$, $b$, and $c$ respectively that as long as $\eps$ is small enough, the event $A_{u,v,w} \cap B_{u,v,w}$ must occur.  Therefore,
\begin{equation}\label{mainPA}
\P(A) \leq \P(G^c) + \sum_{\substack{u, v, w \in L \\ u < v < w}} \P(A_{u,v,w} \cap B_{u,v,w} \cap G).
\end{equation}
We will therefore bound $\P(A_{u,v,w} \cap B_{u,v,w} \cap G)$.  We will first bound $\P(A_{u,v,w})$ and then essentially bound  $\P(B_{u,v,w}\cap G\mid A_{u,v,w})$. The former task involves considering three cases involving the separation of $u,v,$ and $w$.

\medskip
\noindent {\bf Case 1}:  Suppose $v - u > 2$ and $w - v > 2$.  Let $a_1 = u - 1/2$, $a_2 = v - 1/2$, and $a_3 = w - 1/2$.  We can then apply Theorem \ref{duncan12} with $t = 1$, $k = \ell = 3$, and ${\bf a} = (a_1, a_2, a_3)$.  
Letting $\mathfrak{L}^{\bf a}$ be the ensemble defined in Theorem \ref{duncan12}, we get
\begin{align*}
&\P(A_{u,v,w}) \\
&\quad = \P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps \,|\, \mathfrak{L}^{\bf a}_1 > \mathfrak{L}^{\bf a}_2 > \dots) \\
&\quad \leq e^{c_{3,3}^*}  \P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps , \mathfrak{L}^{\bf a}_1 > \mathfrak{L}^{\bf a}_2 > \dots).
\end{align*}
Let $\mathcal{G}$ be the $\sigma$-field generated by the values of $\mathfrak{L}^{\bf a}$ outside $U({\bf a})$.
It follows from the Gibbs property stated in Theorem \ref{duncan12} with $m = 3$ that conditional on $\mathcal{G}$, the processes $\mathfrak{L}^{\bf a}_1$, $\mathfrak{L}^{\bf a}_2$, $\mathfrak{L}^{\bf a}_3$ in the intervals $(a_j, a_j + 1)$ for $j = 1, 2, 3$ are independent Brownian bridges.
Let $D_1$ be the event that $\mathfrak{L}^{\bf a}_1(s) > \mathfrak{L}^{\bf a}_2(s)$ for all $s \in (a_1, a_1 + 1)$.  Let $D_2$ be the event that $\mathfrak{L}^{\bf a}_2(s) > \mathfrak{L}^{\bf a}_3(s)$ for all $s \in (a_2, a_2 + 1)$, and let $D_3$ be the event that $\mathfrak{L}^{\bf a}_1(s) > \mathfrak{L}^{\bf a}_2(s)$ for all $s \in (a_3, a_3 + 1)$.  Then
{\begin{align*}
&\P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps , \mathfrak{L}^{\bf a}_1 > \mathfrak{L}^{\bf a}_2 > \dots | \mathcal{G}) \\
&\quad \leq \P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, D_1 | \mathcal{G}) \P(\mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, D_2 | \mathcal{G}) \P( \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, D_3 | \mathcal{G}).
\end{align*}}
Because the difference between two Brownian bridges is a Brownian bridge with twice the variance parameter, we can apply Lemma \ref{onebridge} with $\mathfrak{L}^{\bf a}_1 - \mathfrak{L}^{\bf a}_2$ or $\mathfrak{L}^{\bf a}_2 - \mathfrak{L}^{\bf a}_3$ in place of $X$ to get that each of the three probabilities on the right-hand side is $O(\eps^3)$.  
It follows that
\begin{equation}\label{case1}
\P(A_{u,v,w}) = O(\eps^9).
\end{equation}

\medskip
\noindent {\bf Case 2}:  Suppose either $v - u > 4$ and $w - v \leq 2$, or $v - u \leq 2$ and $w - v > 4$.  Because these two possibilities can be handled in the same way, it is enough to consider $v - u > 4$ and $w - v \leq 2$.  This time, instead of considering three intervals, we will consider the two intervals $(u - 5/2, u + 1/2)$ and $(v - 1/2, v + 5/2)$.  Note that $v + 5/2 \geq w + 1/2$ and $(v - 1/2) - (u + 1/2) > 3$.  Therefore, we can apply Theorem \ref{duncan12} with $\ell = 2$, $a_1 = u - 5/2$, $a_2 = v - 1/2$, and $t = 3$.  As in the previous case, let $\mathfrak{L}^{\bf a}$ be the ensemble defined in Theorem \ref{duncan12}, and let $\mathcal{G}$ be the $\sigma$-field generated by the values of $\mathfrak{L}^{\bf a}$ outside $U({\bf a})$. Similarly, let $D_1$ be the event that $\mathfrak{L}_1^{\bf a}(r) > \mathfrak{L}_2^{\bf a}(r)$ for all $r \in (a_1, a_1 + 3)$, and let $D_2$ be the event that $\mathfrak{L}_1^{\bf a}(r) > \mathfrak{L}_2^{\bf a}(r) > \mathfrak{L}^{\bf a}_3(r)$ for all $r \in (a_2, a_2 + 3)$.  Also, let $G_2$ be the event that $|\mathfrak{L}^{\bf a}_i(t) - \mathfrak{L}_i^{\bf a}(s)| \leq C_{10} \log(1/\eps) \sqrt{|t - s|}$ whenever $i \in \{1, 2, 3\}$ and $s,t \in [a_2, a_2 + 3]$ with $\eps^{100} \leq |t - s| \leq 1$.  Reasoning as in Case 1, we can apply Theorem \ref{duncan12} to get
\begin{align} \label{AuvwG}
&\P(A_{u,v,w} \cap G) \nonumber \\
&\: \leq C \P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, \mathfrak{L}^{\bf a}_1 > \mathfrak{L}^{\bf a}_2 > \dots, G_2).
\end{align}
Also,
\begin{align} \label{case2cond}
&\P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, \mathfrak{L}^{\bf a}_1 > \mathfrak{L}^{\bf a}_2 > \dots, G_2|\mathcal{G}) \nonumber \\
&\: \: \leq \P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, D_1|\mathcal{G}) \P(\mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, D_2 \cap G_2|\mathcal{G}).
\end{align}
Applying Lemma \ref{onebridge} and following the argument used for Case 1, we get
\begin{equation}\label{firstprob}
\P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, D_1|\mathcal{G}) = O(\eps^3).
\end{equation}

It remains to bound $\P(\mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, D_2 \cap G_2|\mathcal{G})$.  It follows from Theorem \ref{duncan12} that conditional on $\mathcal{G}$, the processes $\mathfrak{L}^{\bf a}_1$, $\mathfrak{L}^{\bf a}_2$, and $\mathfrak{L}^{\bf a}_3$ over the interval $[a_2, a_2 + 3]$ are independent Brownian bridges.  Note that $D_2$ is the event that these bridges do not intersect.  Therefore, if we let $X$, $Y$, and $Z$ be nonintersecting independent Brownian bridges on the time interval $[a_2, a_2 + 3]$ with the same endpoints as $\mathfrak{L}^{\bf a}_1$, $\mathfrak{L}^{\bf a}_2$, and $\mathfrak{L}^{\bf a}_3$, and if $G_2^*$ is defined in the same way as $G_2$ but with $X$, $Y$, and $Z$ in place of $\mathfrak{L}^{\bf a}_1$, $\mathfrak{L}^{\bf a}_2$, and $\mathfrak{L}^{\bf a}_3$, then
\begin{align}\label{LXYZbound}
&\P(\mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, D_2 \cap G_2|\mathcal{G}) \nonumber \\
&\qquad \qquad \qquad \qquad \qquad \leq \P(X_w - Y_w < 2 \eps, Y_v - Z_v < 2 \eps, G_2^*).
\end{align}
We will therefore work with these nonintersecting Brownian bridges. The analysis proceeds by zooming in on an appropriate scale to probe the behaviors near $v$ and $w.$
Let $\ell$ be the nonnegative integer such that $2^{-\ell} < w - v \leq 2^{-(\ell - 1)}$.  Define the times $$s_1 = v - \frac{2^{-\ell}}{4}, \quad s_2 = \frac{v+w}{2}, \quad s_3 = w + \frac{2^{-\ell}}{4}.$$
Note that $a_2 < s_1 < v < s_2 < w < s_3 < a_2 + 3$.  Also, $s_1 - a_2 \geq 1/4$ and $(a_2 + 3) - s_3 \geq 1/4$.  Let $E_1$ be the event that $X_{s_1} - Y_{s_1} \leq 2^{-\ell/2} \log^2(1/\eps)$ and $Y_{s_1} - Z_{s_1} \leq 2^{-\ell/2} \log^2(1/\eps)$.  If the events $X_w - Y_w < 2 \eps$, $Y_v - Z_v < 2 \eps$, and $G_2^*$ all occur, then by the regularity imposed by the latter, $X_{s_1} - Y_{s_1}$ and $Y_{s_1} - Z_{s_1}$ are both bounded above by $2 \eps + 3 C_{10} 2^{-\ell/2} \log(1/\eps)$.  Because $2^{-(\ell - 1)} \geq \frac{1}{2} \eps^2 \log^{-3}(1/\eps)$, it follows that for sufficiently small $\eps$, the event $E_1$ must occur.
By \eqref{threeclose},
\begin{equation}\label{E1G}
\P(E_1|\mathcal{G}) = O(2^{-4 \ell} \log^{16}(1/\eps)).
\end{equation} 
Let $\mathcal{J}$ be the $\sigma$-field generated by $\mathcal{G}$ and by the values $X_{s_i}$, $Y_{s_i}$, and $Z_{s_i}$ for $i \in \{1, 2, 3\}$.  Note that $E_1 \in \mathcal{J}$.  
Let $E_2$ be the event that $X_w - Y_w < 2 \eps$ and $Y_v - Z_v < 2 \eps$.
We have $s_2 - s_1 = s_3 - s_2 = (w - v) + \frac{1}{2} 2^{-\ell} \in (\frac{3}{2} 2^{-\ell}, \frac{5}{2} 2^{-\ell}]$.  Therefore, we can use Brownian scaling to scale the time intervals $[s_1, s_2]$ and $[s_2, s_3]$ to $[0,1]$ and then apply \eqref{twoclose} twice, one for each interval, with $2 \eps (s_2 - s_1)^{-1/2}$ in place of $\eps$, to get
\begin{equation}\label{E2H}
\P(E_2|\mathcal{J}) = O(\eps^6 2^{3 \ell}).
\end{equation}
It follows from \eqref{E1G} and \eqref{E2H} that $\P(X_w - Y_w < 2 \eps, Y_v - Z_v < 2 \eps, G_2^*) = O(\eps^6 2^{-\ell} \log^{16}(1/\eps))$.
Because this bound does not depend on the endpoints of the Brownian bridges, combining this result with \eqref{LXYZbound} yields
\begin{equation}\label{secondprob}
\P(\mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, D_2 \cap G_2|\mathcal{G}) = O(\eps^6 2^{-\ell} \log^{16}(1/\eps)).
\end{equation}
Combining \eqref{AuvwG}, \eqref{case2cond}, \eqref{firstprob}, and \eqref{secondprob}, we get
\begin{equation}\label{case2}
\P(A_{u,v,w} \cap G) = O(\eps^9 2^{-\ell} \log^{16}(1/\eps)).
\end{equation}

\medskip
\noindent {\bf Case 3}:  Suppose $v - u \leq 4$ and $w - v \leq 4$.  We apply Theorem \ref{duncan12} with $\ell = 1$, $a_1 = u - 2$, and $t = 12$.  Let $\mathfrak{L}^{\bf a}$ be the ensemble defined in Theorem \ref{duncan12}.  Let $D$ be the event that $\mathfrak{L}_1^{\bf a}(r) > \mathfrak{L}_2^{\bf a}(r) > \mathfrak{L}^{\bf a}_3(r)$ for all $r \in [a_1, a_1 + 12]$.  Also, let $G_3$ be the event that $|\mathfrak{L}^{\bf a}_i(t) - \mathfrak{L}_i^{\bf a}(s)| \leq C_{10} \log(1/\eps) \sqrt{|t - s|}$ whenever $i \in \{1, 2, 3\}$ and $s,t \in (a_1, a_1 + 12)$ with $\eps^{100} \leq |t - s| \leq 1$.  Theorem \ref{duncan12} implies that
\begin{align*}
\P(A_{u,v,w} \cap G) \leq C \P(\mathfrak{L}^{\bf a}_1(u) - \mathfrak{L}^{\bf a}_2(u) < 2 \eps, \mathfrak{L}^{\bf a}_1(w) - \mathfrak{L}^{\bf a}_2(w) < 2 \eps, \mathfrak{L}^{\bf a}_2(v) - \mathfrak{L}^{\bf a}_3(v) < 2 \eps, D \cap G_3).
\end{align*}
It follows from Theorem \ref{duncan12} that conditional on $\mathcal{G}$, the processes $\mathfrak{L}^{\bf a}_1$, $\mathfrak{L}^{\bf a}_2$, and $\mathfrak{L}^{\bf a}_3$ over the interval $[a_1, a_1 + 12]$ are independent Brownian bridges. 
As in Case 2, we will consider nonintersecting Brownian bridges $X$, $Y$, and $Z$ on the interval $[a_1, a_1 + 12]$ with arbitrary endpoints.  Define $G_3^*$ the same way as $G_3$ but with $X$, $Y$, and $Z$ in place of $\mathfrak{L}^{\bf a}_1$, $\mathfrak{L}^{\bf a}_2$, and $\mathfrak{L}^{\bf a}_3$.  Then
\begin{equation}\label{main3bound}
\P(A_{u,v,w} \cap G) \leq C \P(X_u - Y_u < 2 \eps, X_w - Y_w < 2 \eps, Y_v - Z_v < 2 \eps, G_3^*).
\end{equation}
We again do a scale decomposition.
Let $k$ be the integer such that $2^{-k} < w - u \leq 2^{-(k-1)}$, and let $\ell$ be the integer such that $2^{-\ell} < v - u \leq 2^{-(\ell - 1)}$.  Note that $k \geq -1$ and $\ell \geq -1$.  We may assume without loss of generality that $v - u \leq \frac{1}{2}(w - u)$, which implies that $\ell > k$.  We now define the following times:
$$t_1=u-\frac{2^{-k}}{2}, \quad t_2=w- \frac{2^{-k}}{4}, \quad t_3=w+\frac{2^{-k}}{2}, \quad t_4=u- \frac{2^{-\ell}}{2}, \quad t_5 = \frac{u+v}{2}, \quad t_6=v+\frac{2^{-\ell}}{2}.$$
Note that $t_1 < t_4 < u < t_5 < v < t_6 < t_2 < w < t_3$.  Also, the points $t_1 < u < t_2 < w < t_3$ all fit within an interval of length at most $3 \cdot 2^{-k}$.  Likewise, the points $t_4 < u < t_5 < v < t_6$ all fit within an interval of length at most $3 \cdot 2^{-\ell}$.  We will use these times to study the process on two different time scales.  See the figure below.

