We now define four new events.
\begin{itemize}
\item Let $A_1$ be the event that $X_{t_2} - Y_{t_2} \leq 2^{-k/2} \log^2(1/\eps)$ and $Y_{t_2} - Z_{t_2} \leq 2^{-k/2} \log^2(1/\eps)$.
For sufficiently small $\eps$, if $G_3^*$ occurs and if both $X_u - Y_u$ and $Y_v - Z_v$ are less than $2 \eps$, then the regularity imposed by $G_3^*$ ensures that the closeness of the curves must be felt at $t_2$ as well and therefore the event $A_1$ must occur. 

\item Let $A_2$ be the event that $X_w - Y_w < 2 \eps$.

\item Let $A_3$ be the event that $X_{t_4} - Y_{t_4} \leq 2^{-\ell/2} \log^2(1/\eps)$ and $Y_{t_4} - Z_{t_4} \leq 2^{-\ell/2} \log^2(1/\eps)$.  Note that for sufficiently small $\eps$, if $G$ occurs and if both $X_u - Y_u$ and $Y_v - Z_v$ are less than $2 \eps$, then $A_3$ must occur. 

\item Let $A_4$ be the event that $X_u - Y_u < 2 \eps$ and $Y_v - Z_v < 2 \eps$.
\end{itemize}
This discussion implies that the event on the right-hand side of \eqref{main3bound} whose probability we need to bound is contained in
$A_1 \cap A_2 \cap A_3 \cap A_4$.

Let $\mathcal{G}$ be the $\sigma$-field generated by the values of $\mathfrak{L}^{\bf a}$ outside $U({\bf a})$.  We first bound $P(A_1|\mathcal{G})$.  We can scale the time interval $[a_1, a_1 + 12]$ to $[0,1]$ using Brownian scaling and apply \eqref{threeclose} with $\frac{1}{\sqrt{12}} 2^{-k/2} \log^2(1/\eps)$ in place of $\eps$ to get
\begin{equation}\label{PA1}
\P(A_1) = O(2^{-4k} \log^{16}(1/\eps)).
\end{equation}

Let $\mathcal{F}_1$ be the $\sigma$-field generated by $\mathcal{G}$ and by $X_{t_2}$, $Y_{t_2}$, $Z_{t_2}$, $X_{t_3}$, $Y_{t_3}$, and $Z_{t_3}$.  Conditional on $\mathcal{F}_1$, the processes $X$, $Y$, and $Z$ between times $t_2$ and $t_3$ are nonintersecting Brownian bridges.  
We have $t_3 - t_2 = \frac{3}{4} 2^{-k}$.  Also, $w - t_2 = \frac{1}{4} 2^{-k}$ and $t_3 - w = \frac{1}{2}2^{-k}$.  Therefore, we can use Brownian scaling to scale the time interval $[t_2, t_3]$ to $[0,1]$, and then apply \eqref{twoclose} with $2 \eps (t_3 - t_2)^{-1/2}$ in place of $\eps$ to get
\begin{equation}\label{PA2}
\P(A_2|\mathcal{F}_1) = O(2^{3k/2} \eps^3).
\end{equation}

Analogous to above, let $\mathcal{F}_2$ be the $\sigma$-field generated by $\mathcal{F}_1$, $X_{t_1}$, $Y_{t_1}$, $Z_{t_1}$, $X_w$, $Y_w$, and $Z_w$.
Conditional on $\mathcal{F}_2$, the processes $X$, $Y$, and $Z$ between times $t_1$ and $t_2$ are nonintersecting Brownian bridges. 
We have $\frac{5}{4} 2^{-k} \leq t_2 - t_1 \leq \frac{9}{4} 2^{-k}$.  Also, $t_4 - t_1 \geq \frac{1}{4} 2^{-k}$ because $\ell > k$, and $t_2 - t_4 \geq \frac{3}{4}2^{-k}$.  Therefore, we can use Brownian scaling to scale the time interval $[t_1, t_2]$ to $[0,1]$, and then we can apply \eqref{threeclose} with $2^{-\ell/2} \log^2(1/\eps) (t_2 - t_1)^{-1/2}$ in place of $\eps$ to get
\begin{equation}\label{PA3}
\P(A_3|\mathcal{F}_2) = O(2^{4k-4\ell} \log^{16}(1/\eps)).
\end{equation}

Let $\mathcal{F}_3$ be the $\sigma$-field generated by $\mathcal{F}_2$ and by $X_{t_i}$, $Y_{t_i}$, and $Z_{t_i}$ for $i \in \{4, 5, 6\}$.
Conditional on $\mathcal{F}_3$, the processes $X$, $Y$, and $Z$ between times $t_4$ and $t_5$, and between times $t_5$ and $t_6$, are independent Brownian bridges.  
We have $2^{-\ell} \leq t_5 - t_4 = t_6 - t_5 \leq \frac{3}{2} 2^{-\ell}$.  Also, $u$ and $v$ are at least a distance $\frac{1}{2} 2^{-\ell}$ from the points $t_4$, $t_5$, and $t_6$.  Therefore, we can use Brownian scaling to scale the time intervals $[t_4, t_5]$ and $[t_5, t_6]$ to $[0,1]$, and then we can apply \eqref{twoclose} twice, once for each interval, with $2 \eps (t_5 - t_4)^{-1/2}$ in place of $\eps$ to get
\begin{equation}\label{PA4}
\P(A_4|\mathcal{F}_3) = O(2^{3 \ell} \eps^6).
\end{equation}

Because $A_1 \in \mathcal{F}_1$, $A_1 \cap A_2 \in \mathcal{F}_2$, and $A_1 \cap A_2 \cap A_3 \in \mathcal{F}_3$, we can combine the estimates in \eqref{PA1}, \eqref{PA2}, \eqref{PA3}, and \eqref{PA4} to get
\begin{equation}\label{case3}
\P(A_{u,v,w} \cap G) \leq C \P(A_1 \cap A_2 \cap A_3 \cap A_4) = O(2^{3k/2} 2^{-\ell} \eps^9 \log^{32}(1/\eps)).
\end{equation}

The number of points in $L$ is $O(\eps^{-2} \log^{7/2}(1/\eps))$.  Therefore, the number of possible choices for $(u,v,w)$ in Case 1 is $O(\eps^{-6} \log^{21/2}(1/\eps))$.  In Case 2, given the values of $u$, $v$, and $\ell$, the number of possible choices for $w$ is $O(2^{-\ell} \eps^{-2} \log^3(1/\eps))$.  Therefore, for a given value of $\ell$, the number of possible choices for $(u,v,w)$ in Case 2 is $O(\eps^{-6} \log^{10}(1/\eps) 2^{-\ell})$.  Likewise, in Case 3, given the values of $u$, $k$, and $\ell$, the number of possible choices for $v$ is $O(2^{-\ell} \eps^{-2} \log^3(1/\eps))$, and the number of possible choices for $w$ is $O(2^{-k} \eps^{-2} \log^3(1/\eps))$.  Therefore, for given values of $k$ and $\ell$, the number of possible choices for $(u,v,w)$ in Case 3 is $O(2^{-k} 2^{-\ell} \eps^{-6} \log^{19/2}(1/\eps))$.
Now we can combine the results \eqref{case1}, \eqref{case2}, and \eqref{case3}, along with Lemma \ref{AiryHolder}, to get
\begin{align}\label{Auvw}
\sum_{\substack{u, v, w \in L \\ u < v < w}} \P(A_{u,v,w}) &\leq \sum_{\substack{u, v, w \in L \\ u < v < w}} \P(G^c) + \sum_{\substack{u, v, w \in L \\ u < v < w}} \P(A_{u,v,w} \cap G) \nonumber \\
&\leq C \eps^{100} \cdot \eps^{-6} \log^{21/2}(1/\eps) + C \eps^9 \cdot \eps^{-6} \log^{21/2}(1/\eps) \nonumber \\
&\qquad+ C \sum_{\ell = 0}^{\infty} \eps^9 2^{-\ell} \log^{16}(1/\eps) \cdot \eps^{-6} \log^{10}(1/\eps) 2^{-\ell} \nonumber \\
&\qquad \qquad + C \sum_{k=-1}^{\infty} \sum_{\ell = k+1}^{\infty} 2^{3k/2} 2^{-\ell} \eps^9 \log^{32}(1/\eps) \cdot 2^{-k} 2^{-\ell} \eps^{-6} \log^{19/2}(1/\eps) \nonumber \\
&\leq C \eps^{94} \log^{11}(1/\eps) + C \eps^3 \log^{11}(1/\eps) + C \eps^3 \log^{26}(1/\eps) \sum_{\ell = 0}^{\infty} 2^{-2 \ell}  \nonumber \\
&\qquad + C \eps^3 \log^{42}(1/\eps) \sum_{k=-1}^{\infty} 2^{k/2} \sum_{\ell=k+1}^{\infty} 2^{-2 \ell} \nonumber \\
&\leq C \eps^3 \log^{42}(1/\eps).
\end{align}

Let $\mathcal{H}$ be the $\sigma$-field generated by $(W(t), u \leq t \leq w)$ and by $\mathcal{P}_i(t)$ for $t \in [u, w]$ and $i \in \{1, 2, 3\}$.  Note that $A_{u,v,w} \in \mathcal{H}$, and $m_2^*$ is $\mathcal{H}$-measurable. 

Having bounded $\P(A_{u,v,w})$ we now aim to bound $\P(B_{u,v,w} \cap G|\mathcal{H})$.  
Let $G_u \subseteq G$ be the event that the bound in Lemma \ref{AiryHolder} holds when $s,t \in [-T, u]$, and let $G_w \subseteq G$ be the event that the bound in Lemma \ref{AiryHolder} holds when $s,t \in [w, T]$.  If $|m_1^* - m_2^*|  < 2 \eps$ and $G_u$ occurs, we claim that one of the following must hold:
\begin{itemize}
\item There exists $r \in L \cap [-T, (u - T)/2]$ such that $$r = \min\{t \in L \cap [-T, (u - T)/2]: W(t) + \mathcal{P}_1(t) \geq m_2^* - 3 \eps\}$$ and 
$$\max_{t \in [r, r + 1/2]} (W(t) + \mathcal{P}_1(t) - W(r) - \mathcal{P}_1(r)) < 5 \eps.$$  Also, we must have $|W(r) + \mathcal{P}_1(r) - (W(r+1/2) + \mathcal{P}_1(r +1/2))| < \sqrt{2} C_{10} \log(1/\eps)$.

\item There exists $r \in L \cap ((u - T)/2, u]$ such that $$r = \max\{t \in L \cap ((u - T)/2, u]: W(t) + \mathcal{P}_1(t) \geq m_2^* - 3 \eps\}$$ and $$\max_{t \in [r, r - 1/2]} (W(t) + \mathcal{P}_1(t) - W(r) - \mathcal{P}_1(r)) < 5 \eps.$$  Also, we must have $|W(r) + \mathcal{P}_1(r) - (W(r-1/2) + \mathcal{P}_1(r -1/2))| < \sqrt{2} C_{10} \log(1/\eps)$.
\end{itemize}
To see this, note that Lemma \ref{AiryHolder} implies that for $\eps$ sufficiently small, when $|m_1^* - m_2^*| < 2 \eps$ and $G_u$ occurs, the process $(W(t) + \mathcal{P}_1(t), -T \leq t \leq u)$ must get to within $\eps$ of its maximum, and therefore within $3 \eps$ of $m_2^*$, at one of the points in $L$.  This point in $L$ must either be in $[-T, (u - T)/2]$ or in $((u - T)/2, u]$.  In the first case, we consider the points in $L$ in increasing order, and let $r$ be the first point at which the process gets within $3 \eps$ of $m_2^*$.  If $|m_1^* - m_2^*| < 2 \eps$, then the process $(W(t) + \mathcal{P}_1(t), -T \leq t \leq u)$ can not increase by more than $5 \eps$ during the time interval $[r, r + 1/2]$.  Note, in particular, that $r + 1/2 < u$ because $u \geq -(T-1)$.  The second case is handled the same way, except that we work backwards from time $u$.

Now suppose $r \in L \cap [-T, (u - T)/2]$, and let $\mathcal{H}_r$ be the $\sigma$-field generated by $\mathcal{P}_i$ for $i \geq 2$ and by $W(t)$ and $\mathcal{P}_1(t)$ for all $t \notin (r, r+1/2)$.  A consequence of the Brownian Gibbs Property of the parabolic Airy line ensemble is that conditional on $\mathcal{H}_r$, the process $(W(t), t \in [r, r + 1/2])$ is a Brownian bridge, and the process $(\mathcal{P}_1(t), t \in [r, r + 1/2])$ is a Brownian bridge conditioned to stay above $\mathcal{P}_2$.  A standard monotonicity argument given, for example, in Lemma 2.6 of \cite{ch14} implies that conditional on $\mathcal{H}_r$, the process $(\mathcal{P}_1(t), t \in [r, r + 1/2])$ can be coupled with a Brownian bridge $(B(t), t \in [r, r+1/2])$ having the same endpoints such that $B(t) \leq \mathcal{P}_1(t)$ for all $t \in [r, r + 1/2]$.  Therefore,
\begin{align}\label{probincrease}
&\P \Big( \max_{t \in [r, r + 1/2]} (W(t) + \mathcal{P}_1(t) - W(r) - \mathcal{P}_1(r)) < 5 \eps \,\Big|\, \mathcal{H}_r \Big) \nonumber \\
&\qquad \leq \P \Big( \max_{t \in [r, r + 1/2]} (W(t) + B(t) - W(r) - B(r)) < 5 \eps \,\Big|\, \mathcal{H}_r \Big).
\end{align}
Because the sum of two Brownian bridges is a Brownian bridge with twice the variance parameter, it follows from Lemma \ref{maxbridge} that on the event that $|W(r) + \mathcal{P}_1(r) - (W(r+1/2) + \mathcal{P}_1(r +1/2))| < \sqrt{2} C_{10} \log(1/\eps)$, the conditional probability on the right-hand side of \eqref{probincrease} is $O(\eps \log(1/\eps))$.
Because the Brownian bridge is symmetric under time reversal, the same bound can be obtained when $r \in L \cap ((u - T)/2, u]$.  It follows that $$\P(G_u \cap \{|m_1^* - m_2^*| < 2 \eps\}|\mathcal{H}) = O(\eps \log(1/\eps)).$$
The same argument, applied to the interval $[w, T]$ instead of $[-T, u]$ gives $$\P(G_w \cap \{|m_2^* - m_3^*| > 2 \eps\}|\mathcal{H}) = O(\eps \log(1/\eps)),$$
and also establishes the conditional independence of these two events given $\mathcal{H}$.
Combining these results, we get $\P(B_{u,v,w} \cap G|\mathcal{H}) = O(\eps^2 \log^2(1/\eps))$, and therefore because $A_{u,v,w} \in \mathcal{H}$, there is a positive constant $C$ such that
\begin{equation}\label{Buvw}
\P(B_{u,v,w} \cap G|A_{u,v,w}) \leq C \eps^2 \log^2(1/\eps).
\end{equation}
Combining \eqref{mainPA}, \eqref{Auvw}, and \eqref{Buvw}, we get
$$\P(A) \leq \P(G^c) + \sum_{\substack{u, v, w \in L \\ u < v < w}} \P(A_{u,v,w}) \P(B_{u,v,w} \cap G|A_{u,v,w}) \leq C \eps^5 \log^{44}(1/\eps),$$
which completes the proof.
\end{proof}

