\section{Statement of results}

We first address the continuity of $M_{k,a}$. From the functional equation \eqref{eq:Okamoto-FE} it follows easily that $F_a$ is H\"older continuous with exponent 
\[
\gamma:=-\log_3 \max\{a,|1-2a|\}.
\]
%\[
%b:=\max\{a,|1-2a|\}=\begin{cases}
%a & \mbox{if $a\geq 1/3$},\\
%1-2a & \mbox{if $a<1/3$}.
%\end{cases}
%\]
This means that there is a constant $C$ such that $|F_a(x)-F_a(y)|\leq C|x-y|^\gamma$ for all $x,y\in[0,1]$.

\begin{proposition} \label{prop:Holder-continuity}
For each $k$, $M_{k,a}$ is H\"older continuous with exponent $\alpha$ for any $0<\alpha<\gamma$. More precisely, there is a constant $C_k$ such that
\[
|M_{k,a}(x)-M_{k,a}(y)|\leq C_k|x-y|^\gamma \left(\log_3\frac{1}{|x-y|}\right)^k \qquad \forall x,y\in[0,1].
\]
\end{proposition}

Our next result gives the box-counting dimension of the graph of $M_{k,a}$. We denote the box-counting dimension of a set $E$ by $\dim_B E$.

\begin{theorem} \label{thm:box-dimension}
For each $k\in\NN$ and $a\in(0,1)$, we have
\[
\dim_B \graph(M_{k,a})=\dim_B \graph(F_a)=\begin{cases}
1+\log_3(4a-1) & \mbox{if $a\geq 1/2$},\\
1 & \mbox{if $a\leq 1/2$}.
\end{cases}
\]
\end{theorem}


\subsection{Finite derivatives}

To state our results on differentiability, we need some further notation. Let $(x_i)_i=(x_1,x_2,\dots)$ denote the ternary expansion of a point $x\in(0,1)$, so that $x_i\in\{0,1,2\}$ for each $i$ and $x=\sum_{i=1}^\infty x_i 3^{-i}$. If $x$ has two such representations, we choose the one ending in all zeros. For $x\in(0,1)$ and $n\in\NN$, let 
\[
l_n(x):=\#\{i\leq n: x_i=1\} 
\]
denote the number of $1$'s in the first $n$ ternary digits of $x$. Define the function
\begin{equation} \label{eq:phi}
\phi(a):=\frac{\log(3a)}{\log a-\log|1-2a|}, \qquad a\in\left(0,2/3\right]\backslash\left\{1/3,1/2\right\}.
\end{equation}
We extend $\phi$ continuously to $[0,2/3]$ by setting $\phi(0):=1$, $\phi(1/3):=1/3$, and $\phi(1/2):=0$. It can be shown that $\phi$ is strictly decreasing on $[0,1/2]$, and strictly increasing on $[1/2,2/3]$; see Figure \ref{fig:phi-and-h}. 
For each $a\in(0,1)\backslash\{1/3,1/2\}$, we also define the constant
\[
C_0:=C_0(a):=\frac{1}{\log a-\log|1-2a|}.
\]
Note that $C_0<0$ for $a<1/3$, whereas $C_0>0$ for $a>1/3$. Furthermore, $C_0(a)$ tends to $-\infty$ as $a\nearrow 1/3$, to $+\infty$ as $a\searrow 1/3$, and to $0$ as $a\to 1/2$.

\begin{proposition} \label{prop:only-zero}
Let $k\geq 1$ and $a\in(0,1)$. If $M_{k,a}$ is differentiable at a point $x$, then $M_{k,a}'(x)=0$.
\end{proposition}

\begin{theorem} \label{thm:differentiability-summary}
Let $k\geq 1$ and $a\in(0,1)$. For $x\in(0,1)$ and $n\in\NN$, define 
$$r_n(x):=l_n(x)-n\phi(a).$$
\begin{enumerate}[(a)]
\item If $0<a<1/3$, then $M_{k,a}'(x)=0$ if and only if $r_n(x)+k|C_0|\log n \to -\infty$ as $n\to\infty$;
\item If $1/3<a<2/3$ and $a\neq 1/2$, then $M_{k,a}'(x)=0$ if and only if $r_n(x)-kC_0\log n \to \infty$ as $n\to\infty$;
\item If $2/3\leq a<1$ or $a=1/3$, then $M_{k,a}$ is nowhere differentiable.
\end{enumerate}
\end{theorem}

The case $a=1/2$ is a bit special; we characterize the differentiability of $M_{k,1/2}$ in Proposition \ref{prop:one-half} below.

Defining the set
\[
D_{k,a}^0:=\{x\in(0,1): M_{k,a}'(x)=0\},
\]
we obtain the following consequence of the last theorem, which makes precise that the functions $M_{k,a}$ become progressively ``less differentiable" as $k$ increases.

\begin{corollary} \label{cor:strictly-descending-sets}
For each $0<a<2/3$ except $a=1/3$, the sequence of sets $(D_{k,a}^0)_{k\geq 0}$ is strictly decreasing; that is,
\[
D_{0,a}^0\supsetneq D_{1,a}^0 \supsetneq D_{2,a}^0 \supsetneq  \dots.
\]
Moreover, for each $k\geq 0$, $D_{k,a}^0\backslash D_{k+1,a}^0$ has positive Hausdorff dimension.
\end{corollary}

