%\begin{align*}
%M_{k,a}(x)-M_{k,a}(x_0)&=\sum_{m=1}^\f \big\{M_{k,a}(x_m)-M_{k,a}(x_{m-1})\big\}\\
%&\leq 2Ca^{n-l-k}|1-2a|^{l-k}\sum_{m=1}^\f \gamma^m(n+m)^k\\
