For $a=1/2$ we have the following explicit expression for the increments over ternary intervals.

\begin{lemma} \label{lem:difference-formulas}
Assume $0\leq l\leq k\leq n$, and let $j\in\{0,1,\dots,3^n-1\}$ be such that $l(j)=l$. Then
\[
\Delta_{k,1/2}(I_{n,j})=\frac{k!}{(k-l)!}\cdot\frac{(n-l)!}{(n-k)!}\left(1/2\right)^{n-k}(-2)^l.
\]
\end{lemma}

\begin{proof}
Starting from \eqref{eq:Leibniz-formula}, set $a=1/2$ and note that since $l\leq k\leq n$, only the term with $j=k-l$ does not vanish.
\end{proof}

In the next lemma and its proof, we write $M_k:=M_{k,1/2}$ to avoid clutter.

\begin{lemma} \label{prop:box-containment}
Fix $n\geq 2k-1$, and let $I=[x_l,x_r]=I_{n,j}$ be a ternary interval of order $n$. Then 
\[
\min\{M_{k}(x_l),M_{k}(x_r)\}\leq M_{k}(x)\leq \max\{M_{k}(x_l),M_{k}(x_r)\} \qquad\forall\,x\in I.
\]
In other words, the graph of $M_{k}$ over $I$ lies inside the rectangular `box' with opposite vertices $(x_l,M_{k}(x_l))$ and $(x_r,M_{k}(x_r))$ and edges parallel to the coordinate axes.
\end{lemma}

Note the conclusion of the lemma fails for $n\leq 2k-2$, as in that case the functional equation shows that $M_{k}(0)=M_{k}(3^{-n})=0$.

\begin{proof}
Since $M_{k}$ is continuous, the conclusion will follow by induction if we show that for each $m\geq 2k-1$ and each $j\in\{0,1,\dots,3^m-1\}$, $M_k\big((3j+1)3^{-m-1}\big)$ and $M_k\big((3j+2)3^{-m-1}\big)$ lie between $M_k(j3^{-m})$ and $M_k((j+1)3^{-m})$. By symmetry (cf. Lemma \ref{lem:symmetry}), it is enough to show this for $(3j+1)3^{-m-1}$.
Let $l:=l(j)$. Note that
\[
M_{k}\left(\frac{j+1}{3^m}\right)-M_{k}\left(\frac{j}{3^m}\right)=\Delta_{k,1/2}(I_{m,j})
\]
and
\[
M_{k}\left(\frac{3j+1}{3^{m+1}}\right)-M_{k}\left(\frac{j}{3^m}\right)=\Delta_{k,1/2}(I_{m+1,3j}).
\]
Since $l(3j)=l(j)=l$, Lemma \ref{lem:difference-formulas} shows that $\Delta_{k,1/2}(I_{m,j})$ and $\Delta_{k,1/2}(I_{m+1,3j})$ have the same sign, and
\[
\frac{|\Delta_{k,1/2}(I_{m+1,3j})|}{|\Delta_{k,1/2}(I_{m,j})|}=1/2\cdot \frac{m+1-l}{m+1-k}\leq 1,
\]
since $m\geq 2k-1\geq 2k-l-1$. Hence, $M_k\big((3j+1)3^{-m-1}\big)$ lies between $M_k(j3^{-m})$ and $M_k((j+1)3^{-m})$, as desired.
\end{proof}



\section{Box-counting dimension of the graph} \label{sec:box-dimension}

\begin{proof}[Proof of Theorem \ref{thm:box-dimension}]
Let $G_{k,a}$ denote the graph of $M_{k,a}$.

{\em Step 1: Upper bound.} Assume first that $a\neq 1/2$. For fixed $n$, the number of words $\mathbf{i}\in\{0,1,2\}^n$ with $l$ zeros is
$\binom{n}{l}2^{n-l}.$
%We have $\binom{n}{l}$ choices for the location of the 1s, and the remaining $n-l$ digits are independently chosen to be 0 or 2. 
Lemma \ref{lem:oscillation-bounds} implies that the number of $3^{-n}$-mesh cubes intersecting $G_{k,a}$ is bounded above by
\begin{align*}
N_{3^{-n}}(G_{k,a})&\leq C_k\left(3^n+2\right)n^k\sum_{l=0}^n\binom{n}{l}2^{n-l}a^{n-l}|1-2a|^l\\
%&\leq C\left(3^n+2\right)n^{k}\sum_{\ell=0}^n\binom{n}{\ell}(2a)^{n-\ell}|1-2a|^\ell\\
&= C_k\left(3^n+2\right)n^{k}\big(2a+|1-2a|\big)^n, %=C_k\left(3^n+2\right)n^{k}(4a-1)^n,
\end{align*}
where $C_k$ is the constant from Lemma \ref{lem:oscillation-bounds}.
The stated upper bound follows upon observing that
\[
2a+|1-2a|=\begin{cases} 1 & \mbox{if $a<1/2$},\\
4a-1 & \mbox{if $a>1/2$}.
\end{cases}
\]

If $a=1/2$, then by Lemmas \ref{lem:difference-formulas} and \ref{prop:box-containment}, we have, for an interval $I_{n,j}$ with $l(j)=l$,
\[
\osc(M_{k,1/2};I_{n,j})=|\Delta_{k,1/2}(I_{n,j})|=\frac{k!}{(k-l)!}\cdot\frac{(n-l)!}{(n-k)!}\left(1/2\right)^{n-k}2^{l},
\] 
for $0\leq l\leq k\leq n$. Furthermore, if $l(j)>k$, then $M_{k,1/2}$ is constant over $I_{n,j}$ and so the graph of $M_{k,1/2}$ over $I_{n,j}$ intersects only one $3^{-n}$-mesh square. Thus, for $n\geq k$,
\begin{align*}
N_{3^{-n}}\left(G_{k,1/2}\right)&\leq 3^n+\left(3^n+2\right)\sum_{l=0}^k\binom{n}{l}2^{n-l}\frac{k!}{(k-l)!}\cdot\frac{(n-l)!}{(n-k)!}\left(1/2\right)^{n-k}2^l\\
&=3^n+\left(3^n+2\right)2^k\sum_{l=0}^k\binom{k}{l}\frac{n!}{(n-k)!}\\
%&\leq 3^n+\left(3^n+2\right)2^k\sum_{l=0}^k\binom{k}{l} n^k\\
&\leq 3^n+\left(3^n+2\right)2^{2k}n^k,
%&\leq 3^n+2\left(3^n+2\right)n^{2k}\sum_{\ell=0}^k\binom{n}{\ell},
\end{align*}
yielding the desired upper bound of 1.

{\em Step 2: Lower bound.} The lower bound is trivial for $a\leq 1/2$, so let $a>1/2$. Then $1-2a<0$, and so $|(1-2a)n-l|\geq|1-2a|n=(2a-1)n$ for all $0\leq l\leq n$. By Lemma \ref{lem:ternary-increments}, there exists therefore a constant $\delta>0$  such that for all sufficiently large $n$,
\[
|\Delta_{k,a}(I_{n,j})|\geq a^{n-l(j)}(2a-1)^{l(j)}\delta n^k, \qquad \mbox{for all $0\leq j<3^n$}.
\]
(Here we have included the factors $a^{-k}$ and $(2a-1)^{-k}$ in the constant $\delta$.) We may further assume $n$ is so large that $\delta n^k\geq 1$.
Since the oscillation of $M_{k,a}$ over $I_{n,j}$ is at least $|\Delta_{k,a}(I_{n,j})|$, the number of $3^{-n}$-mesh squares that intersect the graph of $M_{k,a}$ over $I_{n,j}$ is at least
\[
3^n |\Delta_{k,a}(I_{n,j})|\geq 3^n a^{n-l(j)}(2a-1)^{l(j)}.
\]
Summing over $j=0,1,\dots,3^n-1$ and noting once more that for each $l\in\{0,1,\dots,n\}$ there are precisely $\binom{n}{l}2^{n-l}$ values of $j$ with $l(j)=l$, we get
\begin{equation*}
N_{3^{-n}}\left(G_{k,a}\right)\geq 3^n\sum_{l=0}^n\binom{n}{l}2^{n-l}a^{n-l}(2a-1)^l
=3^n\big(2a+(2a-1)\big)^n=3^n(4a-1)^n
\end{equation*}
for all sufficiently large $n$, yielding the desired lower bound.
\end{proof}


\section{Finite derivatives} \label{sec:differentiability}

In this section we consider the set of points where $M_{k,a}$ has a finite derivative. Throughout, $P_k(n,l)$ denotes the polynomial from Lemma \ref{lem:ternary-increments}.

\begin{lemma} \label{lem:no-polynomial-limit}
Assume $a\neq 1/2$. Let $x\in(0,1)$ and put $l_n:=l_n(x)$. Then, for $k\geq 1$, the sequence $(P_k(n,l_n))_n$ cannot have a finite limit as $n\to\infty$.
\end{lemma}

\begin{proof}
Suppose, to the contrary, that $\lim_{n\to\infty} P_k(n,l_n)$ exists and is finite. Then
    \begin{equation*}%\label{lim:PkDLim}
       \lim_{n\to\infty} \big[P_k(n+1,l_{n+1})-P_k(n,l_n)\big]= 0.
    \end{equation*}
		From the functional equations in Lemma \ref{lem:FE} (or, alternatively, from the precise expressions in the proof of Lemma \ref{lem:ternary-increments}), we can derive the difference equations
		\begin{align}
		P_k(n+1,l)-P_k(n,l)&=k(1-2a)P_{k-1}(n,l_n), \label{eq:difference-eq1}\\
		P_k(n+1,l+1)-P_k(n,l)&=-2kaP_{k-1}(n,l_n) \label{eq:difference-eq2}.
		\end{align}
		Since $l_{n+1}\in\{l_n,l_n+1\}$, it follows that $\lim_{n\to\infty} P_{k-1}(n,l_n) = 0$.
  %  By the difference formulas for $P_k$ we have that 
  %  \begin{equation}
  %      P_k(n+1,l_{n+1})-P_k(n,l_n) = 
	%			\begin{cases} -2kaP_{k-1}(n,l_n) & \text{ when } x_n = 1, \\
  %      k(1-2a)P_{k-1}(n,l_n) & \text{ when } x_n = 0,2.
  %      \end{cases}
  %  \end{equation}
  %  And so \eqref{lim:PkDLim} implies that $\lim_{n\to\infty} P_{k-1}(n,l_n) = 0$. 
		By induction, we then conclude that $\lim_{n\to\infty} P_0(n,l_n) = 0$. However, by definition, $P_0(n,l_n) = 1$ and we have a contradiction. 
\end{proof}

\begin{lemma} \label{lem:polynomial-growth}
Suppose
\[
\liminf_{n\to\infty}\left|\frac{l_n(x)}{n}-(1-2a)\right|>0.
\]
Then there exists $\delta>0$ such that $|P_k(n,l_n(x))|\geq\delta n^k$ for all sufficiently large $n$. In particular, this holds when $a>1/2$.
\end{lemma}

\begin{proof}
This follows immediately from Lemma \ref{lem:ternary-increments}.
\end{proof}

Recall that $I_n(x)$ denotes the ternary interval $I_{n,j}$ containing $x$.
Throughout this section, we use the following well-known fact: If $M_{k,a}'(x)=d\in\RR$, then
\[
\frac{\Delta_{k,a}(I_n(x))}{|I_n(x)|}=3^n \Delta_{k,a}(I_n(x))\to d \qquad\mbox{as $n\to\infty$},
\]
%where $I_n(x)$ denotes the ternary interval $I_{n,j}$ containing $x$. (If $x=j/3^n$, we choose $I_n(x):=[j/3^n,(j+1)/3^n]$ for definiteness.)

Recall the definition of $\phi(a)$ from \eqref{eq:phi}. It is not difficult to verify that 
\begin{gather}
0<a<\frac13 \qquad \Longrightarrow \qquad \frac13<\phi(a)<1-2a, \label{eq:where-is-phi-1}\\
\frac13<a<\frac12 \qquad \Longrightarrow \qquad \frac13>\phi(a)>1-2a. \label{eq:where-is-phi-2}
\end{gather}

We first collect a few special cases.

\begin{proposition} \mbox{\ } \label{prop:special-cases}
\begin{enumerate}[(a)]
\item If $a\geq 2/3$, then $M_{k,a}$ does not have a finite derivative at any point.
\item If $a= 1/3$ and $k\geq 1$, then $M_{k,a}$ does not have a finite derivative at any point.
\end{enumerate}
\end{proposition}

\begin{proof}
Let $x\in(0,1)$ and write $l_n:=l_n(x)$. 

(a) Suppose $a\geq 2/3$. Then $3^n a^{n-l_n}|1-2a|^{l_n}\geq 1$ for all $n$, and by Lemma \ref{lem:polynomial-growth}, $|P_k(n,l_n)|\to\infty$. So by Lemma \ref{lem:ternary-increments}, $3^n\Delta_{k,a}(I_n(x))$ does not have a finite limit for any $x$. Hence, $M_{k,a}$ does not have a finite derivative at any point.

(b) Suppose $a=1/3$ and $k\geq 1$. Then by Lemma \ref{lem:ternary-increments} we have that 
    \begin{equation*}
        3^n\Delta_{k,a}(I_{n,j}) = 3^{-2k}P_k(n,l_n),
    \end{equation*}
		but this does not have a finite limit by Lemma \ref{lem:no-polynomial-limit}. Hence, $M_{k,a}'(x)$ does not exist as a finite number.
\end{proof}

\begin{remark}
{\rm
For $k=1$, the conclusion of Proposition \ref{prop:special-cases} (b) was proved in \cite{Dalaklis}. We observe that this result is quite different from the situation for $k=0$, as $M_{0,1/3}$ is the identity function. 
}
\end{remark}

The case $a=1/2$ is also special:

\begin{proposition} \label{prop:one-half}
Let $a=1/2$ and $x\in(0,1)$. Then $M_{k,a}$ has a finite derivative at $x$ if and only if there is an $n\in\NN$ such that $l_n(x)=k+1$ and $3^n x\not\in\mathbb{Z}$. In that case, $M_{k,a}'(x)=0$.
%Then $M_{k,a}$ has a finite derivative at $x$ if and only if $x$ lies in the interior of an interval $I_{n,j}$ with $n\geq k+1$, $0\leq j<3^n$ and $l(j)\geq k+1$. In that case, $M_{k,a}'(x)=0$.
\end{proposition}

\begin{proof}
Let $x=(0.x_1x_2\dots)_3$, and first assume the stated condition. It follows from the functional equation (Lemma \ref{lem:FE}) that the graph of $M_{k,1/2}$ is flat on $I_n(x)$, and since $x$ lies in the interior of this interval, $M_{k,1/2}'(x)=0$.

Next, suppose $l:=\sup_n l_n(x)\leq k$. Then Lemma \ref{lem:difference-formulas} implies that
\[
3^n|\Delta_{k,1/2}(I_n(x))|=\frac{k!}{(k-l)!}\cdot \frac{(n-l)!}{(n-k)!}\left(\frac32\right)^n 2^{k+l}\to\infty,
\]
so $M_{k,1/2}'(x)$ does not exist as a finite real number.

Finally, if $l_n(x)=k+1$ and $3^n x\in\mathbb{Z}$, we can assume, by choosing $n$ minimal with this property, that $x_n=1$. Put $\bar{x}:=1-x$. Then the terminating ternary expansion of $\bar{x}$ contains exactly $k$ $1$'s, because we can alternatively write $x=(0.x_1\dots x_{n-1}02^\f)_3$. So by the previous case, $M_{k,1/2}$ does not have a finite derivative at $\bar{x}$. But then, by symmetry (Lemma \ref{lem:symmetry}), it does not have one at $x$ either.
\end{proof}

%For $m\geq 1$, let $j_m$ be the integer such that the right endpoint of $I_{n+m,j_m}$ is $x$. Then $l(j_m)=l_n(x)-1=k$. Hence, by Lemma \ref{lem:difference-formulas},
%\[
%3^{n+m}|\Delta_{k,1/2}(I_{n+m,j_m})|=k!2^{2k}\left(\frac32\right)^{n+m}\to\f,
%\]
%so that the left derivative of $M_{k,1/2}$ at $x$ is $\pm\f$.

%Finally, suppose $l:=\sup_n l_n(x)\leq k$. In that case, Lemma \ref{lem:difference-formulas} implies that
%\[
%3^n|\Delta_{k,1/2}(I_n(x))|=\frac{k!}{(k-l)!}\cdot \frac{(n-l)!}{(n-k)!}\left(\frac32\right)^n 2^{k+l}\to\infty,
%\]
%so again, $M_{k,1/2}'(x)$ does not exist as a finite real number.
%It follows from the functional equation (Lemma \ref{lem:FE}) that the graph of $M_{k,1/2}$ is flat on $I_{n,j}$ if $l(j)\geq k+1$, hence $M_{k,1/2}'(x)=0$ for $x$ in the interior of $I_{n,j}$. If $x$ is an endpoint of $I_{n,j}$, then one of the one-sided derivatives at $x$ is $0$, but the other is infinite. Finally, if $x$ does not lie in $I_{n,j}$ for any $n$ and $j$ with $l(j)\geq k+1$, this means that $l:=\sup_n l_n(x)\leq k$. In that case, Lemma \ref{lem:difference-formulas} implies that
%\[
%3^n|\Delta_{k,1/2}(I_n(x))|=\frac{k!}{(k-l)!}\cdot \frac{(n-l)!}{(n-k)!}\left(\frac32\right)^n 2^{k+l}\to\infty,
%\]
%so $M_{k,1/2}'(x)$ does not exist as a finite real number.

\begin{corollary} \label{cor:one-half-diff-ae}
For each $k\geq 1$, $M_{k,1/2}$ is differentiable almost everywhere.
\end{corollary}

\begin{proof}
By Proposition \ref{prop:one-half}, $M_{k,1/2}'(x)=0$ whenever the ternary expansion of $x$ contains infinitely many $1$'s. This is the case for Lebesgue-almost all $x\in(0,1)$.
\end{proof}

We now get to the main case: $0<a<2/3$ and $a\not\in\{1/3,1/2\}$. We divide this case in two parts. For both, we introduce the constant
\begin{equation} \label{eq:C0}
C_0:=C_0(a):=\frac{1}{\log a-\log|1-2a|}.
\end{equation}
Note that $C_0<0$ for $a<1/3$, whereas $C_0>0$ for $a>1/3$. Furthermore, $C_0(a)$ tends to $-\infty$ as $a\nearrow 1/3$, to $+\infty$ as $a\searrow 1/3$, and to $0$ as $a\to 1/2$.

The next two propositions show that the only possible finite value of $M_{k,a}'$ is $0$, and characterize exactly the set of points where this happens.

\begin{proposition} \label{prop:large-a-derivative}
Let $1/3<a<2/3$ and $a\neq 1/2$. For $x\in(0,1)$ and $n\in\NN$, set 
\[
r_n: = l_n(x)-n\phi(a). 
\]
Then $M_{k,a}$ has a finite derivative at $x$ if and only if 
\begin{equation} \label{eq:overshoot}
r_n-kC_0\log n \to \infty \qquad\mbox{as $n\to\infty$}, 
\end{equation}
in which case $M_{k,a}'(x)=0$. 
\end{proposition}

\begin{proof}
First assume \eqref{eq:overshoot}. Let $y\neq x$ be arbitrary and choose $n\in\NN$ so that $3^{-(n+1)}<|x-y|<3^{-n}$. Let $j$ be the integer such that $x\in I_{n,j}$; then $y\in I_{n,j-1}\cup I_{n,j}\cup I_{n,j+1}$. Since $l(j-1)=l(j)\pm 1$ and $l(j+1)=l(j)\pm 1$, Lemma \ref{lem:oscillation-bounds} and the triangle inequality yield that 
    \begin{equation}\label{ineq:DiffQuo}
        \left\vert\frac{M_{k,a}(x)-M_{k,a}(y)}{x-y}\right\vert \leq 3^{n+1}(2B_k)a^{n-l_n(x)}\vert1-2a\vert^{l_n(x)}n^k,
    \end{equation}
    where $B_k:=C_k a/|1-2a|$. The definition of $\phi(a)$ is equivalent to $3a^{1-\phi(a)}|1-2a|^{\phi(a)}=1$, and so
    \begin{equation}\label{eq:rn}
        3^na^{n-l_n(x)}\vert1-2a\vert^{l_n(x)}n^k = \left(\frac{|1-2a|}{a}\right)^{r_n}n^k=e^{-r_n/C_0}n^k\to 0,
    \end{equation}
		as can be seen by taking logarithms. Hence, $M_{k,a}'(x)=0$.

Conversely, suppose $M_{k,a}'(x)=d\in\RR$. Then certainly $3^n\Delta_{k,a}(I_n(x))\to d$. Write $l_n:=l_n(x)$ for short. We consider two cases.

\medskip
{\em Case 1.} Suppose $\liminf\big|\frac{l_n}{n}-(1-2a)\big|>0$. Then by Lemma \ref{lem:polynomial-growth} there exists $\delta>0$ such that for all large enough $n$, $|P_k(n,l_n)|\geq\delta n^k$. It follows that
\[
\lim_{n\to\infty} \frac{|P_k(n+1,l_{n+1})|}{|P_k(n,l_n)|}=1,
\]
since the difference equations \eqref{eq:difference-eq1} and \eqref{eq:difference-eq2} imply that $P_k(n+1,l_{n+1})-P_k(n,l_n)=o(n^{k-1})$. Since $|1-2a|<1/3$ for $1/3<a<2/3$, we can choose $\eps>0$ so small that 
\[
3|1-2a|(1+\eps)<1<3a(1-\eps), 
\]
and then choose $n_0$ so large that 
\[
1-\eps<\frac{|P_k(n+1,l_{n+1})|}{|P_k(n,l_n)|}<1+\eps \qquad\forall n\geq n_0.
\]
Now
\[
\frac{3^{n+1}|\Delta_{k,a}(I_{n+1}(x))|}{3^n|\Delta_{k,a}(I_n(x))|}=3a^{1-(l_{n+1}-l_n)}|1-2a|^{l_{n+1}-l_n}\cdot \frac{|P_k(n+1,l_{n+1})|}{|P_k(n,l_n)|},
\]
and since $3a^{1-(l_{n+1}-l_n)}|1-2a|^{l_{n+1}-l_n}=3a$ or $3|1-2a|$, it follows that the above ratio cannot converge to $1$. Hence, $M_{k,a}'(x)=d=0$. But then, for all large enough $n$,
\[
\delta \left(\frac{|1-2a|}{a}\right)^{r_n}n^k=3^n a^{n-l_n}|1-2a|^{l_n}\delta n^k\leq 3^n\Delta_{k,a}(I_n(x))\to 0,
\]
and taking logarithms yields \eqref{eq:overshoot}.

\medskip
{\em Case 2.} Suppose alternatively that $\lim_{n\to\infty}\frac{l_n}{n}=1-2a$. This is of course only possible if $a<1/2$.
Note by \eqref{eq:where-is-phi-2} that $1-2a<\phi(a)$, and since $a>|1-2a|$, it follows that
\[
3^n a^{n-l_n}|1-2a|^{l_n}\to \infty.
\]
Further, by Lemma \ref{lem:no-polynomial-limit}, $P_k(n,l_n)$ cannot tend to $0$. Therefore, $3^n|\Delta_{k,a}(I_n(x))|$ cannot have a finite limit as $n\to\infty$, contradicting that $M_{k,a}'(x)=d\in\RR$.
\end{proof}

\begin{proposition} \label{prop:small-a-derivative}
Let $0<a<1/3$. let $C_0$ be defined by \eqref{eq:C0}. For $x\in(0,1)$ and $n\in\NN$, define $r_n$ as in Proposition \ref{prop:large-a-derivative}. Then $M_{k,a}$ has a finite derivative at $x$ if and only if 
\[
r_n+k|C_0|\log n \to -\infty \qquad \mbox{as $n\to\infty$}, 
\]
in which case $M_{k,a}'(x)=0$. 
\end{proposition}

\begin{proof}
The proof is analogous to that of Proposition \ref{prop:large-a-derivative}, and is omitted.
\end{proof}

Together, Propositions \ref{prop:special-cases}, \ref{prop:large-a-derivative} and \ref{prop:small-a-derivative} imply Proposition \ref{prop:only-zero} and Theorem \ref{thm:differentiability-summary}.

%\begin{proof}[Proof of Theorem \ref{thm:differentiability-summary}]
%Statements (a), (b) and (c) follow from Propositions \ref{prop:small-a-derivative}, \ref{prop:large-a-derivative} and \ref{prop:special-cases}, respectively.
%\end{proof}

\begin{corollary} \label{cor:derivativ-zero-rough}
Let $x\in(0,1)$ and define
\[
\lambda_*(x):=\liminf_{n\to\infty}\frac{l_n(x)}{n}, \qquad \lambda^*(x):=\limsup_{n\to\infty}\frac{l_n(x)}{n}.
\]
\begin{enumerate}[(a)]
\item If $0<a<1/3$, then 
\[
\{x:\lambda^*(x)<\phi(a)\}\subset D_{k,a}^0\subset \{x:\lambda^*(x)\leq\phi(a)\}.
\]
%and $\lambda^{*}<\phi(a)$ then $M'_{k,a}(x) = 0$.
\item If $1/3<a<2/3$, then
\[
\{x:\lambda_*(x)>\phi(a)\}\subset D_{k,a}^0\subset \{x:\lambda_*(x)\geq\phi(a)\}.
\]
% $\lambda_{*}>\phi(a)$ then $M'_{k,a}(x) = 0$. 
\end{enumerate}
\end{corollary}

\begin{proof}
Let $0<a<1/3$ and $\lambda^{*}<\phi(a)$. Then $r_n=l_n(x)-\phi(a)n\leq -\delta n$ for some fixed $\delta>0$ and all large enough $n$, so certainly $r_n+k|C_0|\log n\to-\infty$. On the other hand, if $\lambda^{*}>\phi(a)$, then there is a subsequence $(n_i)$ and a $\delta>0$ such that $r_{n_i}\geq \delta n_i$ for all $i$. Hence (a) follows from Proposition \ref{prop:small-a-derivative}. The proof of (b) is analogous.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:M_k-differentiability}]
Statement ({\em a}) is the same as Theorem \ref{thm:differentiability-summary} (c). Statements ({\em b}) and ({\em c}) follow from Corollary \ref{cor:derivativ-zero-rough} in the same way as in \cite[Section 4]{Allaart}.
\end{proof}

\begin{theorem} \label{thm:big-set-difference}
For $a\in(0,2/3)\backslash\big\{1/3\big\}$ and any $k\geq 1$ there exist uncountably many points $x$ such that $M'_{k,a}(x) = 0$ but $M_{k+1,a}$ does not have a finite derivative at $x$. Moreover, the set of such points has positive Hausdorff dimension.
\end{theorem}

\begin{proof}
We first consider the case $a=1/2$. For $x\in(0,1)$, let $l(x):=\sup_n l_n(x)$. If $x$ is not a ternary rational point, then the condition of Proposition \ref{prop:one-half} simplifies to $l(x)\geq k+1$. Thus, the set difference $D_{k,1/2}^0\backslash D_{k+1,1/2}^0$ is, up to a countable set of endpoints, equal to the set of points $x$ such that $l(x)=k+1$. This set has Hausdorff dimension $\log_3 2$, as it is a countable union of affine copies of the ternary Cantor set.

Next, we assume $0<a<1/3$. Recall that $C_0<0$ in this case.
Fix an arbitrary $\delta\in(0,1)$. We construct a point $x$ with the desired property by prescribing the positions of the 1's in its ternary expansion. For $n\in\NN$, let
\[
b_n:=\left\lfloor\frac{n}{\phi(a)}-\frac{k+\delta}{\log 3a}\log n\right\rfloor,
\]
and put $x:=\sum_{j=1}^\infty d_j 3^{-j}$, where
\begin{equation} \label{eq:special-ternary-expansion}
d_j=\begin{cases}
1 & \mbox{if $j=b_n$ for some $n\in\NN$},\\
0\ \mbox{or}\ 2\ \mbox{arbitrarily} & \mbox{otherwise}.
\end{cases}
\end{equation}
We first verify that $M_{k,a}'(x)=0$. For all large enough $n$,
\begin{align*}
l_{b_n}(x)&-\phi(a)b_n+k|C_0|\log b_n=n-\phi(a)b_n+k|C_0|\log b_n\\
&\leq n-\phi(a)\left(\frac{n}{\phi(a)}-\frac{k+\delta}{\log 3a}\log n-1\right)+k|C_0|\log\left(\frac{n}{\phi(a)}-\frac{(k+\delta)}{\log 3a}\log n\right)\\
&\leq \phi(a)\left(\frac{k+\delta}{\log 3a}\log n+1\right)+k|C_0|\log\left(\frac{2n}{\phi(a)}\right)\\
&=-(k+\delta)|C_0|\log n+\phi(a)+k|C_0|\{\log n+\log 2-\log\phi(a)\}\\
&=-\delta |C_0|\log n+\phi(a)+k|C_0|\{\log 2-\log\phi(a)\}\to -\infty.
\end{align*}
Here the second-to-last step follows from the definitions of $\phi(a)$ and $C_0$.
Now if $j\in\NN$ is arbitrary, choose $n$ so that $b_{n-1}<j\leq b_{n}$. Then
\begin{align*}
l_j(x)-\phi(a)j+k|C_0|\log j &\leq l_{b_{n}}(x)-\phi(a)b_{n-1}+k|C_0|\log b_{n}\\
&\leq l_{b_{n}}(x)-\phi(a)b_{n}+k|C_0|\log b_{n}+\phi(a)\{b_{n}-b_{n-1}\}\\
&\to -\infty,
\end{align*}
because $b_n-b_{n-1}$ is bounded in $n$. Thus, we have verified the condition of Proposition \ref{prop:small-a-derivative}. A similar calculation, which we omit, shows that $l_j(x)-\phi(a)j+(k+1)|C_0|\log j\to +\infty$. Hence, $M_{k,a}'(x)=0$ but $M_{k+1,a}'(x)$ does not exist as a finite real number.

It is not difficult to show that the set of points $x$ whose ternary expansion is given by \eqref{eq:special-ternary-expansion} has Hausdorff dimension $(1-\phi(a))\log_3 2>0$. Hence, the set of points for which $M_{k,a}'(x)=0$ but $M_{k+1,a}$ does not have a finite derivative at $x$ has at least this dimension. We leave the details to the interested reader.

Finally, the case where $1/3<a<2/3, a\neq 1/2$ can be dealt with in a similar way; we omit the details.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:strictly-descending-sets}]
That the differences $D_{k,a}^0\backslash D_{k+1,a}^0$ are descending in $k$ for each $a\in(0,2/3)\backslash \{1/3\}$ follows immediately from Propositions \ref{prop:one-half}, \ref{prop:large-a-derivative} and \ref{prop:small-a-derivative}. That they have positive Hausdorff dimension is the result of Theorem \ref{thm:big-set-difference}.
\end{proof}



\section{Infinite derivatives: $a=1/2$} \label{sec:infinite-derivative-one-half}

In this section we describe the infinite derivatives of $M_{k,1/2}$. Since the parameter $a$ will be fixed at $1/2$, we drop it from the notation and write simply $M_k$ instead of $M_{k,1/2}$.

For $x\in[0,1]$, $n\in\NN$ and $d\in\{0,2\}$, let 
\begin{equation} \label{eq:run-length}
\rho_n(x;d):=\max\{m\geq 0: x_{n+1}=\dots=x_{n+m}=d\}
\end{equation}
be the run length of consecutive digits $d$ starting at the $(n+1)$th ternary digit of $x$, where we make the convention that the maximum of the empty set is zero.

\begin{theorem} \label{thm:infinite-derivatives-half}
Fix $k\in\NN$. Let $x\in(0,1)$, and let $l:=l(x):=\sup_n l_n(x)$ be the total number of $1$'s in the ternary expansion of $x$. 
\begin{enumerate}[(a)]
\item If $l>k$, then $M_k$ does not have an infinite derivative at $x$.
\item If $l=k$, then $M_k$ has an infinite derivative at $x$ if and only if Eidswick's condition holds (see \cite{Eidswick}): 
\[
cn-\rho_n(x;d)\to\f, \qquad d=0,2,
\]
where $c:=\log_2 3-1$. If this is the case, $M_k'(x)=(-1)^k\cdot \f$.
\item If $l<k$, then sufficient for $M_k$ to have an infinite derivative at $x$ is that there exists $N\in\NN$ such that
\[
\rho_n(x;d)\leq \log_2 n-\log_2(k-l)-2 \qquad \forall n\geq N, \forall d\in\{0,2\};
\]
and necessary is that there exists $N\in\NN$ such that
\[
\rho_n(x;d)\leq \log_2 n-\log_2(k-l) \qquad \forall n\geq N, \forall d\in\{0,2\}.
\]
Moreover, if $M_k$ has an infinite derivative at $x$, then $M_k'(x)=(-1)^l\cdot\f$.
\end{enumerate}
\end{theorem}

(An exact characterization would involve the entire sequence $(\rho_n(x;d))$ of run lengths in a complicated way, and even though one can be written down, it is not enlightening and therefore we omit it here. On the other hand, the conditions given above are simple to understand, and are sharp to within a small constant.)

\begin{corollary} \label{cor:full-dimension}
For all $l\leq k$, let $F_{k,l}^\f$ be the set
\[
F_{k,l}^\f:=\{x\in[0,1]: l(x)=l\ \mbox{and}\ M_k'(x)=\pm\f\}.
\]
Then $F_{k,l}^\f$ has Hausdorff dimension $s:=\log_3 2$. Furthermore, letting $\mathcal{H}^s(E)$ denote the $s$-dimensional Hausdorff measure of a set $E$, we have that $\mathcal{H}^s(F_{k,l}^\f)=0$ for $l<k$, whereas $\mathcal{H}^s(F_{k,k}^\f)>0$. As a result,
\[
\mathcal{H}^s(D_{k,1/2}^{+\f})>0 \quad\mbox{and}\quad \mathcal{H}^s(D_{k,1/2}^{-\f})=0 \quad\mbox{when $k$ is even},
\]
and
\[
\mathcal{H}^s(D_{k,1/2}^{-\f})=0 \quad\mbox{and}\quad \mathcal{H}^s(D_{k,1/2}^{+\f})>0 \quad\mbox{when $k$ is odd}.
\]
\end{corollary}

\begin{proof}[Proof of Theorem \ref{thm:infinite-derivatives-half}]
({\em a}) and ({\em b}): If $x_1\dots x_n$ contains exactly $k$ 1's, including at the $n$th digit, then the graph of $M_k$ over the interval $[0.x_1\dots x_n,0.x_1\dots x_n+3^{-n}]$ is an affine copy of the Cantor devil's staircase $F_{1/2}$. This follows by setting $a=1/2$ in the functional equations \eqref{eq:M1-FE} and \eqref{eq:Mk-FE} and iterating: eventually, all higher order partial derivatives will vanish. Thus, ({\em b}) follows from Eidswick's theorem \cite{Eidswick}. Moreover, if $(x_i)$ contains at least $k+1$ 1's, then $x$ lies in one of the flat segments of a devil's staircase (possibly at an endpoint), so the right derivative of $M_k$ vanishes at $x$, and this gives ({\em a}).

({\em c}) We assume $l$ is even and explore when $M_k'(x)=+\f$. Note that $M_k'(x)$ cannot equal $-\f$ because for all sufficiently large $n$ (namely, all $n$ beyond the position of the last 1), the secant slope of $M_k$ over the interval $I_n(x)=[0.x_1\dots x_n,0.x_1\dots x_n+3^{-n}]$ is positive. Note further that $x$ cannot be a ternary rational point, because $M_k$ has local extrema at such points. Thus, $(x_i)$ does not end in $0^\f$ or $2^\f$, and hence $(x_i)$ contains both infinitely many 0's and infinitely many 2's.

We first consider whether $M_k$ has an infinite {\em right} derivative at $x$. We denote the right derivative by $(M_k)_+'$. Let $n_0$ be the position of the last 1 in $(x_i)$, and define the set $E:=\{n>n_0: x_n=0\}$. For each $n\in E$, put $z_n:=0.x_1\dots x_{n-1}20^\f$. Then $z_n>x$ and $3^{-n}<z_n-x<2\cdot 3^{-n}$. We certainly need that
\begin{equation} \label{eq:the-critical-sequence}
\frac{M_k(z_n)-M_k(x)}{z_n-x}\to\f,
\end{equation}
but this is also sufficient: For arbitrary $y>x$, let $n$ be the index such that $x_1\dots x_{n-1}=y_1\dots y_{n-1}$ and $x_n<y_n$. If $y$ is close enough to $x$, then $n>n_0$, and hence $x_n=0$; i.e. $n\in E$. Since $y_n=1$ or $2$, Lemmas \ref{prop:box-containment} and \ref{lem:difference-formulas} imply that $M_k(y)\geq M_k(z_n)$, recalling that $l$ is even. Thus, if \eqref{eq:the-critical-sequence} holds, then $M_k'(x)=+\f$.

Take $n>n_0$ and assume also that $n\geq 2k$. Let $r:=\rho_n(x;2)$ be the run length of consecutive $2$'s starting with $x_{n+1}$; see \eqref{eq:run-length}. Since the ternary expansion of $x$ contains no more 1's after the $n$th digit, $x$ lies between $0.x_1\dots x_{n-1}02^r 0^\f$ and $0.x_1\dots x_{n-1}02^r 10^\f$, and so
\begin{equation} \label{eq:Mx-bounds}
M_k(x_1\dots x_{n-1}02^r0^\f)\leq M_k(x)\leq M_k(x_1\dots x_{n-1}02^r10^\f)
\end{equation}
by Lemma \ref{prop:box-containment}, since $l$ is even. Hence,
%Then $x>0.x_1\dots x_{n-1}02^r0^\f$, and, by Lemma \ref{lem:difference-formulas} and Proposition \ref{prop:box-containment}, $M_k(x)>M_k(x_1\dots x_{n-1}02^r0^\f)$, since $l$ is even. Hence,
\[
\frac{M_k(z_n)-M_k(x)}{z_n-x}<3^n\big\{M_k(x_1\dots x_{n-1}20^\f)-M_k(x_1\dots x_{n-1}02^r0^\f)\big\}.
\]
To calculate the difference in square brackets, we first compute the corresponding difference for $F_a$ and then differentiate $k$ times. Set $\mathbf{i}:=x_1\dots x_{n-1}$. Note that
\[
F_a(\mathbf{i}20^\f)-F_a(\mathbf{i}0^\f)=a^{n-l-1}(1-2a)^l(1-a) \qquad\mbox{for all $n>n_0$},
\]
and so
\begin{align*}
F_a(\mathbf{i}20^\f)-F_a(\mathbf{i}02^r0^\f)&=a^{n-l-1}(1-2a)^l(1-a)-\sum_{j=n+1}^{n+r}a^{j-l-1}(1-2a)^l(1-a)\\
&=a^{n-l-1}(1-2a)^l\big(1-a-a(1-a^r)\big)\\
%&=a^{n-l-1}(1-2a)^l(1-2a+a^{r+1})\\
&=a^{n-l-1}(1-2a)^{l+1}+a^{n-l+r}(1-2a)^l.
\end{align*}
Differentiating $k$ times and substituting $a=1/2$ gives, after some calculations,
\begin{align}
\begin{split}
M_k(\mathbf{i}&20^\f)-M_k(\mathbf{i}02^r0^\f)\\
&=\frac{k!}{(k-l)!}(-2)^l\left(1/2\right)^{n-k+r}\left[\frac{(n-l+r)!}{(n-k+r)!}-2^{r+1}(k-l)\frac{(n-l-1)!}{(n-k)!}\right].
\end{split}
\label{eq:lower-critical-difference}
\end{align}
Suppose $r>\log_2 n-\log_2(k-l)$. Then $2^{r+1}(k-l)>2n$, and we claim this implies that the difference in square brackets is negative for all sufficiently large $n$. First we estimate
\begin{equation} \label{eq:first-estimate}
\frac{(n-l+r)!}{(n-k+r)!}-2^{r+1}(k-l)\frac{(n-l-1)!}{(n-k)!}<(n+r)^{k-l}-2n(n-k+1)^{k-l-1}.
\end{equation}
Choose $\eps>0$ so small that
\[
(1+\eps)^{k-l}<2(1-\eps)^{k-l-1}.
\]
If $r\geq \eps n$, then for large enough $n$ the factor $2^{r+1}$ in \eqref{eq:first-estimate} will dominate and make the left-hand side negative. So assume $r<\eps n$. Then, for $n$ so large that $n-k+1>(1-\eps)n$,
\begin{equation*}
(n+r)^{k-l}<(1+\eps)^{k-l}n^{k-l}<2(1-\eps)^{k-l-1}n^{k-l}
<2n(n-k+1)^{k-l-1},%<2^{r+1}(k-l)(n-k+1)^{k-l-1},
\end{equation*}
as required. Thus, an infinite derivative at $x$ is impossible. This proves the necessity statement in ({\em c}).

For the sufficiency statement, observe that $M_k(x)\leq M_k(\mathbf{i}02^r10^\f)$, by \eqref{eq:Mx-bounds}. Lemma \ref{lem:difference-formulas} gives
\[
M_k(\mathbf{i}02^r10^\f)-M_k(\mathbf{i}02^r0^\f)=(-2)^l\frac{k!}{(k-l)!}\cdot\frac{(n+r+1-l)!}{(n+r+1-k)!}\left(1/2\right)^{n+r+1-k}.
\]
Subtracting this from \eqref{eq:lower-critical-difference} yields, after some manipulation,
\[
M_k(\mathbf{i}20^\f)-M_k(\mathbf{i}02^r10^\f)=(-2)^l\frac{k!}{(k-l)!}\left(1/2\right)^{n-k+r+1}A_k(n,l,r),
\]
%&=(-2)^l\frac{k!}{(k-l)!}\left(1/2\right)^{(-2)^l\frac{k!}{(k-l)!}-k+r+1}\left[\frac{(n-l+r)!}{(n-k+r)!}\left(2-\frac{n+r+1-l}{n+r+1-k}\right)-2^{r+2}(k-l)\frac{(n-l-1)!}{(n-k)!}\right]\\
where
\[
A_k(n,l,r):=\frac{(n-l+r)!}{(n-k+r+1)!}(n+r+1+l-2k)-2^{r+2}(k-l)\frac{(n-l-1)!}{(n-k)!}.
\]
Since $l$ is even, it follows that $M_k(\mathbf{i}20^\f)-M_k(\mathbf{i}02^r10^\f)>0$ if and only if $A_k(n,l,r)>0$. We can estimate $A_k(n,l,r)$ by
\[
A_k(n,l,r)>(n-k+r+2)^{k-l-1}(n+r+1+l-2k)-2^{r+2}(k-l)(n-l-1)^{k-l-1}.
\]
%\begin{align*}
%&\frac{(n-l+r)!}{(n-k+r+1)!}(n+r+1+l-2k)-2^{r+2}(k-l)\frac{(n-l-1)!}{(n-k)!}\\
%&\qquad >(n-k+r+2)^{k-l-1}(n+r+1+l-2k)-2^{r+2}(k-l)(n-l-1)^{k-l-1}.
%\end{align*}
Assume $r\leq \log_2 n-\log_2(k-l)-2$. Then $2^{r+2}(k-l)\leq n$. If, in fact, $r\leq 2k-l$, then $2^{r+2}(k-l)(n-l-1)^{k-l-1}=O(n^{k-l-1})$ whereas $(n-k+r+2)^{k-l-1}(n+r+1+l-2k)$ is of order $n^{k-l}$. Otherwise, we have
\begin{align*}
(n-k+r+2)^{k-l-1}(n+r+1+l-2k)&>(n+k-l+2)^{k-l-1}(n+1)\\
&>n(n-l-1)^{k-l-1}\\
&\geq 2^{r+2}(k-l)(n-l-1)^{k-l-1}.
\end{align*}
Hence, in either case, $A_k(n,l,r)>0$,
%\[
%\frac{(n-l+r)!}{(n-k+r+1)!}(n+r+1+l-2k)-2^{r+2}(k-l)\frac{(n-l-1)!}{(n-k)!}>0,
%\]
at least for large enough $n$. Since $A_k(n,l,r)$ is an integer (recall $l<k$ and $n\geq 2k$), it follows that
\[
M_k(\mathbf{i}20^\f)-M_k(\mathbf{i}02^r10^\f)\geq 2^l\frac{k!}{(k-l)!}\left(1/2\right)^{n-k+r+1}.
\]
But this implies
\begin{align*}
\lim_{n\to\f, n\in E}\frac{M_k(z_n)-M_k(x)}{z_n-x}&\geq \lim_{n\to\f}\frac{M_k(\mathbf{i}20^\f)-M_k(\mathbf{i}02^r10^\f)}{2\cdot 3^{-n}}\\
&\geq\lim_{n\to\f} 3^n2^{l-1}\frac{k!}{(k-l)!}\left(1/2\right)^{n-k+\rho_n(x;2)+1}\\
&\geq \lim_{n\to\f} 3^n2^{l-1}\frac{k!}{(k-l)!}\left(1/2\right)^{n+\log_2 n}=+\f.
\end{align*}
Hence, $(M_k)_+'(x)=+\f$.

If $l$ is odd, all the signs are reversed and we get $(M_k)_+'(x)=-\f$.

Finally, the symmetry property of Lemma \ref{lem:symmetry}, applied to the full unit interval (that is, $M_k(1-x)=-M_k(x)$ for all $x\in[0,1]$) yields that $(M_k)_-'(x)=(M_k)_+'(1-x)$, so the conditions for $M_k$ to have an infinite {\em left} derivative at $x$ are the same as those for an infinite {\em right} derivative at $1-x$. Since the expansion of $1-x$ is obtained from that of $x$ by changing $0$'s to $2$'s and vice versa, this means we obtain the same conditions for the run lengths of $0$'s.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:full-dimension}]
Let $l\leq k$. By Theorem \ref{thm:infinite-derivatives-half}, $M_k$ has an infinite derivative at $x$ whenever $l(x)\leq k$ and the run lengths $\rho_n(x;0)$ and $\rho_n(x;d)$ are bounded. Let $K$ be the set of points $x$ for which this is the case, and for $m\geq 2$, let $K_m$ be the set of points $x=(0.x_1x_2\dots)_3$ such that $x_i\in\{0,2\}$ for all $i$, $x_{jm-1}=0$ for all $j\in\NN$, and $x_{jm}=2$ for all $j\in\NN$. Clearly, $K\supset K_m$ for all $m$. Note that $K_m$ is a Cantor set of $2^{m-2}$ parts with contraction ratio $3^{-m}$ (because the last two digits of each successive block of $m$ digits are fixed and the others can be freely chosen from $\{0,2\}$). Thus,
\[
\dim_H K_m=\frac{(m-2)\log 2}{m\log 3},
\]
and it follows that
\[
\dim_H F_{k,l}^\f\geq \dim_H K\geq\sup_m \dim_H K_m=\log_3 2=s.
\]
% such that $R_n(x;d)\leq m$ for all $n\in\NN$ and $d\in\{0,2\}$. Let $\tilde{K}:=\{x\in K: l(x)=0\}$ and likewise, $\tilde{K}_m:=\{x\in K_m: l(x)=0\}$. Then $K$ is a countable union of affine contracted copies of $\tilde{K}$, and likewise, $K_m$ is a countable union of affine contracted copies of $\tilde{K}_m$. Hence,
%\[
%\dim_H F_{k,l}^\f\geq \dim_H K=\dim_H \tilde{K}=\sup_m \dim_H \tilde{K}_m.
%\]
%Note that $\tilde{K}_m$ is a Cantor set of $2^{m-2}$ parts with contraction ratio $3^{-m}$ (because the last two digits of each successive block of $m$ digits are fixed and the others can be freely chosen). Thus
%\[
%\dim_H \tilde{K}_m=\frac{(m-2)\log 2}{m\log 3},
%\]
%and it follows that $\dim_H F_{k,l}^\f\geq s:=\frac{\log 2}{\log 3}$. 
On the other hand, each $F_{k,l}^\f$ is contained in a countable union of affine copies of the ternary Cantor set $C$, hence $\dim_H F_{k,l}^\f\leq s$.

Next, observe that $\mathcal{H}^s(C)=1$ (see \cite[p.~53]{Falconer}), so $\mathcal{H}^s|_C$ is a probability measure on $C$. In fact, it is the measure that makes the ternary digits of $x$ independent and identically distributed, with digits $0$ and $2$ each having probability $1/2$. Let first $l<k$. By a refinement of the Borel-Cantelli lemma (see \cite[Example 6.5]{Billingsley}), the set of $x\in C$ such that $\rho_n(x;2)>\log_2 n-\log_2(k-l)$ for infinitely many $n$ has full $\mathcal{H}^s$-measure in $C$ because the infinite series
\[
\sum_{n=1}^\infty 2^{-(\log_2 n-\log_2(k-l))}=(k-l)\sum_{n=1}^\infty \frac{1}{n}
\]
diverges, so it follows from the necessary condition in Theorem \ref{thm:infinite-derivatives-half} ({\em c}) that $\mathcal{H}^s(F_{k,l}^\f)=0$.

If $l=k$, then $F_{k,k}^\f$ contains the set 
\[
\{x\in [0,1]: l(x)=k\ \mbox{and}\ \rho_n(x;d)<(c/2)n\ \mbox{for all sufficiently large $n$ and $d\in\{0,2\}$}\},
\]
and this set has full $\mathcal{H}^s$ measure in $\{x\in C: l(x)=k\}$ by the Borel-Cantelli lemma since $\sum_{n=1}^\f 2^{-(c/2)n}<\f$. Hence, $\mathcal{H}^s(F_{k,k}^\f)>0$.
The statements about $\mathcal{H}^s(D_{k,1/2}^{+\f})$ and $\mathcal{H}^s(D_{k,1/2}^{-\f})$ now follow since Theorem \ref{thm:infinite-derivatives-half} shows that $M_k'(x)=(-1)^l\cdot\f$ when $M_k$ has an infinite derivative at $x$.
\end{proof}



\section{Infinite derivatives: $a<1/2$} \label{sec:infinite-derivative-small-a}

In this section, we investigate the infinite derivatives of $M_{k,a}$ when $a<1/2$. While we are unable to state exact ``if and only if" conditions, the first theorem below gives a partial characterization in terms of the (upper and lower) frequency of $1$'s in the ternary expansion of $x$; this will be enough to prove Theorem \ref{thm:D-inf-dimensions}.
Recall the definition of $\phi(a)$ from \eqref{eq:phi}, as well as the inequalities \eqref{eq:where-is-phi-1} and \eqref{eq:where-is-phi-2}. 

\begin{theorem} \label{thm:infinite-derivative-detail}
Let $k\in\NN$ and $x\in(0,1)$, and let
\[
\lambda_*:=\liminf_{n\to\f}\frac{l_n(x)}{n}, \qquad \lambda^*:=\limsup_{n\to\f}\frac{l_n(x)}{n}.
\]
\begin{enumerate}[(a)]
\item Suppose $0<a<1/3$.
\begin{enumerate}[(i)]
\item If $\lambda_*>1-2a,$ then $M_{k,a}'(x)=(-1)^k\cdot\f$.
%\[
%M_{k,a}'(x)=\begin{cases}
%+\f & \mbox{if $k$ is even},\\
%-\f & \mbox{if $k$ is odd}.
%\end{cases}
%\]
\item If 
$$\phi(a)<\lambda_*\leq\lambda^*<1-2a,$$ 
then $M_{k,a}'(x)=+\f$.
\item If $\lambda_*<\phi(a),$ then $M_{k,a}$ does not have an infinite derivative at $x$.
\end{enumerate}
\item Suppose $a=1/3$.
\begin{enumerate}[(i)]
\item If $\lambda^*<1/3,$ then $M_{k,a}'(x)=+\f$.
\item If $\lambda_*>1/3,$ then $M_{k,a}'(x)=(-1)^k\cdot\f$.
\end{enumerate}
\item Suppose $1/3<a<1/2$.
\begin{enumerate}[(i)]
\item If $\lambda^*<1-2a,$ then $M_{k,a}'(x)=+\f$.
\item If 
$$1-2a<\lambda_*\leq\lambda^*<\phi(a),$$ 
then $M_{k,a}'(x)=(-1)^k\cdot\f$.
\item If $\lambda^*>\phi(a),$ then $M_{k,a}$ does not have an infinite derivative at $x$.
\end{enumerate}
\item For all $0<a<1/2$, if 
$$\lambda_*<1-2a<\lambda^*,$$ 
then $M_{k,a}$ does not have an infinite derivative at $x$.
\end{enumerate}
\end{theorem}

We do not give a proof of this theorem here, as it is a direct consequence of Theorem \ref{thm:alternating-infinities} below.
This next theorem provides more details about the infinite derivatives in the boundary case of Theorem \ref{thm:infinite-derivative-detail}, when $l_n(x)/n\to 1-2a$. It reveals a surprising alternating pattern when $(1-2a)n-l_n(x)$ is of order $\sqrt{n}$. In order to state it, we first define a sequence $(q_k)$ of polynomials inductively by
\begin{align}
\begin{split}
q_1(t)&=t,\\
q_{k+1}(t)&=tq_k(t)-q_k'(t), \qquad k=1,2,\dots.
\end{split}
\label{eq:q-polynomials}
\end{align}

\begin{lemma} \label{lem:polynomial-roots}
For each $k\in\NN$, $q_k$ has $k$ distinct real zeros, distributed symmetrically about $0$. Furthermore, $q_k$ is even when $k$ is even, and $q_k$ is odd when $k$ is odd.
\end{lemma}

\begin{proof}
The second statement is immediate from the definition and induction. It follows that the graph of $q_k$ is symmetric about the $y$-axis when $k$ is even, and is symmetric about the origin when $k$ is odd. Thus, the set of zeros of $q_k$ is symmetric about $0$. Furthermore, $q_k(0)=0$ when $k$ is odd.

We now prove inductively that $q_k$ has $k$ distinct real zeros. This is clear for $k=1$. Suppose the statement is true for $k$, and consider $q_{k+1}(t)=tq_k(t)-q_k'(t)$. We first show that between any two consecutive zeros of $q_k$ there is a zero of $q_{k+1}$. Let $t_1<t_2<\dots<t_k$ be the zeros of $q_k$, and take $i\in\{1,2,\dots,k-1\}$. Since $q_k$ has no double zeros, its graph crosses the $t$-axis transversally (i.e. with a non-zero derivative). Thus, either $q_k'(t_i)<0$ and $q_k'(t_{i+1})>0$ or the other way around; without loss of generality assume the former. Then $q_{k+1}(t_i)=-q_k'(t_i)>0$ and $q_{k+1}(t_{i+1})=-q_k'(t_{i+1})<0$. Therefore, $q_{k+1}$ has a zero between $t_i$ and $t_{i+1}$.

Next, we claim that $q_{k+1}$ has a zero to the left of $t_1$ and another to the right of $t_k$. Assume first that $k$ is even. Then $q_k$ is even, so $q_k'(t_1)<0$ and $q_k'(t_k)>0$. Hence $q_{k+1}(t_1)>0$ and $q_{k+1}(t_k)<0$. Since $q_{k+1}$ is odd with positive leading coefficient, the claim follows. A similar argument applies when $k$ is odd.
\end{proof}

We list the first eight polynomials of the sequence $(q_k)$ here:
\begin{alignat*}{2}
q_1(t)&=t, & \qquad\qquad  q_5(t)&=t^5-10t^3+15t, \\
q_2(t)&=t^2-1, & \qquad\qquad  q_6(t)&=t^6-15t^4+45t^2-15, \\
q_3(t)&=t^3-3t, & \qquad\qquad  q_7(t)&=t^7-21t^5+105t^3-105t, \\
q_4(t)&=t^4-6t^2+3, & \qquad\qquad  q_8(t)&=t^8-28t^6+210t^4-420t^2+105.
\end{alignat*}
%\begin{align*}
%q_1(x)&=x,\\ 
%q_2(x)&=x^2-1, \\
%q_3(x)&=x^3-3x, \\
%q_4(x)&=x^4-6x^2+3, \\
%q_5(x)&=x^5-10x^3+15x, \\
%q_6(x)&=x^6-15x^4+45x^2-15, \\
%q_7(x)&=x^7-21x^5+105x^3-105x, \\
%q_8(x)&=x^8-28x^6+210x^4-420x^2+105.
%\end{align*}

In the extremal cases of Theorem \ref{thm:alternating-infinities} below, we assume that
\begin{equation} \label{eq:not-going-to-zero}
3^n a^{n-l_n(x)}(1-2a)^{l_n(x)}\geq 1 \qquad\mbox{for all sufficiently large $n$}.
\end{equation}
Sufficient for \eqref{eq:not-going-to-zero} is that either (i) $a<1/3$ and $\lambda_*>\phi(a)$; (ii) $a=1/3$; or (iii) $1/3<a<1/2$ and $\lambda^*<\phi(a)$.

Theorem \ref{thm:alternating-pattern} in the Introduction is a special case of the following more general result.

\begin{theorem} \label{thm:alternating-infinities}
Let $0<a<1/2$. Let $t_1<t_2<\dots<t_k$ be the zeros of the polynomial $q_k$ defined by \eqref{eq:q-polynomials}, and put $\tilde{t}_i:=t_i\sqrt{2a(1-2a)}$ for $i=1,\dots,k$. Also define
\[
\delta_*:=\liminf_{n\to\f} \frac{(1-2a)n-l_n(x)}{\sqrt{n}}, \qquad \delta^*:=\limsup_{n\to\f} \frac{(1-2a)n-l_n(x)}{\sqrt{n}}.
\]
\begin{enumerate}[(a)]
\item If $\delta^*<\tilde{t}_1$ and \eqref{eq:not-going-to-zero} holds, then $M_{k,a}'(x)=(-1)^k\cdot\f$.
\item If %for some {\em even} $i\in\{1,2,\dots,k-1\}$ we have
%\begin{equation} \label{eq:between-zeros}
$\tilde{t}_{i}<\delta_*\leq\delta^*<\tilde{t}_{i+1}$ 
%\end{equation}
for some $i\in\{1,2,\dots,k-1\}$, then %$M_{k,a}'(x)=+\f$.
\[
M_{k,a}'(x)=\begin{cases}
+\f & \mbox{if $k-i$ is even},\\
-\f & \mbox{if $k-i$ is odd}.
\end{cases}
\]
%\item If \eqref{eq:between-zeros} holds for some {\em odd} $i\in\{1,2,\dots,k-1\}$, then $M_{k,a}'(x)=-\f$.
\item If $\delta_*>\tilde{t}_k$ and \eqref{eq:not-going-to-zero} holds, then $M_{k,a}'(x)=+\f$.
\item If $\delta^*<\tilde{t}_i<\delta_*$ for some $i\in\{1,2,\dots,k\}$, then $M_{k,a}$ does not have an infinite derivative at $x$.
\end{enumerate}
\end{theorem}

\begin{example} \label{ex:infinite-derivatives-M_2}
Let $k=2$. Note that $q_2(t)=t^2-1$, so $\tilde{t}_1=\sqrt{2a(1-2a)}=:c_0$ and $\tilde{t}_2=-c_0$.
Defining
