\gamma_*:=\liminf_{n\to\f} \frac{|(1-2a)n-l_n(x)|}{\sqrt{n}}, \qquad \gamma^*:=\limsup_{n\to\f} \frac{|(1-2a)n-l_n(x)|}{\sqrt{n}},
\]
we can state Theorem \ref{thm:alternating-infinities} for this case as follows:
\begin{enumerate}[(i)]
\item If $\gamma^*<c_0$,
%\begin{equation} \label{eq:square-root-inner-k2}
%\limsup_{n\to\f} \frac{|(1-2a)n-l_n(x)|}{\sqrt{n}}<c_0,
%\end{equation}
then $M_{2,a}'(x)=-\f$.
\item If \eqref{eq:not-going-to-zero} holds and $\gamma_*>c_0$,
%\begin{equation} \label{eq:square-root-outer-k2}
%\liminf_{n\to\f} \frac{|(1-2a)n-l_n(x)|}{\sqrt{n}}>c_0,
%\end{equation}
then $M_{2,a}'(x)=+\f$.
\item If $\gamma_*<c_0<\gamma^*$,
%\[
%\liminf_{n\to\f} \frac{|(1-2a)n-l_n(x)|}{\sqrt{n}}<c_0<\limsup_{n\to\f} \frac{|(1-2a)n-l_n(x)|}{\sqrt{n}},
%\]
then $M_{2,a}$ does not have an infinite derivative at $x$.
\end{enumerate}
\end{example}

\begin{example} \label{ex:infinite-derivatives-M_3}
Take $k=3$. Since $q_3(t)=t^3-3t$, we have $\tilde{t}_1=-c_0'$, $\tilde{t}_2=0$ and $\tilde{t}_3=c_0'$, where $c_0':=\sqrt{6a(1-2a)}$. Thus, Theorem \ref{thm:alternating-infinities} implies:
\begin{enumerate}[(i)]
\item If either $\delta_*>c_0'$ and \eqref{eq:not-going-to-zero} holds, or $-c_0'<\delta_*\leq\delta^*<0$,
then $M_{3,a}'(x)=+\f$.
\item If either $\delta^*<-c_0'$ and \eqref{eq:not-going-to-zero} holds, or $0<\delta_*\leq\delta^*<c_0'$,
then $M_{3,a}'(x)=-\f$.
\end{enumerate}
\end{example}

We give one more example, because it illustrates a qualitative difference between $k\equiv 0 \pmod 4$ and $k\equiv 2 \pmod 4$.

\begin{example} \label{ex:infinite-derivatives-M_4}
Take $k=4$. The roots of $q_4(t)=t^4-6t+3$ are $\pm \sqrt{3-\sqrt{6}}$ and $\pm \sqrt{3+\sqrt{6}}$. Hence, setting
\[
c_1:=\sqrt{2a(1-2a)(3-\sqrt{6})}, \qquad c_2:=\sqrt{2a(1-2a)(3+\sqrt{6})},
\]
we have $\tilde{t}_1=-c_2, \tilde{t}_2=-c_1, \tilde{t}_3=c_1$ and $\tilde{t}_4=c_2$.
Define $\gamma_*$ and $\gamma^*$ as in Example \ref{ex:infinite-derivatives-M_2}. Theorem \ref{thm:alternating-infinities} implies:
\begin{enumerate}[(i)]
\item If either \eqref{eq:not-going-to-zero} holds and $\gamma_*>c_2$, or $\gamma^*<c_1$,
then $M_{4,a}'(x)=+\f$.
\item If 
\[
c_1<\delta_*\leq\delta^*<c_2 \qquad\mbox{or}\qquad -c_2<\delta_*\leq\delta^*<-c_1,
\]
then $M_{4,a}'(x)=-\f$.
\end{enumerate}
\end{example}

Before proving the theorem we need a few lemmas. Recall that the polynomials $P_k(n,l)$ were defined in Lemma \ref{lem:ternary-increments}.

\begin{lemma} \label{lem:P-recursion}
For all $k\in\NN$ we have the recursion
\begin{equation} \label{eq:P-recursion}
P_{k+1}(n,l)=a(1-2a)\frac{\partial P_k}{\partial a}(n,l)+\{(1-2a)n-l-(1-4a)k\}P_k(n,l).
\end{equation}
\end{lemma}

\begin{proof}
Since $n$ and $l$ are fixed, we write $\Delta_{k,a}:=\Delta_{k,a}(I_{n,j})$, where $j$ is such that $l(j)=l$. By Lemma \ref{lem:ternary-increments}, $\Delta_{k,a}=a^{n-l-k}(1-2a)^{l-k}P_k(n,l)$. Differentiating with respect to $a$ and simplifying gives
\begin{align*}
\Delta_{k+1,a}=\frac{\partial\Delta_{k,a}}{\partial a} &= a^{n-l-k-1}(1-2a)^{l-k-1}\bigg(a(1-2a)\frac{\partial P_k}{\partial a}(n,l)\\
& \qquad\qquad\qquad +\{(1-2a)n-l-(1-4a)k\}P_k(n,l)\bigg).
\end{align*}
Applying Lemma \ref{lem:ternary-increments} in reverse yields the result.
\end{proof}

\begin{lemma} \label{lem:polynomial-convergence}
Let $(l_n)$ be any sequence of integers such that $0\leq l_n\leq n$. Then
\[
P_k(n,l_n)\sim \big(2a(1-2a)n\big)^{k/2}q_k\left(\frac{(1-2a)n-l_n}{\sqrt{2a(1-2a)n}}\right) \qquad \mbox{as $n\to\f$},
\]
where, as usual, $a_n\sim b_n$ means that $a_n/b_n\to 1$ as $n\to\f$.
%Fix $t\in\RR$, and let 
%$$l_n:=(1-2a)n-t\sqrt{2a(1-2a)n}.$$ 
%Then for each $k\in\NN$,
%\[
%\lim_{n\to\f} n^{-k/2}P_k(n,l_n)=\big(2a(1-2a)\big)^{k/2}q_k(t).
%\]
\end{lemma}

\begin{proof}
Put $g(n):=(1-2a)n-l_n$. We will prove the statement by induction using the previous lemma. In fact, we will prove a bit more, namely
\begin{equation} \label{eq:polynomial-derivative-convergence}
\frac{\partial^j P_k}{\partial a^j}(n,l_n)\sim n^{(k+j)/2}\big(2a(1-2a)\big)^{(k-j)/2}(-2)^j q_k^{(j)}\left(\frac{g(n)}{\sqrt{2a(1-2a)n}}\right)
\end{equation}
for $j=0,1,\dots,k$, where $q_k^{(j)}$ denotes the $j$th derivative of $q_k$. Setting $j=0$ then gives the lemma.

We will need the following linear recursion for $q_k^{(j)}$:
\begin{equation} \label{eq:q-derivative-recursion}
q_{k+1}^{(j)}(t)=-q_k^{(j+1)}(t)+tq_k^{(j)}(t)+jq_k^{(j-1)}(t).
\end{equation}
For $j=0$ this is just the definition of $q_{k+1}$, provided we put $q_k^{(-1)}\equiv 0$. For $j\geq 1$ it follows readily by induction.

Observe that \eqref{eq:polynomial-derivative-convergence} holds for $k=1$, as $q_1(t)=t$ and
$P_1(n,l_n)=(1-2a)n-l_n$. 
Suppose \eqref{eq:polynomial-derivative-convergence} holds for $k$. Differentiating \eqref{eq:P-recursion} $j$ times with respect to $a$ gives
\begin{align*}
\frac{\partial^j P_{k+1}}{\partial a^j}(n,l) &=a(1-2a)\frac{\partial^{j+1}P_{k}}{\partial a^{j+1}}(n,l) + \{(1-2a)n-l-(1-4a)(k-j)\}\frac{\partial^j P_k}{\partial a^j}(n,l) \\
& \qquad\qquad - \left(2jn-4\sum_{\nu=k-j+1}^k\nu\right)\frac{\partial^{j-1}P_{k}}{\partial a^{j-1}}(n,l),
\end{align*}
for $j\geq 1$. Substituting $l=l_n$ and discarding constant terms yields
\[
\frac{\partial^j P_{k+1}}{\partial a^j}(n,l_n)\sim a(1-2a)\frac{\partial^{j+1}P_{k}}{\partial a^{j+1}}(n,l_n) + g(n)\frac{\partial^j P_k}{\partial a^j}(n,l_n)
 -2jn \frac{\partial^{j-1}P_{k}}{\partial a^{j-1}}(n,l_n).
\]
Applying the induction hypothesis \eqref{eq:polynomial-derivative-convergence} to each term on the right hand side and using \eqref{eq:q-derivative-recursion}, we see that \eqref{eq:polynomial-derivative-convergence} holds for $k+1$ in place of $k$, as desired.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:alternating-infinities}]
We will prove ({\em b}) for the case when $k-i$ is even. Let us assume $k$ and $i$ are both odd; the case when both are even is similar. Without loss of generality we may take $i=1$; the assumption then is that $\tilde{t}_1<\delta_*\leq\delta^*<\tilde{t}_2$. Then for some $\eps>0$ and all sufficiently large $n$ we have
\begin{equation} \label{eq:sandwich}
(\tilde{t}_1+\eps)\sqrt{n}\leq (1-2a)n-l_n\leq (\tilde{t}_2-\eps)\sqrt{n}.
\end{equation}
%In fact, we will show that $M_{k,a}'(x)=+\f$ under the weaker assumption
%\begin{equation} \label{eq:sandwich}
%(1-2a)-l_n-\tilde{t}_1\sqrt{n}\to\f \qquad \mbox{and} \qquad (1-2a)-l_n-\tilde{t}_2\sqrt{n}\to-\f.
%\end{equation}
By the symmetry argument outlined at the end of the proof of Theorem \ref{thm:infinite-derivatives}, it suffices to show that $M_{k,a}$ has an infinite right derivative.

Observe that $q_k(t)>0$ for $t\in(t_1,t_2)$. Let 
\[
g(n):=(1-2a)n-l_n, \qquad \tilde{g}(n):\frac{g(n)}{\sqrt{2a(1-2a)n}}, \qquad \tilde{\eps}:=\frac{\eps}{\sqrt{2a(1-2a)n}}.
\]
By \eqref{eq:sandwich}, $t_1+\tilde{\eps}<\tilde{g}(n)<t_2-\tilde{\eps}$ for all large enough $n$. 
%and so $q_k(\tilde{g}(n))>0$ (for large enough $n$). %But to conclude that $P_k(n,l_n)\to\f$ we need to be a bit more precise.
%If for some subsequence $(n_i)$ we have $\tilde{g}(n_i)\to t_1$, then the Mean Value Theorem, along with $q_k(t_1)=0$ gives that
%\[
%\frac{q_k(\tilde{g}(n_i))}{\tilde{g}(n_i)-t_1}\to q_k'(t_1)>0
%\]
%(as $q_k$ does not have double roots), so that $q_k(\tilde{g}(n_i))>1/2 q_k'(t_1)(\tilde{g}(n_i)-t_1)$ for all sufficiently large $i$. This implies, by Lemma \ref{lem:polynomial-convergence} and \eqref{eq:sandwich}, that
%\begin{align*}
%P_k(n_i,l_{n_i})&\sim \big(2a(1-2a)n_i\big)^{k/2}q_k(\tilde{g}(n_i))\\
%&>1/2 q_k'(t_1)\big(2a(1-2a)n_i\big)^{(k-1)/2}\{g(n_i)-\tilde{t}_1\sqrt{n_i}\}\to\f.
%\end{align*}
%Similarly, $P_k(n_i,l_{n_i})\to\f$ if $\tilde{g}(n_i)\to t_2$. If no subsequence of $(\tilde{g}(n))$ converges to either $t_1$ or $t_2$, then there is a $\delta>0$ such that $\min\{\tilde{g}(n)-t_1,t_2-\tilde{g}(n)\}\geq\delta$ for all large enough $n$, and therefore 
Thus, 
$$q_k(\tilde{g}(n))\geq \min\{q_k(t_1+\tilde{\eps}),q_k(t_1-\tilde{\eps})\}>0$$ 
for all large enough $n$, as $q_k$ is unimodal over $(t_1,t_2)$. Hence, Lemma \ref{lem:polynomial-convergence} yields $P_k(n,l_{n})\to\f$, and in fact,
\begin{equation} \label{eq:P_k-estimate}
P_k(n,l_n)\geq \delta n^{k/2} \qquad\mbox{for all large enough $n$},
\end{equation}
where $\delta>0$ is a constant depending only on $a$ and $\eps$.

Observe that, if $l_n$ is replaced with $l_n':=l_n+c_n$ for some bounded sequence $(c_n)$, then \eqref{eq:sandwich} holds also for $l_n'$ in place of $l_n$, so the same argument shows that $P_k(n,l_n+c_n)\to\f$ as well. Even more is true, namely,
\begin{equation} \label{eq:bounded-sequence-equivalence}
P_k(n,l_n+c_n)\sim P_k(n,l_n).
\end{equation}
This is clear if $g(n)\to\pm\f$. But when $k$ is odd, $(g(n))$ cannot have a bounded subsequence in view of \eqref{eq:sandwich} since $(t_1,t_2)$ does not contain $0$. (When $k$ is even, $(t_1,t_2)$ can contain $0$ and so $(g(n))$ can have a bounded subsequence, but even then \eqref{eq:bounded-sequence-equivalence} still holds because $q_k(0)\neq 0$.)

In fact, the sequence $(c_n)$ may even tend to $\pm\f$, as long as it does so more slowly than $\sqrt{n}$. In that case, we have, instead of \eqref{eq:sandwich},
\[
\left(\tilde{t}_1+\frac{\eps}{2}\right)\sqrt{n}\leq g(n)\pm c_n\leq \left(\tilde{t}_2-\frac{\eps}{2}\right)\sqrt{n}
\]
for all large enough $n$, and we conclude \eqref{eq:bounded-sequence-equivalence} in the same way. We will need this fact later on in the proof.

Now let $h>0$ be given, and take $n\in\NN$ such that $3^{-n+1}\leq h<3^{-n+2}$. Let $j$ and $j'$ be the integers such that $x\in I_{n,j}$ and $x+h\in I_{n,j'}$. Then $3\leq j'-j\leq 9$. For $i\in\NN$, let $l(i)$ denote the number of $1$'s in the ternary representation of $i$. Since $|l(i+3^\nu)-l(i)|=1$ for all $i$ and $\nu=0,1,2,\dots$, it follows that
\begin{equation} \label{eq:l-difference}
|l(i)-l(j)|\leq 4 \qquad\mbox{for $i=j,j+1,\dots,j'$}.
\end{equation}
Define constants
\[
b:=\max\{a,1-2a\}, \qquad r:=\min\left\{\frac{a}{1-2a},\frac{1-2a}{a}\right\}.
\]
By Lemma \ref{lem:ternary-increments}, we may write
\[
\Delta_{k,a}(I_{n,i})=a^{n-l(i)-k}(1-2a)^{l(i)-k}P_k(n,l(i)).
\]
By \eqref{eq:l-difference} and \eqref{eq:bounded-sequence-equivalence}, there is an $n_0\in\NN$ such that
\[
P_k(n,l(i))\geq \frac12 P_k(n,l_n) \qquad \mbox{for all $j\leq i\leq j'$ and all $n>n_0$}.
\]
Again using \eqref{eq:l-difference}, it follows from \eqref{eq:P_k-estimate} that
\begin{align}
\begin{split}
\Delta_{k,a}(I_{n,i})&\geq \frac12 r^4 a^{n-l_n-k}(1-2a)^{l_n-k}P_k(n,l_n), \\
&\geq \frac12 r^4 a^{n-l_n-k}(1-2a)^{l_n-k}\delta n^{k/2}, \qquad i=j,\dots,j'.
\end{split}
\label{eq:Delta-lower-estimate}
\end{align}

We have established that the increments over the ternary intervals of order $n$ between $x$ and $x+h$ are large. Furthermore, $x$ and $x+h$ are separated by at least one full ternary interval of order $n$. Next, we must make sure that the oscillations of $M_{k,a}$ over $I_{n,j}$ and $I_{n,j'}$ are not too much bigger than the increments over these intervals, so that $M_{k,a}(x)$ is not too much bigger than $M_{k,a}((j+1)3^{-n})$ and $M_{k,a}(x+h)$ is not too much smaller than $M_{k,a}(j'3^{-n})$. Unfortunately, we do not have an analogue of Lemma \ref{prop:box-containment} for $a<1/2$, so the analysis is by necessity somewhat more technical.

Let $m:=m_n:=\lfloor n^{1/4}\rfloor$, and note that for any $y\in J:=\bigcup_{i=j}^{j'}I_{n,i}$, we have $|l_{n+m_n}(y)-l_{n+m_n}(x)|\leq m_n$. Hence, by \eqref{eq:bounded-sequence-equivalence} applied to $n+m_n$ in place of $n$, we see that
\[
P_k(n+m_n,l_{n+m_n}(y))>\frac12 P_k(n+m_n,l_{n+m_n}(x))>0 \qquad \forall y\in J.
\]
Thus,
\begin{equation} \label{eq:nonnegative-increments}
\Delta_{k,a}(I_{n+m,\nu})\geq 0 \qquad \mbox{for $\nu=3^m j, \dots, 3^m(j'+1)-1$},
\end{equation}
i.e., the increments over the ternary intervals of order $n+m$ in $J$ are nonnegative.
Now we use Lemma \ref{lem:oscillation-bounds} to estimate, for $0\leq\nu<3^m$,
\begin{align*}
\osc(M_{k,a};I_{n+m,3^m j+\nu})&\leq a^{n+m-l(3^m j+\nu)}(1-2a)^{l(3^m j+\nu)}C_k(n+m)^k\\
&\leq a^{n-l_n}(1-2a)^{l_n}b^m C_k(n+m)^k,
\end{align*}
where we used that $l(3^m j+\nu)\geq l(j)=l_n$. Similarly,
\begin{align*}
\osc(M_{k,a};I_{n+m,3^m j'+\nu})&\leq a^{n+m-l(3^m j'+\nu)}(1-2a)^{l(3^m j'+\nu)}C_k(n+m)^k\\
&\leq a^{n-l(j')}(1-2a)^{l(j')}b^m C_k(n+m)^k\\
&\leq r^{-4}a^{n-l_n}(1-2a)^{l_n}b^m C_k(n+m)^k,
\end{align*}
where the last inequality used \eqref{eq:l-difference}. %Since $Q_k(n)$ is a polynomial in $n$ of degree $k$, we may assume for simplicity that $Q_k(n)=D_k n^k$ for some constant $D_k$, and hence, 
%\begin{equation} \label{eq:Q-estimate}
%Q_k(n+m)=D_k(n+m)^k\leq 2^k D_k n^k.
%\end{equation}
Since $m\leq n$ and $x$ lies in one of the intervals $I_{n+m,3^m j+\nu}$ for $0\leq\nu<3^m$, it follows by \eqref{eq:nonnegative-increments} that
\[
M_{k,a}(x)\leq M_{k,a}\left(\frac{j+1}{3^n}\right)+b^m a^{n-l_n}(1-2a)^{l_n}C_k 2^k n^k,
\]
and likewise, since $x+h$ lies in one of the intervals $I_{n+m,3^m j'+\nu}$ for $0\leq\nu<3^m$,
\[
M_{k,a}(x+h)\geq M_{k,a}\left(\frac{j'}{3^n}\right)-r^{-4}b^m a^{n-l_n}(1-2a)^{l_n}C_k 2^k n^k.
\]
Hence,
\begin{align*}
M_{k,a}(x+h)-M_{k,a}(x)&\geq M_{k,a}\left(\frac{j'}{3^n}\right)-M_{k,a}\left(\frac{j+1}{3^n}\right)\\
& \qquad -(1+r^{-4})b^m a^{n-l_n}(1-2a)^{l_n}C_k 2^k n^k\\
&\geq \Delta_{k,a}(I_{n,j+1})-(1+r^{-4})b^m a^{n-l_n}(1-2a)^{l_n}C_k 2^k n^k,
\end{align*}
where we used that $j'\geq j+3$ and $\Delta_{k,a}(I_{n,i})\geq 0$ for $i=j,\dots,j'$. Finally, applying \eqref{eq:Delta-lower-estimate}, we obtain
\begin{align*}
M_{k,a}(x+h)-M_{k,a}(x)&\geq a^{n-l_n}(1-2a)^{l_n}\left\{1/2 r^4\delta n^{k/2}-(1+r^{-4})b^m C_k 2^k n^k\right\}\\
&\geq a^{n-l_n}(1-2a)^{l_n}n^{k/2} \cdot\frac14 r^4\delta,
\end{align*}
for all sufficiently large $n$, since $b^{m_n}n^{k/2}\to 0$ as $n\to\f$. (Recall $m_n=\lfloor n^{1/4}\rfloor$.) 
Note that \eqref{eq:not-going-to-zero} holds in view of \eqref{eq:where-is-phi-1} and \eqref{eq:where-is-phi-2}, because the hypothesis $\tilde{t}_1<\delta_*\leq\delta^*<\tilde{t}_2$ implies that $l_n(x)/n\to 1-2a$.
Recalling that $h<3^{-n+2}$, we conclude that
\begin{equation} \label{eq:final-inequality}
\frac{M_{k,a}(x+h)-M_{k,a}(x)}{h}\geq 3^{n-2} a^{n-l_n}(1-2a)^{l_n}n^{k/2} \cdot\frac14 r^4\delta^k\to\f
\end{equation}
as $n\to\f$. This proves ({\em b}). For ({\em a}) and ({\em c}), observe that the hypotheses do not imply that $l_n(x)/n\to 1-2a$, so we additionally assume \eqref{eq:not-going-to-zero} to ensure \eqref{eq:final-inequality}.

It remains to prove ({\em d}). Suppose $\delta_*<\tilde{t}_i<\delta^*$ for some $i\in\{1,2,\dots,k\}$. Then, as can be seen from the above argument, $P_k(n,l_n)$ oscillates around $0$ infinitely many times, and hence, so does $\Delta_{k,a}(I_n(x))$. Therefore, $M_{k,a}$ cannot have an infinite derivative at $x$.
\end{proof}

\begin{remark}
{\rm
For $a=1/3$, Dalaklis et al.~\cite{Dalaklis} showed that $M_{1,1/3}'(x)=\f$ (resp. $-\f$) if and only if $n-3l_n(x)\to\f$ (resp. $-\f$). This condition is weaker than the one in Theorem \ref{thm:alternating-infinities}. Unfortunately, we have not been able to either prove or disprove a similar result for $k=1$ and $a\neq 1/3$. For $k\geq 2$, however, it is clear from Theorem \ref{thm:alternating-infinities} that if one knows only that $n-3l_n(x)\to\f$, then $M_{k,1/3}'(x)$ can be either $+\f$ or $-\f$ or $M_{k,1/3}$ may not have an infinite derivative at all; finer information, about the asymptotics of $(n-3l_n)/\sqrt{n}$, is needed.
}
\end{remark}


