The situation is different for $k=4$. By Example \ref{ex:infinite-derivatives-M_4}, a necessary condition for $M_{4,a}'(x)=-\f$ is that either
\[
c_1\leq\delta_*\leq\delta^*\leq c_2 \qquad\mbox{or}\qquad -c_2\leq\delta_*\leq\delta^*\leq -c_1.
\]
Although the set (call it $E$) of points $x$ satisfying this condition is clearly uncountable, its dimension should be very small, if not zero. For instance, if $c_1\leq\delta_*\leq\delta^*\leq c_2$, we must have, for every $\eps>0$,
\[
(1-2a)n-(c_2+\eps)\sqrt{n}<l_n<(1-2a)n-(c_1-\eps)\sqrt{n} \qquad\mbox{for all $n$ sufficiently large}.
\] 
This is a very tight restriction, hence $E$ is a very small subset of the set $\{x: l_n(x)/n\to 1-2a\}$. In fact, we do not know whether $\dim_H D_{4,a}^{-\f}>0$.



\section{Infinite derivatives: $a>1/2$} \label{sec:infinite-derivative-high}

The situation regarding infinite derivatives is very different when $a>1/2$. The reason is, that if the ternary expansion of $x$ has infinitely many $1$'s, then the increments $\Delta_{k,a}(I_n(x))$ change sign infinitely many times in view of Lemma \ref{lem:ternary-increments}, because $1-2a<0$. Therefore, the only points at which there can possibly be an infinite derivative are those whose ternary expansion has only a finite number of $1$'s. This condition is necessary, but not sufficient, as we will see below. Contrary to the case $a<1/2$ studied in the previous section, the polynomial $P_k(n,l)$ behaves much more regularly here: Depending on the parity of $k$, there is an integer $n_0\in\NN$ such that either $P_k(n,l)>0$ for all $n\geq n_0$ and all $l\leq n$, or $P_k(n,l)>0$ for all $n\geq n_0$ and all $l\leq n$.

\begin{lemma} \label{lem:alternating-slopes}
Assume $a>1/2$. There is an integer $n_0\in\NN$ such that for all $n>n_0$, the signs of $\Delta_{k,a}(I_{n,j})$ alternate: that is, 
\[
\sgn(\Delta_{k,a}(I_{n,j+1}))=-\sgn(\Delta_{k,a}(I_{n,j})), \qquad j=0,1,\dots,3^n-2. 
\]
Furthermore, for each $n>n_0$ and $0\leq j<3^n$, we have that
\begin{equation} \label{eq:zigzag}
|\Delta_{k,a}(I_{n+1,3j})|=|\Delta_{k,a}(I_{n+1,3j+2})|>|\Delta_{k,a}(I_{n+1,3j+1})|.
\end{equation}
\end{lemma}

Thus, for all sufficiently large $n$, the $n$th piecewise linear approximation of $M_{k,a}$ follows the same `zig zag' pattern as Okamoto's function itself.

\begin{proof}
Observe that $(1-2a)n-l<0$ for all $n$ and $l$, and its absolute value increases with $l$. Thus, $|(1-2a)n-l|^k\geq n^k(2a-1)^k$. Furthermore, there is a constant $C>0$ such that $R_k(n,l)\leq Cn^{k-1}$ for all $n$ and all $l\leq n$, where $R_k(n,l)$ is the polynomial from Lemma \ref{lem:ternary-increments}. Put
\[
n_0:=\frac{C}{(2a-1)^k}.
\]
Then $|(1-2a)n-l|^k>R_k(n,l)$ for all $n>n_0$ and all $l\leq n$, so for $n>n_0$ the sign of $P_k(n,l)$ is the same as the sign of $\{(1-2a)n-l\}^k$; that is, $P_k(n,l)>0$ if $k$ is even, and $P_k(n,l)<0$ if $k$ is odd. Therefore, the sign of $\Delta_{k,a}(I_{n,j})$ is equal to $(-1)^k$ times the sign of $(1-2a)^{l(j)}$. Since $|l(j+1)-l(j)|=1$ for all $j$, this proves the alternating signs statement. In addition, we see that $|P_k(n,l)|\to\infty$ as $n\to\infty$, uniformly in $l$.

Next, since $a>1/2$ implies $a>2a-1=|1-2a|$, we can choose $\eps>0$ so that
\[
\frac{a}{|1-2a|}>1+\eps,
\]
and then we can find $n_1\in\NN$ such that
\[
(1+\eps)^{-1}<\frac{P_k(n,l+1)}{P_k(n,l)}<1+\eps \qquad \forall n>n_1,\ \forall l\leq n.
\]
Together with Lemma \ref{lem:ternary-increments}, this establishes \eqref{eq:zigzag}, because
\[
\frac{\Delta_{k,a}(I_{n+1,3j+1})}{\Delta_{k,a}(I_{n+1,3j})}=\frac{|1-2a|}{a}\cdot\frac{P_k(n+1,l(j)+1)}{P_k(n+1,l(j))}.
\]
\end{proof}

We see from the above proof that for all large enough $n$, $P_k(n,l)$ has the same sign as $(1-2a)^{-k}$. Hence, $\Delta_{k,a}(I_{n,j})$ has the same sign as $(1-2a)^{l(j)}$ for all large enough $n$.

For $d,\xi\in\{0,1,2\}$, define
\[
\delta_d(\xi):=\begin{cases}
1 & \mbox{if $\xi=d$},\\
0 & \mbox{otherwise}.
\end{cases}
\]

\begin{proposition} \label{prop:limsup-conditions}
Assume $a>1/2$. Let $x=(0.x_1x_2\dots)_3$, and assume that $l:=\sup_{n\in\NN} l_n(x)<\infty$. Put
\[
L_a^+(x):=\limsup_{n\to\f} \sum_{j=1}^\f a^{j}\delta_2(x_{n+j}).
\]
In order that $M_{k,a}$ have an infinite right derivative at $x$ it is sufficient that $L_a^+(x)<1$, and it is necessary that $L_a^+(x)\leq 1$. Furthermore, if $M_{k,a}$ has an infinite right derivative at $x$, then $(M_{k,a})_+'(x)=(-1)^{l}\cdot\f$.
\end{proposition}

\begin{proof}
Let $N_0$ be the position of the last 1 in $(x_i)$, and put $E:=\{n>N_0: x_n=0\}$. For each $n\in E$, put $z_n:=0.x_1\dots x_{n-1}20^\f$. Then $z_n>x$ and $3^{-n}<z_n-x<2\cdot 3^{-n}$. As in the proof of Theorem \ref{thm:infinite-derivatives-half}, in order that $M_{k,a}$ has an infinite right derivative at $x$, it is necessary and sufficient that
\begin{equation*} %\label{eq:the-critical-sequence-b}
\frac{M_{k,a}(z_n)-M_{k,a}(x)}{z_n-x}\to\pm\f.
\end{equation*}
This is a consequence of Lemma \ref{lem:alternating-slopes}; we refer to the argument in the above-mentioned proof.

%We use the following explicit expression for $F_a(x)$ (see \cite{Kobayashi}): 
%\begin{equation}
%F_a(x)=\sum_{j=1}^\infty a^{j-1-l_{j-1}(x)}(1-2a)^{l_{j-1}(x)}q(x_j),
%\label{eq:explicit-expression}
%\end{equation}
%where $q(0)=0$, $q(1)=a$ and $q(2)=1-a$. 
Take $n\in E$. Then Lemma \ref{lem:Okamoto-series} implies
\[
F_a(z_n)-F_a(x)=a^{n-l-1}(1-a)(1-2a)^l-\sum_{j=n+1}^\f a^{j-l-1}(1-a)(1-2a)^l\delta_2(x_j).
\]
Differentiating $k$ times with respect to $a$ gives
\begin{align*}
M_{k,a}&(z_n)-M_{k,a}(x)=\sum_{i=0}^k\binom{k}{i}\frac{\partial^i}{\partial a^i}(a^{n-l-1}-a^{n-l})\cdot\frac{\partial^{k-i}}{\partial a^{k-i}}(1-2a)^l\\
&\qquad\qquad\qquad\qquad -\sum_{j=n+1}^\f \sum_{i=0}^k\binom{k}{i}\frac{\partial^i}{\partial a^i}(a^{j-l-1}-a^{j-l})\cdot\frac{\partial^{k-i}}{\partial a^{k-i}}(1-2a)^l\delta_2(x_j)\\
&=\sum_{i=0}^k\binom{k}{i}\left(\pi_{n-l-1,i}a^{n-l-i-1}-\pi_{n-l,i}a^{n-l-i}\right)\pi_{l,k-i}(-2)^{k-i}(1-2a)^{l-k+i}\\
& \quad -\sum_{j=n+1}^\f \sum_{i=0}^k\binom{k}{i}\left(\pi_{j-l-1,i}a^{j-l-i-1}-\pi_{j-l,i}a^{j-l-i}\right)\pi_{l,k-i}(-2)^{k-i}(1-2a)^{l-k+i}\delta_2(x_j),
\end{align*}
where, for nonnegative integers $n$ and $m$ with $n\geq m$, we denote
\[
\pi_{n,m}:=\frac{n!}{m!}=n(n-1)\cdots(n-m+1).
\]
After reindexing, the summation over $j$ can be written as
\begin{align*}
\sum_{m=1}^\f \sum_{i=0}^k\binom{k}{i}&\left(\pi_{n+m-l-1,i}a^{n+m-l-i-1}-\pi_{n+m-l,i}a^{n+m-l-i}\right)  \\
& \qquad \times \pi_{l,k-i}(-2)^{k-i}(1-2a)^{l-k+i}\delta_2(x_{n+m}).
\end{align*}
Thus, $M_{k,a}(z_n)-M_{k,a}(x)$ takes the form
\[
M_{k,a}(z_n)-M_{k,a}(x)=a^{n-l-k-1}(1-2a)^{l}\left(c_k^{(n)} n^k+c_{k-1}^{(n)}n^{k-1}+\dots+c_1^{(n)} n+c_0^{(n)}\right),
\]
for certain coefficients $c_k^{(n)},\dots,c_0^{(n)}$ that depend on $n$ only through $\{\delta_2(x_{n+m}): m\in\NN\}$ and are therefore bounded. In particular,
\[
c_k^{(n)}=(1-a)\left(1-\sum_{m=1}^\f a^m\delta_2(x_{n+m})\right),
\]
as only the terms with $i=k$ include a term $n^k$. If $L_a^+(x)=\limsup_{n\to\f}a^m\delta_2(x_{n+m})<1$, then $c_k^{(n)}$ is bounded away from $0$, and so the sign of $M_{k,a}(z_n)-M_{k,a}(x)$ is eventually determined by the dominant term $c_k^{(n)} n^k$, so there is a constant $\eps>0$ such that 
\[
|M_{k,a}(z_n)-M_{k,a}(x)|\geq a^{n-l-k-1}(1-a)|1-2a|^l\eps n^k 
\]
for all sufficiently large $n\in E$. Since furthermore $z_n-x<2\cdot 3^{-n}$ and $(3a)^n\to\f$, it follows that $(M_{k,a})_+'(x)=(-1)^l\cdot\f$.

On the other hand, suppose $L_a^+(x)>1$. Then there is a subsequence $(n_i)$ and a constant $\eps>0$ such that $c_k^{(n_i)}<-(1-a)\eps$ for all $i$, which implies that $M_{k,a}(z_{n_i})-M_{k,a}(x)$ has the opposite sign to $(1-2a)^l$ for all sufficiently large $i$. If $M_{k,a}$ were to have an infinite derivative at $x$, say $+\f$, we would need to have the secant slope $3^n\Delta_{k,a}(I_n(x))=3^n a^{n-l-k}(1-2a)^{l-k}P_k(n,l)$ tending to $+\f$ as well. But the sign of $M_{k,a}(z_{n_i})-M_{k,a}(x)$ is the opposite of the sign of $\Delta_{k,a}(I_{n_i}(x))$. Hence, $M_{k,a}$ does not have an infinite derivative at $x$.
\end{proof}

