% \subsection{Mode sum expressions for the Hertz potential}

Because the rescaled Hertz potentials satisfy the Teukolsky equations and their adjoints, e.g.,
\begin{align}
    \mathcal{O}^\dagger_4 \zeta^{4}\Phi_0 &= \zeta^{4} \mathcal{O}_{0} \Phi_0,
    &
    \mathcal{O}^\dagger_0 \zeta^{4}\Phi_4 &= \zeta^{4} \mathcal{O}_{4}\Phi_4,
\end{align}
(see Appendix \ref{app:GHP}),
they can be expressed in mode-sum forms comparable to \eqref{eqn:Weylmodesum},
\begin{subequations} \label{eqn:Hertzmodesum}
    \begin{align}
    \Phi_{\pm 2}^\mathcal{G} &= \Phi_{\pm 2}^{\mathcal{G},\mathcal{I}} \Theta(r-r_p(t)) + \Phi_{\pm 2}^{\mathcal{G},\mathcal{H}} \Theta(r_p(t)-r),
    \\
    \Phi_{\pm 2}^{\mathcal{G},\mathcal{J}} &= \sum_{jm\omega} \Phi^{\mathcal{G},\mathcal{J}}_{\pm 2jm\omega}(r)S_{\pm 2jm\omega}(z) e^{i(m\phi - \omega t)},
\end{align}
\end{subequations}
where $\mathcal{G} = \{\mathrm{I}, \mathrm{O}, \mathrm{S}, \mathrm{A}\}$ as before,
\begin{subequations}
\begin{align}
    \Phi_{-2}^{\mathrm{I},\mathcal{J}} &= \zeta^4 \Phi_4^\mathrm{I},
    &
    \Phi_{+2}^{\mathrm{O},\mathcal{J}} &= \Phi_0^\mathrm{O},
    \\
    \Phi_{-2}^{\mathrm{S},\mathcal{J}} &= \zeta^4 \Phi_4^\mathrm{S},
    &
    \Phi_{+2}^{\mathrm{S},\mathcal{J}} &= \Phi_0^\mathrm{S},
    \\
    \Phi_{-2}^{\mathrm{A},\mathcal{J}} &= \zeta^4 \Phi_4^\mathrm{A},
    &
    \Phi_{-2}^{\mathrm{A},\mathcal{J}} &= \Phi_0^\mathrm{A},
\end{align}
\end{subequations}
and $\Phi^{\mathcal{G},\mathcal{J}}_{\pm 2jm\omega}(r) = \mathcal{Z}^{\mathcal{G},\mathcal{J}}_{\pm 2jm\omega} {R}^\mathcal{J}_{\pm 2 jm \omega}(r)$ are solutions to the radial Teukolsky equation with complex amplitudes $\mathcal{Z}^{\mathcal{G},\mathcal{J}}_{\pm 2jm\omega}$.

To determine the Hertz amplitudes $\mathcal{Z}^{\mathrm{G},\mathcal{J}}_{\pm 2jm\omega}$, we insert \eqref{eqn:Hertzmodesum} into \eqref{eqn:hertzEqns}. Using the symmetries of the mode functions (see Appendix \ref{app:symmetries}) and the Teukolsky-Starobinsky identities (see Appendix \ref{app:TS}), the Hertz amplitudes can be expressed in terms of the asymptotic amplitudes of $\psi_0$ and $\psi_4$,
\begin{subequations} \label{eqn:hertzAmpRG1}
    \begin{align}
        \mathcal{Z}^{\mathrm{I},\mathcal{J}}_{-2jm\omega} &= (-1)^{j+m+k}  \frac{2{Z}^\mathcal{J}_{+2jm\omega}}{{\alpha}^{\mathrm{TS},\mathcal{J}}_{+2jm\omega}} 
        \\
        &= (-1)^{j+m+k}  \frac{8{Z}^\mathcal{J}_{-2jm\omega}}{{C}^\mathrm{TS}_{jm\omega}},
        \\
        \mathcal{Z}^{\mathrm{O},\mathcal{J}}_{+2jm\omega} &= (-1)^{j+m+k}  \frac{32{Z}^\mathcal{J}_{-2jm\omega}}{{\alpha}^{\mathrm{TS},\mathcal{J}}_{-2jm\omega}} 
        \\
        &= (-1)^{j+m+k}  \frac{8{Z}^\mathcal{J}_{+2jm\omega}}{\overline{{C}^\mathrm{TS}_{jm\omega}}},
    \end{align}
\end{subequations}
where the Teukolsky-Starobinsky constant ${C}^\mathrm{TS}_{jm\omega}$ is defined in Eq.~\eqref{eqn:CTS}.
% where we have made use of the fact that $\overline{{\alpha}^\mathcal{J}_{\pm 2j-m-\omega}} = {\alpha}^\mathcal{J}_{\pm 2jm\omega}$ and ${\alpha}^\mathcal{J}_{-2jm\omega} {\alpha}^\mathcal{J}_{+2jm\omega} = |{C}_{jm\omega}|^2$.
% 
For the symmetric and antisymmetric reconstruction procedures, we arrive at similarly simple forms,
\begin{subequations} \label{eqn:hertzAmpRG2}
    \begin{align}
        \mathcal{Z}^{S,\mathcal{J}}_{\pm 2jm\omega} &= (-1)^{j+m+k}  \frac{4{Z}^\mathcal{J}_{\pm 2jm\omega}}{\mathrm{Re} \left[C^\mathrm{TS}_{jm\omega} \right]},
        \\ \label{eqn:minuSRGamp}
        \mathcal{Z}^{A,\mathcal{J}}_{\pm 2jm\omega} &= -\frac{{Z}^\mathcal{J}_{\pm 2jm\omega}}{3iM\omega}.
    \end{align}
\end{subequations}
Note that, as mentioned in Sec.~\ref{sec:intro}, \eqref{eqn:minuSRGamp} breaks down for static ($\omega=0$) modes.

Making use of \eqref{eqn:mixingCoeffs}, we can further re-expand onto a basis of spin-weighted spherical harmonics,
\begin{subequations} \label{eqn:HertzYslm}
\begin{align}
    \Phi_{\pm 2}^{\mathcal{G},\mathcal{J}} &= \sum_{\ell m\omega} \check{\Phi}^{\mathcal{G},\mathcal{J}}_{\pm 2\ell m\omega}(r)Y_{\pm 2\ell m} e^{i(m\phi - \omega t)},
    \\
    \check{\Phi}^{\mathcal{G},\mathcal{J}}_{\pm 2\ell m\omega}(r) &= \sum_j b^{\ell}_{sjm\omega}\Phi^{\mathcal{G},\mathcal{J}}_{\pm 2jm\omega}(r),
\end{align}
\end{subequations}
which will be useful for leveraging the properties of the spin-raising and -lowering operators [i.e., \eqref{eqn:spinOps}] in the proceeding calculations.

\begin{widetext}

\subsection{Mode-sum expressions for metric perturbations}
\label{sec:mode-sum-recon}

To assemble mode-sum expressions for the metric perturbations, we first calculate the intermediate quantities $h^{\mathcal{G}, \mathcal{J}}_{(-2)\alpha\beta} = (\mathcal{S}_0^\dagger \Phi^{\mathcal{G}, \mathcal{J}}_{-2})_{\alpha\beta}$ and $h^{\mathcal{G}, \mathcal{J}}_{(+2)\alpha\beta} = (\mathcal{S}_4^\dagger \zeta^4 \Phi^{\mathcal{G}, \mathcal{J}}_{+2})_{\alpha\beta}$ using \eqref{eqn:HertzYslm}, leading to
\begin{subequations}
\begin{align}
    h^{\mathcal{G}\mathrm{RG}}_{(\pm2)\alpha\beta} &= h^{\mathcal{G}, \mathcal{I}}_{(\pm 2)\alpha\beta}\Theta(r-r_p(t)) + h^{\mathcal{G}, \mathcal{H}}_{(\pm 2)\alpha\beta}\Theta(r_p(t)-r),
    \\
    h^{\mathcal{G}, \mathcal{J}}_{(\pm 2)\alpha\beta} &= \sum_{n_i}h_{(\pm2)\alpha\beta}^{(n_t,n_r,n_s,n_\phi)}(r,z) \partial_t^{n_t}\partial_r^{n_r} \eth^{n_s}_\mp \partial_\phi^{n_\phi}  \sum_{\ell m\omega} \check{\Phi}^{\mathcal{G},\mathcal{J}}_{\pm 2jm\omega}(r) Y_{\pm 2\ell m}(z) e^{i(m\phi - \omega t)} + \mathrm{c.c.},
\end{align}
\end{subequations}
where we have introduced the notation
\begin{align}
    \sum_{n_i} = \sum_{n_t = 0}^2 \sum_{n_r = 0}^2 \sum_{n_s=0}^2 \sum_{n_\phi=0}^2.
\end{align} 
Recall that $\mathcal{G}\mathrm{RG}$ refers to the resulting gauge of $h_{(\pm2)\alpha\beta}$, with $\mathcal{G}=$ \{I,O,S,A\}. The functions $h_{(\pm2)\alpha\beta}^{(n_t,n_r,n_s,n_\phi)}(r,z) $ are independent of the mode-numbers and vanish unless $n_t+n_r+n_s+n_\phi\leq 2$ and $n_t,n_r,n_s,n_\phi\leq 2$. Thus, one has up to 15 independent coefficients for each component of the metric perturbation. For completeness, the non-vanishing coefficients are given in Boyer-Lindquist coordinates in Appendix \ref{app:metricCoeffs}. We find this particular decomposition of the mode-sum numerically advantageous, because the coefficients only need to be calculated once, and then can be applied to each mode. 

Acting the derivatives on the mode functions then leads to
\begin{subequations} \label{eqn:modeSumHABpm}
\begin{align}
    h^{\mathcal{G}, \mathcal{J}}_{(\pm 2)\alpha\beta}(t,r,z,\phi) &= \sum_{n_i}h_{(\pm2)\alpha\beta}^{(n_t,n_r,n_s,n_\phi)}(r,z) \sum_{\ell m\omega} \mathcal{M}^{(n_t,n_s,n_\phi)}_{\pm 2\ell m\omega} \partial_r^{n_r} \check{\Psi}^{\mathcal{G},\mathcal{J}}_{\pm 2\ell m\omega}(r) Y_{\pm (2-n_s)\ell m}(z) e^{i(m\phi - \omega t)} + \mathrm{c.c.},
    \\
    &= \sum_{\ell m\omega} \sum_{s_n=0}^2 h^{(s_n)\mathcal{G}, \mathcal{J}}_{(\pm 2\ell m\omega)\alpha\beta}(r,z) Y_{\pm s_n\ell m}(z) e^{i(m\phi - \omega t)} + \mathrm{c.c.},
\end{align}   
\end{subequations}
\end{widetext}
with $s_n = 2-n_s$ and scalar coefficients
\begin{align}
    \mathcal{M}^{(n_t,n_s,n_\phi)}_{\pm 2\ell m\omega} &= (-i\omega)^{n_t}(im)^{n_\phi} \prod_{s=0}^{n_s} \mu^{\mp(2-s)}_{\ell}.
\end{align}
Finally, to assemble full mode-sum expressions of the metric perturbation, we can insert \eqref{eqn:modeSumHABpm} into \eqref{eqn:reconstruct}. Combining these expressions with the completion pieces in \eqref{eqn:hcomp}, we arrive at full expressions for the metric perturbation $h_{\alpha\beta}$ in Eq.~\eqref{eqn:h1decomp} with
\begin{subequations}
\begin{align}
    h^{\mathcal{G}\mathrm{RG}-}_{\alpha\beta} &= h^{\mathcal{G}\mathrm{RG}, \mathcal{H}}_{(\pm 2)\alpha\beta},
    \\
    h^{\mathcal{G}\mathrm{RG}+}_{\alpha\beta} &= h^{\mathcal{G}\mathrm{RG}, \mathcal{I}}_{(\pm 2)\alpha\beta} + h^\mathrm{comp+}_{\alpha\beta},
\end{align}
\end{subequations}
and similarly for the gauge-fixed $h_{uu}$,
\begin{subequations} \label{eqn:huuModes}
\begin{align} 
    h^{\mathcal{G}\mathrm{RG}-}_{uu} &= h^{\mathcal{G}\mathrm{RG}, \mathcal{H}}_{(\pm 2)uu} + \pounds_{\xi^-}g_{uu},
    \\
    h^{\mathcal{G}\mathrm{RG}+}_{uu} &= h^{\mathcal{G}\mathrm{RG}, \mathcal{I}}_{(\pm 2)uu} + h^\mathrm{comp+}_{uu}.
\end{align}
\end{subequations}

