	\section{Proofs of \Cref{sec:preliminaries}}


	\begin{toto}
		\textbf{\Cref{all:top:bottom}.}\hypertarget{proof:all:top:bottom}{}
		Consider a QLA $\AA = (h, \A)$ with $h \in \{\Inf, \Sup, \E\}$.
		Then, $\top_{\AA} = \top_{\A}$ and $\bot_{\AA} = \bot_{\A}$.
		\begin{proof}
			Let $\AA = (h, \A)$ be a language automaton as in the statement.
			Assume $h = \Sup$.
			First, observe that for every language $L_1$ and $L_2$ with $L_1 \subseteq L_2$ we have $\AA(L_1) \leq \AA(L_2)$.
			We immediately obtain $\top_{\AA} = \AA(\Sigma^\omega)$.
			By definition, $\AA(\Sigma^\omega) = \sup_{w \in \Sigma^\omega} \A(w) = \top_{\A}$.
			For the case of bottom values, we have $\bot_{\AA} = \inf_{w \in \Sigma^\omega} \AA(\{w\})$ by the observation above, which implies that for every word $w$ and language $L$ with $w \in L$ we have $\AA(\{w\}) \leq \AA(L)$.
			Then, as $\AA(\{w\}) = \A(w)$, we conclude $\bot_{\AA} = \bot_{\A}$.
			The case of $h = \Inf$ is similar.

			Now, assume $h = \E$.
			Consider a sequence of words $w_1, w_2, \ldots$ such that $\lim_{i \to \infty} \A(w_i) = \top_{\A}$.
			Then, there is a sequence of probabilistic language generators $G_1, G_2, \ldots$ such that for each $i \geq 1$ the measure $\mu_i$ of $G_i$ assign probability 1 to $\{w_i\}$, which implies $\top_{\AA} \geq \top_{\A}$.
			Moreover, thanks to monotonicity of expected value, we have $\top_{\AA} \leq \top_{\A}$, which results in $\top_{\AA} = \top_{\A}$.
			The case of bottom values is similar.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{all:dual}.}\hypertarget{proof:all:dual}{}
		Consider a QLA $\AA$ and its dual $\hat{\AA}$.
		Then, $\AA(G) = -\hat{\AA}(G)$ for every language generator $G$.
		\begin{proof}	
			Follows from the fact that $\inf X = - \sup -X$ and $\liminf X = - \limsup -X$.
		\end{proof}
	\end{toto}



	\section{Proofs of \Cref{sec:problems}}


	\begin{toto}
		\textbf{\Cref{Borel:reduction}.}\hypertarget{proof:Borel:reduction}{}
		Consider a QLA $\AA = (h, \A)$ with $h \in \{\Inf$, $\Sup$, $\LimSup$, $\LimInf\}$ (resp. $h = \E$), a rational $k \in \QQ$, and ${\compare}\in\{{>}, {\geq}\}$.
		Then, $\AA$ is ${\compare}$-nonempty for $k$ iff $\AA$ is Borel ${\compare}$-nonempty (resp. Markov ${\compare}$-nonempty) for $k$.
		The same holds for universality.
		\begin{proof}
			We focus on the ${\geq}$-nonemptiness problem as the strict case is similar, and prove the $\Rightarrow$ implication as the other direction is immediate.
			(The proof is similar for the $\Leftarrow$ implication of universality.)

			Let $h = \Sup$.
			Suppose there is a subset $L \subseteq \Sigma^\omega$ with $\AA(L) \geq k$.
			Since for every $L_1, L_2 \subseteq \Sigma^\omega$ with $L_1 \subseteq L_2$ we have $\AA(L_1) \leq \AA(L_2)$.
			Then $\AA(\Sigma^\omega) \geq k$, witnessing Borel nonemptiness of $\AA$ as $\Sigma^\omega$ is a Borel set (it is both open and closed).
			For $h = \LimSup$, the same argument provides the witness.
			For $h = \Inf$, by the same argument, the witness for Borel nonemptiness is a singleton (thus a closed set).
			For $h = \LimInf$, we consider only the set $V$ of values achieved by infinitely many words in $L$, and map $L$ to $\inf V$.
			Since every infinite set has a countably infinite subset, take some $v \in V$ and such a subset $L'$ of words in $L$ with value $v$.
			As $L'$ can be viewed as a countable union of singletons, it is Borel.

			Let $h = \E$.
			Suppose there is a measure $\mu$ with $\AA(\mu) \geq k$.
			By monotonicity of $\E$, it implies the existence of a word $w$ with $\A(w) \geq k$.
			Then, the (potentially infinite-state) Markov chain generating $w$ with probability 1 witnesses the Markov nonemptiness.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{emptiness:reduction}.}\hypertarget{proof:emptiness:reduction}{}
		Consider a QLA $\AA = (h, \A)$ with $h \in \{\Inf,\Sup,\E\}$, a rational $k \in \QQ$, and ${\compare}\in\{{>}, {\geq}\}$.
		\begin{enumerate}[(a)]
			\item Unrestricted variant
			\begin{enumerate}[(i)]\itemindent=-1.6em
				\item If $h \neq \Sup$ or ${\compare} = {>}$, then $\AA$ is $\compare$-nonempty for $k$ iff $\A$ is ${\compare}$-nonempty for $k$.
				\item If $h = \Sup$, then $\AA$ is $\geq$-nonempty for $k$ iff $\A$ is approximate-nonempty for $k$.
			\end{enumerate}
			\item Finite-state variant
			\begin{enumerate}[(i)]\itemindent=-1.6em
				\item If $h = \Sup$, then $\AA$ is finite-state ${\compare}$-nonempty for $k$ iff $\AA$ is ${\compare}$-nonempty for $k$.
				\item If $h = \Inf$, then $\AA$ is finite-state ${\compare}$-nonempty for $k$ iff $\A$ is lasso-word ${\compare}$-nonempty for $k$.
				\item If $\top_{\A}$ is achievable by a lasso word, then $\AA$ is finite-state ${\compare}$-nonempty for $k$ iff $\AA$ is ${\compare}$-nonempty for $k$ iff $\A$ is lasso-word ${\compare}$-nonempty for $k$.
			\end{enumerate}
		\end{enumerate}
		For universality, we have the duals where we exchange $\Inf$ with $\Sup$, $>$ with $\geq$ , nonempty with universal, approximate-nonempty with approximate-universal, and $\top_{\A}$ with $\bot_{\A}$.
		\begin{proof}
			\begin{enumerate}[(a)]
				\item Unrestricted
				\begin{enumerate}[(i)]
					\item 
					Suppose $h = \Inf$. If $\AA(L) = \inf_{w \in L} \A(w) \compare k$ for some $L \subseteq \Sigma^\omega$, then $\A(w) \compare k$ for all $w \in L$.
					If $\A(w) \compare k$ for some $w \in \Sigma^\omega$, then $\AA(\{w\}) \compare k$ as well.

					Suppose $h = \E$. Assume $\AA(\mu) \compare k$ for some probability measure $\mu$. By monotonicity of $\E$, there is a word $w$ with $\A(w) \compare k$.
					Now, assume $\A(w) \compare k$ for some $w \in \Sigma^\omega$.
					Then, construct a measure having $\mu(\{w\}) = 1$, which witnesses the ${\compare}$-nonemptiness.

					Suppose $h = \Sup$ and ${\compare}  = {>}$. If there exists $L \subseteq \Sigma^{\omega}$ such that $\AA(L) > k$, then there is a word $w \in \Sigma^{\omega}$ such that $\A(w) > k$. For the other direction, let $w$ such that $\A(w) > k$, then $\AA(\{w\}) > k$.
					\item We have $\AA(\Sigma^{\omega}) \compare \AA(L)$ for any $L \subseteq \Sigma^\omega$ since for every $L_1, L_2 \subseteq \Sigma^\omega$ with $L_1 \subseteq L_2$ we have $\AA(L_1) \leq \AA(L_2)$.
					Using this fact, there exists $L \subseteq \Sigma^{\omega}$ such that $\AA(L) \geq k$ iff $\AA(\Sigma^{\omega}) \geq k$ iff $\top_{\AA} \geq k$ iff $\top_{\A} \geq k$ iff $\A$ is approximate-nonempty.

				\end{enumerate}
				\item Finite-state
				\begin{enumerate}[(i)]
					\item There exists $L \subseteq \Sigma^{\omega}$ such that $\AA(L) \compare k$ iff $\AA(\Sigma^{\omega}) \compare k$ iff there exists an $\omega$-regular language $L$ such that $\AA(L) \compare k$. The last equivalence follows since $\Sigma^{\omega}$ is an $\omega$-regular language.
					\item 
					Suppose $h = \Inf$. If $\AA(L) = \inf_{w \in L} \A(w) \compare k$ for some $\omega$-regular $L \subseteq \Sigma^\omega$, then $\A(w) \compare k$ for all $w \in L$. In particular, $\A(w') \compare k$ for some lasso $w' \in \Sigma^\omega$ since every $\omega$-regular contains a lasso word.
					Suppose $\A(w) \compare k$ for some ultimately-periodic $w \in \Sigma^\omega$, then $\AA(\{w\}) \compare k$ and $\{w\}$ is $\omega$-regular.
					\item
					Suppose $h = \E$.
					For any measure $\mu$, we have $\top_{\A} \compare \AA(\mu)$ as the expected value is never outside of the interval of numbers taking expected value from. Hence, if $\AA(\mu) \compare k$ for some measure $\mu$, then $\top_{\A} \compare k$ and there is an ultimately-periodic word $w$ such that $\A(w) = k$ by our initial assumption.

					Suppose $\top_{\A} \compare k$. Then, by our initial assumption, $\A(w) \compare k$ where $w$ is an ultimately-periodic word such that $\A(w) = \top_{\A}$. Then we can construct a Markov chain generating $w$ and thus witnessing finite-state ${\compare}$-nonemptiness of $\AA$ for $k$ and also unrestricted ${\compare}$-nonemptiness of $\AA$ for $k$.

					Suppose $h = \Inf$. One can combine (a)(i) and (b)(ii) with the fact that there exists $w \in \Sigma^\omega$ such that $\A(w) \compare k$ iff there exists lasso $w' \in \Sigma^\omega$ such that $\A(w') \compare k$.

					If $h = \Sup$, the argument works as for $h = \Inf$ since if $\top_{\A}$ is achievable, approximate-nonemptiness is equivalent to $\geq$-nonemptiness.
				\end{enumerate}
				The duals follow from the same arguments.\qedhere
			\end{enumerate}
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{approximability-reduction}.}\hypertarget{proof:approximability-reduction}{}
		Consider a QLA $\AA = (h, \A)$ with $h \in \{\Inf, \Sup, \E\}$ and $k \in \QQ$.
		If for every $\varepsilon > 0$ there is a lasso word $w$ such that $\A(w) \geq \top_{\A} - \varepsilon$, then $\AA$ is $>$-nonempty for $k$ iff $\AA$ is finite-state $>$-nonempty for $k$.
		Dually, if for every $\varepsilon > 0$ there is a lasso word $w$ such that $\A(w) \leq \bot_{\A} + \varepsilon$, then $\AA$ is $\geq$-universal for $k$ iff $\AA$ is finite-state $\geq$-universal for $k$.
		\begin{proof}
			The case $h = \Sup$ follows from~\cref{bigreduction}(b)(i). For $h = \Inf$, from~\cref{bigreduction}(a)(i) we have that $\AA$ is $>$-nonempty for $k$ iff there exists $w$ such that $\A(w) > k$. Using the assumption above, the latter is equivalent to: there exists ultimately-periodic $w$ such that $\A(w) >k$ which is equivalent to $\AA$ being finite-state $>$-nonempty for $k$ using~\cref{bigreduction}(b)(ii). For $h = \E$, if $\AA$ is $>$-nonempty, then~\cref{bigreduction}(a)(i) gives us that $\A(w) > k$ for some $w$ which implies, using the assumption, that there is an ultimately periodic word $w'$ such that $\A(w') > k$ for which we can construct a Markov chain $\M$ generating $w'$ such that $\AA(\M) = \A(w')$. The other direction is trivial. The dual cases follow the same line of argument.
		\end{proof}	
	\end{toto}


	\section{Proofs of \Cref{sec:evaluation}}



	\begin{toto}
		\textbf{\Cref{evaluation:classic}.}\hypertarget{proof:evaluation:classic}{}
		Consider a QLA $\AA = (h,(g,f,\T))$ with $f\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and $g,h \in \{\Inf$, $\Sup\}$.
		Let $S \subseteq \Sigma^\omega$ be an $\omega$-regular language given by a B\"uchi automaton.
		The value $\AA(S)$ is computable in \PTime when $g = h$ and in \PSpace when $g \neq h$.
		\begin{proof}
			This statement is a special case in the proof of \Cref{classic:membership:reduction}.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{ultim:avg}.}\hypertarget{proof:ultim:avg}{}
		There is a QLA $\AA$ with a run aggregator $f\in\{\LimInfAvg, \LimSupAvg\}$ and an $\omega$-regular language $S$ such that no lasso word in $S$ achieves the value $\AA(S)$.
		\begin{proof}
			Consider a language automaton $\AA = (\Sup,\A)$ where $\A = (g,f,\T)$ and $\T$ consists of a single state that loops over $a$ and $b$ with respectively weight 1 and 0.
			Since $\T$ is deterministic, the choice of $g \in \{\Inf,\Sup,\E\}$ is not relevant.
			Let $f \in \{\LimInfAvg, \LimSupAvg\}$ and $L = (\Sigma^* b)^\omega$.
			Observe that a lasso word $w$ fulfills $\A(w) = 1$ iff it has finitely many letters $b$.
			We define $w' = b a b a^2 b a^4 b a^8\dots$.
			Since $w' \in L$ and $\A(w') = 1$, we have $\AA(L) = \Sup_{w \in L} \A(w) = 1$.
			Hence, although the value $\AA(L)$ is achieved by some word, it cannot be achieved by an ultimately periodic word in $L$.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{evaluation:avg}.}\hypertarget{proof:evaluation:avg}{}
		Consider a QLA $\AA = (h,(g,f,\T))$ with $f\in\{\LimInfAvg$, $\LimSupAvg\}$ and $g,h \in \{\Inf$, $\Sup\}$.
		Let $S \subseteq \Sigma^\omega$ be an $\omega$-regular language given by a B\"uchi automaton.
		The value $\AA(S)$ is computable in \PTime when $g = h$ and not computable when $g \neq h$.
		\begin{proof}
			Let $\A$ be the underlying QWA of $\AA$.
			First, suppose $h = g = \Sup$.
			Let $\B$ be the input B\"uchi automaton.
			Construct the product automaton $\A \times \B$.
			Among all SCCs of $\A \times \B$ that are reachable from the initial state, find the ones that contain at least one state whose $\B$-component is accepting in $\B$.
			In each such SCC, compute the maximum mean of its cycles by Karp's algorithm \cite{DBLP:journals/dm/Karp78}.
			The largest among these mean values is exactly $\AA(S)$.
			Even though such a cycle $C$ may not involve an accepting state of $\B$, we can construct a run of the product that visits an accepting state infinitely often while going over $C$ with increasing frequency.
			Overall, $\AA(S)$ is computable in \PTime.
			The case of $h = g =\Inf$ is dual thanks to \cref{all:dual}.
			Now, suppose $h = \Inf$ and $g = \Sup$.
			Let $S = \Sigma^\omega$ and notice that $\AA(\Sigma^\omega) = \bot_{\A}$.
			An algorithm to compute $\bot_{\A}$ would imply the decidability of the universality problem of nondeterministic limit-average automata since $\A(w) \geq k$ for every word $w$ iff $\bot_{\A} \geq k$.
			Since this universality problem is undecidable \cite{DBLP:conf/csl/DegorreDGRT10,DBLP:conf/concur/ChatterjeeDEHR10}, the value $\AA(S)$ is not computable.
			The case of $h = \Sup$ and $g = \Inf$ is dual thanks to \cref{all:dual}.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{ultim:dsum}.}\hypertarget{proof:ultim:dsum}{}
		There is a QLA $\AA$ with the run aggregator $f=\DSum$ and an $\omega$-regular language $S$ such that no word in $S$ achieves the value $\AA(S)$.
		\begin{proof}
			Consider $L = (\Sigma^* b)^\omega$ and the automata $\AA$ and $\A$ from \Cref{ultim:avg} with $f = \DSum_{0.5}$.
			Observe that, $a^\omega$ is the only word achieving the value $2$, i.e., $\A(w) < 2$ for all $w \neq a^\omega$.
			For each $i \geq 1$ we define $w_i = a^i b^\omega \in L$.
			Since $\lim_{i \to \infty} \A(w_i) = 2$ and $\top_{\AA} = 2$, we have $\AA(L) = 2$.
			Therefore, the value $\AA(L)$ is not achievable by any word in $L$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{dsum:safe:in}.}\hypertarget{proof:dsum:safe:in}{}
		Consider a QLA $\AA = (\Sup, (\Sup, \DSum, \T))$.
		For every nonempty safety language $S \subseteq \Sigma^\omega$, the value $\AA(S)$ is achievable by some run of a word in $S$.
		\begin{proof}
			Let $\AA$ be as in the statement and $\A$ be its underlying QWA.
			Since $\AA(S) = \sup_{w \in S} \A(w)$, there exists a sequence of words $\{w_i\}_{i\in\NN}$ all coming from $S$ such that $\lim_{i \to \infty} \A(w_i) = \AA(S)$.
			As in the proof of \cite[Thm. 9]{DBLP:conf/fsttcs/BokerL21}, for each $i \in \NN$, we can choose a run $\pi_i$ on $w_i$ satisfying $\DSum(\gamma(\pi_i)) = \A(w_i)$, thus $\lim_{i \to \infty} \DSum(\gamma(\pi_i)) = \AA(S)$.
			Since the alphabet $\Sigma$ is finite, for each $j \in \NN$ there exists at least one finite word $u_j \in \Sigma^j$ (of length $j$) that occurs as a prefix of infinitely many $w_i$'s.
			By a diagonalization argument, we extract an infinite subsequence $(w'_j)_{j \in \NN}$ (of $(w_i)_{i \in \NN}$) such that $u_j \prec w'_j$ for each $j$, and $\lim_{j \to \infty} \A(w'_j) = \AA(S)$.

			Similarly, consider the corresponding runs $\rho'_j$ on $w'_j$ (with $\DSum(\gamma(\rho'_j)) = \A(w'_j)$).
			For each $j \in \NN$ there exists a finite run fragment $\theta_j$ of length $j$ that is a prefix of infinitely many $\rho'_j$'s.
			Thus, we can extract an infinite subsequence (which we continue to index by $j$) such that $\theta_j \prec \rho'_j$ and $\theta_j \prec \theta_k$ for all $j < k$.
			Denote by $\rho_j$ the run $\rho'_j$ from the extracted subsequence.
			Let $w = \lim_{j \to \infty} u_j$.
			Since each $u_j$ is a prefix of some word in $S$ and $S$ is a safety language, we have $w \in S$.
			Next, define the infinite run $\rho$ on $w$ by letting the $j$th transition of $\rho$ equal the $j$th transition of $\rho_j$.
			The run $\rho$ is well defined because $\theta_j \prec \theta_k$ for every $j,k \in \NN$ with $j < k$.

			For each $j \in \NN$, note that the difference between the values $\DSum(\gamma(\rho))$ and $\DSum(\gamma(\rho_j))$ comes from the tail of the run: $\left|\DSum(\gamma(\rho)) - \DSum(\gamma(\rho_j))\right| \leq \sum_{i=j}^\infty \lambda^i \ell = \frac{\ell \lambda^j}{1-\lambda}$ where $\ell$ is the maximal transition weight in $\A$ and $\lambda$ the discount factor.
			Since $\lim_{j\to\infty} \frac{\ell \lambda^j}{1-\lambda} = 0$, we have $\lim_{j \to \infty} \DSum(\gamma(\rho_j)) = \DSum(\gamma(\rho))$.
			Moreover, since $\lim_{j \to \infty} \DSum(\gamma(\rho_j)) = \lim_{j \to \infty} \DSum(\gamma(\rho'_j)) = \AA(S)$, we conclude $\DSum(\gamma(\rho)) = \A(w) = \AA(S)$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{dsum:safe:equal}.}\hypertarget{proof:dsum:safe:equal}{}
		Consider a QLA $\AA = (\Sup, (\Sup, \DSum, \T))$.
		For every language $S \subseteq \Sigma^\omega$ we have $\AA(S) = \AA(S')$ where $S'$ is the safety closure of $S$.
		\begin{proof}
			Let $\AA$ be as in the statement and $\A$ be its underlying QWA.
			Since $S \subseteq S'$ by definition, we immediately have $\AA(S) \leq \AA(S')$.
			We prove below $\AA(S) \geq \AA(S')$.

			Suppose towards contradiction that $\AA(S) < \AA(S')$ and let $\varepsilon = \AA(S') - \AA(S) > 0$.
			Since $S'$ is safe, thanks to \cref{dsum:safe:in} there exists a word $w \in S'$ and a run $\rho$ of $\A$ over $w$ such that $\A(w) = \DSum(\gamma(\rho)) = \AA(S')$.
			Moreover, since $\A$ is discounting, there exists $n \in \NN$ such that $\sum_{i = n}^{\infty} \ell \lambda^i < \frac{\varepsilon}{2}$, where $\ell$ is the maximal transition weight in $\A$ and $\lambda$ the discount factor.

			Let $u$ be the prefix of $w$ of length $n$ and $\theta$ the corresponding finite prefix of $\rho$.
			By definition of $S'$, there exists $w' \in S$ with $u \prec w'$.
			Let $\rho'$ be a run on $w'$ with the finite prefix $\theta$.
			By the discounting property mentioned above, we have $\left|\DSum(\gamma(\rho)) - \DSum(\gamma(\rho'))\right| \leq \sum_{i=n}^{\infty} \ell \lambda^i < \frac{\varepsilon}{2}$.
			Therefore, we obtain $\DSum(\gamma(\rho')) \geq \DSum(\gamma(\rho)) - \frac{\varepsilon}{2} = \AA(S') - \frac{\varepsilon}{2}$.
			Since $\rho'$ is a run of a word in $S$, we also have $\AA(S) \geq \DSum(\gamma(\rho'))$.
			It implies that $\AA(S) \geq \AA(S') - \frac{\varepsilon}{2}$, which contradicts the initial assumption that $\AA(S') - \AA(S) = \varepsilon > 0$.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{evaluation:dsum}.}\hypertarget{proof:evaluation:dsum}{}
		Consider a QLA $\AA = (h,(g,\DSum,\T))$ with $g,h \in \{\Inf$, $\Sup\}$.
		Let $S \subseteq \Sigma^\omega$ be an $\omega$-regular language given by a B\"uchi automaton.
		The value $\AA(S)$ is computable in \PTime when $g = h$.
		If $\AA(S)$ is computable when $g\neq h$, then the ${\geq}$-universality of nondeterministic discounted-sum word automata is decidable.
		\begin{proof}
			We start with the case with $h=g=\Sup$.
			Let $\B$ be the B\"uchi automaton recognizing $S$. 
			The B\"uchi automaton $\B'$ recognizing the safety closure of $S$ is computable in \PTime thanks to~\cite{DBLP:journals/dc/AlpernS87}.
			By safety condition, we can assume without loss of generality that $\B'$ is complete and has only one rejecting state which is a sink, called $p$ hereafter.
			We construct the discounted-sum word automaton $\C$ as the cross-product of $\B'$ and $\A$ where the transition weights are taken from $\A$.
			By \Cref{dsum:safe:equal}, we have $\AA(L(\B)) = \AA(L(\B'))$, and by \Cref{dsum:safe:in}, the value $\AA(L(\B'))$  is achievable by some run of a word of $L(\B')$.
			This implies that the value $\AA(L(\B))$ is achieved by a run that never visits a pair with $p$.
			Hence, we can compute this value in polynomial time thanks to the algorithm solving the one-player discounted payoff objectives game of~\cite{esslli2006-students-And} on the arena defined by $\C$ where all pairs containing $p$ are removed.
			The case of $g = h = \Inf$ is dual thanks to~\Cref{all:dual}.

			Suppose $h = \Inf$ and $g = \Sup$.
			Considering $S = \Sigma^\omega$, we have $\AA(S) = \bot_{\A}$.
			Notice that $\A$ is ${\geq}$-universal for $k$ iff $\bot_{\A} \geq k$.
			Therefore, the evaluation problem for this class of QLAs is at least as hard as the universality problem of nondeterministic discounted-sum word automata.
			The case of $h = \Sup$ and $g = \Inf$ is dual.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{nondet:stochastic:evaluation}.}\hypertarget{proof:nondet:stochastic:evaluation}{}
		Consider a QLA $\AA = (h,(\E,f,\T))$ with $f \in \{\Inf,$ $\Sup$, $\LimInf$, $\LimSup$, $\LimInfAvg$, $\LimSupAvg$, $\DSum \}$ and $h \in \{\Inf$, $\Sup\}$.
		Let $\mu$ be a probability measure given by a finite-state Markov chain.
		The value $\AA(\mu)$ is not computable.
		\begin{proof}
			For $h = \Sup$, we sketch a reduction from the approximate-nonemptiness problem of QWA with $f$ and $g$ as in the statement, which is undecidable as proved in~\cref{stochastic:undecidability}.
			Evaluating $\AA(\Sigma^{\omega})$ is equivalent to evaluating $\sup_{w \in \Sigma^{\omega}}\A(w)$, which is equal to $\top_{\A}$.
			Recall that deciding approximate-nonemptiness for $k$ is equivalent to deciding whether $\top_{\A} \geq k$.
			For $h = \Inf$, the proof goes by a reduction to the approximate-universality problem, which is undecidable (see ~\cref{stochastic:undecidability}).
			Recall that deciding approximate-universality for $k$ is equivalent to deciding whether $\bot_{\A} > k$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{stochastic:classic:evaluation}.}\hypertarget{proof:stochastic:classic:evaluation}{}
		Consider a QLA $\AA = (\E,(g,f,\T))$ with $f \in \{\Inf$, $\Sup$, $\LimInf,$ $\LimSup\}$ and $g \in \{\Inf$, $\Sup\}$.
		Let $\mu$ be a probability measure given by a finite-state Markov chain.
		The value $\AA(\mu)$ is computable in \ExpTime.
		\begin{proof}
			This proof extends the results of~\cite{DBLP:journals/jcss/MichaliszynO20}.
			Let $X = \{x_1, x_2, \ldots, x_n\}$ be the set of weights of $\A$ such that $x_1 < x_2 < \ldots < x_n$.
			Let $P_{\geq x}$ be the probability $P_{w \sim \mu}[\A(w) \geq x]$ for all $x \in X$.
			We define the probabilities $P_{w \sim \mu}[\A(w) = x_i] =P_{\geq x_i} - P_{\geq x_{i+1}}$ for $i < n$ and $P_{w \sim \mu}[\A(w) = x_n] = P_{\geq x_n}.$
			For all $w \in \Sigma^{\omega}$, we have $\A(w) \in X$, allowing us to express $\AA(\mu) = \sum_{i=1}^{n} x_i P_{w \sim \mu}[\A(w) = x_i]$.

			We only present the construction when $g = \Sup$.
			The duality property of \Cref{all:dual} allows us to treat the case $g=\Inf$.
			When $f=\LimSup$ and $g=\Sup$, we can construct a B\"uchi automaton $\A_{\geq x}$ recognizing $L(\A_{\geq x}) = \{w \in L \st \A(w) \geq x\}$ in linear time~\cite{DBLP:journals/tocl/ChatterjeeDH10}.
			Thanks to~\cite[Prop. 2.1.]{DBLP:conf/concur/BokerHMS23} and~\cite[Thm 13. (iv)]{DBLP:journals/tocl/ChatterjeeDH10}, we can assume that $f = \LimSup$ without loss of generality.
			From $\A_{\geq x}$, we can construct an equivalent deterministic Rabin automaton $\B_{\geq x}$ in \ExpTime.
			Finally, we construct the Markov chain $\C$ as the cross-product of the Markov chain $M$ representing the measure $\mu$ with the automaton $\B_{\geq x}$.
			Observe that $P_{\geq x}$ corresponds to the probability for a random walk in $\C$ to fulfill the accepting condition of the Rabin automaton $\B_{\geq x}$.
			Let $Q_1$, $Q_2$, and $Q=Q_1 \times Q_2$ be the set of states of $M$, $\B_{\geq x}$, and $\C$, respectively.	
			Given a pair of state sets $(G, B) \subseteq Q_2 \times Q_2$ of the accepting condition of the Rabin automaton $\B_{\geq x}$ and a bottom strongly connected component $S \subseteq Q$ of $\C$, we say that $S$ suits $(G, B)$ iff
			$S \subseteq Q_1 \times G$ and $S \cap (Q_1 \times B) = \emptyset$.
			Observe that, when $S$ suits $(G, B)$, every random walk in $S$ fulfills the accepting condition of the Rabin automaton $\B_{\geq x}$.
			Thus, $P_{\geq x}$ is the probability of reaching some bottom strongly connected component of $\C$ that suits some pair of the accepting condition of $\B_{\geq x}$.
			It can be computed in $\PTime$ thanks to~\cite[Chapter 10.3]{DBLP:books/daglib/0020348}.		
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{stochastic:nondet:dsum}.}\hypertarget{proof:stochastic:nondet:dsum}{}
		Consider a QLA $\AA = (\E,(g,\DSum,\T))$ with $g \in \{\Inf$, $\Sup\}$.
		Let $\mu$ be a probability measure given by a finite-state Markov chain.
		If $\AA(\mu)$ is computable, then the ${\geq}$-universality of nondeterministic discounted-sum word automata is decidable.
		\begin{proof}
			Given a $\DSum$ word automaton $\A$ and a threshold $k$, we can decide whether $\A(w) \geq k$ holds for every $w\in\Sigma^\omega$ by reducing the evaluation of some language automaton $\AA' = (\E, \A')$ where $\A$ has $g = \Sup$, and $f = \DSum$. 
			We construct a word automaton $\A'$ such that  $\A'(w) = \max(k, \A(w))$, for all $w\in\Sigma^\omega$.
			This is possible by introducing a new run from the initial state, for which the first transition is weighted by $k$ and all other transition is weighted by $0$.
			The construction thus consists in adding a new state with self-loop weighed $0$ that is reachable only from the initial state with weight $k$.
			Let $\AA = (\E, \A)$ and $\AA' = (\E, \A')$ be two language automata, and $\M$ be the uniform Markov chain (i.e., single state with a uniform self loop).
			We show that $\AA(\M) = \AA'(\M)$ if and only if $\A(w) \geq k$ for every $w\in\Sigma^\omega$.
			If $\A(w) \geq k$ holds for every $w\in\Sigma^\omega$, then both values are trivially equal.
			Otherwise, there exists $w\in\Sigma^\omega$ such that $\A(w) < k$, which by discounting implies that there exists a finite prefix $u \prec w$ such that $\A(uw') < k$ for all $w' \in \Sigma^{\omega}$.
			Since $\M$ is the uniform Markov chain, the measure of the set $u\Sigma^\omega$ is nonzero, and thus $\AA(\M) \neq \AA'(\M)$.
		\end{proof}
	\end{toto}





	\section{Proofs of \Cref{sec:emptiness}}


	\begin{toto}
		\textbf{\Cref{ptime:nonemptiness}.}\hypertarget{proof:ptime:nonemptiness}{}
		Consider a QLA $\AA = (h,(\Sup,f,\T))$ with $f \in \{\Inf,$ $\Sup$, $\LimInf$, $\LimSup$, $\LimInfAvg$, $\LimSupAvg$, $\DSum \}$ and $h \in \{\Inf$, $\Sup$, $\E\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		The ${\compare}$-nonemptiness of $\AA$ is in \PTime.
		The statement holds also for the finite-state restriction.
		\begin{proof}
			Let $\A$ be the underlying QWA of $\AA$.
			As $g = \Sup$, the value $\top_{\A}$ is achievable by some lasso word~\cite[Thm. 3]{DBLP:journals/tocl/ChatterjeeDH10}.
			Thus, using \cref{bigreduction}(b)(iii), we can reduce whether $\AA$ is (finite-state) ${\compare}$-nonempty for $k$ to whether $\A$ is (lasso-word) ${\compare}$-nonempty for $k$, which is decidable in \PTime.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{emptiness:classic}.}\hypertarget{proof:emptiness:classic}{}
		Consider a QLA $\AA = (h,(\Inf,f,\T))$ with $f\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and $h \in \{\Inf,\Sup,\E\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		The ${\compare}$-nonemptiness of $\AA$ is in \PSpace.
		The statement holds also for the finite-state restriction.
		\begin{proof}
			For any QWA $\A=(g,f,\T)$ with $f\in\{\Inf, \Sup, \LimInf, \LimSup\}$, the values $\top_{\A}$ and $\bot_{\A}$ are both achievable by some lasso words.
			This is because both values equal one of the weights in $\A$, and for each weight $x$ the language $\A_{=x}$ is $\omega$-regular.
			Thus, using \cref{bigreduction}(b)(iii), we can reduce whether $\AA$ is (finite-state) ${\compare}$-nonempty for $k$ to whether $\A$ is ${\compare}$-nonempty for $k$, which is decidable in \PSpace when $g=\Inf$~\cite[Thm. 3]{DBLP:conf/fct/ChatterjeeDH09}.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{limsupavg-approximability}.}\hypertarget{proof:limsupavg-approximability}{}
		Consider a QWA $\A = (\Sup, \LimSupAvg, \T)$.
		For every $\varepsilon > 0$ there is a lasso word $w$ such that $\A(w) < \bot_{\A} + \varepsilon$.
		\begin{proof}
			Let $\A = (\Sup, \LimSupAvg, \T)$ be a QWA with the alphabet $\Sigma$ and the set of states $Q$.
			For all finite sequences of rational weights $x = x_0, x_1, \ldots$, we define $\Sum(x) = \sum_{i=0}^{|x|} x_i$ and $\Avg(x) = \frac{\Sum(x)}{|x|}$.	
			Given $\varepsilon > 0$, let $w \in \Sigma^\omega$ be a word such that $\A(w) < \bot_{\A} + \frac{\varepsilon}{4}$.
			By definition of $\LimSupAvg$, there exists $\ell \in \NN$ such that for all $u \in \Sigma^*$ if $|u| > \ell$ and $u \prec w$ then $\sup \{\Avg(\gamma(\pi)) \st \pi \in R(\T,u)\}  < \bot_{\A} + \frac{\varepsilon}{2}$ where $R(\T,u)$ denotes the set of runs of $u$ in $\T$.
			Otherwise, infinitely many prefix of $w$ achieve an average of at least $\bot_{\A} + \frac{\varepsilon}{2}$ which contradict that $\A(w) < \bot_{\A} + \frac{\varepsilon}{2}$.
			We define $x_{\max}$ and $x_{\min}$ as the respective maximal and minimal weight appearing on $\A$ together with $c = x_{\max} - x_{\min}$.
			Since $Q$ is finite, $w$ admits infinitely many prefixes allowing to reach the same set of states in $\A$.
			Accordingly, consider $u_1, u_2 \in \Sigma^*$ such that $u_1 \prec u_1 u_2 \prec w$, $\delta(s, u_1) = \delta(s, u_1 u_2)$, $|u_1 u_2| > \ell$ and $\frac{|u_1|}{|u_2|} < \frac{\varepsilon}{\varepsilon + 2c}$.
			In particular, we have that $\delta(s, u_1) = \delta(s, u_1 u_2^{k})$ and $\frac{|u_1|}{k|u_2|} < \frac{\varepsilon}{\varepsilon + 2c}$ for all $k \in \NN$.
			Let $k \in \NN$, and let $\pi_1$ and $\pi_2$ be two runs on $u_1$ and $u_2^{k}$, respectively, such that $\pi_2$ starts from the state where $\pi_1$ ends.
			Observe that $\Sum(\gamma(\pi_1)) \geq x_{\min} |u_1| \geq (\bot_{\A} - c)|u_1|$.
			Additionally, the following holds by construction:
			\begin{center}
				$\begin{array}{c}
					\bot_{\A} + \frac{\varepsilon}{2} 
					> \frac{\Sum(\gamma(\pi_1)) + \Sum(\gamma(\pi_2))}{|u_1| + k|u_2|}
					\geq \frac{(\bot_{\A} - c)|u_1| + \Sum(\gamma(\pi_2))}{|u_1| + k|u_2|}
					\smallskip\\
					\big(\bot_{\A} + \frac{\varepsilon}{2}\big)\big(\frac{|u_1|}{k|u_2|} + 1\big) >\frac{|u_1|}{k|u_2|}\big(\bot_{\A} - c\big) +  \frac{\Sum(\gamma(\pi_2))}{k|u_2|}
					\smallskip\\
					\bot_{\A} + \varepsilon > \Avg(\gamma(\pi_2))
				\end{array}$
			\end{center}
			Since for all $k\in\NN$ every run $\pi$ on $u_1 u_2^{k}$ fulfills $\bot_{\A} + \varepsilon > \Avg(\gamma(\pi))$, the lasso word $u_1u_2^{\omega}$ fulfills $\bot_{\A} + \varepsilon > \A(u_1u_2^{\omega})$.
		\end{proof}
	\end{toto}

	\begin{toto}
		\begin{theorem}{\bf\cite{DBLP:conf/csl/DegorreDGRT10,DBLP:conf/concur/ChatterjeeDEHR10,DBLP:journals/tcs/HunterPPR18}.}\label{undecidability:limavg}
			Consider a QWA $\A = (\Inf, f, \T)$ with $f\in\{\LimInfAvg$, $\LimSupAvg\}$.
			Let ${\compare}\in\{{>}, {\geq}\}$.
			The ${\compare}$-nonemptiness of $\A$ is undecidable, whether we consider all words from $\Sigma^{\omega}$ or only lasso words.
			Moreover, its approximate-nonemptiness is also undecidable.
		\end{theorem}
		\begin{proof}
			The undecidability of
			\begin{itemize}
				\item $>$-nonemptiness for $\LimInfAvg$ and $\LimSupAvg$ was proved in~\cite[Thm. 4]{DBLP:conf/csl/DegorreDGRT10},
				\item $\geq$-nonemptiness for $\LimSupAvg$ in~\cite[Thm. 5]{DBLP:conf/csl/DegorreDGRT10}, and 
				\item $\geq$-nonemptiness for $\LimInfAvg$ in~\cite[Thm. 1]{DBLP:journals/tcs/HunterPPR18}.
			\end{itemize}

			The undecidability of lasso-word $\geq$-nonemptiness for $\LimInfAvg$ and $\LimSupAvg$ was proved in~\cite[Thm. 6]{DBLP:conf/csl/DegorreDGRT10}.
			The lasso-word $>$-nonemptiness for $\LimInfAvg$ is undecidable since the problem is equivalent to $>$-nonemptiness for $\LimInfAvg$ by the dual version of~\cref{limsupavg-approximability}.
			The corresponding problems for $\LimSupAvg$ are equivalent to those for $\LimInfAvg$ since for all lasso words the $\LimSupAvg$ and $\LimInfAvg$ values coincide.

			To prove the undecidability of approximate-nonemptiness, notice that the proofs of \cite[Thm. 5]{DBLP:conf/csl/DegorreDGRT10} and \cite[Thm. 1]{DBLP:journals/tcs/HunterPPR18} both actually show the undecidability of approximate-nonemptiness.
			In both proofs, either there is a word whose limit-average value is at least the threshold, or there is a gap between the potential limit-average values and the threshold.
			These gaps correspond to $\varepsilon$ in our definition of approximate-nonemptiness, which are of the size $\frac{1}{\ell}$ in \cite[Thm. 5]{DBLP:conf/csl/DegorreDGRT10} and $\frac{1}{2N}$ in \cite[Thm. 1]{DBLP:journals/tcs/HunterPPR18}, where both $\ell$ and $N$ encode the lengths of some runs.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{emptiness:avg}.}\hypertarget{proof:emptiness:avg}{}
		Consider a QLA $\AA = (h,(\Inf,f,\T))$ with $f\in\{\LimInfAvg$, $\LimSupAvg\}$ and $h \in \{\Inf,\Sup,\E\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		The ${\compare}$-nonemptiness of $\AA$ is undecidable.
		The statement holds also for the finite-state restriction when (i) $h \neq \E$ or (ii) $f = \LimInfAvg$ and ${\compare} = {>}$.
		\begin{proof}
			Let $\A$ be the underlying QWA of $\AA$.
			For the unrestricted cases, we use~\cref{bigreduction}(a)(i-ii) to reduce the ${\compare}$-nonemptiness or approximate-nonemptiness of $\A$, both undecidable by \Cref{undecidability:limavg}, to the ${\compare}$-nonemptiness of $\AA$.

			For the finite-state restrictions, we have the following.
			If $h = \Inf$, we use~\cref{bigreduction}(b)(ii) to reduce the lasso-word ${\compare}$-nonemptiness of $\A$, which is undecidable by \Cref{undecidability:limavg}, to the finite-state ${\compare}$-nonemptiness of $\AA$.
			If $h = \Sup$, we use~\cref{bigreduction}(b)(i) to reduce the unrestricted ${\compare}$-nonemptiness of $\AA$, which we proved undecidable above, to the finite-state ${\compare}$-nonemptiness of $\AA$.
			If $h = \E$ and $f = \LimInfAvg$, by~\cref{approximability-reduction} and the dual version of~\cref{limsupavg-approximability} (namely, for every QWA $\A = (\Inf, \LimInfAvg, \T)$ and every $\varepsilon > 0$ there is a lasso word $w$ such that $\A(w) > \top_{\A} - \varepsilon$), the finite-state $>$-nonemptiness of $\AA$ is equivalent to the unrestricted $>$-nonemptiness of $\AA$, which we proved undecidable above.
			We leave the remaining finite-state cases open.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{realizability:dsum}.}\hypertarget{proof:realizability:dsum}{}
		Consider a QWA $\A = (\Sup, \DSum, \T)$.
		There is a word $w$ such that $\A(w) = \bot_{\A}$.
		\begin{proof}
			Let $\A$ be a QWA as in the statement.
			For every $u \in \Sigma^*$, let $P_u = \{\A(uw) \st w \in \Sigma^\omega\}$.
			We claim that for every $u \in \Sigma^*$, there exists $\sigma \in \Sigma$ such that $\inf P_u = \inf P_{u\sigma}$.
			To prove, let $u$ be a finite word and observe the following:
			$P_u = \bigcup_{\sigma \in \Sigma} P_{u\sigma}$.
			Then, since $\inf(\bigcup_{i=1}^n X_i) = \min_{1 \leq i \leq n} \inf X_i$ for every finite collection $X_1, \ldots, X_n$ of sets and $\Sigma$ is finite, we have the following: $\inf P_u = \min_{\sigma \in \Sigma} (\inf P_{u\sigma})$.
			Finally, since some $\hat{\sigma} \in \Sigma$ achieves this minimum by definition, we have $\inf P_u = \inf P_{u\hat{\sigma}}$.


			Now, let $u_0 = \epsilon$ be the empty word.
			For each $i \geq 0$, choose a letter $\sigma_0 \in \Sigma$ and set $u_{i+1} = u_i \sigma_i$.
			Then, define $w$ as the limit of this sequence, i.e., $w = \sigma_0 \sigma_1 \ldots$.
			By the definition of $w$, we have $\lim_{i \to \infty} \inf P_{u_i} = \bot_{\A}$.
			Since the sequence of infima is nondecreasing, we can equivalently write $\sup_{u \prec w} \inf P_u = \bot_{\A}$.
			By~\cite[Definition 24]{DBLP:conf/fossacs/HenzingerMS23} the left-hand side expresses the co-safety closure of $\A$.
			Moreover, since every nondeterministic discounted-sum word automaton is co-safe~\cite[Theorems 4.15 and 4.16]{DBLP:conf/concur/BokerHMS23}, the left-hand side equals $\A(w)$.
			Therefore, $\A(w) = \bot_{\A}$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{emptiness:dsum}.}\hypertarget{proof:emptiness:dsum}{}
		Consider a QLA $\AA = (h,(\Inf,\DSum,\T))$ with $h \in \{\Inf,\Sup,\E\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		If the ${\compare}$-nonemptiness of $\AA$ is decidable, then the universality of nondeterministic discounted-sum word automata is decidable.
		The statement holds also for the finite-state restriction when (i) $h =\Sup$ or (ii) ${\compare} = {>}$.
		\begin{proof}
			Let ${\hat{\compare}} \in\{{>}, {\geq}\} \setminus \{{\compare}\}$ be the dual of ${\compare}$. 
			Let $\A = (\Inf, \DSum, \T)$ be the underlying QWA of $\AA$.
			We show that if the ${\compare}$-nonemptiness of $\AA$ is decidable, then the ${\hat{\compare}}$-universality of $\A$ is decidable.
			Observe that since $\top_{\A}$ is achievable thanks to the dual version of~\cref{realizability:dsum}, the approximate-nonemptiness and the $\geq$-nonemptiness problems coincide.
			Then, using~\cref{bigreduction}(a)(i-ii), we reduce the ${\compare}$-nonemptiness of $\A$, which is open and famously hard, to the ${\compare}$-nonemptiness of $\AA$.
			For finite-state restriction, we have the following:
			If $h = \Sup$, we use~\cref{bigreduction}(b)(i) to reduce the unrestricted ${\compare}$-nonemptiness of $\AA$ to the finite-state ${\compare}$-nonemptiness of $\AA$.
			If ${\compare} = {>}$, since $\top_{\A}$ is approximable by lasso words, we use~\cref{approximability-reduction} to reduce the unrestricted $>$-nonemptiness of $\AA$ to the finite-state $>$-nonemptiness of $\AA$.
			We leave the finite-state $\geq$-nonemptiness for $h \neq \Sup$ open.
		\end{proof}
	\end{toto}









	\begin{toto}
		\begin{theorem}{\bf\cite[Cor. 3.4]{DBLP:journals/ai/MadaniHC03}.}\label{inapproximability}
			For any $\varepsilon$ such that $0 < \varepsilon < \frac{1}{2}$, the following problem is undecidable:
			Let $\A = (\E, \Sup, \T)$ be a probabilistic word automaton with weights over $\{0, 1\}$ and accepting states, i.e., a subset of states $S \subseteq Q$ such that all transitions leading to $S$ have weight 1 and every other transition has weight 0. Given that either of the two cases hold:
			\begin{enumerate}[(i)]
				\item There exists a word $w \in \Sigma^{\omega}$ such that $\A(w) > 1 - \varepsilon$.
				\item For all words $w \in \Sigma^{\omega}$, we have $\A(w) < \varepsilon$.
			\end{enumerate}
			Decide whether (i) holds.
		\end{theorem}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{stochastic:undecidability}.}\hypertarget{proof:stochastic:undecidability}{}
		Consider a QWA $\A = (\E, f, \T)$ with $f \in \{\Inf$, $\Sup$, $\LimInf,$ $\LimSup$, $\LimInfAvg$, $\LimSupAvg$, $\DSum\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		The ${\compare}$-nonemptiness of $\A$ is undecidable, whether we consider all words from $\Sigma^{\omega}$ or only lasso words.
		Moreover, its approximate-nonemptiness is also undecidable.
		\begin{proof}
			When considering all words, the problems are generally known to be undecidable \cite{DBLP:journals/ai/MadaniHC03}.

			For the lasso-word variants, let us start with $f =\DSum$.
			Since the top value can be arbitrarily approximated by lasso words, then the lasso-word $>$-nonemptiness is equivalent to the unrestricted $>$-nonemptiness.
			For $\geq$-nonemptiness, we use \cite[Thm. 4.8]{DBLP:journals/ai/MadaniHC03}: it is undecidable to determine whether the top value (which is known to be $\frac{1}{2}$) of a particular automaton is achieved by a lasso word.
			Since this problem can be encoded as a lasso-word $\geq$-nonemptiness (with threshold $\frac{1}{2}$), this nonemptiness problem is undecidable.

			For other run aggregators, the undecidability follows from the inapproximability of the top value as stated by \Cref{inapproximability}.
			Let us first cover the case $f = \Sup$.
			If (i) holds for some $w \in \Sigma^{\omega}$ then there exists a long enough prefix $u \in \Sigma^*$ of $w$ such that $\A(u v^\omega) > \frac{1}{2}$ for any $v \in \Sigma^*$ since $\A(u v^\omega)$ is at least the probability of getting to an accepting state after reading $v$. 
			If (ii) holds, there is no lasso word with value above $\frac{1}{2}$.
			For $f = \Inf$, the argument is the same but we also change all weights to $1$ except the weights of sinks states, i.e., states from which the probability of getting to an accepting state is zero.
			For $f \in \{\LimSup, \LimInf, \LimSupAvg, \LimInfAvg\}$, the reduction is the same but we modify $\A$ such that every outgoing transition of an accepting state is a loop.

			Regarding the approximate-nonemptiness problem, since $\DSum$ has $\top_{\A}$ value always achievable \cite[Thm. 2.3.2]{madani2000complexity}, it is equivalent to the $\geq$-nonemptiness problem. 
			For the remaining run aggregators $f$, the above construction proves undecidability of approximate-nonemptiness thanks to \Cref{inapproximability}
			as $\varepsilon < \frac{1}{2}$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{emptiness:mixe}.}\hypertarget{proof:emptiness:mixe}{}
		Consider a QLA $\AA = (h, (\E, f, \T))$ with $f \in \{\Inf$, $\Sup$, $\LimInf,$ $\LimSup$, $\LimInfAvg$, $\LimSupAvg$, $\DSum\}$ and $h \in \{\Inf,\Sup,\E\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		The ${\compare}$-nonemptiness of $\AA$ is undecidable.
		The statement holds also for the finite-state restriction when (i) $h \neq \E$ or (ii) $f = \DSum$ and ${\compare} = {>}$.
		\begin{proof}
			For the unrestricted cases, we use~\cref{bigreduction}(a)(i-ii) to reduce the ${\compare}$-nonemptiness or approximate-nonemptiness of $\A$, both of which are undecidable by~\cref{stochastic:undecidability}, to the ${\compare}$-nonemptiness of $\AA$.

			For the finite-state case, we have the following:
			If $h = \Sup$, we use~\cref{bigreduction}(b)(i) to reduce the unrestricted ${\compare}$-nonemptiness of $\AA$, which we proved undecidable above, to the finite-state ${\compare}$-nonemptiness of $\AA$.
			If $h = \Inf$, we use~\cref{bigreduction}(b)(ii) to reduce the lasso-word ${\compare}$-nonemptiness of $\A$, which is undecidable by~\cref{stochastic:undecidability}, to the finite-state ${\compare}$-nonemptiness of $\AA$.
			If $h = \E$ and $f = \DSum$, we use~\cref{approximability-reduction} to reduce the unrestricted $>$-nonemptiness of $\AA$ to the finite-state $>$-nonemptiness of $\AA$.
			We leave open the finite-state ${\compare}$-nonemptiness for (i) $h = \E$ and $f \neq \DSum$, and (ii) $h = \E$ and $f = \DSum$ and ${\compare} = {\geq}$.
		\end{proof}
	\end{toto}


	\section{Proofs of \Cref{sec:limit}}

	\begin{toto}
		\textbf{\Cref{characterize:words:fixed}.}\hypertarget{proof:characterize:words:fixed}{}
		Let $\T$ be a (weighted) labeled transition system with $n$ states and $q_I$ its initial state.
		For every state $q_2$ of $\T$, 
		there exist infinitely many words with a run from $q_I$ visiting $q_2$ infinitely often iff
		$\T$ complies with the pattern parameterized by $q_2$ and $n$ given in \Cref{fig:pattern:words:fixed}a.
		\begin{proof}
			We start with the backward implication.
			Given the state $q_2$, we assume that $\T$ complies with the pattern in \Cref{fig:pattern:words:fixed}a exhibiting four finite runs of the form $\rho_1 : q_I \xrightarrow{u_1} q_1$, $\ell_1 : q_1 \xrightarrow{u_2u_3} q_1$, $\rho_2 : q_1 \xrightarrow{v} q_2$, $\ell_2 \colon q_2 \xrightarrow{u_2u_3} q_2$.
			Additionally we have that $|u_2|=|v|$ and $u_2\neq v$.
			For all $i\in\NN$, we define the run $\pi_i = \rho_1^{}(\ell_1^{})^{i}\rho_2^{}(\ell_2^{})^\omega$ from $q_I$ over $u_1(u_2u_3)^{i}v(u_2u_3)^\omega$.
			Since  $|u_2|=|v|$ and $u_2\neq v$, we have that $\pi_{i}$ and $\pi_{j}$ read distinct words for all $i \neq j$.
			In particular, the set $\{u_1(u_2u_3)^iv(u_2u_3)^\omega \st i \in \NN\}$ of ultimately periodic words with a run visiting $q_2$ infinitely often is infinite.


			Next, we prove the forward implication having an infinite set $S\subseteq \Sigma^\omega$ of words admitting some run from the initial state $q_I$ that visits the state $q_2$ infinitely often.
			Consider a word $w_1\in S$ together with one of its runs $\pi_1$ that visits $q_2$ infinitely.
			Let $w_0\in\Sigma^*$ be a finite prefix of $w_1$ for which $\pi_1$ visits at least $n^2$ times the state $q_2$ while reading $w_0$, where $n$ refers to the number of states of $\T$.
			Assuming that $w_1$ mismatches with all the other words of $S$ exclusively over its $|w_0|$ first letters contradicts $|S| = \infty$.
			Hence, there exists another word $w_2\in S$, distinct from $w_1$, but starting with the finite prefix $w_0$.
			Let $\pi_2$ be a run over $w_2$ that visits $q_2$ infinitely often.
			Since $\pi_1$ visits $n^2$ times the state $q_2$ while reading $w_0$, by the pigeon hole principle, there exists a state $q_1$ such that the pair $(q_1, q_2)$ is visited twice by $(\pi_1, \pi_2)$ while reading $w_0$.
			\Cref{pattern:proof:fixed} displays the two runs $\pi_1$ and $\pi_2$.
			The finite word $z$ refers the factor of $w_0$ corresponding to the synchronized loop, and the finite word $u$ stands for the prefix of $w_0$ before $z$.
			We ensure that $z \leq n^2$ by removing inner synchronized loops.
			We denote by $x$ and $y_1$ the synchronized section where $\pi_1$ and $\pi_2$ mismatch.
			In particular, $|x|=|y_1|$ and $x \neq y_1$.			
			Since both $\pi_1$ and $\pi_2$ visit $q_2$ infinitely often, we can take $x$ and $y_1$ long enough so that $x$ leads to $q_2$.
			Then, we denote by $\hat{y}_2$ the continuation of $y_1$ ending in $q_2$.
			Additionally, we ensure that $|y_1\hat{y}_2| \leq 3n^2+1$.
			Indeed, any synchronized loop in the factors $x$ and $y_1$ appearing before or after the mismatching letter can be removed without changing the reachability of $q_2$.
			Moreover, any loop in the factor $\hat{y}_2$ can be removed as well.
			Note that $z, x, y_1$ are nonempty by construction.
			By unfolding the synchronized loop, we can assume without loss of generality that all $u$ and $\hat{y}_2$ are nonempty.
			Hence, all words appearing in \Cref{pattern:proof:fixed} are nonempty.
			From $\hat{y}_2$, we define $y_2$ as $\hat{y}_2(y_1\hat{y}_2)^{|x|-1}$.
			This implies that $|y_1y_2| = m|x|$ for some $m\in\{1, \dots, 3n^2+1\}$.
			Furthermore, we can assume that $|z|=|y_1y_2|$, otherwise we lengthen $y_2$ and $z$ by pumping the synchronized loop over $z$.
			In particular $|z| = |y_1y_2| = m|x|$ for some $m\in\{1, \dots, 4n^4\}$.


			Now we distinguish the following two cases.
			First, if $z\neq y_1y_2$, then we define $u_1 = u$, $u_2 = z$, $u_3 = \varepsilon$, and $v = y_1y_2$.
			Second, if $z = y_1y_2$, then we define $u_1 = u$, $u_2 = y_1$, $u_3 = y_2$, and $v = x$.
			Either way, $u_1, u_2, u_3, v$ allow $\T$ to comply with the pattern in \Cref{fig:pattern:words:fixed}a.
		\end{proof}
	\end{toto}


