	\begin{toto}
		\begin{lemma}\label{exact:value:construction}
			Consider a QWA $\A = (g,f,\T)$ with $n$ states, $f\in\{\LimInf$, $\LimSup\}$, $g\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$.
			Given $x \in \QQ$, we can construct in polynomial time a B\"uchi automaton $\B$ such that
			(i) $L(\B) = \{w \in \Sigma^\omega \st \A(w) = x\}$
			and
			(ii) for every word $w$, the automaton $\B$ admits infinitely many accepting runs over $w$ iff $\A$ admits infinitely many runs of value $x$ over $w$.
		\end{lemma}
		\begin{proof}
			We start by constructing the B\"uchi automaton $\B_1$ that captures the runs visiting infinitely a transition of weight $x$.
			To do so, we consider two copies of $\T$ (the transition system of $\A$) such that:
			(1.i) the states of the first copy are all accepting,
			(1.ii) firing any transition from the first copy leads to the second copy,
			(2.i) the states of the second copy are all non-initial and non-accepting,	
			(2.ii) firing a transition from the second copy leads to the first copy if and only if its weight is $x$.
			Essentially, $\B_1$ visits an accepting state only when a transition weighted $x$ is fired.

			Then, from $\B_1$, we construct the B\"uchi automaton $\B_2$ that captures the runs of value exactly $x$.
			To do so, we consider three copies of $\B_1$ such that:
			(1.i) the states of the first copy are all non-accepting,
			(1.ii) firing any transition from the first copy leads nondeterministically to the second or the third copy,
			(2.i) the states of the second copy are all non-initial and non-accepting,
			(2.ii) firing a transition from the second copy leads to the first copy if and only if its weight is respectively larger or lower than $x$ when $f=\LimSup$ or $f=\LimInf$ (otherwise it stays in the second copy),
			(3.i) the states of the third copy are all accepting and non-initial,	
			(3.ii) all transitions weighted more than $x$ are removed from the third copy, and the others are unchanged.
			Essentially, $\B_2$ reaches the copy with accepting states (the third one) only once no more transitions dismissing the value $x$ can be fired. 

			Observe that there is a bijection between the accepting runs of $\B_2$ and the runs of value $x$ in $\A$.
			It follows from the fact that $\B_1$ jumps between the copies of $\A$ deterministically and the nondeterministic choices of $\B_2$ in its first copy are unambiguous (in the following sense for $f = \LimSup$: jumping to the second copy and not seeing a weight larger than $x$ in $\A$ and jumping to the third copy and seeing a weight larger than $x$ both result in a rejecting run).
			Note that this does not hold for rejecting runs due to the nondeterminism of $\B_2$.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{characterize:runs:fixed}.}\hypertarget{proof:characterize:runs:fixed}{}
		Consider a QWA $\A = (g,f,\T)$ with $n$ states, $f\in\{\LimInf$, $\LimSup\}$, $g\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$, and initial state $q_I$.
		Let ${\sim} = {\leq}$ if $f=\LimSup$ and ${\sim} = {\geq}$ if $f=\LimInf$.
		For every $x\in \QQ$ and every lasso word $w\in\Sigma^\omega$, we have that $w$ admits infinitely many runs of value $x$ in $\A$ iff $\A$ complies with the pattern in \Cref{fig:pattern:runs:fixed}b parameterized by $x$, $n$, ${\sim}$, and $w$.
		\begin{proof}
			We first prove the backward implication. 
			Given a weight $x$ and a lasso word $w\in\Sigma^\omega$, we assume that $\A$ complies with the pattern given in \Cref{fig:pattern:runs:fixed}b exhibiting four runs of the form $\rho_1 : q_I \xrightarrow{u_1} q_1$, $\ell_1 : q_1 \xrightarrow{v_1av_2}q_1$, $\rho_2 : q_1 \xrightarrow{u_2}q_2$ and $\ell_2 : q_2 \xrightarrow{v_1av_2}q_2$ where $q_1\neq q_2$, $w=u(v_1av_2)^\omega$, and $(u_2)^m = v_1av_2$ for some $m \in \{1, \dots, 4n^4\}$.
			For all $i\in\NN$, we define the run $\pi_i = \rho_1^{}(\ell_1^{})^i\rho_2^{}(\ell_2^{})^\omega$ in $\A$.
			Since $(u_2)^m = v_1av_2$, the run $\pi_i$ is over $w$ and achieves the value $x$ thanks to the definition of ${\sim}$.
			As a direct consequence of $q_1\neq q_2$, we have that $\pi_i \neq \pi_j$ for all $i \neq j$.
			In particular, $w$ have infinitely many runs of value $x$ in $\A$.


			Next, we prove the forward implication. 
			Given a weight $x$ and a lasso word $w\in\Sigma^\omega$, we assume that $w$ has infinitely many runs of value $x$ in $\A$.
			Let $\tilde{u}\in\Sigma^*$ and $\tilde{v}\in\Sigma^*\setminus\{\varepsilon\}$ be such that $w= \tilde{u}(\tilde{v})^\omega$.


			In the first step, we construct a B\"uchi automaton $\B$ that captures the runs over $w$ of value $x$ in $\A$.
			Thanks to \Cref{exact:value:construction}, we construct the B\"uchi automaton $\B'$ such that (i) $L(\B') = \{w \in \Sigma^\omega \st \A(w) = x\}$ and (ii) for every word $w$, the automaton $\B'$ admits infinitely many accepting runs over $w$ iff $\A$ admits infinitely many runs of value $x$ over $w$.			
			Finally, from $\B'$, we construction the B\"uchi automaton $\B$ that captures the runs over $w$ of value $x$ in $\A$.
			To do so, we consider a deterministic B\"uchi automaton $\B''$ accepting only $w$ and we construct $\B$ such that $L(\B) = L(\B') \cap L(\B'')$.
			Observe that there is a bijection between the accepting runs of $\B$ and the runs over $w$ of value $x$ in $\A$.
			This does not hold for non-accepting runs due to the nondeterminism of $\B'$.



			The second step consists of lifting runs to words and leveraging \Cref{characterize:words:fixed} to get the desired pattern.
			We thus construct a B\"uchi automaton $\C$ from $\B$ by re-labeling each transition $p_1 \xrightarrow{\sigma} p_2$ by $p_1 \xrightarrow{(p_1, \sigma, p_2)} p_2$.
			Since $w$ has infinitely many runs in $\A$ and $w\in L(\B)$, it has infinitely many accepting runs in $\C$.
			By \Cref{characterize:words:fixed}, some accepting state of $\C$ allows $\A$ to comply with the pattern given in \Cref{fig:pattern:words:fixed}a.
			Consequently there exist $u_1, u_2, u_3, v\in\Sigma^+$ such that $|u_2| = |v|$, $u_2 \neq v$, and $m|v| = |u_2u_3|$ for some $m \in \{1, \dots, 4n^4\}$, together with four runs of the form $\rho_1 : q_I \xrightarrow{u_1} q_1$, $\ell_1 : q_1 \xrightarrow{u_2u_3} q_1$, $\rho_2 = q_1 \xrightarrow{v} q_2$, $\ell_2 : q_2 \xrightarrow{u_2u_3} q_2$ in $\C$.
			Observe that $u_1, u_2, u_3, v$ are not over $\Sigma^*$ but over the alphabet consisting of the transitions of $\B$, called $\Gamma$ here after.
			For all finite words $w_0 \in \Gamma^*$ we denote $\Sigma(w_0) \in \Sigma^*$ the projection of all letters of $\Gamma$ to $\Sigma$, e.g., $\Sigma((p_1, \sigma_1, p_2)(p_2, \sigma_2, p_3)) = \sigma_1\sigma_2$.
			We established that $\C$ admits infinitely many ultimately periodic words of $\Gamma^\omega$ visiting $q_2$ infinitely often, and thus $\B$ admits infinitely many ultimately periodic runs (over its singleton language $\{w\}$).
			In particular, the set $\{u_1^{}(u_2^{}u_3^{})^iv^{}(u_2^{}u_3^{})^\omega \st i \in \NN\}$ of ultimately periodic words with a run visiting $q_2$ infinitely often is infinite.
			However, $\{\Sigma(u_1^{}(u_2^{}u_3^{})^iv^{})(\Sigma(u_2^{}u_3^{}))^\omega \st i \in \NN\} = \{w\}$.
			It is worth emphasizing that despite $u_2 \neq v$ we have $\Sigma(u_2) = \Sigma(v)$ because $L(\B) = \{w\}$.


			In the third step, we prove how to ensure $q_1 \neq q_2$.
			If in the above construction we obtain $q_1 = q_2$, called $q$ here after, then we can construct $u'_1, u'_2, u''_2, u'_3, u''_3, v'$ to get the desired property as follows.
			We identified $\rho_1 : q_I \xrightarrow{u_1} q$, $\rho_2 : q \xrightarrow{v} q$ and $\ell : q \xrightarrow{u_2u_3} q$ in $\C$.
			We recall that \Cref{characterize:words:fixed} ensures $|u_2|=|v|$ and $u_2 \neq v$.
			Since $\Sigma(u_2) = \Sigma(v)$, the mismatch is caused by the states of some letter of $\Gamma$.
			Thus, there are two distinct states $q'_1 \neq q'_2$ of $\C$ such that $q \xrightarrow{y_1} q_1'$, $q_1' \xrightarrow{y_2} q$, $q \xrightarrow{z_1} q_2'$, $q_2' \xrightarrow{z_2} q$ in $\C$, where $v = y_1y_2$,  $u_2 = z_1z_2$, $|y_1|=|z_1|$, and $|y_2|=|z_2|$.
			Let $u'_1 = u_1y_1$, $u'_2=y_2u_2u_3$, $u''_2=z_2u_3v$, $u'_3=y_1$, $u''_3=z_1$, and $v'=y_2vz_1$ together with the four runs of the form $\rho_1' : q_I \xrightarrow{u'_1} q_1'$, $\ell_1' : q_1' \xrightarrow{u'_2u'_3} q_1'$, $\rho_2' : q_1' \xrightarrow{v'} q_2'$, $\ell_2' : q_2' \xrightarrow{u''_2u''_3} q_2'$.
			For all $i\in\NN$, we define the run $\pi_i = \rho'_1(\ell'_1)^i\rho'_2(\ell'_2)^\omega$ over $w$ in $\C$.
			Observe that $\pi_i = \rho_1(\rho_2\ell)^i\rho_2\rho_2(\ell\rho_2)^\omega$ because $q_1 = q_2 = q$.
			In particular, the set $\{u'_1(u'_2u'_3)^iv'_{}(u''_2u''_3)^\omega \st i \in \NN\}$ of ultimately periodic words with a run visiting $q_2'$ infinitely often is infinite.
			We now prove that new pattern complies with \Cref{fig:pattern:runs:fixed}b.
			Since $\Sigma(u_2) = \Sigma(v)$, $|y_1|=|z_1|$, and $|y_2|=|z_2|$, we have that $\Sigma(y_1) = \Sigma(z_1)$ and $\Sigma(y_2) = \Sigma(z_2)$.
			Hence, $\Sigma(u'_2u'_3) = \Sigma(u''_2u''_3)$.
			Additionally, $\Sigma(v)^m = \Sigma(u'_2u'_3)$ for some $m\in\{1, \dots, 4n^4\}$ comes as a consequence of $m|v| = |u_2u_3|$ for some $m \in \{1, \dots, 4n^4\}$.


			Finally, we decompose $u_2u_3$ into $v_1av_2$.
			We identified $\rho_1 : q_I \xrightarrow{u_1} q_1$, $ \ell_1 : q_1 \xrightarrow{u_2u_3} q_1$, $\rho_2 : q_1 \xrightarrow{v} q_2$, and $ \ell_2 : q_2 \xrightarrow{u_2u_3} q_2$ where $q_1\neq q_2$ in $\B$. 
			Recall that there is a bijection between the accepting runs of $\B$ and the runs over $w$ of value $x$ in $\A$.
			By construction of $\B$, the accepting run $u_1^{}v_{}^{}(u_2^{}u_3^{})^\omega$ of $\B$ (which is a word accepted by $\C$) corresponds to a run over $w$ of value $x$ in $\A$.
			Therefore, the loop $\ell_2 : q_2 \xrightarrow{u_2u_3} q_2$ corresponds to a loop visiting the weight $x$ and other weights of value at most (resp. at least) $x$ when $f=\LimSup$ (resp. $f=\LimInf$).
			To conclude, there exist $v_1, v_2 \in\Sigma^*$ and $a\in\Sigma$ such that $u_2u_3 = v_1av_2$ together with the runs $q_2 \xrightarrow{v_1 :\sim x} q_3$, $q_4 \xrightarrow{v_2 : \sim x} q_2$ and the transition $q_3 \xrightarrow{a : x} q_4$.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{all:inf:sup}.}\hypertarget{proof:all:inf:sup}{}
		Consider a QLA $\AA = (h,(g,f,\T))$ with $f\in\{\Inf$, $\Sup\}$, $g \in \{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$, and $h$ any language aggregator function.
		We can construct in \PTime a QLA $\BB = (h,(g,f',\T'))$ with $f' \in \{\LimInf$, $\LimSup\}$ such that $\AA(S) = \BB(S)$ for all $S\subseteq \Sigma^\omega$.
		\begin{proof}
			A careful observation shows that the constructions of~\cite{DBLP:conf/concur/BokerHMS23,DBLP:journals/tocl/ChatterjeeDH10} allowing to convert a word automaton to a $\LimSup$ one extends to language automata.
			This proof provides the correctness of the construction from~\cite{DBLP:conf/concur/BokerHMS23} in the context of language automata.

			Consider a language automaton $\AA = (h,(g,\Sup,\T))$ where $\T = (\Sigma, Q, q_I, \delta)$ with $\gamma$ the weight function of $\T$, the word aggregator function $g\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$, and $h$ can be any language aggregator function. 
			Let $\A = (g,\Sup,\T)$.
			The idea is to construct an equivalent word automaton $\A' = (g,f',\T')$ where $f' \in \{\LimInf, \LimSup\}$ and transition system $\T'$ memorizes the maximal visited weight, and thus be used to construct a language automaton where runs are aggregated indifferently with $\Sup$, $\LimInf$, or $\LimSup$.
			Let $X$ be the set of weights of $\A$.
			Since $|X| < \infty$, we can fix the minimal weight $X_0 = \min X$.
			We construct $\T' = (\Sigma, Q \times X, (q_I, X_0), \delta')$ where $\trans{(q_1,v)}{a:x}{(q_2,x)}$ is a transition in $\T'$ iff $\trans{q_1}{a:v'}{q_2}$ in $\T$ where $x = \max\{v, v'\}$.
			The construction of $\T'$ can be done in \PTime in the size of $|\T|$.
			Observe that, by construction, every run $\pi$ of $\T'$ yields a non-decreasing weight sequence for which there exists $i \in \NN$ such that for all $j \geq i$ we have $\gamma(\pi[i]) = \gamma(\pi[j]) = \sup(\gamma(\pi))$.
			Therefore, $\A$ and $\A'$ are equivalent regardless of the choice of $f' \in \{\LimInf, \LimSup\}$.
			Moreover, again by construction, there is a bijection between their runs, implying that for all $w\in\Sigma^\omega$ the number of runs over $w$ is the same in $\A$ and $\A'$.
			Now, let $\AA' = (h,\A')$ and observe that since $\A$ and $\A'$ are equivalent, so are $\AA$ and $\AA'$.	
			The construction for a given automaton with $f=\Inf$ is dual as it consists in memorizing the minimal visited weight, therefore the weight sequences are non-increasing.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{limit:reduction:g}.}\hypertarget{proof:limit:reduction:g}{}
		Let $\AA = (h,(g,f,\T))$ be a QLA with $f\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$, $g = \LimSup$ (resp. $g = \LimInf$), and $h$ any language aggregator function.
		We can construct in \PSpace a QLA $\BB = (h,(g',f',\T'))$ with $f' = \LimSup$ and $g' = \Sup$ (resp. $f' = \LimInf$ and $g' = \Inf$) such that $\AA(S) = \BB(S)$ for all $S\subseteq\Sigma^\omega$.
		\begin{proof}
			Consider a language automaton $\AA = (h, \A)$ where $\A = (g,f,\T)$ is as in the statement.
			We show the case $g=\LimSup$, as the case $g=\LimInf$ can be solved by duality (\Cref{all:dual}).
			Thanks to \Cref{all:inf:sup}, we can assume that $f \in \{\LimInf, \LimSup\}$.
			The proof describes the construction of a QWA $\B = (\Sup, f, \T')$ such that $\A(w) = \B(w)$ for every ultimately periodic word $w \in \Sigma^\omega$, and argue why this equivalence generalizes to all words.

			Recall that, by definition (when $g = \LimSup$), $\bot_{\A}$ is the smallest weight $x$ in $\T$ such that there is a word $w$ with infinitely many runs of value $x$ in $\T$ and at most finitely many runs of value larger than $x$ in $\T$.
			Therefore, we can compute $\bot_{\A}$ as follows:
			Take a weight $x$ in $\T$ and construct in \PTime a B\"uchi automaton $\D_x$ from the transition system $\T$, recognizing exactly the set of words with some run of value $x$ in $\T$.
			Then, using \cite{DBLP:conf/dlt/LodingP18,DBLP:conf/dlt/FiliotMR18}, we can decide in \PTime if $\D_x$ has an infinite degree of ambiguity, i.e., some word in its language has infinitely many accepting runs (namely, runs of value $x$ in $\T$).
			Let $Y$ be the set of weights $x$ such that $\D_x$ has an infinite degree of ambiguity.
			Then, $\bot_{\A}$ is the largest $y \in Y$ such that the automaton $\D = (\Sup,f,\T)$ is ${\geq}$-universal for $y$, which can be computed in \PSpace.
			We can compute $\bot_{\A}$ similarly when $g = \LimInf$.
			Now, let $X$ be the set of all weights in $\T$.
			By \Cref{main:runs}, for all $x\in X$, we can construct in \PTime a B\"uchi (if $f=\LimSup$) or a co-B\"uchi (if $f=\LimInf$) automaton $\C_{x}$ recognizing all ultimately periodic words admitting infinitely many runs of value $x$ in $\A$.
			From $\C_{x}$ we construct in \PTime the QWA $\A'_{x}=(\Sup, f, \T_x)$ such that $\A'_x(w) = x$ when $w \in L(\C_x)$ and $\A'_x(w) = \bot_{\A'}$ when $w\notin L(\C_x)$.
			The construction consists in changing the transition weight $1$ to $x$ and $0$ to $\bot_{\A}$.
			The QWA $\B = (\Sup,f,\T')$ is defined by $\B = \max_{x\in X} \A'_x$, effectively computable in \PTime~\cite{DBLP:journals/corr/abs-1007-4018}.


			For every ultimately periodic word $w \in \Sigma^\omega$, the value $\A(w)$ corresponds to the maximal value $x \in X$ such that there exist infinitely many runs of value $x$ for $w$ in $\T$.
			Let $X_w \subseteq X$ denote the set of values $x$ for which $w$ admits infinitely many runs in $\T$; equivalently, $x \in X_w$ iff $w \in L(C_x)$.
			By construction, we have $\A'_x(w) = x$ for each $x \in X_w$ and $\A'_x(w) = \bot_{\A'}$ for each $x \in X \setminus X_w$.
			If $X_w \neq \emptyset$, it follows that $\A(w) = \max X' = \max_{x\in X'} \A'_x(w) = \B(w)$.
			Otherwise, if $X_w = \emptyset$, we have $\A(w) = \bot_{\A'} = \B(w)$.

			Next, we argue that if $\A(w) = \B(w)$ for every ultimately periodic word $w \in \Sigma^\omega$, then $\A(w) = \B(w)$ for every word $w \in \Sigma^\omega$.
			We prove the contrapositive.
			Suppose the existence of a word $\hat{w}$ such that $\A(\hat{w}) \neq \B(\hat{w})$.
			Clearly, we have $\A(\hat{w}) \in X$ and $\B(\hat{w}) \in X$.
			Using \Cref{exact:value:construction}, we construct a B\"uchi automaton $\A'_{\hat{w}}$ such that (i) $L(\A'_{\hat{w}}) = \{w \in \Sigma^\omega \st \A'(w) = \A'(\hat{w})\}$ and (ii) for every word $w$, the automaton $\A'_{\hat{w}}$ admits infinitely many accepting runs over $w$ iff $\A'$ admits infinitely many runs of value $\A'(\hat{w})$ over $w$.
			Similarly, we construct a B\"uchi automaton $\B_{\hat{w}}$ such that (i) $L(\B_{\hat{w}}) = \{w \in \Sigma^\omega \st \B(w) = \B(\hat{w})\}$ and (ii) for every word $w$, the automaton $\B_{\hat{w}}$ admits infinitely many accepting runs over $w$ iff $\B$ admits infinitely many runs of value $\B(\hat{w})$ over $w$.
			Thanks to~\cite{DBLP:conf/dlt/LodingP18}, we can construct from $\B_{\hat{w}}$ an unambiguous B\"uchi automaton $\B'_{\hat{w}}$ recognizing the same language.
			The cross product between $\A'_{\hat{w}}$ and $\B'_{\hat{w}}$ yields a B\"uchi automaton $\C$ such that (i) $L(C) = L(\B_{\hat{w}}) \cap L(\A'_{\hat{w}})$ and (ii) for every word $w$, the automaton $\C$ admits infinitely many accepting runs over $w$ iff $\A'$ admits infinitely many runs of value $\A'(\hat{w})$ over $w$.
			Observe that $\hat{w} \in L(\C)$ and for all $w\in L(\C)$ we have $\A'(w) = \A'(\hat{w}) \neq \B(\hat{w}) = \B(w)$.
			By~\cite{DBLP:journals/tcs/WeberS91,DBLP:conf/dlt/LodingP18}, we can decide whether $\C$ admits infinitely many accepting runs on some word.
			Furthermore, it follows from~\cite{DBLP:journals/tcs/WeberS91,DBLP:conf/dlt/LodingP18} that if $\C$ admits infinitely many accepting runs on a word, then it recognizes an ultimately periodic word $\tilde{w}$ with infinitely many accepting runs.
			In this case, $\A'$ admits infinitely many runs of value $\A'(\hat{w})$ over $\tilde{w}$, implying that $\A(\tilde{w}) = \A'(\tilde{w}) = \A'(\hat{w})$.
			Otherwise, we have $\A(\hat{w}) = \bot_{\A'} = \A'(\hat{w})$, and since $L(\C) \neq \emptyset$, there exists an ultimately periodic word $\tilde{w}$ for which $\A'(\tilde{w}) = \bot_{\A'}$.
			In either scenario, since $\tilde{w} \in L(\C)$, we have $\B(\tilde{w}) = \B(\hat{w})$.
			Therefore, we conclude that there is an ultimately periodic word $\tilde{w}$ satisfying $\A'(\tilde{w}) \neq \B(\tilde{w})$.
		\end{proof}
	\end{toto}



	\begin{toto}
		\textbf{\Cref{classic:reduction:g}.}\hypertarget{proof:classic:reduction:g}{}
		Consider a QLA $\AA = (h,(g,f,\T))$ with $f$ any run aggregator function, $g = \Sup$ (resp. $g = \Inf$), and $h$ any language aggregator function.
		We can construct in \PTime a QLA $\BB = (h,(g',f,\T')$ with $g' = \LimSup$ (resp. $g' = \LimInf$)
		such that $\AA(S) = \BB(S)$ for all $S\subseteq \Sigma^\omega$.
		\begin{proof}
			The transition system $\T'$ consists of two copies of $\T$ that are connected by nondeterministic transitions, allowing for every run in $\AA$ infinitely many runs in $\BB$.
			In particular, for every transition $\trans{q}{\sigma:x}{p}$ in $\T$, there are three transitions in $\T'$ as follows: $\trans{q}{\sigma:x}{p}$ copying the original transition, $\trans{q}{\sigma:x}{p'}$ allowing to jump from the first copy of the transition system to the second, and $\trans{q'}{\sigma:x}{p'}$ allowing to stay in the second copy.
			Evidently, for every run $\rho$ in $\T$ and every $i \in \NN$, there is a run $\rho_i'$ in $\T'$ such that $\rho_i'$ imitates $\rho$ in the first copy in the first $i$ transitions and in the second copy afterwards.
			Moreover, the values of $\rho_i'$ and $\rho$ coincide as they yield the same weight sequences.
			Since the word automata $(g,f,\T)$ and $(g',f,\T')$ are equivalent, so are $\AA$ and $\BB$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{limit:incomparable}.}\hypertarget{proof:limit:incomparable}{}
		QLAs with the language aggregators $\Inf$ and $\LimInf$ (resp. $\Sup$ and $\LimSup$) are expressively incomparable.
		\begin{proof}	
			Consider a QLA $\AA = (\Inf, \A)$ over the value domain $\{0,1\}$ where $\A$ maps a single word $w$ to 0 and every other word to 1.
			Then, for every language $L$, we have $\AA(L) = 0$ iff $w \in L$.
			Assume the existence of a QLA $\BB = (\LimInf,\B)$ that is equivalent to $\AA$.
			By construction, $\AA(\{w\}) = 0$ but since the language is finite, we have $\BB(\{w\}) = 1$, yielding a contradiction.

			Consider a QLA $\AA = (\LimInf, \A)$ over the value domain $\{0,1\}$ where $\A$ maps all words to 0.
			Then, for every language $L$, we have $\AA(L) = 0$ iff $|L| = \infty$.
			Assume the existence of a QLA $\BB = (\Inf,\B)$ that is equivalent to $\AA$.
			By definition, for every language $L$ we have $\BB(L) = \Inf_{w \in L} \B(w)$, meaning that $\B$ maps all words $w \in L$ to 0 iff $L$ is infinite.
			Intuitively, this is not possible since $\B$ only has a ``local'' view, i.e., values of words do not depend on other words they are given together with.
			Formally, consider the infinite language $\Sigma^\omega$.
			By assumption, we have $\AA(\Sigma^\omega) = \BB(\Sigma^\omega) = 0$.
			Notice that $\BB(\Sigma^\omega) = \Inf_{w \in L} \B(w) = 0$ implies the existence of a word $w$ with $\B(w) = 0$.
			Then, $\BB(\{w\}) = 0$ although $\AA(\{w\}) = 1$, yielding a contradiction.

			The case of $\Sup$ and $\LimSup$ can be proved similarly.
		\end{proof}
	\end{toto}

	\begin{toto}
		\textbf{\Cref{classic:membership:reduction}.}\hypertarget{proof:classic:membership:reduction}{}
		Consider a QLA $\AA = (h,(g,f,\T))$ with $f, g, h\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and at least one $g$ and $h$ belong to $\{\LimInf$, $\LimSup\}$.
		Let $S \subseteq \Sigma^\omega$ be an $\omega$-regular language given by a B\"uchi automaton.
		The value $\AA(S)$ is computable in \PSpace.
		\begin{proof}
			Consider a QLA $\AA = (h,(g,f,\T))$ with $f, g, h\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$.
			Let $X$ be the set of weights of $\T$.
			We assume that $g \in\{\Inf,\Sup\}$ thanks to \Cref{limit:reduction:g}.
			Further, we only consider the case when $g=\Sup$.
			By the duality property of \Cref{all:dual}, the other case can be solved by evaluating $\hat{\AA}$ instead and multiplying the result by $-1$.
			Thanks to~\cite[Thm 13. (iv)]{DBLP:journals/tocl/ChatterjeeDH10}, we can assume that $f = \LimSup$.
			It is worth emphasizing that the transformation of \cite{DBLP:journals/tocl/ChatterjeeDH10} must be performed once we have $g = \Sup$.
			Since $f = \LimSup$, we can compute $\top_{\A}$ in \PTime~\cite{DBLP:journals/tocl/ChatterjeeDH10} and $\bot_{\A}$ in \PSpace~\cite{DBLP:conf/concur/HenzingerMS24}.
			Let $\B_S$ be the B\"uchi automaton recognizing $S\subseteq \Sigma^\omega$.
			Next, we define $L(\A_{{\sim}x})= \{ w \in\Sigma^\omega \st \A(w) \sim x\}$ where $x\in\QQ$ is a rational threshold and ${\sim}\in\{{=}, {>}, {\geq}\}$. 
			When $f\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and $g=\Sup$, we can construct a B\"uchi automaton recognizing $L(\C_{>x})$ (resp., $L(\C_{\geq x})$) in linear time~\cite{DBLP:journals/tocl/ChatterjeeDH10}.
			Thus, we leverage \Cref{main:words} to compute in \PSpace the set of weights $Y \subseteq X$ such that $x\in Y$ if and only if $(L(\B_S) \cap L(\A_{\geq x})) \setminus L(\A_{>x})$ is infinite.
			We define the set of weights $Z$ as $Z=X$ if $h\in\{\Inf, \Sup\}$, as $Z=Y\cup \{\bot_{\A}\}$ if $h=\LimSup$, and as $Z=Y\cup \{\top_{\A}\}$ if $h=\LimInf$.

			Now, we distinguish two cases.
			When $h\in\{\Sup, \LimSup\}$, the evaluation procedure finds the largest weight of $\tilde{x} \in X$ such that for some $w\in L(\B_{S})$ we have $\AA(w) = \tilde{x}$.
			Equivalently, $\tilde{x}$ is the largest weight of $x\in Z$ for which $L(\B_S) \cap L(\A_{\geq x})$ is not empty.
			Hence, $\tilde{x}$ can be identified in \PSpace $h = \LimSup$ and in \PTime when $h=\Sup$ since the set $Y$ then does not need to be computed and the nonemptiness check above is in \PTime.
			When $h\in\{\Inf, \LimInf\}$, the evaluation procedure finds the smallest weight of $\tilde{x} \in X$ such that for all $w\in L(\B_{S})$ we have $\AA(w) = \tilde{x}$.
			Equivalently, $\tilde{x}$ is the smallest weight of $x\in Z$ for which $L(\B_S) \subseteq L(\A_{\geq x})$ holds.
			Hence, $\tilde{x}$ can be identified in \PSpace in this case.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{inclusion:limit}.}\hypertarget{proof:inclusion:limit}{}
		Consider two QLAs $\AA = (h, (g, f, \T))$ and $\BB = (h', (g', f', \T'))$ with $f, f', g, g', h, h' \in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		Deciding whether $\AA(S) \compare \BB(S)$ for every language $S \subseteq \Sigma^\omega$ is in \PSpace.
		The same holds when $S$ ranges over $\omega$-regular languages.
		\begin{proof}
			The inclusion problem of QWA with $f_{\AA}, f_{\BB} \in \{\Inf, \Sup, \LimInf, \LimSup\}$ and $g\in\{\Inf, \Sup\}$ reduces to that of $\omega$-regular languages~\cite{DBLP:journals/tocl/ChatterjeeDH10,DBLP:conf/fct/ChatterjeeDH09}, and thus can be decided by reasoning exclusively about lasso words.
			This property extends to language automata with $g_{\AA}, g_{\BB} \in \{ \Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ thanks to \Cref{limit:reduction:g}.
			We now argue that it also extends to language automata with $h_{\AA}, h_{\BB} \in \{ \Inf$, $\Sup$, $\LimInf$, $\LimSup\}$.
			Consider two QLAs $\AA$ and $\BB$ as in the statement.
			Let $X_{\AA}, X_{\BB}$ be the sets of weights of $\AA$ and $\BB$, respectively. 
			We assume that $g_{\AA}, g_{\BB} \in\{\Inf,\Sup\}$ thanks to \Cref{limit:reduction:g}.
			Suppose the existence of a non-empty language $S \subseteq \Sigma^\omega$ such that $\AA(S) {\not}\compare \BB(S)$.
			We have $\AA(S) \in X_{\AA}$ and $\BB(S) \in X_{\BB}$.
			Let $L_{\AA} = \{w \in \Sigma^\omega \st \A(w) \leq \AA(S)\}$, $L_{\BB} = \{w \in \Sigma^\omega \st \B(w) \geq \BB(S)\}$ both $\omega$-regular, together with they respective complements $L_{\AA}^{\complement}$ and $L_{\BB}^{\complement}$.
			Intuitively, we aim at constructing an $\omega$-regular language $L$ that allows $\AA$ and $\BB$ to achieve their respective image of $S$.


			The simpler cases are when exactly one of $h_{\AA}$ and $h_{\BB}$ belongs to $\{\Inf, \Sup\}$ and the other to $\{\LimInf, \LimSup\}$ since the value of the limit language aggregator is not affected by the addition of a single word.
			For instance, having $h_{\AA} = \LimSup$ and $h_{\BB} = \Inf$, we define $L = L_{\AA} \cup \{w\}$ where $w$ is an ultimately periodic word witnessing that $L_{\BB}$ is not empty.


			The cases when both $h_{\AA}$ and $h_{\BB}$ belong to $\{\LimInf, \LimSup\}$ go as follows.
			If $h_{\AA} =\LimInf$ and $h_{\BB}=\LimSup$, we define $L=\Sigma^\omega$.
			Otherwise, if
			(i) $h_{\AA} = h_{\BB} = \LimInf$,
			(ii) $h_{\AA} = h_{\BB} = \LimSup$, or
			(iii) $h_{\AA} =\LimSup$ and $h_{\BB}=\LimInf$, we continue as follows.
			If $S$ is finite, then both automata output their respective ``extreme value'' and thus defining $L$ with any finite language will do.
			Otherwise, we let $L= L_{\AA} \cap L_{\BB}$ and prove that $L$ is infinite.
			Indeed, the infiniteness of $S$ implies the infiniteness of both $L_{\AA} \cap S$ and $L_{\BB} \cap S$.
			Also, because $h_{\AA} = \LimSup$ or $h_{\BB} = \LimInf$, either $S \cap L_{\AA}^{\complement}$ or $S \cap L_{\BB}^{\complement}$ is finite, allowing us to conclude.
			For instance, having $h_{\BB} = \LimInf$ implies that $S \cap L_{\BB}^{\complement}$ is finite.
			Since $L_{\AA} \cap S$ is infinite but $S \cap L_{\BB}^{\complement}$ is finite, then $L_{\AA} \cap S = (L_{\AA} \cap S \cap L_{\BB}^{\complement}) \cup (L_{\AA} \cap S \cap  L_{\BB})$ is infinite, as well as $L_{\AA} \cap S \cap  L_{\BB}$.
			In particular, $L_{\AA} \cap  L_{\BB}$ is infinite.


			Finally, the cases both $h_{\AA}$ and $h_{\BB}$ belongs to $\{\Inf, \Sup\}$ uses a similar reasoning, replacing infinite by non-empty.
			If $h_{\AA} =\Inf$ and $h_{\BB}=\Sup$, we define $L=\Sigma^\omega$.
			Otherwise, if
			(i) $h_{\AA} = h_{\BB} = \Inf$,
			(ii) $h_{\AA} = h_{\BB} = \Sup$, or
			(iii) $h_{\AA} =\Sup$ and $h_{\BB}=\Inf$, we define $L = L_{\AA} \cap L_{\BB}$ and prove that it is non-empty.
			Clearly, both $L_{\AA} \cap S$ and $L_{\BB} \cap S$ are non-empty.
			Also, because $h_{\AA} = \Sup$ or  $h_{\BB}= \Inf$, either $S \cap {L_{\AA}}^{\complement}$ or $S \cap L_{\BB}^{\complement}$  is empty, allowing us to conclude.
			For instance, having $h_{\BB} = \Inf$ implies that $L_{\BB}^{\complement}$ is empty.
			Since $L_{\AA} \cap S$ is non-empty but $L_{\BB}^{\complement}$ is empty, then  $L_{\AA} \cap S = (L_{\AA} \cap S \cap L_{\BB}^{\complement}) \cup (L_{\AA} \cap S \cap  L_{\BB})$ is non-empty, as well as $L_{\AA} \cap S \cap  L_{\BB}$.
			In particular, $L_{\AA} \cap  L_{\BB}$ is non-empty.


			Next we provide a decision procedure for the inclusion problem.	
			Consider two QLAs $\AA = (h_{\AA},(g_{\AA},f_{\AA},\T_{\AA}))$ and $\BB = (h_{\BB},(g_{\BB},f_{\BB},\T_{\BB}))$ with $f_{\AA}, f_{\BB}\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$.
			Let $X_{\AA}, X_{\BB}$ be the sets of weights of $\AA$ and $\BB$, respectively. 
			We assume that $g_{\AA}, g_{\BB} \in\{\Inf,\Sup\}$ thanks to \Cref{limit:reduction:g}.
			Further, we use the duality properties of \Cref{all:dual} to get an equation where all language automata have a word aggregator $\Sup$.
			The problem is then of one of the following forms.
			%
			%
			\hfill\break
			\noindent\begin{minipage}{\linewidth}\medskip
				\begin{minipage}{.5\linewidth}
					\begin{itemize}
						\item $\forall S: \AA(S) \compare \BB(S)$ 
						\item $\forall S: \AA(S)+\hat{\BB}(S) \compare 0$
					\end{itemize}
				\end{minipage}%
				\begin{minipage}{.5\linewidth}
					\begin{itemize}
						\item $\forall S: 0 \compare \hat{\AA}(S) + \BB(S)$ 
						\item $\forall S: \hat{\BB}(S) \compare \hat{\AA}(S)$
					\end{itemize}
				\end{minipage}%
				\medskip\end{minipage}
			\indent
			%
			%	
			For simplicity, we reason about automata without duality and assume $g_{\AA} = g_{\BB} = \Sup$ while solving the four problems above.
			Thanks to~\cite[Thm 13. (iv)]{DBLP:journals/tocl/ChatterjeeDH10}, we can assume that $f_{\AA} = f_{\BB} = \LimSup$.
			It is worth emphasizing that, the transformation of~\cite{DBLP:journals/tocl/ChatterjeeDH10} must be performed once we have $g_{\AA} = g_{\BB} = \Sup$.
			Since $f_{\AA} = f_{\BB} = \LimSup$, we can compute $\top_{\A}$ and $\top_{\B}$ in \PTime~\cite{DBLP:journals/tocl/ChatterjeeDH10}, $\bot_{\A}$ and $\bot_{\B}$ in \PSpace~\cite{DBLP:conf/concur/HenzingerMS24}.
			Next, we define $L(\C_{{\sim}x})= \{ w \in\Sigma^\omega \st \C(w) \sim x\}$ where $\C$ is QWA, $x\in\QQ$ is a rational threshold, and ${\sim}\in\{{=}, {>}, {\geq}\}$. 
			When $f\in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and $g=\Sup$, we can construct a B\"uchi automaton recognizing $L(\C_{>x})$ (respectively $L(\C_{\geq x})$) in linear time~\cite{DBLP:journals/tocl/ChatterjeeDH10}.
			Thus, we leverage \Cref{main:words} to compute in \PSpace the set of weights $Y_{\AA} \subseteq X_{\AA}$ such that $x\in Y_{\AA}$ if and only if $L(\A_{\geq x}) \setminus L(\A_{>x})$ is infinite.
			We compute $Y_{\BB}$ similarly.

			The procedure iterates over all pair of weights $x\in X_{\AA}$ and $y\in X_{\BB}$.
			First, we check whether some word $w\in\Sigma^\omega$ is such that $\A(w) = x$ and $\B(w) = y$, i.e., whether $L(\A_{=x}) \cap L(\B_{=y})$ is not empty. 
			This can be equivalently encoded as the inclusion of B\"uchi automata $L(\A_{\geq x}) \cap L(\B_{\geq y}) \nsubseteq L(\A_{>x}) \cup L(\B_{>y})$ which is decidable in \PSpace.
			If $L(\A_{=x}) \cap L(\B_{=y})\neq \varnothing$, we consider its the two values $x'= \AA(L(\A_{=x}))$ and $y' = \BB(L(\B_{=y}))$.
			Thus the following holds.
			%
			%
			\hfill\break
			\begin{minipage}{\linewidth}\medskip
				\begin{minipage}{.5\linewidth}
					\begin{itemize}
						\item $x'=x$ iff $x\in Y_{\AA} \lor h_{\AA}\in\{\Inf, \Sup\}$
						\item $x'=\top_{\A}$ iff $x\notin Y_{\AA} \land h_{\AA}=\LimInf$
						\item $x'=\bot_{\A}$ iff $x\notin Y_{\AA} \land h_{\AA}=\LimSup$
					\end{itemize}
				\end{minipage}%
				\begin{minipage}{.5\linewidth}
					\begin{itemize}
						\item $y'=y$ iff $y\in Y_{\BB} \lor h_{\BB}\in\{\Inf, \Sup\}$
						\item $y'=\top_{\B}$ iff $y\notin Y_{\AA} \land h_{\BB}=\LimInf$
						\item $y'=\bot_{\B}$ iff $y\notin Y_{\BB} \land h_{\BB}=\LimSup$
					\end{itemize}
				\end{minipage}%
				\medskip\end{minipage}
			\indent
			%
			%	
			Additionally, we observe that for all language automaton $\CC = (h_{\CC}, \C)$ have $\top_{\CC} = \top_{\C}$ for $h_{\C}=\LimInf$ and $\bot_{\CC} = \bot_{\C}$ for $h_{\C}=\LimSup$.
			This is because $h_{\CC}=\LimInf$ may only increase the values of languages compared to using $\Inf$, while $h_{\CC}=\LimSup$ may only decrease compared to $\Sup$.
			Finally, we respectively check that $x' \compare y$, $x'+y' \compare 0$, $0 \compare x'+y'$, or $y' \compare x'$ holds.
			Clearly, if for some $\tilde{x}\in X_{\AA}$ and all $\tilde{y}\in X_{\BB}$, we have $S_{\tilde{x},\tilde{y}} = L(\A_{=\tilde{x}})\cap L(\B_{=\tilde{y}})\neq \varnothing$ but $\tilde{x}', \tilde{y}'$ do not satisfy the equation, then $S_{\tilde{x}, \tilde{y}}$ is a non-inclusion witness.
			Otherwise, if for all $x\in X_{\AA}$ and all $y\in X_{\BB}$ having $S_{x,y} = L(\A_{=x})\cap L(\B_{=y})\neq \varnothing$ implies that $x', y'$ satisfy the equation, then the inclusion holds for all $\bigcup_{x\in Z_{\AA}, y\in Z_{\BB}} S_{x, y}$ where $Z_{\AA} \subseteq X_{\AA}$ and $Z_{\BB} \subseteq X_{\BB}$, and thus for all $S\subseteq \Sigma^\omega$.
		\end{proof}
	\end{toto}


	\begin{toto}
		\textbf{\Cref{emptiness:limit}.}\hypertarget{proof:emptiness:limit}{} 
		Consider a QLA $\AA = (h,(g,f,\T))$ with $f, g, h \in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and at least one $g$ and $h$ belong to $\{\LimInf$, $\LimSup\}$.
		Let ${\compare}\in\{{>}, {\geq}\}$.
		The ${\compare}$-nonemptiness (resp. ${\compare}$-universality) of $\AA$ is in \PSpace.
		The statement holds also for the finite-state restriction.
		\begin{proof}
			We provide a direct proof as an alternative.

			Let $\AA = (h,(g,f,\T))$ be a QLA with $f, g, h \in\{\Inf$, $\Sup$, $\LimInf$, $\LimSup\}$ and let $k \in \QQ$.
			Thanks to \cref{all:inf:sup,limit:reduction:g}, we can assume w.l.o.g. that $g = \Sup$ and $f = \LimSup$.
			Let $\A$ be the underlying QWA of $\AA$.

			First, we show that $\top_{\AA} \compare k$ iff $\AA$ is ${\compare}$-nonempty for $k$.
			For the left-to-right direction, notice that there are only finitely many values to which a language $L$ can be mapped by $\AA$, and the value $\top_{\AA}$ is the maximum among these values.
			So, if $\AA(L) {\not}\compare k$ for all $L \subseteq \Sigma^\omega$, then $\top_{\AA} {\not}\compare k$ as well.
			For the right-to-left direction, simply observe that $\top_{\AA} \geq \AA(L)$ by definition where $L$ is a nonemptiness witness.	

			Second, we describe an algorithm to compute $\top_{\AA}$.
			For $h \in \{\Inf,\Sup\}$, we have $\top_{\AA} = \top_{\A}$ thanks to \cref{all:top:bot}, which can be computed in \PTime when $g = \Sup$ and in \PSpace otherwise.
			(Note that translating the underlying QWA to one with $g = \Sup$ can be also done in \PSpace.)
			Let us now consider $h \in \{\LimInf, \LimSup\}$.
			Notice that $\top_{\AA}$ is exactly the largest weight $x$ in $\A$ such that $L(\A_{= x})$ is infinite, which we can compute in \PSpace thanks to \cref{main:words}.

			Third, we show that the unrestricted and the finite-state nonemptiness problems coincide in this setting.
			To achieve this, we prove the following claim:
			For every language $S$, there is an $\omega$-regular language $L$ such that $\AA(S) = \AA(L)$.
			If $h \in \{\Inf,\LimInf\}$, let $L = \{w \in \Sigma^\omega \st \A(w) \geq \AA(S)\}$.
			For $h = \Inf$, it is easy to see that $\AA(L) = \AA(S)$---there is a word $w \in L$ with value $\AA(S)$ since $\A$ has $g = \Sup$ and $f = \LimSup$, and all words in $L$ have at least this value.
			For $h = \LimInf$, the argument goes as follows.
			If $S$ is not finite, $\AA(S)$ is the least weight $x$ of $\A$ such that there are infinitely many words $w \in S$ with $\A(w) = x$.
			By definition, $L$ contains at least all such words, so it has infinitely many words with value $x$.
			Moreover, $L$ does not contain any word with a smaller value, therefore $\AA(L) = x$.
			If $S$ is finite, then $\AA(S) = \top_{\AA}$.
			Recall that $\top_{\AA}$ is exactly the largest weight $x$ in $\A$ such that $L(\A_{= x})$ is infinite, so $L$ is nonempty and satisfies $\AA(L) = \top_{\AA}$.
			For $h \in \{\Sup,\LimSup\}$, let $L = \{w \in \Sigma^\omega \st \A(w) \leq \AA(S)\}$ instead.
			Having this, we finally conclude that $\AA(S) \compare k$ for some language $S$ iff $\AA(L) \compare k$ for some $\omega$-regular language $L$.
		\end{proof}
	\end{toto}	
