The existence of a Gr{\"o}bner basis for $I$ of the following special type will be the most general context in which our main theorem holds. As in \cref{subsec:mon.ar.rem}{}, we use $p$ and $q$ to denote two paths that avoid the fixed arrow $ \a $, such that $t( p ) = s ( \a )$  and $s( q) = t ( \a )$. Furthermore, we allow at most one of $p$ and $q$ to be trivial.

\begin{defn}
	\label{defn:2}
	A Gr{\"o}bner basis $\GG $ for $I$ will be called \emph{strict $ \a $-monomial} if there are paths $p$ and $q$ as above such that:
		\begin{enumerate}[\rm(i)]
			\item the set $ \GG $ satisfies property \hyperlink{P1}{(P1)} non-trivially, i.e.\ it contains the path $p \a q $;
			\item the set $\tip ( \GG )$ satisfies properties \hyperlink{P2}{(P2)}, \hyperlink{P2op}{(P2)$^{\textrm{op}}$} and \hyperlink{P3}{(P3)}.
		%	\item the set $\GG $ satisfies property \hyperlink{P1}{(P1)}.
		\end{enumerate}
	We write $\GG = \GG_{p , q} $ in order to indicate the paths $p$ and $q$.
\end{defn}

\begin{rem}
	\label{rem:1}
	If the admissible ideal $I$ possesses a strict $ \a $-monomial Gr{\"o}bner basis $ \GG = \GG_{p , q} $, then $ \a $ cannot be a loop. Indeed, if $ \a $ was a loop then there would be a positive integer $ i $ such that $ \a ^i \in I$, implying that $\tip ( g )$ divides $ \a ^i$ for some $ g \in \GG $. However, this is not possible as either $\tip ( g ) = p \a q$ or $\tip ( g ) $ avoids $ \a $.
\end{rem}


\begin{lem}
	\label{lem:00}
	The ideal $I$ possesses a strict $ \a $-monomial Gr{\"o}bner basis if and only if the reduced Gr{\"o}bner basis of $I$ is strict $ \a $-monomial. In particular, if $ \GG_{ p , q } $ and $ \GG'_{p' , q'} $ are two strict $ \a $-monomial Gr\"{o}bner bases for $ I $, then $ p ' = p $ and $ q' = q $.
	%the paths $ p $ and $ q $ are uniquely defined 
	%there are unique paths $p$ and $q$ such that $\GG = \GG_{p , q }$ for every strict $ \a $-monomial Gr{\"o}bner basis $\GG$ for $I$. 
\end{lem}


\begin{proof}
	Let $\GG = \GG_{p , q}$ be a strict $ \a $-monomial Gr{\"o}bner basis for $I$. Then $\GG$ is in particular an $ \a $-monomial generating set for $I$. For every element $ z \in k Q $, we use $ z_\a $ and $ z'$ to denote the unique elements of $k Q$ such that $z' $ avoids $ \a $, every path occurring in $z_\a $ is divided by $ \a $,  and $z = z_\a + z'$. Then it follows from the proof of \cref{propcleftextension}{} that $z_\a, z' \in I$ whenever $z \in I$.

	Let now $\GG_{\textrm{red}} $ be the reduced Gr{\"o}bner basis of $I$, and observe that $\tip (\GG_{\textrm{red}} )$ satisfies properties \hyperlink{P2}{(P2)}, \hyperlink{P2op}{(P2)$^{\textrm{op}}$} and \hyperlink{P3}{(P3)}, as $\tip (\GG_{\textrm{red}} ) \subseteq \tip (\GG)$. It remains to show that $p \a q \in \GG_{\textrm{red}} $ and $\GG_{\textrm{red}} \setminus \{ p \a q \} $ avoids $ \a $.

	Let $T$ denote the unique minimal generating set of the ideal of $ k Q $ generated by $ \tip (I) $, and observe that $ T \subseteq \tip ( \GG ) $. We begin by showing that $p \a q \in T$. If we assume that $p \a q \notin T$, then there is an element $ g \in \GG \setminus \{ p \a q \}$ such that $\tip ( g ) $ divides $ p \a q $. Since $ g $ avoids $ \a $, the path $\tip ( g ) $ divides $p$ or $q$, a contradiction as $\tip (\GG)$ satisfies property \hyperlink{P3}{(P3)}. Of course, we have $N( p \a q ) = 0$ as $p \a q \in I$. It remains to prove that for every path $t \in T \setminus \{ p \a q \}$ it holds that $t - N(t)$ avoids $ \a $. It is immediate that $t $ avoids $ \a $ as $ t \in \tip ( \GG  \setminus \{ p \a q \} )$. On the other hand, we have that $ { { ( t - N( t ) )' } = { t - N(t)' } } , { { ( t - N( t ) )_\a } = { N(t)_\a} } \in I$ since $t - N ( t ) \in I$. We conclude that $N(t)_\a = 0$, as the intersection of $I$ and ${}_k \la \ntip (I) \ra$ is trivial, and thus the element $N(t) = N(t)'$ avoids $ \a $.

	Now observe that, if $\GG' = \GG'_{p' , q'}$ is some other strict $ \a $-monomial Gr{\"o}bner basis for $I$, then $p' = p $ and $q' = q $ as both $p \a q $ and $p' \a q'$ are equal to the unique path of $T$ that is divided by $ \a $. It remains to note that $T$ is uniquely determined by $I$ and the admissible order on $\BQ$.
\end{proof}

We prove next that an admissible ideal $I$ admits a strict $ \a $-monomial Gr{\"o}bner basis whenever $\La / \la \ol{ \a } \ra $ is a strict monomial arrow removal of $ \La = k Q / I $. The converse is not true, however, as illustrated in \cref{exam:1''}{}.




\begin{lem}
		\label{lem:1}
	If the quotient algebra $\La / \la \ol{ \a } \ra $ is a strict monomial arrow removal of $\La = k Q / I $, then
	there is a finite Gr{\"o}bner basis for $I$ that is strict $ \a $-monomial (even as a generating set for $I$).
\end{lem}





\begin{proof}
	Let $ T = T_{p , q}$ be a finite strict $ \a $-monomial generating set of relations for $I$. According to \cref{lem:0}{}, this is equivalent to $ p \a q \in T $ and $ T $ satisfying properties \hyperlink{P1}{(P)} for the paths $p$ and $q$. It suffices to prove that if $X$ is any finite set of relations satisfying properties \hyperlink{P1}{(P)}, then the same holds for $\tilde{ X }$. Indeed, then the Gr\"{o}bner basis $ \GG $ constructed from $ T $ as in \cref{reformII}{} will be strict $ \a $-monomial as a generating set for $ I $, as it will satisfy properties \hyperlink{P1}{(P)} and $ p \a q \in T \subseteq \GG $.


	Let $ y = \oo ( z, w, u, v )$ be an overlapping relation for $z, w \in X$, and let $y \Rightarrow_X r $. The only thing we need to prove is that the remainder $r $ satisfies properties \hyperlink{P1}{(P)}.

	\smallskip

	\phantomsection	\hypertarget{stepI}{}	\textbf{Step I}: It holds that $z $ and $ w $ avoid $ \a $.

	We assume that $p \a q \in X$ because, otherwise, there is nothing to prove. Since the set $ X $ satisfies in particular property \hyperlink{P1}{(P1)}, we have to show that $ z, w \neq p \a q $.

	Let $z \neq p \a q $ and $w = p \a q $, and the case where $z = p \a q $ and $w \neq p \a  q$ is analogous. It holds that $\tip (z ) v = u p \a q $, where $ p \a q $ does not divide $v$ and $\tip (z ) $ does not divide $u$. On the other hand, the path $\tip (z) $ avoids $ \a $ implying that $\tip ( z) p_2 = u p $, where $p_2 $ is a proper subpath of $p $ such that $p = p_1 p_2$ and $v = p_2 \a q $. It follows that $p$ overlaps with $\tip (z )$ from the left as the paths $\tip (z)$ and $p$ do not divide $u$ and $p_2$, respectively, and this is a contradiction to property \hyperlink{P2}{(P2)} for the set $X$.

	Now let $z= p \a q = w $. Then $p \a q v = u p \a q $ where $ p \a q $ does not divide $u$ or $v$. We may assume that none of $u$ and $v$ is trivial because, otherwise, we would have $y = 0$ and there would be nothing to prove. It follows that the path $ v $ is divided by $ \a $.
	%	the $ \a $ appearing between $p$ and $q$ in the right-hand side is not the same as the $ \a $ appearing in the left-hand side.
	Consequently, we have $v = p_2 \a q $ for a proper subpath $p_2 $ of $p$ such that $p = p_1 p_2 $. In particular, we have $ ( p \a q ) p_2 = u p $ where $p $ does not divide $ p_2 $ and $ p \a q $ does not divide $ u $, implying that $ p $ overlaps from the left with $ p \a q $, a contradiction to property \hyperlink{P2}{(P2)} for the set $ X $.

	\smallskip

	\phantomsection	\hypertarget{stepII}{}	\textbf{Step II:} It holds that $y  $ satisfies properties (P) and $y \neq p a q$.

	Recall that
	\[
	y = \ctip ( z )^{-1} \cdot z v - \ctip ( w )^{-1} \cdot u w .
	\]
	Therefore, every path occurring in $y$ is of the form $ s v $ or $ u t $ for paths $ s $ and $ t $ occurring in $z$ and $w$, respectively. More generally, the paths $ s $ and $ t $ occur in $X$. It suffices to prove that the paths of the form $ s v $ as above satisfy properties \hyperlink{P1}{(P)} and avoid $ \a $, and the proof for paths of the form $ u t $ is analogous. We assume that $ v $ is non-trivial as, otherwise, there is nothing to prove.

	\hyperlink{P1}{(P1)} The equality $\tip (z) v = u \tip (w )  $, where the paths $\tip (w )$ and $\tip (z) $ do not divide $v$ and $u$, respectively, implies that the paths $u$ and $v$ avoid $ \a $. Indeed, this follows from property \hyperlink{P1}{(P1)} for $X$ and the fact that $z$ and $w$ avoid $ \a $ (\hyperlink{stepI}{Step I}{}). In particular, the paths of the form $ s v $  avoid $ \a $.

	\hyperlink{P2}{(P2)} We assume now that $p$ overlaps with a path $ s v $ from the left. Then either $p$ overlaps with $ v $ from the left, implying that $p$ overlaps with $\tip (w )$ from the left, or $p$ overlaps with $ s $ from the left. In both cases, we have reachead a contradiction as both $ \tip (w) $ and $ s $ occur in $X $.

	\hyperlink{P2op}{(P2)$^{\textrm{op}}$} If $q$ overlaps with $ s v $ from the right, then either $q$ overlaps with $ s $ from the right or $ s $ divides $q$. This is a contradiction in either case, as $X$ satisfies properties \hyperlink{P2op}{(P2)$^{\textrm{op}}$} and \hyperlink{P3}{(P3)}.


	\hyperlink{P3}{(P3)} Assume that a path of the form $ s v $ divides $p $ or $q$. Then $ s  $ divides $p $ or $ q$, a contradiction as $X$ satisfies property \hyperlink{P3}{(P3)}.

	\smallskip

	\phantomsection	\hypertarget{stepIII}{}	\textbf{Step III:} Consider elements $f , g \in k Q$ such that $g \neq p a q$, the set $\{ f, g\}$ satisfies properties \hyperlink{P1}{(P)}, and $\tip ( g ) = c \tip ( f ) d $ for paths $c$ and $d$. Then the element
	\[
	h = g - ( \ctip (g ) \ctip ( f )^{-1} ) \cdot c f d
	\]
	satisfies properties \hyperlink{P1}{(P)} and $h \neq p a q $.

	%Note that it suffices to show that all paths of the form $c s d$ satisfy properties \hyperlink{P1}{(P)} and avoid $ \a $, where $s$ is a path occurring in $ f $. We omit the proof of property \hyperlink{P2op}{(P2)$^{\textrm{op}}$} as it is analogous to the proof of property \hyperlink{P2}{(P2)}.

	\hyperlink{P1}{(P1)} Since $ g \neq p \a q  $ and the set $ \{ f , g  \} $ satisfies property \hyperlink{P1}{(P1)}, we have that $ g $ avoids $ \a $. Now the equation $\tip ( g ) = c \tip ( f ) d $ implies that the pahts $ \tip ( f ) $, $c$ and $d$ avoid $ \a $ as the same holds for $\tip ( g )$. In particular, we have that $ f \neq p \a q $ and therefore $ f $ avoids $ \a $ as the set $ \{  f , g \} $ satisfies property \hyperlink{P1}{(P1)}.

	\hyperlink{P2}{(P2)} If $p$ overlaps with $ h $ from the left, then $p$ overlaps with $c s d $ from the left for some path $ s $ occurring in $ f $. There are three cases. If $p$ overlaps with $ d $ from the left, then $p$ overlaps with $ \tip ( g ) $ from the left. If $p$ does not overlap with $d$ from the left but it does so with $ s d $, then $p$ overlaps with $ s $ from the left. If $p$ does not overlap with $ d $ or $ s d $ from the left then it does so with $c s d $, in which case $s$ divides $ p $. All three cases contradict the assumption that the set $ \{ f ,  g \} $ satisfies properties \hyperlink{P2}{(P2)} and \hyperlink{P3}{(P3)}.
	We omit the proof of property \hyperlink{P2op}{(P2)$^{\textrm{op}}$} as it is analogous to the proof of property \hyperlink{P2}{(P2)}.

	\hyperlink{P3}{(P3)} If a path occurring in $ h $ divides $ p $ or $ q $, then it has to be of the form $c s d $ for some path $ s $ occurring in $ f $. But then $s $ divides $p$ or $q$, a contradiction to the fact that the set $ \{ f ,  g \} $ satisfies property \hyperlink{P3}{(P3)}.

	\smallskip

	A careful examination of \cref{reformI}{} shows that $r$ satisfies properties \hyperlink{P1}{(P)} and is not equal to $ p \a q $ according to \hyperlink{stepII}{Step II}{} and \hyperlink{stepIII}{Step III}{}. Specifically, we have that the element $y_0 = y $ satisfies properties \hyperlink{P1}{(P)} and is not equal to $ p \a q $ according to \hyperlink{stepII}{Step II}{}. Assume now that the elements $y_j$ and $y_{j+1}$ are non-zero for some non-zero integer $ j $, where $y_j $ satisfies properties \hyperlink{P1}{(P)} and is not equal to $ p \a q $. If $y_j$ satisfies \hyperlink{ruleII}{Rule II}, then \hyperlink{stepIII}{Step III}{} implies that $ y_{j+1} $ satisfies properties \hyperlink{P1}{(P)} and is not equal to $ p \a q $. If $y_j$ satisfies \hyperlink{ruleIII}{Rule III}, then we reach the same conclusion trivially. The lemma follows now from the fact that every path occurring in $r$ occurs in $y_j$ for some non-negative integer $ j $.
	%
	%	then the element $y_{j+1} $ satisfies properties \hyperlink{P1}{(P)} and is not equal to $ p \a q $. If the elements $y_j$ and $y_{j+1}$ are non-zero and $y_j $ satisfies properties \hyperlink{P1}{(P)} and \hyperlink{ruleIII}{Rule III}, and is not equal to $ p \a q $, then it holds trivially that $y_{j+1} $ also satisfies properties \hyperlink{P1}{(P)} and is not equal to $ p \a q $.
\end{proof}


	\begin{exam}
		\label{exam:1''}
	Let $ \La = k Q / I $ be the bound quiver algebra of \cref{exam:1}{}. We show that $ I $ possesses a strict $ \a $-monomial Gr\"{o}bner basis with respect to any admissible order on $ \BQ $, even though the quotient algebra $ \La / \la \ol{ \a } \ra $ is not a strict monomial arrow removal of $ \La $ according to \cref{exam:1'}{}.

	Recall that $ T = T_{p, q}$ is the reduced Gr\"{o}bner basis for $ I $ with respect to any admissible order on $ \BQ $ such that $ \g_1 \d_1 $ is smaller than $ \g_2 \d_2 $. It is easy to see that $ T = T_{p, q}$ is strict $\a$-monomial as a Gr{\"o}bner basis by verifying property \hyperlink{P1}{(P1)} for $ T $ and properties \hyperlink{P2}{(P2)}, \hyperlink{P2op}{(P2)$^{\textrm{op}}$} and \hyperlink{P3}{(P3)} for $ \tip( T ) $. It should be noted that $ T $ is not strict $ \a $-monomial as a generating set for $ I $.

	On the other hand, if the fixed admissible order on $ \BQ $ is such that $ \g_2 \d_2 $ is smaller than $ \g_1 \d_1 $, then the Gr\"{o}bner basis $ \tilde{ T } = T \cup \{ \th \a \b \g_2 \d_2  \}$ constructed from $ T $ is not strict $ \a $-monomial. However, the reduced Gr\"{o}bner basis $\tilde{ T } \setminus \{ \th \a \b \g_1 \d_1 \} $ is strict $\a $-monomial, which is straightforward to verify.
\end{exam}




We close this section by noting that a loop can never be removed through a strict monomial arrow removal.


\begin{cor}
	If $ \a $ is a loop, the quotient algebra $\La / \la \ol{ \a } \ra $ is never a strict monomial arrow removal of $\La = k Q / I$.
\end{cor}

\begin{proof}
	Direct application of \cref{lem:1}{} and \cref{rem:1}{}.
\end{proof}


