{\color{red} NEVER USED

	We end this section by discussing cleft extensions with special
	properties.  In the application discussed in
	\cref{sec:cleft-findim}\marginpar{In previous paper} the square of $F$
	is zero, and the functor $\ml$ is exact and the functor $\me$
	preserves projectives.  The remaining results concern cleft extensions
	having some of these properties or generalizations thereof.

	\begin{lem}
		\label{lemnilpotentfunctors}
		Let $(\B,\A,\me, \ml, \mi)$ be a cleft extension of abelian categories.
		The following statements hold.
		\begin{enumerate}[\rm(i)]
			\item For any $n\geq 1$, there is a natural isomorphism $\me G^n\simeq F^n\me$.

			\item Let $n\geq 1$. Then $F^n=0$ if and only if $G^n=0$.
		\end{enumerate}
	\end{lem}

	From now on we make the following assumption on a cleft extension $(\B,\A,\me, \ml, \mi)$ of abelian categories:
	\begin{equation}
		\label{assumptionscleftext}
		\text{The functor} \ \ml \ \text{is exact and the functor} \ \me \ \text{preserves projectives.}
	\end{equation}

	We continue with the following useful results.\marginpar{Add proofs?}

	\begin{lem}\label{corpropofF}
		Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
		categories such that condition $(\ref{assumptionscleftext})$
		holds. Then the functor $F$ is exact and preserves projective
		objects.
	\end{lem}


	\begin{lem}\label{lem:FGequivalence}
		Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
		categories such that condition $(\ref{assumptionscleftext})$
		holds. Moreover, assume that $F^n=0$ for some $n\geq 2$. Let $A$ be
		an object in $\A$. Then the following statements are equivalent:
		\begin{enumerate}[\rm(i)]
			\item $G^{n-1}(A)$ lies in $\Proj\A$. 
			\item $F^{n-1}\me(A)$ lies in $\Proj\B$. 
		\end{enumerate}
	\end{lem}

	\begin{lem}
		Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
		categories such that condition $(\ref{assumptionscleftext})$
		holds. 
		\begin{enumerate}[\rm(a)]
			\item If $\Image G \subseteq \Proj^m(\A)$, then
			$\Image F \subseteq \Proj^m(\B)$.
			\item If $F^n = 0$ $($or equivalently $G^n = 0)$, then $\pd_\B
			F(\me(A)) \leq m$ implies that $\pd_\A G(A) \leq m+n$.  
		\end{enumerate}
	\end{lem}
	\begin{proof}
		(a) Since $\me$ is dense, there exists $A$ in $\A$ such that $\me(A)\simeq
		B$ for any $B$ in $\B$. By \cref{lemnilpotentfunctors} we have
		$\me G(A) \simeq F\me(A)$.  If $\Image G \subseteq \Proj^m(\A)$, then
		$\pd_\A \me(G(A)) \leq m$.  Since $\me$ is exact and preserves
		projectives, $\pd_\B \me(G(A)) \leq m$. This imples that $\pd_\B
		F(\me(A)) \leq m$, hence $\Image F \subseteq \Proj^m(\B)$. 

		(b) By \cref{lemnilpotentfunctors} we have $\me G^i(A) \simeq
		F^i\me(A)$ for all $A$ in $\A$ and for all $i\geq 1$, so that $\pd_\B
		\me(G^i(A)) \leq m$ for all $A$ in $\A$ and for all $i\geq 1$, since
		$\me$ preserves projective objects.  As $\ml$ is exact and preserves
		projective objects, we infer that $\pd_\A \ml\me(G^i(A)) \leq m$ for
		all $A$ in $\A$ and for all $i\geq 1$.  

		Assume that $F^n = 0$ or equivalently that $G^n = 0$.  Repeated use of
		the exact sequence 
		\[0\to G(A) \to \ml\me(A) \to A \to 0\]
		we obtain an exact sequence 
		\[0\to \ml\me(G^{n-1}(A)) \to \ml\me(G^{n-2}(A)) \to \cdots \to
		\ml\me(G^2(A)) \to \ml\me(G(A)) \to G(A) \to 0.\]
		By (a) the projective dimension of $\ml\me(G^i(A))$ is at most $m$ and
		the above resolution has length $n-1$, for which we infer that $\pd_\A
		G(A) \leq m + n$.   This completes the proof. 
\end{proof}}








\subsection{Cleft extensions of abelian categories and singularity
	categories}

\begin{lem}\label{lem:singcatcleftextab}
	Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
	categories. Consider the following conditions.
	\begin{enumerate}[\rm(i)]
		\item $\sup\{ \pd_\B \me(P)\mid P\in\Proj(\A)\} = p_\A$ for some integer $p_\A$. 
		\item $\sup\{ \pd_\A \mi(F)\mid F\in\Proj(\B)\} = p_\B$ for some integer $p_\B$. 
		\item $\sup\{ \pd_\A H(B) \mid B\in\B\} = n_H$ for some integer
		$n_H$. 
		\item $\sup\{ \pd_\A G(A) \mid A\in\A\} = n_G$ for some integer  $n_G$. 
	\end{enumerate}
	\begin{enumerate}[\rm(a)]
		\item If \textup{(ii)} holds, then $\mi\colon \B\to\A$ induces a
		functor $\mi\colon \Dsg(\B) \to \Dsg(\A)$. 
		\item If \textup{(i)} holds, then $\me\colon \A \to \B$ induces a
		functor $\me\colon \Dsg(\A) \to \Dsg(\B)$. 
		\item If \textup{(i)} and \textup{(ii)} hold, then $\me\mi\colon
		\Dsg(\B) \to \Dsg(\B)$ is isomorphic to the identity functors. 
		\item If $\ml$ is an exact functor, then $\ml\colon \B \to \A$ induces
		a functor $\ml\colon \Dsg(\B) \to \Dsg(\A)$. 
		\item If \textup{(i)} and \textup{(iv)} hold and $\ml$ is an exact
		functor, then $\ml\me\colon \Dsg(\A) \to \Dsg(\A)$ is isomorphic to
		the identity functor. 
		\item If \textup{(i)}--\textup{(iv)} hold and the
		functor $\ml$ is exact, then $\me\colon \Dsg(\A) \to \Dsg(\B)$ is a
		singular equivalence. 
	\end{enumerate}
\end{lem}
\begin{proof}
	(a) Since the functor $\mi\colon \B \to \A$ is exact, we have an
	induced functor $\mi\colon \mD(\B) \to \mD(\A)$.  By property (ii) the
	functor $\mi$ induce a functor $\mi\colon \mD^\perf(\B) \to
	\mD^\perf(\A)$.  The claim follows from this.

	(b) This follows as the claim in (a).

	(c) This follows from (a) and (b) and the fact that $\me\mi \simeq
	\iden_\B$. 

	(d) Since the functor $\ml\colon \B \to \A$ preserves projective
	objects, the claim is immediate.

	(e) By (b) and (d) the functors $\me$ and $\ml$ induce functors on the
	singularity categories.  Having the exact sequence
	\[0\to G(A) \to \ml\me(A) \to A \to 0\]
	and property (iv) ensure that the composition of $\ml$ and $\me$ is
	isomorphic to the identity.

	(f) By (c) the composition of $\me$ and $\mi$ is the identity functor
	on $\Dsg(\B)$.  From (e) the composition of $\ml$ and $\me$ is
	isomorphic to the identity functor on $\Dsg(\A)$.  Using the exact
	sequence of functors
	\[0\to H\to \ml \to \mi \to 0\]
	and property (iii), we infer that $\ml\me$ and $\mi\me$ are isomorphic
	as endofunctors of $\Dsg(\A)$.  The claim follows from this.
\end{proof}




\section{Cleft extensions and eventually homological isomorphisms}

Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
categories.  Then the functor $\me\colon \A\to \B$ is an exact
functor, so it always induces homomorphism of the following Yoneda
rings  
\[\me\colon \Ext^*_\A(A,A) \to \Ext^*_\B( \me(A),\me(A) )\]
for all $A$ in $\A$.  Recall from \cite[Section 3]{PSS} that $\me$ is
called an \emph{eventually homological isomorphism} if 
\[\Ext^i_\A(A,A) \simeq \Ext^i_\B( \me(A),\me(A) )\]
for every $i > t$ for some $t$. The definition do not require that the
isomorphism is induced by the functor $\me$.  In this section we
describe one situation where $\me$ is an eventually homological
isomorphism.  

\subsection{Cleft extensions of abelian categories}

\begin{lem}\label{lem:commdiagcleft}
	Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
	categories with $\ml\colon \B\to\A$ an exact functor and the functor
	$\me\colon \A\to\B$ preserving projective objects.  Then the following
	diagram commutes
	\[\xymatrix{
		\Ext^i_\A(C,A) \ar[r]^-\me\ar@{=}[d] & \Ext^i_\B(\me(C),\me(A)) \\
		\Ext^i_\A(C,A) \ar[r]^-{\mu_C^*} & \Ext^i_\A(\ml\me(C),A)
		\ar[u]_{\theta_{\me(C),A}}},\]
	where the vertical maps are isomorphisms. 
\end{lem}
\begin{proof}
	Let $m\geq 1$, and let $f\in\Ext^m_\A(C,A)$ be represented by a
	morphism $f\colon \Omega_\A^m(C)\to A$.  Then consider the following
	commutative diagram 
	\[\xymatrix{
		0\ar[r] & \Omega_\A^m(C) \ar[r]\ar[d]_f & P_{m-1} \ar[r]\ar[d] & P_{m-2}\ar[r]\ar@{=}[d] &
		\cdots \ar[r] & P_0\ar[r]\ar@{=}[d] & C \ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & A \ar[r] & M \ar[r] & P_{m-2}\ar[r] &
		\cdots\ar[r] & P_0\ar[r] & C \ar[r] & 0
	}\]
	Apply the functor $\me$ to this diagram and obtain the following
	diagram
	\[\xymatrix@C15pt{
		0\ar[r] & \me(\Omega_\A^m(C)) \ar[r]\ar[d]_{\me(f)} & \me(P_{m-1}) \ar[r]\ar[d] & \me(P_{m-2})\ar[r]\ar@{=}[d] &
		\cdots \ar[r] & \me(P_0)\ar[r]\ar@{=}[d] & \me(C) \ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & \me(A) \ar[r] & \me(M) \ar[r] & \me(P_{m-2})\ar[r] &
		\cdots\ar[r] & \me(P_0)\ar[r] & \me(C) \ar[r] & 0
	}\]
	The lower row represents the image of $f$ under the functor $\me$. 

	By the adjungtion $\sigma\colon \Hom_\B(\me(\Omega_\A^m(C)),\me(A))
	\simeq \Hom_\A(\ml\me(\Omega_\A^m(C)), A)$ the morphism $\me(f)$
	corresponding to $\sigma(\me(f))\colon \ml\me(\Omega_\A^m(C))\to A$.
	This last morphism is equal to the composition of the morphisms 
	\[\ml\me(\Omega_\A^m(C))\xrightarrow{\ml(f)} \ml\me(A)
	\xrightarrow{\sigma(1_{\me(A)}} A.\]
	In addition we have the following two commutative diagrams
	\[\xymatrix{
		0\ar[r] & \ml\me(A) \ar[r]\ar[d]^{\sigma(1_{\me(A)})} & \ml\me(M) \ar[r]\ar[d]^s &
		\ml\me(\Omega_\A^{m-1}(C))\ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & A \ar[r]\ar@{=}[d] & E \ar[r]\ar[d]^t &
		\ml\me(\Omega_\A^{m-1}(C))\ar[r]\ar[d]^{\sigma(1_{\Omega_\A^{m-1}(C)})} & 0\\
		0\ar[r] & A \ar[r] & M \ar[r] & \Omega_\A^{m-1}(C)\ar[r] & 0
	}\]
	and 
	\[\xymatrix{
		0\ar[r] & \ml\me(\Omega_\A^1(C)) \ar[r]\ar[d]^{\sigma(1_{\me(\Omega_\A^1(C)}))} & \ml\me(P_0) \ar[r]\ar[d]^{s'} &
		\ml\me(C)\ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & \Omega_\A^1(C) \ar[r]\ar@{=}[d] & E' \ar[r]\ar[d]^{t'} &
		\ml\me(C)\ar[r]\ar[d]^{\sigma(1_{C})} & 0\\
		0\ar[r] & \Omega_\A^1(C) \ar[r] & P_0 \ar[r] & C\ar[r] & 0
	}\]
	with $ts = \sigma(1_{\me(M)})$ and $t's' =
	\sigma(1_{\me(P_0)})$. Using these commutative diagrams we can
	construct the following commutative diagram 
	\[\xymatrix@C11pt{
		0\ar[r] & \ml\me(\Omega_\A^m(C)) \ar[r]\ar[d]_{\ml\me(f)} &
		\ml\me(P_{m-1}) \ar[r]\ar[d] & \ml\me(P_{m-2})\ar[r]\ar@{=}[d] & 
		\cdots \ar[r] & \ml\me(P_1)\ar[r]\ar@{=}[d] & \ml\me(P_0)\ar[r]\ar@{=}[d] & \ml\me(C) \ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & \ml\me(A) \ar[r]\ar[d]_{\sigma(1_{\me(A)})} & \ml\me(M) \ar[r]\ar[d]^s & \ml\me(P_{m-2})\ar[r]\ar@{=}[d] &
		\cdots\ar[r] & \ml\me(P_1)\ar[r]\ar@{=}[d]
		&\ml\me(P_0)\ar[r]\ar@{=}[d] & \ml\me(C) \ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & A \ar[r]\ar@{=}[d] & E \ar[r]\ar[d]^t & \ml\me(P_{m-2})\ar[r]\ar[d]^{\sigma(1_{P_{m-2}})} &
		\cdots\ar[r] & \ml\me(P_1)\ar[r]\ar[d]^{\sigma(1_{P_1})}
		&\ml\me(P_0)\ar[r]\ar[d]^{s'} & \ml\me(C) \ar[r]\ar@{=}[d] & 0\\
		0\ar[r] & A \ar[r]\ar@{=}[d] & M \ar[r]\ar@{=}[d] &
		P_{m-2}\ar[r]\ar@{=}[d] &\cdots\ar[r]
		& P_1\ar[r]\ar@{=}[d] & E'\ar[r]\ar[d]^{t'} & \ml\me(C)\ar[r]\ar[d]^{\sigma(1_{\me(C)})} & 0\\
		0\ar[r] & A\ar[r] & M\ar[r] & P_{m-2}\ar[r] & \cdots\ar[r] & P_1\ar[r]
		& P_0\ar[r] & C\ar[r] & 0
	}\]
	The third row in the above diagram corresponds to the
	$\theta^{-1}_{\me(C),A}(\me(f))$, and the fourth row in the above
	diagram corresponds to the image of $f$ under the map $\mu_C^*$.  It
	follows that the diagram in the statement is commutative. 
\end{proof}


\begin{thm}\label{thm:cleftabelianeventuallyisom}
	Let $(\B,\A, \me, \ml, \mi)$ be a cleft extension of abelian
	categories with $\ml\colon \B\to\A$ an exact functor and the functor
	$\me\colon \A\to\B$ preserving projective objects. Assume that 
	\[\sup\{\pd_\A G(A) \mid A\in\A\} \leq n_\A\]
	for some integer $n_\A$.  Then the functor $\me\colon \A\to \B$ is an
	$n_\A$-eventually homological isomorphism.
\end{thm}
\begin{proof}  
	Using the commutative diagram in \cref{lem:commdiagcleft} and the
	long exact sequence induced from the exact sequence
	\[0\to G(C)\to \ml\me(C) \to C \to 0\]
	applying the functor $\Ext^*_\A(-,A)$, in fact the functor $\me$
	induces an isomorphism between $\Ext^i_\A(C,A)$ and
	$\Ext^i_\B(\me(C),\me(A))$ for $i > n_\A$. 
\end{proof}

\subsection{Cleft extensions from arrow removal}

Let $\Lambda=kQ/I$ be an admissible quotient of a path algebra $kQ$.
Recall that if $a$ is an arrow in $Q$ which is not occurring in a
minimal generating set for $I$, then we refer to the quotient
$\Gamma = \Lambda/\langle \overline{a} \rangle$ as \emph{arrow
	removal}.   

\begin{thm}
	Let $\Lambda=kQ/I$ be an admissible quotient of a path algebra $kQ$,
	and suppose $a$ is an arrow in $Q$ such that $\Gamma = \Lambda/\langle
	\overline{a} \rangle$ is an arrow removal. Then $\Lambda$ is
	Gorenstein if and only if $\Gamma$ is Gorenstein.
\end{thm}
\begin{proof}
	By \cite[Proposition 4.6]{GPS} the algebras $\Gamma$ and $\Lambda$
	forms a cleft extension of algebras with $\Image G \subseteq
	\Proj(\Lambda)$, and $_\Gamma\Lambda$ and $\Lambda_\Gamma$ are
	projective modules.  This implies that $\ml$ is exact and $\me$
	preserves projective objects. By
	\cref{thm:cleftabelianeventuallyisom} the functor $\me$ induces an
	eventually homological isomorphism.  Since $\me$ is an essentially
	surjective eventually homological isomorphism, $\Lambda$ is Gorenstein
	if and only if $\Gamma$ is Gorenstein by \cite[Theorem 4.3 (v)]{PSS}.  
\end{proof}

\begin{prop}
	Let $\Lambda=kQ/I$ be an admissible quotient of a path algebra $kQ$,
	and suppose $a$ is an arrow in $Q$ such that $\Gamma = \Lambda/\langle
	\overline{a} \rangle$ is an arrow removal.  Let $\nu\colon \Gamma \to
	\Lambda$ and $\pi\colon \Lambda \to \Gamma$ be the algebra
	homomorphism defining the cleft extension.  Then the following
	assertions hold. 
	\begin{enumerate}[\rm(a)]
		\item The algebra
		homomorphisms 
		\[\nu\otimes\nu \colon \Gamma^{\opp}\otimes_k \Gamma \to
		\Lambda^{\opp}\otimes_k\Lambda\]
		and 
		\[\pi\otimes\pi \colon \Lambda^{\opp}\otimes_k\Lambda \to
		\Gamma^{\opp}\otimes_k \Gamma\] 
		defines $\Gamma^\evl=\Gamma^{\opp}\otimes_k \Gamma$ and $\Lambda^\evl =
		\Lambda^{\opp}\otimes_k\Lambda$ as a cleft extension.
		\item $_{\Gamma^\evl}\Lambda^\evl$ and $\Lambda^\evl_{\Gamma^\evl}$
		are projective modules.
		\item The restriction functor $\me^\evl$ along the algebra
		homomorphism $\nu\otimes\nu$ preserves projective modules (and is
		exact), and the functor 
		\[\ml^\evl= - \otimes_{\Gamma^\evl}\Lambda^\evl\colon
		\smod\Gamma^\evl\to \smod\Lambda^\evl\]
		is exact. 
	\end{enumerate}
\end{prop}
\begin{proof}
	(a) It is straightforward to see that $(\pi\otimes\pi)(\nu\otimes\nu)
	= \id_{\Gamma^\evl}$. 

	(b) Since $\Lambda$ and $\Gamma$ is an arrow removal, $_\Gamma\Lambda$
	and $\Lambda_\Gamma$ are projective modules.  Since
	$_{\Gamma^\evl}\Lambda^\evl \simeq {_\Gamma\Lambda^{\opp}}\otimes_k
	\Lambda_\Gamma$, it follows that $_{\Gamma^\evl}\Lambda^\evl$ is a
	projective module over $\Gamma^\evl$.  Similarly we infer that
	$\Lambda^\evl_{\Gamma^\evl}$ is a projective module over
	$\Gamma^\evl$.   

	(c) Both of the claims follows from (b).
\end{proof}


\begin{lem}\label{lem:FG-properties}
	Let $\Lambda$ and $\Gamma$ be a cleft extension given by the
	homomorphism $\Gamma\xrightarrow{\nu} \Lambda \xrightarrow{\pi}
	\Gamma$. Then the following hold
	\begin{enumerate}[\rm(a)]
		\item For a $\Gamma$-bimodule $B$ the endofunctor $F$ of
		$\smod\Gamma$ applied to $B$ defines a $\Gamma$-bimodule and the
		exact sequence 
		\[0\to F(B) \to B\otimes_\Gamma \Lambda
		\xrightarrow{\operatorname{mult}} B\to 0\]
		splits as a sequence of $\Gamma$-bimodules. 
		\item When $\Lambda_\Gamma$ is projective we have for a
		$\Gamma$-bimodule $B$ we have 
		\[F(\Lambda\otimes_\Gamma B) = \Lambda\otimes_\Gamma F(B).\]
		\item Let $F^{\opp}$ be the endofunctor of $\smod\Gamma^{\opp}$ considering
		$\Gamma^{\opp}$ and $\Lambda^{\opp}$ as a cleft extension of algebras.
		When $\Lambda_\Gamma$ is projective, we have for a $\Gamma$-bimodule $B$ 
		\[F^\evl(B)  \simeq \Lambda\otimes_\Gamma F(B_\Gamma) \oplus F^{\opp}({_\Gamma B}).\]
		\item For a $\Lambda$-bimodule $B$ the endofunctor $G$ of
		$\smod\Lambda$ applied to $B$ defines a $\Lambda$-bimodule. 
		\item For a $\Lambda$-bimodule $B$ we have
		\[G(\Lambda\otimes_\Gamma B) = \Lambda\otimes_\Gamma G(B).\]
		\item Let $G^{\opp}$ be the endofunctor of $\smod\Lambda^{\opp}$ considering
		$\Gamma^{\opp}$ and $\Lambda^{\opp}$ as a cleft extension of algebras.
		For a $\Lambda$-bimodule $B$ we have an exact sequence
		\[0\to \Lambda\otimes_\Gamma G(B_\Lambda) \to G^\evl(B) \to
		G^{\opp}({_\Lambda B})\to 0.\]
		\item If $\Lambda$ and $\Gamma$ is an arrow removal, then
		\begin{enumerate}[\rm(i)]
			\item $(F^\evl)^2(\me^\evl(\Lambda)) = 0$, 
			\item $(G^\evl)^2(\Lambda) = 0$, 
			\item $G^\evl(\Lambda)$ is a projective $\Lambda$-bimodule,
		\end{enumerate}
	\end{enumerate}
\end{lem}
\begin{proof}
	(d) Let $B$ be a $\Gamma$-bimodule and consider the exact sequence
	\[0\to F(B_\Gamma) \to B\otimes_\Gamma \Lambda
	\xrightarrow{\textrm{mult}} B_\Gamma \to 0,\]
	where the map $\textrm{mult}$ is a homomorphism of
	$\Gamma$-bimodules. This implies that $F(B_\Gamma)$ is a
	$\Gamma$-bimodule whenever $B$ is a $\Gamma$-bimodule.  The above
	exact sequence splits as right $\Gamma$-modules, but the splitting is
	also a homomorphism of $\Gamma$-bimodules.  Hence the final claim
	follows. 

	(b) Let $B$ be a $\Gamma$-bimodule and consider the exact sequence
	\[0\to F(B_\Gamma) \to B\otimes_\Gamma \Lambda_\Gamma 
	\xrightarrow{\textrm{mult}(1\otimes \pi)}  B_\Gamma \to 0.\]

	Tensoring this exact sequence with $\Lambda\otimes_\Gamma-$ we get the
	following exact commutative diagram
	\[\xymatrix{ 
		0 \ar[r] & \Lambda\otimes_\Gamma F(B_\Gamma)\ar[r]\ar@{=}[d] 
		&  \Lambda\otimes_\Gamma B\otimes_\Gamma \Lambda_\Gamma \ar[rr]^-{1\otimes
			\textrm{mult}(1\otimes \pi)} \ar@{=}[d] & & \Lambda\otimes_\Gamma B_\Gamma
		\ar[r]\ar@{=}[d]  & 0\\
		0 \ar[r] & F(\Lambda\otimes_\Gamma B_\Gamma)\ar[r] 
		&  \Lambda\otimes_\Gamma B\otimes_\Gamma \Lambda_\Gamma
		\ar[rr]^-{\textrm{mult}((1_{\Lambda\otimes_\Gamma B})\otimes \pi)} & & \Lambda\otimes_\Gamma B_\Gamma
		\ar[r] & 0
	}\]
	The claim follows from this. 

	(c) Recall that $F^\evl$ is given by the exact sequence 
	\[0\to F^\evl \to \me^\evl\ml^\evl \to \iden_{\smod\Gamma^\evl} \to 0\]
	Let $B$ be a $\Gamma$-bimodule. Then $\ml^\evl(B) =
	\Lambda\otimes_\Gamma B\otimes_\Gamma \Lambda$, so that
	\[\me^\evl\ml^\evl(B) = {_\Gamma\Lambda\otimes_\Gamma B\otimes_\Gamma\Lambda_\Gamma}.\] 
	We construct the following commutative diagram 
	\[\xymatrix{
		&  & & & 0\ar[d] & \\
		& 0\ar[d] & 0\ar[d] & & F^{\opp}({_\Gamma B})\ar[d] & \\
		0\ar[r] & \Lambda\otimes_\Gamma F(B_\Gamma)\ar[r]\ar[d] & \Lambda\otimes_\Gamma
		B\otimes_\Gamma \Lambda \ar[rr]^-{1\otimes (\textrm{mult}(1\otimes\pi))}\ar@{=}[d]
		& & \Lambda\otimes_\Gamma B \ar[r]\ar[d]^{\textrm{mult}(\pi\otimes 1)} & 0\\
		0\ar[r] & F^\evl(B)\ar[d]\ar[r] & \Lambda\otimes_\Gamma
		B\otimes_\Gamma \Lambda \ar[rr]^-{1\otimes (\textrm{mult}(1\otimes\pi))}
		& & B \ar[r]\ar[d] & 0\\
		& F^{\opp}({_\Gamma B})\ar[d] & & & 0 &\\
		& 0 &  & & &\\
	}\]
	We have 
	\begin{align}
		\Lambda\otimes_\Gamma B\otimes_\Gamma \Lambda & \simeq F^\evl(B)\oplus
		B\notag\\
		& \simeq \Lambda\otimes_\Gamma F(B)\oplus \Lambda\otimes_\Gamma
		B\notag\\
		&  \simeq \Lambda\otimes_\Gamma F(B)\oplus F^{\opp}(B) \oplus B\notag
	\end{align}
	which implies that $F^\evl(B) \simeq \Lambda\otimes_\Gamma F(B)\oplus
	F^{\opp}(B)$. 

	(d) Let $B$ be a $\Lambda$-bimodule and consider the exact sequence
	\begin{equation}\label{eq:G-sequence}
		0\to G(B_\Lambda) \to B\otimes_\Gamma \Lambda
		\xrightarrow{\textrm{mult}} B_\Lambda \to 0,\notag
	\end{equation}
	where the map $\textrm{mult}$ is a homomorphism of
	$\Lambda$-bimodules. This implies that $G(B_\Lambda)$ is a
	$\Lambda$-bimodule whenever $B$ is a $\Lambda$-bimodule. 

	(e) Let $B$ be a $\Lambda$-bimodule. Since $\Lambda_\Gamma$ is
	projective, tensoring the exact sequence \eqref{eq:G-sequence} with
	$\Lambda\otimes_\Gamma -$ leaves it exact and we obtain the following
	commutative diagram 
	\[\xymatrix{ 
		0 \ar[r] & \Lambda\otimes_\Gamma G(B_\Lambda)\ar[r]\ar@{=}[d] 
		&  \Lambda\otimes_\Gamma B\otimes_\Gamma \Lambda
		\ar[rr]^-{1_\Lambda\otimes\textrm{mult}_B} \ar@{=}[d] & &
		\Lambda\otimes_\Gamma B \ar[r]\ar@{=}[d]  & 0\\
		0 \ar[r] & G(\Lambda\otimes_\Gamma B)\ar[r] 
		&  \Lambda\otimes_\Gamma B\otimes_\Gamma \Lambda
		\ar[rr]^-{\textrm{mult}_{\Lambda\otimes_\Gamma B}} & & \Lambda\otimes_\Gamma B
		\ar[r] & 0
	}\]
	The claim follows from this. 

	(f) This follows in a similar way as for $F^\evl$, and it left to the
	reader. 

	(g) Let  $\Lambda$ and $\Gamma$ be an arrow removal, and let $B$ be a
	$\Gamma$-bimodule. Then 
	\begin{align}
		(F^\evl)^2(B) & = F^\evl(F^\evl(B))\notag\\
		& \simeq F^\evl(F(\Lambda\otimes_\Gamma B) \oplus F^{\opp}(B))\notag\\
		& = F(\Lambda\otimes_\Gamma (F(\Lambda\otimes_\Gamma B) \oplus
		F^{\opp}(B))) \oplus F^{\opp}(F(\Lambda\otimes_\Gamma B) \oplus
		F^{\opp}(B))\notag\\
		& = F(\Lambda\otimes_\Gamma F(\Lambda\otimes_\Gamma B)) \oplus
		F(\Lambda\otimes_\Gamma F^{\opp}(B))\notag\\
		& \rule{20mm}{0mm} \oplus F^{\opp}(F(\Lambda\otimes_\Gamma B)) \oplus
		F^{\opp}(F^{\opp}(B))\notag\\
		& = F^2(\Lambda\otimes_\Gamma\Lambda\otimes_\Gamma B) \oplus
		\Lambda\otimes_\Gamma FF^{\opp}(B) \oplus
		F^{\opp}F(\Lambda\otimes_\Gamma B) \oplus (F^{\opp})^2(B)\notag
	\end{align}
	Since $F^2 = 0$ for an arrow removal, we have 
	\[(F^\evl)^2(B) = \Lambda\otimes_\Gamma FF^{\opp}(B) \oplus
	F^{\opp}F(\Lambda\otimes_\Gamma B).\] 
	We have 
	\[FF^{\opp}(B) = \langle \overline{a} \rangle \otimes_\Gamma B
	\otimes_\Gamma \langle \overline{a} \rangle\quad \textrm{and} \quad
	F^{\opp}F(\Lambda\otimes_\Gamma B) = \langle \overline{a} \rangle
	\otimes_\Gamma \Lambda\otimes_\Gamma B\otimes_\Gamma \langle
	\overline{a} \rangle.\]
	When we specialize to $B = {_\Gamma\Lambda_\Gamma} =
	\me^\evl(\Lambda)$. Then  
	\begin{align}
		FF^{\opp}(\me^\evl(\Lambda)) & =  \langle \overline{a} \rangle
		\otimes_\Gamma (\Gamma\oplus \langle \overline{a}
		\rangle)\otimes_\Gamma \langle \overline{a} \rangle\notag\\
		& \simeq \langle \overline{a} \rangle\otimes_\Gamma \langle \overline{a}
		\rangle \oplus \langle \overline{a} \rangle\otimes_\Gamma \langle
		\overline{a} \rangle\otimes_\Gamma \langle \overline{a} \rangle = 0\notag
	\end{align}
	For similar reasons we obtain that $F^{\opp}F(\Lambda\otimes_\Gamma
	\Lambda) = 0$ and consequently $(F^\evl)^2(\me^\evl(\Lambda)) = 0$.
	Since $\me^\evl(G^\evl(B))^2 \simeq (F^\evl)^2(\me^\evl(B))$ and
	$\me^\evl$ is faithful, we infer that $(G^\evl)^2(\Lambda) = 0$.
	Using similar arguments as above $F^\evl(\me^\evl(\Lambda)) \simeq
	\langle \overline{a} \rangle$ as a $\Gamma$-bimodule.  For an arrow
	removal $\langle \overline{a} \rangle$ is a projective
	$\Gamma$-bimodule.  Then by the above $\me^\evl(G^\evl(\Lambda))$ is
	projective.  Since the functor $\ml^\evl$ preserves projective
	modules, the bimodule $\ml^\evl\me^\evl G^\evl(\Lambda)$ is
	projective.  We have the exact sequence
	\[0\to (G^\evl)^2(\Lambda) \to \ml^\evl\me^\evl G^\evl(\Lambda) \to
	G^\evl(\Lambda) \to 0,\]
	which implies that $G^\evl(\Lambda) \simeq \ml^\evl\me^\evl
	G^\evl(\Lambda)$ is a projective $\Lambda$-bimodule.  
\end{proof}


\begin{prop}
	If $\Lambda$ and $\Gamma$ is an arrow removal, then
	\[\Ext^*_{\Lambda^\evl}(\Lambda,\Lambda) \simeq
	\Ext^*_{\Gamma^\evl}(\Gamma,\Gamma \oplus \Ker\pi)\]
	is an isomorphism for $* > 1$.
\end{prop}
\begin{proof}
	As above we have
	the exact sequence 
	\[0\to G^\evl(\Lambda) \to \ml^\evl\me^\evl(\Lambda) \to
	\Lambda \to 0.\]
	By \cref{lem:FG-properties} (g) the bimodule $G^\evl(\Lambda)$ is
	projective, and then using \cref{lem:commdiagcleft} 
	\[\Ext^*_{\Lambda^\evl}(\Lambda,\Lambda) \simeq
	\Ext^*_{\Gamma^\evl}(\me^\evl(\Lambda),\me^\evl(\Lambda))\]
	for $i > 1$.  The restriction $\me^\evl(\Lambda) \simeq \Gamma \oplus
	\langle \overline{a} \rangle$, where $\langle \overline{a} \rangle$ is
	a projective $\Gamma$-bimodule.  This implies that 
	\[\Ext^*_{\Lambda^\evl}(\Lambda,\Lambda) \simeq
	\Ext^*_{\Gamma^\evl}(\Gamma,\Gamma \oplus \langle \overline{a} \rangle),\]
	and it completes the proof. 
\end{proof}

\begin{lem}
	Let $M$ be a right $\Lambda$-module and $B$ a $\Lambda$-bimodule. Then
	the map 
	\[\me(M)\otimes_\Gamma\me^\evl(B) \xrightarrow{\varphi}
	\me(M\otimes_\Lambda B)\]
	given by $m\otimes b \mapsto m\otimes b$ is well-defined, functorial
	in both variables, and an onto map of right $\Gamma$-modules. 
\end{lem}
\begin{proof}
	The module $\me(M)\otimes_\Gamma\me^\evl(B) = M_\Gamma \otimes_\Gamma
	{_\Gamma B_\Gamma}$ and the module $\me(M\otimes_\Lambda B) =
	M\otimes_\Lambda B_\Gamma$. Therefore the map $\varphi$ is the natural
	projection. 
\end{proof}

\begin{prop}\label{prop:commutativeFGdiagram}
	The diagram is commutative
	\[\xymatrix{
		\Ext^*_{\Lambda^\evl}(\Lambda,\Lambda) \ar[rr]^{M\otimes_\Lambda-}
		\ar[ddd]_{\me^\evl} & & \Ext^*_\Lambda(M,M)\ar[d]^\me \\
		& & \Ext^*_\Gamma( \me(M),\me(M) )\ar[d]^{\Ext^*_\Gamma(\varphi,-)} \\
		& & \Ext^*_\Gamma( \me(M)\otimes_\Gamma\me^\evl(\Lambda), \me(M))\\
		\Ext^*_{\Gamma^\evl}(\me^\evl(\Lambda), \me^\evl(\Lambda))
		\ar[rr]^-{\me(M)\otimes_\Gamma-} & & \Ext^*_\Gamma(
		\me(M)\otimes_\Gamma\me^\evl(\Lambda), \me(M)\otimes_\Gamma
		\me^\evl(\Lambda)) \ar[u]_{\Ext^*_\Gamma(-,\varphi)}
	}\]
\end{prop}
\begin{proof}
	Let $\eta\colon \Omega^n_{\Lambda^\evl}(\Lambda)\to \Lambda$ represent
	an element in $\Ext^n_{\Lambda^\evl}(\Lambda,\Lambda)$. As an
	extension $\eta$ correspond to the lower row in the following
	commutative diagram
	\[\xymatrix{
		0\ar[r] & \Omega^n_{\Lambda^\evl}(\Lambda) \ar[r]\ar[d]_\eta &
		P_{n-1}\ar[r]\ar[d] & P_{n-2}\ar[r]\ar@{=}[d] & \cdots\ar[r] &
		P_0\ar[r]\ar@{=}[d] & \Lambda\ar[r] \ar@{=}[d] & 0\\
		0\ar[r] & \Lambda\ar[r] & E\ar[r] & P_{n-2}\ar[r] & \cdots\ar[r] &
		P_0\ar[r] & \Lambda\ar[r] & 0
	}\]
	where the first row is the start of a projective resolution of
	$\Lambda$ over $\Lambda^\evl$.  Tensoring this diagram with $M$ over
	$\Lambda$ we obtain the extension $M\otimes_\Lambda\eta$ as the lower
	row in the following commutative diagram
	\[\xymatrix@C7pt{
		0\ar[r] & M\otimes_\Lambda\Omega^n_{\Lambda^\evl}(\Lambda) \ar[r]\ar[d]_{M\otimes\eta} &
		M\otimes_\Lambda P_{n-1}\ar[r]\ar[d] & M\otimes_\Lambda P_{n-2}\ar[r]\ar@{=}[d] & \cdots\ar[r] &
		M\otimes_\Lambda P_0\ar[r]\ar@{=}[d] & M\otimes_\Lambda\Lambda\ar[r] \ar@{=}[d] & 0\\
		0\ar[r] & M\otimes_\Lambda\Lambda\ar[r] & M\otimes_\Lambda E\ar[r] & M\otimes_\Lambda P_{n-2}\ar[r] & \cdots\ar[r] &
		M\otimes_\Lambda P_0\ar[r] & M\otimes_\Lambda\Lambda\ar[r] & 0
	}\]
	Restricting this all the homomorphisms and all the modules to $\Gamma$
	in the above diagram we obtain the extension $\me(M\otimes_\Lambda
	\eta)$ in the second row of the following commutative diagram, where
	we use similar arguments as in the proof of
	\cref{lem:commdiagcleft} to construct it. 
	\[\xymatrix@C7pt{
		0\ar[r] & M\otimes_\Lambda\Omega^n_{\Lambda^\evl}(\Lambda)_\Gamma
		\ar[r]\ar[d]_{M\otimes\eta} & 
		M\otimes_\Lambda P_{n-1}\ar[r]\ar[d] & M\otimes_\Lambda P_{n-2}\ar[r]\ar@{=}[d] & \cdots\ar[r] &
		M\otimes_\Lambda P_1\ar[r]\ar@{=}[d] & M\otimes_\Lambda P_0\ar[r]\ar@{=}[d] &
		M\otimes_\Lambda\Lambda_\Gamma\ar[r] \ar@{=}[d] & 0\\ 
		0\ar[r] & M\otimes_\Lambda\Lambda_\Gamma\ar[r] & M\otimes_\Lambda
		E\ar[r] & M\otimes_\Lambda P_{n-2}\ar[r] & \cdots\ar[r] &
		M\otimes_\Lambda P_1\ar[r] &
		M\otimes_\Lambda P_0\ar[r] & M\otimes_\Lambda\Lambda_\Gamma\ar[r] &
		0\\
		0\ar[r] & M\otimes_\Lambda\Lambda_\Gamma\ar[r]\ar@{=}[u] & M\otimes_\Lambda
		E\ar[r]\ar@{=}[u] & M\otimes_\Lambda P_{n-2}\ar[r]\ar@{=}[u] &
		\cdots\ar[r] & M\otimes_\Lambda P_1\ar[r]\ar@{=}[u] &
		E''\ar[r]\ar[u] & M\otimes_\Gamma\Lambda_\Gamma\ar[r]\ar[u]^\varphi &
		0\\
		0\ar[r] & M\otimes_\Lambda\Lambda_\Gamma\ar[r]\ar@{=}[u] & 
		E'\ar[r]\ar[u] & M\otimes_\Gamma P_{n-2}\ar[r]\ar[u]^\varphi & \cdots\ar[r] &
		M\otimes_\Gamma P_1\ar[r]\ar[u]^\varphi &
		M\otimes_\Gamma P_0\ar[r]\ar[u] & M\otimes_\Gamma\Lambda_\Gamma\ar[r]\ar@{=}[u] &
		0\\
		0\ar[r] & M\otimes_\Gamma\Lambda_\Gamma\ar[r]\ar[u]^\varphi & M\otimes_\Gamma
		E\ar[r]\ar[u] & M\otimes_\Gamma P_{n-2}\ar[r]\ar@{=}[u] & \cdots\ar[r]
		& M\otimes_\Lambda P_1\ar[r]\ar@{=}[u] &
		M\otimes_\Gamma P_0\ar[r]\ar@{=}[u] & M\otimes_\Gamma\Lambda_\Gamma\ar[r]\ar@{=}[u] & 0
	}\]
	As said above, the second row is $\me(M\otimes_\Lambda\eta)$, the
	third row is $\Ext^n_\Gamma(\varphi,-)(\me(M\otimes_\Lambda
	\eta)$, the fifth row is $\me(M)\otimes_\Gamma \me^\evl(\eta)$, and
	the fourth row is $\Ext^n_\Gamma(-,\varphi)(\me(M)\otimes_\Gamma
	\me^\evl(\eta))$. The diagram shows that the extension on the third
	row and the extension on the fourth row are equivalent.  In other
	words, the diagram in the proposition is commutative.
\end{proof}



\begin{thm}
	Let $\Lambda=kQ/I$ be an admissible quotient of a path algebra $kQ$,
	and suppose $a$ is an arrow in $Q$ such that $\Gamma = \Lambda/\langle
	\overline{a} \rangle$ is an arrow removal.  Then $\Lambda$ satisfies
	\fg{} if and only if $\Gamma$ satisfies \fg{}.
\end{thm}
\begin{proof}
	We have that 
	\begin{align}
		\me(M)\otimes_\Gamma \me^\evl(\Lambda) & \simeq
		\me(M)\otimes_\Gamma (\Gamma \oplus \langle \overline{a}
		\rangle)\notag\\
		& \simeq \me(M)\otimes_\Gamma \oplus \me(M)\otimes_\Gamma \langle \overline{a}
		\rangle)\notag\\
		& \simeq \me(M) \oplus F(\me(M))\notag
	\end{align}
	Since $F(\me(M))$ is projective, the homomorphism
	$\Ext^*_\Gamma(\varphi,-)$ is an isomorphism for $* > 0$ in the
	commutative diagram in
	\cref{prop:commutativeFGdiagram}. Since $\Lambda$ is Gorenstein if and
	only if $\Gamma$ is Gorenstein, we have that both $\Lambda$ and
	$\Gamma$ are Gorenstein whenever we assume one of them are Gorenstein.
	Hence if we assume that one of $\Lambda$ and $\Gamma$ has \fg{}, then
	$\Gamma$ is Gorenstein.  So we can suppose $\Gamma$ is Gorenstein.
	Then $\langle \overline{a} \rangle$ has finite injective dimension
	over as a right $\Gamma$-module, say $n$.  This implies that the
	homomorphism $\Ext^*_\Gamma(-,\varphi)$ is an isomorphism for $* > n$
	in the commutative in \cref{prop:commutativeFGdiagram}.
	Furthermore, $\Gamma^\evl$ and $\Lambda^\evl$ are both also
	Gorenstein.  Suppose that $\Gamma^\evl$ has Gorenstein dimension $d$.  

	Let $p_\Gamma\colon \me^\evl(\Lambda) \to \Gamma$ be the natural
	projection.  Then construct the following commutative diagram for $* >
	\max\{ n, d\}$.  The upper square is the the commutative square of
	\cref{prop:commutativeFGdiagram}. 
	\[\xymatrix{
		\Ext^*_{\Lambda^\evl}(\Lambda,\Lambda) \ar[rr]^{M\otimes_\Lambda-}
		\ar[d]_{\me^\evl} & & \Ext^*_\Lambda(M,M)\ar[d]^\simeq \\
		\Ext^*_{\Gamma^\evl}(\me^\evl(\Lambda), \me^\evl(\Lambda))
		\ar[rr]^-{\me(M)\otimes_\Gamma-}\ar[d]_{\Ext^*_{\Gamma^\evl}(-, p_\Gamma)} & & \Ext^*_\Gamma(
		\me(M)\otimes_\Gamma\me^\evl(\Lambda), \me(M)\otimes_\Gamma
		\me^\evl(\Lambda)) \ar[d]^{\Ext^*_\Gamma(-,1\otimes p_\Gamma)}\\
		\Ext^*_{\Gamma^\evl}(\me^\evl(\Lambda), \Gamma)
		\ar[rr]^-{\me(M)\otimes_\Gamma-} & & 
		\Ext^*_\Gamma(\me(M)\otimes_\Gamma\me^\evl(\Lambda),
		\me(M)\otimes_\Gamma \Gamma) \\
		\Ext^*_{\Gamma^\evl}(\Gamma, \Gamma)
		\ar[rr]^-{\me(M)\otimes_\Gamma-}\ar[u]^{\Ext^*_\Gamma(p_\Gamma,-)}\ar@{=}[d] & & 
		\Ext^*_\Gamma(\me(M)\otimes_\Gamma\Gamma,
		\me(M)\otimes_\Gamma \Gamma) \ar[u]_{\Ext^*_\Gamma(1\otimes
			p_\Gamma,-)}\ar[d]^\simeq\\
		\Ext^*_{\Gamma^\evl}(\Gamma, \Gamma)
		\ar[rr]^-{\me(M)\otimes_\Gamma-} & &  \Ext^*_\Gamma(\me(M), \me(M))
	}\]
	All the vertical maps in this diagram are isomorphisms and the diagram
	is commutative.  Then using \cite[Proposition 6.4]{PSS} with $N = N' =
	\Gamma/\rad\Gamma$ and $M = M' = \mi(\Gamma/\rad\Gamma)$, where $N$ is
	the direct sum of all simple $\Gamma$-modules and $M$ is the direct
	sum of all simple $\Lambda$-modules, we obtain that $\Lambda$ has
	\fg{} if and only if $\Gamma$ has \fg{}.    
\end{proof}


\subsection{Singular equivalence}

\begin{exam}
	Let $Q^*$ be the quiver be given by 
	\[\xymatrix{
		1 \ar[rr]^\alpha & & 2\ar[dl]^\beta \\
		& 3\ar[lu]^\gamma &
	}\]
	For a field $k$ consider the relations $\rho = \{ \alpha\beta, \beta\gamma,
	\gamma\alpha\}$ in $kQ^*$, and define the algebra $\Gamma =
	kQ^*/\langle \rho \rangle$. 

	Let $Q_n$ be the quiver be given by 
	\[\xymatrix{
		1
		\ar[rr]^{\alpha}\ar@/^0.7pc/[rr]^{\alpha_2}="a2"\ar@/^2pc/[rr]^{\alpha_n}="an"
		& & 2\ar[dl]^\beta \\ 
		& 3\ar[lu]^\gamma & \ar@{..} "a2";"an"
	}\]
	For a field $k$ consider the relations $\rho = \{ \alpha\beta, \beta\gamma,
	\gamma\alpha\}$ in $kQ^*$, and define the algebra $\Lambda_n =
	kQ_n/\langle \rho \rangle$.  Then the algebras $\Gamma$ and
	$\Lambda_n$ are singular equivalent for all $n\geq 2$. 
\end{exam}

