      \draw[->, shorten >= 5pt,bend left]  (6.25,0.2) to node[left]{{\scriptsize $\up_1$}} (7.5,\hgt);
      \draw[->, shorten >= 5pt,bend left]  (6.25,0) to node[right]{{\scriptsize $\down_1$}} (5,-\hgt);

      \draw[->, shorten >= 5pt,bend right] (3.75,-0.2) to node[left]{{\scriptsize $\up_2$}}  (5,-\hgt) ;
      \draw[->, shorten >= 5pt,bend right] (3.75,-0) to node[right]{{\scriptsize $\down_2$}}  (2.5,\hgt) ;

      \draw[->, shorten >= 5pt,bend right] (8.75,-0.2) to node[left]{{\scriptsize $\up_2$}}  (10,-\hgt);
      \draw[->, shorten >= 5pt,bend right] (8.75,-0) to node[right]{{\scriptsize $\down_2$}}  (7.5,\hgt);
  \end{tikzpicture}
  \caption{Mappings among intervals and their extremities. All the solid arrows represent 1- or 2-Lipschitz maps, while the dashed one is 4-Lipschitz.}\label{fig}
\end{figure}



\begin{lemma}\label{lem:coarse homotopy equivalence} The above pairs of maps are
  coarse homotopy inverses to one another. In particular, $\topp_\ast$ and
  $\bott_\ast$ are isomorphisms with inverses $\up_\ast$ and $\down_\ast$
  respectively.
\end{lemma}
\begin{proof}
  Of course, $\up_1\circ \topp_1$ is the identity and $\topp_1\circ \up_1$ is homotopic to the identity by linearly varying the height.
  Explicitly, defining $h\colon \wcone^{I_1}\times[0,1]\to\wcone^{I_1}$ by $h((x,t),s)\coloneqq (x, st + (1-s)2^{2n+1})$ for $2^{2n}\leq t\leq 2^{2n+1}$ yields a coarse homotopy in the sense $(\star)$.

  Defining $H$ on $X\times 2^{[2n,2n+1]}\times \mathbb R$ by
  \[
    H((x,t),s)\coloneqq\left\{ 
      \begin{array}{ll}
        (x, (2^{-2n}s)t + (1-2^{-2n}s)2^{2n+1}) & s\in [0,2^{2n}]\\
        (x, t) & s > 2^{2n}
      \end{array}
    \right.
  \] 
  yields a coarse homotopy in the sense $(\star\star)$. The other cases are analogous.
\end{proof}


Note that the ``shift upwards of the level sets'' map gives a coarse equivalence
\begin{equation*}
  \begin{tikzcd}[column sep = 0pt,row sep = 0pt]
    \shift\colon &[-1em] \wcone^{\expnat}\ar{r} &[2em] \wcone^\expnat;
    \\ 
    & (x,t)\ar[|->]{r} &(x,2t).
  \end{tikzcd}  
\end{equation*}
Writing $2^{\mathbb N+1}=\expodd\sqcup\expeven$ (and ignoring bounded issues at
the tip of the cone which are irrelevant in the coarse category), we observe that $\shift$ swaps $\wcone^\expodd$ with
$\wcone^\expeven$ and that we have $\shift = \up\circ\bott$. In coarse homology,
let
\begin{align*}
  s_{\rm od}\coloneqq (\shift|_{\wcone^\expodd})_\ast\colon
  & HX_\ast(\wcone^\expodd)\to HX_\ast(\wcone^\expeven),
  \\
  s_{\rm ev}\coloneqq (\shift|_{\wcone^\expeven})_\ast\colon
  & HX_\ast(\wcone^\expeven)\to HX_\ast(\wcone^\expodd).
\end{align*}
The following is then immediate.

\begin{lemma}\label{lem:shift in homology} We have:
  \begin{align*}
    s_{\rm od}=& (\topp_2)_\ast^{-1}\circ(\bott_2)_\ast\\
    s_{\rm ev} =& (\topp_1)_\ast^{-1}\circ(\bott_1)_\ast.
  \end{align*}
\end{lemma}
\begin{proof}
 As noted above, $s_{\rm od}\coloneqq (\shift|_{\wcone^\expodd})_\ast = (\up_2\circ\bott_2)_\ast$. We see by \cref{lem:coarse homotopy equivalence} that $(\up_2)_\ast = (\topp_2)_\ast^{-1}$, from which the claim follows. The same applies to $s_{\rm ev}$ as well.
\end{proof}

Let now $\iotaodd\colon\wcone^\expodd\to\wcone^\expnat$ and
$\iotaeven\colon\wcone^\expeven\to\wcone^\expnat$ denote the inclusions.
A first application of Mayer--Vietoris gives the following.

\begin{lemma}\label{lem:M-V on naturals}
In the situation of \cref{thm:LES}, coarse Mayer--Vietoris yields a natural
short exact sequence 
  \[
    \{0\}\to
    HX_\ast(\pt)\xrightarrow{(\iota_\ast,-\iota_\ast)}
    HX_\ast\bigparen{\wcone^\expodd}\oplus HX_\ast\bigparen{\wcone^\expeven}
    \xrightarrow{\hspace{-.5ex}(\iotaodd)_\ast+(\iotaeven)_\ast\hspace{-.5ex}}HX_\ast\bigparen{\wcone^\expnat}
    \to\{0\}.
  \]
\end{lemma}
\begin{proof}
  The inclusions $\wcone^\expodd\hookrightarrow\wcone^{\expodd\cup\{1\}}$ and
  $\wcone^\expeven\hookrightarrow\wcone^{\expeven\cup\{1\}}$ are coarse
  equivalences, hence induce natural isomorphisms in coarse homology. Note that
  $\expnat= (\expodd\cup\{1\})\cup(\expeven\cup\{1\})$ is an excisive pair.
  By \cref{lem:excisive is excisive}, we can apply coarse Mayer--Vietoris to obtain a long exact sequence 
  \[
  \begin{tikzcd}
    \cdots\ar{r} &
    HX_\ast(\wcone^{\{1\}})\ar{r}{(\iota_\ast,-\iota_\ast)} &[2ex]
    HX_\ast\bigparen{\wcone^{\expodd\cup\{1\}}}\oplus HX_\ast\bigparen{\wcone^{\expeven\cup\{1\}}}
    \ar{d}{(\iotaodd)_\ast+(\iotaeven)_\ast}
    & \\
    && HX_\ast(\wcone^{\expnat})\ar{r}{\partial}&\cdots
  \end{tikzcd}
  \]

  Observe that
  $HX_\ast(\wcone^{\{1\}})=HX_\ast(\pt)$, because $\wcone^{\{1\}}$ is
  bounded. Moreover, the projection $\pi\colon \wcone^{\expodd\cup\{1\}}\to\expnat$
  sending $(x,2^{k})\mapsto 2^{k}$ is proper and controlled, hence induces a map in $HX_\ast$.
  The composition of $\iota$ with $\pi$ is the
  inclusion $\{1\}\hookrightarrow\expnat$ which is injective in $HX_*$ by
  hypothesis. Hence the arrow $(\iota_\ast,-\iota_\ast)$ is injective and by exactness
  all the boundary maps in the long exact sequence vanish, which proves the lemma.
\end{proof}

Note that the diagram
\[
\begin{tikzcd}[ampersand replacement=\&, column sep=5em, row sep = 2em]
  HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}
  \ar[->>]{d}[swap]{(\iotaodd)_\ast+(\iotaeven)_\ast}
  \ar{r}{
    \begin{psmallmatrix}
      0 & s_{\rm ev} \\
      s_{\rm od} & 0
    \end{psmallmatrix}
  }
  \&
  HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}
  \ar[->>]{d}{(\iotaodd)_\ast+(\iotaeven)_\ast}.
  \\
  HX_\ast(\wcone^{\expnat})\ar{r}{\shift_\ast}
  \&
  HX_\ast(\wcone^{\expnat})
\end{tikzcd}
\]
commutes. We now have all that it takes to prove \cref{thm:LES}.

\begin{proof}[Proof of \cref{thm:LES}]
  The decomposition $\rpos = I_1\cup I_2$ is excisive, hence we obtain a
  Mayer--Vietoris exact sequence
 \begin{equation} \label{eq:M-V on I1, I2}
    \cdots \to
    HX_\ast(\wcone^\expnat)
    \xrightarrow{({\iota_1}_*,{\iota_2}_*)}
    HX_\ast\bigparen{\wcone^{I_1}}\oplus HX_\ast\bigparen{\wcone^{I_2}}
    \xrightarrow{{j_1}_* -{j_2}_*}
    HX_\ast(\wcone)
    \xrightarrow{\partial}\cdots.
  \end{equation}
  Here we are using the opposite sign convention from the Mayer--Vietoris
  sequence of \cref{lem:M-V on naturals}, as this results in a tidier
  computation.
  We use the natural isomorphism from \cref{lem:coarse homotopy equivalence}
  and the exact sequence from \cref{lem:M-V on naturals} to obtain a
  commutative diagram as follows:
  \begin{equation}\label{cd: expnat to sum via top top}
  \begin{tikzcd}
    HX_\ast(\wcone^\expnat)\ar{r}{({\iota_1}_*,{\iota_2}_*)}\ar[dashed]{dr}{D}
    &
    HX_\ast\bigparen{\wcone^{I_1}}\oplus HX_\ast\bigparen{\wcone^{I_2}} 
    \\ 
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}
    \ar[->>]{u}{(\iotaodd)_\ast+(\iotaeven)_\ast}
    \ar[dashed]{r}{A}
    &
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}.
    \ar{u}[swap]{(\topp_1)_\ast \oplus(\topp_2)_\ast}{\cong}
  \end{tikzcd}
  \end{equation}
  Note that
  \begin{align*}
    \iota_1\circ\iotaodd &= \topp_1 
    &
    \iota_2\circ\iotaodd &= \bott_2
    \\
    \iota_1\circ\iotaeven &= \bott_1
    &
    \iota_2\circ\iotaeven &= \topp_2.
  \end{align*}
  Therefore \cref{lem:shift in homology} shows that the arrow labelled with $A$ is given by
  \[
A=  \left(
    \begin{array}{cc}
      1 & s_{\rm ev} \\
      s_{\rm od} & 1
    \end{array}
  \right) .
  \]

  We now identify the right hand side of the diagram \eqref{cd: expnat to sum via top top}, apply the exact sequence of \cref{lem:M-V on naturals}, and then combine it with the long
  exact sequence \eqref{eq:M-V on I1, I2} to obtain the commutative diagram
  \begin{equation}\label{cd: exactness at first expnat}
  \begin{tikzcd}[row sep=3em]
    HX_{\ast-1}(\wcone)\ar{r}{\partial}
    &[-3em]
    HX_\ast(\wcone^\expnat)\ar{r}{\id+\shift_\ast}\ar{dr}{D}
    &[-.5em]
    HX_\ast(\wcone^\expnat) 
    \\
    &
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}
    \ar[->>]{u}{(\iotaodd)_\ast+(\iotaeven)_\ast}
    \ar{r}{A}   
    &
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}.
    \ar{u}[swap]{(\iotaodd)_\ast+(\iotaeven)_\ast}
    \\
    &
    HX_\ast(\pt)\ar{u}{(\iota_\ast,-\iota_\ast)}
    &
    HX_\ast(\pt)\ar{u}[swap]{(\iota_\ast,-\iota_\ast)}
  \end{tikzcd}
  \end{equation}
  Note that the top line is exact at $HX_\ast(\wcone^\expnat)$ because by
  a diagram chase $\ker(D)=\ker(\id+\shift_\ast)$.  
  Combining \eqref{cd: expnat to sum via top top} with the right part of the
  Mayer--Vietoris exact sequence \eqref{eq:M-V on I1, I2}, we also know that
  \begin{equation}\label{eq: exact right of D}
    HX_\ast(\wcone^\expnat)
    \xrightarrow{D}
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}
    \xrightarrow{\paren{j_1\circ \topp_1}_* -\paren{j_2\circ\topp_2}_*}
    HX_\ast(\wcone)
  \end{equation}
  is exact. 
    Combining the above and the short exact sequence of \cref{lem:M-V on naturals} we obtain the following diagram 
    \[\begin{tikzcd}
  & HX_\ast(\wcone^\expnat) \ar[dashed, shift left=1.5ex]{dr} & [6em] \\
    HX_\ast(\wcone^\expnat)
    \ar{r}{D}
    &
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}\ar[->>]{u}[swap]{(\iotaodd)_\ast+(\iotaeven)_\ast}
    \ar{r}{\paren{j_1\circ \topp_1}_* -\paren{j_2\circ\topp_2}_*}
    &[6em]
    HX_\ast(\wcone)
    \\
    &
     HX_\ast(\pt)\ar{u}[swap]{(\iota_\ast,-\iota_\ast)}
    &
  \end{tikzcd},
  \]
  where the vertical and horizontal sequences are exact.
  The image of $HX_\ast(\pt)$ under the composition of
  $(\iota_\ast,-\iota_\ast)$ and the map on the right hand side of \eqref{eq:
  exact right of D} is $2 \cdot \iota_\ast(HX_\ast(\pt))$. However, we have a
  factorization of $\iota$ as $\{\pt\}\to [1,\infty)\to \wcone$. As
  $HX_*([1,\infty))=0$ by flasqueness, we see that $2\iota_*HX_*(\pt)=0$. It follows that
  $\paren{j_1\circ \topp_1}_* -\paren{j_2\circ\topp_2}_*$ factors 
  through the quotient by $(\iota_\ast,-\iota_\ast)(HX_\ast(\pt))$, as indicated by the dashed arrow in the diagram above. We call the quotient map $\jalt$ and observe that the top row exact sequence of
  \eqref{cd: exactness at first expnat} prolongs to the right of
  $(\id+\shift_\ast)$:
  \begin{equation}\label{eq: diagram prolong exactness to the right}
  \begin{tikzcd}[row sep=3em]
    HX_\ast(\wcone^\expnat)\ar{r}{\id+\shift_\ast}\ar{dr}{D}
    &
    HX_\ast(\wcone^\expnat)\ar{r}{\jalt}
    &[0em]
    HX_\ast(\wcone)\ar{r}{\partial}
    & \cdots
    \\
    &
    HX_\ast\bigparen{\wcone^{\expodd}}\oplus HX_\ast\bigparen{\wcone^{\expeven}}
    \ar[->>]{u}[swap]{(\iotaodd)_\ast+(\iotaeven)_\ast}
    \ar{ur}[swap]{\paren{j_1\circ \topp_1}_* -\paren{j_2\circ\topp_2}_*}
    & &
  \end{tikzcd}
  \end{equation}
  This concludes the proof of \cref{thm:LES}.
\end{proof}




\section{Consequences of \cref{thm:LES}}\label{sec: consequences of LES}
It is well known that both the coarse K-homology and the K\=/theory of Roe
algebras satisfy the three axioms listed in \cref{ssec:coarse homology setup}.
For references, we refer to \cite[Section 8]{BunkeEngel2020HomotopyTheory}, in
particular \cite[Theorems 8.79 and 8.88]{BunkeEngel2020HomotopyTheory}, which
shows that the the K-theory of the Roe algebra is a coarse homology theory in
the sense of \cite{BunkeEngel2020HomotopyTheory}. On the other hand,
\cite[Section 7]{BunkeEngel2020HomotopyTheory}, in particular \cite[Proposition
7.46,Definition 7.66]{BunkeEngel2020HomotopyTheory} implies that all
coarsifications of locally finite homology theories and therefore also coarse
K-homology is a coarse homology theory in the sense of
\cite{BunkeEngel2020HomotopyTheory}. By \cite[Corollary
4.28]{BunkeEngel2020HomotopyTheory} a coarse homology theory in the sense of
\cite{BunkeEngel2020HomotopyTheory} satisfies homotopy invariance and
Mayer--Vietoris (the latter is the long exact sequence of homotopy groups
associated to the cocartesian square of spectra of \cite[Corollary 4.28
4.]{BunkeEngel2020HomotopyTheory}).

We need one further property which is not completely automatic: the
compatibility of the coarse assembly map with the boundary map of the
Mayer--Vietoris sequences. This is commonly used in the literature and proven in
\cite[Section 3]{Siegel} or \cite[Theorem 2.10]{SchickZadeh}.

In the following, which is well known to experts, we verify also the last requirement of \cref{thm:LES}:

\begin{lemma}
  The inclusion $\{1\}\hookrightarrow \expnat$ induces injections
  \[
   KX_\ast(\{1\})\hookrightarrow KX_\ast(\expnat)
   \qquad
   K_\ast(\Croe{\{1\})}\hookrightarrow K_\ast(\Croe{\expnat})
  \]
\end{lemma}
\begin{proof}
  The coarse K-homology of $X$ can be defined as the direct limit of the
  locally finite K-homology groups of the $R$-Rips complexes $P_R(X)$
  as $R$ tends to infinity. Passing to an appropriate cofinal sequence $R_n$,
  the associated Rips complex consists of the simplex spanned by the
    first $n+1$ points together with the disjoint union of the points $2^k$
    with $k>n$. Since we use locally finite  K-homology, $K_\ast(P_{R_n}(X))\cong \prod_{k\geq n} K_\ast(\pt)$ (alternatively, see \cite{WillettYu2020HigherIndex}*{Theorem 6.4.20}).

  For $n<m$, the inclusion $P_{R_{n}}(X)\hookrightarrow P_{R_{m}}(X)$ induces the homomorphism
  \begin{equation*}
    \begin{tikzcd}[column sep = 0pt,row sep = 0pt]
      \varphi_{n,m}\colon &[-.5em] \prod_{k\geq n} K_\ast(\pt) \ar{r} &[2em] \prod_{k\geq m} K_\ast(\pt);
      \\ 
      & (a^{(n)}_k)_{k\geq n}\ar[|->]{r} & (\sum_{k=n}^{m}a^{(n)}_k,\;a^{(n)}_{m+1},\;a^{(n)}_{m+2},\dots).
    \end{tikzcd}  
  \end{equation*}that adds up the components between $n$ and $m$.

  Let $\sigma\colon \bigoplus_{k\in \naturals}K_\ast(\pt)\to
  K_\ast(\pt)$ and $\sigma_n\colon \bigoplus_{k\ge n} K_\ast(\pt)\to
  K_\ast(\pt)$ be the sum homomorphisms. The inclusions (extending by
  zero) then induce isomorphisms
  \begin{equation*}
    \frac{\prod_{k\geq n} K_\ast(\pt)}{\ker(\sigma_n)}
      \xrightarrow{\ \cong\ }
    \frac{\prod_{k\in \naturals} K_\ast(\pt)}{\ker(\sigma)}. 
  \end{equation*}
  These homomorphisms are compatible with the $\varphi_{n,m}$ and hence induce
  a well defined homomorphism
  \begin{equation*}
      KX_\ast(\expnat) 
    \cong \varinjlim_{n\in\mathbb N}\left(\prod_{k\ge n} K_\ast(\pt)\right)
    \longrightarrow  \frac{\prod_{n\in \mathbb N} K_\ast(\pt)}{\ker(\sigma)}.
  \end{equation*}
  This map is surjective, as already the homomorphism for $n=0$ is
  surjective. It is also injective, because every element of $\ker(\sigma)$ is
  mapped to $0$ by some $\varphi_{0m}$. Using the isomorphism $\frac{\bigoplus_{n\in\naturals}
    K_*(\pt)}{\ker(\sigma)} \xrightarrow{\cong} K_*(\pt)$ and the isomorphism
  theorem,  we get the canonical short exact sequence
  \begin{equation}\label{eq:compute_KX}
    0\to K_\ast(\pt)\longrightarrow KX_*(2^\naturals) \longrightarrow \frac{\prod_{n\in\naturals}
      K_*(\pt)}{\bigoplus_{n\in\naturals}K_*(\pt)} \to 0
  \end{equation}
  The homomorphism induced by inclusion $\{1\}\to \expnat$ factorizes---using
  $KX_\ast(\{1\})\cong K_\ast(\pt)$---through the inclusion of $K_\ast(\pt)$
  in \eqref{eq:compute_KX} and is therefore injective.

  The proof for the $K$-theory of the Roe algebra is analogous by using that
  \[
  \Croe{\expnat}\cong \varinjlim_{n\in\mathbb N}\left(\prod_{k\geq n}\Croe{\pt} \right)
  \cong \varinjlim_{n\in\mathbb N}\left(\prod_{k\geq n}\mathcal K \right)
  \]
  and continuity of K\=/theory. Here the description as limit is obtained by observing that the set of locally compact operators of propagation at most $R_n$ is identified with the $C^*$-algebra $\prod_{k\geq n}\Croe{\pt}$, where the first instance of $\Croe{\pt}$ accounts for all the operators supported on $\{2^k\mid k\leq n\}$.
  For $n<m$, the homomorphisms $\varphi_{n,m}$ induced in K-theory by the inclusions $\{\text{prop.}\leq R_n\}\hookrightarrow \{\text{prop.}\leq R_m\}$ are the sum, just as in the K-homology case. The same computation then applies.

  Alternatively, the statement in K-theory can be deduced from the statement on coarse K-homology, because $\expnat$ satisfies the coarse Baum--Connes conjecture.
\end{proof}

We can hence apply \cref{thm:LES} to obtain long exact sequences in this setting. This is done in the next two subsections.


\subsection{Vanishing revisited}
As a first application, we note that \cref{thm:LES} can be used to give yet another proof of the fact that the
(integral) Dru\k{t}u--Nowak projection vanishes in $K$-theory.

Recall that we construct the Roe algebra of $\wcone^\naturals$ using the geometric module $L^2(M)\otimes\ell^2(\naturals)$, which contains one orthogonal copy of $L^2(M)$ for each $n\in \naturals$.
Let $p\in \mathcal B(L^2M)$ be a projection such that
$p\otimes\id_{\ell^2\naturals}\in\Croe{\wcone^\naturals}$.\footnote{ We already
observed that every $p\in\Cfp{\Gamma\curvearrowright M}\cap \mathcal K(L^2M)$
satisfies this condition, but a priori this might be true for other projections
as well. }
It is convenient to write $p\otimes\id_{\ell^2\naturals}$ as the
sequence $(p)_{i\in \naturals} = (p,p,\ldots)$.
With this notation, when the integral Dru\k{t}u--Nowak projection $\mathfrak G^\naturals$ exists, it is given by $(m,m,\ldots)$, where $m\in\mathcal B(L^2M)$ is the projection onto the constant functions.


Given $p$ as above and a sequence of integers $(c_i)_{i\in \naturals}$, we wish to consider the K\=/theory class
$[(c_0p,c_1p,\ldots)]\in K_0(\Croe{\wcone^\naturals})$.
To make sense of this, if the $c_i$'s are all positive one may tensor $L^2(M)\otimes\ell^2(\naturals)$ with another infinite dimensional separable Hilbert space $\mathcal H$ and define $c_i(p\otimes\delta_i)$ as $p\otimes\delta_i\otimes q_i$ where $q_i\in \mathcal B(\mathcal H)$ is a projection of rank $c_i$ (i.e.\ we pass to a ``very ample'' geometric module). The K\=/theory class 
\[
  [(c_0p,c_1p,\ldots)] \coloneqq [(p\otimes\delta_0\otimes q_0\;,\ p\otimes\delta_1\otimes q_1\;,\; \ldots\; )]
  \in K_0(\Croe{\wcone^\naturals})
\]
does not depend on the choices made: had we used $q_i'\in\mathcal B(\mathcal H)$, we could pick unitaries $U_i\in \U(\mathcal H)$ conjugating $q_i'$ to $q_i$, and assemble them into a unitary operator $U$ on $L^2(M)\otimes\ell^2(\naturals)\otimes\mathcal H$ that conjugates $(p\otimes\delta_i\otimes q_i')_{i\in \mathbb N}$ to $(p\otimes\delta_i\otimes q_i)_{i\in \mathbb N}$. Since $U$ has propagation zero, this shows that the two projections define the same element in K-theory.
Note that $[(1\,p,1\,p,\ldots)]$ is naturally identified with $[(p,p,\ldots)]$ by embedding $L^2(M)\otimes\ell^2(\naturals)$ into $L^2(M)\otimes\ell^2(\naturals)\otimes\mathcal H$.

A K\=/theory class $[(c_0p,c_1p,\cdots)]$ with non-positive coefficients is obviously defined taking formal differences.
Identifying $K_0(\Croe{\wcone^\naturals})\cong K_0(\Croe{\wcone})$ via the embedding $\wcone^\naturals\subseteq\wcone$ as at the beginning of \cref{sec: vanishing proof}, we can then make sense of the class $[(c_ip)_{i\in\naturals}]\in K_0(\Croe{\wcone})$.


\begin{remark}
  Using this notation, the class $[\Phi(\mathfrak G^\naturals)]$ appearing in \cref{ssec: swindle} is nothing but $[((n+1)m)_{n\in\naturals}]$.
\end{remark}

We can do the same on the exponentially-spaced warped cone $\wcone^\expnat$: given $p$ as above and an integer sequence $(c_{2^j})_{2^j\in\expnat}$ we obtain a class $[(c_{2^j}p)_{2^j\in\expnat}]\in K_0(\Croe{\wcone^\expnat})$.
Quite plainly, we have:
\begin{equation}\label{eq: shift of K0}
  \shift_\ast([(c_{2^0}p,c_{2^1}p,\cdots)]) = [(0,c_{2^0}p,c_{2^1}p,\cdots)]
   = [(c_{2^{j-1}}p)_{2^j\in 2^{\naturals+1}}].
\end{equation}

\begin{remark}

  One should be careful when using sequences as above to denote K-theory classes: it is generally not clear when a K-theory class can be represented by such a sequence, and when it does, this representation is generally non-unique.

  On the other hand, since we gave an explicit construction for the class
  $[(c_ip)_{i\in\naturals}]$ in terms of (differences of) projections, here it
  is easy to describe its image under homomorphisms induced by functions at
  the level of spaces.

  For instance, \eqref{eq: shift of K0} is justified by observing that the isometry
  \[
    \begin{tikzcd}[column sep = 0pt,row sep = 0pt]
      V\colon &[-.5em] L^2(M)\otimes\ell^2(\expnat)\otimes\mathcal H
       \ar{r} &[2em] L^2(M)\otimes\ell^2(\expnat)\otimes\mathcal H;
      \\ 
      & \xi\otimes \delta_{2^i}\otimes\eta \ar[|->]{r} & \xi\otimes \delta_{2^{i+1}}\otimes\eta.
    \end{tikzcd}  
  \]
 covers the shift map, and hence $\shift_\ast$ is the homomorphism induced in K-theory by the conjugation $t\mapsto VtV^*$. The latter acts as prescribed in \eqref{eq: shift of K0} on the defining projections $(p\otimes\delta_i\otimes q_i)_{i\in \expnat}$.

  Similar arguments will be used again in the sequel. In \cref{lem: concentrate D-N} we also need to construct isometries covering non-injective maps of spaces. This is simply done by arbitrarily embedding $\mathcal H \otimes\ell^2(\naturals)$ into $\mathcal H$ to create enough space for it.
\end{remark}


The following is now easy to prove:

\begin{lemma}
  Any class $x = [(c_{2^0}p,c_{2^1}p,\ldots)]\in K_0(\Croe{\wcone^\expnat})$ as above is in the kernel of
  $\jalt$.
\end{lemma}
\begin{proof}
  Consider the class 
  \[
  y\coloneqq\sum_{n\in\mathbb N}(-1)^n\shift_\ast^{n}(x) = [(c_{2^0}p, (c_{2^1}-c_{2^0})p, (c_{2^2}-c_{2^1}+c_{2^0})p,\ldots )]\in K_0(\wcone^\expnat)
  \]
  (the infinite series is simply intended as a formal sum, and it is seen to make sense because the RHS is well-defined).
  Then $x= (\id+\shift_\ast)(y)$, and therefore
  $\jalt(x)=0$ by exactness.
\end{proof}

From the diagram \eqref{eq: diagram prolong exactness to the right}, we read that $\jalt\colon K_0(\Croe{\wcone^\expnat})\to K_0(\Croe{\wcone})$ maps
\[
[(c_{2^{j}}p)_{2^j\in \expnat}] \longmapsto [((-1)^{j+1}c_{2^{j}}p)_{2^j\in \expnat}],
\]
where it is understood that in the right hand side every element in $\naturals\smallsetminus\expnat$ has coefficient zero.
Here we are being ever so slightly imprecise in that \eqref{eq: diagram prolong exactness to the right} does not directly specify what happens to the coefficient $c_{2^0}$. However, the fact that the quotient map $\jalt$ is well-defined means precisely that this choice does not matter.

Suppose now that $\Gamma\curvearrowright M$ is strongly ergodic, and let
$\mathfrak G^{\mathbb N} = (m)_{i\in \naturals}$ be the integral Dru\k{t}u--Nowak projection.
We note that this is equivalent to a class concentrated on the exponential level sets:

\begin{lemma}\label{lem: concentrate D-N}
  \(
[(m)_{i\in \naturals}] = [(2^jm)_{2^j\in\expnat}].
\)
\end{lemma}
\begin{proof}
  We split up the cone into exponential intervals and consider their coarse disjoint union
  \[
  Y \coloneqq \bigsqcup_{n\in\naturals}\wcone^{[2^n,2^{n+1})}.
  \]
  We define the class
  \[
  [\mathfrak G^\naturals_{\rm split}]\coloneqq [(m),(m,m),(m,m,m,m),\ldots]\in K_0(\Croe{Y})
  \]
  the obvious way, and note that $[\mathfrak G^\naturals]$ is the image of $[\mathfrak G^\naturals_{\rm split}]$ under the map 
  \[f_0\colon Y\to\wcone\]
  that glues the intervals back up (this map is proper and controlled).

  On the other hand, also the mapping $f_1\colon Y\to\wcone$ defined by compressing each interval to their bottom extremity is proper and controlled. Since $f_0$ and $f_1$ are clearly coarse homotopic (cf.\ \cref{lem:coarse homotopy equivalence}), they must induce the same map in K-theory. Then we are done, because $(f_1)_\ast([\mathfrak G^\naturals_{\rm split}])=[(2^jm)_{2^j\in\expnat}]$.
\end{proof}


The following is now clear.

\begin{corollary}\label{cor: vanishing II}
  Let $\Gamma\curvearrowright M$ be strongly ergodic.
  Then $[\mathfrak G^{\mathbb N}]=0$ in $K_0(\Croe{\wcone})$.
\end{corollary}
\begin{proof}
  $[\mathfrak G^{\mathbb N}]= [(2^jm)_{2^j\in\expnat}]$ is the image under ${\jalt}$ of
  \([((-1)^{j+1}2^{j}m)_{2^j\in \expnat}]\).
\end{proof}

\begin{remark}
  Of course, in \cref{cor: vanishing II} there is nothing special about $[\mathfrak G^{\mathbb N}]$, the same proof applies to any class of the form $[(c_ip)_{i\in \naturals}]$.
  It is most likely possible to use \cref{thm:LES} to directly prove that all
  generalized Dru\k{t}u--Nowak projections vanish in K\=/theory. However, this
  would require various technical details to deal with projections of the form
  $m\otimes q$ where $q$ is something more complicated than
  $\id_{\ell^2\naturals}$ (e.g.\ it does not have finite propagation). In this
  case \cref{thm:vanishing} seems to be the most straightforward solution.
\end{remark}






\subsection{Failure of coarse Baum--Connes}
As a second and main application, we provide the announced counterexamples to coarse Baum--Connes in K$_1$.

\begin{proof}[Proof of \cref{thm:cBC_counter}]
By assumption, $\Gamma$ is a group with property A and $\Gamma\curvearrowright M$ a free strongly ergodic action by Lipschitz homeomorphisms.
We then know that the averaging
projection $m\in\mathcal B(L^2M)$ lies in $\Cfp{\Gamma\curvearrowright M}\cap \mathcal
K(L^2(M))$, and hence both $(m,0,m,0,\dots)$ and $(0,m,0,m,\dots)$ belong to $\Croe{\wcone^{2^\naturals}}$.
The alternating Dru\k{t}u--Nowak class
\[
  [\mathfrak G^\expnat_{\rm alt}] \coloneqq [(m,0,m,0,\dots)] - [(0,m,0,m,\dots)]
  = [(m,-m,m,-m,\ldots)]
\]
is then an element in $K_0(\Croe{\wcone^\expnat})$.

The same methods used to prove \cref{thm: old-counterexample}, also prove that
$[\mathfrak G^\expnat_{\rm alt}]$ does not belong to the image of $\mu_c\colon KX_0(\wcone^\expnat)\to K_0(\Croe{\wcone^\expnat})$.
In fact, exactly as in \cref{thm: old-counterexample}, we may consider the two traces
\[
\tau_{\rm d}, \tau_{\rm u}\colon K_0(\Croe{\wcone^\expnat})
\to \frac{\prod_{n\in\mathbb N}\mathbb R}{\bigoplus_{n\in\mathbb N}\mathbb R},
\]
which we know coincide on the image of $\mu_c$ (the existence of $\tau_{\rm u}$ is the only place where we need the property A, Lipschitz and freeness assumptions).
We then observe that 
\[
  \tau_{\rm d}([\mathfrak G^\expnat_{\rm alt}])= [(-1,\;1,-1,\;1,\ldots)]\neq 0,
\]
while $\tau_{\rm u}([\mathfrak G^\expnat_{\rm alt}])=0$ because $[\mathfrak
G^\expnat_{\rm alt}]$ is the difference of two classes represented by ghost projections.

Having established this, we wish to use $[\mathfrak G^\expnat_{\rm alt}]$ to construct an element in 
\begin{equation*}
  \ker\left(\id+\shift_*\colon 
    K_0(\Croe{\wcone^{2^\naturals}})\to 
    K(\Croe{\wcone^{2^\naturals}})\right).
\end{equation*}
Since $(\id+\shift_\ast)([\mathfrak G^\expnat_{\rm alt}])=[(m,0,0,\ldots)]$, this is easy to do:
arbitrarily pick some $x\in M$, and for every $n\in\mathbb N$ pick a rank-1 orthogonal projection $p_n\in \mathcal B(L^2M)$ such that the image of $p_n\otimes\delta_{2^n}$ is supported on the ball of radius $1$ centered at $(x,2^n)$.
This gives two further projections $(p_0,0,,p_2,0,\dots )$ and $(0,p_1,0,p_3,\dots)$ in $\Croe{\wcone^{2^\naturals}}$
and a class
\[
[p_{\rm alt}]\coloneqq [(p_0,0,p_2,0,\dots )] - [(0,p_1,0,p_3,\dots)]
\in K_0(\Croe{\wcone^{2^\naturals}}).
\]
Then $(\id+\shift_\ast)([p_{\rm alt}])=[(p_0,0,0,\ldots)]$, because for every $n\in\mathbb N_{\geq 1}$ the projections $p_{n-1}\otimes\delta_{2^{n}}$ and $p_n\otimes\delta_{2^n}$ are unitarily equivalent via a
unitary of propagation at most $3$.
Now, the image of $[\mathfrak G^\expnat_{\rm alt}]-[p_{\rm alt}]$ under $\id+\shift_*$ is represented by
\begin{equation*}
  [(m-p_0,0,0,\dots)] =0
\end{equation*}
which vanishes, because on the single slice $\wcone^{\{1\}}$ the projections $m$
and $p_0$ are unitarily equivalent via a unitary of finite propagation.


At this point we are done. The class $[p_{\rm alt}]$ is in the image of
$\mu_c$, and hence $[\mathfrak G^\expnat_{\rm alt}]-[p_{\rm alt}]$ is not.
The compatibility of  of the coarse assembly with the boundary maps of
  the Mayer--Vietoris sequences shows that we have a commutative diagram
\[
\begin{tikzcd}
  KX_1(\wcone)\ar[->>]{r}\ar{d}{\mu_c}
  &
  \ker\left(\id+\shift_*\colon 
    K_0(KX_0{\wcone^{2^\naturals}})\to 
    K(KX_0{\wcone^{2^\naturals}})\right)
  \ar{d}{\mu_c}
  \\
  K_1(\Croe{\wcone})\ar[->>]{r}
  &
  \ker\left(\id+\shift_*\colon 
    K_0(\Croe{\wcone^{2^\naturals}})\to 
    K(\Croe{\wcone^{2^\naturals}})\right).
\end{tikzcd}
\]
An immediate diagram chase then proves that any lift of the class $[\mathfrak G^\expnat_{\rm alt}]-[p_{\rm alt}]$ to $K_1(\Croe{\wcone})$ does not belong to the image of 
\[\mu_c \colon KX_1(\wcone) \longrightarrow   K_1(\Croe{\wcone}). \qedhere\]
\end{proof}


\begin{remark}
  Note that in the construction of $[p_{\rm alt}]$ we could have chosen $p_n$ to be supported on the $1$-ball around an arbitrary point $(x_n,2^n)$, and the resulting K\=/theory class would have stayed the same.
  In fact, this class is just the image of a K\=/theory class in $K_0(\Croe{2^n})$ under the embedding $2^\naturals\into
  \wcone^{2^\naturals}$ sending $2^n$ to $(x_n,2^n)$. Since $M$ is compact and connected, it is easily seen that any two such embedding are coarsely homotopic.
\end{remark}



