To define a chord slide operation, we require a site, $i\in \underline{2N}$, to slide, and a direction, up or down, in which to slide.
We thus define:

\mdef\label{admissibility} For a pair partition $P\in B_{\underline{2N}}$, an \textbf{admissible pair} in $P$ is a pair $(i,\epsilon)\in \underline{2N}\times \{\pm 1\}$, such that $i+\e\in \underline{2N}$ and $\{i,i+\e\}\notin P$. \label{def:chordslide} Let $(i,\e)$ be admissible in $P$, and hence let $q=\{i+\e,i'\}\in P$ for $i'\neq i$. Then for any $(P,s)\in \mathcal{TC}_N$, let $\sigma_{(i,\e,P,s)}\in \mathfrak{S}_{2N}$ denote the unique permutation which is order preserving (OP) on $\underline{2N}\smallsetminus\{i\}$, and 
\[\sigma_{(i,\e,P,s)}(i)=\sigma_{(i,\e,P,s)}(i')+\e(-1)^{s(q)},\]
(Note that the map $(-1)^{(\_)} : \Z_2 \to \{\pm 1\}$ is well defined). Explicitly, one has 
\begin{equation}\sigma=\begin{cases} \left(M(q) \ M(q)-1  \dots  i\right), &\begin{matrix} \e=1, \ i+\e =m(q), \text{ and } s(q)=0,\\
\text{or }\e=-1, \ i+\e =m(q), \text{ and } s(q)=1,\end{matrix}\\[1em]
\left( M(q)-1 \ M(q)-2 \ \dots \ i\right), & \begin{matrix}\e=1, \ i+\e =m(q), \text{ and } s(q)=1,\\
\text{or }\e=-1, \ i+\e =m(q), \text{ and } s(q)=0,\end{matrix}\\[1em]
\left( m(q)+1 \ m(q)+2  \ \dots \ i\right), & \begin{matrix}\e=1, \ i+\e =M(q), \text{ and } s(q)=0, \\
\text{or }\e=-1, \ i+\e =M(q), \text{ and } s(q)=1,\end{matrix}\\[1em]
\left( m(q) \ m(q)+1  \ \dots \ i\right), & \begin{matrix}\e=1, \ i+\e =M(q), \text{ and } s(q)=1, \\
\text{or }\e=-1, \ i+\e =M(q), \text{ and } s(q)=0,
\end{matrix} 

\end{cases}\label{perm}\end{equation}
using cycle notation.

For any $(i,\epsilon)\in \underline{2N}\times \{\pm1\}$, define a map $h_{(i,\epsilon)}:\mathcal{TC}_N\to\mathcal{TC}_N$ by
\begin{equation*}
    h_{(i,\epsilon)}(P,s)=\begin{cases}(\sigma(P), s_{(i, \epsilon)}\circ \sigma^{-1}), & (i,\e) \text{ admissible in }P,\\
(P,s), & \text{otherwise},\end{cases}
\end{equation*}
where $\sigma=\sigma_{(i,\e,P,s)} \in \mathfrak{S}_{2N}$ is as per \ref{def:chordslide}, and $s_{(i, \epsilon)}: P\to \Z_2$ is the map
\begin{equation*}
s_{(i, \epsilon)}(p)=\begin{cases}s(p)+s(q), & \text{when } i\in p,\\
s(p), & \text{otherwise}.\end{cases}    
\end{equation*}
For $(i,\pm 1)$ we call the map $h_{(i,\pm 1)}$ the \textbf{chord slide} up (+) or down (-) at position $i$.

\begin{remark} \label{rem:orient} For $(P,s)\in \mathcal{TC}_N$, $(i,\e)$ admissible in $P$, and $q$ as above, observe that if $s(q)=0$, then $s_{(i,\e)}=s$. In particular, if $(P,s)$ is orientable than any $(P',s')\in \mathcal{TC}_N$ satisfying $(P,s)\sim (P',s')$ is necessarily orientable (\textit{c.f.} Prop. \ref{S2eq}).\end{remark}

The following two lemmas describe the interplay between certain permutations and chord slides, which is used to reduce case work in further results. 

\begin{lemma}\label{cyclemma} Suppose that $(P,s)\in \mathcal{TC}_N$ and $\{i+1,i'\}\in P$ for integers $1<i<2N$ and $i'$.
Then $h_{(i,+1)}(P,s)=C_N^{-1} \circ h_{(i-1,+1)}\circ C_N(P,s)$ unless $i'=1$, in which case $h_{(i,+1)}(P,s)=C_N^{-2}\circ h_{(i-1,+1)}\circ C_N (P,s)$. 
\end{lemma}

\begin{proof} Follows by direct verification. \end{proof}

\begin{lemma}\label{fliplemma} For any $N\in \Z_{\geq 0}$, $(i,\e)\in \underline{2N}\times \{\pm 1\}$, we have $h_{(i,\e)}=\omega_N \circ h_{(\omega_N(i),-\e)}\circ\omega_N$, where $\omega_N \in \SS_{2N}$ is as per \ref{perm1}.
\end{lemma}
\begin{proof} Follows by direct verification. \end{proof}

\begin{prop}\label{S2eq}  Define a relation on $\mathcal{TC}_N$ by $(P,s)\sim (P',s')$ if $(P,s)=h (P',s')$, where $h$ is a finite (possibly empty) composite of chord slides. This is an equivalence relation.
\end{prop}
\begin{proof} 
The relation $\sim$ is manifestly reflexive and transitive. To check symmetry, it suffices to check that for any $(P,s)\in \mathcal{TC}_N$ and $(i,\e)$ admissible in $P$, we have $(P,s)\sim h_{(i,\e)} (P,s)$. Writing $h_{(i,\e)}(P,s)=(\sigma(P),s_{(i, \e)}\circ \sigma^{-1})$ as per \ref{def:chordslide}, and $i+\e \in q \in P$, let $\e'$ be given by 
\begin{equation*}
    \e'=\begin{cases} -\e, & s(q)=0, \\ \e, & s(q)=1.\end{cases}
\label{epdash}\end{equation*}
Then we claim that $(P,s)=h_{(\sigma(i),\e')}\left[ h_{(i,\e)}(P,s)\right]$ giving $(P,s)\sim h_{(i,\e)} (P,s)$ as desired.
\end{proof}

Below we define the boundary graph of a TCD, which describes the boundary of the surface formed from a TCD. 

\mdef\label{bdgrp} Given a twisted chord datum $(P,s)\in \mathcal{TC}_N$, define its \textbf{boundary graph} $\del (P,s)$ as the graph with vertex set $\underline{2N}\times\{\pm 1\}$, and edge set given by
\[
    \left\{\begin{array}{ccc}
         (i,+1) \edge (i+1,-1), & |  &\text{for all } i=1,\dots,2N-1,\\
    (i,+1) \edge (j,- 1 ),(i,-1) \edge (j,+ 1 ), & |  & \text{for all untwisted arcs } \{i,j\} \in P,\\
    (i', +1) \edge (j',+ 1 ), (i', -1) \edge (j',-1 ), &| & \text{for all twisted arcs } \{i',j'\} \in P,\end{array}\right\}\,
\]
(recall that $(i, \epsilon_1) \edge (j, \epsilon_2)$ denotes an edge between vertices $(i, \epsilon_1)$ and $ (j, \epsilon_2)$). Order this vertex set by $(i,\e)<(j,\e')$ whenever $2i+\e/2<2j+\e'/2$; if we place $(i,\pm)$ just above (+) and below (-) the vertex $i$ in a twisted chord diagram, then this order is compatible with the diagrammatic ``bottom to top" order and the graph $\del(P,s)$ can be drawn as a collection of 2 dimensional 1-handles attached to a line as per Figure \ref{fig:boundary_graph}. It will also be convenient to define $\overline{\del(P,s)}:=\del(P,s)\cup \left[ (0,+1)\edge (1,-1)\right]\cup \left[(2N,+1)\edge (2N+1,-1)\right]$, with the previous order extended to this vertex set by the same formula. 

