\begin{prop}\label{Prop:bondarycomponentspreserved} For any $(P,s)\in \mathcal{TC}_N$, $\del(P,s)$ contains a path between $(1,-1)$ and $(2N,+1)$. Furthermore, if $(P,s)\sim (P',s')$, then $|\CC(\del(P,S))|=|\CC(\del(P',S'))|$.

\end{prop}
\begin{proof}
    Existence of the path between $(1,-1)$ and $(2N,+1)$ follows immediately from Lemma \ref{grlemma} since these are the only two vertices with valence 1. For the second part, it suffices to treat the case $(P',s')=h_{(i,\e)}(P,s)$ for $(i,\e)$ admissible in $P$. Using Lemmata \ref{cyclemma} and \ref{fliplemma}, we can further reduce to the case $(i,\e)=(1,+1)$ since $(i,\e)\mapsto (\omega_N(i),-\e)$ is a graph isomorphism $\del(P,s)\overset{\sim}{\to} \del((P,s)^*)$, and $(i,\e)\mapsto (C_N(i),\e)$ is a graph isomorphism 
    \begin{equation*}
    (\del(P,s)\cup e)\overset{\sim}{\to} (\del(C_N(P,s))\cup e), \quad \text{for} \quad e=(1,-1)\edge (2N,+1),
    \end{equation*}
    and it follows from the first claim that $|\CC(\del(P,s)\cup e)|=|\CC(\del(P,s))|$. This case can be directly verified.\end{proof}

Below we define the notions of vertical juxtaposition and insertion of TCD, which are useful notions of decomposition for TCD (\textit{c.f.} Theorem \ref{rform}). 

\mdef\label{vjuxt} For two pair-partitions $P_i\in B_{\underline{2N_i}}$ ($i=1,2$), define their \textbf{vertical juxtaposition} $P_2\# P_1\in B_{\underline{2(N_1+N_2)}}$ by $P_2\# P_1=P_1\cup (P_2+2N_1)$\footnote{We regard $(\_)+N$ as a function $\Z\to \Z$ so that $P_2+2N_1=\{\{i+2N_1,i'+2N_1\} \ | \ \{i,i'\}\in P_2\}$ in accordance with \ref{notn}.}. For two twisted chord data $(P_i,s_i)\in \mathcal{TC}_{N_i}$ ($i=1,2$), define their vertical juxtaposition by $(P_2,s_2)\# (P_1,s_1)=(P_2\#P_1,s_2\#s_1)\in \mathcal{TC}_{N_1+N_2}$, where $s_2\#s_1$ is uniquely defined by $s_2\#s_1 (p)=s_1(p)$ and $s_2\# s_1 (q+2N_1) =s_2(q)$ for $p\in P_1, q\in P_2$. 

\mdef\label{ins} Define the \textbf{insertion} of $P_1$ in $P_2$ at height $d =0,\dots, 2N_2$, as the pair partition 

\begin{equation*}
P_{2} \#_d P_1:= (P_1+d) \cup o_d(P_2),
\end{equation*}
where $o_d:\underline{2N_2}\to \underline{2(N_1+N_2)}\smallsetminus(\underline{2N_1}+d)$ is the unique OP map. For twisted chord data, define their insertion $(P_2,s_2)\#_d (P_1,s_1):=(P_2\#_d P_1,s_2\#_d s_1)\in \mathcal{TC}_{N_1+N_2}$, where $s_2\#_d s_1$ is uniquely defined by $s_2\#_d s_1 (p+d)=s_1(p)$ and $s_2\#_d s_1 (o_d(q)) =s_2(q)$ for $p\in P_1, q\in P_2$. In particular, observe that $(P_2,s_2)\#_0 (P_1,s_1)=(P_2,s_2)\# (P_1,s_1)$ and $(P_2,s_2)\#_{2N_2} (P_1,s_1)=(P_1,s_1)\# (P_2,s_2)$.

