We define these notions, in more generality below:

\mdef\label{def:evac}  For $(P,s)\in \mathcal{TC}_N$, and non-negative integers $d_1 \leq d_2<2N$, and $d_1' \leq d_2'<2N$, define two sequences of chord slides $\mathit{ev}^{+}_{[d_1,d_2]}$ and $\mathit{ev}^{-}_{[d_1',d_2']}$ iteratively as follows: $\mathit{ev}_{[d_2,d_2]}^{+}=h_{(d_2,+1)}$, $\mathit{ev}_{[d_1',d_1']}^{-}=h_{(d_1',-1)}$, and for $d_1<d\leq d_2$ and $d_1'\leq d' <d_2'$
\begin{align*} \mathit{ev}^{+}_{[d-1,d_2]}&:= h_{(\tau^{+}_d(d-1),+1)}\circ \mathit{ev}^{+}_{[d,d_2]},\\
\mathit{ev}^{-}_{[d_1',d'+1]}&:= h_{(\tau^{-}_{d'}(d'+1),-1)}\circ \mathit{ev}^{-}_{[d_1',d']},
\end{align*}
where $\tau^{+}_d, \tau^{-}_{d'}\in \mathfrak{S}_{2N}$ are the permutations determined by $\mathit{ev}^{+}_{[d,d_2]}(P,s)=(\tau^+_d(P),(s^+_d)\circ(\tau^+_d)^{-1} )$ and  $\mathit{ev}^{-}_{[d_1',d']}(P,s)=(\tau^-_{d'}(P),(s^-_{d'})\circ(\tau^-_{d'})^{-1} )$, respectively. We refer to $\mathit{ev}^{+}_{[d_1,d_2]}$ (and $\mathit{ev}^{-}_{[d_1',d_2']}$) as the \textbf{upward} (and \textbf{downward}) \textbf{evacuation} of sites $d_1$ to $d_2$ (and $d_1'$ to $d_2'$) in $(P,s)$, respectively. Observe that 
\begin{equation*}
\mathit{ev}^{-}_{[d_1',d_2']}=\omega_N\circ \left(\mathit{ev}^{+}_{[\omega_N(d_2'),\omega_N(d_1')]}\right)_{(P,s)^*} \circ\omega_N,
\end{equation*}
using the subscript to indicate that the upward slide is in the chord datum $(P,s)^*\in \mathcal{TC}_N$.

\mdef\label{def:slideover} Let $(P_1,s_1)\in \mathcal{TC}_{N_1} $, $(P_2,s_2)\in \mathcal{TC}_{N_2},$ and suppose that $0< d\leq 2N_2$ and $0\leq  d'< 2N_2$ are non-negative integers. Let $\Gamma\subset \del (P_1,s_1)$ be the unique component containing vertices $(2N_1,+1)$ and $(1,-1)$. Then $\Gamma$ is a line which has the form
\[(1,-1) \edge (i_{1},\e_1) \edge (i_{1}-\e_1,-\e_1) \edge (i_{2},\e_2) \edge (i_{2}-\e_2,-\e_2) \edge \dots \]
\[\dots  \edge (i_{k},\e_k) \edge (i_{k}-\e_k,-\e_k) \edge (2N_1,+1),    \]
for $\e_j \in \{\pm 1\}$, $i_j\in \underline{2N_1}$. Define $\mathit{bs}^{+}_{(d,(P_1,s_1))}, \mathit{bs}^{-}_{(d',(P_1,s_1))}:\mathcal{TC}_{N_1+N_2}\to \mathcal{TC}_{N_1+N_2}$ to be the following sequences of handle slides:
\begin{align*}
\mathit{bs}^{+}_{(d,(P_1,s_1))}&:=  h_{(d+i_k+\delta_k,\epsilon_k)} \circ \dots  \circ h_{(d+i_2+\delta_2,\epsilon_2)} \circ h_{(d+i_1+\delta_1,\epsilon_1)}\circ h_{(d,+1)},\\
\mathit{bs}^{-}_{(d',(P_1,s_1))}&:=  h_{(d'+i_{1}+\delta_1,-\epsilon_1)}\circ\dots  \circ h_{(d'+i_{k-1}+\delta_{k-1},-\epsilon_{k-1})}\circ h_{(d'+i_k+\delta_k,-\epsilon_k)}\circ h_{(d'+2N_1+1,-1)},
\end{align*}
where $\delta_i=(\epsilon_i+1)/2$. We refer to $\mathit{bs}^+_{(d,(P_1,s_1))}$ (and $\mathit{bs}^-_{(d',(P_1,s_1))}$) as the \textbf{upward} (and \textbf{downward}) \textbf{boundary slide} of site $d$ (and $d'+1$) over $(P_1,s_1)$. Observe that
\begin{equation*}
\mathit{bs}^{-}_{(d',(P_1,s_1))}=\omega_N\circ \mathit{bs}^+_{\left(2N_2-d',(P_1,s_1)^*\right)}\circ \omega_N.
\end{equation*}

\begin{lemma}\label{moveslem} Let $(P_1,s_1)\in \mathcal{TC}_{N_1} $, $(P_2,s_2)\in \mathcal{TC}_{N_2}$, and let $d<2N_1$ be a non-negative integer. Let $p=\{d+1,i\}\in P_2$ be the unique part containing $d+1$. The following hold:
\begin{enumerate}
    \item If $s(p)=0$, then $\mathit{ev}^+_{[d+1,d+2N_1]}\left((P_2,s_2)\#_d (P_1,s_1)\right)= (P_2,s_2)\#_{i} (P_1,s_1)$.
    \item If $s(p)=1$, then $\mathit{ev}^+_{[d+1,d+2N_1]}\left((P_2,s_2)\#_d (P_1,s_1)\right)= (P_2,s_2)\#_{i-1} (P_1,s_1)^*$.
    \item $\mathit{bs}^-_{(d,(P_1,s_1))}\left((P_2,s_2)\#_d (P_1,s_1)\right)= (P_2,s_2)\#_{d+1} (P_1,s_1)$.
\end{enumerate}
\end{lemma}
\begin{proof}
    Omitted.
\end{proof}
