\begin{lemma}
\label{grp1} Let $\Th$ and $\Th'$ be two SWB-datum. If $\Th$ and $\Th'$ have the same frame, then $\Th= \Th'$, if and only if, $G(\Th)=G(\Th')$. 
\end{lemma}
\begin{proof} Clearly $\Th= \Th'$ implies $G(\Th)=G(\Th')$. Now write, $\Th=(F,E)$, $\Th'=(F,E')$ and suppose $G(\Th)=G(\Th')$. If $e \in E\smallsetminus E'$ then $e\in D_F$ (otherwise $E(G(\Th))\neq E(G(\Th'))$), but then a vertex in $e$ has valence $2$ in $G(\Th)$ and valence $1$ in $G(\Th')$, a contradiction. Thus $E\smallsetminus E'=\emptyset$, and by symmetry $E=E'$. \end{proof}

\begin{remark} Note that we can relax the last part of the above to $G(\Th)\simeq_O G(\Th')$ (\textit{c.f.} \ref{OG}), since having the same frame guarantees both graphs have the same vertex set. We will use this fact frequently.\end{remark}

\mdef\label{twist} Given a SWB $\Th=(F,E)$, and a component $\Gamma\in \mathcal{C}(G(\Th))$, define the \textbf{twist} of $\Gamma$, $\tau_\Gamma\in \Z_2$, by the formula
\[\tau_{\Gamma}= \sum_{p \in P} \left|(D_F)_p\cap E(\Gamma)\right|s(p).\]
The twist of a component then, is simply the $\Z_2$-count of the number of twisted bands the corresponding curve passes through. Geometrically then, the twist of a component is 1 if the corresponding curve is $1$-sided, and 0 if it is $2$-sided. 

\begin{example}\label{TWex} From \ref{SWBex}, the red components in the diagrams for $\Th_1$ and $\Th_2'$ have twist 1. From \ref{CPTex}, the red component in $\Th_4$ has twist 1, whereas the blue components has twist 0. 

\end{example}
\mdef\label{cptfn} Given a SWB $\Th=(F,E)$, $F=(P,s,f)$, and a component $\Gamma \in \mathcal{C}(G(\Th))$, define $g_{\Gamma}:\overline{P}\to \Z$ by 
\[g_{\Gamma}(p)=\left|(V_F)_p\cap V(\Gamma)\right|.\]

In the following proposition, we establish how to ``delete curves" from SWB-data:

\begin{prop}\label{del} Let $\Th=(F,E)\in Sq_N(n,m)$, and let $\Gamma\in \mathcal{C}(G(\Th))$. There exists a unique SWB datum $\Th\smallsetminus \Gamma$ with frame $F_{-\Gamma}=(P,s,f-g_{\Gamma})$, such that $G(\Th\smallsetminus \Gamma)\simeq_{O} G(\Th)\smallsetminus \Gamma$.
\end{prop}
\begin{proof} Since $|V_F\smallsetminus V(\Gamma)|=|V_{F_{-\Gamma}}|$ by construction, we may set $o :V_F\smallsetminus V(\Gamma) \to V_{F_{-\Gamma}}$ as the unique OP map. Then $\Th':=(F_{- \Gamma}, o(E\smallsetminus E(\Gamma)  ) )$ is a SWB-datum and 
\[G(\Th')=(V_{F_{-\Gamma}}, o(E\smallsetminus E(\Gamma))\cup D_{F_{-\Gamma}} ).\]
Since $|(V_F)_i \smallsetminus V(\Gamma)|=|(V_{F_{-\Gamma}})_i|$ for all $i=0,\dots, 2N+1$, one has that $o((V_F)_i \smallsetminus V(\Gamma))=(V_{F_{-\Gamma}})_i$. 
One can futher check that for any $v\in (V_F)_\int \smallsetminus V(\Gamma)$, we have $o \circ \iota_F(v)=\iota_{F_{-\Gamma}}\circ o(v)$, from which it follows that $D_{F_{-\Gamma}}=o(D_F)$, and hence $G(\Th')=o(G(\Th)\smallsetminus \Gamma )$. Thus we may take $\Th\smallsetminus\Gamma =\Th'$. Uniqueness is guaranteed by \ref{grp1}.
\end{proof}

Henceforth, let $o_{\Gamma} :V_F\smallsetminus V(\Gamma) \to V_{F_{-\Gamma}}$ denote the unique OP map. Thus in particular $G(\Th\smallsetminus \Gamma)= o_{\Gamma}(G(\Th)\smallsetminus \Gamma)$. 



\begin{prop}\label{delp} Let $\Th=(F,E)$ be a SWB and let $\Gamma\in \mathcal{C}(G(\Th))$. The following hold:
\begin{enumerate}
\item\label{delp1} For $\Gamma \neq \Lambda\in \mathcal{C}(\Th)$, set $\Gamma':=o_{\Lambda}(\Gamma)\in \mathcal{C}(G(\Th\smallsetminus \Lambda))$ and $\Lambda'=o_{\Gamma}(\Lambda)\in \mathcal{C}(G(\Th\smallsetminus \Gamma))$. Then $\tau_{\Gamma'}=\tau_{\Gamma}$, $\Gamma$ is internal if and only if $\Gamma'$ is, and
\[(\Th\smallsetminus \Gamma)\smallsetminus \Lambda'=(\Th\smallsetminus \Lambda)\smallsetminus \Gamma'.\] 
\item\label{delp2} $G(\Th^*)\simeq_O G(\Th)^*$. Furthermore, set $\Gamma^*=\omega_F(\Gamma)\in \mathcal{C}(G(\Th^*))$. Then $\tau_{\Gamma^*}=\tau_{\Gamma}$, $\Gamma^*$ is internal if and only if $\Gamma$ is, and 
\[(\Th\smallsetminus \Gamma)^*=\Th^*\smallsetminus \Gamma^*.\]
\end{enumerate}
\end{prop}
\begin{proof} For (1), since $\iota_{F_{-\Lambda}}\circ o_{\Lambda}=o_{\Lambda }\circ \iota_F$ (where defined), and since $o_{\Lambda}((V_F)_p \smallsetminus V(\Lambda))=(V_{F_{-\Lambda}})_p$ for any $p\in P$, $o_{\Lambda}$ induces a bijection $o_{\Lambda}:E(\Gamma) \cap D_F \to E(\Gamma') \cap D_{F_{-\Lambda}}$ which restricts to bijections $E(\Gamma) \cap (D_F)_p \to E(\Gamma') \cap (D_{F_{-\Lambda}})_p$. It therefore follows that $\tau_{\Gamma'}=\tau_{\Gamma}$. The second claim is clear since $o_{\Lambda}$ restricts to a bijection $(V_F)_{\int}\smallsetminus V(\Lambda) \overset{\sim}{\to} (V_{F_{-\Lambda}})_{\int}$. The third claim follows by \ref{grp1} since $g_{\Gamma'}=g_{\Gamma}$ (and likewise for $\Lambda$) and since (using \ref{contpr})
\[G\left( (\Th\smallsetminus \Gamma)\smallsetminus \Lambda'\right)\simeq_{O}G(\Th) \smallsetminus(\Gamma\cup \Lambda )\simeq_{O}G\left( (\Th\smallsetminus \Lambda)\smallsetminus \Gamma'\right).\]
For (2), one can check using the formula in \ref{flip} that $\omega_{F}\circ \iota_F =\iota_{F^*} \circ \omega_{F}$, from which it follows that $\omega_F(D_F)=D_{F^*}$ and hence $G(\Th^*)=\omega_F(G(\Th))$. Clearly, $\omega_F$ descends to a bijection $(V_F)_\int\overset{\sim}{\to} (V_{F^*})_\int$, which proves the second claim about $\Gamma^*$. For the first we note that $\omega_{F}$ induces a bijection $E(\Gamma)\cap D_F\overset{\sim}{\to} E(\Gamma^*)\cap D_{F^*}$ which descends to bijections $E(\Gamma)\cap (D_F)_p\overset{\sim}{\to} E(\Gamma^*)\cap (D_{F^*})_{\omega_N(p)}$ for all $p\in P$. The last claim follows by \ref{grp1}, since $g_{\Gamma^*}=g_{\Gamma}\circ \omega_{N}'$, and (using \ref{contpr})
\[G((\Th\smallsetminus \Gamma)^*)\simeq_O (G(\Th)\smallsetminus \Gamma)^*=G(\Th)^*\smallsetminus \Gamma^*\simeq G(\Th^*\smallsetminus \Gamma^*).\qedhere\]
\end{proof}

Just as we can describe the curves in a SWB-diagram via the curve graph $G(\Th)$, so too we can describe the complement of these curves with a graph as follows:

\mdef\label{SWBcomp} Given a SWB $\Th=(F,E)$, define the \textbf{complement graph} $\mathcal{G}(\Th)$ to be the graph with vertex set $\V_F$, and edge set $\mathcal{D}_F\cup \mathcal{E}$ where
\begin{align*}\mathcal{D}_F&=\{ v\edge \iota_F(v) \ : \ v \in (\V_F)_{\int} \}, \\
\mathcal{E}&=\{ u\edge v \ : \ u,v \in \V_F, \ \{u,v\} \text{ crosses no part in } E  \}.
\end{align*}
Here we regard $\prec$ as defining a total order on $V_F\cup \V_F$ (\textit{c.f.} \ref{vset}).

\begin{example} Below we illustrate the complement graph on the SWB diagram for $\Th_1$ (\textit{c.f.} \ref{SWBex}). The vertices in $\V_F$ (drawn as black circles) correspond to regions between the vertices in $V_F$, and the edges (drawn as dashed curves) are all possible pairings of the vertices which do not cross curves in the SWB-diagram. Thus one sees that components of $\G(\Th)$ correspond to components of the complement of the curves in a given SWB diagram, for example $|\CC(\G(\Th_1))|=1$.
    \[\CPTone{0.6}\]
Furthermore, observe that components of the subgraph $(\V_F, \mathcal{E})$ correspond to the connected components of the complement of the curves inside the square, now ignoring the bands.
\end{example}

\begin{prop}\label{comp1} Let $\Th=(F,E)$ be a SWB datum. Then $|\mathcal{C}(\mathcal{G}(\Th))|\leq |\mathcal{C}(G(\Th))|+1$.
\end{prop}
\begin{proof} For $v=(i,a)\in V_F$, let $v^{\pm}$ denote the vertex $(i,a\pm 1/2)\in \V_F$. For a path $v_1\edge v_2\edge \dots\edge v_k\subset G(\Th)$, one has that $v_1^{\pm}\edge v_2^{\pm}\edge \dots\edge v_k^{\pm}\subset \G(\Th)$, where the signs at each step are determined as follows: For $u\edge v\in E $ we have $u^{\pm}\edge v^{\mp}\in \mathcal{E}$, and for $u\edge v \in (D_F)_p$ we have $u^{\pm}\edge v^{\mp} \in \mathcal{D}_F$ if $s (p)=0$, and $u^{\pm}\edge v^{\pm}\in \mathcal{D}_F$ for $s (p)=1$. 

Now let $\mathcal{H}\subset \G(\Th)$ be a connected component, and set $\bm{v}:=\min_{\prec}V(\mathcal{H})$. We now claim that either $\bm{v}=v^+$ where $v=\min_{\prec}(V(\Gamma))$ for some connected component $\Gamma \subset G(\Th)$, or $\bm{v}=(0,1/2)$. If $\bm{v}\neq (0,1/2)$ then $\bm{v}=v^+$ for some $v\in V_F$, as otherwise, $\bm{v}=(i,1/2)$ for $i>0$ implies $(i,1/2)-\max_{\prec}((V_F)_{i-1} )^+$ contradicting minimality. Let $\Gamma \in \CC(G(\Th))$ be such that $v\in V(\Gamma)$, and suppose that $v\neq v':= \min_{\prec}V(\Gamma)$. By the previous paragraph, there exists a path between $\bm{v}=v^+$ and $(v')^\pm$ in $\mathcal{H}$ which contradicts minimality of $\bm{v}$. Thus we have proven the claim, and it follows that $\G(\Th)$ may be written as a union of components
\[\G(\Th)=\G_{(0,1/2)}\cup \left(\cup_{\Gamma \in \mathcal{C}(G(\Th)) }\G_{ \min_{\prec}(V(\Gamma))^{+} }\right),\]
where $\G_{\bm{v}}$ denotes the unique component of $\G(\Th)$ containing the vertex $\bm{v}$. Since this union is in general not disjoint, we obtain the desired bound on $|\CC(\G(\Th))|$.\end{proof}


\mdef Given a SWB $\Th=(F,E)$ and a component $\Gamma\in \CC(G(\Th))$, let $\Th_{\Gamma}=(F_\Gamma,E_\Gamma)$ be the SWB obtained from $\Th$ by deleting all components except $\Gamma$ (this is well defined by \ref{delp} part \ref{delp1}). We say that $\Gamma$ is \textbf{separating} (in $\Th$) if $\G (\Th_{\Gamma})$ has two components, and \textbf{non-separating} if it has one.

\begin{prop}\label{comp2} Let $\Th=(F,E)$ be a SWB and let $\Gamma\in \mathcal{C}(G(\Th))$. The following hold:
\begin{enumerate}
\item\label{comp21} If $\tau_\Gamma=1$, then $\Gamma$ is non-separating.

\item\label{comp22} $\G(\Th^*)\simeq_O \G(\Th)^*$. In particular, $\Gamma$ is separating in $\Th$  if and only if $\omega_F(\Gamma)$ is separating in $\Th^*$.

\item\label{comp23} For $\Gamma \neq \Lambda\in \mathcal{C}(\Th)$, $\omega_\Lambda(\Gamma)$ is separating in $\Th\smallsetminus \Lambda$, if and only if, $\Gamma$ is separating in $\Th$. 
\end{enumerate}
\end{prop}
\begin{proof} For (1), set $\mathcal{G}=\mathcal{G}(\Th_{\Gamma})$. From the proof of \ref{comp1}, it is enough to prove that $(0,1/2)\sim_{\G} v^+$, where $v=\min V_{F_\Gamma}$. If $\Gamma$ is external with $v$ southern and $w=\max V_{F_\Gamma}$ northern, it follows that $\G$ contains a path between $v^+$ and $w^{+}=\max (\V_{F_{\Gamma}})$, since $\Gamma$ consists of odd number of arcs coming from twisted bands and an even number of other arcs, and thus $(0,1/2)\sim_{\G} w^+ \sim_{\G} v^+$. If $\Gamma$ is internal with two southern vertices as end points, say $v(=\min V_{F_\Gamma})$ and $u$, then by a similar argument $(0,1/2)=v^-\sim_{G} u^-=v^+$. If $\Gamma$ is internal then $\G$ contains a path between $v^-$ and $v^+$, since $\Gamma$ now consists of an odd number of arcs through twisted bands and an odd number of other arcs, thus $(0,1/2)\sim_\G v^- \sim_\G v^+$.   


For part (2), we observe that the identity $\omega_{F}\circ \iota_F =\iota_{F^*} \circ \omega_{F}$, used in the proof of \ref{delp}, remains true when both sides are regarded as maps $(\V_F)_\int\to (\V_{F^*})_\int$. Thus we have $\mathcal{D}_{F^*}=\omega_F(\mathcal{D}_F)$. Using $\omega_{F^*}\circ \omega_F=\text{id}$ one sees that 
\[\omega_F(\mathcal{E})=\{u\edge v \ : \ u,v\in \V_{F^*}, \{u,v\} \text{ crosses no part in } \omega_F(E)\}.\]
Hence $\G(\Th^*)=\omega_F(\G(\Th))$.  Part (3) is immediate.
\end{proof}

\begin{lemma}
    [Insertion Lemma]\label{insSWB} Let $\Th=(F,E)$ be a SWB with $F=(P,s,f)$, and suppose $(P,s)=(P_2,s_2)\#_{d}(P_1,s_1)$, where $(P_i,s_i)\in \mathcal{TC}_{N_i}$, and $1\leq d\leq 2N_2$. Then there exist unique frames $F_1=(P_1,s_1,f_1)$ and $F_2=(P_2,s_2,f_2)$, and a SWB, without fully external components, $\Th_1=(F_1,E_1)$, together with an OP map $o:V_{F_1}\to V_F$, obeying $o(i,a)=(i+d,a)$ for all $(i,a)\in (V_{F_1})_I$, such that 
\[\Th=(F_2\#_N F_1, o(E_1)\sqcup \left(E\smallsetminus o(E_1) \right) ).\]
\end{lemma}
\begin{proof} Let $U:=\cup_{i=0}^{d-1} (V_F)_{i},  V:=\cup_{p\in P_1} (V_F)_{p+d}, W:=V_F\smallsetminus (U\cup V)$, and define vertices $u_i$ and $w_i$, by
\begin{align*}
\{u_1\prec u_2\prec \dots \prec u_n\}&:=\{u \in U \ : \ \text{there exists } v\in V \text{ with } u-v \in E \},  \\
\{w_1\succ w_2 \succ \dots\succ w_m\}&:=\{w \in W \ : \ \text{there exists } v \in V \text{ with } w-v \in E  \}. 
\end{align*}  
Now let $v_i$ ($v^j$) be the unique vertex in $V$ such that $u_i\edge v_i\in E$ $(w_j-v^j\in E)$, respectively. Define $f_1:\overline{P_1}\to \N$ by $f_1(\{0\})=n, f_1(\{2N_1+1\})=m$ and $f_1(p)=f(p+d)$ for $p\in P_1$, define $f_2:\overline{P_2}\to \N$ by $f_2=f\circ o_d$ (using \ref{ins}), and set $F_i=(P_i,s_i,f_i)$ for $i=1,2$. Let $\tilde{o}: V \to (V_{F_1})_\int$ be the unique OP map, and define
\[E_1=\tilde{o}\left(\{e \in E \ : \ e\subset V\}\right)\cup \{(0,i)\edge \tilde{o}(v_i) \ : \ 1\leq i \leq n\} \cup \{(2 N_1+1,j)\edge \tilde{o}(v^j) \ : \ 1\leq j \leq m\}.  \]  
Then by construction $(F_1,E_1)\in Sq_{N_1}(n,m)$, and is without fully external components. Define an OP map $o':V_{F_1}\to V_{F}$ by
\[o'(v)= \begin{cases}(\tilde{o})^{-1}(v), &v \text{ is internal}, \\
u_i, &v=(0,i) \in (V_{F_1})_\sth, \\
w_j, &v=(2N_1+1,j) \in (V_{F_1})_\nth.\end{cases}\]
By construction, $o'(E_1)\subset E$ and so the result follows taking $o=o'$.\end{proof}

