\subsection{Vertical Juxtaposition} In this subsection we define the vertical juxtaposition of SWB data $(\_) \# (\_) : Sq(m,l)\times Sq(n,m) \to Sq(n,l)$, which will be used in \S4 to define a categorical composition. After defining this operation, we establish some of its key properties in Prop \ref{vjassoc}, and prove the Factorisation Lemma for SWB in Lemma \ref{vjfact}. 

\mdef\label{vjvset} Given SWB data $\Th_1=(F_1,E_1)\in Sq_{N_1}(n,m)$ and $\Th_2=(F_2,E_2)\in Sq_{N_2}(m,l)$, define a set $V_{F_1,F_2}$ as 
\[V_{F_1,F_2}=V_{F_1}\sqcup V_{F_2}/(V_{F_1}\ni (2N_1+1,a) \sim (0,a) \in V_{F_2} \text{ for } a=1,\dots, m).\]
Let $(\_)^{(i)}:V_{F_i}\to V_{F_1,F_2}$ denote the canonical inclusion maps, so that in particular, $(2N_1+1,a)^{(1)}=(0,a)^{(2)}$ for all $a=1,\dots, m$. Let $U_{F_1,F_2}\subset V_{F_1,F_2}$ be the subset $(V_{F_1})_{\nth}^{(1)}=(V_{F_2})_{\sth}^{(2)}$, and let $W_{F_1,F_2}=V_{F_1,F_2}\smallsetminus U_{F_1,F_2}$. Define a total order on $W_{F_1,F_2}$ by $v^{(i)}\prec u^{(j)}$ if $i<j$, or if $i=j$ and $v\prec u$ in $V_{F_i}$. Noting that $|W_{F_1,F_2}|=|V_{F_2\#F_1}|$ (\textit{c.f.} \ref{frame}), let $o_{F_1,F_2}:W_{F_1,F_2}\to V_{F_2\#F_1}$ denote the unique OP map. 

Define the \textbf{composite graph} of the pair $(\Th_1,\Th_2)$ as the graph (with vertex set $V_{F_1,F_2}$) given by
\[G(\Th_1,\Th_2):=G(\Th_1)^{(1)}\cup G(\Th_2)^{(2)},\]
and define the \textbf{linking number} $L_{\Th_1,\Th_2}$ as the index (\textit{c.f.} \ref{con1})  $L_{\Th_1,\Th_2}=[U_{F_1,F_2}, G(\Th_1,\Th_2)]$. 

Similarly, given SWB data $\Th_i=(F_i,E_i)\in Sq_{N_i}(n_i,n_{i+1})$ for $i=1,\dots, k$, define 
\[V_{\bm{F}}= \left[\sqcup_{i=1}^k V_{F_i}\right]/ \left((V_{F_i})_{\nth} \ni (2N_i+1,a) \sim (0,a) \in (V_{F_{i+1}})_{\sth} \text{ for } a=1,\dots, n_{i+1}\right),\]
(where $\bm{F}=(F_1,\dots, F_k)$). Define $U_{F_i,F_{i+1}}=(V_{F_i})_{\nth}^{(i)}$, and $W_{\bm{F}}=V_{\bm{F}}/(\cup_i U_{F_i,F_{i+1}})$. Observe, the previous formulae defines a total order on $W_{\bm{F}}$ also. Define the composite graph of the tuple $\bm{\Th}=(\Th_1,\dots, \Th_k)$ as $G(\bm{\Th})=\cup_{i} G(\Th_i)^{(i)}$ on vertex set $V_{\bm{F}}$, and define the linking number as $L_{\bm{\Th}}=[\cup_i U_{F_i,F_{i+1}} , G(\bm{\Th})]$.

\begin{example}\label{vjuxteg} The composite graph of the pair $(\Th_1,\Th_2)$ can be visualised by vertically stacking the SWB diagram for $\Th_2$ on top that for $\Th_1$, lining up the vertices $(0,a)\in V_{F_2}$ with $(2N_1+1,a)\in V_{F_1}$ for each $a$. For example, let $\Th_1 \in Sq(3,9), \Th_2\in Sq(9,5)$ be the SWB data represented by the diagrams below. 
    \[\vjuxtega{0.7} \qquad \qquad \vjuxtegb{0.4}\]
Then the composite graph $G=G(\Th_1,\Th_2)$ is visualised below. The vertices drawn as large blue dots are those comprising the set $U_{F_1,F_2}$. One reads off the linking number $L_{\Th_1,\Th_2}=1$ since there is one component of $G$ whose vertex set is contained in $U_{F_1,F_2}$ (namely, the component drawn with red dashed lines).
\[\vjuxteg{0.8} \quad \to \quad  \vjuxtegg{0.6} \]
By deleting all such components from the above diagram, it can be regarded as an SWB diagram on frame $F_2 \# F_1$ by simply ignoring the blue vertices as depicted on the right above. In particular, the ordering on $W_{F_1,F_2}\subset V_{F_1,F_2}$ is compatible with the ordering on $V_{F_1\#F_2}$ as the ``anticlockwise" ordering. This motivates what follows.  
\end{example}

\begin{prop}[Vertical Juxtaposition]\label{vjuxtSWB} Let $\Th_1=(F_1,E_1)\in Sq_{N_1}(n,m)$ and $\Th_2=(F_2,E_2)\in Sq_{N_2}(m,l)$. Then there exists a unique SWB-datum $\Th_2\# \Th_1\in Sq_{N_1+N_2}(n,l)$ with frame $F_2\# F_1$, such that $G(\Th_2\# \Th_1)\simeq_O G(\Th_1,\Th_2)/ U_{F_1,F_2}$. 
\end{prop}

\begin{proof} Let $o=o_{F_1,F_2}$ for this proof. Set $\Th=(F_2\#F_1, o(E) )$, where $E$ is uniquely defined by 
\[(W_{F_1,F_2},E)=(V_{F_1}, E_1)^{(1)}\cup (V_{F_2}, E_2)^{(2)}/U_{F_1,F_2}.\]
 Then one has that $\Th\in Sq_{N_1+N_2}(n,l)$ by \ref{TLarg}. One can now check the identities $o\circ \iota_{F_1}^{(1)}=\iota_{F_2\#F_1}\circ o$ and $o\circ \iota_{F_2}^{(2)}=\iota_{F_2\#F_1}\circ o$, wherever both sides are defined. Thus we obtain $D_{F_2\#F_1}=o(D_{F_1}^{(1)}\cup D_{F_2}^{(2)})$, from which it follows that
\begin{align*}
G(\Th)&=o\left( (V_{F_1,F_2}, E_1^{(1)}\cup E_2^{(2)})/U_{F_1,F_2}\right) \cup (V_{F_2\#F_1}, D_{F_2\#F_1})\\
&=o\left( \left( V_{F_1,F_2}, (E_1\cup D_{F_1})^{(1)}\cup (E_2\cup D_{F_2})^{(2)} \right) /U_{F_1,F_2}\right)=o(G(\Th_1,\Th_2)/ U_{F_1,F_2}),
\end{align*}
using \ref{contpr}. Thus $\Th$ has the desired properties for $\Th_2\# \Th_1$, uniqueness follows by \ref{grp1}. 
\end{proof}

\begin{example}The SWB diagram for $\Th_2\#\Th_1$ with $\Th_1$ and $\Th_2$ as per \ref{vjuxteg}, is precisely the diagram on the right of the composite graph in the same example. \end{example}

\begin{prop}[Properties of Vertical Juxtaposition]\label{vjassoc} Given $(\Th_1, \Th_2, \Th_3)\in Sq_{M_1}(n,m)\times Sq_{M_2}(m,l)\times Sq_{M_3}(l,k)$, write $\Th_i=(F_i,E_i)$ for each $i$. The following hold:
\begin{enumerate}
    \item $\mathcal{G}(\Th_2\# \Th_1)\simeq_O\mathcal{G}(\Th_1)^{(1)}\cup \mathcal{G}(\Th_2)^{(2)}/\mathcal{U}_{F_1,F_2}$ (defined analogously to in \ref{vjvset}).
    \item $\Th_3\#(\Th_2\# \Th_1)=(\Th_3\#\Th_2)\#\Th_1\in Sq_{M}(n,k)$ where $M=M_1+M_2+M_3$ and  $L_{\Th_1,\Th_2}+L_{\Th_2\#\Th_1,\Th_3}=L_{\Th_1,\Th_3\#\Th_2}+L_{\Th_2,\Th_3}$.
    \item $(\Th_2\#\Th_1)^*=\Th_1^*\#\Th_2^*\in Sq_{M_1+M_2}(l,n)$ and $L_{\Th_1,\Th_2}=L_{\Th_2^*,\Th_1^*}$.
    \item For any internal component $\Gamma\subset G(\Th_1)$, $\Gamma':=o_{F_1,F_2}(\Gamma^{(1)})\subset G(\Th_2\#\Th_1)$ is an internal component such that $\Th_2\#(\Th_1\smallsetminus \Gamma)=(\Th_2\#\Th_1)\smallsetminus \Gamma'$, and $L_{\Th_1,\Th_2}=L_{\Th_1\smallsetminus\Gamma,\Th_2}$. Furthermore, $\tau_{\Gamma}=\tau_{\Gamma'}$, and $\Gamma'$ is separating if and only if $\Gamma$ is.   \end{enumerate}\end{prop}

\begin{proof} For (1), placing elements of $\V_{F_1}^{(1)}$ and $\V_{F_2}^{(2)}$ in a diagram for the composite graph $G(\Th_1,\Th_2)$ in the obvious way, it is clear that for $v_1^{(i_1)}, v_2^{(i_2)}\in \mathcal{W}_{F_1,F_2}$ we have that $o_{F_1,F_2}(v_1^{(i_1)})$, $o_{F_1,F_2}(v_2^{(i_2)}) \in \V_{F_2\#F_1}$ \footnote{here we uniquely extend $o_{F_1,F_2}$ to an OP map $V_{F_1,F_2}\cup \V_{F_1,F_2}\smallsetminus(U_{F_1,F_2}\cup \mathcal{U}_{F_1,F_2} )\to  V_{F_2\#F_1}\cup \V_{F_2\#F_1}$.} belong to the same component of the curve complement within the square (for a diagram of $\Th_2\#\Th_1$), if and only if, there is a path (possibly of length 2) through $\mathcal{U}_{F_1,F_2}$ in $\mathcal{G}(\Th_1)^{(1)}\cup \mathcal{G}(\Th_2)^{(2)}$ (\textit{c.f.} Figure \ref{fig:vjcomp}). Thus the desired result follows.
\begin{figure}[ht]

\[ \vjuxtcompa{2} \quad \xmapstoo{ (\_ )/\bm{U}_{F_1,F_2}}\quad  \vjuxtcompb{2}\]
    \caption{Local diagram for Prop. \ref{vjassoc}, part 1 with $\Th_1$ and $\Th_2$ as per \ref{vjuxteg} ($\bm{U}_{F_1,F_2}=U_{F_1,F_2}\cup \mathcal{U}_{F_1,F_2}$). }
    \label{fig:vjcomp}
\end{figure}

For (2), set $\Th_L=\Th_3\#(\Th_2\# \Th_1)$ and $\Th_R=(\Th_3\#\Th_2) \# \Th_1$. One can check that $\Th_L$ and $\Th_R$ have equal frames (\textit{c.f.} \ref{assoc1}). Furthermore, using \ref{contpr}, one has that 
\begin{align*}G(\Th_L )\simeq_{O} G(\Th_1,\Th_2,\Th_3)/(U_{F_1,F_2}\cup U_{F_2,F_3})\simeq_O G((\Th_R ),\end{align*}
hence $\Th_L=\Th_R$ by \ref{grp1}. The identity $L_{\Th_1,\Th_2}+L_{\Th_2\#\Th_1,\Th_3}=L_{\Th_1,\Th_3\#\Th_2}+L_{\Th_2,\Th_3}$ follows by \ref{contpr}; both sides are equal to $L_{(\Th_1,\Th_2,\Th_3)}$.

For (3), one can check that $(F_2\# F_1)^*=F_1^*\# F_2^*$ and using \ref{contpr}, we compute
\begin{align*}G(\Th_1^*\# \Th_2^*)&\simeq_{O} (\omega_{F_1}(G(\Th_1))^{(2)}\cup  \omega_{F_2}(G(\Th_2))^{(1)})/U_{F_2^*,F_1^*}\\
&=\omega( G(\Th_1)^{(1)} \cup G(\Th_2)^{(2)} / U_{F_1,F_2})\simeq_O G(\Th_2\#\Th_1)^*, \end{align*}
where $\omega:V_{F_1,F_2}\to V_{F_2^*,F_1^*}$ is the map given by $\omega(v^{(1)})=\omega_{F_1}(v)^{(2)}$ and $\omega(u^{(2)} )=\omega_{F_2}(u)^{(1)}$, which satisfies $\omega(U_{F_1,F_2})= U_{F_2^*,F_1^*}$ and restricts to the unique OR map $W_{F_1,F_2}\to W_{F_2^*,F_1^*}$. Furthermore, one computes 
\[L_{\Th_2^*,\Th_1^*}=[U_{F_2^*,F_1^*}, G(\Th_2^*,\Th_1^*)]=[U_{F_1,F_2}, G(\Th_1,\Th_2)] =L_{\Th_1,\Th_2}. \]
For (4), clearly $o_{F_1,F_2}$ maps $(V_{F_1})^{(1)}_{\int}$ into $(V_{F_2\# F_1})_\int$, so $\Gamma'$ is internal. Furthermore, $g_{\Gamma'}|_{P_1}=g_{\Gamma}|_{P_1}$, and $g_{\Gamma'}$ and $g_{\Gamma}$ are 0 elsewhere, hence $F_2\#(F_1)_{-\Gamma}=(F_2\#F_1)_{-\Gamma'}$ (where we have written $F_1=(P_1,s_1,f_1)$). Using \ref{contpr}, one has that 
\[G(\Th_2\#(\Th_1\smallsetminus \Gamma)) \simeq_O (G(\Th_1,\Th_2)/U_{F_1,F_2})\smallsetminus \Gamma^{(1)} \simeq_O G((\Th_2\#\Th_1)\smallsetminus \Gamma'),\]
Hence $\Th_2\#(\Th_1\smallsetminus \Gamma)=(\Th_2\#\Th_1)\smallsetminus \Gamma'$ follows by \ref{grp1}. 

To prove $\tau_{\Gamma}=\tau_{\Gamma}$, observe that $o_{F_1,F_2}^{(1)}$ induces a bijection $E(\Gamma)\cap D_{F_1}\to E(\Gamma')\cap D_{F_2\# F_1} $ which restricts to bijections $E(\Gamma)\cap (D_{F_1})_p\to E(\Gamma')\cap (D_{F_2\# F_1})_p$ for all $p\in P_1$, and that $E(\Gamma')\cap (D_{F_2\# F_1})_{q+2N_1}=\emptyset$ for all $q\in P_2$. For the last claim, we use that $(\Th_2\#\Th_1)_{\Gamma'}=\emptyset_{(P_2,s_2)} \# (\Th_1)_{\Gamma}$ with part (1), to conclude $|\G((\Th_1)_{\Gamma})|=|\G((\Th_2\#\Th_1)_{\Gamma'})|$. 
\end{proof}


\begin{lemma}[Factorisation Lemma]\label{vjfact} Let $\Th =(F,E)$ be a SWB with $F=(P,s,f)$, and suppose that $(P,s)=(P_2,s_2)\# (P_1,s_1)$ for $(P_a,s_a)\in \mathcal{TC}^*_{N_i}$. Then there exists frames $F_1=(P_1,s_1,f_1)$ and $F_2=(P_2,s_2,f_2)$, and SWB data $\Th_a=(F_{a},E_a)$, such that $\Th=\Th_2\#\Th_1$ and $L_{\Th_1, \Th_2}=0$. \end{lemma}

\begin{proof} Let $N=N_1+N_2, V_1=\cup_{i=0}^{2N_1} (V_F)_i$, $V_2=\cup_{i=2N_1+1}^{2N+1} (V_F)_i$, and partition $E$ into sets $E_1'=\{e \in E \ | \ e \subset V_1\},  E_2'=\{e \in E \ | \ e \subset V_2\},  E'=E\smallsetminus(E_1'\cup E_2')$. Let $|E'|=m$. The crossing-less condition for $E$ now implies that 
\[ E'=\{ u_i\edge v_i \ | \ u_i\in V_1, \ v_i\in V_2, \ i=1,\dots, m \}, \]
where $u_1\prec u_2 \prec \dots \prec u_m\prec v_m \prec v_{m-1}\prec \dots \prec v_1$. 

Define $f_1:\overline{P_1}\to \N$ by $f_1(p)=f(p)$ for $p\in P_1$, $f_1(\{0\})=f(\{0\})$, and $f_1(\{2N_1+1\})=m$, and define $f_2:\overline{P_2}\to \N$ by $f_2(p)=f(p+2N_1)$ for $p\in P_2$, $f_2(\{0\})=m$, and $f_2(\{2N_2+1\})=f(\{2N+1\})$. Let $o_1:V_1\to (V_{F_1})_{\sth}\cup (V_{F_1})_{\int}$ and $o_2:V_2 \to (V_{F_2})_{\nth}\cup (V_{F_2})_{\int}$ be the unique OP maps, where $F_i=(P_i,s_i,f_i)$. Now define pair-partitions
\begin{align*} E_1&=o_1(E_1')\cup \{ o(u_a)\edge (2N_1+1,a) \ | \ a=1, \dots, m\},\\
E_2&=o_1(E_2')\cup \{ o(v_a)\edge (0,a) \ | \ a=1, \dots, m\}.\end{align*}
The crossing-less condition for $E$ implies that $E_1$ and $E_2$ are crossing-less, that is, $\Th_1=(F_1,E_1)$ and $\Th_2=(F_2,E_2)$ are SWB-data, and one has $\Th=\Th_2\# \Th_1$ and $L_{\Th_1, \Th_2}=0$ by construction.  \end{proof}


\subsection{Isotopy} In this subsection we define a notion of isotopy for SWB data, which is an equivalence relation on the latter \ref{iso}. We establish some key properties of this relation in Prop. \ref{ptprops} and then prove Prop. \ref{isorep}, which establishes the existence and uniqueness of isotopy reduced representatives, under mild conditions.


\mdef\label{turnb} For $\Th=(F,E)\in Sq_N (n,m)$, a \textbf{turn-back} is a part $e\in E$ of the form $e=\{(i,a),(i,b)\}$ for $i\in \underline{2N}$, \textit{i.e.} $e\subset V_i$. For $(i,a)\in (\Z_{> 0})^2$ fix the notation $((i,a))=\{(i,a),(i,a+1)\}$. If $((i,a))\subset (V_F)_\int$, define $U_{((i,a))}=((i,a))\cup \iota_{F}((i,a))\subset (V_F)_\int$, and $V_{((i,a))}=V_F\smallsetminus U_{((i,a))}$. Setting $F=(P,s,f)$, define $\delta_i:\overline{P}\to \Z_{\geq 0}$ by
\[\delta_{i}(p)=\begin{cases}1, & \text{if }i\in p,\\
0, &\text{otherwise,}\end{cases}\]
and $F_{((i,a))}:=(P,s,f-2\delta_i)$. Observe that $|V_{((i,a))}|=|V_{F_{((i,a))}}|$ and let $o_{((i,a))}:V_{((i,a))}\to V_{F_{((i,a))}}$ be the unique OP map. 

\begin{prop}[Pull-throughs]\label{pthru} Let $\Th=(F,E)$ be a SWB-datum, and suppose that $((i,a))\in E$ for $(i,a)\in (V_F)_\int$, while $\iota_{F}((i,a))\notin E$. There exists a unique SWB-datum $\Th_{((i,a))}:=(F_{((i,a))}, E')$, such that 
\[G(\Th_{((i,a))})\simeq_O G(\Th)/U_{((i,a))},\]
Furthermore, there is a bijection $O_{((i,a))}:\mathcal{C}(G(\Th))\to \mathcal{C}(G(\Th_{((i,a))}))$ given by 
\[O_{((i,a))}(\Gamma)=o_{((i,a))}\left(\Gamma/\left(V(\Gamma)\cap U_{((i,a))}\right) \right).\] 
\end{prop}
\begin{proof} Let $u=(i,a)$ and $v=(i,a+1)$ for convenience. Since $\iota_F((i,a))\notin E$, it follows that there exist distinct $u', v' \in V_F$ such that $u'\edge \iota_F(u)\edge u\edge v\edge \iota_F(v)\edge v' \subset G(\Th)$, with $\{u',\iota_F(u)\}, \{v,\iota_F(v)\} \in E$. The crossingless condition for $E$, then implies that 
\[E''=E \smallsetminus \{\{u,v\},\{u', \iota_F(u)\},\{v', \iota_F(v)\}\} \cup\{ \{u', v'\}\}, \]
is a crossingless pair-partition of $V_{((i,a))}$, and hence $\Th'=(F_{((i,a))}, o_{((i,a))}(E'') )$ is a SWB-datum. 

Using the fact that $\iota_{F_{((i,a)}}\circ o_{((i,a))}= o_{((i,a))}\circ \iota_F$ (where defined), one can check that $G(\Th')$ is obtained from $G(\Th)$ by replacing the path $u'\edge \iota_F(u)\edge u\edge v\edge \iota_F(v)\edge v'$ with the path $u'\edge v'$ (which is precisely the effect of contracting on the vertex subset $U_{((i,a))}$), and then applying the OP map $o_{((i,a))}$. The last claim follows by \ref{contpr} since $[U_{((i,a))}: G(\Th)]=0$.
\end{proof}

