\mdef\label{pthru2} For $N\in \Z_{\geq 0}$, and $(i,a)\in \underline{2N}\times \Z_{>0}$ define the \textbf{pull-through}, $J^{(N)}_{(i,a)}:Sq_N (n,m)\to Sq_N (n,m)$ by
\[J^{(N)}_{(i,a)}(\Th)=\begin{cases}\Th_{((i,a))}, &((i,a))\in E \text{ and } \iota_{F}((i,a))\notin E,\\
\Th, & \text{otherwise.}
\end{cases}\]
We will often omit the superscript and write simply $J_{(i,a)}$ for a pull-through when the rank is clear from context.

\begin{example} We draw the SWB diagrams for $\Th_2'$ as per \ref{SWBex}, and $J_{(3,1)}(\Th_2')$ below. 
\[\SWBtwo{0.42} \quad\xmapstoo{J_{(3,1)}}\quad \SWBiso{0.42}\]
\end{example}

\mdef\label{iso} Let $\overset{\iso}{\sim}$ be the equivalence relation on $Sq(n,m)$ generated by $\Th_1 \overset{\iso}{\sim} \Th_2$, if $\Th_2=J^{(N)}_{(i,a)}(\Th_1)$ for some $N\in \Z_{\geq 0}$ and $(i,a)\in \underline{2N}\times \Z_{> 0}$. We call the equivalence relation $\overset{\iso}{\sim}$ \textbf{isotopy}, and if $\Th_1\overset{\iso}{\sim} \Th_2 $ we say that $\Th_1$ and $\Th_2$ are \textbf{isotopic}. We denote the set of isotopy classes by $Sq^{\iso}(n,m)=Sq(n,m)/\overset{\iso}{\sim}$.

\begin{prop}[Properties of pull-throughs]\label{ptprops} Let $\Th=(F,E)\in Sq_N(n,m)$ be such that $((i,a))\in E$ for $(i,a)\in (V_F)_\int$, whilst $\iota_F((i,a))\notin E$. Let $\Th'=(F',E')\in Sq_{N'}(m,l)$ and write $\Th''=(F'',E'')=\Th'\#\Th\in Sq_{N''}(n,l)$, and $L=L_{\Th,\Th'}$. The following hold:
\begin{enumerate}
    \item $|\CC(\mathcal{G}(\Th_{((i,a))}))|=|\CC(\mathcal{G}(\Th))|$.
    \item $(\Th_{((i,a))})^*=J_{\omega_{F}(i,j+1)}(\Th^*)$.
    \item For $\Gamma\in \mathcal{C}(G(\Th))$, set $\Gamma'=O_{((i,a))}(\Gamma)\in \mathcal{C}(G(\Th_{((i,a))}))$. If $(i,a)\in V(\Gamma)$ then $\Th\smallsetminus \Gamma=\Th_{((i,a))}\smallsetminus \Gamma'$, otherwise $J_{o_\Gamma(i,a)}(\Th\smallsetminus \Gamma)=\Th_{((i,a))}\smallsetminus \Gamma'$. Furthermore, $\tau_{\Gamma'}=\tau_{\Gamma}$, and $\Gamma'$ is internal (separating) if and only if $\Gamma$ is, respectively.
    \item If $\iota_{F''}((i,a))\notin E''$ then $J_{(i,a)}^{(N'')}(\Th'')=\Th'\#\Th_{((i,a))}$ and $L_{\Th_{((i,a))},\Th'}=L$. If $\iota_{F''}((i,a))\in E''$ then $U^{(F'')}_{((i,a))}$ is the vertex set of a component $\Gamma \in \mathcal{C}(G(\Th''))$, \textit{i.e.} $V(\Gamma)=U^{(F'')}_{((i,a))}$, which satisfies $\Th''\smallsetminus \Gamma=\Th'\#\Th_{((i,a))}$ and $L_{\Th_{((i,a))},\Th'}=L+1$. Futhermore, $\Gamma$ is internal, separating, and satisfies $\tau_\Gamma=0$.
\end{enumerate}\end{prop}

\begin{proof} For (1), set $\mathcal{G}=\mathcal{G}(\Th)$, $\mathcal{G}'=\mathcal{G}(\Th_{((i,a))})$ and $u=(i,a), v=(i,a+1)\in V_F$. One sees from \ref{fig:iso_local} that there are two components of $\mathcal{G}$ of interest, namely, the components containing $u^+$ and $u^-$, respectively. After applying $J_{(i,a)}$, the former component is changed by deleting vertex subset $\{u^+, \iota_F(u^+)\}$, and the latter is changed by identifying $u^-\sim v^+$ and $\iota_F(u^-)\sim \iota_F(v^+)$ (both up to applying an OP map). Neither of these steps changes the number of components, hence (1) follows.

For (2), one can check both SWB-datum have frame $(F_{((i,a))})^*$, and we compute 
\[G((\Th_{((i,a))})^* ) \simeq_O \omega_F ( G(\Th )/U_{((i,a))}) = G(\Th^* )/ U^{(F^*)}_{ \omega_F((i,a)) }\simeq_O G(J_{\omega_F(i,j+1)}(\Th^*)),  \]
using the fact that $\omega_F(U_{((i,a))})=U^{(F^*)}_{\omega_F ((i,a))}$. The desired equality follows from \ref{grp1}.

For (3), if $(i,a)\in V(\Gamma)$ then $g_{\Gamma}=g_{\Gamma'}+2 \delta_i$, hence $\Th\smallsetminus \Gamma$ and $\Th_{((i,a))}\smallsetminus \Gamma'$ have frame $F_{-\Gamma}$. If $(i,a)\notin V(\Gamma)$ then $g_{\Gamma}=g_{\Gamma'}$, hence $J_{o_{\Gamma}(i,a)}(\Th\smallsetminus \Gamma)$ and $\Th_{((i,a))}\smallsetminus \Gamma'$ have frame $(F_{((i,a))})_{-\Gamma'}$. In both cases we have 
\[G(\Th_{((i,a))}\smallsetminus \Gamma')\simeq_O (G(\Th)/U_{((i,a))})/o_{((i,a))}^{-1}( V(\Gamma') )=G(\Th)/(U_{((i,a))}\cup o_{((i,a))}^{-1}V(\Gamma' ) ).  \]
If $(i,a)\in V(\Gamma)$ then $U_{((i,a))}\cup o_{((i,a))}^{-1}V(\Gamma' )=V(\Gamma)$ hence $G(\Th_{((i,a))}\smallsetminus \Gamma')\simeq_O G(\Th\smallsetminus \Gamma)$. If $(i,a)\notin V(\Gamma)$ then $o_{((i,a))}^{-1}V(\Gamma' )=V(\Gamma)$, hence 
\[G(\Th_{((i,a))}\smallsetminus \Gamma')\simeq_O(G(\Th)/V(\Gamma))/U_{((i,a))} \simeq_O G(J_{o_{\Gamma}(i,a)}(\Th\smallsetminus \Gamma)).\]
In both cases, the desired equality now follows from \ref{grp1}. 

Since $o_{((i,a))}$ restricts to a bijection $(V_{F})_{\int}/U_{((i,j))}\to (V_{F_{((i,j))}})_\int$, it follows that $O_{((i,a))}$ maps internal (external) components of $G(\Th)$, to internal (external) components of $G(\Th_{((i,a))})$, respectively. If $((i,a))\subset V(\Gamma)$, then $E(\Gamma')\cap D_{F_{((i,j))}} $ contains two fewer parts both belonging to the same band, so $\tau_{\Gamma'}$ is unchanged. If $((i,a))\not\subset V(\Gamma)$, then $o_{((i,a))}$ induces a bijection $E(\Gamma)\cap D_{F}\to E(\Gamma')\cap D_{F_{((i,j))}}$ which preserves the band each part belongs to so $\tau_{\Gamma'}=\tau_{\Gamma}$. For the last claim, it follows from the first part of (3) and part (1) that $|\CC(\G(\Th_{\Gamma}))|=|\CC(\G((\Th_{((i,j))})_{\Gamma'}))|$.

For (4), in both cases using \ref{grp1} we can compute
\[ G(\Th'\#\Th_{((i,a))})\simeq_O   \left(G(\Th, \Th')/ (U_{((i,a))}^{(F)})^{(1)}\right)/U_{F,F'}\simeq_O G(\Th'')/U_{((i,a))}^{(F'')},  \]
and that $\Th'\#\Th_{((i,a))}$ has frame $F'\# F_{((i,a))}=F''_{((i,a))}$. 

If $\iota_{F''}((i,a))\notin E''$, then $J^{(N'')}_{((i,a))}(\Th'')=(\Th'')_{((i,a))}$ which has frame $F''_{((i,a))}$, and satisfies $G(\Th''_{((i,a))})\simeq_O G(\Th'')/U_{((i,a))}^{(F'')}$, hence $J^{(N'')}_{((i,a))}(\Th'')=\Th'\# \Th_{((i,a))}$ by \ref{grp1}. Furthermore,  $|\CC(G(\Th''_{((i,a))}))|=|\CC(G(\Th''))|$ so $L_{\Th_{((i,a))},\Th'}=L$.

If $\iota_{F''}((i,a))\in E''$, then $G(\Th'')$ contains the cycle $\Gamma=u\edge v\edge \iota_{F''}(v)\edge \iota_{F''}(u)\edge u$ (where we let $((i,a))=\{u,v\}$), and clearly $V(\Gamma)=U^{(F'')}_{((i,a))}$. Furthermore, $\Th''\smallsetminus \Gamma$ has frame $(P'',s'',f''-2\delta_i)=F'\# F_{((i,a))}$ (where $F''=(P'',s'',f'')$), and satisfies $G(\Th''\smallsetminus \Gamma)\simeq_O G(\Th'')/ V(\Gamma)\simeq_O G(\Th' \# \Th_{((i,a))})$. Hence $\Th''\smallsetminus \Gamma=\Th' \# \Th_{((i,a))}$ by \ref{grp1}, and since $|\CC(G(\Th''\smallsetminus \Gamma))|=|\CC(G(\Th''))|-1$, we find $F_{\Th_{((i,a))}, \Th'}=L+1$. The desired properties for $\Gamma$ are clear.
\end{proof}

\begin{prop}\label{isorep} Let $\Th$ be a SWB-datum whose curve graph has no internal components. Then the class $[\Th]_\iso$ has a unique representative $\Th'\isosim\Th$ without turnbacks. We call such a representative \textbf{isotopy reduced}.    
\end{prop}

\begin{proof} Suppose that $\Th=(F,E)$ has a turnback $e\in E$, such that $e\subset (V_F)_i$ for some integer $i$. The crossing-less condition for $E$, then implies that $((i,a))\in e$ for some $j$. Since $G(\Th)$ had no internal components, we have $\iota_F((i,a))\notin E$ hence $J_{(i,a)}(\Th)=\Th_{((i,a))}$, \textit{i.e.} we can always apply a non-trivial pull-through to such a $\Th$. The existence of an isotopy representative $\Th' \sim \Th$ without turnbacks now follows by iterating this procedure finitely many times, since the complexity (\text{c.f.} \ref{cpx}) strictly decreases with each iteration; $C(\Th_{((i,a))})=C(\Th)-2$.

For uniqueness we apply Newman's diamond lemma \cite{Newman}; suppose that $\Th_1=J_{((i_1,a_1))}(\Th)$ and $\Th_2=J_{((i_2,a_2))}(\Th)$ for $(i_1,a_1)\neq (i_2,a_2) $. We may assume WLOG that $((i_1,a_1)), ((i_2,a_2)) \in E$, and set $o_{((i_1,a_1))}(i_2,a_2)=(i_2,a_2')$ and $o_{((i_2,a_2))}(i_1,a_1)=(i_1,a_1')$, for convenience. There are two cases two consider, namely,  $|U_{((i_1,a_1))}\cap U_{((i_2,a_2))}|=0,2$. When $U_{((i_1,a_1))}$ and $U_{((i_2,a_2))}$ are disjoint, one can verify straightforwardly using the criteria from \ref{grp1} that $J_{((i_2,a_2'))}(\Th_1)= J_{((i_1,a_1'))}(\Th_2)$. Otherwise, when $|U_{((i_1,a_1))}\cap U_{((i_2,a_2))}|=2$ one can similarly verify that $\Th_1=\Th_2$. In either case, there exists some common SWB $\Th_3$ obtainable from $\Th_1$ and $\Th_2$ by a pull-through. \end{proof}

