\begin{prop}[Handle slides]\label{hsprop} Let $\Th=(F,E)\in Sq_M(n,m)$ with $F=(P,s,f)$, and let $(i,\e)$ be an admissible pair in $P$. Then there exists a unique SWB-datum $\Th_{(i,\e)}\in Sq_M(n,m)$ of the form $\Th_{(i,\e)}=(F_{(i,\e)},E')$ such that
\begin{equation}G(\Th_{(i,\e)})=o_{(i,\e)}\left(G(\Th)\smallsetminus\bigcup_{u \in (U_F)_i} u\edge \iota_F(u)\right)\cup \bigcup_{u\in (V_F)_i} P_u  ,\label{hsgr}\end{equation}
where $(U_F)_i:=\{ u\in (V_F)_i \ | \ \{u,\iota_F(u)\}\notin E\}$, and $P_u$ is the path
\[P_u:=[o_{(i,\e)}(u) ] \edge [\iota_{F_{(i,\e)}}\circ o_{(i,\e)}(u)] \edge [\iota_{F_{(i,\e)}}\circ o_{(i,\e)}\circ \iota_{F}(u)]\edge [o_{(i,\e)}\circ \iota_{F}(u)].\]
Furthermore, there is a bijection $O_{(i,\e)}: \mathcal{C}(G(\Th))\to \mathcal{C}(G(\Th_{(i,\e)}))$ uniquely defined by 
\[O_{(i,\e)}(\Gamma)/(V(O_{(i,\e)}(\Gamma))\cap U_{(i,\e)})=o_{(i,\e)}(\Gamma).\] \end{prop}

\begin{proof} For this proof, fix $F'=F_{(i,\e)}, o'=o_{(i,\e)}$, $U'=U_{(i,\e)}$, set $q=\{i+\e,i'\}\in P$ and $i\in p\in P$. By direct computation, one finds the following for $(i,a) \in (V_F)_i$:
\begin{align*}
    \iota_{F'}\circ o' (i,a)&=\begin{cases} (\sigma(i'),f(p)+f(q)+1-a), & s(q)=0, \& \ \sigma(i)>\sigma(i'),\\
    (\sigma(i'),f(q)+a), & s(q)=1, \& \ \sigma(i)>\sigma(i'),\\
    (\sigma(i'),f(p)+1-a), & s(q)=0, \& \  \sigma(i')>\sigma(i),\\
    (\sigma(i'),a), & s(q)=1, \& \ \sigma(i')>\sigma(i),   \end{cases} \\
    \iota_{F'}\circ o' \circ \iota_{F} (i,a)&=\begin{cases} (\sigma(i),a), & s(q)=0,\\
    (\sigma(i),f(p)+1-a), & s(q)=1.   \end{cases} 
\end{align*}
From the above, one can verify $\iota_{F'}\circ o'((V_F)_i\cup \iota_F(V_F)_i )=U'$ and the following:
\begin{align*}E_{(i,\e)}&:=\iota_{F'}\circ o'\{ u \edge \iota_F(u) | \ u \in (V_F)_i \}\\
&=\begin{cases} \left\{ (\sigma(i),f(p)+1-a)\edge (\sigma(i'),f(q)+a)    \ | \ a=1,\dots, f(p)\right\}, &  \sigma(i')<\sigma(i),\\
\left\{ (\sigma(i),f(p)+1-a)\edge (\sigma(i'),a)    \ | \ a=1,\dots, f(p)\right\}, &  \sigma(i)<\sigma(i').
\end{cases} \end{align*}
Thus $E_{(i,\e)}$ is a crossing-less pairing of the convex subset $U'$, and so $\Th'=(F', o'(E)\cup E_{(i,\e)})$ is a SWB-datum. 

To see that $G(\Th')$ has the desired property \eqref{hsgr}, we note that the identity $o'\circ \iota_F=\iota_{F'} \circ o'$ holds on $(V_F)_\int \smallsetminus (V_F)_p$, so 
\[D_{F'}=o'(D_F\smallsetminus (D_F)_p )\cup \left\{\begin{array}{c}  {[\iota_F'\circ o'(u)] \edge [o'(u)]  ,}\\ {[\iota_F'\circ o'\circ \iota_F(u)] \edge [o'\circ \iota_F(u)],}\end{array}  \ \Big| \ u \in (V_F)_i   \right\}.\]
The identity \eqref{hsgr} now follows from \ref{SWBgraph}. The existence and bijectivity of the map $O_{(i,\e)}$ follows from \ref{contpr}, noting that $G(\Th')/ U'=o'(G(\Th))$; contraction on vertices $\iota_F'\circ o'(u)$ and $\iota_F'\circ o'\circ \iota_F(u)$ replaces the path $P_u$ with the edge $o'(u\edge \iota_F(u))$ for all $u\in (V_F)_i$. \end{proof}

