\mdef\label{hsdef} For any $N\in \Z_{\geq 0}$ and $(i,\e)\in \underline{2N}\times \{\pm 1\}$, define a map $H^{(N)}_{(i,\e)}:Sq_{N}(n,m)\to Sq_{N}(n,m)$, by 
\[ H^{(N)}_{(i,\e)}(\Th ) = \begin{cases} \Th_{(i,\e)}, & (i,\e) \text{ admissible in } P,\\
\Th, & \text{otherwise},\end{cases} \]
for $\Th=(F,E)$, $F=(P,s,f)$. We refer to the map $H^{(M)}_{(i,\pm 1)}$ as the \textbf{handle slide} up (+1) or down (-1) at site $i$. We will often omit the superscript and write simply $H_{(i,\e)}$ for a handle slide when the rank is clear from context.

\begin{prop}[Properties of handle-sliding]\label{hselem} Let $\Th=(F,E)\in Sq_N(n,m)$ be an SWB datum, with $F=(P,s,f)$, and suppose $(i,\e)$ is admissible in $P$. Then the following hold:
\begin{enumerate}
    \item\label{hscplt} $|\mathcal{G}(\Th_{(i,\e)})|=|\mathcal{G}(\Th)|$. 
    \item\label{hsdual} $(\Th_{(i,\e)})^*=H_{(\omega_M(i),-\e)}(\Th^*)$.
    \item\label{hscpt} For $\Gamma\in \mathcal{C}(G(\Th))$ set $\Gamma'=O_{(i,\e)}(\Gamma)$. Then  $H_{(i,\e)}(\Th\smallsetminus \Gamma)=\Th_{(i,\e)}\smallsetminus \Gamma'$. Furthermore, $\tau_{\Gamma}=\tau_{\Gamma'}$, and $\Gamma'$ is internal (separating), if and only if $\Gamma$ is, respectively.
    \item\label{hsiso}$H_{(i,\e)}\circ J_{(j,a)}(\Th)\overset{\iso}{\sim} \Th_{(i,\e)}$ for all $(j,a)\in \underline{2M}\times \Z_{>0}$.
    \item\label{hsjuxt} For any $\Th' \in Sq_{N'}(m,l)$ we have $\Th' \# \Th_{(i,\e)}=H^{(N+N')}_{(i,\e)}\left(\Th' \#\Th\right)$ and $L_{\Th_{(i,\e)},\Th'}=L_{\Th,\Th'}$.
\end{enumerate}\end{prop}
\begin{proof} As for \ref{hsprop}, set $F'=F_{(i,\e)}$, $o'=o_{(i,\e)}$ and let $i\in p\in P$ and let $q=\{i+\e, i'\}\in P$.

    For (1), by considering the curve complements in Figure \ref{fig:hsloc}, one sees that for $\e=+1$
\begin{equation}\mathcal{G}(\Th)/\{v_M^+, w_m^-, \iota_F(w_m^-) \} \simeq_O \mathcal{G}(\Th_{(i,\e)})/\{o'(v_M)^{+}\}\cup \mathcal{U}_{(i,\e)}  \label{eqhscpt}\end{equation}
where $v_M=\max((V_F)_i)$, $w_m=\min((V_F)_{i+1})$, and $\mathcal{U}_{(i,\e)}:=\left\{u^+, u^- \ | \ u \in U_{(i,\e)} \right\}$ (using the notation $v^\pm\in \V_F$ for $v\in V_F$ as in the proof of Prop. \ref{comp1}). The desired equality in the $\e=+1$ case now follows since both contractions in \eqref{eqhscpt} preserve the number of components. The case $\e=-1$ follows by combining with part \eqref{hsdual}.

    For (2), using \ref{fliplemma} one has that $H_{(\omega_N(i),-\e)}(\Th^*)=(\Th^*)_{(\omega_N(i),-\e)}$, and both SWB data have frame $(\omega(P),s_{(i,\e)}\circ\omega^{-1},f_{(i,\e)}\circ\omega^{-1}  )$, where $\omega=\omega_N\circ \sigma$. Furthermore, one computes 
    \begin{align*}
          G(\Th_{(i,\e)}^*)&=\omega_{F_{(i,\e)}}(G(\Th_{(i,\e)}))\\
          &=o_{(i,\e)}\left(G(\Th^*)\smallsetminus\bigcup_{u \in (U_{F^*})_{\omega_N(i)}} u- \iota_{F^*}(u)\right)\cup \bigcup_{u\in (V_{F^*})_{\omega_N(i)}} P^{(\Th^*)}_u\\
          &=G(H_{(\omega_N(i),-\e)}(\Th^*) ),
    \end{align*}
    where we have used the identities $\omega_{F'}\circ \iota_{F'}= \iota_{(F')^*}\circ \omega_{F'}$ (for any frame $F'$) and $\omega_{F_{(i,\e)}}\circ o_{(i,\e)}=o_{(\omega_N(i),-\e)}\circ \omega_F$, wherever defined. The result now follows by \ref{grp1}.

    For (3), we first note that $(f-g_{\Gamma})_{(i,\e)}=f_{(i,\e)}-(g_{\Gamma})_{(i,\e)}=f_{(i,\e)}-g_{\Gamma'}$, hence both SWB-data have the same frame. Their equality follows from \ref{grp1} now since both have graphs $\simeq_O G(\Th_{(i,\e)}) \smallsetminus \Gamma'$.

    Clearly $O_{(i,\e)}$ preserves internality of components, and $|\CC\left(\mathcal{G}((\Th_{(i,\e)})_{\Gamma'}  )\right)|=|\CC\left(\mathcal{G}(\Th_{\Gamma}  )\right)|$ follows by combining part (1) and (3). Since $o_{(i,\e)}$ induces a bijections $E(\Gamma)\cap (D_{F})_r\to E(\Gamma')\cap (D_{F'})_{\sigma(r)} $, for all $r\in P\smallsetminus\{p,q\}$, we now compute
    \begin{align*}\tau_{\Gamma'}&=\sum_{p' \in \sigma( P) }| E(\Gamma')\cap (D_{F'})_{p'}|s_{(i,\e)}\circ \sigma^{-1}(p')\\
    &=\sum_{r\in P\smallsetminus\{p,q\}} | E(\Gamma)\cap (D_{F})_r|s(r)+| E(\Gamma')\cap (D_{F'})_{\sigma(p)}|s_{(i,\e)}(p)+| E(\Gamma')\cap (D_{F'})_{\sigma(p)}|s_{(i,\e)}(q) \\
    &=\sum_{r\in P\smallsetminus\{p,q\}} | E(\Gamma)\cap (D_{F})_r|s(r)+| E(\Gamma)\cap (D_{F})_{p}|\left( s(p)+s(q) \right)\\
    &\quad+\left(| E(\Gamma)\cap (D_{F})_{p}|+| E(\Gamma)\cap (D_{F})_{q}|\right )s(q)=\sum_{r\in P} | E(\Gamma)\cap (D_{F})_r|s(r)=\tau_\Gamma.
    \end{align*}

    Part (4) is trivial unless $((j,a)) \in E$ and $\iota_F((j,a))\notin E$. If $j \in p$, we then claim that $H_{(i,\e)}\circ J_{(j,a)}(\Th)=J_{(j_2,a_2)}\circ J_{(j_1,a_1)} (\Th_{(i,\e)})$ where $((j_1,a_1))=o'((j,a))$, and $((j_2,a_2))=\iota_{F'}\circ o'\circ \iota_F((j,a))$. Otherwise, we claim that $H_{(i,\e)}\circ J_{(j,a)}(\Th)=J_{(j_1,a_1)} (\Th_{(i,\e)})$ for $(j_1,a_1)$ as before. Part (5) is verified straightforwardly using the criteria in \ref{grp1}.\end{proof}

