We conclude this subsection with the following corollary:

\begin{corollary}\label{hscor}
    For any $\Th\in Sq_N(n,m)$ with $N>0$, there exist unique $g\in \Z_{\geq 0}$ and $t\in \{0,1,2\}$ subject to $2g+t=N$, and $l_i\in \Z_{\geq 0}$ for $i=1,\dots, g+t-1$, such that 
    \[\Th \hssim (\Psi_{t}\# \dots \# \Psi_{1}) \# (\Th_g \# \dots \# \Th_1)  \]
    for some $\Th_{i}\in Sq_{\tor}(l_{i-1},l_i)$, $\Psi_i\in Sq_{\mob}(l_{g+i-1}, l_{g+i})$, where we set $l_0=n$ and $l_{g+t}=m$.
\end{corollary}

\begin{proof}
    Follows by combining the Factorisation Lemma \ref{vjfact}, with Theorem \ref{rform}.
\end{proof}



\subsection{Left-most and Right-most Components} In this subsection we define two (families of) maps $\I_L,\I_R:Sq(n,m)\to Sq(n+1,m+1)$, which can be defined by adding certain components to the corresponding curve graphs. Diagrammatically, these correspond to adding curves which are isotopic to sub-intervals of the surface boundary, either on the left or right hand edge of the diagram. In Prop \ref{Ilrprop}, we prove that both maps descend to maps on handle slide equivalence classes, as well as some other key properties. In Lemmata \ref{lem1}, \ref{lem2}, and \ref{lem3} we establish three identities, which will be used in \S4 to establish a monoidal structure on the category we define in \S4. Finally we conclude this section with Prop. \ref{decomp}, from which we can deduce a monoidal generating set for said category.

\mdef For a frame $F=(P,s,f)$ of rank $N$, define frames $F_L=(P,s,f_L)$ and $F_R=(P,s,f_R)$ by $f_L(r)=f_R(r)=f(r)+1$ for $r\in \{\{0\}, \{2N+1\}\}$, and $f_L(p)=f(p)$, $f_R(p)=f(p)+2$ for $p \in P$. Define vertex subsets $U_{L}\subset V_{F_L}$ and $U_{R}\subset V_{F_R}$ by
\[U_L=\{\min(V_{F_L}), \max(V_{F_L})\}, \quad U_R=\{\max(V_{F_R})_i, \min(V_{F_R})_{i+1} \ | \ i=0,\dots, 2N\}.\]
Let $o_L:V_{F}\to V_{F_L}\smallsetminus U_L$ and $o_R: V_F \to V_{F_R}\smallsetminus U_R$ be the unique OP maps.

\begin{prop}\label{LRadd} Let $\Th\in Sq_N(n,m)$. Then there exist unique SWB-data $\Th_L=(F_L,E'), \Th_R=(F_R,E'')\in Sq(n+1,m+1)$, such that 
\[G(\Th_L)= o_L(G(\Th))\sqcup \Gamma_L, \qquad  G(\Th_R)=o_R(G(\Th))\sqcup \Gamma_R,\]
where $\Gamma_L=(0,1)\edge (2N+1,1)$, and $\Gamma_R\simeq_O \overline{\del(P,s)}$ (\textit{c.f.} \ref{bdgrp}) is a path between $(0,n+1)$ and $(2N+1,m+1)$. Furthermore, $\Gamma_L$ and $\Gamma_R$ are separating with $\tau_{\Gamma_L}=0=\tau_{\Gamma_R}$.\end{prop}
\begin{proof} Set $v_M^{(i)}=\max((V_{F_R})_i)$ and $v_m^{(i)}=\min((V_{F_R})_i)$ and take $E'=o_L(E) \cup \{ (0,1)\edge (2N+1,1) \}$ and $E''=o_R(E)\cup \{v_M^{(i)}\edge v_m^{(i+1)} \ | \ i=0,\dots 2N\}$. Then $\Th'=(F_L,E')$ and $\Th''=(F_R,E'')$ are SWB-data. It is clear that $\Th'$ is the unique such datum with desired property for $\Th_L$. Observe that $\iota_{F_R}$ preserves the vertex subset $U_R\subset V_{F_R}$, thus one may write $G(\Th'')=o_R(G(\Th))\sqcup G(\Th'')[U_R]$. Since $\iota_{F_R}(v_M^{(i)})=v_m^{(i')}$ where $\{i,i'\}\in P$, we establish an OP graph isomorphism $\overline{G(P,s)} \simeq_O G(\Th'')[U_R]$ via the map $(i,+)\mapsto v_M^{(i)}$ and $(i,-)\mapsto v_m^{(i)}$, thus $\Th''$ is the unique SWB datum with the desired property for $\Th_R$.

The component $\Gamma_L\subset \G(\Th_L)$ has $\tau_{\Gamma_L}=0$, since it contains no edges from $D_{F_L}$, and $\Gamma_R\subset \G(\Th_R)$ has $\tau_{\Gamma_R}=0$ since $|E(\Gamma_R)\cap (D_F)_p|=2$ for all $p\in P$. Furthermore, $\mathcal{G} \left((\Th_L)_{\Gamma_L}\right)$ contains the component $(0,1/2) \edge (2N+1,1/2)$, and $\mathcal{G}\left((\Th_R)_{\Gamma_R} \right)$ contains a component $\simeq_O\overline{\del(P,s)}$ on the vertex set 
\[\left\{(0,3/2),(2N+1,3/2)\right\}\cup \left\{ (i,1/2),(i,5/2) \ | \ i=1,\dots 2N\right\}.\]
Thus the components $\Gamma_L$ and $\Gamma_R$ are separating.\end{proof}


\mdef\label{Ilr} Let $\I_L, \I_R: Sq(n,m)\to Sq(n+1,m+1)$ be maps defined by $\I_L(\Th)=\Th_L$ and $\I_R(\Th)=\Th_R$, respectively. 

\begin{example} Let $\Th_1 \in Sq(3,1)$ be as per \ref{SWBex}. SWB diagrams for $\I_L(\Th_1)$ and $\I_R(\Th_2)$ are below:
\[\I_L(\Th_1)=\ILexa{0.45}, \quad \I_R(\Th_1)=\IRexa{0.45}.\]
    Let $\Th_2=(F_2, E_2)$ as per the same example with $E_2$ generic. We can draw $\I_L(\Th_1)$ and $\I_R(\Th_2)$ by adding new components to the otherwise generic diagram:
    \[ \I_L(\Th_2)=\SWBtwL{0.35}, \quad \I_R(\Th_2)=\SWBtwR{0.35} .\]
For a completely generic diagram of some $\Th=(F,E)$, drawn using the box notation as in Example \ref{SWBex}, we can similarly draw $\I_L(\Th)$ and $\I_R(\Th)$ by adding new components to the generic diagrams
\[\I_L(\Th)= \genSWBL{1.4} , \qquad \I_R(\Th)=\genSWBR{1.4}.\]
\end{example}



\begin{prop}\label{Ilrprop} Let $\Th\in Sq(n,m)$ The following hold:
\begin{enumerate}    
    \item For any component $\Gamma \subset G(\Th)$, $o_L(\Gamma)\subset G(\I_L(\Th))$ and $o_R(\Gamma)\subset G(\I_R(\Th))$ are components with the same twist, internality, and separatingness.
    \item\label{Ilrdesc} $\I_L$ and $\I_R$ descend to maps $\I_L,\I_R : Sq^{\hs}(n,m)\to Sq^{\hs}(n+1,m+1)$.
    \item For $\Th' \in Sq(m,l)$, we have $\I_L(\Th'\# \Th)=\I_L(\Th')\# \I_L(\Th)$, $\I_R(\Th'\# \Th)=\I_R(\Th')\# \I_R(\Th)$, and $L_{\Th,\Th'}=L_{\I_L(\Th),\I_L(\Th')}=L_{\I_R(\Th),\I_R(\Th')}$.
    \item $\I_L(\Th^*)=(\I_L(\Th))^*$ and $\I_R(\Th^*)=(\I_R(\Th))^*$. 
\end{enumerate}
\end{prop}
\begin{proof}
    Part (1) follows since $\Th_L\smallsetminus \Gamma_L = \Th = \Th_R\smallsetminus \Gamma_R$, since for any $\Gamma \in \mathcal{C}(G(\Th))$ and $p \in P$ we have $|E(o_L(\Gamma))\cap (D_{F_L})_p|=| E(\Gamma)\cap (D_F)_p|=| E(o_R(\Gamma))\cap (D_{F_R})_p|$, and since $o_L$ and $o_R$ preserve the internality/externality of vertices.

    For (2), it suffices to check that $\I_L\circ J_{(i,\a)}(\Th) \hssim \I_L(\Th)$, $\I_L\circ H_{(i,\e)}(\Th) \hssim \I_L(\Th)$, $\I_R\circ J_{(i,\a)}(\Th) \hssim \I_R(\Th)$, and $\I_R\circ H_{(i,\e)}(\Th) \hssim \I_R(\Th)$ for any relevant $(i,a)$ and $(i,\e)$. In the first three cases, the following identities can be proven by the criteria in Lemma \ref{grp1}:
    \[\I_L\circ J_{(i,a)}(\Th) =J_{(i,a)} \circ \I_L(\Th), \quad   \I_L\circ H_{(i,\e)}(\Th) =H_{(i,\e)} \circ \I_L(\Th),\quad \I_R\circ J_{(i,a)}(\Th)=J_{(i,a+1)}\circ \I_R (\Th).\]
    For the last case, comparing $\I_R\circ H_{(i,\e)}(\Th)$ and $H_{(i,\e)}\circ \I_R(\Th)$ we see that the latter contains an extra turn-back at level $\sigma(i+\e)$, belonging to the added component $O_{(i,\e)}(\Gamma_R)$. Removing this turn-back using the isotopy equivalence gives $\I_R\circ H_{(i,\e)}(\Th)\isosim H_{(i,\e)}\circ \I_R(\Th)$ (\textit{c.f.} Figure \ref{fig:Irdes}).

    For (3), letting $G(\Th'_L)=o'_L(G(\Th'))\cup \Gamma_L$ and likewise for $\Th_R$, we have 
    \begin{align*}G(\Th_L,\Th_L') &= (o_L(G(\Th))^{(1)} \cup o'_L(G(\Th))^{(2)}) \sqcup(\Gamma_L^{(1)} \cup {\Gamma'_L}^{(2)}),\\
    G(\Th_R,\Th_R') &= (o_R(G(\Th))^{(1)} \cup o'_R(G(\Th))^{(2)}) \sqcup(\Gamma_R^{(1)} \cup {\Gamma'_R}^{(2)}).\end{align*}
Observe that the subgraphs $\Gamma_L^{(1)} \cup {\Gamma'_L}^{(2)}$ and $\Gamma_R^{(1)} \cup {\Gamma'_R}^{(2)}$ are lines which join the left-most (right-most) southern and northern vertices in the composite graphs, respectively. After contracting the above graphs on vertices $U_{F_L,F_L'}$ and $U_{F_R,F_R'}$, and applying the OP maps $o_{F_L,F_L'}$ and $o_{F_R,F_R'}$, respectively, one obtains $\I_L(\Th)=\Th'_L \# \Th_L$ and $\I_R(\Th)=\Th'_R \# \Th_R$ by using Lemma \ref{grp1}. Futhermore, it is clear from the above that $[U_{F_L,F_L'}:G(\Th_L,\Th'_L)]=[U_{F,F'}:G(\Th, \Th')]=[U_{F_R,F_R'}:G(\Th_R,\Th'_R)]$. Part (4) follows immediately using the construction in \ref{LRadd} and the fact that $\omega_{F}(\max((V_F)_i))=\min((V_{F^*})_{\overline{\omega_N}(i)})$ for any frame $F$ and relevant integer $i$.\end{proof}

