\mdef\label{setup} Suppose that $\Th=(F, E)$ is a SWB-datum without turn-backs and without internal components, and that $F=(P,s,f)$ where $(P,s)=(P_2,s_2)\#_d (P_1,s_1)$ for $(P_i,s_i)\in \mathcal{TC}_{N_i}$ and $d<2N_2$. Let $p=\{d+1, c\}\in P_2$ be the unique part containing $d+1$, and write $o_d(p)=:\{D+1,C\}$, where $D=o_d(d+1)=d+2N_1+1$. Then let $F_2=(P_2,f_2,s_2)$, $F_1=(P_1,s_1,f_1)$, be frames, $\Th=(F_1,E_1)\in Sq(n,m)$ a SWB-datum without fully external components, and $o:V_{F_1}\to V_{F}$ an OP map according to \ref{insSWB}, such that, $\Th=(F_2\#_d F_1, o(E_1)\sqcup \overline{E} )$.

Define the following vertex subsets of $V_F$ 
\begin{align*}
    U&:=o((V_{F_1})_{\sth}),& V&:=o(V_{F_1})\cap (V_F)_{D+1}\\
    U''&:= \{u\in (V_F)_{<C} \ | \ u\edge \iota_F(v)\in E \text{ for } v\in V  \}, & U'&:=o(V_{F_1})\cap (V_F)_{>D+1}, \\
    U'''&:= \{u\in (V_F)_{>C} \ | \ u\edge \iota_F(v) \in E \text{ for } v\in V \}, & W&:=V \cup \iota_F(V) ,
\end{align*}
and write $|U'|=m_1$, $|U''|=m_2$, $|U'''|=m_3$, hence $m=m_1+m_2+m_3$, and $|U|=n$. The condition that $\Th$ is without turnbacks implies that $V$ is the set of the least $m_2+m_3$ elements of $(V_F)_{D+1}$. See Figure \ref{fig:setup} for a diagram of this notation.
\begin{figure}[ht]
    \centering
\[\lemoneintA{1} \qquad \qquad \lemtwintA{0.9375}\]
    \caption{Diagram for the notation in \ref{setup}, with the case $s(p)=0$ on the left and $s(p)=1$ on the right.}
    \label{fig:setup}
\end{figure}


\begin{lemma}\label{lem1} Let $\Th=(F, E)=(F_2\#_d F_1, o(E_1)\sqcup \overline{E} )$ be as per \ref{setup} and suppose that $s(p)=0$. Then 
\[\Th\hssim (F', E' ):= (F_2'\#_c F_1', o'(E_1')\sqcup  o''(\overline{E}\smallsetminus [\overline{E}\cap W] )\sqcup \overline{E}'), \]
where $(F_1',E_1')=\mathit{Sf}^{m_1+m_2}(\Th_1) \in Sq(n+m_1+m_2,m_3)$ and $F_2'=(P_2,s_2,f_2')$ with $f_2'(p)=f_2(p)+n+m_1-m_2-m_3$, and otherwise $f_2'(q)=f_2(q)$ for $q\neq p \in \overline{P_2}$.

    Here $o''$ is the unique OP map $V_F\smallsetminus (W\cup o((V_{F_1})_\int) )\to V_{F'}\smallsetminus (W'\cup o'((V_{F_1'})_\int))$, where $W'=V'\cup \iota_{F'}(V')$ for $V'$ the set of the $n+m_1$ greatest elements of $(V_{F'})_c$, and $o':V_{F_1'}\to V_{F'} $ is the unique OP map such that $o'(i,a)=(i+c,a)$ for $(i,a)\in (V_{F_1'})_{\int}$ and $o'((V_{F_1'})_{\ext})=V'\cup o''(U''\cup U''')$. $\overline{E}'$ is the unique pairing of $\iota_{F'}(V')\cup o''(U\cup U')$ without turnbacks. 
\end{lemma}

\begin{proof} Let $\mathit{Ev}_{[d+1,D]}:Sq_N\to Sq_N$ be the sequence of handle slides obtained from the upward evacuation of sites $d+1$ to $D$, sequence of chord slides, $\mathit{ev}_{[d+1,D]}:\mathcal{TC}_N\to \mathcal{TC}_N$ (\textit{c.f.} \ref{def:evac}), by replacing each chord slide $h_{(i,\e)}$ with the corresponding handle slide $H_{(i,\e)}$. Set $\Th'':=(F'',E''):=\mathit{Ev}_{[d+1,D]}(\Th)$ with $F''=(P'',s'',f'')$. By Lemma \ref{moveslem}, it follows that $(P'',s'')=\mathit{ev}_{[d+1,D]}(P,s)=(P_2,s_2)\#_c (P_1,s_1)$ hence we can write $F''=F_2''\#_c F_1''$, with $F_2''=(P_2,s_2,f_2'')$ and $F_1''=(P_1, s_1,f_1'')$. Furthermore, $f_2''(q)$ differs from $f_2(q)$ only when $q=p \in \overline{P_2}$, in which case $f_2''(p)=f_2(p)+2 C(F_1)$. 

Let $\tau \in \mathfrak{S}_{2N}$ be the resultant permutation from applying $\mathit{ev}_{[d+1,D]}$ (\textit{i.e.} $P''=\tau(P)$), let $\tau(v)$ for any $v=(i,a)\in (V_F)_\int$ denote $(\tau(i),a)\in V_{F''}$, and let $o_H:V_F\to V_{F''}$ be the OP map which is the composite of the OP maps $o_{(i,\e)}$ (\textit{c.f.} \ref{hsvset}) for each handle slide in $\mathit{Ev}_{[d+1,D]}$. Note that $V_{F''}\smallsetminus o_{H}(V_F)=\iota_{F''}\circ o_{H}\circ o((V_{F_1})_{\int}) \cup \tau\circ o((V_{F_1})_\int)$. Let $\tau':V_{F_1}\to V_{F''}$ be the map given by 
\[
\tau'(v)=\begin{cases}\tau\circ o(v), & v\in (V_{F_1})_\int,\\
\begin{matrix} o_{H}(u) \text{ for the unique $u\neq o(v)$ s.t. }\\ u\edge \iota_{F}\circ o(v)\edge o(v) \subset G(\Th)\end{matrix} , & v \in  o^{-1}\left((V_{F})_{D+1}\right),\\ 
o_{H}\circ o(u), & \text{otherwise.}    
\end{cases}
\]
For each part $e=\{u,v\}\in E_1$ such that $e\subset (V_{F_1})_{\int}\cup o^{-1}\left((V_{F})_{D+1}\right)$, we have that $o_H\circ o(e):=\{u'',v''\}\in E''$ is a turnback in $\Th''$ and $G(\Th'')$ contains the (full) subgraph
\[P_{e}:=\left(\tau'(u)\edge \iota_{F''}(u'')\edge u'' \edge v'' \edge \iota_{F''}(v'')\edge\tau'(v)\right). \]
Since $\Th$ was without turnbacks, these are the only turnbacks in $\Th''$. For any $u \in V_{F_1}\smallsetminus \left[(V_{F_1})_{\int}\cup o^{-1}\left((V_{F})_{D+1}\right)\right]$, there is a part
$e=\{u,v_u\}\in E_1$ for $v_u\in (V_{F_1})_\int$. Letting $o_H\circ o(e):=\{u'',(v_u)''\}\in E''$ again, we have that $G(\Th'')$ contains the (full) subgraph
\[ Q_{u}:=\left(u''=\tau'(u)\edge (v_u)''\edge \iota_{F''}((v_u)'')\edge \tau'(v_u)\right).  \]
\begin{figure}[ht]
    \centering
    \[\lemoneA{1}\quad \xmapstoo{\mathit{Ev}_{[d+1,D]}}\quad \lemoneBB{0.88235294117}  \]
    \caption{Local diagram for $\mathit{Ev}_{[d+1,D]}(\Th)$.}
    \label{fig:localEV}
\end{figure}
Let $\tilde{\Th}=(\tilde{F},\tilde{E})$ be the unique isotopy reduced representative of $\Th''$. We then claim that $\tilde{\Th}=(F',E')$. By counting the number of turn-backs removed by pull-throughs one finds that $\tilde{F}=F'$ as desired. Now let $U_{F_1}=\{v \in (V_{F_1})_\int\cup o^{-1}\left( (V_F)_{D+1} \right) \ | \ \{u,v\}\in E_1 \text{ for } u \in (V_{F_1})_\int\cup o^{-1}\left( (V_F)_{D+1} \right) \}$ so that 
\[G(\tilde{\Th})\simeq_O G(\Th'')/\left[o_H\circ o(U_{F_1})\cup \iota_{F''}\circ o_H\circ o(U_{F_1})\right].   \]
The result of this contraction is simply to replace all paths $P_e$ with $\tau'(e)$. After applying the unique OP map, say $o_P$, between the vertex sets of the above graphs (right to left), we have that
\begin{align*}
    o'(E_1')&=o_P\left(\{ \tau'(e) \ | \ e \subset U_{F_1}\} \cup \{\iota_{F''}((v_u)'')\edge \tau'(v_u) \ | \ u \in V_{F_1}\smallsetminus \left[(V_{F_1})_{\int}\cup o^{-1}\left((V_{F})_{D+1}\right)\right] \}\right),\\
    \overline{E}'&= o_P\left(\{\tau'(u) \edge (v_u)'' \ | \ u \in V_{F_1}\smallsetminus \left[(V_{F_1})_{\int}\cup o^{-1}\left((V_{F})_{D+1}\right)\right]  \}\right).
\end{align*}
which combined with the fact that $o_P\circ o_H$ agrees with $o''$ when restricted to the appropriate domain, now gives $\tilde{\Th}=(F',E')$ as desired. Thus $\Th\hssim \tilde{\Th}=(F',E')$.\end{proof}

