\begin{lemma}\label{lem2} Let $\Th=(F, E)=(F_2\#_d F_1, o(E_1)\sqcup \overline{E} )$ be as per \ref{setup} and suppose that $s(p)=1$. Then 
\[\Th\hssim (F', E' ):= (F_2'\#_{c-1} F_1', o'(E_1')\sqcup  o''(\overline{E}\smallsetminus (\overline{E}\cap W) )\sqcup \overline{E}'), \]
where $(F_1',E_1')=(\mathit{Sf}^{m_2+m_3}(\Th_1))^* \in Sq(m_2,n+m_1+m_3)$ and $F_2'=(P_2,s_2,f_2')$ with $f_2'(p)=f_2(p)+n+m_1-m_2-m_3$, and otherwise $f_2'(q)=f_2(q)$ for $q\neq p \in P_2$. 

    Here $o''$ is the unique OP map $V_F\smallsetminus (W\cup o((V_{F_1})_\int) )\to V_{F'}\smallsetminus (W'\cup o'((V_{F_1'})_\int))$, where $W'=V'\cup \iota_{F'}(V')$ for $V'$ the set of the $n+m_1$ least elements of $(V_{F'})_{c+2N_1}$, and $o':V_{F_1'}\to V_{F'} $ is the unique OP map such that $o'(i,a)=(i+c-1,a)$ for $(i,a)\in (V_{F_1'})_{\int}$, and $o'((V_{F_1'})_{\ext})=V'\cup o''(U''\cup U''')$. $\overline{E}'$ is the unique pairing of $\iota_{F'}(V')\cup o''(U\cup U')$ without turnbacks. 
\end{lemma}
\begin{proof} The proof proceeds the same as for \ref{lem1}, \textit{i.e.} $\textit{Ev}_{[d+1,D]}(\Th):=(F'',E'')\isosim (F',E')$. The key differences here are that $\textit{ev}_{[d+1,D]}(P,s)=(P_2,s_2)\#_{c-1}[\omega_{N_1}(P_1,s_1)]$ (\textit{c.f.} Lemma \ref{moveslem}), and that the map $\tau':V_{F_1}\to V_{F''}$ used in defining the paths $P_e$ and $Q_u$ becomes the map
\[
\tau'(v)=\begin{cases}\omega_{F_1}(v)+(c-1,0), & v\in (V_{F_1})_\int,\\
\begin{matrix} o_{H}(u) \text{ for the unique $u\neq o(v)$ s.t. }\\ u\edge \iota_{F}\circ o(v)\edge o(v) \subset G(\Th)\end{matrix} , & v \in  o^{-1}\left((V_{F})_{D+1}\right),\\ 
o_{H}\circ o(u), & \text{otherwise.}    
\end{cases}\qedhere\]\end{proof}

