\begin{lemma}\label{lem3} Let $\Th=(F, E)=(F_2\#_d F_1, o(E_1)\sqcup \overline{E} )$ be as per \ref{setup}, and suppose that $m_2=m_3=0$, and that $f(p)=l+k$, where $l=|X|, k=|X'|$, for vertex subsets 
\begin{align*}
    X&:=\{v \in (V_F)_{<D} \ | \ v\edge u \in E \text{ for } u \in (V_F)_{D+1}\},\\
    X'&:=\{v \in (V_F)_{>D} \ | \ v\edge u\in E \text{ for } u \in (V_F)_{D+1}\},
\end{align*}
(note that one of $k$ and $m$ must be 0). Then
\[\Th\hssim (F',E'):=(F_2\#_{d+1} F_1',o'(E_1')\sqcup o''(\overline{E}\smallsetminus[\overline{E}\cap (V_F)_{D+1}])  ),\]
where $(F_1',E_1')=\mathit{Sf}^{k}(\I_R^{l+k}(\Th_1))$, $o'':V_F\smallsetminus(o((V_{F_1})_{\int})\cup (V_F)_{D+1})\to V_{F'}\smallsetminus(o'((V_{F_1'})_{\int})\cup (V_{F})_d)$ is the unique OP map, and $o':V_{F_1'}\to V_{F'}$ is the OP map uniquely defined by $o'(i,a)=(i+d+1,a)$ for $(i,a)\in (V_{F_1})_{\int}$, and $o'((V_{F_1'})_{\ext})=o''(X\cup U \cup X' \cup U')\cup (V_{F'})_{d+1}$.
\end{lemma}


