\section{Square with Bands Category} In this section we define the square with bands (SWB) category, $\SQ$, using SWB data from \S3. This category will be a linear (small) category, which contains the Temperley-Lieb category as a subcategory. Using \S3.5, we equip $\SQ$ with a monoidal structure (and indeed a pivotal structure), and provide a monoidal generating set for $\SQ(n,m)$.\\

In what follows, let $\K$ be a commutative, unital, ring, and fix $\a,\b,\gamma\in \K$.

\mdef\label{homset} For $n,m\in \N$, let $A(n,m), B(n,m), C(n,m)$ denote the following $\K$-submodules of $\K Sq^{\hs}(n,m)$:
\begin{align*}
A(n,m)&=\K \left\{ [\Th]_{\hs}-\a [\Th\smallsetminus \Gamma ]_{\hs} \ \Big| \  \begin{array}{c}\Th\in Sq(n,m), \text{ and } \Gamma \in \CC(G(\Th)) \text{ an internal,} \\ \text{separating component.} \end{array}\right\}, \\
B(n,m)&=\K \left\{ [\Th]_{\hs}-\b [\Th\smallsetminus \Gamma ]_{\hs} \ \Big| \   \begin{array}{c}\Th\in Sq(n,m), \text{ and } \Gamma \in \CC(G(\Th)) \text{ an internal,}\\ \text{twisted component.}\end{array} \right\},\\
C(n,m)&=\K \left\{ [\Th]_{\hs}-\gamma [\Th\smallsetminus \Gamma ]_{\hs} \ \Big| \  \begin{array}{c} \Th \in Sq(n,m), \text{ and } \Gamma \in \CC(G(\Th)) \text{ an internal,}\\
\text{non-separating, untwisted component.}\end{array} \right\}.
\end{align*}

\begin{theorem}[Square with Bands Category]\label{SWBcat} $\SQ=\SQ(\a,\b,\gamma)$, is a small $\K$-linear category with the following data:
\begin{itemize} 
\item[] \underline{Objects:} $\SQ$ has object set $\SQ:=\N$.
\item[] \underline{Morphisms:} For $n,m\in \SQ$, $\SQ(n,m)$ is the $\K$-module of morphisms given by
\begin{equation*}\SQ(n,m):= \K Sq^{\hs}(n,m)/(A(n,m) + B(n,m) + C(n,m) ). \end{equation*}
For $\Th\in Sq(n,m)$, write $\overline{\Th}$ for the image of $[\Th]_\hs\in \K Sq^{\hs}(n,m)$ under this quotient.
\item[] \underline{Composition:} For $n,m, l \in \SQ$, composition $\circ: \SQ(n,m) \times \SQ(m,l)\to \SQ(n,l)$ is given by linearly extending the formula 
\begin{equation*} (\overline{\Th_1},\overline{\Th_2})\mapsto \overline{\Th_2} \circ \overline{\Th_1} := \a^{L_{\Th_1,\Th_2}} \, \overline{\Th_2 \# \Th_1}, \end{equation*}
for $\Th_1 \in Sq(n,m), \Th_2 \in Sq(m,l)$, where $\Th_2\# \Th_1$ denotes the vertical juxtaposition, and $L_{\Th_1, \Th_2}$ the linking number (\textit{c.f.} \S3.2).
\end{itemize}
Furthermore, $\SQ$ has a contravariant duality $(\_)^*:\SQ\to \SQ$ defined on objects by $n^*=n$, and on morphisms by $\overline{\Th}^*=\overline{\Th^*}$, for $\Th$ an SWB datum, and by extending $\K$-linearly.
\end{theorem}

We refer to $\SQ$ as the square with bands (SWB) category. We refer to morphisms of the form $\overline{\Th}\in \SQ(n,m)$, for $\Th\in Sq(n,m)$ as homogeneous morphisms.  

\begin{remark} We can define two wide subcategories of $\SQ$, $\SQ_0\subset \SQ^+ \subset \SQ$, as the wide subcategories with the following $\K$-modules of morphisms:
    \begin{align*}
        \SQ^+(n,m)=\K \{ \overline{\Th}\in \SQ(n,m) \ | \ \Th \in Sq^+(n,m)  \},\\
        \SQ_0(n,m)=\K \{ \overline{\Th} \in \SQ(n,m) \ | \ \Th \in Sq_0(n,m) \}. 
    \end{align*}
    Diagrammatically, morphisms in $\SQ^+$ are $\K$-linear combinations of (classes of) SWB diagrams on orientable surfaces, and morphisms in $\SQ_0$ are $\K$-linear combinations of SWB diagrams in the square, \textit{i.e.} Temperley-Lieb diagrams. Since no orientable surface contains twisted curves we have that $\SQ^+=\SQ^+(\a,\gamma)$ (\textit{i.e.} $\SQ^+$ is only defined by these two parameters) and similarly, since the square only contains separating curves, $\SQ_0=\SQ_0(\a)$. Furthermore, one can identify $\SQ_0(\a)$ with the Temperley-Lieb category at loop parameter $\alpha$, see  \cite{TemperleyLieb, JonesIndex}.   

    In addition, define the following submodules of $\SQ(n,m)$:
    \begin{align*}
        \SQ_{\tor}(n,m)=\K \{ \overline{\Th}\in \SQ(n,m) \ | \ \Th \in Sq_{\tor}(n,m)  \}, \\
        \SQ_{\mob}(n,m)=\K \{ \overline{\Th} \in \SQ(n,m) \ | \ \Th \in Sq_{\mob}(n,m) \}. 
    \end{align*}
    It follows from Cor. \ref{hscor} that any homogeneous morphism, can be factored into homogeneous morphisms coming from $\SQ_0$, $\SQ_{\tor}$, and $\SQ_{\mob}$, with at most two factors from the latter.   
\end{remark}

\begin{prop} Let $\Th\in Sq(n,m)$, and consider the homogeneous morphism $\overline{\Th}\in \SQ(n,m)$. There exist unique non-negative integers $a,b,c \in \N$, and a SWB datum $\Th'\in Sq(n,m)$ without internal components, such that $\overline{\Th}=\a^a \, \b^b \, \gamma^c \ \overline{\Th'}$.
\end{prop}

\begin{theorem} There is a tensor product $(\_)\otimes(\_):\SQ\times \SQ \to \SQ$, defined on objects by $n_1\otimes n_2=n_1+n_2$ and uniquely defined on morphisms by the formulae:
\begin{equation*} \id_l\otimes \overline{\Th}=\overline{(\I_L)^l(\Th)}, \qquad \overline{\Th}\otimes \id_l=\overline{(\I_R)^l(\Th)},
\end{equation*}
for $\Th\in Sq(n,m)$, where $\I_L$ and $\I_R$ are as per \ref{Ilr}. In addition, $\SQ$ can be made into a rigid monoidal category with self-dual objects $n^\dagger=n$, and evaluation and coevaluation maps given by:
\begin{equation*}
    \mathit{ev}_n = \overline{\mathbb{V}_n} \in \SQ(2n,0), \qquad   \mathit{coev}_n = \overline{\mathbb{U}_n} \in \SQ(0,2n),\end{equation*}
Let $(\_)^\dagger: \SQ \to \SQ$ denote the associated contravariant functor (not to be confused with $(\_)^*$ from Theorem \ref{SWBcat}). Furthermore, we have the following identities 
$((\_)^\dagger)^\dagger=\text{id}:\SQ \to \SQ$ and $((\_)^\dagger)^*=((\_)^*)^\dagger:\SQ \to \SQ$.
\end{theorem}

\begin{remark} The restriction of the tensor product $\otimes$ to the subcategory $\SQ_0$ coincides with the usual ``horizontal juxtaposition" tensor product in the Temperley-Lieb category. The composition of contravariant functors $(\_)^\dagger$ and $(\_)^*$ results in a covariant endofunctor $R:=((\_)^{\dagger})^*:\SQ\to \SQ$. Since both contravariant functors are involutive and commute, it follows that $R^2=\text{id}$, and since $(\_)^\dagger$ is tensor product reversing, while $(\_)^*$ is tensor product preserving, it follows that $R$ is tensor product reversing. The restriction of $R$ to $\SQ_0$ is simply the functor, defined on TL-diagrams by horizontal reflection (\textit{i.e.} reflection across a vertical).   \end{remark}

\begin{remark} Since $(\_)^\dagger$ is involutive, $\SQ$ has a trivial pivotal structure $\text{id}:\text{id}\Rightarrow ((\_)^\dagger)^\dagger$.    
\end{remark}

\begin{prop}  $\SQ$ is monoidally generated by the homogeneous morphisms $\id_0$, $\id_1$, $\overline{\mathbb{U}}$, $\overline{\mathbb{V}}$, $\overline{\TT_{l,m}}$, and $\overline{\MM_n}$, for $l,m,n\in \N$. Furthermore, the morphisms $\overline{\TT_{l,m}}\in \SQ(l+m,l+m)$ are the components of a natural transformation $\overline{\TT}:(\_)\otimes(\_) \Rightarrow (\_)\otimes^{\text{op.}}(\_)$, and the morphisms $\overline{\MM}_n\in \SQ(n,n)$ are the components of a natural transformation $\overline{\MM}:\text{id} \Rightarrow R$.
\end{prop}

\begin{remark} Note that the morphisms $\overline{\TT_{l,m}}$ are not invertible in $\SQ$, so $\overline{\TT}$ does not make $\SQ$ into a braided monoidal category. These morphisms do, however, satisfy the Yang-Baxter equation, \textit{i.e.} for $l,m,n\in \N$ we have
\begin{equation*}
(\id_n\otimes \overline{\TT_{l,m}})\circ (\overline{\TT_{l,n}}\otimes \id_m) \circ (\id_l\otimes \overline{\TT_{m,n}})=
    (\overline{\TT_{m,n}}\otimes \id_{l})\circ (\id_{m}\otimes \overline{\TT_{l,n}}) \circ (\overline{\TT_{l,m}}\otimes \id_{n}).\end{equation*}
There are also mixed relations between the $\TT_{l,m}$ and $\MM_n$, for example, for $l,m\in \N$ we have
\begin{equation*}
    (\id_m\otimes \overline{\MM_l})\circ 
    \overline{\MM_{l+m}} \circ 
    (\id_l\otimes \overline{\MM_m})=(\id_m\otimes \overline{\MM_0})\circ (\overline{\TT_{l,m}}).
\end{equation*}

\end{remark}

