    \centering
        \includegraphics[scale=0.2, trim={0.5cm 0.5cm 0.5cm 0.5cm}, clip]{figures/block/iot_major_update_wcd_four.pdf}
        \caption{Worst-Case Queuing Delay for \texttt{QG}1, \texttt{QG}2, and \texttt{QG}3 in Multi-CQF. In \texttt{QG}1, one queue transmits (S) while two receive (R). In the worst case, flows in \texttt{QG}1 are stored in the \emph{tolerating queue} at each switch, causing an extra cycle of delay before transmission. In contrast, flows in \texttt{QG}2 and \texttt{QG}3 are forwarded in the next cycle.}
    \label{fig:mcqf_all_qg_wcd}
    \vspace{-0.3cm}
