\title{Feature Geometry for Stereo Sidescan and Forward-looking Sonar}

% author names and affiliations
% use a multiple column layout for up to three different
% affiliations
\author{Kalin~Norman and Joshua~G.~Mangelson%
    \thanks{This work was funded under Department of Navy awards N00014-21-1-2435 and N00014-21-1-2260 issued by the Office of Naval Research.}
