\begin{tikzpicture}
    % Axes
    \draw[->] (-3,0) -- (3,0); % x-axis
    \draw[->] (0,-2) -- (0,2); % y-axis

    % Dashed horizontal lines
    \draw[dashed] (-3,1) -- (3,1) node[right] {\small $\beta(t)$};
    \draw[dashed] (-3,-1) -- (3,-1) node[right] {\small $\alpha(t)$};

    % Clipped smooth curve
    \draw[thick, domain=-3:3, smooth, samples=100] 
        plot (\x, {max(-1, min(1.5*exp(-0.3*\x*\x)*sin(180*\x/2), 1))});

    % Function label
    \node[right] at (2,0.5) {\small $\Tilde{h}(t)$};

\end{tikzpicture}
\end{center}
\end{figure}

Observe that, \(\tilde{h}\) is continuous at \(x=\alpha(t)\) and \(x=\beta(t)\). Indeed,
\begin{align*}
    &\lim_{x\to\beta(t)}\tilde{h}(t,\ \beta(t),\ \beta(t)-\sigma(t,\ z))
    -\frac{x-\beta(t)}{x-\beta(t)+1}=h(t,\ x,\ x-\sigma(t,\ z))\\
    &\text{and}\\
    &\lim_{x\to\alpha(t)}\tilde{h}(t,\ \alpha(t),\ \alpha(t)-\sigma(t,\ z))
    +\frac{\alpha(t)-x}{\alpha(t)-x+1}=h(t,\ x,\ x-\sigma(t,\ z))\text{.}
\end{align*}
Therefore, we can conclude that, $\tilde{h}(t)$ is continuous in the discrete time scale \(\mathbb{T}^0=[1,\ T+1]\). Now, since $\mathbb{T}^0$ is closed and bounded, hence, we can apply extreme value theorem on $\tilde{h}$ to conclude that, $\tilde{h}$ attains its extrema in $\mathbb{T}^0$, i.e. there exists an \(M>0\) such that 
\begin{equation}
    \label{extreme_value}
    \left|\tilde{h}(t,\ x,\ y)\right|\leq M\text{ for }t\in[1,\ T+1],\ (x,\ y)\in\mathbb{R}\text{.}
\end{equation}

Finally, we define the following auxiliary problem corresponding to \eqref{Problem} using the function $\tilde{h}$ as described above:
\begin{equation}
    \label{regular_problem}
    \begin{cases}
        u^{\Delta\Delta}(t-1)+\tilde{h}(t,\ u(t),\ u^{\Delta}(t-1))=0\\
        u^{\Delta}(0)=0\\
        u(T+2)=g(T+2)
    \end{cases}
\end{equation}

\begin{rem}
The solution $u(t);~\alpha(t) \le u(t) \le \beta(t)$ to the auxiliary problem \eqref{regular_problem} is equivalent to the solution $u(t)$ of the given problem \eqref{Problem}, since $\tilde{h}\equiv h$ when $\alpha (t) \le t \le \beta (t)$.
\end{rem}

\subsection*{Step 2: Construction of solution operator}

In this step, we define the corresponding solution operator for the auxiliary problem \eqref{regular_problem} such that a fixed point of the solution operator turns out to be a solution of \eqref{regular_problem}. To define the solution operator, first we define the underlying function space and the appropriate norm as follows:

\begin{defi}
 Define the space \(E := \{u\colon[0,\ T+2]\to\mathbb{R},\ u^{\Delta}(0)=0,\ u(T+2)=cg(T+2)\}\) with the associated distance function \[\|u\|:=\max\{u(t)\colon t\in[1,\ T+1]\}\] where $c$ is an arbitrary positive constant.  
\end{defi}

\begin{lemma}
$\langle E, \|u\|\rangle$ is a Banach space.
\end{lemma}

\begin{proof}
{\bf Criterion 1: Show that $E$ is a linear space.}
This follows from the fact that $u \in E$ is a real-valued function and the forward difference operator $\Delta$ is linear.

{\bf Criterion 2: Show that $\|\cdot\|$ defined above is a norm.} Note that since $g$ is a positive function and $c$ is an arbitrary constant, $u(T+2) >0$.  Therefore, $\|u\| \ge 0$, for any $u \in E $ and $\|u\|=0$ if and only if $u \equiv 0$. Triangle inequality follows from the fact that maximum of sum of two functions is less than the sum of the maximums of the functions.

{\bf Criterion 3: To show $\langle E, \|u\|\rangle$ is complete.}
Observe that, $u \in E$ is a real-valued function and the completeness of $\mathbb{R}$ implies the completeness of $E$. 
Hence we can conclude that $\langle E, \|u\|\rangle$ is a Banach space.
\end{proof}

Now, we define the solution operator \(\mathcal{T}\colon E\to E\) by
\begin{equation}
    \label{t_operator}
    (\mathcal{T}u)(t)=cg(T+2)+\sum_{s=t}^{T+1}\left(\sum_{i=1}^s
    \tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\right),\ t\in[0,\ T+2]
\end{equation}

\subsection*{Step 3: Application of Brouwer's Fixed Point Theorem}

Continuity of $g$ and $\tilde{h}$ implies the continuity of the operator \(\mathcal{T}\). Moreover, continuity of $g$ over a closed set, \eqref{extreme_value} and \eqref{t_operator} imply that if
\[r\geq\sum_{s=1}^{T+1}sM\]
Then \(\mathcal{T}(\overline{B(r)})\subseteq\overline{B(r)}\), where
\(B(r)=\{u\in E\colon\|u\|<r\}\).
Therefore, by the Brouwer Fixed Point Theorem, \(\exists u\in\overline{B(r)}\) such that \(u=\mathcal{T}u\).

\subsection*{Step 4: \(u\) is a fixed point of \(\mathcal{T}\) iff \(u\) is a solution of \eqref{regular_problem}}

\subsubsection*{Forward Direction \((\Rightarrow)\)} 

Let us assume \(u=\mathcal{T}u\). Without loss of generality, we can assume $c=1$. Since $\mathcal{T}: E \to E$, hence \(u\in E\) and thus, satisfies the boundary conditions in \eqref{regular_problem}. 
Moreover,  for  $t\in[1,\ T+1]$, we have,
\begin{align*}
    u^{\Delta}(t-1) &= u(t)-u(t-1)\\
                  &= g(T+2)+\sum_{s=t}^{T+1}\sum_{i=1}^s\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\\
                  &\quad \quad -\left(g(T+2)+\sum_{s=t-1}^{T+1}\sum_{i=1}^s\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\right)\\
                  &= -\sum_{i=1}^{t-1}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\\
   \Rightarrow u^{\Delta \Delta}(t-1) &= u^{\Delta}(t)-u^{\Delta}(t-1)\\
                        &=-\tilde{h}(t,\ u(t),\ u^{\Delta}(t-1)).
\end{align*}
Therefore, we can conclude that $u$ is a solution of \eqref{regular_problem} if $u$ is a fixed point of the operator $\mathcal{T}$.

\subsubsection*{Backward Direction \((\Leftarrow)\)}

Next, let us assume \(u\) solves \eqref{regular_problem} with $c=1$. Then \(u\in E\) and \[ u^{\Delta \Delta}(t)=-\tilde{h}(t,\ u(t),\ u^{\Delta}(t-1)).\] We will show $u(t)= (\mathcal{T}u)(t)$, for $t \in [1, T+1]$. First, continuing via mathematical induction,  we can see, \begin{equation}
    \label{delta_u}
    u^{\Delta}(t)=-\sum_{i=1}^t\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))
\end{equation}

Indeed, for \(t=1\),
\begin{align*}
    u^{\Delta\Delta}(0) &= u^{\Delta}(1)-u^{\Delta}(0)\\
    -\tilde{h}(1,\ u(1),\ u^{\Delta}(0)) &= u^{\Delta}(1)-0\\
    u^{\Delta}(1) &= -\tilde{h}(1,\ u(1),\ u^{\Delta}(0));
\end{align*}
for $t =2$,
\begin{align*}
    u^{\Delta\Delta}(1) &= u^{\Delta}(2)-u^{\Delta}(1)\\
    \Rightarrow-\tilde{h}(1,\ u(1),\ u^{\Delta}(0)) &= u^{\Delta}(2)+\tilde{h}(1,\ u(1),\ u^{\Delta}(0))\\
    \Rightarrow u^{\Delta}(2) &= -(\tilde{h}(1,\ u(1),\ u^{\Delta}(0))+\tilde{h}(2,\ u(2),\ u^{\Delta}(1))); 
\end{align*}
for $t=3$,
\begin{align*}
    u^{\Delta\Delta}(2) &= u^{\Delta}(3)-u^{\Delta}(2)\\
    \Rightarrow -\tilde{h}(2,\ u(2),\ u^{\Delta}(1)) &= u^{\Delta}(3)
    +\tilde{h}(1,\ u(1),\ u^{\Delta}(0))+\tilde{h}(2,\ u(2),\ u^{\Delta}(1))\\
    \Rightarrow u^{\Delta}(3) &= -\left(\tilde{h}(1,\ u(1),\ u^{\Delta}(0))
    +\tilde{h}(2,\ u(2),\ u^{\Delta}(1))+\tilde{h}(3,\ u(3),\ u^{\Delta}(2))\right);
\end{align*} 
and so on.

Next, we again apply mathematical induction, starting backwards, to show, for $t=T+1$,
\begin{align*}
    u^{\Delta}(T+1) &= u(T+2)-u(T+1)\\
    \Rightarrow -\sum_{i=1}^{T+1}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1)) &= g(T+2)-u(T+1)\\
    \Rightarrow u(T+1) &= g(T+2)+\sum_{i=1}^{T+1}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1));
\end{align*}
for $t=T$,
\begin{align*}
    u^{\Delta}(T) &= u(T+1)-u(T)\\
    \Rightarrow -\sum_{i=1}^{T}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1)) &= g(T+2)
    +\left(\sum_{i=1}^{T+1}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\right)-u(T)\\
    \Rightarrow u(T) &= g(T+2)+\left(\sum_{i=1}^{T+1}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\right)\\
    & \quad \quad +\left(\sum_{i=1}^{T}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))\right)\\
         &= g(T+2)+\sum_{s=T}^{T+1}\sum_{i=1}^s\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1));
\end{align*}

and so on. Thus continuing on via induction and using the vacuous cases that \(\displaystyle\sum_i^0=0\) and
\(\displaystyle\sum_{T+2}^{T+1}=0\) we get,
\begin{equation}
    \label{u(t)}
    u(t)=g(T+2)+\sum_{s=t}^{T+1}\sum_{i=1}^{s}\tilde{h}(i,\ u(i),\ u^{\Delta}(i-1))
    \text{,\quad}t\in[0,\ T+2]
\end{equation}

\subsection*{Step 5:}

Finally, we show that, \(u\) satisfies
\[\alpha(t)\leq u(t)\leq\beta(t)\text{,\quad}t\in[0,\ T+2]\]
We will prove case \(u(t)\leq\beta(t)\) and the proof for the case $\alpha(t) \le u(t)$ can be done similarly.
Let us consider the function \(v(t)=u(t)-\beta(t)\). Let us assume that \(\max\{v(t)\colon t\in[0,\ T+2]\}=v(\ell)>0\). Boundary conditions described in \eqref{regular_problem} and \eqref{beta} imply that $\ell \notin \{0,T+2\}$. Therefore, \(\ell\in[1,\ T+1]\). Consequently, \(v(\ell+1)\leq v(\ell)\) and \(v(\ell)\geq v(\ell-1)\) which implies \(    v^{\Delta}(\ell)\leq 0\) and \(v^{\Delta}(\ell-1)\geq 0\).
Hence,
\begin{equation}
    \label{contradiction}
    v^{\Delta \Delta}(\ell-1)\leq 0 \Rightarrow u^{\Delta \Delta}(\ell-1)\leq\beta^{\Delta\Delta}(\ell-1).
\end{equation}

On the other hand, utilizing the definition of $\tilde{h}(t, x, x-z)$ for $t=\ell,~x=u(\ell),~z=u(\ell -1)$ and the fact \(h\) is non-increasing in its third variable (see {\bf (A2)}),
we obtain, 
\begin{align*}
    u^{\Delta\Delta}(\ell-1)-\beta^{\Delta\Delta}(\ell-1) &=
    -\tilde{h}(\ell,\ u(\ell),\ u^{\Delta}(\ell-1))-\beta^{\Delta\Delta}(\ell-1)\\
                                                     &= -h(\ell,\ \beta(\ell),\ \beta(\ell)-\sigma(\ell,\ u(\ell-1)))+\frac{v(\ell)}{v(\ell)+1}-\beta^{\Delta\Delta}(\ell-1)\\
                                                     &\geq -h(\ell,\ \beta(\ell),\ \beta^{\Delta}(\ell-1)+\frac{v(\ell)}{v(\ell)+1}-\beta^{\Delta\Delta}(\ell-1)\\
                                                     &\geq\frac{v(\ell)}{v(\ell)+1}\\
                                                     &> 0
\end{align*}
which contradicts \eqref{contradiction}. Therefore, \(u(t)\leq\beta(t)\) for \(t\in[0,\ T+2]\) and this completes the proof of Theorem \ref{Theorem}.

