	\section{Preliminaries}\label{Sec pre}
  In this section we collect some facts for later use.
	\subsection{The Dirichlet problem}\label{Sec 2.1}
 Let $f=(f^1,\cdots, f^m)$ be a smooth map from $E$ to $\R^m$ and $\Gamma(f)$ denote the graph of $f$. Then $\Gamma(f)$ is an $n$-dimensional  submanifold with respect to the product metric on $E\times\R^m$. Fix a local coordinate system $\{x_1,\cdots, x_n\}$ on $E$. Then $\{\F{\P}{\P x_i}+df(\frac{\P }{\P  x_i}),i=1,\cdots, n\}$ is a local frame on $\Gamma(f)$. Denote $\la \F{\P}{\P x_i}, \F{\P}{\P x_j}\ra_{\sigma_M}$ by $\sigma_{ij}$. Here $\sigma_M$ denotes the metric of $M$. Therefore the induced metric on $\Gamma(f)$ can be written as
\begin{equation}\label{coe:g}
	g_{ij}(f)=\sigma_{ij}+\sum_{A=1}^{m}\frac{\P f^A}{\P x_i}\frac{\P f^A}{\P x_j}, \, \text{and}\, (g^{ij}(f))=(g^{ij}(f))^{-1}.
\end{equation}
\bl\label{lm:gij}With the assumption as above, the matrix $(g_{ij})$ in \eqref{coe:g} satisfies
\begin{equation}
    (1+|Df|^2)(\sigma_{ij})\geq (g_{ij})\geq (\sigma_{ij}),\ \text{and}\  (\sigma^{ij})\geq (g^{ij})\geq  \frac{1}{1+|Df|^2}(\sigma^{ij}).
\end{equation}
Here $(\sigma^{ij})=(\sigma_{ij})^{-1}$ and $|Df|=\sup_{|\tau|=1}|Df(\tau)|$.
\el
The proof will be deferred to the frame described in \eqref{relation:A}.



  Let $\bar{\nabla }$ be the connection on $E$. The mean curvature vector $\vec{H}$ of $\Gamma(f)$ in $E\times\R^{m}$ can be computed as
\begin{equation}
\vec{H} =g^{ij}(f )(\bar{\nabla }_{\F{\P }{\P x_i}}\F{\P }{\P x_j}+\F{\P ^2f^A}{\P x_i \P x_j}\F{\P}{\P y^A})^{\bot},
\end{equation}
where $\{\F{\P }{\P y^1},\cdots, \F{\P}{\P y^m}\}$ is the orthonormal frame of $\R^m$ and $( \cdot)^\bot$ denotes the projection onto the normal bundle of $\Gamma(f)$. Set
\begin{equation}
	f_{ij}^A=\F{\P^2f^A}{\P x_i\P x_j}-(\bar{\nabla }_{\F{\P}{\P x_i}}\F{\P}{\P x_j})(f^A),\quad A=1,\cdots, m.
\end{equation}
%Notice that $\{v^A= -Df^A+\F{\P}{\P y^A}:A=1,\cdots, m\}$ is a frame of the normal bundle of $\Gamma(f)$.
Therefore, $\Gamma(f)$ is minimal (that is $\vec{H}\equiv 0$) in $E\times \R^m$ if and only if $g^{ij}(f)f_{ij}^A=0$ for each $A=1,\cdots, m$.

 Suppose $\psi=(\psi^{1},\ldots,\psi^{m}):\bar{E}\rightarrow \R^m $ is a smooth map on $\bar{E}=E\cup\partial E$. The Dirichlet problem for the minimal surface system (MSS) over $E$ is defined to seek the solution of
	the following quasi-linear system
	\begin{equation}\label{DP:MSSB}
		\left\{
		\begin{aligned}
			g^{ij}(f)f^A_{ij}&=0\quad A=1,2,\cdots,m\text{\quad on~} E,\\
			f &=\psi \text{\quad on~}\P E,
		\end{aligned}
		\right.
	\end{equation}
	where $(g^{ij}(f))$ is as in \eqref{coe:g}.


	 In the codimension one case ($m=1$), \eqref{DP:MSSB} is simplified into the Dirichlet problem of the minimal surface equation as
	\begin{equation}\label{DP:MSE}
		\left\{
		\begin{aligned}
			 div (\F{D f}{\sqrt{1+|D f|^2}})&=0 ~ \text{\quad on~} E,\\
			f &=\psi \text{\quad on~ }\P E,
		\end{aligned}
		\right.
	\end{equation}
	where $\psi:\bar{E}  \rightarrow \R$ is a continuous map, $f:\bar{E}\rightarrow\R$, and $div$ denotes the divergence of $E$.


	Recall that a smooth domain is \textit{convex} if the second fundamental form of its boundary is non-negative definite, and it is \textit{mean-convex} if the mean curvature of its boundary is non-negative. Some partial results on the Dirichlet problem \eqref{DP:MSE} are recorded as follows.

	\begin{theorem}\label{codimension:one}
	Suppose $E\subset\R^{n}$ is a smooth bounded domain. Then there exists a unique solution $u\in C^\infty(E)\cap C(\bar{E})$ to \eqref{DP:MSE} if one of the following conditions holds:
		\begin{enumerate}
			\item (Jenkins-Serrin \cite{Jenkins-Serrin1968}) the domain $E$ is mean-convex and $\psi$ is continuous;
			\item (Jenkins-Serrin \cite{Jenkins-Serrin1968}) $\psi\in C^2(\bar{E})$ satisfies $w(\psi)<\Sc$ and $\sup_{E}\{|D\psi|+|D^2\psi|\}<K$ for some constant $K>0$ and for some constant $\Sc =\Sc(n,K,E)>0$;
			\item (Williams \cite{Williams1984}) $\psi\in C^1(\bar{E})$ satisfies $ \sup_{\P E}|D\psi|<K$ for any constant $K\in (0, \F{1}{\sqrt{n-1}})$ and $w(\psi)<\Sc$  for some $\Sc=\Sc(n,K,E)>0$.
		\end{enumerate}
    Here $w(\psi)=\sup_{\bar{E} }\psi-\inf_{\bar{E}}\psi$.
 \end{theorem}
In the higher codimensional case ($m\geq 2$), the Dirichlet problem for the MSS \eqref{DP:MSSB} was resolved for both convex and mean-convex domains in Euclidean spaces, respectively, as follows.
\bt\label{codimension:higher} Let $E$ be a smooth compact domain in $\R^n$ with diameter $\eta$ and let $\psi:\bar{E}\rightarrow \R^m$ be a smooth map. Then the Dirichlet problem \eqref{DP:MSSB} for the MSS is solvable if one of the following two conditions holds:
\begin{enumerate}
    \item (Wang \cite{Wang2004}) $8n\eta\sup_{E}|D^2\psi|+\sqrt{2}\sup_{\P E}|D\psi|<1$ and $E$ is convex;
    \item (Ding-Jost-Xin %,Theorem 1.1 in
    \cite{Ding-Jost-Xin2023}) $\eta\sup_{E}|D^2\psi|+\sup_{E}|D\psi|<\epsilon_{0}$ and $E$ is mean-convex for some constant $\epsilon_{0}=\epsilon_{0}(n,m,\eta,\psi)>0$.
    \end{enumerate}
\et
\begin{remark} \label{remark:motivation} Comparing with  Theorem \ref{codimension:one} and Theorem \ref{codimension:higher}, it is natural to ask the following questions regarding \eqref{DP:MSSB}. Is the mean-convex  assumption essentially indispensable? How should we understand the role of the diameter of $E$ when solving \eqref{DP:MSSB}? These questions are the main motivations of this paper.
\end{remark}
	\subsection{Mean curvature flow}
	 Let $E\subset M$ be a smooth domain given in Section \ref{Sec 2.1}.
%Suppose $(M^{n},\sigma_{M})$ is a complete Riemannian manifold with  non-negative Ricci curvature and $E\subset M$ is a smooth compact domain with boundary $\partial E$.
For any smooth map $f:E\rightarrow \R^m$, its singular values $\lambda_1,\cdots, \lambda_n$ are the square root of the eigenvalues of the matrix $(df)_{x}^T(df)_{x}$, where $(df)_x:T_x E\rightarrow  \R^m$ is the differential map of $f$ at $x$.
\begin{definition}\label{def:strictly:decreasing}
We say that a smooth or {\Lp} map $f:E\rightarrow\mathbb{R}^{m}$ is (\textit{strictly}) \textit{length decreasing} if the singular values of $df$ satisfy  $\lambda_i\leq 1(<1-\Sc)$ for  $1\leq i\leq n$, and $f$ is \textit{(strictly) area decreasing} if $\lambda_i\lambda_j\leq1(<1-\Sc)$ for  $1\leq i\neq j\leq n$ whenever the differential $df$ is well-defined. Here $\Sc$ is a fixed positive constant in $(0,1)$.
\end{definition}
 It is easy to verify that this definition is independent of the choice of orthogonal frame near $x$ and $f(x)$.

 Next we define the mean curvature flow (MCF) according to \eqref{DP:MSSB} as in \cite{Wang2004}. Suppose $F_{t}(x)=F(x,t)$, where $F:\bar{E} \times [0,T)\rightarrow \bar{E} \times \R^m$, is a smooth parametric solution to the following mean curvature flow
	\begin{equation}\label{MCF}
	\left\{\begin{aligned}
	(	\frac{\partial F  }{\partial t})^{\perp}  &=H; \\
		F |_{\partial E}  &=Id_{E}\times \psi|_{\partial E} .
	\end{aligned}
	\right.
\end{equation}
Here $ Id_{E}$ is the identity map on $E$.
%	\begin{equation}\label{MCF}
	%	\left\{\begin{aligned}
	%		\frac{\partial   }{\partial t}F (x,t) &= \vec{H}, ~\mbox{on}~E\times[0, T) ; \\
%			F (x,t) &=x,~\mbox{on}~E;\\
%			F (x,t)&=(x,\psi(x)), ~\mbox{on}~\partial E\times[0,T) .
%		\end{aligned}
%		\right.
%	\end{equation}
Under a local coordinate system $\{x_{1},\ldots, x_{n}\}$ on $E$, the mean curvature flow $F(x_{1},\ldots, x_{n},t)=( F^{1},\ldots,F^{m})$ satisfies the following parabolic system:
	\begin{align}\label{MCF2}
		\frac{\partial F ^{A}}{\partial t}=\big(g^{ij}\frac{\partial ^2 F^{A}}{\partial x_{i}\partial x_{j}}\big)^{\perp},\  A=1,\ldots,m.
	\end{align}
	Here $(g^{ij})=(g_{ij})^{-1}$ is the inverse of the induced metric $ g_{ij}=\langle \frac{\partial  F}{\partial x_{i} },\frac{\partial  F}{\partial x_{j} }\rangle$, and $(\cdot )^{\perp}$ denotes the projection onto the normal bundle of $F(E,t)$ in $E\times \R^{m}$.% in  $T(E\times\mathbb{R}^{ m} )$. %while $(\cdot)^{\perp}$ denotes the normal part of the projection onto the orthogonal complement of the tangent space.


	%Next, we give a correspondence of the equation of \eqref{DP:MSS} and \eqref{MCF}.
	Suppose the image of $F=(F^{1},\ldots, F^{m})$ is a graph over  $E$. Then there exists a family of diffeomorphisms $r_{t}:E\rightarrow E$ such that $\tilde{F_{t}}=F_{t}\circ r_{t}$ has the form
	\begin{align*}
	\tilde{F}  (x_{1},\ldots, x_{n},t)=(x_{1}, \ldots, x_{n}, f^{1}(x,t),\ldots,f^{m}(x,t)).
	\end{align*}
Here $f_{t}(x)=f(x,t)$, where $ f=(f^{1}(x,t),\ldots,f^{m}(x,t)): E \times [0,T)\rightarrow \mathbb{R}^{m}$, satisfies  non-parametric system
\begin{equation}\label{MCF3}
\left\{\begin{aligned}
\frac{\partial}{\partial t} f^{A} (x,t )&=g^{ij}\frac{\partial^{2}f^{A}}{\partial x_{i}\partial x_{j}}\quad A=1,\ldots,m, ~\mbox{on} ~E\times [0,T)\\
f (x,t)&= \psi ( x),\quad \,\mbox{on} ~\partial E\times [0,T) .
\end{aligned}
\right.
\end{equation}
%	where $(g^{ij})$ is the inverse of $g_{ij} =\sigma_{ij}+\sum_{A=1}^m f^A_i f^A_j$.

%	Note that,  if  $f=(f^{A}) :E \times [0,T)\rightarrow \mathbb{R}^{m}$ solves \eqref{MCF2}, then $\tilde{F}(x , t)=(x,f_{t}(x))$ satisfies
