Now, we collect some facts about the singular values of a smooth map $f:E\rightarrow \R^{m}$. We use similar notations as in \cite{Tsui-Wang2004}. Suppose $r$ is the rank of differential map $df$ at $x\in E$. By the singular value decomposition theorem, there exist an orthonormal basis $\{a_1,\cdots , a_n\}$ in $T_xE$ and an orthonormal basis $\{a_{n+1},\cdots, a_{n+m}\}$ in $T_{f(x)}\R^m$ such that
   \begin{equation}\label{relation:A}
       df(a_i)=\lambda_i a_{n+i}, 1\leq i\leq r,\ \text{and}\  df(a_i)=0,  r+1\leq i\leq n.
              \end{equation}
Using this frame we show Lemma \ref{lm:gij} as follows.
\begin{proof}[The proof of Lemma \ref{lm:gij}] Fix any $(x,f(x))\in E\times\R^m$. Notice that both inequalities in Lemma \ref{lm:gij} are invariant under any coordinate system composed with an orthonormal transformation in $T_x E$ and $T_{f(x)}\R^m$. We may assume the frame $\{a_1,\cdots, a_n\}$ is equal to $\{\F{\P}{\P x_1},\cdots, \F{\P}{\P x_n}\}$ at $x$, and $\{a_{n+1},\cdots, a_{n+m}\}$ is equal to $\{\F{\P}{\P y^{ 1}},\cdots, \F{\P}{\P y^{ m}}\}$ at $f(x)$. Under this setting,
    $$
    g_{ij}=(1+\lambda_i\lambda_j)\delta_{ij},\ \text{and} \  g^{ij}=\frac{1}{1+\lambda_i\lambda_j}\delta_{ij}.
    $$
Notice that $\lambda _i\leq |Df|$ for $i=1,\cdots,n$. Therefore $(1+|Df|^2)(\delta_{ij})\geq (g_{ij})\geq  (\delta_{ij})$ and $(\delta_{ij})\geq (g^{ij})\geq\F{1}{1+|Df|^2} (\delta_{ij})$. The proof is complete.
    \end{proof}
We view $\Gamma(f)$ as a submanifold in the product manifold $E\times \R^m$. Denote the point $(x,f(x))$ by $p$.  Therefore
	\begin{equation}\label{def:tangent:vector}
		e_{i}:=\left\lbrace
		\begin{aligned} 	&\frac{1}{\sqrt{1+\lambda_{i}^{2}}}(a_{i}+\lambda_{i}a_{n+i}),\quad i=1,\cdots,r;\\
			&a_i,\quad\quad\quad i=r+1,\ldots,n,
		\end{aligned}\right.
	\end{equation}
forms an orthonormal basis of the tangent space $T_{p}\Gamma(f)$,  and
	\begin{equation}\label{def:normal:vector}
		e_{n+i}:=\left\lbrace
		\begin{aligned}
            &\frac{1}{\sqrt{1+\lambda_{i}^{2}}}(-\lambda_{i}a_{i}+a_{m+i})\quad i= 1,\ldots,r;\\
			&a_{m+i},\quad\quad\quad i=r+1,\cdots, n,
		\end{aligned}\right.
	\end{equation}
forms an orthonormal basis of the normal space $N_{p}\Gamma(f)$.

From now on, we assume that the Ricci curvature of the Riemannian manifold $M$ is non-negative, that is $Ric_M\geq 0$. Our purpose is to show Proposition \ref{prop:preserved}, which says that the strictly length decreasing property is preserved along the MCF in $E\times \R$ with fixed boundary.

With the above notation, let $\Omega$ be the volume form of $E$ such that
	$\Omega(a_1,\cdots, a_n) =1$,
and so $*\Omega$, the projection of $\Omega$ onto $\Gamma(f)$, can be written as
	\begin{equation}\label{star Omega}
		*\Omega=\Omega(e_1,\cdots, e_n)=\F{1}{\sqrt{\prod_{i=1}^n(1+\lambda_i^2)}},
	\end{equation}
which is independent of the choice of local orientable frame on $\Gamma(f)$.

For the graphic mean curvature flow $\Sigma_t=F(x,t)=\{(x,f_t(x)):x\in E\}$ defined in \eqref{MCF2}, Wang \cite{Wang2002,Wang2003,Wang2004}  and Tsui-Wang \cite{Tsui-Wang2004}  have already done a lot of calculation. We record the evolution equation of $*\Omega$  for completeness .

In the followings, let $\bar{R}$ and $R$ denote the curvature tensors of $E\times\R^m$ and $E$, respectively. Let the index $i,j,k,l$ range from $1$ to $n$, and let $\alpha$ range from $n+1$ to $n+m$. Suppose the MCF flow $\Sigma_t$ exists on $[0,T)$ in $E\times \R^m$. By noting $(\ln *\Omega)_k= -\sum_{i} \lambda_i h_{n+i,ik}$, for each $k $,  we have
   \begin{equation}\label{evolution Omega}
   	\begin{aligned}
   		&(\F{d}{dt}-\Delta)\ln *\Omega = \sum_{\alpha ,l,k} h_{\alpha  lk}^{2}+2\sum _{k,i<j}\lambda_{i}\lambda_{j}   h_{n+i,jk}h_{n+j,ik}
           \\
     &+\sum_{i,k} \lambda_{i}^{2} h_{n+i,ik}^{2}-\F{1}{*\Omega}\sum_{\alpha,k}(\Omega_{\alpha 2\cdots n}\bar{R}_{\alpha kk1}+\cdots+\Omega_{1\cdots ( n-1)\alpha }\bar{R}_{\alpha kk n})
   	\end{aligned}
   \end{equation}
   where $h_{\alpha,ij}=\la \bar{\nabla}_{\tau_i}\tau_j, \tau_{\alpha} \ra$, $\bar{R}_{\alpha kkj}=\bar{R}(e_{\alpha},e_k,e_k,e_j)$, and $\Omega_{1\cdots (k-1)\alpha (k+1)\cdots n}=\Omega(e_1,\cdots, e_{k-1},e_\alpha, e_{k},\cdots,e_n)$. Putting \eqref{def:tangent:vector} and \eqref{def:normal:vector}  into the curvature term in   \eqref{evolution Omega}, we obtain
   	\begin{align*}
   		&-\frac{1}{*\Omega}\sum_{\alpha,k}(\Omega_{\alpha 2\cdots n}\bar{R}_{\alpha kk1}+\cdots+\Omega_{1\cdots n-1\alpha }\bar{R}_{\alpha kk n})\\
   		=&\sum_{i}  \frac{\lambda_i^2}{1+\lambda_i^2}\prod_{j\neq i}\frac{1}{1+\lambda_j^2}\sum_{k}R(a_i, a_k,a_j, a_k) \\
   		=& \sum_{i}  \frac{\lambda_i^2}{1+\lambda_i^2}\prod_{j\neq i}\frac{1}{1+\lambda_j^2} Ric_M(a_i, a_j)\geq 0.
   	\end{align*}
Since $Ric_{M}\geq 0$, we obtain
\begin{equation}\label{eq star Omega}
               (\F{d}{dt}-\Delta)\ln *\Omega\geq  \sum_{\alpha ,l,k} h_{\alpha, lk}^{2}+2\sum _{k,i<j}\lambda_{i}\lambda_{j}   h_{n+i,jk}h_{n+j,ik}+\sum_{i,k} \lambda_{i}^{2} h_{n+i,ik}^{2}.
\end{equation}
If $f_t$ preserves the strictly area decreasing property, $\lambda_i\lambda_j<1-\Sc$ for some positive constant $\Sc$ independent of $t$, as \cite[(6.2)]{Tsui-Wang2004}, the right hand side of \eqref{eq star Omega} is greater than $\Sc \sum_{\alpha,l,k}h_{\alpha,lk}^2$. Therefore it holds that
\begin{equation} \label{del:min:A}
     (\F{d}{dt}-\Delta)\ln *\Omega\geq \Sc\sum_{\alpha ,l,k} h_{\alpha, lk}^{2}
    \end{equation}
     \begin{remark}
        According to the maximum principle, the condition $*\Omega>0$ is not broken along the interior of the graphic MCF flows. \label{thegraph:remark}  As a result, under the assumption of Proposition \ref{prop:preserved} below, if the strictly length decreasing property of $f_t(x)$ is preserved along the MCF $\Sigma_t$, it remains a graph.
    \end{remark}
     To study the length decreasing property, consider the symmetric 2-tensor $S$ defined by
        \begin{equation*}
            S(X,Y)=\la  \pi_1 (X), \pi_1 (Y)\ra-\la  \pi_2 (X),  \pi_2 (Y)\ra
            \end{equation*}
           for any $X,Y\in T(E\times \mathbb{R}^{m})$, where $\pi_1:E\times\R^m\rightarrow E$ and $\pi_2:E\times \R^m\rightarrow \R^m$ are the corresponding projections. From \eqref{def:tangent:vector},
            \begin{equation}\label{S_ij}
               S_{ij}=S(e_i, e_j)=\frac{1-\lambda^2_{i}}{1+\lambda_i^2}\delta_{ij}.
                \end{equation}
      Thus $S$ is positive definite restricted on $T\Sigma_{t}$ if and only if $\lambda_i <1$, for $i=1,\cdots, n$  (that is $f_{t}$ is strictly length decreasing).  For future use, we point out that
      \begin{equation}\label{dust} S(e_{i}, e_{n+j})=S(e_{n+i}, e_j)=\frac{ -2\lambda _{i}}{1+\lambda_i^2}\delta_{ij} \quad  S(e_{n+i}, e_{n+j})=-S_{ij},
          \end{equation}  by \eqref{def:tangent:vector} and \eqref{def:normal:vector}.

The following theorem is an analog of the strictly length decreasing preserving result in \cite[Section  4]{Tsui-Wang2004} in the boundary case.
     \begin{prop} \label{prop:preserved}
     	Let $M^{n}$ be a complete Riemannian manifold with non-negative Ricci curvature and let $E\subset M$ be a bounded smooth domain. Suppose $\psi:\bar{E}\rightarrow \R^m$ is a smooth strictly length decreasing map, and the mean curvature flow $\Sigma_t$ in \eqref{MCF3} exists on $\bar{E} \times [0, T)$ as a smooth graph $(x,f_t(x))$ satisfying $\max\{\sup_{ \P E\times  [0,T)}|Df_t|,\sup_{ \bar{E} }|D\psi|\}<1-\Sc $, for a fixed constant $\Sc \in (0,1)$. Then $\Sigma_t$ stays a graph of a smooth strictly length decreasing map  on $\bar{E} \times [0, T)$ with $\sup_{E}|Df_t|< 1-\Sc$.
     \end{prop}
     \begin{proof}
     	  %and the assumption $\sup_{x\in \P E, t\in [0,T]}|Df_t|<1-\Sc_0$ on $[0,T]$,
     By Remark \ref{thegraph:remark},  %and the assumption $\sup_{x\in \P E, t\in [0,T]}|Df_t|<1-\Sc_0$ on $[0,T]$,
     it suffices to show that $ \sup_{E}|D f_{t}|<1-\Sc$ for any $t\in [0,T)$.

    % Fix a fixed local coordinate system $\{x^{1 },\cdots, x^{n}\}$ on $E$, then the MCF $\Sigma_t$ can be written as $(x,f_{t}(x))\subset E\times  \R^m$.
     %Here $\Sc$ is a positive constant only depending on $\Sc_0$ and $\psi$.

     By the assumption, define $P_{ij}=S_{ij}-\epsilon' g_{ij}$ along the mean curvature flow $\Sigma_t$. Here $\Sc'=\frac{1-(1-\epsilon)^{2} }{1+(1-\epsilon)^{2}}\in (0,1)$ is a constant such %$S_{ij}-\epsilon g_{ij}> 0$ for some $\epsilon>0$ at time $t=0$. %Since $\sup_{\P E}|Df_t|<1$ for all $t\in [0,T)$, it follows
     	 that $P_{ij}>0$ (positive definite) on $\P E\times [0,T)\cup E\times \{ 0\} $ according to \eqref{S_ij}. It remains to show that $P_{ij}>0$ is preserved along the interior of $\Sigma_t$ over the interval $[0,T)$.

     A straightforward computation gives that (c.f. \cite[ Eq. (4.8)]{Tsui-Wang2004})
     	\begin{align*}
     		(\frac{d}{dt}-\Delta )P_{ij}
     		=& -h_{\alpha il}H_{\alpha}P_{lj}-h_{\alpha jl}H_{\alpha}P_{li}+\bar{R}_{kik\alpha}S_{\alpha j}+\bar{R}_{kjk\alpha}S_{\alpha i}
     		\\&+h_{\alpha kl}h_{\alpha ki} P_{lj} +h_{\alpha kl}h_{\alpha kj} P_{li}+2\epsilon' h_{\alpha ki}h_{\alpha kj}-2h_{\alpha ki}h_{\beta kj} S_{\alpha\beta},
     	\end{align*}
          on $E\times [0, T)$.
         %Here $\bar{R}$ and $R$ denote the Riemannian curvature  tensor of $E\times \R^m$ and $E$ respectively.
         Let $Q_{ij}$ denote the right hand-side of the above equation.
         By the Hamilton's maximum principle for tensors (see \cite[Theorem 9.1]{Hamilton1982} or \cite{Hamilton1986}), if $Q_{ij}w^{i}w^{j}\geq 0$ for any vector $w=(w^1,\cdots, w^{n})^T$ on $E\times [0, T)$  such that  $P_{ij}w^{j}= 0$ for all $1\leq i\leq n$, then $P_{ij}$ is positive definite on $E\times[0,T)$.

         Indeed, we compute
     	\begin{align} \label{Q positive}
     		Q_{ij}  w^{i}w^{j}
     		=&  2\bar{R}_{kik\alpha}S_{\alpha j}w^{i}w^{j}
     		+2\epsilon' h_{\alpha ki}h_{\alpha kj}w^{i}w^{j}-2h_{\alpha ki}h_{\beta kj} S_{\alpha\beta}w^{i}w^{j}\nonumber
     		\\\geq& 2\bar{R}_{kik\alpha}S_{\alpha j}w^{i}w^{j} -2h_{\alpha ki}h_{\beta kj} S_{\alpha\beta}w^{i}w^{j}.
     	\end{align}
     	For the second term in \eqref{Q positive}, using $S_{ij}\geq \epsilon g_{ij}\geq0$ and the relation in \eqref{dust}, we have
     	\begin{align*}
     		&-2h_{\alpha ki}h_{\beta kj} S_{\alpha\beta}w^{i}w^{j}
     		\\=&2\sum_{1\leq p,q\leq r} h_{n+p, ki}h_{n+q, kj} S_{pq}w^{i}w^{j}+2\sum_{r+1\leq p,q\leq m} h_{n+p, ki}h_{n+q, kj}  w^{i}w^{j}\geq 0.
     	\end{align*}
     For the first term in \eqref{Q positive}, we  prove that $\bar{R}_{kik\alpha}S_{\alpha j} \geq 0$.
     	Since
     	\begin{align*}
     		\sum_{k} \bar{R} (e_{ \alpha},e_{ k},e_{k},e_{i})
     		= &\sum_{k}R(\pi_{1}(e_{ \alpha}),\pi_{1}(e_{ k}),\pi_{1}(e_{k}),\pi_{1}(e_{i}))
     		\\= & \sum_{k}R( e_{ \alpha},e_{ k},e_{k},e_{i})=Ric_{M} ( e_{ \alpha}, e_{i}).
     	\end{align*}
Here we used the definition of sectional curvature  $K(X,Y)=R(X,Y,Y,X)$.
     	As a result, by \eqref{dust}, we have
     	\begin{align*}
     		\sum_{\alpha,k} \bar{R}_{kik\alpha}S_{\alpha j}
     		=  &- \sum_{p,k} \bar{R}_{n+p, kki }S_{n+p, j} =-\sum_{p }Ric_{M}( e_{n+p}, e_{i})S_{n+p, j}
     		\\=& Ric_{M}( e_{n+j}, e_{i}) \frac{ 2\lambda_{j}}{1+\lambda_{j}^{2}}  \geq0.
     	\end{align*}
   In summary, plugging the above computations into \eqref{Q positive} gives $Q_{ij}v^i v^j\geq 0$. This completes the proof.
     \end{proof}



\section{Boundary gradient estimates}\label{Sec bdry est}

	In this section, we derive the boundary gradient estimate along the mean curvature flow, which is essential in the proof of Theorem \ref{main:thm:A}.

	Denote the graphic mean curvature flow by  $\Sigma_{t }=(x,f_{t}(x))$, where $f_t(x):\bar{E}\times [0,T)\rightarrow \R^m$. Let $df_t$ denote the differential of $f_t$. Define $d(x):=dist(x,\partial E)$, for $x\in E$ as the distance from $x$ to the boundary $\partial E$.

	\begin{lem}\label{lap}
	Let $M^{n}$ be a complete Riemannian manifold and let $E\subset M$ be a bounded smooth domain. Suppose the mean curvature flow $\Sigma_{t}$ exists on $E\times[0,T)$. Then there exists a constant $\eta_0=\eta_0(n, \P E)>0$, and $c_{0}=c_{0}(n,\partial E )>0$,  such that
		\begin{align*}
			-\Delta_{\Sigma_{t}} d \geq -c_{0}, \  \   \mbox{on} \ E_{\eta_0} ,
		\end{align*}
	 where $E_{\eta_{0}} =\{x\in E:d(x,\partial E)<\eta_{0}\}$.  Additionally, if $E$ is strictly convex,  $c_0$ can be chosen as $0$.
	\end{lem}
    \begin{remark}
    	The main role of $\eta_0$ is to ensure that the function $d$ is a $C^2$ function on $E_{\eta_0}$. For instance, whenever $E$ is strictly convex, we shall choose $\eta_0$ sufficiently small such that the level set of $d(x)$ in $E_{\eta_0}$ is embedded and convex with respect to the outward normal vector.
        \end{remark}
	\begin{proof}
	It is easy to see that $d(x)$ is a $C^2$ function on $E_{\eta_{0}}$, for some  $\eta_{0}=\eta_{0}(n,\partial E)>0$.
Fix any $x\in E_{\eta_{0}}$, we use the induced metric of $\Sigma_t$ given in \eqref{coe:g}. Let $(\sigma_{ij})$ be the metric matrix of $E$. By Lemma \ref{lm:gij},$(g_{ij})\leq (\sigma_{ij})$. For any $x\in E_\eta$, choose an orthonormal frame $\{a_1,\cdots,a_n\}$ at $T_x E$. Without loss of generality, we assume $(\sigma_{ij})$ is the identity matrix at $x$. Hence $(g_{ij})\leq (\delta_{ij})$. Then at any $x\in E_{\delta_0}$,
		\begin{align}
			-\Delta_{\Sigma_{t}} d =&-g^{ij}\mathrm{Hess}(d) (a_{i}, a_{j})
			\geq%- \delta_{ij} |Hess(d) (e_{i}, e_{j})|
		  -  \sum_{i} |\mathrm{Hess}(d) (a_{i}, a_{i})|\label{eq:computation:d}\\
          \geq& -n\max_{i}\sup_{E_{\eta_0}}|\mathrm{Hess}(d) (a_{i}, a_{i})|:=-c_{0}(n,\partial E).\notag
		\end{align}
     \noindent   In the case that $ E$ is strictly convex, the matrix $\{-\mathrm {Hess}(d)(a_i,a_j)\}$ is positive definite on $\P E$. As a result, if we take $\eta_0$ sufficiently small, it holds that
        $-g^{ij}\mathrm{Hess}(d)(a_i,a_j)\geq 0$ on $E_{\eta_0}$. In the above inequality, $c_0$ could be chosen as $0$.
	\end{proof}
	\begin{remark}\label{delta0rmk}
		%\begin{enumerate}
			%\item Since $E\in C^{2}$, there exists $\eta
			%=\eta_{0}(n,\partial E)>0$ such that $d$  is a $C^{2}$ function in $E_{\eta_{0}}$ and the set $\{x\in E: d(x,\P E)\}$ is embedded. %From now on fix this $\eta$, then it holds that
			%\begin{align*}
			%	-\Delta_{\Sigma_{t}} d \geq &\frac{1}{2}\delta_{ij}\nabla_{e_{i}}\nabla_{e_{j}}d\geq - \frac{1}{2}|\Delta_{E_{\eta}} d| \geq -c_{0}(n,\partial E).
		%	\end{align*}
			%\item
			In particular, when  $E$ is a ball $B_{r}(0)$ in $\R^n$ centered
            at the origin with radius $ r$, a direct computation yields that  $-\mathrm {Hess}(d)(e_i,e_j)(x)=\F{1}{r-d(x)}\delta_{ij}> 0$ for any $x\in B_{r}(0)$. Then, according to \eqref{eq:computation:d},
			\begin{equation}
				-\Delta_{\Sigma_t}d \geq 0
			\end{equation}
			holds on $\{x\in B_{r}(0): dist(x,\P B_{r}(0))<1\}$.
			Therefore, we can choose $c_0$ as zero and $\eta_0$ as any number in $(0, r)$.
	%	\end{enumerate}
	\end{remark}

To formulate the desirable boundary gradient estimates, we begin by defining some notations to govern the subsequent discussion. Denote $w^{A} =\sup_{\bar{E}}\psi ^{A}-\inf_{\bar{E}}\psi^{A} $ and  $w(\psi) =\max_{1\leq A\leq m}w^{A}$. Let  $f=(f^{A})_{A=1}^{m}$ and $\psi=(\psi^{A})_{A=1}^{m}$. By the maximum principle, $\inf_{\bar{E}}\psi^{A} \leq  f^{A} \leq\sup_{\bar{E}}\psi^{A}$  on $\bar{E}\times[0,T)$ for $1\leq 	A \leq m$.

	\begin{prop}\label{keyLboundary:estimate}
		Let $M^{n}$ be a complete Riemannian manifold and let $E\subset M$ be a bounded smooth domain. Suppose $F=(x,f(x,t)): E\times[0,T)\rightarrow E`	\times \R^{m}$ is a smooth solution to \eqref{MCF3}. Then there exists a constant $ \delta_0=\delta_0(n,\partial E,\mu)>0$  such that for any $\delta\in (0,\delta_0]$,
		\begin{align*}
			|Df | \leq &    \frac{ \omega(\psi)}{\delta} +  |D\psi |+16n(1+\mu) \delta   |D^{2} \psi |, \quad \mbox{on}\quad  ~\partial E \times [0,T),
		\end{align*}
		where $\mu=\sup_{E \times [0,T)}|Df |^{2} $.
		%Additionally, if $ |Df|<1$ on $E \times [0,T)$,	then there exists constant $ \delta_0=\delta_0(n,\partial E)>0$ such that for any $\delta_0\in (0,\delta)$,
		%\begin{align*}
		%	|Df |\leq &\frac{\omega}{\delta}+ |D\psi | +32n\delta|D^{2} \psi  |, \quad \mbox{on} ~\partial E \times [0,T).
	%	\end{align*}
	\begin{remark}\label{remark:definitioneta}
	Let $c_0$ and $\eta_0$ be the numbers given in Lemma \ref{lap}. In \eqref{definition:eta_0},  the constant $\delta_0$ is given by
	\begin{align*}
	\delta_0=\begin{cases} \frac{1}{2}\min \{\frac{1}{8c_{0}(1+\mu) }, \eta_{0}\}, \quad \mbox{if}\  c_0>0;\\
		\eta_0, \quad\mbox{if}\  c_0=0 \quad( \text{when $E$ is strictly convex}).
	\end{cases}
	\end{align*}
    This Proposition generalizes the computation in \cite[Proposition 2.2]{Wang2004}.
	\end{remark}
	\end{prop}
	\begin{proof}
		Choose two coordinate systems  $\{x^{i}\}$ on $E$  and   $\{y^{A}\}$ on $\mathbb{R}^{ m}$, respectively. Then
            $F(x,t)=(x^1,\cdots, x^n, f^1(x,t),\cdots, f^m(x,t))$ and  $ \psi(x)=(\psi^1(x),\cdots,\psi^m(x)) $. For each  $A=1,\ldots,m$, define
		\begin{align*}
			S (x,t)=\nu \log (1+kd(x))+\psi ^{A}-f ^{A}+\frac{\omega^{A}}{\delta}d(x), \quad\mbox{on}~ E_{\delta}\times[0,T),
	  \end{align*}
		where $k,\nu$  and $\delta$ are positive constants to be determined later.

		Firstly, we claim that $S\geq 0$ on $\partial E_{\delta}\times[0,T)$. In fact, note that $\partial E_{\delta}=\partial E \cup\partial^{\delta}E$, where $\partial^{\delta} E:=\{x\in E:d(x,\partial E)=\delta\}$.  Obviously, $S=0$ on $\partial E\times[0,T)$. By the definition of $\omega^A$,  $\omega^{A}=\sup_{\bar{E}}\psi^A-\inf_{\bar{E}}\psi^A$, it holds that
		\begin{align*}
			S  \geq   %\psi ^{A}-f^{A}+  \omega^{A}=
			\psi^{A}-f^{A}+\sup_{\overline{E}}\psi^{A}-\inf_{\overline{E}}\psi^{A}\geq 	\sup_{\overline{E}}\psi^{A}- f^{A} \geq 0,  \quad\mbox{on}~ \partial^{\delta}E\times[0,T).
		\end{align*}
		On the other hand, since $f\equiv \psi$ on $\P E\times [0,T)$, we see that $S\geq 0$ on $ \P E\times [0,T)$. These two facts together yield the claim.

		Next, a direct calculation gives
		\begin{align}\label{dt-laplace}
			&(\dfrac{d}{dt}-\Delta _{\Sigma_{t}})S \\
			=&-\bigg(\frac{ \nu k}{1+kd (x)}+ \frac{\omega^{A}}{\delta} \bigg)\Delta _{\Sigma_{t}}d(x) +\frac{\nu k^{2}}{(1+kd(x))^2}g^{ij}\frac{\partial d }{\partial x^{i} }\frac{\partial d }{\partial x^{j} }-\Delta_{\Sigma_{t}} \psi ^{A} \nonumber.
		\end{align}

		Let $\mu=\sup_{E \times [0,T)}|Df |^{2} $. By Lemma \ref{lm:gij} $\frac{1}{1+\mu} (\sigma^{ij})\leq (g^{ij})\leq (\sigma^{ij})$. Applying Lemma \ref{lap}, we derive
		\begin{align*}
			(\dfrac{d}{dt}-\Delta _{\Sigma_{t}})S \geq-c_{0}\bigg(\dfrac{ \nu k}{1+kd (x)}+ \frac{\omega^{A}}{\delta} \bigg)+\frac{\nu k^{2}}{(1+kd (x))^2} \frac{1}{1+\mu} -|\Delta_{\Sigma_{t}} \psi ^{A}|,
		\end{align*}
		where $c_{0}=c_{0}(n,\partial E)>0$ is the constant given in Lemma \ref{lap}.

		Further,  using $|\Delta_{\Sigma_{t}} \psi ^{A}|  \leq n|D^{2}\psi^{A}|$
		and $d(x)< \delta$ on $E_{\delta}$, we obtain
		\begin{align*}
			(\frac{d}{dt}-\Delta _{\Sigma_{t}})S
			\geq&-c_{0}( \nu k +\frac{ \omega^{A}}{\delta})+ \frac{\nu k^{2}}{(1+k\delta)^2}\frac{1}{1+\mu} -n|D^{2} \psi ^{A}|.
		\end{align*}
		Choose $k= \delta^{-1}$. We derive
		\begin{align*}
			(\frac{d}{dt}-\Delta _{\Sigma_{t}})S
			\geq&-c_{0}\frac{( \nu + \omega^{A})}{\delta}+  \dfrac{\nu}{4(1+\mu)\delta^{2}} -n|D^{2} \psi ^{A}|\\
			=&\frac{\nu  }{\delta}\big (   \frac{1}{4(1+\mu) \delta} -c_{0}  \big)-c_{0}\frac{  \omega^{A} }{\delta}-n|D^{2} \psi ^{A}|.
		\end{align*}
		%To make sure
		%	\begin{align*}
			%	\frac{\nu}{\delta } \geq&\big(   \frac{1}{4(1+\mu) \delta} -c_{0}  \big) ^{-1}\big(c_{0}\frac{  \omega^{A} }{\delta}+n|D^{2} \psi ^{A}|\big)  .
			%	\end{align*}

	It suffices to take $\nu$ as
		\begin{align*}
			\nu =& \frac{4(1+\mu) \delta ^{2} }{1-4c_{0}(1+\mu) \delta}\big(c_{0}\frac{  \omega^{A} }{\delta}+n|D^{2} \psi ^{A}|\big)>0.
		\end{align*}
		Then
		\begin{align*}
			(\frac{d}{dt}-\Delta _{\Sigma_{t}})S\geq 0 \quad \text{ on} \quad E_\delta\times [0,T)
		\end{align*}

		To determine $\delta$, our consideration is divided into two cases.

		\textit{Case 1}.
		Suppose $c_{0}=0$. Now
		\begin{align} \label{c0=0}
			\dfrac{\nu }{\delta} =&  4(1+\mu) \delta n|D^{2} \psi ^{A}| .
		\end{align}
	Let $\delta_0=\eta_0$, where $\eta_0$ is   given as in Lemma \ref{lap}. We can choose $\delta$ to be any number in $(0,\delta_0]$.

	\textit{Case 2}. Suppose $c_{0}>0$.	Take $\alpha_0=\min \{\frac{1}{8c_{0}(1+\mu) }, \eta_{0}\}$. For any $\delta\in (0,\alpha_0]$, then  $4c_{0}(1+\mu)\delta\leq 1/2$ and so
		$1-4c_{0}(1+\mu) \delta \geq1/2$.
		Thus
		\begin{align}  \label{nu-delta-mu}
			\frac{\nu }{\delta} =& \frac{4(1+\mu) \delta  }{1-4c_{0}(1+\mu) \delta}\big(c_{0}\frac{  \omega^{A} }{\delta}+n|D^{2} \psi ^{A}|\big)\\\nonumber
			\leq&  8(1+\mu) \delta   \big(c_{0}\frac{  \omega^{A} }{\delta}+n|D^{2} \psi ^{A}|\big)\\\nonumber
			% =&  8(1+\mu) \big(c_{0}   \omega^{A} +\delta   n|D^{2} \psi ^{A}|\big)\\
			=&  8(1+\mu) c_{0}   \omega^{A} +8(1+\mu) \delta   n|D^{2} \psi ^{A}|\\\nonumber
			\leq &    \frac{ \omega^{A}}{\delta} +8n(1+\mu) \delta   |D^{2} \psi ^{A}| ,
		\end{align}


		In both cases, we arrive at $(\frac{d}{dt}-\Delta _{\Sigma_{t}})S\geq0$.
		Applying the maximum principle, we have $S \geq 0$ in $E_{\delta}\times[0,T)$. Namely $f^{A}- \psi ^{A}\leq \nu \log (1+kd(x))+ \frac{\omega^{A}}{\delta}d(x)$  on $E_{\delta}\times[0,T)$.

		Similarly, applying the above process to the function
		$\tilde{S} =\nu\log(1+kd (x ))+f^{A}-\psi^{A}+ \frac{\omega^{A}}{\delta}d(x)$, we obtain $ \psi ^{A}-f^{A}\leq \nu \log (1+kd(x))+ \frac{\omega^{A}}{\delta}d(x)$  on $E_{\delta}\times[0,T)$.

		Therefore, we obtain  %the normal derivative of  $(f^{A}-\psi^{A})$
		\begin{align*}
			\left| \dfrac{\partial(f^{A}-\psi^{A}) }{\partial \mathbf{n}} \right|
			\leq&\lim_{d (x)\rightarrow0}	\dfrac {|f^{A}(x)-\psi^{A}(x)|}{d (x)}\\
			\leq &\lim_{d (x)\rightarrow0}\dfrac{\nu\log(1+kd (x))}{d (x)}+ \frac{\omega^{A}}{\delta}\\
			\leq&\nu k+\frac{ \omega^{A} }{\delta} = \frac{\nu +\omega ^{A}}{\delta}
		\end{align*}
		where $ \mathbf{n}$ is the outward unit  normal vector of $\partial E$.
		Assuming $\frac{\partial f^{A}}{\partial \mathbf{n}}=0$ for all $A\geq2 $ up to an orthogonal transformation of coordinates on $E$ at a fixed point, we derive
		\begin{align*}
			\left|\frac{\partial f}{\partial \mathbf{n}} \right|  \leq \frac{\nu +w(\psi) }{\delta}+\left| \dfrac{\partial \psi}{\partial \mathbf{n}}\right| .
		\end{align*}

		On the other hand, we have %by the Dirichlet condition, we know
		\begin{align*}
			|D^{\top}f |= |D^{\top}\psi | \quad \mbox{on} ~ \partial E,
		\end{align*}
		where  $|D^{\top}f |(x)=\sup_{v\in T_{x}(\partial E),|v|=1}|Df(x)(v)|$.

		Therefore,
		\begin{align} \label{nu+omega}
			|Df |\leq &\sqrt{\big( \frac{\nu +w(\psi) }{\delta}+ | \frac{\partial \psi}{\partial \mathbf{n}}|\big )^{2}+|D^{\top}\psi |^{2}}\\
			\leq &\frac{\nu +w(\psi) }{\delta}+ |D\psi | \quad \mbox{on}~ \partial E.\nonumber
		\end{align}
		Here, in the last inequality, we use
		\begin{align*}
			&\big( \frac{\nu +w(\psi) }{\delta}\big)^{2}+| \frac{\partial \psi}{\partial \mathbf{n}} |^{2}+2\big( \frac{\nu +w(\psi) }{\delta}\big) | \frac{\partial \psi}{\partial \mathbf{n}} |+|D^{\top}\psi |^{2}\\
			\leq &(\frac{\nu +w(\psi) }{\delta})^{2}+  |D\psi | ^{2}+2 |D\psi | \frac{\nu +w(\psi) }{\delta}=(\frac{\nu +w(\psi) }{\delta}+ |D\psi |)^{2}
		\end{align*}

		Finally, we arrive the following conclusion.

		\textit{Case 1}.
		Combining \eqref{c0=0} and \eqref{nu+omega} together, we obtain
		\begin{align*}
			|Df | \leq &    \frac{ w(\psi) }{\delta} +  |D\psi |+4n(1+\mu) \delta   |D^{2} \psi |,\quad \mbox{on} ~\partial E \times [0,T).
		\end{align*}
      for any $\delta \in (0, \delta_0]$. \\
		\indent \textit{Case 2}.
		Combining \eqref{nu-delta-mu} and \eqref{nu+omega} together, we have
		\begin{align*}
			|Df | \leq &    \frac{ 2 w(\psi) }{\delta} +  |D\psi |+8n(1+\mu) \delta   |D^{2} \psi |,\quad \mbox{on} ~\partial E \times [0,T).
		\end{align*}
        for any $\delta\in (0,\alpha_0]$. Now let $\delta_0=\frac{1}{2}\alpha_0=\frac{1}{2}\min \{\frac{1}{8c_{0}(1+\mu) }, \eta_{0}\}$. The above inequality becomes that
		\begin{align*}
			|Df | \leq &    \frac{ w(\psi)}{\delta} +  |D\psi |+16n(1+\mu) \delta   |D^{2} \psi |.
		\end{align*}
        for any $\delta\in (0,\delta_0]$.

         Combining these cases together, there exists  $\delta_0=\delta_0(n,\mu, \P E)>0$ given by
        \begin{equation}\label{definition:eta_0}
                \delta_0=\begin{cases} \frac{1}{2}\min \{\frac{1}{8c_{0}(1+\mu) }, \eta_{0}\}, \quad c_0>0;\\
                    \eta_0, \quad c_0=0,
                \end{cases}
            \end{equation}
            such that for any $\delta\in (0,\delta_0]$,
   	\begin{align*}
   		|Df | \leq &    \frac{ w(\psi)}{\delta} +  |D\psi |+16n(1+\mu) \delta |D^{2} \psi |.
   	\end{align*}
   on $\P E\times [0,T]$. The proof is complete.
	\end{proof}


	\section{Bernstein-type results over half-spaces}\label{Sec Bernstein}
 In this section, we derive some Bernstein-type results for minimal graphs and self-shrinkers
 over half-spaces.  These results  are essential for establishing the long-time existence of the MCF flow with boundary in Lemma \ref{second:step:MCF}, albeit they may not be optimal.
 \subsection{Smooth Bernstein type theorem} Let $\R^n_{+}$ be the upper half-space $\{(x_1,\cdots, x_n)\in\R^n:x_n>0\}$. Throughout this subsection, $\Omega$ denotes $dx^1\wedge \cdots \wedge dx^n$ which is the volume form of $\R^n$.
	\begin{theorem}\label{smooth:bernstein:theorem}
		Let $f:\bar{E}\subset \R^n \rightarrow \R^m$ be a smooth map on $E$ and Liptschtiz on $\bar{E}$. Suppose $f$ is strictly length decreasing i.e. $\lambda_i <1-\Sc$ for  $1\leq i\leq n$ and for some $\Sc\in (0,1)$. Then the following results hold.

		(1) If $\Gamma(f)$, the graph of $f$, is minimal, then
		\begin{equation}\label{star:Omega}
			0\geq \Delta \ln *\Omega + \Sc \sum_{\alpha,l,k}h^2_{\alpha,lk} \quad \textit{on}\  \Gamma(f).
		\end{equation}

				(2) In addition, if $E=\R^n_{+}$ and $f|_{\P \R^n_{+}}=u_{\P \R^n_{+}}$, then $f$ is a linear map. Here $u_{\P \R^n_+}$ is a linear  map from $\P \R^n_+$ to itself. %and $\Sigma$ is a linear subspace.
	\end{theorem}
	\begin{proof}
		The conclusion (1) follows from \eqref{del:min:A} and the fact that a minimal submanifold is stationary for the MCF.

	From now on, we assume that $E$ is the half space $\R^n_{+}$. Denote $B=\{(x_1,\cdots,x_{n-1},0, \cdots,0)\}$ which is the subspace of $ \R^{n+m}$. Let $\theta,\theta^{\bot}$ be the orthogonal projections from $\R^{n+m}$ onto $B$ and $B^{\bot}$ (which is the normal space of $B$), respectively. For $z=(x_1,\cdots,x_n,y^1,\cdots,y^m)\in \R^{n+m}$, define $$
		\tau(z):=\theta(z)-\theta^{\bot}(z)=(x_1,\cdots,x_{n-1}, -x_n, -y^1,\cdots, -y^m).$$
		Let $v(\Gamma(f))$ note the integral varifold generated from $\Gamma(f)$. Then it is stationary on $\R^{n+m}\setminus B $. According to the reflection principle in \cite[Section 3.2]{Allard1975}, $v(\Gamma(f))+\tau (v(\Gamma(f)))$ is also a stationary integral varifold which is the graph of some {\Lp} function $\tilde{f}:\R^n\rightarrow \R^m$. Moreover, $\lambda_i <1-\Sc$ for any $i=1,\cdots,n$ whenever $d\tilde{f} $ is well-defined. By \cite[Theorem 4.1]{Wang2004} or Theorem \ref{smooth:c-minimal} below, $\tilde{f}$ is smooth. According to \cite[Theorem 1.1]{Wang2003}, $\tilde{f}$ is a linear map on $\R^n$.
	\end{proof}
  Recall that a smooth submanifold in Euclidean space is called a \textit{self-shrinker} if its mean curvature vector $\vec{H}$ satisfies
\begin{equation}
    \vec{H}+\F{\vec{F}^{\bot}}{2}=0,
\end{equation}
where $\vec{F}$ is the position vector and $\vec{F}^{\bot}$ denotes the projection of $\vec{F}$ into its normal bundle. First, we recall the following two results for self-shrinkers from the thesis of the second author \cite{Zhou15}.
\bt(\cite[Theorem 4.1.2]{Zhou15})\label{thm:st:eq:ad} Let $E$ be an open set in $\R^n$. Suppose $f:E\rightarrow \R^m$ is a smooth map, and $\Gamma(f)$ is a smooth self-shrinker. Then  $*\Omega$ (given by \eqref{star Omega})satisfies
\begin{align}
	&\Delta \ast\Omega -\F{1}{2}\la\vec{F},\ast \Omega\ra-\F{|\nb \ast\Omega|^2}{\ast\Omega}\notag\\ &+\bigg(\sum_{i,k}\lambda^2_i  h_{ n+i,ik} ^2 +\sum_{i,j,\alpha} h_{\alpha,ij}  ^{2} + 2\sum_{i<j,k}\lambda_i\lambda_j h_{n+j,ik}h_{n+i,jk} \bigg)\ast\Omega=0.\label{eq:st_ad}
\end{align}
Here $  h_{\alpha,ij}=\la \bnb_{e_i}e_j, e_\alpha\ra$, $\bnb(\nb)$ is the covariant derivative of $\R^{n+m} (\Gamma(f))$, $\Delta$ is the Laplacian of $\Gamma(f)$ and $\vec{F}$ is the position vector of $\Gamma(f)$.
\et
\begin{remark} The proof of the above structure equations is the same as that in \cite{Wang2002} if we replace the vector $\P_t$ by $-\F{\vec{F}}{2}$.
    \end{remark}
\bt(\cite[Theorem 2.2.1]{Zhou15})\label{thm:v_normal} Let $U$ be an open set in $\R^{n+m}$. If $\Sigma$ is a smooth, properly embedded $n$-dimensional submanifold in $U$ such that its point $\vec{F}$ satisfies
$\vec{F}^{\bot}\equiv 0$
, then $\Sigma$ is totally geodesic in $U$.
\et
\br An advantage of our proof is that it works locally. A proof that a smooth, minimal, complete self-shrinker $\Sigma$ with codimension one is totally geodesic can be briefly stated as follows (See Corollary 2.8, \cite{CM12}). If $\Sigma$ is minimal, then $\sqrt{-t}\Sigma=\Sigma$ since $\sqrt{-t}\Sigma$ is a solution of the mean curvature flow. Therefore $\Sigma$ is a smooth minimal cone, the rigidity of $\Sigma$ follows from that a smooth minimal cone is a totally geodesic plane. If a self-shrinker is minimal only in its open subset, then the above derivations are invalid. In this case, we can not claim the self-shrinker is a smooth minimal cone, which is a global property.
\er
\bp Choose any point $\vec{F}_1$ on $\Sigma$. We denote by $\{e_i\}_{i=1}^n$ the orthonormal frame of the tangent bundle and denote by $\{n^\alpha\}_{\alpha=1}^k$ the normal bundle of $\Sigma$ in a neighborhood of $\vec{F}_1$. Without confusion, we assume this neighborhood is still $U\cap \Sigma$. We define a set $V\subset U\cap \Sigma$ as follows:
$$
V=\{\vec{F}:\vec{F}\in U\cap \Sigma,\quad \la\vec{F}, e_i\ra\neq 0\quad \text{for}\quad i=1,\cdots,n\}
$$
We claim that $V$ is an open dense set in $U\cap \Sigma$.\\
\indent It is obvious that $V$ is open. If $V$ is not dense, without loss of generality, we can suppose that there is an open set $W$ in $U\cap \Sigma$ such that $\la\vec{F}, e_1\ra\equiv 0$ in $W$. This gives a representation for the position vector $\vec{F}$ of $\Sigma$ in $W$ as follows:
\begin{align}
    \vec{F}&=\vec{F}^{\bot}+\sum_{i=1}^{n}\la\vec{F},e_i\ra e_i; \notag\\
    &=\sum_{i=2}^{n}\la\vec{F}, e_i\ra e_i;
\end{align}
Then we can take $\{\la\vec{F}, e_2\ra, \cdots, \la\vec{F},e_n\ra\}$ as a coordinate of $W$. This leads to a contradiction since such coordinates implies we have a diffeomorphism from $W$ to an open set of $\R^{n-1}$. However $W$ is an $n$ dimensional open set. Hence $W$ is empty and $V$ is an open dense set of $U\cap \Sigma$. \\
\indent For any normal vector $n^\alpha$, $A^{\alpha}$ denotes the second fundamental form  $(h _{\alpha,ij})$, where $h _{\alpha,ij}=\la \bnb_{e_i}e_j, n^{\alpha}\ra$ and $\bnb$ is the {\Cd} of $\R^{n+m}$. We define the following sets:
$$
V_k=\{\vec{F}:\vec{F}\in V,\quad \mathrm{rank}(A^{\alpha})=k\} \quad \text{for $k=0,1,\cdots, n$}.
$$
It is easy to see that $V=V_0\cup \cup_{k=1}V_k$ and $A^{\alpha}\equiv 0$ on $V_0$. Assume we can show that $V_0$ is dense in $V$. By the continuity of $A^{\alpha}$, we will obtain that $A^{\alpha}\equiv 0$ in $V$. Since $V$ is dense in $U\cap \Sigma$, $A^{\alpha}\equiv 0$ in $U\cap \Sigma$ for any normal vector $n^\alpha$.  This gives that $\Sigma$ is totally geodesic in $U$.\\
\indent Next we show that $V_0$ is dense in $V$. Let $V_k^0$ be the interior of $V_k$ for $k\geq 1$. To prove the denseness of $V_0$ in $V$, it is suffice to prove that $V_k^0$ is empty for $k\geq 1$.\\
\indent Fix $k\geq 1$. Suppose $V_k^0$ is not empty. We emphasize it is an $n$-dimensional  manifold in $\Sigma$. Let $\vec{F}$ be any point in $V_k^0$ written as
\begin{equation}
    \vec{F}=\sum_{i=1}^n\la {F},e_i\ra e_i
    \end{equation}
    Then the map $T:V_k^0\rightarrow \R^n$ given by
    \begin{equation}
        T(\vec{F})=(\la F,e_1\ra,\cdots, \la F,e_n\ra), \vec{F}\in V_k^0
    \end{equation}
    is a local diffeomorphism on $V_k^0$.\\
 \indent    Since $\la \vec{F}, n^\alpha\ra \equiv 0$, taking the derivatives {\wrt} $\{e_i\}_{i=1}^{n}$ gives that
\be\label{eq:midterm}
T(\vec{F})A^\alpha=\sum_k\la \vec{F}, e_k\ra h_{\alpha,ik }\equiv 0;
\ene
Here we used that $\bnb_{e_i}n^{\alpha}=-h_{\alpha,ik}e_k+\sum_{\beta}\la \bnb_{e_i}n^{\alpha}, n^{\beta}\ra n^{\beta}$ and $e_i\la \vec{F}, n^\alpha\ra\equiv 0$.

Consequently $T(\vec{F})\subset ker (A^\alpha)$ which is an $(n-k)$-dimensional submanifold of $\R^n$. This leads to a contradiction. Hence $V_k^0$ is empty for $k\geq 1$. Finally $\Sigma$ is totally geodesic in $U$. The proof is complete.
\ep
As a result, we obtain the following rigidity for self-shrinkers based on an integral technique.
\bt\label{st:A:self-shrinker}  Let $\Gamma(f)$ be a self-shrinker in $\R^{n+m}$, where $f:E\subset\R^n \rightarrow \R^m$ is a smooth map with singular values satisfying $ \lambda_i\lambda_j \leq 1$ for all $i\neq j$. Suppose one of the following conditions holds:
\begin{itemize}
	\item[(i)] $E=\R^n$;
	\item [(ii)] $E=\R^n_{+}=\{(x_1,\cdots,x_{n-1},x_n):x_n>0\}$, $\sup_E |Df|\leq \mu<1$ where $\mu$ is a fixed constant, $f\in C(\bar{E})$ and $f(0)=0$,
\end{itemize}
then $\Gamma(f)$ is an $n$-dimensional plane through the origin over $E$.
\et
\br The following proof is based on the thesis of the second author in \cite[Chapter 4]{Zhou15}. The conclusion of item (ii) is much stronger than item (ii) in Theorem 4.1, because of no linear assumption on the boundary. Item (i) has been obtained in \cite[Theorem 10,(i)]{DW11} with an elliptic method.
\er
\bp For simplicity, we set
$$
\mathcal{A } :=\sum_{i,k}\lambda_i^2  h_{n+i,ik} ^2+\sum_{i,j,\alpha} h_{\alpha,ij} ^2+2\sum_{i<j,k}\lambda_i\lambda_j h_{n+i,jk}h_{n+j,ik}.
$$
Then \eqref{eq:st_ad} can be rewritten as
\begin{equation} \label{eq:estd}
\Delta  \ln(\ast\Omega) - \F{1}{2}\la\vec{F},\nb  \ln(\ast\Omega)\ra +\mathcal{A }\equiv 0.
\end{equation}
Notice that $\nb  \ln(\ast\Omega)=\F{\nb(\ast\Omega)}{\ast\Omega}$ and
\begin{align}
	|\nb\ast\Omega|^{2} %=\sum_i|\nb_{e_i}\Omega|^{2}
	&=\sum_k(\sum_i\Omega(e_1,\cdots,\bnb_{e_i}e_{k},\cdots, e_n))^2 \notag\\
	&=\sum_k\big(\sum_{i,\alpha}h_{\alpha,ik}\Omega(e_1,\cdots,\underset{ i -th}{e_\alpha},\cdots, e_n)\big)^2 \label{eq:md:1} \\
	&=\sum_k(\sum_{i}\lambda_i h_{n+i,ik})^{2}(*\Omega)^2,\label{eq:md:2}
\end{align}
we have
\begin{align}
	\mathcal{A} -\F{1}{2n}|\nb   \ln(\ast\Omega) |^{2}&= \mathcal{A } -\F{1}{2n}\sum_{k}(\sum_i\lambda_i h_{n+i,ik})^{2}\notag \\
	&\geq \mathcal{A}-\F{1}{2}\sum_{i,k} \lambda_i^{2} h _{n+i,ik} ^{2}\notag\\
	&\geq \F{1}{2} \sum_{i,k}\lambda_i^2  h_{n+i,ik}^2+ \sum_{i,j,\alpha} h_{\alpha,ij} ^2+2\sum_{i<j,k}\lambda_i\lambda_jh_{n+i,jk}h_{n+j,ik};\notag\\
	&\geq \F{1}{2} \sum_{i,k}\lambda_i^2  h_{n+i,ik} ^2+\sum_{\alpha,i}h_{\alpha,ii}^{2}\notag\\
	&+\sum_{i<j,k}\big( h_{n+i,jk} ^2+ h_{n+j,ik} ^2+2\lambda_i\lambda_jh_{n+i,jk}h_{n+j,ik}\big) \label{eq:get0}\\
	&\geq 0.\notag
\end{align}
In the first inequality, we applied the Cauchy inequality  $(\sum_i\lambda_ih_{n+i,ik} )^2\leq n  \sum_{i}\lambda_i^2 h_{n+i,ik} ^2 $.
In the last inequality, we used the fact that $ \lambda_i\lambda_j  \leq 1$.

Now we use a similar technique as in \cite[Lemma 3.10]{Zhou18a-d}.  Fix $r\geq 1$, we denote by $\phi$ a compact supported smooth function in $\R^{n+m}$
such that $\phi\equiv 1$ on $B_{r}(z_r)$ and $\phi\equiv 0$ outside of $B_{r+1}(z_r)$ with
$|\nb \phi|\leq |D\phi|\leq 2$. Here $D\phi$ and $\nb \phi$ are the gradient of $\phi$ in
$\R^{n+k}$ and $\Sigma$, respectively, and $z_r$ is a point in $\R^{n+m}$ to be determined later.
Multiplying \eqref{eq:estd}  by $\phi^{2}\ex$ and integrating over $\Gamma(f)$, we obtain
\begin{align}
	0&= \int_{\Gamma(f)} \phi^{2} div_{\Gamma(f)}(\ex \nb \ln(\ast\Omega) ) + \int_{\Gamma(f)}\phi^{2}\ex \mathcal{A}\notag\\
	&= -\int_{\Gamma(f)} 2\phi\la\nb \phi, \nb \ln(\ast\Omega) \ra \ex + \int_{\Gamma(f)}\phi^{2}\ex \mathcal{A}\notag\\
	&\geq -2n\int_{\Gamma(f)}|\nb\phi|^{2}\ex +\int_{\Gamma(f)}\phi^{2}\ex(\mathcal{A}-\F{|\nb \ln(\ast\Omega) |^{2}}{2n}).\label{eq:e_d}
\end{align}
In the last step above, we used that $2|\phi\la \nb\phi, \nb \ln(\ast\Omega) \ra|\leq 2n|\nb\phi|^{2}+\phi^2\F{|\nb \ln(\ast\Omega) |^2}{2n}$. By our assumption of $\phi$, \eqref{eq:e_d} implies that
\begin{equation}\label{det:D}
\begin{aligned}
	\int_{\Gamma(f)\cap B_{r}(z_r)}\ex(\mathcal{A}-\F{|\nb \ln(\ast\Omega) |^{2}}{2n})&\leq 2n\int_{\Gamma(f)\cap B_{r+1}(z_r)}|\nb\phi|^{2}\ex\\
	&\leq C(n,m) r^{n}e^{-\F{r^2}{4}}.
\end{aligned}
\end{equation}
Here we used the fact that $\Gamma(f)$ has the polynomial growth property in both cases. In the case of item (i), this property was obtained in \cite{CZ13} and \cite{DX13}. In the case of item (ii), such property is easily derived from the assumption $|Df|\leq \mu<1$.\\
\indent In the case of item (i), we choose $z_r$ as the origin of $\R^{n+m}$. In the case of item (ii), $z_r=(0,0,\cdots, 0,\underset{n-th }{r+1}, 0,\cdots, 0)$. Letting $r$ go to infinity, \eqref{eq:get0} and \eqref{det:D} indicate that
\begin{align*}
	0&\geq \mathcal{A}-\F{|\nb  \ln(\ast\Omega)|^2}{2n}\\
	&\geq \F{1}{2} \sum_{i,k}\lambda_i^2  h_{n+i,ik} ^2+\sum_{i,k} h_{n+i,ik} ^{2}+\sum_{i<j,k}\big( h_{n+i,jk} ^2+ h_{n+j,ik} ^2+2\lambda_i\lambda_jh_{n+i,jk}h_{n+j,ik}\big).
\end{align*}
on any interior point of $\R^n$ or $\R^n_+$.
Since $ \lambda_i\lambda_j  \leq 1$ for any $i\neq j$, we conclude that
\begin{align}
		& h_{n+i,ik}=0\quad &\text{for any $i, k$;}\label{eq:est_b}\\
	& h_{n+i,jk} ^2+ h_{n+j,ik} ^2+2\lambda_i\lambda_jh_{n+i,jk}h_{n+j,ik}=0\quad &\text{for any $i,j,k$.}\label{eq:est_c}
\end{align}

Next, we claim that the mean curvature vector of $\Sigma$ vanishes, i.e.
\begin{equation}\label{eq:min}
\vec{H}= \sum_{i} (\sum_j h_{n+i,jj})e_{n+i}\equiv 0.
\end{equation}
Item (i) and Item (ii) are both concluded from Theorem \ref{thm:v_normal}.  \\
\indent Now fix any $i_0\in\{1,\cdots,m\}$, and we proceed as follows:
\begin{enumerate}
	\item By \eqref{eq:est_b}, $h_{n+i_0,i_0i_0}=0$.
	\item Fix $j\neq i_0$. \begin{enumerate}
		\item If $ \lambda_{i_0}\lambda_j \leq  1-\delta<1$ for some $\delta\in (0,1)$,  \eqref{eq:est_c} gives that
		\begin{align*}
			0=&\delta( h_{n+i_0,jk} ^2+ h_{n+j,i_0k} ^2)+(1-\delta)(h_{n+i_0,jk} ^2+ h_{n+j,i_0k} ^2)\\
			&+2\F{\lambda_{i_0}\lambda_j}{1-\delta}h_{n+i_0,jk}h_{n+j,i_0k} .
		\end{align*}
		Then $h_{n+i_0,jk}=0$ for any $k$. Let $k=j$, then we get $h_{n+i_0,jj}=0$.
		\item Otherwise, it holds that $\lambda_{i_0}\lambda_j =1$. Then $\lambda_{j}\neq 0$, \eqref{eq:est_b} implies that $h_{n+j,jk}=0$ for any $k$. In particular, $h_{n+j,ji_0}=0$.  With this fact, \eqref{eq:est_c} indicates that
		\begin{align*}
		0= h_{n+i_0,jj} ^2+ h_{n+j,i_0j}^2+2\lambda_i\lambda_jh_{n+i_0,jj}h_{n+j,i_0j}= h_{n+i_0,jj} ^2.
			\end{align*}
		Hence $h_{n+i_0,jj}=0$.
	\end{enumerate}
    \end{enumerate}
As a result, we conclude that $h_{n+i_0,jj}=0$ for any $j\neq i_0$. Consequently, $\sum_{j}h_{n+i_0,jj}=0$. Since we choose $i_0$ arbitrarily, the claim in \eqref{eq:min} holds true. The proof is complete.
\ep
