\subsection{Smoothness of {\Lp} self-shrinker  graphs}\label{Sec smooth}

In this section we derive the smoothness of {\Lp} minimal-type graphs in Theorem \ref{smooth:c-minimal}. We will generalize \cite[Theorem 5.3]{Fischer80} and \cite[Theorem 4.1]{Wang2004} to the setting of {\Lp} self-shrinkers.\\
\indent The following condition will be sufficient for our purposes in the proof of Theorem \ref{main:thm:A}.
\begin{definition}\label{lp:strictly:decreasing} Let $f:E\subset \R^n\rightarrow\R^m$ be a {\Lp} map. We say that $f$ is \textit{strictly length decreasing} if  $ \lambda_i  <1-\Sc$ for any $i  \in \{1,2,\cdots, n\}$ and for some constant $\Sc\in (0,1)$, whenever $df$ is well-defined and $\lambda_i's$ are the singular values of $df$.
    \end{definition}
Now we use a more general definition including minimal graphs and self-shrinkers in Euclidean spaces.
\begin{definition} For any constant $c\geq 0$, an $n$-dimensional smooth $c$-\textit{minimal} submanifold $\Sigma$ in $\R^{n+m}$ is a stationary point of the following area functional $\mathcal{F}(\Sigma)$ given by
    \begin{equation}
          \mathcal{F}(\Sigma):=\int_{\Sigma}\exp(-c\F{|z|^2}{4})d\mathcal{H}^n\quad
        \end{equation}
where $z=(x_1,\cdots, x_n, y^1,\cdots, y^m)\in\Sigma$ and $\mathcal{H}^n$ is the $n$-dimensional Hausdorff measure.
    \end{definition}
 \begin{remark} A $0$-minimal submanifold is precisely a minimal submanifold, and a $1$-minimal submanifold is precisely a self-shrinker.
     \end{remark}
     \indent Suppose $f$ is a {\Lp} map from $E$ into $\R^m$. Then $\mathcal{F}(\Gamma(f))$ takes the form
     $$
     \mathcal{F}(\Gamma(f))=\int_{E}\exp \big(-c\F{|\vec{F}|^2}{4}\big)\sqrt{{\rm det}(I+df^T df)}dx
     $$
where   $|\vec{F}|^2=\sum_{i=1}^n x_i^2+\sum_{A=1}^m (f^A)^2$.
\begin{definition}\label{weak:solution:A}  We say that a {\Lp} function $f:E\subset \R^n\rightarrow \R^m$ is \emph{a weak solution to the $c$-minimal surface system} if it satisfies that
    \begin{equation}
    \begin{aligned}
        &\int_{E}\exp  \big( -c\F{|\vec{F}|^2}{4}\big)\bigg(  \sum_{i,j,A}\sqrt{g}g^{ij}\la \F{\P f^{A}} {\P x_i}, \F{\P \vp^{A}}{\P x_j}\ra -\F{1}{2}c\la \vec{F},\vp\ra\bigg )  dx =0
        \end{aligned}
        \end{equation}
%where $g,g^{ij}$ are given in \eqref{coe:g}
for any  map $\vp =(\vp ^1 ,\cdots, \vp ^m )\in C_{c}^1(E;\R^m)$.
    \end{definition}
 Let $f$ be as in \eqref{weak:solution:A}. Then for each $A=1,\cdots,m$, $f^A$ is the weak solution to the following elliptic equation
 \begin{equation}\label{general:equation}
     g^{ij}\F{\P^2 f^A}{\P x_i\P x_j}+cq(f,\F{\P f^A}{\P x_1},\cdots,\F{\P f^A}{\P x_n})=0,\quad A=1,\cdots, m,
     \end{equation}
where $q$ is smooth with respect to each of its components and $(g^{ij})$ is a smooth matrix-value function depending on  $df^1,df^2,\cdots,df^m$. Then the first variation of $\mathcal{F}(\Gamma(f))$, still denoted by $\vec{H}$, satisfies that
\begin{equation}\label{first:variation}
    \vec{H}+c\F{\vec{F}^{\bot}}{2}=0.
    \end{equation}
   \indent   The following result is implicitly used in the proof of \cite[Theorem 4.1]{Wang2004}. For the convenience of the readers, we include its proof here.
     \begin{theorem}\label{lpcone} Suppose $T$ is an $n$-dimensional {\Lp} strictly length decreasing minimal cone as a graph in $\R^{n+m}$, which is smooth away from vertex. Then $T$ is a plane.
\end{theorem}
\bp In the case of $n=1$, $T$ is the union of two half lines intersecting at the vertex. It is contained in a plane in $\R^{n+m}$. The conclusion is obvious.\\
