\end{align*}
For any $X=(x,t)\in W$, % let $\{\mathcal{V}_i:i=1,\cdots,k\}$ be the smooth unit vector fields near $x$.\\
  any integer $l\geq 0$ and any $\alpha \in (0,1]$, %  $D_tf(X)$ and $D^k_{\mathcal{V}_1,\cdots,\mathcal{V}_k}f(X)$ be the covariant derivative of $f$.
set
\begin{gather*}
    |D_{x}^lD_t^jf|(X):=\sup_{\mathcal{V}_1,\cdots,\mathcal{V}_l}|D^l_{\mathcal{V}_1,\cdots,\mathcal{V}_l}D_t^jf|(X);\\
    [D_{x}^lD_t^jf]_\alpha(X):=\sup_{\mathcal{V}_1,\cdots,\mathcal{V}_l}[D^l_{\mathcal{V}_1,\cdots,\mathcal{V}_l}D_t^jf]_\alpha(X);\\
