For the short-time existence of the MCF in \eqref{MCF3}, the parabolic system \eqref{MCF} admits an analysis analogous to that of a scalar parabolic equation.
\bl \label{lm:st:existence} Suppose $\psi:\bar{E}\rightarrow \R^m$ is smooth. Then there exists $\Sc>0$ such that the mean curvature flow in \eqref{MCF3} exists smoothly on $[0,\Sc)$.
    \el
     The strategy is to generalize the proof of Lieberman \cite[Theorem 8.2]{Lieberman1996} in the setting of \eqref{MCF3} on Riemannian manifolds.
    \begin{proof}
     We give a sketch of the proof on Riemannian manifolds for completeness.
Fix $\theta\in (0,1)$ and denote $V=\bar{E}\times [0,\Sc)$, where $\Sc$ is a positive constant to be determined later.  Set $\zeta:=  |\psi|_{1+\theta, V}+1 $, here $\psi(x,t)\equiv \psi(x)$. Consider the set
    \begin{equation}\label{de:At}
        \mathcal{F}:=\{ v(x,t)\in H_{1+\theta}(V): |v|_{1+\theta,V} \leq \zeta \},
    \end{equation}
    It is obvious that $\psi\in \mathcal{F}$.

    Now define an operator $J:  \mathcal{F}\rightarrow H_{1+\theta}(V)$ by setting  $Jv=u$ if, in any local coordinate $\{x_{1}, \ldots,x_{n}\}$ on $E$, it holds that
     \begin{equation} \label{def:AB}
   \left\{\begin{aligned}
    L^A(v)[u^{A}] &=0,\quad A=1\cdots,m\quad{\text{where}}\quad L^A(v): =-\P_t  +g^{ij}(v) \partial_{ij};
    \\ u(x,0)&=\psi(x),\ x\in E; \quad u(x,t)=\psi(x),\  x \in \P E,
    \end{aligned}\right.
     \end{equation}
     where $g_{ij}(v)  =\delta_{ij} +\sum _{A}v_{i}^{A}v_{j}^{A}$ and  $(g^{ij}(v)) =(g_{ij}(v)) ^{-1}$.\\
    \indent Since $v\in H_{1+\theta}(V)$ is fixed, $ I\geq (g^{ij})\geq \frac{1}{C} I$, where $I$ is the identity matrix and $C$ is a positive constant depending  only  on $v$. Thus \eqref{def:AB} is actually a system of m Cauchy-Dirichlet problems with bounded $C^\theta(E)$ coefficients.
    The Perron process for \eqref{def:AB} for parabolic systems,  \cite[Chapter III, Section 4]{Lieberman1996}), and the comparison principle, remain valid on Riemannian manifolds. Therefore, the conclusion of \cite[Chapter V, Theorem 5.14]{Lieberman1996} still holds for \eqref{def:AB} on $E$. Namely, for each $A=1,\cdots, m$, there exists a unique solution $u^A\in H_{2+\alpha}  (\bar{E}\times [0,\Sc))$ to \eqref{def:AB}, for some $\alpha\in (0,1)$. Moreover for $u=(u^1,\cdots, u^A)$, it holds that
    \begin{equation*}
    	|u|_{H_{1+\theta}} (V)\leq C(\zeta)|\psi|_{1+\theta}\leq C(\zeta).
  %      \sup_{\partial E \times [0,\Sc]}|D^2u|^2+\sup_{  \partial E \times [0,\Sc]}|\F{\P u}{\P t}|\leq C(v)\leq C(\zeta).
    \end{equation*}
 %Following the classical Schauder estimates, all the $k$-th derivatives of $u(x,t)$ are uniformly bounded above by some positive constant $C(k,\zeta)$.
   By the Newton-Leibniz formula,
    \begin{equation*}
   % \sup_{E\times [0,T]  }
     |u-\psi|_{H_{2+\alpha}(V)}   \leq C( \zeta)\Sc.
       % \sup_{\P E}|D^2(u-\psi)|^2+\sup_{\P E}|\F{\P (u-\psi)}{\P t}|\leq C(3,\mu)\Sc.
    \end{equation*}
When $\psi\equiv 0$, this implies that $J$ is continuous.
One can choose $\Sc$ small enough such that $u$ is contained in $\mathcal{F}$, and thus $J$ is a map from $\mathcal{F}$ to $\mathcal{F}$. Notice that $\mathcal{F}$ is a compact and convex set. Applying the Schauder fixed point theorem \cite[Theorem 8.1]{Lieberman1996}, there exists a fixed point $u\in \mathcal{F}$ such that $Ju=u$. Thus we obtain the short-time existence of the MCF flow \eqref{MCF3}.
\end{proof}
\subsection{The long-time existence}
	Suppose the MCF $F(x,t)=(x,f_{t}(x))$ in \eqref{MCF3} exists smoothly on $E\times[0,T)$.
 \bl\label{first:step:MCF} Suppose the assumption \eqref{condition:A} holds. Then there exists $\Sc \in (0,1)$, such that
\begin{equation}\label{deLA}
    \sup_{E}|Df_t|\leq 1-\Sc
\end{equation}
for any $t\in [0, T)$, where $\Sc $  depends only on $\psi$ and the assumption \eqref{condition:A}.
\el
\begin{proof}  Since $\sup_{\bar{E}}|D\psi|<1$, by continuity, there is a maximal time $T_0\leq T$ such that $\sup_{E}|Df_t|<1 $ on $[0,T_0)$. Taking $\mu=1$ and applying Proposition \ref{keyLboundary:estimate}, we derive
\begin{equation}
    \sup_{\P E}|Df_t|\leq \frac{ \omega(\psi)}{\delta} +  |D\psi |+32 n \delta   |D^{2} \psi |<1-\Sc
\end{equation}
for any fixed $\delta\in (0, \delta_0]$ satisfying \eqref{condition:A} and $t\in [0,T_0)$. Here $\Sc$ depends  only on assumption \eqref{condition:A}. In particular, for notation abuse, $\sup_E|D\psi|<1-\Sc$.
By Proposition \ref{prop:preserved}, this implies that  $\sup_{E}|Df_t|<1-\Sc$ for any $t\in [0,T_0)$. Since $T_0$ is maximal, it follows that
$T_0=T$.
\end{proof}
\rm The long-time existence of the MCF flow \eqref{MCF3} under the assumption \eqref{condition:A} follows from Lemma \ref{first:step:MCF} and Theorem \ref{lp:self-shrinker}.
\bl\label{second:step:MCF}Suppose the assumption \eqref{condition:A} holds. Then the graphic mean curvature flow $F(x,t)$ in \eqref{MCF3} can be extended over time $T$.
\el
\begin{proof}
The main tools we will use are the local regularity theory for mean curvature flow, established by White  \cite{White2005,White21}. This technique was first employed by Wang \cite{Wang2002} to show long-time existence for the mean curvature flow of closed graphs in arbitrary codimension. We adopt Wang's method with a modification to tackle the same problem for the MCF flow in \eqref{MCF3} with boundary.

 Assume $E$ is isometrically embedded in to  Euclidean space $\R^{n_0}$ for some sufficiently large $n_0$. Fix a space-time point $(Y,T)\in (\R^{n_0+m},\R_+)$. Define the backward heat kernel by
\begin{equation}
    \rho_{(Y,T)}(y,t):=\frac{1}{ \big(4\pi(T-t)\big) ^{\frac{n}{2}} }\exp\bigg( -\F{|y-Y|^2}{4(T-t)}\bigg),\quad y\in \R^{n_0}\times  \R^m, t<T,
    \end{equation}
here $n$ is the dimension of $F(x,t)$ as a submanifold in $\R^{n_0+m}$.
Define the Gaussian density of the MCF flow $F(x,t)$ in \eqref{MCF3} by
\begin{equation}\label{existence:Gauss:density}
    \Theta(Y,T):=\lim_{t\rightarrow T}\int_{  F_t(E)}\phi(|y-Y|)\rho_{Y,T}(y,t)\rm d  \mathcal{H}^n,
    \end{equation}
    where $F_t(E)$ denotes the graph of $f_t(x)$ over $E$, $\mathcal{H}^n$ denotes the $n$-dimensional \rm{Hausdorff} measure, and $\phi(t)\in C_{c}^{\infty}[0,1]$  with $\phi\equiv 1$ in $[0,\F{1}{2}]$ and $\phi'\leq 0$. The existence in \eqref{existence:Gauss:density} follows from \cite[Corollary 6.2]{White21}, since according to \eqref{deLA}, the area of $F_t(E)$ is uniformly bounded,
    \begin{equation} \label{del:estimates}
       \mathcal{H}^n (F_t(E))\leq \int_{E}\sqrt{(1+\lambda_1^2)\cdots (1+\lambda_n^2)}  d \mathcal{H}^n\leq  2^{\F{n}{2}}\mathcal{H}^n(E),
        \end{equation}
       for any $t\in [0, T)$. It is not hard to see that $\Theta(Y,T)$ is independent of the choice of $\phi$ and the isometric embedding of $E$ .

        Let $Y=(u,v)$ be any space limit of $F(x,t)$ in $\R^{n_0+m}$ as $t\rightarrow T$, where $u\in \bar{E}$ and $v\in \R^m$. To compute $\Theta(Y,T)$, we consider the parabolic dilation of space-time space $\R^{n_0}\times \R^m \times [0,+\infty)$, given by
       \begin{equation}\label{parab dila}
         \mathcal{D} _{\iota}(y,t)=(     \iota(y-Y),\iota^2(t-T))=(\iota(x-u), \iota (f_t(x)-v), \iota^2(t-T)).
           \end{equation}
  Let $S$ be the total space of the mean curvature flow $F_t(E)$ for all $t\in [0, T)$. Denote by $S^{\iota}$  the image $  \mathcal{D}_\iota(S)\subset \R^{n_0+m}\times [-\iota^2T, 0]$. By \eqref{del:estimates} and  \cite[Section 10]{White21} , for any sequence $\{\iota_i\}_{i=1}^\infty$ converging to $\infty$, there exists a subsequence, still denoted by $\{\iota_i\}_{i=1}^\infty$, such that $S^{\iota_i}$ converges to a tangent flow $S^\infty\subset \R^{n_0+m}\times ( -\infty, 0]$. Moreover, $S^\infty$ is invariant under $  \mathcal{D}_\iota$, i.e. $S^\infty$ is  self-similar. For each $t<0$, $S^\infty(t)$ denotes the space slice of the tangent flow $S^\infty$. Furthermore, $S^{\infty}(t)= \sqrt{-t} S^{\infty }(-1)$, where $S^{\infty}(-1)$ is given by the graph of a function $f_\infty$,  which is a {\Lp} weak-solution to the $1$-minimal surface system(  self-shrinker \eqref{first:variation}) over a domain $E'$. \\
  \indent From Lemma \ref{first:step:MCF}, each $f_t$ is strictly length decreasing. Notice that the property of strictly length decreasing is preserved under the parabolic dilation \eqref{parab dila}. Hence, $f_\infty$ is {\Lp}  and strictly length decreasing.


   If $Y$ lies in the interior of $E\times \R^{m}$, then $E'$ should be $T_u E$ viewed as $\R^n$. If $Y$ lies on the boundary of $E\times \R^{m}$, then $E'$ is the half-space $\R^n_+ $. By Theorem \ref{lp:self-shrinker}, in both cases, $f_{\infty}$ must be a linear map. Therefore in the first case $S^{\infty}(-1)$ is an $n$-dimensional linear submanifold in $\R^{n_0+m}$ through $0$. In the second case $S^{\infty}(-1)$ is a half space of an $n$-dimensional linear submanifold in $\R^{n_0+m}$. As a result, in the first case, $\Theta(Y,T)=1$ and in the second case, $\Theta(Y,T)=\F{1}{2}$. By \cite{White2005}, the mean curvature flow $F(x,t)$ can be extended smoothly over time $T$ in both cases.
  \end{proof}
\subsection{The limit} Combining Lemma \ref{first:step:MCF} and Lemma \ref{second:step:MCF} together, we conclude that,  under the assumption \eqref{condition:A}, the mean curvature flow in \eqref{MCF3} $F(x,t)$ exists for all time. Moreover $F(x,t)=(x, f(x,t))$, where $f(x,t)$ satisfies $\sup_{E}|Df_{t}|<1-\Sc$ for some constant $\Sc\in (0,1)$ independent of $t$. Therefore, $f(x,t)$ is strictly length decreasing for all $t>0$. \\
\indent  In the closed manifold setting, Wang \cite{Wang2002} showed that the norm of the second fundamental form of $F(x,t)$ decays exponentially as $t\rightarrow \infty$. In our setting such a strong uniform $C^2$ estimate cannot be obtained.\\
\indent In the following, let $\Sigma_t$ denote the graph of $f(x,t)$ for fixed $t$. In fact,  as the area element $\sqrt{g}$ satisfies $ \frac{d\sqrt{g}}{dt}=-|H|^{2}\sqrt{g}$, we see that the quantity  $\int_{	0}^{\infty}\int_{\Sigma_{t}}|H|^{2} d\mu dt$ is bounded by integration. Here $d\mu$ is the induced volume form. So there exists a sequence $\Sigma_{t_{i}}$ such that $\int_{\Sigma_{t_{i}}}|H|^{2}d\mu\rightarrow0$ as $ t_{i}\rightarrow\infty$. \\
\indent Together with the fact that $\sup_{E}|Df_{t_{i}}|<1-\Sc$, up to taking a subsequence, we have that $\Sigma_{t_{i}}\rightarrow\Sigma$ in the sense of varifold such that $\Sigma=(x,f(x))$ with $ \int _{\Sigma}|H|^{2}d\mu=0$, and $\sup_{E}|Df|\leq 1-\Sc$ for some Lipschitz map $f:\bar{E}\rightarrow\R^{m}$ with $f=\psi$ on $\P E$. Namely, $f$ is strictly length decreasing as a weak solution to the minimal surface system. By \cite[Theorem 4.1]{Wang2004} or Theorem \ref{smooth:c-minimal}, $f$ is smooth on $E$.\\
\indent Consequently, we obtain the desirable solution to the minimal surface system \eqref{DP:MSS} under the assumption \eqref{condition:A}. The proof is complete.
	\section{Proof of Theorem \ref{main:thm:B}}\label{Sec  pf thm:B}
The proof of Theorem \ref{main:thm:B} is divided into two parts: the existence part,  Section \ref{sec exist}, and the asymptotic behavior part,  Section \ref{sec asympt}. We emphasize that the boundary $\partial E$ may admit multiple components.

\subsection{The existence}\label{sec exist}
  Without loss of generality, suppose the origin $0$ is in $\R^{n}\setminus \bar{E}$. As a result the distance between the origin and $\P E$,   $d_0=d(0,\P E)>0$. Let $\mathrm B_r(0)\subset\R^{n}$ be the open ball  centered at the origin $0$ with radius $r$. Denote $Q_r:= E \cap\mathrm B_r(0)$. Then, for any $r>2d_0$, the boundary of $Q_r$ consists of two disjoint parts: $\P B_{r}(0)$ and $\P E$.

We claim that if $r$ is sufficiently large, we can choose $\delta_{0}=\delta_{0}(n,\partial E)>0$, which is independent of $r$ to guarantee that our conclusion holds.

Firstly, we fix $\eta_0>0$ such that the distance function $d(x)=d(x,\P E)$  is $C^{2}$ on  $E_{\eta_0}=\{x\in E: d(x,\P E)<\eta_0\}$. Suppose  $\F{r}{2}> \F{r_{0}}{2}:=  diam(\P E)+2\eta_0+d_0 $. Then  $E_{\eta_0}\subset B_{\frac{r}{2}}(0)$. Now the set $Q_{r,\eta_0}=\{x\in Q_{r}: d(x,\P Q_{r})<\eta_0\}$ consists of two disjoint parts: $E_{\eta_0}$ and $E'_{\eta_0} =\{x\in Q_{r}: d(x,\P B_r(0))<\eta_0\}$. Then the function $ \tilde{d}(x) :=d(x,\P Q_{r})$ on $Q_{r,\eta_0}$ satisfies
\begin{equation}
   \tilde{d}( x)=\left\{
\begin{aligned}
   &d(x),\quad \quad x\in E_{\eta_0};\\
   &d(x,\P B_{r}(0)), \quad  x\in E'_{\eta_0},
    \end{aligned}\right.
    \end{equation}
   due to the fact that set $E'_{\eta_0}$ is disjoint with $B_{\frac{r}{2}}(0)$.

  Similarly, we compute $-\Delta_{\Sigma_t} \tilde{d}(x)$ on $Q_{r}$ as in the proof of  Lemma \ref{lap}, where $\Sigma_t$ is the mean curvature flow in $Q_{r}\times \R^m$ in which the initial data is the graph of $\psi$. % given in \eqref{DP:MSS:Q}. On the set $E'_{\eta_0}$, $d(x)=d(x,\P B_{r}(0))$.
  Since $\P B_{r}(0)$ is strictly convex, arguing as in Remark \ref{delta0rmk} gives
    \begin{equation}
        -\Delta_{\Sigma_t}  \tilde{d}=-\Delta_{\Sigma_t}d(x,\P B_{r}(0))\geq 0 \quad \text{on}\  E'_{\eta_0}
       \end{equation}
  On the other hand, from Lemma \ref{lap}, there exists a constant $c_{0}=c_0(n,\partial E)>0$ which is independent of $r>r_0$, such that
   \begin{equation}
      -\Delta_{\Sigma_t}  \tilde{d}=-\Delta_{\Sigma_t} d\geq -c_0 \quad \text{on}\  E_{\eta_0}.
  \end{equation}
  In both cases, we have
  \begin{equation}
      -\Delta_{\Sigma_t} \tilde{d}\geq -c_0 \quad \text{on}\ Q_{r,\eta_0}.
      \end{equation}
By Remark \ref{remark:definitioneta}, the claim follows. %That is, $\delta_0$ can be chosen only depending on $\P E$ on $Q_r$ for any $r \geq r_0$.

Now we can prove verbatim as in Proposition \ref{keyLboundary:estimate} that there exists  $\tilde{\delta}_{0}=\tilde{ \delta}_{0}(n,\partial  E )>0$ such that for any $\delta\in (0,\tilde{\delta}_0)$,
\begin{align*}
    |Df_{t}(x)| \leq &    \frac{ w(\psi)}{\delta} +  |D\psi |+16n(1+\mu) \delta   |D^{2} \psi |, \quad \mbox{on} ~\partial Q_r \times [0,T),
\end{align*}
where $\mu=\sup_{Q_r \times [0,T)}|Df |^{2}$ and $\Sigma_t=(x,f_t(x))$ is the mean curvature flow on time interval $[0,T)$.

Arguing as in the proof of Theorem \ref{main:thm:A}, for any $\delta\in (0, \tilde{\delta}_0)$ and $\psi$ satisfying assumption \eqref{condition:B},  i.e.
\begin{equation}\label{condition:D}
    \F{w
        (\psi)}{\delta}+\sup
    _{E}|D\psi|+32 n\delta\sup_{E}|D^2\psi|<1-c,
\end{equation}
 the Dirichlet problem of the MSS \eqref{DP:MSS} admits a solution $f_r\in C^\infty(Q_r)\cap C(\bar{Q}_r)$ solving
\begin{equation}\label{DP:MSS:Q}
    \left\{
    \begin{aligned}
        g^{ij}(f_{r})(f_{r})^A_{ij}&=0\quad A=1,2,\cdots,m\quad\text{on} ~Q_r,\\
        f _{r}&=\psi \text{\quad on~}\P Q_r.
    \end{aligned}
    \right.
\end{equation}
Moreover, $\max_{Q_r}|Df_r|<1-c$. Also by the maximum principle, $\max_{Q_r}|f_r|\leq \max_{\bar{Q}_r}|\psi|$.\\
\indent By the Arzel\`{a}–Ascoli theorem, there exists a subsequence   $\{f_{r_i}\}_{i=1}^\infty$ converging to a {\Lp} function $f$ as the weak-solution to the following minimal surface system:
\begin{equation}
	\left\{
	\begin{aligned}
		g^{ij}(f ) f^A_{ij}&=0\quad A=1,2,\cdots,m\quad\text{on} ~E,\\
		f  &=\psi \text{\quad on~}\P E.
	\end{aligned}
	\right.
\end{equation}
Moreover $\sup_{E}|D f|\leq 1-c$ on $E$. Now $f$ is {\Lp} and strictly length decreasing on $E$. By \cite[Theorem 4.1]{Wang2004} or Theorem \ref{smooth:B}, $f$ is smooth on $E$. This gives the existence of Theorem \ref{main:thm:B}.

\subsection{The asymptotic behavior}\label{sec asympt}
We consider the asymptotic behavior of the solution $f$ to the MSS \eqref{DP:MSS} over $E$. Notice that the singular values  satisfy $\sup_{E}|Df|\leq 1-c$.
Now we blow down $\Gamma(f)$, the graph of $f$, following the idea of Simon \cite{Simon1983}. Namely consider the function $f_{k}(x):=k f(k^{-1}x)$ defined over $kE =\{y\in \R^n:ky\in E\}$. Let $\Gamma(f_{k})$ denote the graph of $f_k$ over $kE$.\\
\indent  Applying the classical compactness of stationary varifolds, there exists a subsequence $k_i\rightarrow\infty$ as $ i\rightarrow\infty$,  such that the sequence $\Gamma(f_{k_{i}})$ converges to a minimal cone $T$. Moreover $T$ is a graph of a strictly length decreasing Lipschitz function $f_\infty$, with $|Df_\infty|<1-c$ as the weak solution to the minimal surface system. By Theorem \ref{smooth:B}, $f_{\infty}$ is a linear map on $\R^{n}$. This implies that $\sup_{|x|\rightarrow +\infty}|Df-l|=0$, where $Df$ means the gradient of $f$. The proof is complete.

