	\Omega_a h^2 =\frac{h^2}{\rho_{c,0}} \rho_a(T_{\rm QCD}) \left[\frac{(m_a\, g_{*s})_{T_0}}{(m_a\, g_{*s})_{T_{\rm QCD}}}\right]\left( \frac{T_0}{T_{\rm QCD}} \right)^3,
