We are grateful to Benjamin Wesolowski for providing the ideas that led to the
general algorithm in Section~\ref{sc:generalcase}.
We thank Jean Kieffer and Damien Robert for fruitful discussions, and the isocrypt people for
their interest.
We thank Marc Houben for pointing us to~\cite[Thm~A.1]{TheoremAnnexe}.



\section{Background}\label{sec:background}

For an elliptic curve $E$ over a field $F$, we denote
by $\End(E)$ its ring of endomorphisms defined over $\overline F$, the algebraic closure of $F$.
We also assume that the characteristic $p$ of finite fields is greater than
$3$. For $p=2$ (resp. $p=3$), the algorithmic questions discussed in this paper are trivial
since all supersingular elliptic curves over $\mathbb F_4$ (resp.~$\mathbb
F_9$) are isomorphic.

Throughout this paper, we use the formalism of group schemes to describe
\emph{kernels} of (non-necessarily separable) isogenies, so that any nonzero
isogeny (even if it is purely inseparable) has a non-trivial
kernel. We refer to \cite{waterhouse1969abelian} for more details on this
formalism. In particular, for an elliptic curve $E$ defined over $\overline{\F_p}$, there
are bijections between proper left-ideals
in $\End(E)$, finite group subschemes in $E$, and isogenies with domain $E$ up to
post-composition by isomorphisms. This follows from the fact that all
left-ideals in $\End(E)$ are \emph{kernel ideals}, see \cite[Thm.~3.15]{waterhouse1969abelian}
for the cases where $\End(E)$ has
rank $1$ or $4$, and \cite[Thm.~20.(a)]{kani2009products} for the CM-case.
We also use the following convenient notation: given a
finite subgroup scheme $K$ of an elliptic curve $E$, we let $E\to E/K$ denote the geometric
quotient of $E$ by $K$, where $K$ acts by translation. Therefore, an elliptic
$E'$ is isomorphic to $E/K$ if and only if there exists an isogeny $E\to E'$
whose kernel is $K$. We call the map $E\to E/K$ the canonical isogeny
with kernel $K$.

The main family of curves that we consider are \emph{maximal} elliptic curves
over $\mathbb F_{p^2}$, 
i.e. elliptic curves whose number of rational points equals the Hasse-Weil
upper bound.
\begin{defi}
  Let $E$ be an elliptic curve over $\F_{p^2}$. We say that $E$
  is \emph{maximal} when $\#E(\F_{p^2})=(p+1)^2$.
\end{defi}

\begin{remq}\label{remq:Fp2model}
  Any supersingular curve $E$ over a field $k$ of characteristic $p>0$ is
  $\overline k$-isomorphic to a curve defined over $\F_{p^2}$, see~\cite[Prop.~42.1.7]{QuatAlg}.
  Therefore, for computational purposes, it is convenient to consider
  supersingular curves defined over $\F_{p^2}$. Moreover any such curve is
  $\overline{\mathbb F_p}$-isomorphic to a maximal curve $E'$
  (see~\cite[Lem.~4]{Deuring4People} and \cite[Prop.~5.1]{AbVarMax}), which
  has the convenient property that all endomorphisms and isogenies with domain
  $E$ are also defined over $\mathbb F_{p^2}$, see \cite[Lem.~5.7]{AbVarMax}.
\end{remq}

\subsection{Deuring correspondence}

We recall key concepts of the Deuring correspondence.
 For a more comprehensive study of the subject,
we refer to \cite{LerouxThesis} and \cite{QuatAlg}.



\subsubsection{Quaternion algebras.}

Let $p$ be a prime. We focus on the (unique up to isomorphism) quaternion
algebra $\B$ over $\mathbb Q$ which ramifies at $p$ and $\infty$.  The algebra
$\B$ is non-commutative, and it has dimension $4$ over $\Q$. When $p \equiv 3
\bmod 4$ a $\Q$-basis is $1,i,j,k$, where

\[
  i^2= -1, \ \ j^2= -p \ \  \text{and} \ \ k = i\, j= - j\, i.
\]

Any element $\alpha \in \B$ can be encoded by coordinates $(\alpha_0, \alpha_1,
\alpha_2, \alpha_3) \in \Q^4$, such that $\alpha = \alpha_0 + \alpha_1 i  +
\alpha_2 j + \alpha_3 k$. The \emph{conjugate} of
$\alpha=\alpha_0 + \alpha_1 i+\alpha_2 j +\alpha_3 k\in \B$ is
$\overline{\alpha}=\alpha_0 - \alpha_1 i  - \alpha_2 j - \alpha_3 k$. Its
\emph{reduced trace}
is $\Trd(\alpha)=\alpha + \overline\alpha = 2\alpha_0$ and its
\textit{reduced norm} is $\Nrd(\alpha)=\alpha \cdot \overline{\alpha} =
\alpha_0^2 + \alpha_1^2 + p(\alpha_2^2+\alpha_3^2) \in \Q$.  Every nonzero
$\alpha\in\B$ is invertible, i.e. there exists a unique $\beta\in\B$ such
that $\alpha\cdot\beta = \beta\cdot\alpha = 1$. 

We now focus on subrings
in $\B$ involved in the Deuring correspondence:

\begin{defi}[Quaternion order]
  An \textit{order} in $\B$ is a subring which has rank $4$ as a
  $\Z$-module.
  An order is \textit{maximal} when it is not contained in a strictly larger order.
\end{defi}

\begin{expl}
  Assume that $p \equiv 3 \bmod 4$.
  A non-maximal order of $\B$ is $\Z[i,j]$. This order is contained in
  $\Z [ i, \frac{1+k}{2}]$ \cite[Lem.~2]{KLPT}, which is maximal.
\end{expl}

\begin{defi}[Left/Right Order]
Let $I$ be a rank-$4$ $\Z$-module in $\B$. The \textit{left} and \emph{right}
orders of $I$ are:
\[\mathcal{O}_{L}(I) = \{ \alpha \in \B : \alpha I \subset I \}, \quad
    \mathcal{O}_{R}(I)  = \{ \alpha \in \B : I \alpha \subset I \}.\]

    When $I \subset \mathcal{O}_{L}(I)$ (or equivalently $I \subset
    \mathcal{O}_{R}(I)$, see \cite[Lem.~16.2.8]{QuatAlg}), we say that
  $I$ is an \textit{integral ideal}.
\end{defi}


Integral ideals in maximal orders are actually locally principal~\cite[Cor.~17.2.3]{QuatAlg}. It implies that the
completion $I \otimes \Z_{\ell}$ of an ideal $I\subset\mO$ at a
prime $\ell$ unramified in $\B$ generates a principal ideal in
$\mO\otimes\Z_\ell\cong \Mat_2(\Z_\ell)$. We study localizations in more
details in Section~\ref{section:adic}.


\begin{remq}
  An integral ideal $I$ is a left-$\mathcal{O}_{L}(I)$ ideal,
  and a right-$\mathcal{O}_{R}(I)$ ideal. When $\mathcal{O}_{L}(I)$
  (equivalently, $\mathcal{O}_{R}(I)$) is maximal, then $I$ is called a \textit{connecting ideal} for
  $\mathcal{O}_{L}(I)$ and $\mathcal{O}_{R}(I)$. If $\mathcal O_1, \mathcal
  O_2\subset\B$ are two maximal orders, we let $\Conn(\mathcal O_1,
  \mathcal O_2)$ denote  all integral connecting
  ideals. \end{remq}

\begin{defi}[Ideal norm]
 \cite[Thm.~16.1.3]{QuatAlg} 
 Let $I\subset\B$ be an ideal. The \emph{reduced norm} of $I$ is
 $\Nrd(I) = \gcd(\{ \Nrd(\alpha) \, : \, \alpha \in I \})$.
 Moreover, $\Nrd(I)^2 = [ \mathcal{O}_{L}(I) \, : \, I ] 
 = [ \mathcal{O}_{R}(I) \, : \, I ]$.
\end{defi}

\begin{prop} \cite[Lem.~16.3.7]{QuatAlg} 
  Let $\mathcal O_1, \mathcal O_2, \mathcal O_3\subset\B$ be three maximal
  orders.
  If $I\in\Conn(\mathcal O_1, \mathcal O_2)$ and $J\in\Conn(\mathcal
  O_2,\mathcal O_3)$, then $I\cdot J\in\Conn(\mathcal O_1, \mathcal O_3)$ and $\Nrd(I\cdot
  J)=\Nrd(I)\cdot\Nrd(J)$.
\end{prop}


\subsubsection{The correspondence.}
Endomorphism rings of supersingular elliptic curves are isomorphic to maximal
orders in $\B$. The purpose of Deuring correspondence is to provide a set of tools for representing
geometric objects related to supersingular elliptic curves as algebraic objects
in $\B$.

\begin{theo} \cite[Thm.~42.1.9]{QuatAlg} 
  Let $E$ be a supersingular elliptic curve defined over $\overline{\F_p}$.
  Then the endomorphism ring $\End(E)$ is isomorphic to a maximal order in $\B$.
\end{theo} 

Let $\mathcal O\subset\B$ be a maximal order isomorphic to the endomorphism
ring $\End(E)$ of a supersingular elliptic curve $E$ defined over $\overline{\F_q}$.
We will implicitly use the isomorphism $\End(E) \to \mO$ in
what follows.
There is an anti-equivalence between the category of supersingular elliptic curves over $\overline{\F_q}$
and the category of invertible left $\mathcal O$-modules. This anti-equivalence is
given explicitly via the contravariant functor $\Hom(\_, E)$, see \cite[Thm.~42.3.2]{QuatAlg}.
This equivalence establishes a dictionary
between the geometric world of supersingular elliptic curves
and the algebraic world of quaternion orders.

On the one hand, let $J$ be a left $\End(E)$-ideal. It defines a subgroup scheme
$E[J]:= \cap_{\alpha \in J}\ker \alpha$ in $E$, which is the kernel of an isogeny $\varphi_J:E \to E/E[J]$, see~\cite[42.2.1]{QuatAlg}. 
If $\varphi_J$ is separable, then
$E[J]=\{ P \in E(\overline {\F_q}) \mid \forall \alpha \in I, \, \alpha(P)=0 \}$.
On the other hand, let $\varphi: E \to E'$ be an isogeny. Then $I_\varphi:=\Hom(E',E)\varphi$ is a 
left $\End(E)$-ideal which connects the endomorphism rings of
$E$ and $E'\simeq E/\ker(\varphi)$, regarded as maximal orders in $\B$ up to
conjugation.
Moreover, for a left-ideal $J\subset\mathcal O$ and
$\psi:E \to E'$, we have that $J=I_{\varphi_{J}}$ and $\psi \cong \varphi_{I_{\psi}}$.
In particular we have a bijection between isomorphism classes (i.e. isogenies up
to post-composition by isomorphisms) of isogenies from $E$,
and left-ideals $I$ in $\mathcal O$.


In Table~\ref{table:Deuring} --- which is adapted from
\cite[Table~2.1]{LerouxThesis} --- we summarize the main dictionary in the Deuring correspondence.

\begin{table}
\centering
  \begin{tabular}{ | c || c |} 
    \hline
    Supersingular $j$-invariants over $\F_{p^2}$ & Isomorphism class of maximal order in $\B$  \\ 

    $j(E)$ up to Galois conjugacy  & $\mathcal{O} \cong \End(E)$  \\ 
    \hline
     Isomorphism class of $\varphi:E \to E'$ & $I_{\varphi}$ integral left
     $\mathcal O$-ideal  \\ 
    \hline
    $ \alpha \in \End(E)$ & principal ideal of $\mathcal O$ generated by the image of $\alpha$ \\
    \hline

    $\deg(\varphi)$ & $\Nrd( I_{\varphi})$ \\
    \hline
    $\widehat{\varphi}$ & $\overline{I_{\varphi}}$ \\
    \hline
    Composition $ \psi_2 \circ \psi_1: E_1 \to E_2 \to E_3$ & $I_{\psi_2 \circ \psi_1}
                                                              =I_{\psi_1} I_{\psi_2}$ \\
    \hline
  \end{tabular}
  \caption{Summary of the Deuring correspondence.\label{table:Deuring}}
\end{table}


\subsection{Efficient representations of isogenies}

In order to implement the constructions of this work, we have to
define what is a good representation of an isogeny. 
We will use the notion of \emph{efficient representation}
designed in \cite{endringpb,EffRpz}.


  A \textit{representation} of an isogeny $\varphi: E\to E'$ between elliptic curves defined over $\F_q$, is a set of
  data that contains the domain, the codomain, the degree $\deg(\varphi)$, and
  an algorithm to evaluate $\varphi$ on any point $P\in E(\F_{q'})$ for any
  finite extension $\F_{q'}/\F_{q}$. Notice that a bound on the degree (instead
  of the actual degree) would
  be sufficient since the degree can then be recovered via the CRT by
  using the Weil pairing in small torsion subgroups~\cite[Lem.~6.2]{EffRpz}.
  We say that a representation is \textit{efficient} if this data enable us
  to compute the image of a point $P \in E(\F_{q'})$ in time polynomial in
  both $\log(\deg(\varphi))$ and $\log(q')$. We say that it is \textit{compact} if the
  space needed to store the data is polynomial in $\log(\deg(\varphi))$ and
  $\log(q')$.  

\smallskip

The representation we will use is the \textit{ideal representation} which relies
on the Deuring correspondence.

\subsubsection{Ideal representation.}

The core idea of the ideal representation is to represent an isogeny $\varphi:E
\to E'$ via the ideal $I_\varphi\subset\End(E)$ of all endomorphisms
whose kernel contains $\ker\varphi$, seen as an ideal in a maximal order of
$\B$ isomorphic to $\End(E)$. In order to use this representation, we first
need to fix an embedding $\End(E)\hookrightarrow \B$. Although this only encodes the isomorphism
class of $\varphi$, knowing the codomain $E'$ enables us to determine $\varphi$ up to
post-composition by automorphisms. Consequently, in order to have a full
representation of $\varphi$, we need a bit
more data to discriminate these automorphisms.
We can disregard this subtlety in the present work: the order of $\Aut(E')$ is
at most $24$, so we can use exhaustive search on the automorphism group when
needed without harming the asymptotic
complexity. However, for efficient implementation and optimization, it might be
useful to add to the data structure representing the isogenies some information
to remove the ambiguity, for instance the action of the isogenies on some small
torsion subgroup. Note that if $j(E') \ne 0,1728$
then the only automorphisms of $E'$ are $\pm 1$~\cite[Appendix A, Prop.~1.2.(c)]{Silv}.


\begin{theo} 
  Given an efficient representation of a $\Z$-basis of $\End(E)$ and its
  image via an embedding $\End(E)\hookrightarrow \B$, then a $\Z$-basis of the ideal $I_{\varphi}$ provides a compact representation of $\varphi$.
  Assuming GRH, this representation is efficient.
\end{theo}

For more details, see \cite[Sec.~4.2 and C.1]{EffRpz}.
In this paper, we will work with $2\times 2$ matrices whose entries are
isogenies, which can conveniently be encoded via efficient representations.

\begin{prop}
  Let $E_1, E_2, E_1', E_2', E_1'', E_2''$ be elliptic curves defined over
  $\F_q$. Let $M = (\varphi_{ij})_{i,j\in\{1, 2\}}$ (resp. $N =
  (\psi_{ij})_{i,j\in\{1, 2\}}$) be a $2\times 2$ matrix of isogenies, where
  $\varphi_{ij}:E_j\to E_i'$ (resp. $\psi_{ij}:E_j'\to E_i''$). Then $M$ (resp.
  $N$) represents the isogeny $E_1\times E_2\to E_1'\times E_2'$ (resp.
  $E_1'\times E_2'\to E_1''\times E_2''$) defined as
  $\phi_M(P,Q)=(\varphi_{11}(P) + \varphi_{12}(Q), \varphi_{21}(P) +
  \varphi_{22}(Q))$ (resp. $\phi_N(P,Q)=(\psi_{11}(P) + \psi_{12}(Q), \psi_{21}(P) +
  \psi_{22}(Q))$). Moreover, the matrix product $N\cdot M =
  (\sum_{k\in\{1, 2\}} N_{ik}\circ M_{kj})_{i,j\in\{1, 2\}}$ represents an
  isogeny $E_1\times E_2\to E_1''\times E_2''$ and efficient representations of
  the entries of $N\cdot M$ can be computed in polynomial-time from efficient
  representations of the entries of $M$ and $N$.
\end{prop}

\begin{proof}
  The only thing that we need to prove is that we can compute efficient
  representations of compositions and sums of isogenies encoded with efficient
  representations. Algorithms for doing so are described in \cite[Sec.~6.1]{EffRpz}.
\end{proof}





\subsubsection{Knowing the endomorphism ring of a curve.} Throughout this
paper, we often say that the endomorphism ring of a supersingular elliptic
curve $E$ is ``known'' or ``given''. By this, we mean that efficient representations of a
$\Z$-basis $b_1,\ldots, b_4$ of $\End(E)$ is given, and that we also have
access to elements $\beta_1,\ldots, \beta_4\in\B$ such that the
$\Z$-module $\mathcal O$ generated by $\beta_1,\ldots, \beta_4$ in $\B$ is a maximal order
and the map $\End(E)\to\mathcal O$ sending $b_i$ to $\beta_i$ is a ring
isomorphism.


\subsection{Superspecial Abelian varieties}

The key theoretical result we rely on is the following existential
statement.

\begin{theo}\label{theo:Superspecial}(Deligne/Ogus/Shioda theorem) \cite[Thm.~3.5]{DelignTheo}
  Let $k$ be an algebraically closed field of characteristic $p > 0$. Let $E_1, \dots, E_g$ and 
  $E_1', \dots, E_g'$ be supersingular elliptic curves, where $g \ge 2$.
  Then there exists an isomorphism:
  \begin{equation*}
    E_1 \times \dots \times E_g \cong    E_1' \times \dots \times E_g'.
  \end{equation*}
\end{theo}

In other words, Theorem \ref{theo:Superspecial} states that there is only one superspecial abelian variety of dimension
$g \ge 2$, up to isomorphisms. We emphasize that we do not take into account the \textit{polarizations} of the
abelian varieties.

\begin{defi}
  An abelian variety $\mathcal{A}$ is called \textit{superspecial} when it is isomorphic to a product
  of supersingular elliptic curve.
\end{defi}

When $p\equiv 3\bmod 4$, there is a convenient supersingular elliptic curve
defined over $\mathbb F_p$ by the equation $y^2 = x^3 + x$. We denote this
special curve by $E_0$ throughout this paper. A useful feature of
this curve is that $\End(E_0)$ contains a subring isomorphic
to $\Z[i]$. A direct consequence of
Deligne/Ogus/Shioda theorem is that any superspecial variety of dimension $g$
defined over $\overline{\F_p}$ is $\overline{\F_p}$-isomorphic to $E_0^g$.

\begin{remq}
  Theorem~\ref{theo:Superspecial} is false for $g=1$, since for instance the curve defined by
  $E : y^2 = x^3 + 142x +23$ is isogenous to $E_0$ over $\F_{307^2}$, but not isomorphic to $E_0$.
  However, $E_0^2 \cong E^2$.
\end{remq}


If $E_1$, $E_2$, $E_1'$, $E_2'$ are supersingular elliptic curves defined over
$\F_{p^2}$, Theorem~\ref{theo:Superspecial} implies that $E_1\times E_2$ and
$E_1'\times E_2'$ are $\overline{\F_p}$-isomorphic.
In fact, when $E_1, E_2, E_1', E_2'$ are maximal, this isomorphism
is defined over $\F_{p^2}$, see~\cite[Lem.~5.2]{AbVarMax}. 




In this work, we explore the problem of computing explicit isomorphisms between
products of supersingular elliptic
curves. Moreover, as explained in Remark~\ref{remq:Fp2model}, we can
choose maximal models for the supersingular elliptic curves we work with.
The goal of this article is thus to find an
$\F_{p^2}$-isomorphism between the products $E_1 \times \cdots \times E_g$ and $E_1' \times \cdots \times E_g'$,
where the curves are maximal over $\F_{p^2}$.

\begin{remq}\label{remq:NonMaxCase}
  If the supersingular input curves are not maximal, we can start
  by computing $\overline{\F_p}$-isomorphic maximal curves. This can be done
  efficiently and it does not have any impact on our complexity bounds,
  see~\cite[Lem.~4]{Deuring4People}.
\end{remq}

\section{Main Results}\label{sc:main}

Our main algorithmic result is:

\begin{theo}\label{theo:main}
  Let $E_1, \dots, E_g$ and $E_1', \dots, E_g'$ be maximal elliptic curves over $\F_{p^2}$
  of known endomorphism rings, where $g \ge 2$. Assuming GRH, we give a
  probabilistic Las Vegas algorithm which computes in linear time in $g$
  and polynomial time in $\log(p)$ an $\F_{p^2}$-isomorphism of unpolarized abelian varieties:
  \begin{equation*}
    E_1 \times \dots \times E_g \cong    E_1' \times \dots \times E_g'.
  \end{equation*}
\end{theo}

In fact, the key point is to prove the following theorem.

\begin{theo}\label{theo:main2}
  Let $E_1,E_2$ and $E_1', E_2'$ be maximal elliptic curves over $\F_{p^2}$ of
  known endomorphism rings.  Assuming GRH, we give a probabilistic Las Vegas
  algorithm which computes in polynomial time in
  $\log(p)$ an $\F_{p^2}$-isomorphism of unpolarized abelian surfaces:
  \begin{equation*}
    E_1 \times E_2 \cong    E_1' \times E_2'.
  \end{equation*}
\end{theo}

The rest of the paper will be dedicated to the proof of Theorem~\ref{theo:main2}.
Let us explain how to deduce Theorem~\ref{theo:main} from Theorem~\ref{theo:main2}.

\begin{proof}[Proof that Theorem~\ref{theo:main2} implies
  Theorem~\ref{theo:main}]
We provide a proof by induction on $g$, assuming that the result is true for
  $g=2$ by Theorem~\ref{theo:main2}. 

  By Deligne-Ogus-Shioda theorem, an isomorphism $E_1\times\dots\times E_g\to
  E_1'\times\dots\times E_g'$ can be factored as a composition
  $$E_1\times \dots \times E_g\to E_1'\times \dots\times E_{g-1}'\times E_g \to
  E_1'\times \dots\times E_g'.$$

  This boils down to computing one $(g-1)$-dimensional isomorphism $E_1\times\dots\times E_{g-1}\to
  E_1'\times \dots \times E_{g-1}'$ and one $2$-dimensional isomorphism
  $E_{g-1}'\times E_g\to E_{g-1}'\times E_g'$. By induction, this proves that
  computing a $g$-dimensional isomorphism can be reduced to computing $g-1$
  isomorphisms in dimension $2$.
\end{proof}




\section{Tools}\label{sec:tools}

In this section, we develop tools which will be useful for computing
isomorphisms in Section~\ref{sec:algo_isom}. In Section~\ref{sc:div_ideal}, we study algorithms
for dividing endomorphisms by isogenies. Section~\ref{sec:improv_Kani} proves a
slight improvement of Kani's formula for the degree of an isogeny between
products of elliptic curves; this is useful for proving that an isogeny is an
isomorphism. In Section~\ref{sec:transposing_isog}, we show how to
``transpose''
isogenies between products of elliptic curves: we provide an easy way to
construct an isogeny $E_1'\times E_2'\to E_1\times E_2$ from an isogeny
$E_1\times E_2\to E_1'\times E_2'$, while preserving the degree.
Finally, in Section~\ref{section:adic}, we design
algorithms for finding the generator of the localization of a left-ideal in a
maximal order of $\B$.


\subsection{Division of principal ideals in quaternion orders}\label{sc:div_ideal}


The first tool that we need is a method for dividing efficiently an endomorphism by an
isogeny. More precisely, given an endomorphism $\phi\in\End(E_1)$, which
factors by an
isogeny $f:E_1\to E_2$, we wish to compute an isogeny $g:E_2\to E_1$ (which is
uniquely defined up to composition by automorphisms) such that
$\phi = g\circ f$. 
A general method when isogenies are given via efficient representations is
described in \cite[Cor.~6.8]{EffRpz}. A detailed complexity analysis is
provided in \cite[Sec.~4]{merdy2023supersingular} when $g$ is a scalar multiplication. We
propose here an explicit complete algebraic solution to the quaternionic
version of the problem, i.e. when all isogenies are represented as ideals in
$\B$.
This factorization problem is formalized in quaternion algebras as follows:

\begin{prob}[Principal ideal division]\label{pb:div_prin}
  Let $\mathcal O_1, \mathcal O_2, \mathcal \subset \B$ be two  maximal orders.
  Let
  $\mu\in\mathcal O_1$, $I\in \Conn(\mathcal O_1, \mathcal O_2)$, and $J$ be a
  left $\mathcal O_2$-ideal
  such that $\mathcal O_1\mu = I\cdot J$. Given $\mu$ and 
  $\Z$-bases of $\mathcal O_1, \mathcal O_2, I$, find a $\Z$-basis of $J$.
\end{prob}


\begin{remq}
  If $\Nrd(I)$ and $\Nrd(J)$ are coprime, then \cite[Lem.~6]{2DWest} allows
  us to recover $I$ more easily. However here we need to compute $J$, and the assumption that $\Nrd(I)$ and
  $\Nrd(J)$ are coprime is too strong for our setting: in theory (and in
  experiments), this hypothesis is not always satisfied. Therefore,
  we design a general algorithm which does not require any such
  assumption on the input.
\end{remq}

First we remark that Problem \ref{pb:div_prin} is unambiguous.
\begin{lemm}\label{lemm:unique_ideal}
  The solution of Problem~\ref{pb:div_prin} is unique.
\end{lemm}
\begin{proof}
  Let $J_1$ and $J_2$ be two solutions of Problem~\ref{pb:div_prin}. Then we
  have $I\cdot J_1 = I\cdot J_2.$ By multiplying on the left by $\overline I$,
  we obtain that $\Nrd(I)\cdot\mathcal O_R(I)\cdot J_1 = \Nrd(I)\cdot\mathcal
  O_R(I)\cdot J_2$, see~\cite[Sec.~16.6]{QuatAlg}.
  Moreover $\mathcal{O}_R(I)=\mathcal{O}_L(J_1)= \mathcal{O}_L(J_2)=\mathcal{O}_2$,
  and $J_1$, $J_2$ are left-ideals in $\mathcal{O}_2$. Therefore, $\Nrd(I)\cdot
  J_1 = \Nrd(I)\cdot J_2$, which implies $J_1=J_2$.
\end{proof}


We first address the special case where $\mu \in \Z$.

\begin{prob}[Integer ideal division]\label{pb:int_ideal_div}
  Let $\mathcal O_1, \mathcal O_2, \mathcal \subset \B$ be two  maximal orders. Let
  $d \in \Z$, $I\in \Conn(\mathcal O_1, \mathcal O_2)$, and $J$ a left
  $\mOd$-ideal be
  such that $\mathcal O_1 d = I\cdot J$. Given 
  $d$ and $\Z$-bases of $\mathcal O_1, \mathcal O_2, I$, find a $\Z$-basis of $J$.
\end{prob}

\begin{remq}\label{remq:unicity_int_ideal_div}
  The same argument as in the proof of Lemma~\ref{lemm:unique_ideal} shows the
  unicity of the solution of Problem~\ref{pb:int_ideal_div}. Moreover we can swap the roles of
  $I$ and $J$ via conjugation since $I \cdot J= d \mOi = \overline J  \cdot
  \overline I = d \mOi$. It is easy to check that
  Problems~\ref{pb:int_ideal_div} and~\ref{pb:div_prin} are equivalent: the
  solution $J$ of Problem~\ref{pb:div_prin} with input
  $\mO[1], \mO[2], \mu, I$ equals the solution of Problem~\ref{pb:div_prin}
  with input $\mu^{-1}\mO[1]\mu$, $\mO[2]$, $\Nrd(\mu)$, $\overline\mu I$.
\end{remq}

Now we propose an efficient method to solve Problem \ref{pb:int_ideal_div}.

\begin{prop}\label{prop:J=S}
  With the same notation as in Problem~\ref{pb:int_ideal_div}, $J = \{
    s\in\mathcal O_1 \cap \mathcal O_2 :  I s  \subset \mathcal O_1d \}$.
\end{prop}

\begin{proof}
  Set $S := \{
    s\in\mathcal O_1 \cap \mathcal O_2 :  I s  \subset \mathcal O_1d \}$.
  We must show that $S$ is a left-ideal in $\mathcal O_2$
  and that $IS=\mOi d$.

  First we show that $S$ is a left-ideal of $\mathcal{O}_2$. Let $s \in S, x
  \in \mathcal{O}_2$. First, we notice that
  $I$ is a right-ideal in $\mathcal O_2$,
  thus $Ix\subset I$. Since $s \in S$, we get $Ixs\subset Is\subset \mOi d$,
  hence $xs\in S$. 

  Finally, we prove that $IS=\mOi d$. Notice that $I  S\subset \mathcal O_1 d$ by construction.
  In order to prove the other inclusion, we notice that $J$ is included in
  $S$; hence, $\mathcal O_1 d = I  J \subset I S$.
\end{proof}

Proposition~\ref{prop:J=S} reduces Problem~\ref{pb:int_ideal_div} to
$\Z$-linear algebra. Let $(e_0,\dots,e_3)$, $(u_0,\ldots, u_3)$, $(v_0,\ldots,
v_3)$ be $\Z$-bases of $\mO[1], I, \mO[1]\cap \mO[2]$ respectively.
We need to solve the following system over the integers of $4$
equations in $20$ unknowns
$\{x_i\}_{0\leq i\leq 3}$, $\{y_{ij}\}_{0\leq i,j\leq 3}$:
$$(E_j):u_j\sum_{0\leq i\leq 3} x_i v_i = d\sum_{0\leq i\leq 3} y_{ij} e_i.$$

Let $b^{(1)}, \ldots, b^{(16)}\in\Z^{20}$ be a $\Z$-basis of the solutions of
this system. Then, writing $b^{(i)} = (x^{(i)}_0,\ldots,
x^{(i)}_3,y^{(i)}_{00},\ldots, y^{(i)}_{33})$, we compute a basis $a^{(1)},
\ldots, a^{(3)}$ of the lattice generated by $\{(x^{(i)}_0, \ldots,
x^{(i)}_3)\}_{1\leq i\leq 16}$. Finally, writing $a^{(j)}=(a^{(j)}_0,\ldots,
a^{(j)}_3)$, the set $\{\sum_{0\leq i\leq 3} a^{(j)}_i v_i\}_{0\leq j\leq 3}$ is
a $\Z$-basis for $J$.


\begin{prop}\label{prop:complexityfactor}
  With the same notation as in Problem~\ref{pb:int_ideal_div}, let $\gamma$ be
  the maximum of the numerators and denominators of the coefficients of the
  elements in the bases of $\mO[1], \mO[2], I$, when written in the canonical
  basis $1, i, j, ij$ of $\B$. Then a $\Z$-basis of $J$ (written in the basis
  $1,i,j,ij$) can be computed in quasi-linear complexity $\widetilde
  O(\log\gamma)$.
\end{prop}

\begin{proof}
  A $\Z$-basis for $J$ is obtained via linear algebra over the integers from
  the input $\Z$-bases. It can be computed via a sequence of Hermite Normal
  Forms
  of matrices with dimensions bounded above by a constant. Our proposition follows from the fact
  that the Hermite Normal Form of a nonzero matrix
  $(A_{ij})$ with integer entries can
  be computed with complexity quasi-linear in $\max_{ij}(\log\lvert
  A_{ij}\rvert)$, see~\cite[Chap.~6]{storjohann2000algorithms}.
\end{proof}

\begin{remq}\label{remq:pb_red_facto}
  The reduction in Remark~\ref{remq:unicity_int_ideal_div} shows that Problem~\ref{pb:div_prin} can
  also be solved in quasi-linear complexity.
\end{remq}


\subsection{An improvement of Kani's formula for the degree of isogenies
  between products of elliptic curves}\label{sec:improv_Kani}


The following statement is a slight improvement of Kani's
formula~\cite[Cor.~63]{KaniJacobian} for the degree of an isogeny between
products of elliptic curves. This formula involves absolute values, and our
improvement shows that they are in fact unnecessary. In the following
statement, we use the convention that the zero morphism, that is not an isogeny, has
degree $0$.

\begin{prop}\label{prop:KaniDeg}
  Let $E_1,E_2,E_1',E_2'$ be elliptic curves defined over $\overline{\F_p}$.
 For $i,j\in\{1,2\}$, let $\varphi_{ij}\in\Hom(E_j, E_i')$ be a morphism of
  degree $d_{ij}\in\N$. Let $\phi\in\Hom(E_1\times E_2, E_1'\times E_2')$ be
  the morphism defined as $\phi(x_1, x_2) =
  (\varphi_{11}(x_1)+\varphi_{12}(x_2), \varphi_{21}(x_1)+\varphi_{22}(x_2))$.
  Then
  $$\deg(\phi)
    =
    (d_{11}+d_{21})(d_{12}+d_{22}) -
    \deg(\widehat\varphi_{12}\varphi_{11} +
    \widehat\varphi_{22}\varphi_{21}).$$
\end{prop}

\begin{proof}
  Set $\mu:= \widehat\varphi_{12}\varphi_{11}$ and $\nu :=
\widehat\varphi_{22}\varphi_{21}$. \cite[Cor.~64]{KaniJacobian} states that
$\deg(\phi) = \lvert(d_{11}+d_{21})(d_{12}+d_{22}) -
    \deg(\mu + \nu)\rvert$.
    Therefore, the only thing that we need to prove is that  $\deg(\mu + \nu)\leq
    (d_{11}+d_{21})(d_{12}+d_{22})$, so that the absolute value is not
    required.

We start with the following computation:
\[\begin{array}{rcl}
    0&\leq& \deg(d_{21}\mu-d_{11}\nu)\\
  &=&(d_{21}\mu - d_{11}\nu)(d_{21}\widehat\mu - d_{11}\widehat\nu)\\
  &=&d_{21}^2 \deg(\mu) + d_{11}^2 \deg(\nu)-d_{11}d_{21}(\nu\widehat\mu +
  \mu\widehat\nu).
\end{array}\]

Next, we notice that $\deg(\mu + \nu) -\deg(\mu)-\deg(\nu) = (\mu+\nu)(\widehat\mu+\widehat\nu)-\deg(\mu)-\deg(\nu)  =
\nu\widehat\mu +
\mu\widehat\nu$. Replacing $\nu\widehat\mu +
\mu\widehat\nu$ in the previous inequality, we obtain 
\[d_{21}^2 \deg(\mu) + d_{11}^2 \deg(\nu)\geq d_{11}d_{21}(\deg(\mu +
\nu)-\deg(\mu)-\deg(\nu)).\]
Finally, we replace $\deg(\mu)$ and $\deg(\nu)$ by their respective values
$d_{12}d_{11}$ and $d_{22}d_{21}$ to obtain 
\[d_{21}^2 d_{12}d_{11} + d_{11}^2 d_{22}d_{21}\geq d_{11}d_{21}(\deg(\mu +
\nu)-d_{12}d_{11}-d_{22}d_{21}).\]
By dividing this inequality by $d_{11}d_{21}$ and by rearranging terms, we
obtain the desired inequality $\deg(\mu + \nu)\leq
(d_{11}+d_{21})(d_{12}+d_{22})$.
\end{proof}


We shall use Proposition~\ref{prop:KaniDeg} in order to compute degrees of
isogenies between products of elliptic curves. An important special case is
that it can be used to check if such an isogeny has degree $1$, i.e. if it is
an isomorphism.
More precisely, a $2$-dimensional isogeny between products of elliptic curves
can be given as a matrix of isogenies $(\varphi_{ij})=\begin{pmatrix}
   \varphi_{11} & \varphi_{12} \\
   \varphi_{21} & \varphi_{22} \\           
 \end{pmatrix}$. Such an isogeny is an isomorphism if and only if
\begin{equation*}
    (d_{11}+d_{21})(d_{12}+d_{22}) -
    \deg(\widehat\varphi_{12}\varphi_{11} +
    \widehat\varphi_{22}\varphi_{21}) =1.
  \end{equation*}

We can reformulate this statement to obtain the following necessary and sufficient condition:
 \begin{prop} \label{prop:isomorphism_suff_cond}
   Let $E_1, E_2, E_1', E_2'$ be four elliptic curves defined over
   $\overline{\F_p}$, and
   $\varphi_{ij}:E_j\to E_i'$, $i,j\in\{1, 2\}$ be four isogenies. 
   Set $\mu=\widehat\varphi_{12}\varphi_{11}, \nu =
   \widehat\varphi_{22}\varphi_{21}$, and write $d_{ij} = \deg(\varphi_{ij})$.
   Then $\deg( d_{21} \mu - d_{11} \nu) =  d_{11} d_{21}$ if and only if $\phi=(\varphi_{ij})_{i,j\in\{1,2\}}\in\Hom(E_1 \times E_2, E_1' \times E_2')$
  is an isomorphism.
\end{prop}

\begin{proof}
By Proposition~\ref{prop:KaniDeg}, we have
  $\deg(\mu+\nu) = (d_{11}+d_{21})(d_{12}+d_{22}) -
  \deg(\phi)$.
  Therefore, we obtain the equality
  \begin{equation}\deg(\mu+\nu) - \deg(\mu) - \deg(\nu) = \frac{d_{11}}{d_{21}} \deg(\nu) +
    \frac{d_{21}}{d_{11}} \deg(\mu) - \deg(\phi).\label{eq:normeq2endo}\end{equation}
  By multiplying~\eqref{eq:normeq2endo} by $d_{11}d_{21}$, we obtain
  $$\begin{array}{rcl}
    &&d_{11} d_{21} \deg(\phi)\\ &=& d_{11}(d_{11}+d_{21})\deg(\nu)+
    d_{21}(d_{11}+d_{21})\deg(\mu)-d_{11}d_{21}\deg(\mu+\nu)\\
    &=&
    d_{11}^2\deg(\nu)+d_{21}^2\deg(\mu)-d_{11}d_{21}\Trd(\mu\widehat\nu)\\
    &=& \deg( d_{21} \mu - d_{11} \nu),
  \end{array}$$
  hence $\deg(\phi)=1$ if and only if $\deg( d_{21} \mu - d_{11} \nu) =
  d_{11}d_{21}$.
\end{proof}


\subsection{Transposing isogenies}\label{sec:transposing_isog}

In this section, we show how an isogeny $\phi: E_1\times E_2\to E_1'\times E_2'$ can
be transformed into a transposed isogeny $\widetilde\phi: E_1'\times E_2'\to
E_1\times E_2$ of the same degree.
Since we have not fixed
any polarization on the product surface, this transposed isogeny is
not a dual of $\phi$ in the usual sense. In particular, the composed
endomorphism
$\widetilde\phi\cdot\phi$ need not be the multiplication by an integer. Still,
the degree is preserved, i.e. $\deg(\phi)=\deg(\widetilde\phi)$.

\begin{coro}\label{coro:pseudodual}
  With the same notation as in Proposition~\ref{prop:KaniDeg}, let $\widetilde
  \phi\in\Hom(E_1'\times E_2', E_1\times E_2)$ denote the morphism defined as
  $\widetilde\phi(x_1', x_2') = (\widehat\varphi_{11}(x_1') +
    \widehat\varphi_{21}(x_2'),
  \widehat\varphi_{12}(x_1')+\widehat\varphi_{22}(x_2'))$, i.e. in
  matrix notation
  \[\widetilde\phi = \begin{bmatrix}
      \widehat\varphi_{11}& \widehat\varphi_{21}\\ 
      \widehat\varphi_{12}& \widehat\varphi_{22}
  \end{bmatrix}.\]
    Then $\deg(\phi) = \deg(\widetilde\phi)$.
\end{coro}

\begin{proof}
  Set $d_{ij}=\deg(\varphi_{ij})$ and $\psi:=\varphi_{21}\widehat\varphi_{11}  + \varphi_{22}\widehat\varphi_{12}$, then
$$\phi \widetilde\phi
      = \begin{pmatrix}
        (d_{11} + d_{12}) & \widehat{\psi} \\
        \psi           & (d_{21} + d_{22})\\
      \end{pmatrix}.
$$

    Applying Proposition~\ref{prop:KaniDeg} to the composed endomorphism $\phi
    \widetilde\phi$, we get 
    $$
    \deg(\phi)\deg(\widetilde\phi) = \deg ( \phi \widetilde\phi ) %
      = \left(  (d_{11} + d_{12})(d_{21} + d_{22}) - \deg( \psi) \right)^2
     = \deg( \widetilde\phi ) ^2 .
    $$
Therefore, $\deg( \phi ) = \deg( \widetilde\phi ).$
\end{proof}




\subsection{Localization}\label{section:adic}

In this section, we investigate algorithmic aspects of the ring $\Mat_2(\Z_\ell)$
and of its left-ideals. This will be useful during the study of localizations
of quaternion algebras: when $\mathcal O$ is a maximal order in a quaternion
algebra over $\Q$ not ramified at $\ell$, then $\mathcal O\otimes \Z_\ell$ is
isomorphic to $\Mat_2(\Z_\ell)$. The first thing to notice is that $\Mat_2(\Z_\ell)$ is
left-principal, and its left-ideals correspond to matrices in Hermite Normal
Form.


\begin{prop}\cite[Chap.~II, Thm.~2.3]{QuatVigneras}
  The left-ideals in $\Mat_2(\Z_\ell)$ are the (all distinct) ideals of the form 
  $$\Mat_2(\Z_\ell)\cdot \begin{pmatrix}\ell^n & r\\0&\ell^m\end{pmatrix},$$
    where $n,m\in\N$ are positive integers, and $r\in\{0,\ldots, \ell^{m-1}\}$.
\end{prop}

As $\Mat_2(\Z_\ell)$ is left-principal, we can define the \emph{right-gcd} of
matrices $A_1, A_2\in \Mat_2(\Z_\ell)$ as the Hermite Normal Form of a
generator of the ideal $\Mat_2(\Z_\ell)\cdot A_1+\Mat_2(\Z_\ell)\cdot A_2$. We
now consider the problem of computing this right-gcd, assuming that $A_1$ and
$A_2$ are given in Hermite Normal Form.

\begin{prop}\label{prop:rgcd_mat_zl}
  Let $A_1, A_2\in\Mat_2(\Z_\ell)$ be two matrices in Hermite Normal Form:
  $$A_i = \begin{pmatrix}\ell^{n_i} & r_i\\
  0&\ell^{m_i}\end{pmatrix}, \quad i\in\{1, 2\}.$$
  We assume without loss of generality that $n_2\geq n_1$. Set $m=\min(m_1,
  m_2, \val_\ell(r_2-\ell^{n_2-n_1}r_1))$ (with the convention that
  $\val_\ell(0) = \infty$). Then the
  \emph{right-gcd} of $A_1$ and $A_2$ is
  $$\rgcd(A_1, A_2) = \begin{pmatrix}\ell^{n_1}&(r_1\bmod
  \ell^m)\\0&\ell^m\end{pmatrix}.$$
\end{prop}

\begin{proof}
  We have to prove that 
  $$\Mat_2(\Z_\ell)\cdot A_1 + \Mat_2(\Z_\ell)\cdot A_2 = \Mat_2(\Z_\ell)\cdot
  \begin{pmatrix}\ell^{n_1}& (r_1\bmod \ell^m)\\0&\ell^m\end{pmatrix}.$$
  We notice that the left-ideal generated by a matrix correspond to the
  $\Z_\ell$-module generated by its rows.

  First we prove the inclusion
$$\Mat_2(\Z_\ell)\cdot A_1 + \Mat_2(\Z_\ell)\cdot A_2 \supset \Mat_2(\Z_\ell)\cdot
  \begin{pmatrix}\ell^{n_1}& (r_1\bmod \ell^m)\\0&\ell^m\end{pmatrix}.$$
    The vector $(0, \ell^m)$ clearly belongs to the $\Z_\ell$-module generated
    by the rows of $A_1$ and $A_2$ since $(0, \ell^{m_1}), (0, \ell^{m_2})$ and
    $(0, r_2-\ell^{n_2-n_1} r_1)$ belongs to it. Hence,
    $(\ell^{n_1}, r_1\bmod \ell^m)$ also lies in this $\Z_\ell$-module.

    Let us now prove the other inclusion:
$$\Mat_2(\Z_\ell)\cdot A_1 + \Mat_2(\Z_\ell)\cdot A_2 \subset \Mat_2(\Z_\ell)\cdot
  \begin{pmatrix}\ell^{n_1}& (r_1\bmod \ell^m)\\0&\ell^m\end{pmatrix}.$$
    The only non-trivial thing that we need to prove is that $(\ell^{n_2}, r_2)$ belongs to
    the $\Z_\ell$-module generated by $(\ell^{n_1}, r_1)$ and $(0,
    \ell^m)$. We notice that $\val_\ell(r_2-\ell^{n_2-n_1}r_1)\geq m$, hence
    there exists $x\in\Z_\ell$ such that $r_2-\ell^{n_2-n_1}r_1=x\, \ell^m$.
    Therefore $(\ell^{n_2}, r_2) = \ell^{n_2-n_1}\cdot (\ell^{n_1}, r_1) +
    x\cdot (0, \ell^m)$, which concludes the proof.
\end{proof}

The main application of Proposition~\ref{prop:rgcd_mat_zl} shall appear in the
following setting. Let $\mathcal O\subset \B$ be a maximal order, and
$I\subset \mathcal O$ be a left-ideal given by a $\Z$-basis $b_1, b_2, b_3,
b_4\in \mathcal O$. Assume that we can compute an isomorphism
$\phi:\mathcal O\otimes \Z_\ell\to \Mat_2(\Z_\ell)$. Then a generator of
$I\otimes \Z_\ell$ is $\phi^{-1}(\rgcd(\phi(b_1), \phi(b_2), \phi(b_3),
\phi(b_4)))$, so we can compute this generator by using
Proposition~\ref{prop:rgcd_mat_zl}.


\section{Computing $2$-dimensional isomorphisms}\label{sec:algo_isom}

In this section, which contains our main algorithms, we start by noticing that
the problem of finding automorphisms of surfaces is pretty easy to solve.
Then, in the general case, we give a criterion for an isomorphism to exist, if we fixed two isogenies
of its matrix representation. This criterion can be made effective, and it will then be
used to compute (in polynomial time) isomorphisms between product of
curves.

\subsection{The case of automorphisms}\label{sec:automorphisms}

\begin{prop}\label{prop:autofromiso}
  Let $E_1, E_2$ be two elliptic curves defined over $\overline{\F_p}$,
  $\varphi: E_1 \to E_2$ be an isogeny, and $a,b,c,d \in \Z$ be integers such that $ad - bc\deg(\varphi)  = \pm 1$.
  Then the endomorphism $F=\begin{pmatrix}
    a & b\widehat{\varphi} \\
    c\varphi & d \\
  \end{pmatrix}\in\End(E_1\times E_2)$ 
  is an automorphism.
\end{prop}
\begin{proof}
  By Proposition~\ref{prop:KaniDeg},
  $$\begin{array}{rcl}
    \deg(F) &=& (a^2 + c^2\deg(\varphi))(b^2\deg(\varphi) + d^2) - \deg( b\varphi a + d c \varphi) \\
            &=& (a^2 + c^2\deg(\varphi))(b^2\deg(\varphi) + d^2) - (ba+dc)^2\deg(\varphi) \\
            &=& a^2d^2 + c^2b^2\deg(\varphi)^2 - 2abcd\deg(\varphi) \\
            &=& (ad - bc\deg(\varphi))^2\\
            &=& 1.
  \end{array}$$
\end{proof}

\begin{remq}
  Direct computations show that the inverse of the automorphism $F=\begin{pmatrix}
    a & b\widehat{\varphi} \\
    c\varphi & d \\
  \end{pmatrix}$ is $F^{-1}= \begin{pmatrix}
    d & -b\widehat{\varphi} \\
    -c\varphi & a \\
  \end{pmatrix}$.
\end{remq}

Proposition~\ref{prop:autofromiso} implies that if we are able to compute an isogeny $\varphi: E_1 \to E_2$,
then the $2$-dimensional morphism
$\begin{pmatrix}
  1+\deg(\varphi) & \widehat{\varphi} \\
  \varphi & 1 \\
\end{pmatrix}$
is an isomorphism.
Thus knowing the endomorphism rings of $E_1$ and $E_2$
is enough to compute automorphisms of the surface $E_1 \times E_2$,
thanks to~\cite[Algo.~5]{WesoFocs21}.


\subsection{Completion of matrices of isogenies}
In this section, we investigate the following question: given two isogenies
$\varphi_{11}, \varphi_{21}$, can we compute isogenies $\varphi_{12}, \varphi_{22}$ such that the matrix
$(\varphi_{ij})$ is an isomorphism. First, we give a necessary and sufficient
criterion for the existence of such isogenies $\varphi_{12}, \varphi_{22}$.
When this criterion is satisfied, we provide an algorithm to compute them.
First we state a useful lemma.

\begin{lemm}\label{lemm:SumIdealCoprime}
  Let $F, E, E_1, E_2$ be elliptic curves over $\overline{ \F_p}$, $\psi:F \to E$
  be a (non-necessarily separable) isogeny, and $\varphi_{1}:E \to E_1$, $\varphi_{2}:E \to E_2$ be
  separable isogenies of coprime degrees. Write $K:= \ker(\varphi_{1}) \oplus \ker(\varphi_{2})$. 
  Then
  \begin{equation*}
    \deg(\varphi_2) \Hom(E_1, F)\varphi_1 \psi  +  \deg(\varphi_1) \Hom(E_2,
    F)\varphi_2 \psi  = \Hom(E/K, F) \pi_K \psi.
  \end{equation*}
  where $\pi_K: E \to E/K$ is the canonical separable isogeny with kernel $K$.
\end{lemm}

\begin{proof}
  Set $d_1:=\deg(\varphi_1)$, $d_2:=\deg(\varphi_2)$, $I_1 :=d_2 \Hom(E_1, F)\varphi_1 \psi$,
  $I_2 := d_1 \Hom(E_2, F)\varphi_2 \psi$ and $I_K := \Hom(E/K, F)\pi_K \psi$.
  Direct computations show that
  $$\begin{array}{clcl}
    &\ker(d_2\varphi_1 \psi) \cap \ker(d_1 \varphi_2 \psi) & =& \psi^{-1}( \ker( d_2 \varphi_1) )
                                                            \cap
                                                            \psi^{-1}(\ker( d_1 \varphi_2)) \\
                                                          =& \psi^{-1} \left(  \ker( d_2 \varphi_1)
                                                            \cap \ker( d_2 \varphi_1) \right)
                                                          &=& \psi^{-1}\left(
                                                            ( \ker \varphi_1 + E[d_2] ) \cap
                                                            ( \ker \varphi_2 + E[d_1]) \right) \\
                                                           =& \psi^{-1}( \ker \varphi_1 \oplus \ker \varphi_2)
                                                          &=& \psi^{-1}( \ker( \pi_K)) \\
                                                           =& \ker ( \pi_K \psi).&&
  \end{array}$$  


  Noticing that $I_1 + I_2 = I_{ \ker(d_2\varphi_1 \psi) \cap \ker(d_1 \varphi_2
  \psi)}$ and $\Hom(E/K, F) \pi_K \psi = I_{\ker ( \pi_K \psi)}$ concludes the proof.
  \end{proof}

We are now ready to state a key result of the paper.

\begin{theo}\label{theo:isom_iff}
   Let $E_1, E_2, E_1', E_2'$ be four isogenous elliptic curves defined over
   $\overline{ \F_p}$, and
   $\varphi_{11}:E_1\to E_1'$, $\varphi_{21}: E_1\to E_2'$
   be separable isogenies
   with coprime degrees.  There
   exist isogenies $\varphi_{12}:E_2\to E_1'$, $\varphi_{22}: E_2\to E_2'$
   such that $\phi=(\varphi_{ij})_{i,j\in\{1,2\}}\in \Hom(E_1\times E_2,
   E_1'\times E_2')$ is an isomorphism if and only if
   $ E_1 / \left( \ker(\varphi_{11})\oplus\ker(\varphi_{21}) \right)$ and $E_2$ are isomorphic.
\end{theo}


\begin{proof}
  Let $\psi: E_1\to E_2$ be an isogeny.
  Let $K$ denote the subgroup $\ker(\varphi_{11})\oplus\ker(\varphi_{21})$ of $E_1$. Let 
  $\pi_K:E_1 \to E_1/K$ be the associated canonical isogeny.
  Set $J_{11}:=\Hom(E_1', E_2)\varphi_{11}\widehat\psi$,
  $J_{21}:=\Hom(E_2',E_2)\varphi_{21}\widehat\psi$, and
  $J_K:=\Hom(E_1/K,E_2)\pi_K  \widehat \psi$,
  which are left-ideals in $\End(E_2)$.

  By Proposition~\ref{prop:isomorphism_suff_cond}, there
  exist isogenies $\varphi_{12}:E_2\to E_1'$, $\varphi_{22}: E_2\to E_2'$
  such that $\phi=(\varphi_{ij})_{i,j\in\{1,2\}}\in \Hom(E_1\times E_2,
  E_1'\times E_2')$ is an isomorphism if and only if there exist
  isogenies $\mu, \nu: E_1\to E_2$ which factors respectively by $\varphi_{11}$
  and $\varphi_{21}$ and such that $\deg(d_{21}\mu-d_{11}\nu) =
  d_{11}d_{21}$, where $d_{11}=\deg(\varphi_{11})$ and $d_{21} =
  \deg(\varphi_{21})$.
  Equivalently, $\deg((d_{21}\mu-d_{11}\nu) \widehat\psi) = d_{11}d_{21}\deg(\psi)$,
  with $\mu\widehat\psi\in J_{11}, \nu\widehat\psi\in J_{21}$.
  Since Lemma~\ref{lemm:SumIdealCoprime} implies that $J_K =
  d_{21}J_{11}+ d_{11}J_{21}$, it is equivalent to the existence of a $\sigma \in J_K$ such that
  $\deg( \sigma) = d_{11}d_{21} \deg(\psi)$. Remark that by definition, such a $\sigma \in J_K$
  would factor as $\sigma = \tau \pi_K \widehat \psi $ for some $\tau \in \Hom(E_1 / K , E_2)$.
  Thus the equation $\deg( \sigma )= d_{11}d_{21} \deg(\psi)$ is equivalent to
  $\deg( \tau) \deg( \pi_K) \deg(\psi)=d_{11}d_{21} \deg(\psi)$ by multiplicativity of the degree, which
  reduces to $\deg(\tau) = 1$, since $\deg(\pi_K) = d_{11}d_{21}$.

  We conclude that there
  exist isogenies $\varphi_{12}:E_2\to E_1'$, $\varphi_{22}: E_2\to E_2'$
  such that $\phi=(\varphi_{ij})_{i,j\in\{1,2\}}\in \Hom(E_1\times E_2,
  E_1'\times E_2')$ is an isomorphism if and only if there exists $\tau \in \Hom(E_1 / K, E_2)$ with $\deg(\tau)=1$,
  \textit{i.e.} if and only if $E_1 / K$ and $E_2$ are isomorphic.
\end{proof}

Theorem~\ref{theo:isom_iff} is actually effective, provided that we know the endomorphism rings
of the curves. Algorithm~\ref{algo:isomorphism_completion} computes such an
isomorphism.

\begin{prop}\label{prop:isomcompl_correct}
  Assuming GRH, Algorithm~\ref{algo:isomorphism_completion} is correct and it runs in time
  polynomial in $\log(p)$ and in the size of the input.
\end{prop}

\begin{proof}

  First we prove that Algorithm~\ref{algo:isomorphism_completion} is correct.
  In fact, Algorithm~\ref{algo:isomorphism_completion} follows the proof of
  Theorem~\ref{theo:isom_iff}. An isogeny associated to the ideal $I_\psi$
  plays the role of $\psi$ in the proof of Theorem~\ref{theo:isom_iff}. The
  ideals $I_{11}$, $I_{21}$ correspond to the isogenies $\varphi_{11},
  \varphi_{21}$ in Theorem~\ref{theo:isom_iff}, and the
  ideals $J_{11}$ and $J_{21}$ play the same role as in the proof of
  Theorem~\ref{theo:isom_iff}. We now prove that the endomorphism $\xi$ computed
  in Step~\ref{step:lattice_red} satisfies the requirements of $\sigma$ in the
  proof of Theorem~\ref{theo:isom_iff}, namely that $\Nrd(\xi) =
  d_{11}d_{21}\Nrd(I_{\psi})$. By the same argument as in the proof of
  Theorem~\ref{theo:isom_iff}, $J_K$ is a principal left-ideal (because $E_1/K \simeq E_2$) of reduced
  norm $d_{11}d_{21}\Nrd(I_{\psi})$, so it contains an element with this
  reduced norm; this proves that $\Nrd(\xi)= d_{11}d_{21}\Nrd(I_{\psi})$.
  Theorem~\ref{theo:isom_iff} also asserts that at least one of the
  matrices computed at Step~\ref{step:automorphisms} is an isomorphism.

  \smallskip

  Let us now prove that the complexity is polynomial with respect to the input
  size. Most steps reduce to linear algebra over $\Z$; this boils down to
  computing Hermite Normal Forms, which can be
  done in time polynomial in
  the input size.
  Step~\ref{step:lattice_red} involves computing the shortest vector in a
  lattice of dimension $4$, with respect to the positive definite quadratic
  form $(x_1, x_2, x_3, x_4)\mapsto x_1^2 + x_2^2 + p(x_3^2 + x_4^2)$. This can be achieved in time polynomial in the
  input size and in $\log(p)$, see~\cite[Thm.~4.2.1]{nguyen2009low}.
  The combinatorial factor in Step~\ref{step:automorphisms} does not increase
  the complexity since the number
  of possible isogenies $E\to E'$ that are represented by the same left-ideal
  in $\End(E)$ equals the order of $\Aut(E)$. For most elliptic curves,
  $\Aut(E) = \{1, -1\}$, and in any case $\lvert\Aut(E)\rvert\leq
  24$~\cite[Appendix~A, Prop.~1.2.(c)]{Silv}.
  Assuming GRH, converting the ideal representation to an efficient representation can be
  done in polynomial-time, see e.g.~\cite[Appendix~C]{EffRpz}.
\end{proof}

\begin{algorithm}
  \caption{\IsomorphismCompletion{}\label{algo:isomorphism_completion}}
    \INPUT{Four maximal curves $E_1, E_1', E_2, E_2'$ over $\F_{p^2}$; $\Z$-bases of maximal orders $\mO[1],
     \mO[2]\subset \B$ and isomorphisms $\mO[1]\cong
    \End(E_1)$, $\mO[2]\cong\End(E_2)$; $\Z$-bases of left-ideals $I_{11}, I_{21}\subset\mO[1]$
    of coprime degrees which correspond to isogenies $\varphi_{11}:E_1\to E_1'$, $\varphi_{21}:E_1\to
    E_2'$ such that $E_2 \cong E_1 / \left( \ker(\varphi_{11}) \oplus \ker(\varphi_{21}) \right)$.
  }
    \OUTPUT{An efficient representation of a $2\times
    2$ matrix of isogenies ($\varphi_{ij}$) representing an isomorphism
    $E_1\times E_2\to
    E_1'\times E_2'$ such that $\Hom(E_2, E_1)\varphi_{11}\cong I_{11}$ and
    $\Hom(E_2', E_1)\varphi_{21}\cong I_{21}$.}
    Compute $d\in\Z$ such that $d\mO[1]\mO[2]\subset\mO[1]\cap \mO[2]$ and set
    $I_{\psi}:=d\mO[1]\mO[2]$, which is a connecting ideal between
    $\mO[1]$ and $\mO[2]$\;\tcp{see \cite[Algo.~3.5]{kirschmer2010algorithmic}}

    Compute $\Z$-bases of $J_{11} := \overline I_\psi I_{11}$ and
    $J_{21} := \overline I_\psi I_{21}$\;
    Set $d_{11} := \Nrd(I_{11})$ and $d_{21} = \Nrd(I_{21})$\;
    Compute a $\Z$-basis of $J_K = d_{21}J_{11}+d_{11}J_{21}$\;

    Compute an element $\xi$ in $J_K$ whose reduced norm is
    minimal\;\label{step:lattice_red} \tcp{Lattice reduction in dimension
    $4$}

    Using linear algebra over $\Z$, compute $\xi_{11}\in J_{11},
    \xi_{21}\in J_{21}$ such that $d_{21}\xi_{11}-d_{11}\xi_{21} = \xi$\;

    Compute left-ideals $I_{12}$ and $I_{22}$ in the right-orders of
    $I_{11}$ and $I_{21}$ respectively, such that
    $\overline I_\psi I_{11} \overline I_{12} = \mO[2]\xi_{11}$ and $\overline I_\psi
    I_{21} \overline I_{22} =
    \mO[2]\xi_{21}$\;\tcp{Prop.~\ref{prop:complexityfactor} and
    Remark~\ref{remq:pb_red_facto}}
    Compute efficient representations of all possible matrices
    $(\varphi_{ij})$ such that $\varphi_{ij}\in\Hom(E_j, E_i')$ and $\Hom(E_i',
    E_j)\varphi_{ij}\cong I_{ij}$ as $\End(E_j)$
    left-modules\label{step:automorphisms}\;
    Using Proposition~\ref{prop:KaniDeg}, find a matrix among them which
    is an isomorphism and return it\;
\end{algorithm}




