\subsection{Computing an isomorphism in the general case}\label{sc:generalcase}


For simplicity, we focus on the case $p\equiv 3 \bmod 4$ where we can use the
curve
$E_0$ defined over $\F_{p^2}$ by the equation $y^2 = x^3 + x$ which admits
a low-discriminant endomorphism. If
$p\equiv 1\bmod 4$, we can use instead the construction described
in~\cite[Sec.~3.1]{Deuring4People}.

First we provide an algorithm to solve a special case of Theorem~\ref{theo:main2}.


\begin{algorithm}  
  \caption{\IsomorphismEO{}\label{algo:GeneralIsomReduced}}
    \INPUT{Two maximal elliptic curves $E_1,E_2$ defined over
    $\F_{p^2}$, maximal orders $\mO[1], \mO[2]$ together with isomorphisms
    $\mO[1]\cong \End(E_1), \, \mO[2]\cong \End(E_2)$}
    \OUTPUT{Returns an efficient representation of an isomorphism $E_0^2
    \to E_1 \times E_2$.}
  Compute isogenies $\varphi_1: E_0 \to E_1$ and $\varphi_2: E_0 \to E_2$ 
  of coprime degree, and their ideals $I_{1},I_{2}$ \; 
  \tcp{use KLPT~\cite{KLPT} or \cite[Algo.~5]{WesoFocs21}}

  Set $I_K:=\deg(\varphi_1)I_2 + \deg(\varphi_2)I_1$, and compute its right order $\mO[3]$
along with an elliptic curve $E_3$ such that $\End(E_3) \cong \mO[3]$ \;
  \tcp{Lemma~\ref{lemm:SumIdealCoprime} ensures that $E_3 \simeq E_0/(\ker(\varphi_1) \oplus \ker(\varphi_2))$}

  Compute an isomorphism $F: E_0 \times E_3 \to E_1 \times E_2$ by running
  \IsomorphismCompletion($E_0,E_3,E_1,E_2,\mO[0],\mO[3],I_1,I_2$) \;

  Choose a prime $\ell \neq p$, and compute an isomorphism $G:E_0^2 \to E_0 \times E_3$ by running
  \textsc{LowDiscriminantIsomorphism}($E_3,\mO[3],\ell$), and post-composing by the isomorphism $(P,Q) \mapsto (Q,P)$ \;

  Return the composition $F \circ G: E_0^2 \to E_1 \times E_2$\;
\end{algorithm}

\begin{theo}
  Algorithm~\ref{algo:GeneralIsomReduced} is correct and assuming GRH it requires an expected number of operations which
  is polynomial in $\log(p)$.
\end{theo}


\begin{proof}
  First we prove that the algorithm is correct. Since we know the endomorphism rings of $E_0,E_1,E_2$ we
  can compute the isogenies $\varphi_i:E_0 \to E_i$ of coprime degree by~\cite[Algo.~5]{WesoFocs21}.
  Applying Lemma~\ref{lemm:SumIdealCoprime} with $\psi = Id_{E_0}$ leads to the construction of the
  ideal $I_K$ representing an isogeny $E_0 \to E_0/( \ker(\varphi_1) \oplus \ker(\varphi_2))$.
  The correctness is then a consequence of Proposition~\ref{prop:isomcompl_correct} and Theorem~\ref{th:isom1}.

  The complexity follows from the same results, using the fact that
\cite[Algo.~5]{WesoFocs21} requires polynomial time assuming GRH, and that
constructing $I_K$ is standard $\Z$-linear algebra.  \end{proof}


We finally present a proof of Theorem~\ref{theo:main2}.


\begin{proof}[Proof of Theorem~\ref{theo:main2}]
By two calls to Algorithm~\ref{algo:GeneralIsomReduced}, we compute two isomorphisms
$\Phi: E_1 \times E_2 \to E_0^2 $ and $\Psi:E_1' \times E_2' \to E_0^2$.
Then by Corollary~\ref{coro:pseudodual} we compute
the tranposed isomorphism $\widetilde{\Psi}:E_0^2 \to E_1' \times E_2'$.
Computing the composition $\widetilde{\Psi} \circ \Phi$ leads to the desired
isomorphism $E_1 \times E_2 \to E_1' \times E_2'$.
\end{proof}



