\section{Proofs and Additional Results} \label{app:furthermath}

\subsection{Equivalence Class of Representations}\label{sec:aux_res}

\begin{lemma}[Equivalence Class of Representations]
\label{lem:identifiability_RPS}
Let \((\Omega, \mathcal{F}, P)\) be a probability space, and let \(Z : \Omega \to \mathbb{R}^d\) be a measurable map (a random \emph{representation}).  
Then for each \ILT\ \(Q \) the random variable \(Q(Z)\) satisfies 
\[
   \sigma\bigl(Q(Z)\bigr)
   \;=\;
   \sigma(Z),
\]
where \(\sigma(Z)\) denotes the \(\sigma\)-algebra generated by the random variable \(Z\). Consequently, 
\[
  \mathcal{Z} 
  \;=\;
  \bigl\{Q(Z) \;\mid\; Q \in \mathcal{Q}\bigr\}
\]
forms an equivalence class of representations that are indistinguishable from the viewpoint of measurable information.
\end{lemma}

\begin{proof}
Each \(Q \in \mathcal{Q}\) is an invertible linear transformation. Consequently, \(Q\) is a Borel measurable bijection with a Borel measurable inverse. 
%
To show \(\sigma(Q(Z)) = \sigma(Z)\), consider any Borel set \(B \subseteq \mathbb{R}^d\). We have
\[
   \{\omega \in \Omega : Q(Z(\omega)) \in B\} = \{\omega \in \Omega : Z(\omega) \in Q^{-1}(B)\}.
\]
Since \(Q^{-1}(B)\) is Borel (as \(Q\) is a Borel isomorphism), the pre-image \(\{\omega : Z(\omega) \in Q^{-1}(B)\}\) belongs to \(\sigma(Z)\). Similarly, for any Borel set \(A \subseteq \mathbb{R}^d\),
\[
   \{\omega \in \Omega : Z(\omega) \in A\} = \{\omega \in \Omega : Q(Z(\omega)) \in Q(A)\},
\]
which belongs to \(\sigma(Q(Z))\). Therefore, \(\sigma(Q(Z)) = \sigma(Z)\).
\end{proof}


\subsection{Proof of \cref{lem:smoothness_invariance}}\label{proof:smoothness_invariance}
\begin{proof}
We consider \( f \) being $C^s$ on the open domain \( D \subseteq \mathbb{R}^d \), so by definition, all partial derivatives of \( f \) up to order \( s \) exist and are continuous on \( D \). Further, we consider any invetible matrix \( Q \). Such linear transformations are known to be infinitely smooth (as all their partial derivatives of any order exist and are constant, hence continuous). 
Hence, the function $h= f \circ Q^{-1}$ is the composition of a $C^s$ function \( f\) with a linear (and thus \( C^{\infty} \)) map \( Q^{-1} \). 

Applying the multivariate chain rule, we can easily verify that the differentiability properties of \( h \) are inherited from those of \( f \) and the linear transformation \( Q^{-1} \). Specifically, since \( Q^{-1} \) is \( C^{\infty} \), and \( f \) is \( C^s \), their composition \( h \) retains the \( C^s \) smoothness. Lastly, the (transformed) domain \( Q(D) \) is also open as linear (and thus continuous) transformations preserve the openness of sets in \( \mathbb{R}^d \). Therefore, \( h \) is well-defined and \( C^s \) on \( Q(D) \).
% The above result also holds if $Q$ corresponds to a reflection, permutation, or uniform scaling matrix. This follows from the fact that all of these are orthogonal matrices and thus linear transformations, which are \( C^{\infty} \). 
\end{proof}

