\subsection{Proof of Theorem \ref{thm:rate}}



We will use Theorem 3.4.1 of \citet{van2023weak} to show that the neural network $\hat f$ converges at the rate stated in the theorem. For ease of reference, we restate a slightly simplified version of the theorem adapted to the notation used in our paper. Here and in the following, we write $a \lesssim b$ to indicate $a \le Cb$ for a constant $C \in (0, \infty)$ not depending on $n$.


\begin{proposition} \label{thm:rate-cond}
	Let $\Fcal_n$ be a sequence of function classes, $\ell$ be some loss function, $f_0$ the estimation target, and
	\begin{align*}
		\hat f = \argmin_{f \in \Fcal_n} \frac 1 n \sum_{i = 1}^n \ell(f(Z_i), Y_i).
	\end{align*}
	Define $\Fcal_{n, \delta} = \{f \in \Fcal_n \colon \|f - f_0\|_{L_2(P_Z)} \le \delta\}$ and suppose that for every $\delta > 0$, it holds
	\begin{align} \label{eq:rate-cond-hess} \tag{\ref*{thm:rate-cond}.1}
		\inf_{f \in \Fcal_{n, \delta} \setminus \Fcal_{n, \delta/2}} \E[\ell(f(Z), Y)] - \E[\ell(f_0(Z), Y)] \gtrsim \delta^2,
	\end{align}
	and, writing $\bar \ell_f(z, y) = \ell(f(z), y) - \ell(f_0(z), y)$, that
	\begin{align} \label{eq:rate-cond-ep} \tag{\ref*{thm:rate-cond}.2}
		\E\left[\sup_{f \in \Fcal_{n, \delta}}\left| \frac{1}{n} \sum_{i = 1}^n \bar \ell_f(Z_i, Y_i) - \E[\bar \ell_f(Z, Y)] \right| \right] \lesssim \frac{\phi_n(\delta)}{\sqrt{n}},
	\end{align}
	for functions $\phi_n(\delta)$ such that $\delta \mapsto \phi_n(\delta)/\delta^{2 - \eps}$ is decreasing for some $\eps > 0$. If there are $\widetilde f_0 \in \Fcal_{n}$ and $\eps_n \ge 0$ such that
	\begin{align}
		\label{eq:rate-cond-bias} \eps_n^2        & \gtrsim  \E[\ell(\tilde f_0(Z), Y)] - \E[\ell(f_0(Z), Y)], \tag{\ref*{thm:rate-cond}.3} \\
		\label{eq:rate-cond-rate}  \phi_n(\eps_n) & \lesssim \sqrt{n} \eps_n^2, \tag{\ref*{thm:rate-cond}.4} 
	\end{align}
	it holds $\| \hat f - f_0 \|_{L_2(P_Z)} = O_p(\eps_n).$
\end{proposition}

\begin{proof}[Proof of Theorem \ref{thm:rate}]
	Define  $(s^*, d^*) = \argmin_{(s, p) \in \Pcal \cup (s_\psi, d_{\Mcal})} s / p$ and denote the targeted rate of convergence by
\begin{align*}
	\eps_n = \max_{(s, p) \in \Pcal \cup (s_\psi, d_{\Mcal})} n^{-\frac{s}{2s + p}}  (\log n)^4 = n^{-\frac{s^*}{2s^* + d^*}} (\log n)^4.
\end{align*}
We now check the conditions of \cref{thm:rate-cond}. 

\paragraph{Condition \eqref{eq:rate-cond-hess}:}

Follows from \cref{ass:A2}, since
\begin{align*}
	\inf_{f \in \Fcal_{n, \delta} \setminus \Fcal_{n, \delta/2}} \E[\ell(f(Z), Y)] - \E[\ell(f_0(Z), Y)] \ge 	\inf_{f \in \Fcal_{n, \delta} \setminus \Fcal_{n, \delta/2}} a \|f - f_0\|^2_{L_2(P_Z)} \ge \frac{a}{4} \delta^2.
\end{align*}

\paragraph{Condition \eqref{eq:rate-cond-ep}:}

Let $N(\eps, \Fcal, L_2(Q))$ be the minimal number of $\eps$-balls required to cover $\Fcal$ in the $L_2(Q)$-norm. Theorem 2.14.2 of \citet{van2023weak} states that eq.~\eqref{eq:rate-cond-ep} holds with
\begin{align*}
	\phi_n(\delta) = J_n(\delta)\left(1 + \frac{J_n(\delta)}{\delta^2 \sqrt{n}}\right),
\end{align*}
where
\begin{align*}
	J_n(\delta) = \sup_Q \int_0^{\delta} \sqrt{1 + \log N(\epsilon, \Fcal(L, \nu), L_2(Q))} d\epsilon,
\end{align*}
with the supremum taken over all probability measures $Q$.
\cref{lem:covering} in \cref{sec:auxialiary} gives
\begin{align*}
	J_n(\delta) \lesssim  \delta \sqrt{\log(1/\delta)} L \nu \sqrt{\log (L \nu)},
\end{align*}
which implies that $\delta \mapsto \phi_n(\delta) / \delta^{2 - 1/2}$ is decreasing, so the condition is satisfied.

\paragraph{Condition \eqref{eq:rate-cond-bias}:}

According to \cref{lem:approx} in \cref{sec:auxialiary} there are sequences $L_n = O(\log \eps_n^{-1})$, $\nu_n = O(\eps_n^{-d^*/2s^*})$ such that there is a neural network $\widetilde f_0 \in \Fcal(L_n, \nu_n)$ with
\begin{align*}
	\sup_{z \in \Mcal}| \widetilde f_0(z) - f_0(z) |  = O(\eps_n).
\end{align*}
Together with \cref{ass:A2}, this implies
\begin{align*}
	\E[\ell(\tilde f_0(Z), Y)] - \E[\ell(f_0(Z), Y)] \le b \| \tilde f_0-  f_0 \|_{L_2(P_Z)}^2 \le b 	\sup_{z \in \Mcal}| \widetilde f_0(z) - f_0(z) |^2 \lesssim \eps_n^2,
\end{align*}
as required.


\paragraph{Condition \eqref{eq:rate-cond-rate}:}


Using $L_n = O(\log \eps_n^{-1})$, $\nu_n = O(\eps_n^{-d^*/2s^*})$ and our bound on $J_n(\delta)$ from \cref{lem:covering}, we get
\begin{align*}
	J_n(\delta) \lesssim \delta \log^{1/2}(\delta^{-1})  \eps_n^{-\frac{d^*}{2s^*} }  \log^{3/2} (\eps_n^{-1}).
\end{align*}
Now observe that
\begin{align*}
	\frac{\phi_n(\eps_n) }{\eps_n^2} & \lesssim \eps_n^{-\frac{d^*}{s^*} - 1}  \log^2(\eps_n^{-1})  + \frac{\eps_n^{-\frac{d^*}{s^*} - 2} \log^4(\eps_n^{-1})}{\sqrt{n}} \\
	                                   & =  \eps_n^{-\frac{2s^* + d^*}{2s^*}}  \log^2(\eps_n^{-1})  + \eps_n^{-\frac{2s^* + d^*}{s^*}} \log^4(\eps_n^{-1}) n^{-1/2}        \\
	                                   & \lesssim n^{1/2} (\log n)^{-2} + n^{1/2},
\end{align*}
where the last step follows from our definition of $\eps_n$ and the fact that $\log (\eps_n^{-1}) \lesssim \log n$.
In particular, $\eps_n$ satisfies $\phi_n(\eps_n) \lesssim \sqrt{n}\eps_n^2$, which concludes the proof of the theorem.
\end{proof}


\subsection{Auxiliary results} \label{sec:auxialiary}

\begin{lemma} \label{lem:covering}
	Let $\Fcal(L, \nu)$ be a set of neural networks with $\sup_{f \in \mathcal{\Fcal(L, \nu)}} \|f\|_\infty < \infty$. For all $\delta > 0$ sufficiently small, it holds
	\begin{align*}
		\sup_Q \int_0^{\delta} \sqrt{1 + \log N(\epsilon, \Fcal(L, \nu), L_2(Q))} d\epsilon \lesssim  \delta \sqrt{\log(1/\delta)} L \nu \sqrt{\log (L \nu)}.
	\end{align*}
\end{lemma}
\begin{proof}
	Denote by  $\mathrm{VC}(\Fcal)$ the Vapnik-Chervonenkis dimension of the set $\Fcal$.
	By Theorem 2.6.7 in \citet{van2023weak}, it holds
	\begin{align*}
		\sup_Q \log N(\eps, \Fcal, L_2(Q)) \lesssim \log(1 / \eps) \mathrm{VC}(\Fcal),
	\end{align*}
	for $\eps > 0$ sufficiently small.
	By Theorem 7 of \citet{bartlett2019nearly}, we have
	\begin{align*}
		\mathrm{VC}(\mathcal{F}(L, \nu))\lesssim L^2 \nu^2 \log (L\nu).
	\end{align*}
	For small $\eps$, this gives
	\begin{align*}
		\sup_Q \sqrt{1 + \log N(\eps, \Fcal(L, \nu), L_2(Q))} \lesssim\sqrt{\log(1 / \eps)} L \nu \sqrt{\log (L\nu)},
	\end{align*}
	Integrating the right-hand side gives the desired result.
\end{proof}


\begin{lemma} \label{lem:approx}
	Suppose $f_0$ satisfies \cref{ass:A1} for a given constraint set $\Pcal$ and $(s_\psi, d_{\Mcal})$. Define  $(s^*, d^*) = \argmin_{(s, p) \in \Pcal \cup (s_\psi, d_{\Mcal})} s / p.$
	Then for any $\eps > 0$ sufficiently small, there is a neural network architecture $\Fcal(L, \nu)$ with $L = O(\log \eps^{-1})$, $\nu = O(\eps^{-d^*/2s^*})$ such that there is $\widetilde f_0 \in \Fcal(L, \nu)$ with
	\begin{align*}
		\sup_{z \in \Mcal}| \widetilde f_0(z) - f_0(z) |  = O(\eps).
	\end{align*}
\end{lemma}
\begin{proof}


	The proof proceeds in three steps. We first approximate the embedding component $\psi$ by a neural network $\widetilde \psi$, then the HCM component $f$ by a neural network $\widetilde f$. Finally, we concatenate the networks to approximate the composition $f_0 = f \circ \psi$ by $\widetilde f_0 = \widetilde f \circ \widetilde \psi$.

	\paragraph{Approximation of the embedding component.}

	Recall that $\psi \colon \Mcal \to \R^d$ is a $s_\psi$-smooth mapping.
	Write $\psi(z) = (\psi_1(z), \ldots, \psi_d(z))$ and note that each $\psi_j \colon \Mcal \to \R$ is also $s_\psi$-smooth.
	Since $\Mcal$ is a smooth $d_{\Mcal}$-dimensional manifold, it has Minkowski dimension $d_{\Mcal}$. Then Theorem 2 of \citet{KOHLER2023160} (setting $M = \eps^{-1/2s_\psi}$ in their notation) implies that there is a neural network $\widetilde \psi_j \in \Fcal(L_{\psi}, \nu_{\psi})$ with $
		L_{\psi} = O(\log \eps^{-1})$ and $\nu_{\psi} = O(\eps^{-d_{\Mcal}/2s_\psi})$ such that
	\begin{align*}
		\sup_{z \in \Mcal}| \widetilde \psi_j(z) - \psi_j(z) |  = O(\eps).
	\end{align*}
	Parallelize the networks $\widetilde \psi_j$ into a single network $\widetilde \psi := (\widetilde \psi_1, \ldots, \widetilde \psi_d) \colon \Mcal \to \R^d$. By construction, the parallelized network $\widetilde \psi$ has $L_{\psi}$ layers, width $d\times \nu_{\psi} = O( \nu_{\psi})$, and satisfies
	\begin{align*}
		\sup_{z \in \Mcal}\| \widetilde \psi(z) - \psi(z) \|  = O(\eps).
	\end{align*}

	\paragraph{Approximation of the HCM component.}

	Let $a \in (0, \infty)$ be arbitrary.
	By Theorem 3(a) of \citet{kohler2021rate} (setting $M_{i, j} = \eps^{-1/2p_{j}^{(i)}}$ in their notation), there is a neural network $\widetilde f \in \Fcal(L_{f}, \nu_{f})$ with $L_{f} = O(\log \eps^{-1})$ and $\nu_{f} = O(\eps^{-d^*/2s^*})$ such that
	\begin{align*}
		\sup_{x \in [-a, a]^d}| \widetilde f(x) -f(x) |  = O(\eps),
	\end{align*}

	\paragraph{Combined approximation.} Now concatenate the networks $\widetilde \psi$ and $\widetilde f$ to obtain the network $\widetilde f_0 = \widetilde f \circ \widetilde \psi \in \Fcal(L_\psi + L_f, \max\{\nu_\psi, \nu_f\})$. Observe that $L_\psi + L_f = O(\log \eps^{-1})$ and $\nu_\psi + \nu_f = O(\eps^{-d^*/2s^*})$, so the network has the right size. It remains to show that its approximation error is sufficiently small.
	Define
	\begin{align*}
		\gamma := \sup_{z \in \Mcal}\| \widetilde \psi(z) - \psi(z) \|,
	\end{align*}
	which is $O(\eps)$ by the construction of $\widetilde \psi$,
	\begin{align*}
		a := \sup_{z \in \Mcal}\|\psi(z)\| + \gamma,
	\end{align*}
	which is $O(1)$ by assumption,
	and
	\begin{align*}
		K := \sup_{x, x'} \frac{| f(x) - f(x') |}{\|x - x'\|},
	\end{align*}
	which is finite since $f$ is Lipschitz due to $\min_{(s, d) \in \Pcal} s \ge 1$ and the fact that finite compositions of Lipschitz functions are Lipschitz.
	By the triangle inequality, we have
	\begin{align*}
		\sup_{z \in \Mcal}| \widetilde f_0(z) - f_0(z) |
		 & \le \sup_{z \in \Mcal}| \widetilde f(\widetilde \psi(z)) - f(\widetilde \psi(z)) | + \sup_{z \in \Mcal}\| f(\widetilde \psi(z)) - f(\psi(z)) \| \\
		 & \le \sup_{x \in [-a, a]^d} | \widetilde f(x) - f(x) | + K    \\
		 & = O(\eps),
	\end{align*}
	as claimed.
\end{proof}

\subsection{Proof of Theorem \ref{thm:dml}}

\begin{proof}
    We validate the conditions of Theorem II.1 of \citet{chernozhukov2017double}. Our \cref{ass:A3} covers all their moment and boundedness conditions on $g$ and $m$. By \cref{thm:rate}, we further know that
    \begin{align*}
        \| \hat m^{(k)} - m \|_{L_2(P_Z)} + \| \hat g^{(k)} - g \|_{L_2(P_Z)} = o_p(1).
    \end{align*}
    Further, \cref{thm:rate} yields 
    \begin{align*}
         \| \hat m^{(k)} - m \|_{L_2(P_Z)} \times \| \hat g^{(k)} - g \|_{L_2(P_Z)} 
         &= O_p\left( \max_{(s, p) \in \Pcal_g \cup (s_\psi, d_{\Mcal})} n^{-\frac{s}{2s + p}} \times  \max_{(s', p') \in \Pcal_m \cup (s_\psi', d_{\Mcal})} n^{-\frac{s'}{2s' + p'}}\right) \\
         &= O_p\left( \max_{(s, p) \in \Pcal_g \cup (s_\psi, d_{\Mcal})}  \max_{(s', p') \in \Pcal_m \cup (s_\psi', d_{\Mcal})} n^{- \left(\frac{s}{2s + p} + \frac{s'}{2s' + p'} \right)} \right).
    \end{align*}
    We have to show that the term on the right is of order $o_p(n^{-1/2})$.
    Observe that
    \begin{align*}
         \frac{s}{2s + p} + \frac{s'}{2s' + p'} > \frac{1}{2} \quad  
            & \Leftrightarrow \quad  \frac{1}{2 + p/s} + \frac{1}{2 + p'/s'} >  \frac{1}{2} \\
            & \Leftrightarrow \quad  \frac{4 + p/s + p'/s'}{(2 + p/s)(2 + p'/s')} >   \frac{1}{2} \\
            & \Leftrightarrow \quad 4 + p/s + p'/s'> 2 + p/s + p'/s' + \frac
            {pp'}{2ss'} \\
            & \Leftrightarrow \quad 4 > \frac
            {pp'}{ss'}.
  \end{align*}
  Thus, our condition
   \begin{align*}
        \min_{(s, p) \in \Pcal_g \cup (s_\psi, d_{\Mcal})} \frac{s}{p} \times \min_{(s', p') \in \Pcal_m \cup (s_\psi', d_{\Mcal})} \frac{s'}{p'} > \frac 1 4,
    \end{align*}
    implies
  \begin{align*}
      \| \hat m^{(k)} - m \|_{L_2(P_Z)} \times \| \hat g^{(k)} - g \|_{L_2(P_Z)}  = o_p(n^{-1/2}),
  \end{align*}
  as required.
\end{proof}



\section{Additional Related Literature \& Visualizations} \label{app:furtherlit}

\subsection{Empirical Evidence of Low Intrinsic Dimensions} \label{app:empevidID}

Using different intrinsic dimension (ID) estimators such as the maximum likelihood estimator \citep[MLE;][]{levina2004maximum} on popular image datasets such as ImageNet \cite{deng2009imagenet}, several works find clear empirical evidence for low ID of both the image data and related latent features obtained from pre-trained NNs \citep{gong2019intrinsic, ansuini2019intrinsic, pope2021intrinsic}. The existence of the phenomenon of low intrinsic dimensions was also verified in the medical imaging \cite{konz2024intrinsic} and text-domain \cite{aghajanyan2020intrinsic}. All of the mentioned research finds a striking inverse relation between intrinsic dimensions and (state-of-the-art) model performance, which nicely matches the previously introduced theory about ID-related convergence rates.

\vspace{-1mm}
\subsection{Hierarchical Composition Model (HCM) Visualization} \label{app:hcm_vis}

\vspace{-1mm}
This section provides an illustration of the Hierarchical Composition Model (HCM) that was formally introduced in \cref{def:hcm}. As the name suggests, every HCM is a composition of HCMs of lower level. In \cref{fig:hcm_vis} we give an illustration of a particular HCM of level 2 and constraint set $\mathcal{P}_{21}$, which we abbreviated by $HCM(2,\mathcal{P}_{21})$. Following the notation of \cref{def:hcm}, the $HCM(2,\mathcal{P}_{21})$ corresponds to the function $f: \mathbb{R}^{d}\to \mathbb{R}$ defined by $f(x)=h^{[2]}_1 (h^{[1]}_1(x), \ldots,h^{[1]}_p(x))$. Each $h^{[1]}_j(x)$ for $j \in \{1, \ldots,p\}$ corresponds to a HCM of level 1, which itself are compositions of HCMs of level 0. Each of the latter corresponds to a feature in the data. The constraint set of each HCM corresponds to the collection of pairs of the degree of smoothness and number of inputs of each HCM it is composed of. For example, assuming that $h^{[2]}_1$ is a $s$-smooth function, then the constraint set of the $HCM(2, \mathcal{P}_{21})$ function $f$ is $\mathcal{P}_{21} = \bigcup_{j=1}^p\mathcal{P}_{1j} \cup (s,p)$. 
The HCM framework fits both regression and classification. In the latter, the conditional probability would need to satisfy the HCM condition, and any non-linear link function for classification would just correspond to a simple function in the final layer of the HCM.
