\subsection{The adiabatic-entropic decomposition} 
















It is convenient to introduce a more natural basis to parametrize the multi-field background trajectories. The idea is to define, at each point in field space, the tangential (\textit{adiabatic}) and orthogonal (\textit{entropic}) direction with respect to the trajectory, defining the so-called adiabatic-entropic decomposition \cite{Wands:2007bd}.
















In general, the Lagrangian for a multi-field model of inflation is given by 
\begin{equation}\label{MultifieldAction}
    \frac{{\cal L}(\phi^I)}{\sqrt{-g}}=\frac{1}{2}R-\frac{1}{2}g^{\mu\nu}G_{IJ}(\phi)\partial_{\mu}\phi^{I}\partial_{\nu}\phi^{J}-V(\phi)\,, 
\end{equation}
with $G_{IJ}(\phi)$ the (internal) field-space metric of the set of $n$ scalar fields $\phi^{I}$.
The equations of motion, in a flat FLRW background, derived from this Lagrangian, read 
\begin{equation}
    3H^{2}=\frac{1}{2}\dot{\sigma}^{2}+V(\phi)\,, \quad D_{t}\dot{\phi^{I}}+3H\dot{\phi^{I}}+G^{IJ}\frac{\partial V}{\partial\phi^{J}}=0\,,
\end{equation}
where dots represent derivatives with respect to the cosmic time $t$, and we introduced the generalized kinetic energy and covariant time derivative as
\begin{equation}
    \dot{\sigma}^2\equiv G_{IJ}\dot{\phi}^I\dot{\phi}^J\,, \qquad
    D_{t}\dot{\phi^{I}}\equiv\ddot{\phi^{I}}+\Gamma^{I}_{\ JK}\dot{\phi^{J}}\dot{\phi^{K}}\,.
\end{equation}
The slow-roll parameters in multi-field inflation are then computed as
\begin{equation}
    \epsilon_{H}\equiv -\frac{\dot{H}}{H^{2}}=\frac{\dot{\sigma^{2}}}{2H^{2}}\,,\quad \eta_{H}\equiv\frac{\dot{\epsilon}}{H\epsilon}\,.
\end{equation}
Within this multi-field formalism, the adiabatic-entropic decomposition is introduced as the basis for the tangent field space, in which the metric is locally flat at any point along the background trajectory. This is achieved by introducing the adiabatic unit vector in the tangential direction
\begin{equation}
    e_\sigma^I\equiv\frac{\dot{\phi}^I}{\dot{\sigma}}\,,
\end{equation}
which, together with the entropic unit vector(s), form a complete set of $n$-\textit{beins} of the field space, such that
\begin{equation}
    G_{IJ}e_i^Ie_j^J=\delta_{ij}\,.
\end{equation}
Notice that we adopt uppercase Latin letters $I,J,\ldots$ for curved indices, related to the original field metric in terms of $\varphi$ and $\theta$, and lowercase Latin letters $i,j,\ldots$ for flat indices, related to the flat metric defined by the $n$-beins. 
















In the two-field case under scrutiny, we have a set of \textit{zweibeins} with a single orthogonal direction, which we identify with the $s$ index. In particular, the orthogonal unit vector can be computed as
\begin{equation}
   e_s^I=-G^{-1/2}\epsilon^{IJ}G_{JK}e^K_\sigma\,,
\end{equation}
where $G$ is the field-metric determinant and $\epsilon^{IJ}$ the totally antisymmetric Levi-Civita symbol. Moreover, the tangential and orthogonal directions are dynamical and subject to change if the background trajectory experiences a turning in field space, as described by the following system of equations
\begin{equation}
    D_te_\sigma^I=H\eta_\perp e_s^I\,, \quad  D_te_s^I=-H\eta_\perp e_\sigma^I\,,
\end{equation}
where we introduced the \textit{turning rate} $\eta_\perp$, which quantifies the amount of bending the field-space trajectory is subject to. Once the zweibeins are known, the turning rate is obtained by inverting the previous relation
 \begin{equation}\label{DefTurnRate}
    \eta_{\perp}=\frac{1}{H}e_{Is}D_{t}e^{I}_{\sigma}=-\frac{1}{H}e_{I\sigma}D_{t}e^{I}_{s}\,.
\end{equation}
For the hyperbolic geometry in Eq.~\eqref{ModularKineticterm}, we have the following explicit zweinbeins components
\begin{equation}
    e^I_\sigma=\frac{1}{\dot{\sigma}}\begin{pmatrix}
        \dot{\varphi} \\
        \dot{\theta}
    \end{pmatrix}\,, \quad e^I_s=\frac{1}{\dot{\sigma}}\begin{pmatrix}
        \sqrt{\frac{3\alpha}{2}}e^{-\sqrt{\frac{2}{3\alpha}}\varphi}\dot{\theta} \\
        \sqrt{\frac{2}{3\alpha}}e^{\sqrt{\frac{2}{3\alpha}}\varphi}\dot{\varphi}
    \end{pmatrix}\,,
\end{equation}
so that the turning rate is given by 
\begin{equation}\label{exactturn}
    \eta_\perp=\sqrt{\frac{2}{3 \alpha }}  \frac{e^{\sqrt{\frac{2}{3\alpha}} \varphi}}{\dot{\sigma}^2 H}\left(V_\theta\dot{\varphi}-\frac{3}{2}\alpha e^{-2\sqrt{\frac{2}{3 \alpha }}\varphi}V_\varphi \dot{\theta}\right)\,.
\end{equation}
We will explicitly evaluate this quantity after solving the background dynamics for both models.
%where the generalized kinetic term is given by
%\begin{equation}
    %\dot{\sigma}^{2}=\dot{\varphi}^{2}+\frac{3}{2}\alpha \ e^{-2\sqrt{\frac{2}{3\alpha}}\varphi}\dot{\theta}^{2}\,.
%\end{equation} 
















\subsection{Background evolution}
















The general background equations of motion derived from the hyperbolic geometry Eq.~\eqref{ModularKineticterm} read
\begin{equation}\label{Friedmanlike}
    3H^2=V(\varphi,\theta )+\frac{3}{4}\alpha \ e^{-2 \sqrt{\frac{2}{3\alpha} } \varphi} \dot{\theta}^2+\frac{1}{2} \dot{\varphi}^2\,,
\end{equation}
\begin{equation}\label{phiEOM}
    \ddot{\varphi}+3H\dot{\varphi}+\frac{\partial V(\varphi,\theta)}{\partial \varphi}+\sqrt{\frac{3\alpha}{2}}e^{-2 \sqrt{\frac{2}{3\alpha}}\varphi} \dot{\theta }^2=0\,,
\end{equation}
\begin{equation}\label{ThetaEOM}
    \ddot{\theta}+3H\dot{\theta}-\sqrt{\frac{2}{3\alpha}}\dot{\theta}\dot{\varphi}+\frac{2e^{2 \sqrt{\frac{2}{3\alpha}} \varphi}} {{3 \alpha }} \frac{\partial V(\varphi,\theta)}{\partial \theta}=0\,.
\end{equation}
This system of equations has been analytically studied in Ref.~\cite{Kallosh:2024whb} for the generic type of potentials we are considering in this work (\textit{i.e.} for potentials exhibiting a strong suppression on the $\theta$ direction). In this paper instead we numerically study the dynamics not only in the $SL(2,{\mathbb Z})$ class of models but also in the toy model with the hyperbolic potential, extending the treatment beyond the end of inflation in order to fully capture the turning in field space and estimate its effect on the inflationary predictions.
















